        new Def { Id = "PringlzCheese", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzCheese", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "сыр", EnF = "cheese", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Усатый дядька с тубы обещал: начнёшь и не остановишься. Чипсы сложены ровнее, чем моя жизнь. Кто-то открыл, передумал и умер. Не связано. Торговец дал бы за это тряпку. Вы дадите больше.", EnJ = "The moustached man on the tube swore you can't stop once you pop. The crisps are stacked neater than my life. Someone opened it, changed their mind and died. Unrelated. The trader would give a rag for it. You would give more.", Rare = false },
        new Def { Id = "PringlzBBQ", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzBBQ", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "барбекю", EnF = "barbecue", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Усатый дядька с тубы обещал: начнёшь и не остановишься. Чипсы сложены ровнее, чем моя жизнь. Такое вечно каталось под сиденьем пикапа. Пока жуёте, метель кажется короче.", EnJ = "The moustached man on the tube swore you can't stop once you pop. The crisps are stacked neater than my life. One of these was always rolling under a pickup seat. While you chew, the blizzard seems shorter.", Rare = false },
        new Def { Id = "PringlzVinegar", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzVinegar", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Усатый дядька с тубы обещал: начнёшь и не остановишься. Чипсы сложены ровнее, чем моя жизнь. Привезено паромом, которого больше нет. Организм скажет спасибо. Или не скажет.", EnJ = "The moustached man on the tube swore you can't stop once you pop. The crisps are stacked neater than my life. Brought over by a ferry that no longer exists. Your body will thank you. Or not.", Rare = false },
        new Def { Id = "PringlzHot", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzHot", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "острые", EnF = "hot & spicy", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Усатый дядька с тубы обещал: начнёшь и не остановишься. Чипсы сложены ровнее, чем моя жизнь. Раньше это ели под телевизор. Телевизор молчит. На третьей горсти забываешь, что вокруг конец света.", EnJ = "The moustached man on the tube swore you can't stop once you pop. The crisps are stacked neater than my life. People ate this in front of the telly. The telly is silent. By the third handful you forget the world has ended.", Rare = false },
        new Def { Id = "PringlzPizza", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzPizza", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "пицца", EnF = "pizza", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Усатый дядька с тубы обещал: начнёшь и не остановишься. Чипсы сложены ровнее, чем моя жизнь. Забыто туристами, которым повезло уехать. Рыба подо льдом завидует.", EnJ = "The moustached man on the tube swore you can't stop once you pop. The crisps are stacked neater than my life. Left behind by tourists who were lucky enough to leave. The fish under the ice are jealous.", Rare = false },
        new Def { Id = "PringlzPigs", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzPigs", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "колбаски в беконе", EnF = "pigs in blankets", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Механики заедали этим обед, не вытирая рук. Олень от такого отказался бы. Олень не голодал.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. Mechanics ate these for lunch without wiping their hands. A deer would turn it down. A deer has never starved.", Rare = true },
        new Def { Id = "PringlzMint", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzMint", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "мятный шоколад", EnF = "mint chocolate", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SugarDry" }, RuJ = "Зимняя серия: выпускали на один сезон, а зима тут навсегда. Последнее на всю Одинокую топь. Скорее всего. Ешьте до темноты: в темноте крошки не найти.", EnJ = "A winter edition: made for one season, and here winter is forever. The last one in all of Forlorn Muskeg. Most likely. Eat before dark: you cannot find crumbs in the dark.", Rare = true },
        new Def { Id = "PringlzTurkey", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzTurkey", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "индейка с начинкой", EnF = "roast turkey & stuffing", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Смотритель маяка грыз такое, ожидая кораблей. Ешьте до темноты: в темноте крошки не найти.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. The lighthouse keeper munched these while waiting for ships. Eat before dark: you cannot find crumbs in the dark.", Rare = true },
        new Def { Id = "PringlzPumpkinPie", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzPumpkinPie", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "тыквенный пирог", EnF = "pumpkin pie spice", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Полки рушились, а это уцелело. Лучшее, что случится с вами сегодня.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. Shelves collapsed and this survived. The best thing that will happen to you today.", Rare = true },
        new Def { Id = "PringlzSugar", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzSugar", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "сахарное печенье", EnF = "sugar cookie", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SugarDry" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Смотритель заповедника называл это ужином. Для полного счастья не хватает только дивана.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. The park ranger called this dinner. All that is missing for perfect happiness is a sofa.", Rare = true },
        new Def { Id = "PringlzBurger", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzBurger", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "летний бургер", EnF = "summer cheeseburger", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Такое слали посылками с материка. Адресаты выбыли. Вкус детства, если детство было так себе.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. These came in parcels from the mainland. The addressees are gone. The taste of childhood, if childhood was so-so.", Rare = true },
        new Def { Id = "PringlzKetchup", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzKetchup", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "кетчуп", EnF = "ketchup", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Усатый дядька с тубы обещал: начнёшь и не остановишься. Чипсы сложены ровнее, чем моя жизнь. Иные держали это за лекарство. Тоже лечит. Шуршит как надежда.", EnJ = "The moustached man on the tube swore you can't stop once you pop. The crisps are stacked neater than my life. Some people counted this as medicine. Also a cure. It rustles like hope.", Rare = false },
        new Def { Id = "PringlzRanch", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzRanch", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "соус ранч", EnF = "ranch", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Усатый дядька с тубы обещал: начнёшь и не остановишься. Чипсы сложены ровнее, чем моя жизнь. В школьном рюкзаке такое не доживало до обеда. Голод отступит, жажда придёт. Честный обмен.", EnJ = "The moustached man on the tube swore you can't stop once you pop. The crisps are stacked neater than my life. In a school bag this never lasted till lunch. Hunger leaves, thirst arrives. A fair trade.", Rare = false },
        new Def { Id = "PringlzCheddar", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzCheddar", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "чеддер", EnF = "cheddar cheese", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Усатый дядька с тубы обещал: начнёшь и не остановишься. Чипсы сложены ровнее, чем моя жизнь. Его обменяли бы на патрон, будь тут с кем меняться. Не согреет, зато отвлечёт.", EnJ = "The moustached man on the tube swore you can't stop once you pop. The crisps are stacked neater than my life. You could trade it for a cartridge, if there were anyone to trade with. It will not warm you, but it will distract you.", Rare = false },
        new Def { Id = "PringlzDill", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzDill", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "маринованный огурец", EnF = "dill pickle", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Усатый дядька с тубы обещал: начнёшь и не остановишься. Чипсы сложены ровнее, чем моя жизнь. На вокзале это стоило втрое дороже. Теперь даром. Пума предпочитает мясо. Вам повезло.", EnJ = "The moustached man on the tube swore you can't stop once you pop. The crisps are stacked neater than my life. At the station it cost three times as much. Now it is free. The cougar prefers meat. Lucky you.", Rare = false },
        new Def { Id = "PringlzJalapeno", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzJalapeno", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "халапеньо", EnF = "jalapeno", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Усатый дядька с тубы обещал: начнёшь и не остановишься. Чипсы сложены ровнее, чем моя жизнь. Пережило толчок и даже не помялось. Сначала попробуйте одну штучку. Шутка: ешьте всё.", EnJ = "The moustached man on the tube swore you can't stop once you pop. The crisps are stacked neater than my life. It came through the quake without a dent. Try just one first. Joke: eat the lot.", Rare = false },
        new Def { Id = "PringlzHoney", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzHoney", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "мёд и горчица", EnF = "honey mustard", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Усатый дядька с тубы обещал: начнёшь и не остановишься. Чипсы сложены ровнее, чем моя жизнь. Китобои такого не ели, но оценили бы. Такой ужин не стыдно записать в дневник.", EnJ = "The moustached man on the tube swore you can't stop once you pop. The crisps are stacked neater than my life. The whalers never ate this, but they would have approved. A dinner worth writing in the journal.", Rare = false },
        new Def { Id = "PringlzBacon", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzBacon", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "бекон", EnF = "bacon", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Усатый дядька с тубы обещал: начнёшь и не остановишься. Чипсы сложены ровнее, чем моя жизнь. Осталось после чьего-то дня рождения. Гости не пришли. Силы прибавит на один сугроб.", EnJ = "The moustached man on the tube swore you can't stop once you pop. The crisps are stacked neater than my life. Left over from someone's birthday. The guests never came. It will carry you one snowdrift further.", Rare = false },
        new Def { Id = "PringlzPrawn", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzPrawn", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "креветочный коктейль", EnF = "prawn cocktail", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Усатый дядька с тубы обещал: начнёшь и не остановишься. Чипсы сложены ровнее, чем моя жизнь. Мерзлота хранит лучше любого холодильника. Идеально к закату, которого не видно за бураном.", EnJ = "The moustached man on the tube swore you can't stop once you pop. The crisps are stacked neater than my life. Permafrost keeps things better than any fridge. Perfect with a sunset you cannot see for the storm.", Rare = false },
        new Def { Id = "PringlzWasabi", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzWasabi", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "васаби", EnF = "wasabi", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Усатый дядька с тубы обещал: начнёшь и не остановишься. Чипсы сложены ровнее, чем моя жизнь. Такое добывали из автомата, который съедал последнюю монету. Пахнет магазином. Помните магазины?", EnJ = "The moustached man on the tube swore you can't stop once you pop. The crisps are stacked neater than my life. These came from the vending machine that ate your last coin. It smells of a shop. Remember shops?", Rare = false },
        new Def { Id = "PringlzButter", Kind = Kind.Snack, Shape = "tube", Mesh = "Pringlz", Texture = "PringlzButter", Kg = 0.165f, Kcal = 860f, Thirst = -8f, Eat = 5f, Ru = "Чипсы «Принглз»", En = "Pringlz crisps", RuF = "попкорн с маслом", EnF = "buttered popcorn", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Усатый дядька с тубы обещал: начнёшь и не остановишься. Чипсы сложены ровнее, чем моя жизнь. Такое брали в лодку под брезент, на весь день. Мороз не испортил, время не взяло.", EnJ = "The moustached man on the tube swore you can't stop once you pop. The crisps are stacked neater than my life. People took these out in the boat under the tarpaulin, for the whole day. Frost did not spoil it and time could not take it.", Rare = false },
        new Def { Id = "EstrelyaPaprika", Kind = Kind.Snack, Shape = "bag", Mesh = "Estrelya", Texture = "EstrelyaPaprika", Kg = 0.13f, Kcal = 690f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Эстрелья»", En = "Estrelya crisps", RuF = "паприка", EnF = "paprika", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведская звезда вечеринок: открывают под сериал, доедают под титры. С ним кто-то шёл к перевалу и не дошёл. В рюкзаке не мнётся. Почти.", EnJ = "The Swedish star of every party: opened for the show, finished by the credits. Someone carried it towards the pass and never arrived. It does not get crushed in a pack. Almost.", Rare = false },
        new Def { Id = "EstrelyaDill", Kind = Kind.Snack, Shape = "bag", Mesh = "Estrelya", Texture = "EstrelyaDill", Kg = 0.13f, Kcal = 690f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Эстрелья»", En = "Estrelya crisps", RuF = "укроп", EnF = "dill", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведская звезда вечеринок: открывают под сериал, доедают под титры. С таким сидели у окна с видом на метель. Съешьте сейчас: завтра может не быть аппетита.", EnJ = "The Swedish star of every party: opened for the show, finished by the credits. People sat with these at a window with a view of the blizzard. Eat it now: tomorrow you may have no appetite.", Rare = false },
        new Def { Id = "EstrelyaCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Estrelya", Texture = "EstrelyaCheese", Kg = 0.13f, Kcal = 690f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Эстрелья»", En = "Estrelya crisps", RuF = "сыр и лук", EnF = "cheese & onion", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведская звезда вечеринок: открывают под сериал, доедают под титры. Уцелело там, где сгорело всё остальное. Хватит дойти до следующей хижины и пожалеть, что кончилось.", EnJ = "The Swedish star of every party: opened for the show, finished by the credits. It survived where everything else burned. Enough to reach the next cabin and regret it is gone.", Rare = false },
        new Def { Id = "EstrelyaSourcream", Kind = Kind.Snack, Shape = "bag", Mesh = "Estrelya", Texture = "EstrelyaSourcream", Kg = 0.13f, Kcal = 690f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Эстрелья»", En = "Estrelya crisps", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведская звезда вечеринок: открывают под сериал, доедают под титры. Этим кормили сторожевого пса. Пёс ушёл в волки. От такого не толстеют те, кто ходит по двадцать километров.", EnJ = "The Swedish star of every party: opened for the show, finished by the credits. They fed the guard dog with this. The dog joined the wolves. Nobody who walks twenty kilometres a day gets fat on this.", Rare = false },
        new Def { Id = "EstrelyaGrill", Kind = Kind.Snack, Shape = "bag", Mesh = "Estrelya", Texture = "EstrelyaGrill", Kg = 0.13f, Kcal = 690f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Эстрелья»", En = "Estrelya crisps", RuF = "гриль", EnF = "grill", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведская звезда вечеринок: открывают под сериал, доедают под титры. Из запасов лесорубов: брали ящиками. Волчья стая не в курсе. Пусть так и будет.", EnJ = "The Swedish star of every party: opened for the show, finished by the credits. From the loggers' stores: they bought it by the crate. The wolf pack does not know. Keep it that way.", Rare = false },
        new Def { Id = "EstrelyaMidsommar", Kind = Kind.Snack, Shape = "bag", Mesh = "Estrelya", Texture = "EstrelyaMidsommar", Kg = 0.13f, Kcal = 690f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Эстрелья»", En = "Estrelya crisps", RuF = "укроп и лук к Мидсоммару", EnF = "midsummer dill & chives", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. В пост такое не ели. Пост кончился вместе с миром. Хрустеть в засаде не рекомендуется.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. Nobody ate these during a fast. The fast ended with the world. Crunching in an ambush is not recommended.", Rare = true },
        new Def { Id = "EstrelyaJulskinka", Kind = Kind.Snack, Shape = "bag", Mesh = "Estrelya", Texture = "EstrelyaJulskinka", Kg = 0.13f, Kcal = 690f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Эстрелья»", En = "Estrelya crisps", RuF = "рождественский окорок с горчицей", EnF = "christmas ham & mustard", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Теперь это ценнее денег. Деньги оставьте. Лекарство от тоски, отпускается без рецепта.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. It is worth more than money now. Leave the money. A cure for the blues, no prescription needed.", Rare = true },
        new Def { Id = "EstrelyaKraft", Kind = Kind.Snack, Shape = "bag", Mesh = "Estrelya", Texture = "EstrelyaKraft", Kg = 0.13f, Kcal = 690f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Эстрелья»", En = "Estrelya crisps", RuF = "раки с укропом", EnF = "crayfish & dill", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Его несли на пикник. Пикник отменили навсегда. Жуйте и думайте о хорошем. Например, о добавке.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. It was headed for a picnic. The picnic is cancelled forever. Chew and think of nice things. Seconds, for example.", Rare = true },
        new Def { Id = "EstrelyaPask", Kind = Kind.Snack, Shape = "bag", Mesh = "Estrelya", Texture = "EstrelyaPask", Kg = 0.13f, Kcal = 690f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Эстрелья»", En = "Estrelya crisps", RuF = "пасхальная сельдь", EnF = "easter herring", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Такое стояло у кассы на случай слабости. К утру от него останется только запах на варежках.", EnJ = "A spring edition: a rare pack from the days when spring still came. These stood by the till for moments of weakness. By morning only the smell on your mittens will be left.", Rare = true },
        new Def { Id = "EstrelyaSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "Estrelya", Texture = "EstrelyaSalt", Kg = 0.13f, Kcal = 690f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Эстрелья»", En = "Estrelya crisps", RuF = "морская соль", EnF = "sea salt", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведская звезда вечеринок: открывают под сериал, доедают под титры. Досталось вам, потому что вы дошли первым. Тишина вокруг такая, что слышно, как вы жуёте.", EnJ = "The Swedish star of every party: opened for the show, finished by the credits. It is yours because you got here first. It is so quiet you can hear yourself chew.", Rare = false },
        new Def { Id = "EstrelyaVinegar", Kind = Kind.Snack, Shape = "bag", Mesh = "Estrelya", Texture = "EstrelyaVinegar", Kg = 0.13f, Kcal = 690f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Эстрелья»", En = "Estrelya crisps", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведская звезда вечеринок: открывают под сериал, доедают под титры. Упаковка выцвела, внутри время остановилось. Не делите на завтра: завтра будет новый голод.", EnJ = "The Swedish star of every party: opened for the show, finished by the credits. The wrapper has faded; inside, time stood still. Do not save half for tomorrow: tomorrow brings its own hunger.", Rare = false },
        new Def { Id = "EstrelyaChili", Kind = Kind.Snack, Shape = "bag", Mesh = "Estrelya", Texture = "EstrelyaChili", Kg = 0.13f, Kcal = 690f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Эстрелья»", En = "Estrelya crisps", RuF = "острый чили", EnF = "hot chilli", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Шведская звезда вечеринок: открывают под сериал, доедают под титры. Из чемодана пассажира, который не долетел. Сосны вокруг делают вид, что не смотрят.", EnJ = "The Swedish star of every party: opened for the show, finished by the credits. From the suitcase of a passenger who never landed. The pines around pretend not to watch.", Rare = false },
        new Def { Id = "EstrelyaTruffle", Kind = Kind.Snack, Shape = "bag", Mesh = "Estrelya", Texture = "EstrelyaTruffle", Kg = 0.13f, Kcal = 690f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Эстрелья»", En = "Estrelya crisps", RuF = "трюфель", EnF = "truffle", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведская звезда вечеринок: открывают под сериал, доедают под титры. Перезимовало и ничуть не обиделось. Калории мелкие, зато свои.", EnJ = "The Swedish star of every party: opened for the show, finished by the credits. It made it through the winter and bears no grudge. Small calories, but your own.", Rare = false },
        new Def { Id = "EstrelyaRanch", Kind = Kind.Snack, Shape = "bag", Mesh = "Estrelya", Texture = "EstrelyaRanch", Kg = 0.13f, Kcal = 690f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Эстрелья»", En = "Estrelya crisps", RuF = "ранч", EnF = "ranch", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведская звезда вечеринок: открывают под сериал, доедают под титры. Запасливая хозяйка купила по акции шесть штук. После этого даже крапивный чай покажется десертом.", EnJ = "The Swedish star of every party: opened for the show, finished by the credits. A thrifty housewife bought six of these on offer. After this even nettle tea feels like dessert.", Rare = false },
        new Def { Id = "LeningradSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "Leningrad", Texture = "LeningradSalt", Kg = 0.1f, Kcal = 530f, Thirst = -9f, Eat = 4f, Ru = "Хрустящий картофель «Ленинградский»", En = "Leningrad potato crisps", RuF = "с солью", EnF = "salted", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold" }, RuJ = "Тот самый хрустящий картофель из детства: ломтики через один подгорели, и это было лучшее. Кто-то написал на упаковке «моё». Уже нет. Нашедшему полагается всё.", EnJ = "The crisps of a Soviet childhood: every other slice burnt, and those were the best. Someone wrote 'mine' on it. Not any more. Finders keepers, all of it.", Rare = false },
        new Def { Id = "LeningradDill", Kind = Kind.Snack, Shape = "bag", Mesh = "Leningrad", Texture = "LeningradDill", Kg = 0.1f, Kcal = 530f, Thirst = -9f, Eat = 4f, Ru = "Хрустящий картофель «Ленинградский»", En = "Leningrad potato crisps", RuF = "с укропом", EnF = "with dill", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold" }, RuJ = "Тот самый хрустящий картофель из детства: ломтики через один подгорели, и это было лучшее. В консервном цеху это ели тайком от мастера. Зубы целы? Тогда вперёд.", EnJ = "The crisps of a Soviet childhood: every other slice burnt, and those were the best. At the cannery they ate this behind the foreman's back. Teeth intact? Then go ahead.", Rare = false },
        new Def { Id = "LeningradOnion", Kind = Kind.Snack, Shape = "bag", Mesh = "Leningrad", Texture = "LeningradOnion", Kg = 0.1f, Kcal = 530f, Thirst = -9f, Eat = 4f, Ru = "Хрустящий картофель «Ленинградский»", En = "Leningrad potato crisps", RuF = "с луком", EnF = "with onion", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold" }, RuJ = "Тот самый хрустящий картофель из детства: ломтики через один подгорели, и это было лучшее. Его не взяли даже мародёры. Они спешили. Ночью приснится добавка.", EnJ = "The crisps of a Soviet childhood: every other slice burnt, and those were the best. Even the looters left it. They were in a hurry. Tonight you will dream of seconds.", Rare = false },
        new Def { Id = "LeningradBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Leningrad", Texture = "LeningradBacon", Kg = 0.1f, Kcal = 530f, Thirst = -9f, Eat = 4f, Ru = "Хрустящий картофель «Ленинградский»", En = "Leningrad potato crisps", RuF = "с беконом", EnF = "with bacon", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold" }, RuJ = "Тот самый хрустящий картофель из детства: ломтики через один подгорели, и это было лучшее. Провело зиму на острове, как и вы. С таким запасом можно пережить ещё один вечер.", EnJ = "The crisps of a Soviet childhood: every other slice burnt, and those were the best. It spent the winter on the island, same as you. With supplies like this you can survive one more evening.", Rare = false },
        new Def { Id = "LeningradMushroom", Kind = Kind.Snack, Shape = "bag", Mesh = "Leningrad", Texture = "LeningradMushroom", Kg = 0.1f, Kcal = 530f, Thirst = -9f, Eat = 4f, Ru = "Хрустящий картофель «Ленинградский»", En = "Leningrad potato crisps", RuF = "с грибами", EnF = "mushroom", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold" }, RuJ = "Тот самый хрустящий картофель из детства: ломтики через один подгорели, и это было лучшее. Дети прятали такое под кроватью, в тайнике. Пёс бы выпросил половину. Пса нет.", EnJ = "The crisps of a Soviet childhood: every other slice burnt, and those were the best. Children hid these under the bed, in a secret place. A dog would beg half of it. There is no dog.", Rare = false },
        new Def { Id = "LeningradCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Leningrad", Texture = "LeningradCheese", Kg = 0.1f, Kcal = 530f, Thirst = -9f, Eat = 4f, Ru = "Хрустящий картофель «Ленинградский»", En = "Leningrad potato crisps", RuF = "с сыром", EnF = "cheese", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold" }, RuJ = "Тот самый хрустящий картофель из детства: ломтики через один подгорели, и это было лучшее. Осталось от геологов вместе с картой и долгами. Съедено будет быстрее, чем найдено.", EnJ = "The crisps of a Soviet childhood: every other slice burnt, and those were the best. Left by the geologists along with a map and some debts. It will be eaten faster than it was found.", Rare = false },
        new Def { Id = "LeningradPaprika", Kind = Kind.Snack, Shape = "bag", Mesh = "Leningrad", Texture = "LeningradPaprika", Kg = 0.1f, Kcal = 530f, Thirst = -9f, Eat = 4f, Ru = "Хрустящий картофель «Ленинградский»", En = "Leningrad potato crisps", RuF = "с паприкой", EnF = "paprika", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold" }, RuJ = "Тот самый хрустящий картофель из детства: ломтики через один подгорели, и это было лучшее. На острове такое было праздником и до катастрофы. На вкус как выходной.", EnJ = "The crisps of a Soviet childhood: every other slice burnt, and those were the best. On the island this was a treat even before the disaster. It tastes like a day off.", Rare = false },
        new Def { Id = "LeningradGarlic", Kind = Kind.Snack, Shape = "bag", Mesh = "Leningrad", Texture = "LeningradGarlic", Kg = 0.1f, Kcal = 530f, Thirst = -9f, Eat = 4f, Ru = "Хрустящий картофель «Ленинградский»", En = "Leningrad potato crisps", RuF = "с чесноком", EnF = "garlic", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold" }, RuJ = "Тот самый хрустящий картофель из детства: ломтики через один подгорели, и это было лучшее. С таким слушали радио, которое теперь ловит только треск. Ветер унесёт запах прямо к берлоге. Ешьте быстрее.", EnJ = "The crisps of a Soviet childhood: every other slice burnt, and those were the best. People ate these by the radio, which picks up nothing but crackle now. The wind carries the smell straight to the den. Eat faster.", Rare = false },
        new Def { Id = "ChitozCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitoz", Texture = "ChitozCheese", Kg = 0.085f, Kcal = 470f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Читоз»", En = "Chitoz corn puffs", RuF = "сыр", EnF = "cheese", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Гепард в тёмных очках делает вид, что он крутой. Пальцы после него оранжевые до весны. Крысы прогрызли соседнюю, эту пощадили. Пополняет запас соли и веры в человечество.", EnJ = "A cheetah in shades pretends to be cool. Your fingers stay orange till spring. The rats gnawed through the one next to it and spared this. Restores your salt and your faith in mankind.", Rare = false },
        new Def { Id = "ChitozKetchup", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitoz", Texture = "ChitozKetchup", Kg = 0.085f, Kcal = 470f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Читоз»", En = "Chitoz corn puffs", RuF = "кетчуп", EnF = "ketchup", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Гепард в тёмных очках делает вид, что он крутой. Пальцы после него оранжевые до весны. Бывший хозяин клялся бросить. Не успел. Хорошо идёт под треск поленьев.", EnJ = "A cheetah in shades pretends to be cool. Your fingers stay orange till spring. The former owner swore to give these up. He ran out of time. Goes down well with crackling logs.", Rare = false },
        new Def { Id = "ChitozHot", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitoz", Texture = "ChitozHot", Kg = 0.085f, Kcal = 470f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Читоз»", En = "Chitoz corn puffs", RuF = "острые", EnF = "flamin hot", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Гепард в тёмных очках делает вид, что он крутой. Пальцы после него оранжевые до весны. Его катали в кабине трактора три сезона. Руки вытирать о штаны: салфеток не завезли.", EnJ = "A cheetah in shades pretends to be cool. Your fingers stay orange till spring. It rode around in a tractor cab for three seasons. Wipe your hands on your trousers: no napkins were delivered.", Rare = false },
        new Def { Id = "ChitozPizza", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitoz", Texture = "ChitozPizza", Kg = 0.085f, Kcal = 470f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Читоз»", En = "Chitoz corn puffs", RuF = "пицца", EnF = "pizza", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Гепард в тёмных очках делает вид, что он крутой. Пальцы после него оранжевые до весны. После бани такое шло лучше всего. Маленькая радость размером с ладонь.", EnJ = "A cheetah in shades pretends to be cool. Your fingers stay orange till spring. Nothing went down better after the sauna. A small joy the size of your palm.", Rare = false },
        new Def { Id = "ChitozCrab", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitoz", Texture = "ChitozCrab", Kg = 0.085f, Kcal = 470f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Читоз»", En = "Chitoz corn puffs", RuF = "краб", EnF = "crab", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Гепард в тёмных очках делает вид, что он крутой. Пальцы после него оранжевые до весны. В тюрьме на это выменивали что угодно. Совесть молчит, живот поёт.", EnJ = "A cheetah in shades pretends to be cool. Your fingers stay orange till spring. In the prison you could trade one of these for anything. Conscience is silent, the belly sings.", Rare = false },
        new Def { Id = "ChitozBones", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitoz", Texture = "ChitozBones", Kg = 0.085f, Kcal = 470f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Читоз»", En = "Chitoz corn puffs", RuF = "косточки, белый чеддер", EnF = "bag of bones white cheddar", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Серия к Хэллоуину: редкость. Пугать тут и без неё есть кому. Кто-то менял это на сигареты. Сделка сорвалась. Проверено поколениями и одной катастрофой.", EnJ = "A Halloween edition: a rarity. There is plenty to scare you here without it. Someone was trading this for cigarettes. The deal fell through. Tested by generations and one catastrophe.", Rare = true },
        new Def { Id = "ChitozSnowflake", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitoz", Texture = "ChitozSnowflake", Kg = 0.085f, Kcal = 470f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Читоз»", En = "Chitoz corn puffs", RuF = "снежинки белый чеддер", EnF = "white cheddar snowflakes", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Зимняя серия: выпускали на один сезон, а зима тут навсегда. С ним зимовали на метеостанции, пока было с кем. Оставьте пару штук на перевал. Не оставите.", EnJ = "A winter edition: made for one season, and here winter is forever. They wintered with it at the weather station, while there was a 'they'. Save a couple for the pass. You will not.", Rare = true },
        new Def { Id = "ChitozHearts", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitoz", Texture = "ChitozHearts", Kg = 0.085f, Kcal = 470f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Читоз»", En = "Chitoz corn puffs", RuF = "сердечки острые", EnF = "spicy hearts", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Серия для влюблённых: редкость. Делить не с кем, зато вся ваша. Такое терялось в кладовке среди крупы и надежд. Здесь это считается ужином при свечах.", EnJ = "A Valentine edition: a rarity. No one to share it with, so it is all yours. These got lost in the pantry among the grain and the hopes. Round here this counts as a candlelit dinner.", Rare = true },
        new Def { Id = "ChitozBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitoz", Texture = "ChitozBacon", Kg = 0.085f, Kcal = 470f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Читоз»", En = "Chitoz corn puffs", RuF = "бекон", EnF = "bacon", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Гепард в тёмных очках делает вид, что он крутой. Пальцы после него оранжевые до весны. Его берегли к приезду внуков. Луна светит, еда хрустит, жизнь налаживается.", EnJ = "A cheetah in shades pretends to be cool. Your fingers stay orange till spring. It was being saved for the grandchildren's visit. The moon shines, the food crunches, life is looking up.", Rare = false },
        new Def { Id = "ChitozSour", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitoz", Texture = "ChitozSour", Kg = 0.085f, Kcal = 470f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Читоз»", En = "Chitoz corn puffs", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Гепард в тёмных очках делает вид, что он крутой. Пальцы после него оранжевые до весны. В баре такое ставили на стойку, бесплатно к пиву. Пива нет. Снег вокруг не солёный. Это солёное.", EnJ = "A cheetah in shades pretends to be cool. Your fingers stay orange till spring. Bars put these out free with a beer. There is no beer. The snow around is not salty. This is.", Rare = false },
        new Def { Id = "ChitozJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitoz", Texture = "ChitozJalapeno", Kg = 0.085f, Kcal = 470f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Читоз»", En = "Chitoz corn puffs", RuF = "халапеньо и чеддер", EnF = "cheddar jalapeno", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Гепард в тёмных очках делает вид, что он крутой. Пальцы после него оранжевые до весны. Такое лежало в каждом доме, пока не погас свет. Больше таких не делают. Совсем.", EnJ = "A cheetah in shades pretends to be cool. Your fingers stay orange till spring. Every house had one of these until the lights went out. They do not make these any more. At all.", Rare = false },
        new Def { Id = "ChitozHoney", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitoz", Texture = "ChitozHoney", Kg = 0.085f, Kcal = 470f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Читоз»", En = "Chitoz corn puffs", RuF = "мёд и барбекю", EnF = "honey barbecue", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SugarDry" }, RuJ = "Гепард в тёмных очках делает вид, что он крутой. Пальцы после него оранжевые до весны. Кто-то берёг это на чёрный день. Он настал. Открывайте тихо: у волков отличный слух.", EnJ = "A cheetah in shades pretends to be cool. Your fingers stay orange till spring. Someone saved this for a rainy day. It came. Open it quietly: wolves have excellent hearing.", Rare = false },
        new Def { Id = "ChitozLimon", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitoz", Texture = "ChitozLimon", Kg = 0.085f, Kcal = 470f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Читоз»", En = "Chitoz corn puffs", RuF = "острые с лаймом", EnF = "hot lime", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Гепард в тёмных очках делает вид, что он крутой. Пальцы после него оранжевые до весны. Пережило хозяина, кота и две зимы. Одной не обойдётся, но вторая неизвестно где.", EnJ = "A cheetah in shades pretends to be cool. Your fingers stay orange till spring. It outlived its owner, the cat and two winters. One won't be enough, and nobody knows where the second is.", Rare = false },
        new Def { Id = "ChitozHotdog", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitoz", Texture = "ChitozHotdog", Kg = 0.085f, Kcal = 470f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Читоз»", En = "Chitoz corn puffs", RuF = "хот-дог", EnF = "hot dog", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Гепард в тёмных очках делает вид, что он крутой. Пальцы после него оранжевые до весны. Такое обычно находили за диваном, как всё лучшее в жизни. Крошки с пола тоже считаются.", EnJ = "A cheetah in shades pretends to be cool. Your fingers stay orange till spring. These were usually found behind the sofa, like all the best things in life. The crumbs on the floor count too.", Rare = false },
        new Def { Id = "KiryushkiBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Kiryushki", Texture = "KiryushkiBacon", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Кирюшки»", En = "Kiryushki croutons", RuF = "бекон", EnF = "bacon", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сухарики, которыми закусывали всё, что горит, и заедали всё, что болит. Последний завоз был до того, как упали самолёты. Запейте чаем из шиповника и считайте это обедом.", EnJ = "The croutons that went with everything that burns and everything that hurts. The last delivery came before the planes fell. Wash it down with rosehip tea and call it lunch.", Rare = false },
        new Def { Id = "KiryushkiCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Kiryushki", Texture = "KiryushkiCheese", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Кирюшки»", En = "Kiryushki croutons", RuF = "сыр", EnF = "cheese", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сухарики, которыми закусывали всё, что горит, и заедали всё, что болит. Ценник оторван: теперь это бесценно. Медведю не показывать: отнимет вместе с рукой.", EnJ = "The croutons that went with everything that burns and everything that hurts. The price tag is torn off: it is priceless now. Do not show the bear: he will take it, hand and all.", Rare = false },
        new Def { Id = "KiryushkiSalami", Kind = Kind.Snack, Shape = "bag", Mesh = "Kiryushki", Texture = "KiryushkiSalami", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Кирюшки»", En = "Kiryushki croutons", RuF = "салями", EnF = "salami", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сухарики, которыми закусывали всё, что горит, и заедали всё, что болит. Дата на шве стёрлась, и слава богу. Диетолог не одобрил бы. Диетолога тут нет.", EnJ = "The croutons that went with everything that burns and everything that hurts. The date on the seam has rubbed off, thank goodness. A dietitian would not approve. There is no dietitian here.", Rare = false },
        new Def { Id = "KiryushkiAspic", Kind = Kind.Snack, Shape = "bag", Mesh = "Kiryushki", Texture = "KiryushkiAspic", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Кирюшки»", En = "Kiryushki croutons", RuF = "холодец с хреном", EnF = "aspic with horseradish", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Сухарики, которыми закусывали всё, что горит, и заедали всё, что болит. Пахнет заправкой у Прибрежного шоссе. Лучше, чем кора. Проверено.", EnJ = "The croutons that went with everything that burns and everything that hurts. It smells of the petrol station on the Coastal Highway. Better than bark. Tested.", Rare = false },
        new Def { Id = "KiryushkiCaviar", Kind = Kind.Snack, Shape = "bag", Mesh = "Kiryushki", Texture = "KiryushkiCaviar", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Кирюшки»", En = "Kiryushki croutons", RuF = "красная икра", EnF = "red caviar", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сухарики, которыми закусывали всё, что горит, и заедали всё, что болит. Такое возили в бардачке на дальнюю дорогу. Дороги кончились. Хруст разносится до соседней долины.", EnJ = "The croutons that went with everything that burns and everything that hurts. People kept these in the glovebox for long drives. The drives are over. The crunch carries to the next valley.", Rare = false },
        new Def { Id = "KiryushkiOlivie", Kind = Kind.Snack, Shape = "bag", Mesh = "Kiryushki", Texture = "KiryushkiOlivie", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Кирюшки»", En = "Kiryushki croutons", RuF = "оливье", EnF = "olivier salad", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Новогодняя серия: куранты отбили, а пачка осталась. Редкость. Мыши не тронули. Думайте сами. Ешьте медленно: когда ещё такое найдёте.", EnJ = "A New Year edition: the clock has struck, the pack remains. A rarity. The mice left it alone. Draw your own conclusions. Eat slowly: who knows when you will find another.", Rare = true },
        new Def { Id = "KiryushkiShuba", Kind = Kind.Snack, Shape = "bag", Mesh = "Kiryushki", Texture = "KiryushkiShuba", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Кирюшки»", En = "Kiryushki croutons", RuF = "селёдка под шубой", EnF = "dressed herring", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Новогодняя серия: куранты отбили, а пачка осталась. Редкость. Рыбаки брали такое на лёд вместо обеда. К этому просится пиво, а есть только талый снег.", EnJ = "A New Year edition: the clock has struck, the pack remains. A rarity. Fishermen took this onto the ice instead of lunch. It begs for a beer, and there is only melted snow.", Rare = true },
        new Def { Id = "KiryushkiShashlik2", Kind = Kind.Snack, Shape = "bag", Mesh = "Kiryushki", Texture = "KiryushkiShashlik2", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Кирюшки»", En = "Kiryushki croutons", RuF = "майский шашлык", EnF = "may shashlik", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Смотритель плотины держал такое в заначке. Сияние на вкус не влияет. Наверное.", EnJ = "A spring edition: a rare pack from the days when spring still came. The dam keeper kept a stash of these. The aurora does not affect the taste. Probably.", Rare = true },
        new Def { Id = "KiryushkiSmetana", Kind = Kind.Snack, Shape = "bag", Mesh = "Kiryushki", Texture = "KiryushkiSmetana", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Кирюшки»", En = "Kiryushki croutons", RuF = "сметана и зелень", EnF = "sour cream & herbs", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сухарики, которыми закусывали всё, что горит, и заедали всё, что болит. Кто-то спрятал это от детей. Дети не нашли. После тушёнки из банки это почти ресторан.", EnJ = "The croutons that went with everything that burns and everything that hurts. Someone hid it from the kids. The kids never found it. After stew from a tin this is nearly a restaurant.", Rare = false },
        new Def { Id = "KiryushkiCrab", Kind = Kind.Snack, Shape = "bag", Mesh = "Kiryushki", Texture = "KiryushkiCrab", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Кирюшки»", En = "Kiryushki croutons", RuF = "краб", EnF = "crab", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сухарики, которыми закусывали всё, что горит, и заедали всё, что болит. В сельском магазине такое вечно заваливалось за прилавок. Делиться не с кем, и это впервые радует.", EnJ = "The croutons that went with everything that burns and everything that hurts. In the village shop these kept slipping behind the counter. Nobody to share with, and for once that is good news.", Rare = false },
        new Def { Id = "KiryushkiShashlik", Kind = Kind.Snack, Shape = "bag", Mesh = "Kiryushki", Texture = "KiryushkiShashlik", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Кирюшки»", En = "Kiryushki croutons", RuF = "шашлык", EnF = "shashlik", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сухарики, которыми закусывали всё, что горит, и заедали всё, что болит. Ждало покупателя дольше, чем тот прожил. Пальцы потом оближите: зимой калории не выбрасывают.", EnJ = "The croutons that went with everything that burns and everything that hurts. It waited for a buyer longer than the buyer lived. Lick your fingers after: in winter you do not waste calories.", Rare = false },
        new Def { Id = "KiryushkiGarlic", Kind = Kind.Snack, Shape = "bag", Mesh = "Kiryushki", Texture = "KiryushkiGarlic", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Кирюшки»", En = "Kiryushki croutons", RuF = "чеснок", EnF = "garlic", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сухарики, которыми закусывали всё, что горит, и заедали всё, что болит. С материка такое больше не привезут. Ворон на ветке уже ждёт свою долю.", EnJ = "The croutons that went with everything that burns and everything that hurts. Nobody will bring this from the mainland again. The crow on the branch is already waiting for its share.", Rare = false },
        new Def { Id = "KiryushkiPizza", Kind = Kind.Snack, Shape = "bag", Mesh = "Kiryushki", Texture = "KiryushkiPizza", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Кирюшки»", En = "Kiryushki croutons", RuF = "пицца", EnF = "pizza", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сухарики, которыми закусывали всё, что горит, и заедали всё, что болит. На упаковке иней, внутри всё по-прежнему. На морозе хрустит вдвое громче.", EnJ = "The croutons that went with everything that burns and everything that hurts. Frost on the wrapper, business as usual inside. In the frost it crunches twice as loud.", Rare = false },
        new Def { Id = "KiryushkiHuntsman", Kind = Kind.Snack, Shape = "bag", Mesh = "Kiryushki", Texture = "KiryushkiHuntsman", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Кирюшки»", En = "Kiryushki croutons", RuF = "охотничьи колбаски", EnF = "hunter's sausages", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сухарики, которыми закусывали всё, что горит, и заедали всё, что болит. Мороз ему нипочём: твёрже не стало, мягче тоже. Не еда, а настроение. Настроение тоже греет.", EnJ = "The croutons that went with everything that burns and everything that hurts. The frost did nothing to it: no harder, no softer. Not food but a mood. A mood warms you too.", Rare = false },
        new Def { Id = "KiryushkiMushroom", Kind = Kind.Snack, Shape = "bag", Mesh = "Kiryushki", Texture = "KiryushkiMushroom", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Кирюшки»", En = "Kiryushki croutons", RuF = "грибы со сметаной", EnF = "mushrooms in sour cream", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сухарики, которыми закусывали всё, что горит, и заедали всё, что болит. Из тех времён, когда еду выбирали по вкусу. Сытости на час, воспоминаний на неделю.", EnJ = "The croutons that went with everything that burns and everything that hurts. From the days when people picked food for its taste. An hour of fullness, a week of memories.", Rare = false },
        new Def { Id = "KorochkiAspic", Kind = Kind.Snack, Shape = "bag", Mesh = "Korochki", Texture = "KorochkiAspic", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «4 корочки»", En = "4 Korochki croutons", RuF = "холодец с хреном", EnF = "aspic with horseradish", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Четыре корочки: три съел сам, четвёртую честно отдал другу. Друга не было. Чей-то перекус на ночную смену, которая не кончилась. Кролик смотрит с осуждением.", EnJ = "Four crusts: I ate three and honestly gave the fourth to a friend. There was no friend. Someone's snack for a night shift that never ended. The rabbit looks on with disapproval.", Rare = false },
        new Def { Id = "KorochkiTomato", Kind = Kind.Snack, Shape = "bag", Mesh = "Korochki", Texture = "KorochkiTomato", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «4 корочки»", En = "4 Korochki croutons", RuF = "томат и зелень", EnF = "tomato & herbs", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Четыре корочки: три съел сам, четвёртую честно отдал другу. Друга не было. В охотничьей вышке таким встречали рассвет. У костра вкуснее. У костра всё вкуснее.", EnJ = "Four crusts: I ate three and honestly gave the fourth to a friend. There was no friend. In the hunting blind they met the dawn with this. It tastes better by the fire. Everything does.", Rare = false },
        new Def { Id = "KorochkiSalmon", Kind = Kind.Snack, Shape = "bag", Mesh = "Korochki", Texture = "KorochkiSalmon", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «4 корочки»", En = "4 Korochki croutons", RuF = "сёмга и сыр", EnF = "salmon & cheese", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Четыре корочки: три съел сам, четвёртую честно отдал другу. Друга не было. Такое носили в кармане куртки на всякий случай. Случай настал. Упаковку не выбрасывайте: ею можно разжечь печь.", EnJ = "Four crusts: I ate three and honestly gave the fourth to a friend. There was no friend. People carried these in a coat pocket just in case. The case has come. Keep the wrapper: it will light the stove.", Rare = false },
        new Def { Id = "KorochkiKebab", Kind = Kind.Snack, Shape = "bag", Mesh = "Korochki", Texture = "KorochkiKebab", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «4 корочки»", En = "4 Korochki croutons", RuF = "шашлык", EnF = "shashlik", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Четыре корочки: три съел сам, четвёртую честно отдал другу. Друга не было. Прежний хозяин оставил записку: «Не трогать». Записка сгорела. Если это последняя на острове, вы её достойны.", EnJ = "Four crusts: I ate three and honestly gave the fourth to a friend. There was no friend. The last owner left a note: 'Do not touch'. The note burned. If this is the last one on the island, you have earned it.", Rare = false },
        new Def { Id = "KorochkiHolodets", Kind = Kind.Snack, Shape = "bag", Mesh = "Korochki", Texture = "KorochkiHolodets", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «4 корочки»", En = "4 Korochki croutons", RuF = "новогодний холодец", EnF = "new year aspic", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Новогодняя серия: куранты отбили, а пачка осталась. Редкость. Такими торговали в поезде, пока поезд ходил. Желудок удивится, но возражать не станет.", EnJ = "A New Year edition: the clock has struck, the pack remains. A rarity. They sold these on the train, while the train ran. Your stomach will be surprised but will not object.", Rare = true },
        new Def { Id = "KorochkiGarlic", Kind = Kind.Snack, Shape = "bag", Mesh = "Korochki", Texture = "KorochkiGarlic", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «4 корочки»", En = "4 Korochki croutons", RuF = "чеснок", EnF = "garlic", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Четыре корочки: три съел сам, четвёртую честно отдал другу. Друга не было. Сторож шахты держал такое в ящике стола. Запах выдаёт вас за сто шагов. Оно того стоит.", EnJ = "Four crusts: I ate three and honestly gave the fourth to a friend. There was no friend. The mine watchman kept these in his desk drawer. The smell gives you away at a hundred paces. Worth it.", Rare = false },
        new Def { Id = "KorochkiHorseradish", Kind = Kind.Snack, Shape = "bag", Mesh = "Korochki", Texture = "KorochkiHorseradish", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «4 корочки»", En = "4 Korochki croutons", RuF = "сало с горчицей", EnF = "salo with mustard", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Четыре корочки: три съел сам, четвёртую честно отдал другу. Друга не было. Лавина прошла мимо, срок годности тоже. Раньше это называли вредным. Теперь называют едой.", EnJ = "Four crusts: I ate three and honestly gave the fourth to a friend. There was no friend. The avalanche missed it, and so did the best-before date. They used to call this unhealthy. Now they call it food.", Rare = false },
        new Def { Id = "KorochkiHam", Kind = Kind.Snack, Shape = "bag", Mesh = "Korochki", Texture = "KorochkiHam", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «4 корочки»", En = "4 Korochki croutons", RuF = "ветчина и сыр", EnF = "ham & cheese", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Четыре корочки: три съел сам, четвёртую честно отдал другу. Друга не было. Такое всегда стояло на видном месте, поэтому никто не брал. Спальный мешок потом вытряхните.", EnJ = "Four crusts: I ate three and honestly gave the fourth to a friend. There was no friend. These always stood in plain sight, which is why nobody took them. Shake out your sleeping bag afterwards.", Rare = false },
        new Def { Id = "KorochkiCrab", Kind = Kind.Snack, Shape = "bag", Mesh = "Korochki", Texture = "KorochkiCrab", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «4 корочки»", En = "4 Korochki croutons", RuF = "королевский краб", EnF = "king crab", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Четыре корочки: три съел сам, четвёртую честно отдал другу. Друга не было. Кто-то открыл, передумал и умер. Не связано. Зимой такое идёт за валюту.", EnJ = "Four crusts: I ate three and honestly gave the fourth to a friend. There was no friend. Someone opened it, changed their mind and died. Unrelated. In winter this passes for currency.", Rare = false },
        new Def { Id = "KorochkiSausage", Kind = Kind.Snack, Shape = "bag", Mesh = "Korochki", Texture = "KorochkiSausage", Kg = 0.04f, Kcal = 160f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «4 корочки»", En = "4 Korochki croutons", RuF = "копчёная колбаса", EnF = "smoked sausage", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Четыре корочки: три съел сам, четвёртую честно отдал другу. Друга не было. Такое вечно каталось под сиденьем пикапа. Торговец дал бы за это тряпку. Вы дадите больше.", EnJ = "Four crusts: I ate three and honestly gave the fourth to a friend. There was no friend. One of these was always rolling under a pickup seat. The trader would give a rag for it. You would give more.", Rare = false },
        new Def { Id = "KhrustamGarlic", Kind = Kind.Snack, Shape = "bag", Mesh = "Khrustam", Texture = "KhrustamGarlic", Kg = 0.06f, Kcal = 250f, Thirst = -5f, Eat = 3f, Ru = "Багетные сухарики «Хрустам»", En = "Khrustam baguette croutons", RuF = "чеснок", EnF = "garlic", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Багет, который не дожил до ужина и стал сухариком. Карьера удалась. Привезено паромом, которого больше нет. Пока жуёте, метель кажется короче.", EnJ = "A baguette that never made it to dinner and became a crouton. A fine career. Brought over by a ferry that no longer exists. While you chew, the blizzard seems shorter.", Rare = false },
        new Def { Id = "KhrustamCrab", Kind = Kind.Snack, Shape = "bag", Mesh = "Khrustam", Texture = "KhrustamCrab", Kg = 0.06f, Kcal = 250f, Thirst = -5f, Eat = 3f, Ru = "Багетные сухарики «Хрустам»", En = "Khrustam baguette croutons", RuF = "краб", EnF = "crab", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Багет, который не дожил до ужина и стал сухариком. Карьера удалась. Раньше это ели под телевизор. Телевизор молчит. Организм скажет спасибо. Или не скажет.", EnJ = "A baguette that never made it to dinner and became a crouton. A fine career. People ate this in front of the telly. The telly is silent. Your body will thank you. Or not.", Rare = false },
        new Def { Id = "KhrustamShrimp", Kind = Kind.Snack, Shape = "bag", Mesh = "Khrustam", Texture = "KhrustamShrimp", Kg = 0.06f, Kcal = 250f, Thirst = -5f, Eat = 3f, Ru = "Багетные сухарики «Хрустам»", En = "Khrustam baguette croutons", RuF = "королевская креветка", EnF = "king prawn", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Багет, который не дожил до ужина и стал сухариком. Карьера удалась. Забыто туристами, которым повезло уехать. На третьей горсти забываешь, что вокруг конец света.", EnJ = "A baguette that never made it to dinner and became a crouton. A fine career. Left behind by tourists who were lucky enough to leave. By the third handful you forget the world has ended.", Rare = false },
        new Def { Id = "KhrustamCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Khrustam", Texture = "KhrustamCheese", Kg = 0.06f, Kcal = 250f, Thirst = -5f, Eat = 3f, Ru = "Багетные сухарики «Хрустам»", En = "Khrustam baguette croutons", RuF = "сырное ассорти", EnF = "cheese platter", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Багет, который не дожил до ужина и стал сухариком. Карьера удалась. Механики заедали этим обед, не вытирая рук. Рыба подо льдом завидует.", EnJ = "A baguette that never made it to dinner and became a crouton. A fine career. Mechanics ate these for lunch without wiping their hands. The fish under the ice are jealous.", Rare = false },
        new Def { Id = "KhrustamTomato", Kind = Kind.Snack, Shape = "bag", Mesh = "Khrustam", Texture = "KhrustamTomato", Kg = 0.06f, Kcal = 250f, Thirst = -5f, Eat = 3f, Ru = "Багетные сухарики «Хрустам»", En = "Khrustam baguette croutons", RuF = "томат и зелень", EnF = "tomato & herbs", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Багет, который не дожил до ужина и стал сухариком. Карьера удалась. Последнее на всю Одинокую топь. Скорее всего. Олень от такого отказался бы. Олень не голодал.", EnJ = "A baguette that never made it to dinner and became a crouton. A fine career. The last one in all of Forlorn Muskeg. Most likely. A deer would turn it down. A deer has never starved.", Rare = false },
        new Def { Id = "KhrustamBlini", Kind = Kind.Snack, Shape = "bag", Mesh = "Khrustam", Texture = "KhrustamBlini", Kg = 0.06f, Kcal = 250f, Thirst = -5f, Eat = 3f, Ru = "Багетные сухарики «Хрустам»", En = "Khrustam baguette croutons", RuF = "масленичные блины со сметаной", EnF = "maslenitsa pancakes & sour cream", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Смотритель маяка грыз такое, ожидая кораблей. Соль есть, жир есть, совести нет.", EnJ = "A spring edition: a rare pack from the days when spring still came. The lighthouse keeper munched these while waiting for ships. Salt: yes. Fat: yes. Conscience: none.", Rare = true },
        new Def { Id = "KhrustamOkroshka", Kind = Kind.Snack, Shape = "bag", Mesh = "Khrustam", Texture = "KhrustamOkroshka", Kg = 0.06f, Kcal = 250f, Thirst = -5f, Eat = 3f, Ru = "Багетные сухарики «Хрустам»", En = "Khrustam baguette croutons", RuF = "окрошка на квасе", EnF = "kvass okroshka", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Полки рушились, а это уцелело. Ешьте до темноты: в темноте крошки не найти.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. Shelves collapsed and this survived. Eat before dark: you cannot find crumbs in the dark.", Rare = true },
        new Def { Id = "KhrustamBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Khrustam", Texture = "KhrustamBacon", Kg = 0.06f, Kcal = 250f, Thirst = -5f, Eat = 3f, Ru = "Багетные сухарики «Хрустам»", En = "Khrustam baguette croutons", RuF = "бекон", EnF = "bacon", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Багет, который не дожил до ужина и стал сухариком. Карьера удалась. Смотритель заповедника называл это ужином. Лучшее, что случится с вами сегодня.", EnJ = "A baguette that never made it to dinner and became a crouton. A fine career. The park ranger called this dinner. The best thing that will happen to you today.", Rare = false },
        new Def { Id = "KhrustamAspic", Kind = Kind.Snack, Shape = "bag", Mesh = "Khrustam", Texture = "KhrustamAspic", Kg = 0.06f, Kcal = 250f, Thirst = -5f, Eat = 3f, Ru = "Багетные сухарики «Хрустам»", En = "Khrustam baguette croutons", RuF = "холодец с хреном", EnF = "aspic with horseradish", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Багет, который не дожил до ужина и стал сухариком. Карьера удалась. Такое слали посылками с материка. Адресаты выбыли. Для полного счастья не хватает только дивана.", EnJ = "A baguette that never made it to dinner and became a crouton. A fine career. These came in parcels from the mainland. The addressees are gone. All that is missing for perfect happiness is a sofa.", Rare = false },
        new Def { Id = "KhrustamSmetana", Kind = Kind.Snack, Shape = "bag", Mesh = "Khrustam", Texture = "KhrustamSmetana", Kg = 0.06f, Kcal = 250f, Thirst = -5f, Eat = 3f, Ru = "Багетные сухарики «Хрустам»", En = "Khrustam baguette croutons", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Багет, который не дожил до ужина и стал сухариком. Карьера удалась. Иные держали это за лекарство. Тоже лечит. Вкус детства, если детство было так себе.", EnJ = "A baguette that never made it to dinner and became a crouton. A fine career. Some people counted this as medicine. Also a cure. The taste of childhood, if childhood was so-so.", Rare = false },
        new Def { Id = "KhrustamSalami", Kind = Kind.Snack, Shape = "bag", Mesh = "Khrustam", Texture = "KhrustamSalami", Kg = 0.06f, Kcal = 250f, Thirst = -5f, Eat = 3f, Ru = "Багетные сухарики «Хрустам»", En = "Khrustam baguette croutons", RuF = "салями", EnF = "salami", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Багет, который не дожил до ужина и стал сухариком. Карьера удалась. В школьном рюкзаке такое не доживало до обеда. Шуршит как надежда.", EnJ = "A baguette that never made it to dinner and became a crouton. A fine career. In a school bag this never lasted till lunch. It rustles like hope.", Rare = false },
        new Def { Id = "KhrustamAdjika", Kind = Kind.Snack, Shape = "bag", Mesh = "Khrustam", Texture = "KhrustamAdjika", Kg = 0.06f, Kcal = 250f, Thirst = -5f, Eat = 3f, Ru = "Багетные сухарики «Хрустам»", En = "Khrustam baguette croutons", RuF = "аджика", EnF = "adjika", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Багет, который не дожил до ужина и стал сухариком. Карьера удалась. Его обменяли бы на патрон, будь тут с кем меняться. Голод отступит, жажда придёт. Честный обмен.", EnJ = "A baguette that never made it to dinner and became a crouton. A fine career. You could trade it for a cartridge, if there were anyone to trade with. Hunger leaves, thirst arrives. A fair trade.", Rare = false },
        new Def { Id = "MartynClassic", Kind = Kind.Snack, Shape = "bag", Mesh = "Martyn", Texture = "MartynClassic", Kg = 0.15f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «От Мартына»", En = "Ot Martyna seeds", RuF = "отборные жареные", EnF = "roasted sunflower", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Мартын жарил их так, что щёлкал весь двор. Одна пачка равна одному долгому разговору. На вокзале это стоило втрое дороже. Теперь даром. Не согреет, зато отвлечёт.", EnJ = "Martyn roasted them so the whole yard was cracking shells. One pack equals one long talk. At the station it cost three times as much. Now it is free. It will not warm you, but it will distract you.", Rare = false },
        new Def { Id = "MartynSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "Martyn", Texture = "MartynSalt", Kg = 0.15f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «От Мартына»", En = "Ot Martyna seeds", RuF = "солёные", EnF = "salted sunflower", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Мартын жарил их так, что щёлкал весь двор. Одна пачка равна одному долгому разговору. Пережило толчок и даже не помялось. Пума предпочитает мясо. Вам повезло.", EnJ = "Martyn roasted them so the whole yard was cracking shells. One pack equals one long talk. It came through the quake without a dent. The cougar prefers meat. Lucky you.", Rare = false },
        new Def { Id = "MartynPumpkin", Kind = Kind.Snack, Shape = "bag", Mesh = "Martyn", Texture = "MartynPumpkin", Kg = 0.15f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «От Мартына»", En = "Ot Martyna seeds", RuF = "тыквенные", EnF = "pumpkin seeds", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Мартын жарил их так, что щёлкал весь двор. Одна пачка равна одному долгому разговору. Китобои такого не ели, но оценили бы. Сначала попробуйте одну штучку. Шутка: ешьте всё.", EnJ = "Martyn roasted them so the whole yard was cracking shells. One pack equals one long talk. The whalers never ate this, but they would have approved. Try just one first. Joke: eat the lot.", Rare = false },
        new Def { Id = "MartynStriped", Kind = Kind.Snack, Shape = "bag", Mesh = "Martyn", Texture = "MartynStriped", Kg = 0.15f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «От Мартына»", En = "Ot Martyna seeds", RuF = "полосатые", EnF = "striped sunflower", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Мартын жарил их так, что щёлкал весь двор. Одна пачка равна одному долгому разговору. Осталось после чьего-то дня рождения. Гости не пришли. Такой ужин не стыдно записать в дневник.", EnJ = "Martyn roasted them so the whole yard was cracking shells. One pack equals one long talk. Left over from someone's birthday. The guests never came. A dinner worth writing in the journal.", Rare = false },
        new Def { Id = "MartynMaslenitsa", Kind = Kind.Snack, Shape = "bag", Mesh = "Martyn", Texture = "MartynMaslenitsa", Kg = 0.15f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «От Мартына»", En = "Ot Martyna seeds", RuF = "масленичные с мёдом", EnF = "pancake week honey", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Мерзлота хранит лучше любого холодильника. Силы прибавит на один сугроб.", EnJ = "A spring edition: a rare pack from the days when spring still came. Permafrost keeps things better than any fridge. It will carry you one snowdrift further.", Rare = true },
        new Def { Id = "MartynSesame", Kind = Kind.Snack, Shape = "bag", Mesh = "Martyn", Texture = "MartynSesame", Kg = 0.15f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «От Мартына»", En = "Ot Martyna seeds", RuF = "с кунжутом", EnF = "with sesame", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Мартын жарил их так, что щёлкал весь двор. Одна пачка равна одному долгому разговору. Такое добывали из автомата, который съедал последнюю монету. Идеально к закату, которого не видно за бураном.", EnJ = "Martyn roasted them so the whole yard was cracking shells. One pack equals one long talk. These came from the vending machine that ate your last coin. Perfect with a sunset you cannot see for the storm.", Rare = false },
        new Def { Id = "MartynShelled", Kind = Kind.Snack, Shape = "bag", Mesh = "Martyn", Texture = "MartynShelled", Kg = 0.15f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «От Мартына»", En = "Ot Martyna seeds", RuF = "очищенные", EnF = "shelled kernels", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Мартын жарил их так, что щёлкал весь двор. Одна пачка равна одному долгому разговору. Такое брали в лодку под брезент, на весь день. Пахнет магазином. Помните магазины?", EnJ = "Martyn roasted them so the whole yard was cracking shells. One pack equals one long talk. People took these out in the boat under the tarpaulin, for the whole day. It smells of a shop. Remember shops?", Rare = false },
        new Def { Id = "MartynSmoked", Kind = Kind.Snack, Shape = "bag", Mesh = "Martyn", Texture = "MartynSmoked", Kg = 0.15f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «От Мартына»", En = "Ot Martyna seeds", RuF = "копчёные на ольхе", EnF = "alder smoked", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Мартын жарил их так, что щёлкал весь двор. Одна пачка равна одному долгому разговору. С ним кто-то шёл к перевалу и не дошёл. Мороз не испортил, время не взяло.", EnJ = "Martyn roasted them so the whole yard was cracking shells. One pack equals one long talk. Someone carried it towards the pass and never arrived. Frost did not spoil it and time could not take it.", Rare = false },
        new Def { Id = "MartynKozinak", Kind = Kind.Snack, Shape = "bag", Mesh = "Martyn", Texture = "MartynKozinak", Kg = 0.15f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «От Мартына»", En = "Ot Martyna seeds", RuF = "козинак", EnF = "seed brittle", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Мартын жарил их так, что щёлкал весь двор. Одна пачка равна одному долгому разговору. С таким сидели у окна с видом на метель. В рюкзаке не мнётся. Почти.", EnJ = "Martyn roasted them so the whole yard was cracking shells. One pack equals one long talk. People sat with these at a window with a view of the blizzard. It does not get crushed in a pack. Almost.", Rare = false },
        new Def { Id = "OreshkinSalt", Kind = Kind.Snack, Shape = "can", Mesh = "Oreshkin", Texture = "OreshkinSalt", Kg = 0.17f, Kcal = 900f, Thirst = -8f, Eat = 6f, Ru = "Арахис «Орешкин»", En = "Oreshkin peanuts", RuF = "солёный", EnF = "salted", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Банка арахиса: хотел взять один орешек, очнулся на дне. Уцелело там, где сгорело всё остальное. Съешьте сейчас: завтра может не быть аппетита.", EnJ = "A can of peanuts: I meant to take one and came to at the bottom. It survived where everything else burned. Eat it now: tomorrow you may have no appetite.", Rare = false },
        new Def { Id = "OreshkinHoney", Kind = Kind.Snack, Shape = "can", Mesh = "Oreshkin", Texture = "OreshkinHoney", Kg = 0.17f, Kcal = 900f, Thirst = -8f, Eat = 6f, Ru = "Арахис «Орешкин»", En = "Oreshkin peanuts", RuF = "в медовой глазури", EnF = "honey roasted", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Банка арахиса: хотел взять один орешек, очнулся на дне. Этим кормили сторожевого пса. Пёс ушёл в волки. Хватит дойти до следующей хижины и пожалеть, что кончилось.", EnJ = "A can of peanuts: I meant to take one and came to at the bottom. They fed the guard dog with this. The dog joined the wolves. Enough to reach the next cabin and regret it is gone.", Rare = false },
        new Def { Id = "OreshkinChili", Kind = Kind.Snack, Shape = "can", Mesh = "Oreshkin", Texture = "OreshkinChili", Kg = 0.17f, Kcal = 900f, Thirst = -8f, Eat = 6f, Ru = "Арахис «Орешкин»", En = "Oreshkin peanuts", RuF = "с перцем чили", EnF = "chilli", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Банка арахиса: хотел взять один орешек, очнулся на дне. Из запасов лесорубов: брали ящиками. От такого не толстеют те, кто ходит по двадцать километров.", EnJ = "A can of peanuts: I meant to take one and came to at the bottom. From the loggers' stores: they bought it by the crate. Nobody who walks twenty kilometres a day gets fat on this.", Rare = false },
        new Def { Id = "OreshkinCheese", Kind = Kind.Snack, Shape = "can", Mesh = "Oreshkin", Texture = "OreshkinCheese", Kg = 0.17f, Kcal = 900f, Thirst = -8f, Eat = 6f, Ru = "Арахис «Орешкин»", En = "Oreshkin peanuts", RuF = "со вкусом сыра", EnF = "cheese", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Банка арахиса: хотел взять один орешек, очнулся на дне. В пост такое не ели. Пост кончился вместе с миром. Волчья стая не в курсе. Пусть так и будет.", EnJ = "A can of peanuts: I meant to take one and came to at the bottom. Nobody ate these during a fast. The fast ended with the world. The wolf pack does not know. Keep it that way.", Rare = false },
        new Def { Id = "OreshkinBacon", Kind = Kind.Snack, Shape = "can", Mesh = "Oreshkin", Texture = "OreshkinBacon", Kg = 0.17f, Kcal = 900f, Thirst = -8f, Eat = 6f, Ru = "Арахис «Орешкин»", En = "Oreshkin peanuts", RuF = "со вкусом бекона", EnF = "bacon", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Банка арахиса: хотел взять один орешек, очнулся на дне. Теперь это ценнее денег. Деньги оставьте. Хрустеть в засаде не рекомендуется.", EnJ = "A can of peanuts: I meant to take one and came to at the bottom. It is worth more than money now. Leave the money. Crunching in an ambush is not recommended.", Rare = false },
        new Def { Id = "OreshkinGingerbread", Kind = Kind.Snack, Shape = "can", Mesh = "Oreshkin", Texture = "OreshkinGingerbread", Kg = 0.17f, Kcal = 900f, Thirst = -8f, Eat = 6f, Ru = "Арахис «Орешкин»", En = "Oreshkin peanuts", RuF = "пряничный", EnF = "gingerbread", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Новогодняя серия: куранты отбили, а пачка осталась. Редкость. Его несли на пикник. Пикник отменили навсегда. Лекарство от тоски, отпускается без рецепта.", EnJ = "A New Year edition: the clock has struck, the pack remains. A rarity. It was headed for a picnic. The picnic is cancelled forever. A cure for the blues, no prescription needed.", Rare = true },
        new Def { Id = "OreshkinWasabi", Kind = Kind.Snack, Shape = "can", Mesh = "Oreshkin", Texture = "OreshkinWasabi", Kg = 0.17f, Kcal = 900f, Thirst = -8f, Eat = 6f, Ru = "Арахис «Орешкин»", En = "Oreshkin peanuts", RuF = "васаби", EnF = "wasabi", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Банка арахиса: хотел взять один орешек, очнулся на дне. Такое стояло у кассы на случай слабости. Жуйте и думайте о хорошем. Например, о добавке.", EnJ = "A can of peanuts: I meant to take one and came to at the bottom. These stood by the till for moments of weakness. Chew and think of nice things. Seconds, for example.", Rare = false },
        new Def { Id = "OreshkinSmetana", Kind = Kind.Snack, Shape = "can", Mesh = "Oreshkin", Texture = "OreshkinSmetana", Kg = 0.17f, Kcal = 900f, Thirst = -8f, Eat = 6f, Ru = "Арахис «Орешкин»", En = "Oreshkin peanuts", RuF = "сметана и зелень", EnF = "sour cream & herbs", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Банка арахиса: хотел взять один орешек, очнулся на дне. Досталось вам, потому что вы дошли первым. К утру от него останется только запах на варежках.", EnJ = "A can of peanuts: I meant to take one and came to at the bottom. It is yours because you got here first. By morning only the smell on your mittens will be left.", Rare = false },
        new Def { Id = "OreshkinShashlik", Kind = Kind.Snack, Shape = "can", Mesh = "Oreshkin", Texture = "OreshkinShashlik", Kg = 0.17f, Kcal = 900f, Thirst = -8f, Eat = 6f, Ru = "Арахис «Орешкин»", En = "Oreshkin peanuts", RuF = "шашлык", EnF = "shashlik", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Банка арахиса: хотел взять один орешек, очнулся на дне. Упаковка выцвела, внутри время остановилось. Тишина вокруг такая, что слышно, как вы жуёте.", EnJ = "A can of peanuts: I meant to take one and came to at the bottom. The wrapper has faded; inside, time stood still. It is so quiet you can hear yourself chew.", Rare = false },
        new Def { Id = "OreshkinCrab", Kind = Kind.Snack, Shape = "can", Mesh = "Oreshkin", Texture = "OreshkinCrab", Kg = 0.17f, Kcal = 900f, Thirst = -8f, Eat = 6f, Ru = "Арахис «Орешкин»", En = "Oreshkin peanuts", RuF = "краб", EnF = "crab", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Банка арахиса: хотел взять один орешек, очнулся на дне. Из чемодана пассажира, который не долетел. Не делите на завтра: завтра будет новый голод.", EnJ = "A can of peanuts: I meant to take one and came to at the bottom. From the suitcase of a passenger who never landed. Do not save half for tomorrow: tomorrow brings its own hunger.", Rare = false },
        new Def { Id = "OreshkinCoconut", Kind = Kind.Snack, Shape = "can", Mesh = "Oreshkin", Texture = "OreshkinCoconut", Kg = 0.17f, Kcal = 900f, Thirst = -8f, Eat = 6f, Ru = "Арахис «Орешкин»", En = "Oreshkin peanuts", RuF = "в кокосовой глазури", EnF = "coconut glazed", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Банка арахиса: хотел взять один орешек, очнулся на дне. Перезимовало и ничуть не обиделось. Сосны вокруг делают вид, что не смотрят.", EnJ = "A can of peanuts: I meant to take one and came to at the bottom. It made it through the winter and bears no grudge. The pines around pretend not to watch.", Rare = false },
        new Def { Id = "OreshkinGarlic", Kind = Kind.Snack, Shape = "can", Mesh = "Oreshkin", Texture = "OreshkinGarlic", Kg = 0.17f, Kcal = 900f, Thirst = -8f, Eat = 6f, Ru = "Арахис «Орешкин»", En = "Oreshkin peanuts", RuF = "чеснок", EnF = "garlic", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Банка арахиса: хотел взять один орешек, очнулся на дне. Запасливая хозяйка купила по акции шесть штук. Калории мелкие, зато свои.", EnJ = "A can of peanuts: I meant to take one and came to at the bottom. A thrifty housewife bought six of these on offer. Small calories, but your own.", Rare = false },
        new Def { Id = "StarpomSquid", Kind = Kind.Snack, Shape = "sachet", Mesh = "Starpom", Texture = "StarpomSquid", Kg = 0.07f, Kcal = 200f, Thirst = -10f, Eat = 8f, Ru = "Морские снеки «Старпом»", En = "Starpom sea snacks", RuF = "кальмар сушёный", EnF = "dried squid", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Старпом на пачке смотрит строго: закуска уставная, к пенному положена. Кто-то написал на упаковке «моё». Уже нет. После этого даже крапивный чай покажется десертом.", EnJ = "The first mate on the pack looks stern: a regulation snack, issued with beer. Someone wrote 'mine' on it. Not any more. After this even nettle tea feels like dessert.", Rare = false },
        new Def { Id = "StarpomAnchovy", Kind = Kind.Snack, Shape = "sachet", Mesh = "Starpom", Texture = "StarpomAnchovy", Kg = 0.07f, Kcal = 200f, Thirst = -10f, Eat = 8f, Ru = "Морские снеки «Старпом»", En = "Starpom sea snacks", RuF = "анчоус солёно-сушёный", EnF = "dried anchovy", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Старпом на пачке смотрит строго: закуска уставная, к пенному положена. В консервном цеху это ели тайком от мастера. Нашедшему полагается всё.", EnJ = "The first mate on the pack looks stern: a regulation snack, issued with beer. At the cannery they ate this behind the foreman's back. Finders keepers, all of it.", Rare = false },
        new Def { Id = "StarpomStripe", Kind = Kind.Snack, Shape = "sachet", Mesh = "Starpom", Texture = "StarpomStripe", Kg = 0.07f, Kcal = 200f, Thirst = -10f, Eat = 8f, Ru = "Морские снеки «Старпом»", En = "Starpom sea snacks", RuF = "жёлтый полосатик", EnF = "yellow stripe trevally", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Старпом на пачке смотрит строго: закуска уставная, к пенному положена. Его не взяли даже мародёры. Они спешили. Зубы целы? Тогда вперёд.", EnJ = "The first mate on the pack looks stern: a regulation snack, issued with beer. Even the looters left it. They were in a hurry. Teeth intact? Then go ahead.", Rare = false },
        new Def { Id = "StarpomOctopus", Kind = Kind.Snack, Shape = "sachet", Mesh = "Starpom", Texture = "StarpomOctopus", Kg = 0.07f, Kcal = 200f, Thirst = -10f, Eat = 8f, Ru = "Морские снеки «Старпом»", En = "Starpom sea snacks", RuF = "осьминог сушёный", EnF = "dried octopus", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Старпом на пачке смотрит строго: закуска уставная, к пенному положена. Провело зиму на острове, как и вы. Ночью приснится добавка.", EnJ = "The first mate on the pack looks stern: a regulation snack, issued with beer. It spent the winter on the island, same as you. Tonight you will dream of seconds.", Rare = false },
        new Def { Id = "StarpomPollock", Kind = Kind.Snack, Shape = "sachet", Mesh = "Starpom", Texture = "StarpomPollock", Kg = 0.07f, Kcal = 200f, Thirst = -10f, Eat = 8f, Ru = "Морские снеки «Старпом»", En = "Starpom sea snacks", RuF = "минтай сушёный", EnF = "dried pollock", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Старпом на пачке смотрит строго: закуска уставная, к пенному положена. Дети прятали такое под кроватью, в тайнике. С таким запасом можно пережить ещё один вечер.", EnJ = "The first mate on the pack looks stern: a regulation snack, issued with beer. Children hid these under the bed, in a secret place. With supplies like this you can survive one more evening.", Rare = false },
        new Def { Id = "StarpomCaviar", Kind = Kind.Snack, Shape = "sachet", Mesh = "Starpom", Texture = "StarpomCaviar", Kg = 0.07f, Kcal = 200f, Thirst = -10f, Eat = 8f, Ru = "Морские снеки «Старпом»", En = "Starpom sea snacks", RuF = "новогодняя икра минтая", EnF = "new year pollock roe", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Новогодняя серия: куранты отбили, а пачка осталась. Редкость. Осталось от геологов вместе с картой и долгами. Пёс бы выпросил половину. Пса нет.", EnJ = "A New Year edition: the clock has struck, the pack remains. A rarity. Left by the geologists along with a map and some debts. A dog would beg half of it. There is no dog.", Rare = true },
        new Def { Id = "StarpomSummer", Kind = Kind.Snack, Shape = "sachet", Mesh = "Starpom", Texture = "StarpomSummer", Kg = 0.07f, Kcal = 200f, Thirst = -10f, Eat = 8f, Ru = "Морские снеки «Старпом»", En = "Starpom sea snacks", RuF = "летняя таранка", EnF = "summer roach", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. На острове такое было праздником и до катастрофы. Съедено будет быстрее, чем найдено.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. On the island this was a treat even before the disaster. It will be eaten faster than it was found.", Rare = true },
        new Def { Id = "StarpomTuna", Kind = Kind.Snack, Shape = "sachet", Mesh = "Starpom", Texture = "StarpomTuna", Kg = 0.07f, Kcal = 200f, Thirst = -10f, Eat = 8f, Ru = "Морские снеки «Старпом»", En = "Starpom sea snacks", RuF = "тунец стружкой", EnF = "shredded tuna", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Старпом на пачке смотрит строго: закуска уставная, к пенному положена. С таким слушали радио, которое теперь ловит только треск. На вкус как выходной.", EnJ = "The first mate on the pack looks stern: a regulation snack, issued with beer. People ate these by the radio, which picks up nothing but crackle now. It tastes like a day off.", Rare = false },
        new Def { Id = "StarpomShrimp", Kind = Kind.Snack, Shape = "sachet", Mesh = "Starpom", Texture = "StarpomShrimp", Kg = 0.07f, Kcal = 200f, Thirst = -10f, Eat = 8f, Ru = "Морские снеки «Старпом»", En = "Starpom sea snacks", RuF = "сушёная креветка", EnF = "dried shrimp", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Старпом на пачке смотрит строго: закуска уставная, к пенному положена. Крысы прогрызли соседнюю, эту пощадили. Ветер унесёт запах прямо к берлоге. Ешьте быстрее.", EnJ = "The first mate on the pack looks stern: a regulation snack, issued with beer. The rats gnawed through the one next to it and spared this. The wind carries the smell straight to the den. Eat faster.", Rare = false },
        new Def { Id = "StarpomSalmon", Kind = Kind.Snack, Shape = "sachet", Mesh = "Starpom", Texture = "StarpomSalmon", Kg = 0.07f, Kcal = 200f, Thirst = -10f, Eat = 8f, Ru = "Морские снеки «Старпом»", En = "Starpom sea snacks", RuF = "лосось соломкой", EnF = "salmon straws", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Старпом на пачке смотрит строго: закуска уставная, к пенному положена. Бывший хозяин клялся бросить. Не успел. Пополняет запас соли и веры в человечество.", EnJ = "The first mate on the pack looks stern: a regulation snack, issued with beer. The former owner swore to give these up. He ran out of time. Restores your salt and your faith in mankind.", Rare = false },
        new Def { Id = "StarpomFlounder", Kind = Kind.Snack, Shape = "sachet", Mesh = "Starpom", Texture = "StarpomFlounder", Kg = 0.07f, Kcal = 200f, Thirst = -10f, Eat = 8f, Ru = "Морские снеки «Старпом»", En = "Starpom sea snacks", RuF = "камбала", EnF = "flounder", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Старпом на пачке смотрит строго: закуска уставная, к пенному положена. Его катали в кабине трактора три сезона. Хорошо идёт под треск поленьев.", EnJ = "The first mate on the pack looks stern: a regulation snack, issued with beer. It rode around in a tractor cab for three seasons. Goes down well with crackling logs.", Rare = false },
        new Def { Id = "StarpomSeaweed", Kind = Kind.Snack, Shape = "sachet", Mesh = "Starpom", Texture = "StarpomSeaweed", Kg = 0.07f, Kcal = 200f, Thirst = -10f, Eat = 8f, Ru = "Морские снеки «Старпом»", En = "Starpom sea snacks", RuF = "морская капуста", EnF = "dried kelp", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Старпом на пачке смотрит строго: закуска уставная, к пенному положена. После бани такое шло лучше всего. Руки вытирать о штаны: салфеток не завезли.", EnJ = "The first mate on the pack looks stern: a regulation snack, issued with beer. Nothing went down better after the sauna. Wipe your hands on your trousers: no napkins were delivered.", Rare = false },
        new Def { Id = "StarpomPepper", Kind = Kind.Snack, Shape = "sachet", Mesh = "Starpom", Texture = "StarpomPepper", Kg = 0.07f, Kcal = 200f, Thirst = -10f, Eat = 8f, Ru = "Морские снеки «Старпом»", En = "Starpom sea snacks", RuF = "кальмар с перцем", EnF = "peppered squid", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Старпом на пачке смотрит строго: закуска уставная, к пенному положена. В тюрьме на это выменивали что угодно. Маленькая радость размером с ладонь.", EnJ = "The first mate on the pack looks stern: a regulation snack, issued with beer. In the prison you could trade one of these for anything. A small joy the size of your palm.", Rare = false },
        new Def { Id = "YozhikSweet", Kind = Kind.Snack, Shape = "bag", Mesh = "Yozhik", Texture = "YozhikSweet", Kg = 0.14f, Kcal = 530f, Thirst = -2f, Eat = 5f, Ru = "Кукурузные палочки «Ёжик»", En = "Yozhik corn sticks", RuF = "сладкие", EnF = "sweet", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Кукурузные палочки из детства: липнут к языку и к воспоминаниям. Кто-то менял это на сигареты. Сделка сорвалась. Совесть молчит, живот поёт.", EnJ = "Corn sticks from childhood: they stick to the tongue and to the memories. Someone was trading this for cigarettes. The deal fell through. Conscience is silent, the belly sings.", Rare = false },
        new Def { Id = "YozhikMilk", Kind = Kind.Snack, Shape = "bag", Mesh = "Yozhik", Texture = "YozhikMilk", Kg = 0.14f, Kcal = 530f, Thirst = -2f, Eat = 5f, Ru = "Кукурузные палочки «Ёжик»", En = "Yozhik corn sticks", RuF = "молочные", EnF = "milky", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Кукурузные палочки из детства: липнут к языку и к воспоминаниям. С ним зимовали на метеостанции, пока было с кем. Проверено поколениями и одной катастрофой.", EnJ = "Corn sticks from childhood: they stick to the tongue and to the memories. They wintered with it at the weather station, while there was a 'they'. Tested by generations and one catastrophe.", Rare = false },
        new Def { Id = "YozhikChoco", Kind = Kind.Snack, Shape = "bag", Mesh = "Yozhik", Texture = "YozhikChoco", Kg = 0.14f, Kcal = 530f, Thirst = -2f, Eat = 5f, Ru = "Кукурузные палочки «Ёжик»", En = "Yozhik corn sticks", RuF = "шоколадные", EnF = "chocolate", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Кукурузные палочки из детства: липнут к языку и к воспоминаниям. Такое терялось в кладовке среди крупы и надежд. Оставьте пару штук на перевал. Не оставите.", EnJ = "Corn sticks from childhood: they stick to the tongue and to the memories. These got lost in the pantry among the grain and the hopes. Save a couple for the pass. You will not.", Rare = false },
        new Def { Id = "YozhikBanana", Kind = Kind.Snack, Shape = "bag", Mesh = "Yozhik", Texture = "YozhikBanana", Kg = 0.14f, Kcal = 530f, Thirst = -2f, Eat = 5f, Ru = "Кукурузные палочки «Ёжик»", En = "Yozhik corn sticks", RuF = "банановые", EnF = "banana", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Кукурузные палочки из детства: липнут к языку и к воспоминаниям. Его берегли к приезду внуков. Здесь это считается ужином при свечах.", EnJ = "Corn sticks from childhood: they stick to the tongue and to the memories. It was being saved for the grandchildren's visit. Round here this counts as a candlelit dinner.", Rare = false },
        new Def { Id = "YozhikCinnamon", Kind = Kind.Snack, Shape = "bag", Mesh = "Yozhik", Texture = "YozhikCinnamon", Kg = 0.14f, Kcal = 530f, Thirst = -2f, Eat = 5f, Ru = "Кукурузные палочки «Ёжик»", En = "Yozhik corn sticks", RuF = "новогодние с корицей", EnF = "new year cinnamon", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Новогодняя серия: куранты отбили, а пачка осталась. Редкость. В баре такое ставили на стойку, бесплатно к пиву. Пива нет. Больше таких не делают. Совсем.", EnJ = "A New Year edition: the clock has struck, the pack remains. A rarity. Bars put these out free with a beer. There is no beer. They do not make these any more. At all.", Rare = true },
        new Def { Id = "YozhikNewYear", Kind = Kind.Snack, Shape = "bag", Mesh = "Yozhik", Texture = "YozhikNewYear", Kg = 0.14f, Kcal = 530f, Thirst = -2f, Eat = 5f, Ru = "Кукурузные палочки «Ёжик»", En = "Yozhik corn sticks", RuF = "мандариновые", EnF = "tangerine", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Новогодняя серия: куранты отбили, а пачка осталась. Редкость. Такое лежало в каждом доме, пока не погас свет. Одной не обойдётся, но вторая неизвестно где.", EnJ = "A New Year edition: the clock has struck, the pack remains. A rarity. Every house had one of these until the lights went out. One won't be enough, and nobody knows where the second is.", Rare = true },
        new Def { Id = "YozhikStrawberry", Kind = Kind.Snack, Shape = "bag", Mesh = "Yozhik", Texture = "YozhikStrawberry", Kg = 0.14f, Kcal = 530f, Thirst = -2f, Eat = 5f, Ru = "Кукурузные палочки «Ёжик»", En = "Yozhik corn sticks", RuF = "клубничные", EnF = "strawberry", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Кукурузные палочки из детства: липнут к языку и к воспоминаниям. Кто-то берёг это на чёрный день. Он настал. Больше таких не делают. Совсем.", EnJ = "Corn sticks from childhood: they stick to the tongue and to the memories. Someone saved this for a rainy day. It came. They do not make these any more. At all.", Rare = false },
        new Def { Id = "YozhikCaramel", Kind = Kind.Snack, Shape = "bag", Mesh = "Yozhik", Texture = "YozhikCaramel", Kg = 0.14f, Kcal = 530f, Thirst = -2f, Eat = 5f, Ru = "Кукурузные палочки «Ёжик»", En = "Yozhik corn sticks", RuF = "карамельные", EnF = "caramel", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Кукурузные палочки из детства: липнут к языку и к воспоминаниям. Пережило хозяина, кота и две зимы. Открывайте тихо: у волков отличный слух.", EnJ = "Corn sticks from childhood: they stick to the tongue and to the memories. It outlived its owner, the cat and two winters. Open it quietly: wolves have excellent hearing.", Rare = false },
        new Def { Id = "YozhikCondensed", Kind = Kind.Snack, Shape = "bag", Mesh = "Yozhik", Texture = "YozhikCondensed", Kg = 0.14f, Kcal = 530f, Thirst = -2f, Eat = 5f, Ru = "Кукурузные палочки «Ёжик»", En = "Yozhik corn sticks", RuF = "со сгущёнкой", EnF = "condensed milk", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Кукурузные палочки из детства: липнут к языку и к воспоминаниям. Такое обычно находили за диваном, как всё лучшее в жизни. Одной не обойдётся, но вторая неизвестно где.", EnJ = "Corn sticks from childhood: they stick to the tongue and to the memories. These were usually found behind the sofa, like all the best things in life. One won't be enough, and nobody knows where the second is.", Rare = false },
        new Def { Id = "YozhikHoney", Kind = Kind.Snack, Shape = "bag", Mesh = "Yozhik", Texture = "YozhikHoney", Kg = 0.14f, Kcal = 530f, Thirst = -2f, Eat = 5f, Ru = "Кукурузные палочки «Ёжик»", En = "Yozhik corn sticks", RuF = "медовые", EnF = "honey", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Кукурузные палочки из детства: липнут к языку и к воспоминаниям. Последний завоз был до того, как упали самолёты. Крошки с пола тоже считаются.", EnJ = "Corn sticks from childhood: they stick to the tongue and to the memories. The last delivery came before the planes fell. The crumbs on the floor count too.", Rare = false },
        new Def { Id = "YozhikVanilla", Kind = Kind.Snack, Shape = "bag", Mesh = "Yozhik", Texture = "YozhikVanilla", Kg = 0.14f, Kcal = 530f, Thirst = -2f, Eat = 5f, Ru = "Кукурузные палочки «Ёжик»", En = "Yozhik corn sticks", RuF = "ванильные", EnF = "vanilla", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Кукурузные палочки из детства: липнут к языку и к воспоминаниям. Ценник оторван: теперь это бесценно. Запейте чаем из шиповника и считайте это обедом.", EnJ = "Corn sticks from childhood: they stick to the tongue and to the memories. The price tag is torn off: it is priceless now. Wash it down with rosehip tea and call it lunch.", Rare = false },
        new Def { Id = "DoritozNacho", Kind = Kind.Snack, Shape = "bag", Mesh = "Doritoz", Texture = "DoritozNacho", Kg = 0.158f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Доритоз»", En = "Doritoz tortilla chips", RuF = "сыр начо", EnF = "nacho cheese", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Треугольники, после которых пальцы пахнут сыром, а клавиатура помнит всё. Дата на шве стёрлась, и слава богу. Медведю не показывать: отнимет вместе с рукой.", EnJ = "Triangles that leave your fingers smelling of cheese and your keyboard remembering everything. The date on the seam has rubbed off, thank goodness. Do not show the bear: he will take it, hand and all.", Rare = false },
        new Def { Id = "DoritozRanch", Kind = Kind.Snack, Shape = "bag", Mesh = "Doritoz", Texture = "DoritozRanch", Kg = 0.158f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Доритоз»", En = "Doritoz tortilla chips", RuF = "соус ранч", EnF = "cool ranch", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Треугольники, после которых пальцы пахнут сыром, а клавиатура помнит всё. Пахнет заправкой у Прибрежного шоссе. Диетолог не одобрил бы. Диетолога тут нет.", EnJ = "Triangles that leave your fingers smelling of cheese and your keyboard remembering everything. It smells of the petrol station on the Coastal Highway. A dietitian would not approve. There is no dietitian here.", Rare = false },
        new Def { Id = "DoritozChili", Kind = Kind.Snack, Shape = "bag", Mesh = "Doritoz", Texture = "DoritozChili", Kg = 0.158f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Доритоз»", En = "Doritoz tortilla chips", RuF = "сладкий чили", EnF = "sweet chilli", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Треугольники, после которых пальцы пахнут сыром, а клавиатура помнит всё. Такое возили в бардачке на дальнюю дорогу. Дороги кончились. Лучше, чем кора. Проверено.", EnJ = "Triangles that leave your fingers smelling of cheese and your keyboard remembering everything. People kept these in the glovebox for long drives. The drives are over. Better than bark. Tested.", Rare = false },
        new Def { Id = "DoritozHot", Kind = Kind.Snack, Shape = "bag", Mesh = "Doritoz", Texture = "DoritozHot", Kg = 0.158f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Доритоз»", En = "Doritoz tortilla chips", RuF = "огненные", EnF = "flamin hot", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Треугольники, после которых пальцы пахнут сыром, а клавиатура помнит всё. Мыши не тронули. Думайте сами. Хруст разносится до соседней долины.", EnJ = "Triangles that leave your fingers smelling of cheese and your keyboard remembering everything. The mice left it alone. Draw your own conclusions. The crunch carries to the next valley.", Rare = false },
        new Def { Id = "DoritozSalsa", Kind = Kind.Snack, Shape = "bag", Mesh = "Doritoz", Texture = "DoritozSalsa", Kg = 0.158f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Доритоз»", En = "Doritoz tortilla chips", RuF = "сальса", EnF = "salsa", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Треугольники, после которых пальцы пахнут сыром, а клавиатура помнит всё. Рыбаки брали такое на лёд вместо обеда. Ешьте медленно: когда ещё такое найдёте.", EnJ = "Triangles that leave your fingers smelling of cheese and your keyboard remembering everything. Fishermen took this onto the ice instead of lunch. Eat slowly: who knows when you will find another.", Rare = false },
        new Def { Id = "DoritozPumpkin", Kind = Kind.Snack, Shape = "bag", Mesh = "Doritoz", Texture = "DoritozPumpkin", Kg = 0.158f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Доритоз»", En = "Doritoz tortilla chips", RuF = "огненная тыква", EnF = "pumpkin fire", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Серия к Хэллоуину: редкость. Пугать тут и без неё есть кому. Смотритель плотины держал такое в заначке. К этому просится пиво, а есть только талый снег.", EnJ = "A Halloween edition: a rarity. There is plenty to scare you here without it. The dam keeper kept a stash of these. It begs for a beer, and there is only melted snow.", Rare = true },
        new Def { Id = "DoritozTurkey", Kind = Kind.Snack, Shape = "bag", Mesh = "Doritoz", Texture = "DoritozTurkey", Kg = 0.158f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Доритоз»", En = "Doritoz tortilla chips", RuF = "индейка в остром соусе", EnF = "spicy turkey", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Кто-то спрятал это от детей. Дети не нашли. Сияние на вкус не влияет. Наверное.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. Someone hid it from the kids. The kids never found it. The aurora does not affect the taste. Probably.", Rare = true },
        new Def { Id = "DoritozSummer", Kind = Kind.Snack, Shape = "bag", Mesh = "Doritoz", Texture = "DoritozSummer", Kg = 0.158f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Доритоз»", En = "Doritoz tortilla chips", RuF = "гриль и лайм", EnF = "grill & lime", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. В сельском магазине такое вечно заваливалось за прилавок. После тушёнки из банки это почти ресторан.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. In the village shop these kept slipping behind the counter. After stew from a tin this is nearly a restaurant.", Rare = true },
        new Def { Id = "DoritozTaco", Kind = Kind.Snack, Shape = "bag", Mesh = "Doritoz", Texture = "DoritozTaco", Kg = 0.158f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Доритоз»", En = "Doritoz tortilla chips", RuF = "тако", EnF = "taco", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Треугольники, после которых пальцы пахнут сыром, а клавиатура помнит всё. Ждало покупателя дольше, чем тот прожил. Делиться не с кем, и это впервые радует.", EnJ = "Triangles that leave your fingers smelling of cheese and your keyboard remembering everything. It waited for a buyer longer than the buyer lived. Nobody to share with, and for once that is good news.", Rare = false },
        new Def { Id = "DoritozBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Doritoz", Texture = "DoritozBBQ", Kg = 0.158f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Доритоз»", En = "Doritoz tortilla chips", RuF = "сладкий барбекю", EnF = "sweet barbecue", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Треугольники, после которых пальцы пахнут сыром, а клавиатура помнит всё. С материка такое больше не привезут. Пальцы потом оближите: зимой калории не выбрасывают.", EnJ = "Triangles that leave your fingers smelling of cheese and your keyboard remembering everything. Nobody will bring this from the mainland again. Lick your fingers after: in winter you do not waste calories.", Rare = false },
        new Def { Id = "DoritozJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "Doritoz", Texture = "DoritozJalapeno", Kg = 0.158f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Доритоз»", En = "Doritoz tortilla chips", RuF = "халапеньо", EnF = "jalapeno", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Треугольники, после которых пальцы пахнут сыром, а клавиатура помнит всё. На упаковке иней, внутри всё по-прежнему. Ворон на ветке уже ждёт свою долю.", EnJ = "Triangles that leave your fingers smelling of cheese and your keyboard remembering everything. Frost on the wrapper, business as usual inside. The crow on the branch is already waiting for its share.", Rare = false },
        new Def { Id = "DoritozJack", Kind = Kind.Snack, Shape = "bag", Mesh = "Doritoz", Texture = "DoritozJack", Kg = 0.158f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Доритоз»", En = "Doritoz tortilla chips", RuF = "острый сыр", EnF = "spicy nacho", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Треугольники, после которых пальцы пахнут сыром, а клавиатура помнит всё. Мороз ему нипочём: твёрже не стало, мягче тоже. На морозе хрустит вдвое громче.", EnJ = "Triangles that leave your fingers smelling of cheese and your keyboard remembering everything. The frost did nothing to it: no harder, no softer. In the frost it crunches twice as loud.", Rare = false },
        new Def { Id = "DoritozLime", Kind = Kind.Snack, Shape = "bag", Mesh = "Doritoz", Texture = "DoritozLime", Kg = 0.158f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Доритоз»", En = "Doritoz tortilla chips", RuF = "лайм", EnF = "lime", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Треугольники, после которых пальцы пахнут сыром, а клавиатура помнит всё. Из тех времён, когда еду выбирали по вкусу. Не еда, а настроение. Настроение тоже греет.", EnJ = "Triangles that leave your fingers smelling of cheese and your keyboard remembering everything. From the days when people picked food for its taste. Not food but a mood. A mood warms you too.", Rare = false },
        new Def { Id = "DoritozPure", Kind = Kind.Snack, Shape = "bag", Mesh = "Doritoz", Texture = "DoritozPure", Kg = 0.158f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Доритоз»", En = "Doritoz tortilla chips", RuF = "чистая паприка", EnF = "pure paprika", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Треугольники, после которых пальцы пахнут сыром, а клавиатура помнит всё. Чей-то перекус на ночную смену, которая не кончилась. Сытости на час, воспоминаний на неделю.", EnJ = "Triangles that leave your fingers smelling of cheese and your keyboard remembering everything. Someone's snack for a night shift that never ended. An hour of fullness, a week of memories.", Rare = false },
        new Def { Id = "DoritozCheesier", Kind = Kind.Snack, Shape = "bag", Mesh = "Doritoz", Texture = "DoritozCheesier", Kg = 0.158f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Доритоз»", En = "Doritoz tortilla chips", RuF = "сливочный сыр", EnF = "cream cheese", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Треугольники, после которых пальцы пахнут сыром, а клавиатура помнит всё. В охотничьей вышке таким встречали рассвет. Кролик смотрит с осуждением.", EnJ = "Triangles that leave your fingers smelling of cheese and your keyboard remembering everything. In the hunting blind they met the dawn with this. The rabbit looks on with disapproval.", Rare = false },
        new Def { Id = "RufflzOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "Rufflz", Texture = "RufflzOriginal", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Раффлз»", En = "Rufflz ridged crisps", RuF = "оригинальные", EnF = "original", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Чипсы с рёбрами жёсткости: инженеры гордятся, соус держится. Такое носили в кармане куртки на всякий случай. Случай настал. У костра вкуснее. У костра всё вкуснее.", EnJ = "Crisps with stiffening ribs: engineers are proud, the dip holds. People carried these in a coat pocket just in case. The case has come. It tastes better by the fire. Everything does.", Rare = false },
        new Def { Id = "RufflzCheddar", Kind = Kind.Snack, Shape = "bag", Mesh = "Rufflz", Texture = "RufflzCheddar", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Раффлз»", En = "Rufflz ridged crisps", RuF = "чеддер и сметана", EnF = "cheddar & sour cream", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Чипсы с рёбрами жёсткости: инженеры гордятся, соус держится. Прежний хозяин оставил записку: «Не трогать». Записка сгорела. Упаковку не выбрасывайте: ею можно разжечь печь.", EnJ = "Crisps with stiffening ribs: engineers are proud, the dip holds. The last owner left a note: 'Do not touch'. The note burned. Keep the wrapper: it will light the stove.", Rare = false },
        new Def { Id = "RufflzBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Rufflz", Texture = "RufflzBBQ", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Раффлз»", En = "Rufflz ridged crisps", RuF = "барбекю", EnF = "barbecue", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Чипсы с рёбрами жёсткости: инженеры гордятся, соус держится. Такими торговали в поезде, пока поезд ходил. Если это последняя на острове, вы её достойны.", EnJ = "Crisps with stiffening ribs: engineers are proud, the dip holds. They sold these on the train, while the train ran. If this is the last one on the island, you have earned it.", Rare = false },
        new Def { Id = "RufflzOnion", Kind = Kind.Snack, Shape = "bag", Mesh = "Rufflz", Texture = "RufflzOnion", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Раффлз»", En = "Rufflz ridged crisps", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Чипсы с рёбрами жёсткости: инженеры гордятся, соус держится. Сторож шахты держал такое в ящике стола. Желудок удивится, но возражать не станет.", EnJ = "Crisps with stiffening ribs: engineers are proud, the dip holds. The mine watchman kept these in his desk drawer. Your stomach will be surprised but will not object.", Rare = false },
        new Def { Id = "RufflzGravy", Kind = Kind.Snack, Shape = "bag", Mesh = "Rufflz", Texture = "RufflzGravy", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Раффлз»", En = "Rufflz ridged crisps", RuF = "пюре с подливкой", EnF = "mashed potato & gravy", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Лавина прошла мимо, срок годности тоже. Запах выдаёт вас за сто шагов. Оно того стоит.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. The avalanche missed it, and so did the best-before date. The smell gives you away at a hundred paces. Worth it.", Rare = true },
        new Def { Id = "RufflzJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "Rufflz", Texture = "RufflzJalapeno", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Раффлз»", En = "Rufflz ridged crisps", RuF = "халапеньо ранч", EnF = "jalapeno ranch", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Чипсы с рёбрами жёсткости: инженеры гордятся, соус держится. Такое всегда стояло на видном месте, поэтому никто не брал. Раньше это называли вредным. Теперь называют едой.", EnJ = "Crisps with stiffening ribs: engineers are proud, the dip holds. These always stood in plain sight, which is why nobody took them. They used to call this unhealthy. Now they call it food.", Rare = false },
        new Def { Id = "RufflzAllDressed", Kind = Kind.Snack, Shape = "bag", Mesh = "Rufflz", Texture = "RufflzAllDressed", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Раффлз»", En = "Rufflz ridged crisps", RuF = "со всеми приправами", EnF = "all dressed", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Чипсы с рёбрами жёсткости: инженеры гордятся, соус держится. Кто-то открыл, передумал и умер. Не связано. Спальный мешок потом вытряхните.", EnJ = "Crisps with stiffening ribs: engineers are proud, the dip holds. Someone opened it, changed their mind and died. Unrelated. Shake out your sleeping bag afterwards.", Rare = false },
        new Def { Id = "RufflzQueso", Kind = Kind.Snack, Shape = "bag", Mesh = "Rufflz", Texture = "RufflzQueso", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Раффлз»", En = "Rufflz ridged crisps", RuF = "сырный соус кесо", EnF = "queso", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Чипсы с рёбрами жёсткости: инженеры гордятся, соус держится. Такое вечно каталось под сиденьем пикапа. Зимой такое идёт за валюту.", EnJ = "Crisps with stiffening ribs: engineers are proud, the dip holds. One of these was always rolling under a pickup seat. In winter this passes for currency.", Rare = false },
        new Def { Id = "RufflzHot", Kind = Kind.Snack, Shape = "bag", Mesh = "Rufflz", Texture = "RufflzHot", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Раффлз»", En = "Rufflz ridged crisps", RuF = "огненные", EnF = "flamin hot", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Чипсы с рёбрами жёсткости: инженеры гордятся, соус держится. Привезено паромом, которого больше нет. Торговец дал бы за это тряпку. Вы дадите больше.", EnJ = "Crisps with stiffening ribs: engineers are proud, the dip holds. Brought over by a ferry that no longer exists. The trader would give a rag for it. You would give more.", Rare = false },
        new Def { Id = "RufflzBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Rufflz", Texture = "RufflzBacon", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Раффлз»", En = "Rufflz ridged crisps", RuF = "бекон и чеддер", EnF = "bacon & cheddar", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Чипсы с рёбрами жёсткости: инженеры гордятся, соус держится. Раньше это ели под телевизор. Телевизор молчит. Пока жуёте, метель кажется короче.", EnJ = "Crisps with stiffening ribs: engineers are proud, the dip holds. People ate this in front of the telly. The telly is silent. While you chew, the blizzard seems shorter.", Rare = false },
        new Def { Id = "RufflzLime", Kind = Kind.Snack, Shape = "bag", Mesh = "Rufflz", Texture = "RufflzLime", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Раффлз»", En = "Rufflz ridged crisps", RuF = "лайм и перец", EnF = "lime & jalapeno", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Чипсы с рёбрами жёсткости: инженеры гордятся, соус держится. Забыто туристами, которым повезло уехать. Организм скажет спасибо. Или не скажет.", EnJ = "Crisps with stiffening ribs: engineers are proud, the dip holds. Left behind by tourists who were lucky enough to leave. Your body will thank you. Or not.", Rare = false },
        new Def { Id = "BugelzOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "Bugelz", Texture = "BugelzOriginal", Kg = 0.108f, Kcal = 520f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные рожки «Бьюгелз»", En = "Bugelz corn cones", RuF = "оригинальные", EnF = "original", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рожки, которые сначала надевают на пальцы, а потом уже едят. Иначе не считается. Механики заедали этим обед, не вытирая рук. На третьей горсти забываешь, что вокруг конец света.", EnJ = "Cones you first wear on your fingers and only then eat. Otherwise it doesn't count. Mechanics ate these for lunch without wiping their hands. By the third handful you forget the world has ended.", Rare = false },
        new Def { Id = "BugelzNacho", Kind = Kind.Snack, Shape = "bag", Mesh = "Bugelz", Texture = "BugelzNacho", Kg = 0.108f, Kcal = 520f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные рожки «Бьюгелз»", En = "Bugelz corn cones", RuF = "сыр начо", EnF = "nacho cheese", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рожки, которые сначала надевают на пальцы, а потом уже едят. Иначе не считается. Последнее на всю Одинокую топь. Скорее всего. Рыба подо льдом завидует.", EnJ = "Cones you first wear on your fingers and only then eat. Otherwise it doesn't count. The last one in all of Forlorn Muskeg. Most likely. The fish under the ice are jealous.", Rare = false },
        new Def { Id = "BugelzBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Bugelz", Texture = "BugelzBBQ", Kg = 0.108f, Kcal = 520f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные рожки «Бьюгелз»", En = "Bugelz corn cones", RuF = "барбекю", EnF = "barbecue", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рожки, которые сначала надевают на пальцы, а потом уже едят. Иначе не считается. Смотритель маяка грыз такое, ожидая кораблей. Олень от такого отказался бы. Олень не голодал.", EnJ = "Cones you first wear on your fingers and only then eat. Otherwise it doesn't count. The lighthouse keeper munched these while waiting for ships. A deer would turn it down. A deer has never starved.", Rare = false },
        new Def { Id = "BugelzWitch", Kind = Kind.Snack, Shape = "bag", Mesh = "Bugelz", Texture = "BugelzWitch", Kg = 0.108f, Kcal = 520f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные рожки «Бьюгелз»", En = "Bugelz corn cones", RuF = "ведьмины колпаки", EnF = "witch's hats", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Серия к Хэллоуину: редкость. Пугать тут и без неё есть кому. Полки рушились, а это уцелело. Соль есть, жир есть, совести нет.", EnJ = "A Halloween edition: a rarity. There is plenty to scare you here without it. Shelves collapsed and this survived. Salt: yes. Fat: yes. Conscience: none.", Rare = true },
        new Def { Id = "BugelzRanch", Kind = Kind.Snack, Shape = "bag", Mesh = "Bugelz", Texture = "BugelzRanch", Kg = 0.108f, Kcal = 520f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные рожки «Бьюгелз»", En = "Bugelz corn cones", RuF = "ранч", EnF = "ranch", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рожки, которые сначала надевают на пальцы, а потом уже едят. Иначе не считается. Смотритель заповедника называл это ужином. Ешьте до темноты: в темноте крошки не найти.", EnJ = "Cones you first wear on your fingers and only then eat. Otherwise it doesn't count. The park ranger called this dinner. Eat before dark: you cannot find crumbs in the dark.", Rare = false },
        new Def { Id = "BugelzHot", Kind = Kind.Snack, Shape = "bag", Mesh = "Bugelz", Texture = "BugelzHot", Kg = 0.108f, Kcal = 520f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные рожки «Бьюгелз»", En = "Bugelz corn cones", RuF = "острые буйвол", EnF = "hot buffalo", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Рожки, которые сначала надевают на пальцы, а потом уже едят. Иначе не считается. Такое слали посылками с материка. Адресаты выбыли. Лучшее, что случится с вами сегодня.", EnJ = "Cones you first wear on your fingers and only then eat. Otherwise it doesn't count. These came in parcels from the mainland. The addressees are gone. The best thing that will happen to you today.", Rare = false },
        new Def { Id = "BugelzCaramel", Kind = Kind.Snack, Shape = "bag", Mesh = "Bugelz", Texture = "BugelzCaramel", Kg = 0.108f, Kcal = 520f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные рожки «Бьюгелз»", En = "Bugelz corn cones", RuF = "карамель", EnF = "caramel", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SugarDry" }, RuJ = "Рожки, которые сначала надевают на пальцы, а потом уже едят. Иначе не считается. Иные держали это за лекарство. Тоже лечит. Для полного счастья не хватает только дивана.", EnJ = "Cones you first wear on your fingers and only then eat. Otherwise it doesn't count. Some people counted this as medicine. Also a cure. All that is missing for perfect happiness is a sofa.", Rare = false },
        new Def { Id = "BugelzSour", Kind = Kind.Snack, Shape = "bag", Mesh = "Bugelz", Texture = "BugelzSour", Kg = 0.108f, Kcal = 520f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные рожки «Бьюгелз»", En = "Bugelz corn cones", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рожки, которые сначала надевают на пальцы, а потом уже едят. Иначе не считается. В школьном рюкзаке такое не доживало до обеда. Вкус детства, если детство было так себе.", EnJ = "Cones you first wear on your fingers and only then eat. Otherwise it doesn't count. In a school bag this never lasted till lunch. The taste of childhood, if childhood was so-so.", Rare = false },
        new Def { Id = "BugelzPaprika", Kind = Kind.Snack, Shape = "bag", Mesh = "Bugelz", Texture = "BugelzPaprika", Kg = 0.108f, Kcal = 520f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные рожки «Бьюгелз»", En = "Bugelz corn cones", RuF = "паприка", EnF = "paprika", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рожки, которые сначала надевают на пальцы, а потом уже едят. Иначе не считается. Его обменяли бы на патрон, будь тут с кем меняться. Шуршит как надежда.", EnJ = "Cones you first wear on your fingers and only then eat. Otherwise it doesn't count. You could trade it for a cartridge, if there were anyone to trade with. It rustles like hope.", Rare = false },
        new Def { Id = "PlanterzSalted", Kind = Kind.Snack, Shape = "can", Mesh = "Planterz", Texture = "PlanterzSalted", Kg = 0.21f, Kcal = 1080f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Плантерз»", En = "Planterz nuts", RuF = "солёный арахис", EnF = "salted peanuts", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "Sinew" }, RuJ = "Арахис в монокле и цилиндре: самый воспитанный орех на полке. На вокзале это стоило втрое дороже. Теперь даром. Голод отступит, жажда придёт. Честный обмен.", EnJ = "A peanut in a monocle and top hat: the best-mannered nut on the shelf. At the station it cost three times as much. Now it is free. Hunger leaves, thirst arrives. A fair trade.", Rare = false },
        new Def { Id = "PlanterzHoney", Kind = Kind.Snack, Shape = "can", Mesh = "Planterz", Texture = "PlanterzHoney", Kg = 0.21f, Kcal = 1080f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Плантерз»", En = "Planterz nuts", RuF = "арахис в меду", EnF = "honey roasted", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SugarDry" }, RuJ = "Арахис в монокле и цилиндре: самый воспитанный орех на полке. Пережило толчок и даже не помялось. Не согреет, зато отвлечёт.", EnJ = "A peanut in a monocle and top hat: the best-mannered nut on the shelf. It came through the quake without a dent. It will not warm you, but it will distract you.", Rare = false },
        new Def { Id = "PlanterzDry", Kind = Kind.Snack, Shape = "can", Mesh = "Planterz", Texture = "PlanterzDry", Kg = 0.21f, Kcal = 1080f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Плантерз»", En = "Planterz nuts", RuF = "сухой обжарки", EnF = "dry roasted", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "Sinew" }, RuJ = "Арахис в монокле и цилиндре: самый воспитанный орех на полке. Китобои такого не ели, но оценили бы. Пума предпочитает мясо. Вам повезло.", EnJ = "A peanut in a monocle and top hat: the best-mannered nut on the shelf. The whalers never ate this, but they would have approved. The cougar prefers meat. Lucky you.", Rare = false },
        new Def { Id = "PlanterzCashew", Kind = Kind.Snack, Shape = "can", Mesh = "Planterz", Texture = "PlanterzCashew", Kg = 0.21f, Kcal = 1080f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Плантерз»", En = "Planterz nuts", RuF = "кешью", EnF = "cashews", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "Sinew" }, RuJ = "Арахис в монокле и цилиндре: самый воспитанный орех на полке. Осталось после чьего-то дня рождения. Гости не пришли. Сначала попробуйте одну штучку. Шутка: ешьте всё.", EnJ = "A peanut in a monocle and top hat: the best-mannered nut on the shelf. Left over from someone's birthday. The guests never came. Try just one first. Joke: eat the lot.", Rare = false },
        new Def { Id = "PlanterzChili", Kind = Kind.Snack, Shape = "can", Mesh = "Planterz", Texture = "PlanterzChili", Kg = 0.21f, Kcal = 1080f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Плантерз»", En = "Planterz nuts", RuF = "чили и лайм", EnF = "chilli lime", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Арахис в монокле и цилиндре: самый воспитанный орех на полке. Мерзлота хранит лучше любого холодильника. Такой ужин не стыдно записать в дневник.", EnJ = "A peanut in a monocle and top hat: the best-mannered nut on the shelf. Permafrost keeps things better than any fridge. A dinner worth writing in the journal.", Rare = false },
        new Def { Id = "PlanterzSmoked", Kind = Kind.Snack, Shape = "can", Mesh = "Planterz", Texture = "PlanterzSmoked", Kg = 0.21f, Kcal = 1080f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Плантерз»", En = "Planterz nuts", RuF = "копчёный", EnF = "smoked", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "Sinew" }, RuJ = "Арахис в монокле и цилиндре: самый воспитанный орех на полке. Такое добывали из автомата, который съедал последнюю монету. Силы прибавит на один сугроб.", EnJ = "A peanut in a monocle and top hat: the best-mannered nut on the shelf. These came from the vending machine that ate your last coin. It will carry you one snowdrift further.", Rare = false },
        new Def { Id = "PlanterzUnsalted", Kind = Kind.Snack, Shape = "can", Mesh = "Planterz", Texture = "PlanterzUnsalted", Kg = 0.21f, Kcal = 1080f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Плантерз»", En = "Planterz nuts", RuF = "без соли", EnF = "unsalted", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "Sinew" }, RuJ = "Арахис в монокле и цилиндре: самый воспитанный орех на полке. Такое брали в лодку под брезент, на весь день. Идеально к закату, которого не видно за бураном.", EnJ = "A peanut in a monocle and top hat: the best-mannered nut on the shelf. People took these out in the boat under the tarpaulin, for the whole day. Perfect with a sunset you cannot see for the storm.", Rare = false },
        new Def { Id = "PlanterzCocktail", Kind = Kind.Snack, Shape = "can", Mesh = "Planterz", Texture = "PlanterzCocktail", Kg = 0.21f, Kcal = 1080f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Плантерз»", En = "Planterz nuts", RuF = "коктейльный", EnF = "cocktail peanuts", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "Sinew" }, RuJ = "Арахис в монокле и цилиндре: самый воспитанный орех на полке. С ним кто-то шёл к перевалу и не дошёл. Пахнет магазином. Помните магазины?", EnJ = "A peanut in a monocle and top hat: the best-mannered nut on the shelf. Someone carried it towards the pass and never arrived. It smells of a shop. Remember shops?", Rare = false },
        new Def { Id = "PlanterzSweet", Kind = Kind.Snack, Shape = "can", Mesh = "Planterz", Texture = "PlanterzSweet", Kg = 0.21f, Kcal = 1080f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Плантерз»", En = "Planterz nuts", RuF = "сладко-солёный", EnF = "sweet & salty", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "Sinew" }, RuJ = "Арахис в монокле и цилиндре: самый воспитанный орех на полке. С таким сидели у окна с видом на метель. Мороз не испортил, время не взяло.", EnJ = "A peanut in a monocle and top hat: the best-mannered nut on the shelf. People sat with these at a window with a view of the blizzard. Frost did not spoil it and time could not take it.", Rare = false },
        new Def { Id = "TukOriginal", Kind = Kind.Snack, Shape = "carton", Mesh = "Tuk", Texture = "TukOriginal", Kg = 0.108f, Kcal = 480f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Тук»", En = "Tuk crackers", RuF = "оригинальные", EnF = "original", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крекер, который стучится сам: тук-тук, кто там, это соль. Уцелело там, где сгорело всё остальное. В рюкзаке не мнётся. Почти.", EnJ = "A cracker that knocks by itself: knock-knock, who's there, salt. It survived where everything else burned. It does not get crushed in a pack. Almost.", Rare = false },
        new Def { Id = "TukCheese", Kind = Kind.Snack, Shape = "carton", Mesh = "Tuk", Texture = "TukCheese", Kg = 0.108f, Kcal = 480f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Тук»", En = "Tuk crackers", RuF = "сыр", EnF = "cheese", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крекер, который стучится сам: тук-тук, кто там, это соль. Этим кормили сторожевого пса. Пёс ушёл в волки. Съешьте сейчас: завтра может не быть аппетита.", EnJ = "A cracker that knocks by itself: knock-knock, who's there, salt. They fed the guard dog with this. The dog joined the wolves. Eat it now: tomorrow you may have no appetite.", Rare = false },
        new Def { Id = "TukPaprika", Kind = Kind.Snack, Shape = "carton", Mesh = "Tuk", Texture = "TukPaprika", Kg = 0.108f, Kcal = 480f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Тук»", En = "Tuk crackers", RuF = "паприка", EnF = "paprika", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крекер, который стучится сам: тук-тук, кто там, это соль. Из запасов лесорубов: брали ящиками. Хватит дойти до следующей хижины и пожалеть, что кончилось.", EnJ = "A cracker that knocks by itself: knock-knock, who's there, salt. From the loggers' stores: they bought it by the crate. Enough to reach the next cabin and regret it is gone.", Rare = false },
        new Def { Id = "TukBacon", Kind = Kind.Snack, Shape = "carton", Mesh = "Tuk", Texture = "TukBacon", Kg = 0.108f, Kcal = 480f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Тук»", En = "Tuk crackers", RuF = "бекон", EnF = "bacon", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крекер, который стучится сам: тук-тук, кто там, это соль. В пост такое не ели. Пост кончился вместе с миром. От такого не толстеют те, кто ходит по двадцать километров.", EnJ = "A cracker that knocks by itself: knock-knock, who's there, salt. Nobody ate these during a fast. The fast ended with the world. Nobody who walks twenty kilometres a day gets fat on this.", Rare = false },
        new Def { Id = "TukOnion", Kind = Kind.Snack, Shape = "carton", Mesh = "Tuk", Texture = "TukOnion", Kg = 0.108f, Kcal = 480f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Тук»", En = "Tuk crackers", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крекер, который стучится сам: тук-тук, кто там, это соль. Теперь это ценнее денег. Деньги оставьте. Волчья стая не в курсе. Пусть так и будет.", EnJ = "A cracker that knocks by itself: knock-knock, who's there, salt. It is worth more than money now. Leave the money. The wolf pack does not know. Keep it that way.", Rare = false },
        new Def { Id = "TukPizza", Kind = Kind.Snack, Shape = "carton", Mesh = "Tuk", Texture = "TukPizza", Kg = 0.108f, Kcal = 480f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Тук»", En = "Tuk crackers", RuF = "пицца", EnF = "pizza", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крекер, который стучится сам: тук-тук, кто там, это соль. Его несли на пикник. Пикник отменили навсегда. Хрустеть в засаде не рекомендуется.", EnJ = "A cracker that knocks by itself: knock-knock, who's there, salt. It was headed for a picnic. The picnic is cancelled forever. Crunching in an ambush is not recommended.", Rare = false },
        new Def { Id = "TukRosemary", Kind = Kind.Snack, Shape = "carton", Mesh = "Tuk", Texture = "TukRosemary", Kg = 0.108f, Kcal = 480f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Тук»", En = "Tuk crackers", RuF = "розмарин и оливки", EnF = "rosemary & olive", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крекер, который стучится сам: тук-тук, кто там, это соль. Такое стояло у кассы на случай слабости. Лекарство от тоски, отпускается без рецепта.", EnJ = "A cracker that knocks by itself: knock-knock, who's there, salt. These stood by the till for moments of weakness. A cure for the blues, no prescription needed.", Rare = false },
        new Def { Id = "TukPepper", Kind = Kind.Snack, Shape = "carton", Mesh = "Tuk", Texture = "TukPepper", Kg = 0.108f, Kcal = 480f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Тук»", En = "Tuk crackers", RuF = "чёрный перец", EnF = "black pepper", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крекер, который стучится сам: тук-тук, кто там, это соль. Досталось вам, потому что вы дошли первым. Жуйте и думайте о хорошем. Например, о добавке.", EnJ = "A cracker that knocks by itself: knock-knock, who's there, salt. It is yours because you got here first. Chew and think of nice things. Seconds, for example.", Rare = false },
        new Def { Id = "RitzyOriginal", Kind = Kind.Snack, Shape = "carton", Mesh = "Ritzy", Texture = "RitzyOriginal", Kg = 0.208f, Kcal = 960f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Ритци»", En = "Ritzy crackers", RuF = "оригинальные", EnF = "original", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Круглый крекер для приёмов: сверху кладут сыр, сверху сыра кладут надежды. Упаковка выцвела, внутри время остановилось. К утру от него останется только запах на варежках.", EnJ = "A round cracker for receptions: cheese goes on top, hopes go on top of the cheese. The wrapper has faded; inside, time stood still. By morning only the smell on your mittens will be left.", Rare = false },
        new Def { Id = "RitzyCheese", Kind = Kind.Snack, Shape = "carton", Mesh = "Ritzy", Texture = "RitzyCheese", Kg = 0.208f, Kcal = 960f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Ритци»", En = "Ritzy crackers", RuF = "сыр", EnF = "cheese", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Круглый крекер для приёмов: сверху кладут сыр, сверху сыра кладут надежды. Из чемодана пассажира, который не долетел. Тишина вокруг такая, что слышно, как вы жуёте.", EnJ = "A round cracker for receptions: cheese goes on top, hopes go on top of the cheese. From the suitcase of a passenger who never landed. It is so quiet you can hear yourself chew.", Rare = false },
        new Def { Id = "RitzyWheat", Kind = Kind.Snack, Shape = "carton", Mesh = "Ritzy", Texture = "RitzyWheat", Kg = 0.208f, Kcal = 960f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Ритци»", En = "Ritzy crackers", RuF = "цельнозерновые", EnF = "whole wheat", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Круглый крекер для приёмов: сверху кладут сыр, сверху сыра кладут надежды. Перезимовало и ничуть не обиделось. Не делите на завтра: завтра будет новый голод.", EnJ = "A round cracker for receptions: cheese goes on top, hopes go on top of the cheese. It made it through the winter and bears no grudge. Do not save half for tomorrow: tomorrow brings its own hunger.", Rare = false },
        new Def { Id = "RitzyGarlic", Kind = Kind.Snack, Shape = "carton", Mesh = "Ritzy", Texture = "RitzyGarlic", Kg = 0.208f, Kcal = 960f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Ритци»", En = "Ritzy crackers", RuF = "чесночное масло", EnF = "garlic butter", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Круглый крекер для приёмов: сверху кладут сыр, сверху сыра кладут надежды. Запасливая хозяйка купила по акции шесть штук. Сосны вокруг делают вид, что не смотрят.", EnJ = "A round cracker for receptions: cheese goes on top, hopes go on top of the cheese. A thrifty housewife bought six of these on offer. The pines around pretend not to watch.", Rare = false },
        new Def { Id = "RitzyBacon", Kind = Kind.Snack, Shape = "carton", Mesh = "Ritzy", Texture = "RitzyBacon", Kg = 0.208f, Kcal = 960f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Ритци»", En = "Ritzy crackers", RuF = "бекон", EnF = "bacon", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Круглый крекер для приёмов: сверху кладут сыр, сверху сыра кладут надежды. Кто-то написал на упаковке «моё». Уже нет. Калории мелкие, зато свои.", EnJ = "A round cracker for receptions: cheese goes on top, hopes go on top of the cheese. Someone wrote 'mine' on it. Not any more. Small calories, but your own.", Rare = false },
        new Def { Id = "RitzyVegetable", Kind = Kind.Snack, Shape = "carton", Mesh = "Ritzy", Texture = "RitzyVegetable", Kg = 0.208f, Kcal = 960f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Ритци»", En = "Ritzy crackers", RuF = "овощные", EnF = "vegetable", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Круглый крекер для приёмов: сверху кладут сыр, сверху сыра кладут надежды. В консервном цеху это ели тайком от мастера. После этого даже крапивный чай покажется десертом.", EnJ = "A round cracker for receptions: cheese goes on top, hopes go on top of the cheese. At the cannery they ate this behind the foreman's back. After this even nettle tea feels like dessert.", Rare = false },
        new Def { Id = "RitzyHoney", Kind = Kind.Snack, Shape = "carton", Mesh = "Ritzy", Texture = "RitzyHoney", Kg = 0.208f, Kcal = 960f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Ритци»", En = "Ritzy crackers", RuF = "медовая пшеница", EnF = "honey wheat", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SugarDry" }, RuJ = "Круглый крекер для приёмов: сверху кладут сыр, сверху сыра кладут надежды. Его не взяли даже мародёры. Они спешили. Нашедшему полагается всё.", EnJ = "A round cracker for receptions: cheese goes on top, hopes go on top of the cheese. Even the looters left it. They were in a hurry. Finders keepers, all of it.", Rare = false },
        new Def { Id = "RitzyEverything", Kind = Kind.Snack, Shape = "carton", Mesh = "Ritzy", Texture = "RitzyEverything", Kg = 0.208f, Kcal = 960f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Ритци»", En = "Ritzy crackers", RuF = "со всеми семечками", EnF = "everything seeds", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Круглый крекер для приёмов: сверху кладут сыр, сверху сыра кладут надежды. Провело зиму на острове, как и вы. Зубы целы? Тогда вперёд.", EnJ = "A round cracker for receptions: cheese goes on top, hopes go on top of the cheese. It spent the winter on the island, same as you. Teeth intact? Then go ahead.", Rare = false },
        new Def { Id = "OldDatchKetchup", Kind = Kind.Snack, Shape = "carton", Mesh = "OldDatch", Texture = "OldDatchKetchup", Kg = 0.228f, Kcal = 1180f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Олд Датч»", En = "Old Datch crisps", RuF = "кетчуп", EnF = "ketchup", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Канадская коробка с мельницей: внутри два пакета, чтобы врать себе, что второй на завтра. Дети прятали такое под кроватью, в тайнике. Ночью приснится добавка.", EnJ = "A Canadian box with a windmill: two bags inside, so you can lie that the second is for tomorrow. Children hid these under the bed, in a secret place. Tonight you will dream of seconds.", Rare = false },
        new Def { Id = "OldDatchDressed", Kind = Kind.Snack, Shape = "carton", Mesh = "OldDatch", Texture = "OldDatchDressed", Kg = 0.228f, Kcal = 1180f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Олд Датч»", En = "Old Datch crisps", RuF = "со всеми приправами", EnF = "all dressed", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Канадская коробка с мельницей: внутри два пакета, чтобы врать себе, что второй на завтра. Осталось от геологов вместе с картой и долгами. С таким запасом можно пережить ещё один вечер.", EnJ = "A Canadian box with a windmill: two bags inside, so you can lie that the second is for tomorrow. Left by the geologists along with a map and some debts. With supplies like this you can survive one more evening.", Rare = false },
        new Def { Id = "OldDatchDill", Kind = Kind.Snack, Shape = "carton", Mesh = "OldDatch", Texture = "OldDatchDill", Kg = 0.228f, Kcal = 1180f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Олд Датч»", En = "Old Datch crisps", RuF = "маринованный огурец", EnF = "dill pickle", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Канадская коробка с мельницей: внутри два пакета, чтобы врать себе, что второй на завтра. На острове такое было праздником и до катастрофы. Пёс бы выпросил половину. Пса нет.", EnJ = "A Canadian box with a windmill: two bags inside, so you can lie that the second is for tomorrow. On the island this was a treat even before the disaster. A dog would beg half of it. There is no dog.", Rare = false },
        new Def { Id = "OldDatchVinegar", Kind = Kind.Snack, Shape = "carton", Mesh = "OldDatch", Texture = "OldDatchVinegar", Kg = 0.228f, Kcal = 1180f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Олд Датч»", En = "Old Datch crisps", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Канадская коробка с мельницей: внутри два пакета, чтобы врать себе, что второй на завтра. С таким слушали радио, которое теперь ловит только треск. Съедено будет быстрее, чем найдено.", EnJ = "A Canadian box with a windmill: two bags inside, so you can lie that the second is for tomorrow. People ate these by the radio, which picks up nothing but crackle now. It will be eaten faster than it was found.", Rare = false },
        new Def { Id = "OldDatchRipple", Kind = Kind.Snack, Shape = "carton", Mesh = "OldDatch", Texture = "OldDatchRipple", Kg = 0.228f, Kcal = 1180f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Олд Датч»", En = "Old Datch crisps", RuF = "рифлёные с солью", EnF = "ripple salted", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Канадская коробка с мельницей: внутри два пакета, чтобы врать себе, что второй на завтра. Крысы прогрызли соседнюю, эту пощадили. На вкус как выходной.", EnJ = "A Canadian box with a windmill: two bags inside, so you can lie that the second is for tomorrow. The rats gnawed through the one next to it and spared this. It tastes like a day off.", Rare = false },
        new Def { Id = "OldDatchMaple", Kind = Kind.Snack, Shape = "carton", Mesh = "OldDatch", Texture = "OldDatchMaple", Kg = 0.228f, Kcal = 1180f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Олд Датч»", En = "Old Datch crisps", RuF = "кленовый бекон", EnF = "maple bacon", RuC = "Канада", EnC = "Canada", Fx = new[] { "SugarDry" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Бывший хозяин клялся бросить. Не успел. Ветер унесёт запах прямо к берлоге. Ешьте быстрее.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. The former owner swore to give these up. He ran out of time. The wind carries the smell straight to the den. Eat faster.", Rare = true },
        new Def { Id = "OldDatchTurkey", Kind = Kind.Snack, Shape = "carton", Mesh = "OldDatch", Texture = "OldDatchTurkey", Kg = 0.228f, Kcal = 1180f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Олд Датч»", En = "Old Datch crisps", RuF = "индейка с клюквой", EnF = "turkey & cranberry", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Его катали в кабине трактора три сезона. Пополняет запас соли и веры в человечество.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. It rode around in a tractor cab for three seasons. Restores your salt and your faith in mankind.", Rare = true },
        new Def { Id = "OldDatchBBQ", Kind = Kind.Snack, Shape = "carton", Mesh = "OldDatch", Texture = "OldDatchBBQ", Kg = 0.228f, Kcal = 1180f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Олд Датч»", En = "Old Datch crisps", RuF = "барбекю", EnF = "barbecue", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Канадская коробка с мельницей: внутри два пакета, чтобы врать себе, что второй на завтра. После бани такое шло лучше всего. Хорошо идёт под треск поленьев.", EnJ = "A Canadian box with a windmill: two bags inside, so you can lie that the second is for tomorrow. Nothing went down better after the sauna. Goes down well with crackling logs.", Rare = false },
        new Def { Id = "OldDatchOnion", Kind = Kind.Snack, Shape = "carton", Mesh = "OldDatch", Texture = "OldDatchOnion", Kg = 0.228f, Kcal = 1180f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Олд Датч»", En = "Old Datch crisps", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Канадская коробка с мельницей: внутри два пакета, чтобы врать себе, что второй на завтра. В тюрьме на это выменивали что угодно. Руки вытирать о штаны: салфеток не завезли.", EnJ = "A Canadian box with a windmill: two bags inside, so you can lie that the second is for tomorrow. In the prison you could trade one of these for anything. Wipe your hands on your trousers: no napkins were delivered.", Rare = false },
        new Def { Id = "OldDatchOriginal", Kind = Kind.Snack, Shape = "carton", Mesh = "OldDatch", Texture = "OldDatchOriginal", Kg = 0.228f, Kcal = 1180f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Олд Датч»", En = "Old Datch crisps", RuF = "оригинальные", EnF = "original", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Канадская коробка с мельницей: внутри два пакета, чтобы врать себе, что второй на завтра. Кто-то менял это на сигареты. Сделка сорвалась. Маленькая радость размером с ладонь.", EnJ = "A Canadian box with a windmill: two bags inside, so you can lie that the second is for tomorrow. Someone was trading this for cigarettes. The deal fell through. A small joy the size of your palm.", Rare = false },
        new Def { Id = "OldDatchCheddar", Kind = Kind.Snack, Shape = "carton", Mesh = "OldDatch", Texture = "OldDatchCheddar", Kg = 0.228f, Kcal = 1180f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Олд Датч»", En = "Old Datch crisps", RuF = "чеддер и сметана", EnF = "cheddar & sour cream", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Канадская коробка с мельницей: внутри два пакета, чтобы врать себе, что второй на завтра. С ним зимовали на метеостанции, пока было с кем. Совесть молчит, живот поёт.", EnJ = "A Canadian box with a windmill: two bags inside, so you can lie that the second is for tomorrow. They wintered with it at the weather station, while there was a 'they'. Conscience is silent, the belly sings.", Rare = false },
        new Def { Id = "OldDatchJalapeno", Kind = Kind.Snack, Shape = "carton", Mesh = "OldDatch", Texture = "OldDatchJalapeno", Kg = 0.228f, Kcal = 1180f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Олд Датч»", En = "Old Datch crisps", RuF = "халапеньо и чеддер", EnF = "jalapeno & cheddar", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Канадская коробка с мельницей: внутри два пакета, чтобы врать себе, что второй на завтра. Такое терялось в кладовке среди крупы и надежд. Проверено поколениями и одной катастрофой.", EnJ = "A Canadian box with a windmill: two bags inside, so you can lie that the second is for tomorrow. These got lost in the pantry among the grain and the hopes. Tested by generations and one catastrophe.", Rare = false },
        new Def { Id = "OldDatchPoutine", Kind = Kind.Snack, Shape = "carton", Mesh = "OldDatch", Texture = "OldDatchPoutine", Kg = 0.228f, Kcal = 1180f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Олд Датч»", En = "Old Datch crisps", RuF = "путин с подливкой", EnF = "poutine", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Канадская коробка с мельницей: внутри два пакета, чтобы врать себе, что второй на завтра. Его берегли к приезду внуков. Оставьте пару штук на перевал. Не оставите.", EnJ = "A Canadian box with a windmill: two bags inside, so you can lie that the second is for tomorrow. It was being saved for the grandchildren's visit. Save a couple for the pass. You will not.", Rare = false },
        new Def { Id = "HokinzOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "Hokinz", Texture = "HokinzOriginal", Kg = 0.218f, Kcal = 1160f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Хокинз Чизиз»", En = "Hokinz Cheezies corn puffs", RuF = "чеддер", EnF = "cheddar", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Кривые сырные палочки из Онтарио: ни одна не похожа на другую, как снежинки. В баре такое ставили на стойку, бесплатно к пиву. Пива нет. Здесь это считается ужином при свечах.", EnJ = "Crooked cheese sticks from Ontario: no two alike, just like snowflakes. Bars put these out free with a beer. There is no beer. Round here this counts as a candlelit dinner.", Rare = false },
        new Def { Id = "HokinzJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "Hokinz", Texture = "HokinzJalapeno", Kg = 0.218f, Kcal = 1160f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Хокинз Чизиз»", En = "Hokinz Cheezies corn puffs", RuF = "халапеньо", EnF = "jalapeno", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Кривые сырные палочки из Онтарио: ни одна не похожа на другую, как снежинки. Такое лежало в каждом доме, пока не погас свет. Луна светит, еда хрустит, жизнь налаживается.", EnJ = "Crooked cheese sticks from Ontario: no two alike, just like snowflakes. Every house had one of these until the lights went out. The moon shines, the food crunches, life is looking up.", Rare = false },
        new Def { Id = "HokinzWhite", Kind = Kind.Snack, Shape = "bag", Mesh = "Hokinz", Texture = "HokinzWhite", Kg = 0.218f, Kcal = 1160f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Хокинз Чизиз»", En = "Hokinz Cheezies corn puffs", RuF = "белый чеддер", EnF = "white cheddar", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Кривые сырные палочки из Онтарио: ни одна не похожа на другую, как снежинки. Кто-то берёг это на чёрный день. Он настал. Снег вокруг не солёный. Это солёное.", EnJ = "Crooked cheese sticks from Ontario: no two alike, just like snowflakes. Someone saved this for a rainy day. It came. The snow around is not salty. This is.", Rare = false },
        new Def { Id = "HokinzHot", Kind = Kind.Snack, Shape = "bag", Mesh = "Hokinz", Texture = "HokinzHot", Kg = 0.218f, Kcal = 1160f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Хокинз Чизиз»", En = "Hokinz Cheezies corn puffs", RuF = "острые", EnF = "hot cheddar", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Кривые сырные палочки из Онтарио: ни одна не похожа на другую, как снежинки. Пережило хозяина, кота и две зимы. Больше таких не делают. Совсем.", EnJ = "Crooked cheese sticks from Ontario: no two alike, just like snowflakes. It outlived its owner, the cat and two winters. They do not make these any more. At all.", Rare = false },
        new Def { Id = "HokinzBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Hokinz", Texture = "HokinzBacon", Kg = 0.218f, Kcal = 1160f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Хокинз Чизиз»", En = "Hokinz Cheezies corn puffs", RuF = "бекон и чеддер", EnF = "bacon cheddar", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Кривые сырные палочки из Онтарио: ни одна не похожа на другую, как снежинки. Такое обычно находили за диваном, как всё лучшее в жизни. Открывайте тихо: у волков отличный слух.", EnJ = "Crooked cheese sticks from Ontario: no two alike, just like snowflakes. These were usually found behind the sofa, like all the best things in life. Open it quietly: wolves have excellent hearing.", Rare = false },
        new Def { Id = "HokinzSmoked", Kind = Kind.Snack, Shape = "bag", Mesh = "Hokinz", Texture = "HokinzSmoked", Kg = 0.218f, Kcal = 1160f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Хокинз Чизиз»", En = "Hokinz Cheezies corn puffs", RuF = "копчёный чеддер", EnF = "smoked cheddar", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Кривые сырные палочки из Онтарио: ни одна не похожа на другую, как снежинки. Последний завоз был до того, как упали самолёты. Одной не обойдётся, но вторая неизвестно где.", EnJ = "Crooked cheese sticks from Ontario: no two alike, just like snowflakes. The last delivery came before the planes fell. One won't be enough, and nobody knows where the second is.", Rare = false },
        new Def { Id = "MissVikiSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "MissViki", Texture = "MissVikiSalt", Kg = 0.208f, Kcal = 1070f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Мисс Вики»", En = "Miss Viki’s crisps", RuF = "морская соль", EnF = "sea salt", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Мисс Вики жарит в котле, поэтому хрустят так, что слышно в соседней провинции. Ценник оторван: теперь это бесценно. Крошки с пола тоже считаются.", EnJ = "Miss Viki kettle-cooks them, so the crunch is heard one province over. The price tag is torn off: it is priceless now. The crumbs on the floor count too.", Rare = false },
        new Def { Id = "MissVikiJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "MissViki", Texture = "MissVikiJalapeno", Kg = 0.208f, Kcal = 1070f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Мисс Вики»", En = "Miss Viki’s crisps", RuF = "халапеньо", EnF = "jalapeno", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Мисс Вики жарит в котле, поэтому хрустят так, что слышно в соседней провинции. Дата на шве стёрлась, и слава богу. Запейте чаем из шиповника и считайте это обедом.", EnJ = "Miss Viki kettle-cooks them, so the crunch is heard one province over. The date on the seam has rubbed off, thank goodness. Wash it down with rosehip tea and call it lunch.", Rare = false },
        new Def { Id = "MissVikiChili", Kind = Kind.Snack, Shape = "bag", Mesh = "MissViki", Texture = "MissVikiChili", Kg = 0.208f, Kcal = 1070f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Мисс Вики»", En = "Miss Viki’s crisps", RuF = "сладкий чили и сметана", EnF = "sweet chili & sour cream", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Мисс Вики жарит в котле, поэтому хрустят так, что слышно в соседней провинции. Пахнет заправкой у Прибрежного шоссе. Медведю не показывать: отнимет вместе с рукой.", EnJ = "Miss Viki kettle-cooks them, so the crunch is heard one province over. It smells of the petrol station on the Coastal Highway. Do not show the bear: he will take it, hand and all.", Rare = false },
        new Def { Id = "MissVikiMalt", Kind = Kind.Snack, Shape = "bag", Mesh = "MissViki", Texture = "MissVikiMalt", Kg = 0.208f, Kcal = 1070f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Мисс Вики»", En = "Miss Viki’s crisps", RuF = "соль и солодовый уксус", EnF = "sea salt & malt vinegar", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Мисс Вики жарит в котле, поэтому хрустят так, что слышно в соседней провинции. Такое возили в бардачке на дальнюю дорогу. Дороги кончились. Диетолог не одобрил бы. Диетолога тут нет.", EnJ = "Miss Viki kettle-cooks them, so the crunch is heard one province over. People kept these in the glovebox for long drives. The drives are over. A dietitian would not approve. There is no dietitian here.", Rare = false },
        new Def { Id = "MissVikiApple", Kind = Kind.Snack, Shape = "bag", Mesh = "MissViki", Texture = "MissVikiApple", Kg = 0.208f, Kcal = 1070f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Мисс Вики»", En = "Miss Viki’s crisps", RuF = "яблоко и чеддер нового урожая", EnF = "harvest apple cheddar", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Мыши не тронули. Думайте сами. Лучше, чем кора. Проверено.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. The mice left it alone. Draw your own conclusions. Better than bark. Tested.", Rare = true },
        new Def { Id = "MissVikiMaple", Kind = Kind.Snack, Shape = "bag", Mesh = "MissViki", Texture = "MissVikiMaple", Kg = 0.208f, Kcal = 1070f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Мисс Вики»", En = "Miss Viki’s crisps", RuF = "кленовый сироп с перцем", EnF = "maple & pepper", RuC = "Канада", EnC = "Canada", Fx = new[] { "SugarDry" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Рыбаки брали такое на лёд вместо обеда. После тушёнки из банки это почти ресторан.", EnJ = "A spring edition: a rare pack from the days when spring still came. Fishermen took this onto the ice instead of lunch. After stew from a tin this is nearly a restaurant.", Rare = true },
        new Def { Id = "MissVikiBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "MissViki", Texture = "MissVikiBBQ", Kg = 0.208f, Kcal = 1070f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Мисс Вики»", En = "Miss Viki’s crisps", RuF = "копчёный барбекю", EnF = "smokehouse barbecue", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Мисс Вики жарит в котле, поэтому хрустят так, что слышно в соседней провинции. Смотритель плотины держал такое в заначке. Ешьте медленно: когда ещё такое найдёте.", EnJ = "Miss Viki kettle-cooks them, so the crunch is heard one province over. The dam keeper kept a stash of these. Eat slowly: who knows when you will find another.", Rare = false },
        new Def { Id = "MissVikiUnsalted", Kind = Kind.Snack, Shape = "bag", Mesh = "MissViki", Texture = "MissVikiUnsalted", Kg = 0.208f, Kcal = 1070f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Мисс Вики»", En = "Miss Viki’s crisps", RuF = "без соли", EnF = "unsalted", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Мисс Вики жарит в котле, поэтому хрустят так, что слышно в соседней провинции. Кто-то спрятал это от детей. Дети не нашли. К этому просится пиво, а есть только талый снег.", EnJ = "Miss Viki kettle-cooks them, so the crunch is heard one province over. Someone hid it from the kids. The kids never found it. It begs for a beer, and there is only melted snow.", Rare = false },
        new Def { Id = "MissVikiPepper", Kind = Kind.Snack, Shape = "bag", Mesh = "MissViki", Texture = "MissVikiPepper", Kg = 0.208f, Kcal = 1070f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Мисс Вики»", En = "Miss Viki’s crisps", RuF = "соль и чёрный перец", EnF = "salt & cracked pepper", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Мисс Вики жарит в котле, поэтому хрустят так, что слышно в соседней провинции. В сельском магазине такое вечно заваливалось за прилавок. Сияние на вкус не влияет. Наверное.", EnJ = "Miss Viki kettle-cooks them, so the crunch is heard one province over. In the village shop these kept slipping behind the counter. The aurora does not affect the taste. Probably.", Rare = false },
        new Def { Id = "MissVikiDill", Kind = Kind.Snack, Shape = "bag", Mesh = "MissViki", Texture = "MissVikiDill", Kg = 0.208f, Kcal = 1070f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Мисс Вики»", En = "Miss Viki’s crisps", RuF = "укропный огурчик", EnF = "spicy dill pickle", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Мисс Вики жарит в котле, поэтому хрустят так, что слышно в соседней провинции. Ждало покупателя дольше, чем тот прожил. После тушёнки из банки это почти ресторан.", EnJ = "Miss Viki kettle-cooks them, so the crunch is heard one province over. It waited for a buyer longer than the buyer lived. After stew from a tin this is nearly a restaurant.", Rare = false },
        new Def { Id = "MissVikiOnion", Kind = Kind.Snack, Shape = "bag", Mesh = "MissViki", Texture = "MissVikiOnion", Kg = 0.208f, Kcal = 1070f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Мисс Вики»", En = "Miss Viki’s crisps", RuF = "карамелизованный лук", EnF = "caramelised onion", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Мисс Вики жарит в котле, поэтому хрустят так, что слышно в соседней провинции. С материка такое больше не привезут. Делиться не с кем, и это впервые радует.", EnJ = "Miss Viki kettle-cooks them, so the crunch is heard one province over. Nobody will bring this from the mainland again. Nobody to share with, and for once that is good news.", Rare = false },
        new Def { Id = "HikoriOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "Hikori", Texture = "HikoriOriginal", Kg = 0.158f, Kcal = 810f, Thirst = -8f, Eat = 4f, Ru = "Картофельная соломка «Хикори Стикс»", En = "Hikori Stiks potato sticks", RuF = "с дымком", EnF = "hickory smoke", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Копчёная картофельная соломка: пахнет костром, который за тебя уже кто-то развёл. На упаковке иней, внутри всё по-прежнему. Пальцы потом оближите: зимой калории не выбрасывают.", EnJ = "Smoked potato sticks: they smell of a campfire someone has already lit for you. Frost on the wrapper, business as usual inside. Lick your fingers after: in winter you do not waste calories.", Rare = false },
        new Def { Id = "HikoriBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Hikori", Texture = "HikoriBBQ", Kg = 0.158f, Kcal = 810f, Thirst = -8f, Eat = 4f, Ru = "Картофельная соломка «Хикори Стикс»", En = "Hikori Stiks potato sticks", RuF = "барбекю", EnF = "barbecue", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Копчёная картофельная соломка: пахнет костром, который за тебя уже кто-то развёл. Мороз ему нипочём: твёрже не стало, мягче тоже. Ворон на ветке уже ждёт свою долю.", EnJ = "Smoked potato sticks: they smell of a campfire someone has already lit for you. The frost did nothing to it: no harder, no softer. The crow on the branch is already waiting for its share.", Rare = false },
        new Def { Id = "HikoriCheddar", Kind = Kind.Snack, Shape = "bag", Mesh = "Hikori", Texture = "HikoriCheddar", Kg = 0.158f, Kcal = 810f, Thirst = -8f, Eat = 4f, Ru = "Картофельная соломка «Хикори Стикс»", En = "Hikori Stiks potato sticks", RuF = "чеддер", EnF = "cheddar", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Копчёная картофельная соломка: пахнет костром, который за тебя уже кто-то развёл. Из тех времён, когда еду выбирали по вкусу. На морозе хрустит вдвое громче.", EnJ = "Smoked potato sticks: they smell of a campfire someone has already lit for you. From the days when people picked food for its taste. In the frost it crunches twice as loud.", Rare = false },
        new Def { Id = "HikoriKetchup", Kind = Kind.Snack, Shape = "bag", Mesh = "Hikori", Texture = "HikoriKetchup", Kg = 0.158f, Kcal = 810f, Thirst = -8f, Eat = 4f, Ru = "Картофельная соломка «Хикори Стикс»", En = "Hikori Stiks potato sticks", RuF = "кетчуп", EnF = "ketchup", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Копчёная картофельная соломка: пахнет костром, который за тебя уже кто-то развёл. Чей-то перекус на ночную смену, которая не кончилась. Не еда, а настроение. Настроение тоже греет.", EnJ = "Smoked potato sticks: they smell of a campfire someone has already lit for you. Someone's snack for a night shift that never ended. Not food but a mood. A mood warms you too.", Rare = false },
        new Def { Id = "HikoriVinegar", Kind = Kind.Snack, Shape = "bag", Mesh = "Hikori", Texture = "HikoriVinegar", Kg = 0.158f, Kcal = 810f, Thirst = -8f, Eat = 4f, Ru = "Картофельная соломка «Хикори Стикс»", En = "Hikori Stiks potato sticks", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Копчёная картофельная соломка: пахнет костром, который за тебя уже кто-то развёл. В охотничьей вышке таким встречали рассвет. Сытости на час, воспоминаний на неделю.", EnJ = "Smoked potato sticks: they smell of a campfire someone has already lit for you. In the hunting blind they met the dawn with this. An hour of fullness, a week of memories.", Rare = false },
        new Def { Id = "HikoriDill", Kind = Kind.Snack, Shape = "bag", Mesh = "Hikori", Texture = "HikoriDill", Kg = 0.158f, Kcal = 810f, Thirst = -8f, Eat = 4f, Ru = "Картофельная соломка «Хикори Стикс»", En = "Hikori Stiks potato sticks", RuF = "маринованный огурец", EnF = "dill pickle", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Копчёная картофельная соломка: пахнет костром, который за тебя уже кто-то развёл. Такое носили в кармане куртки на всякий случай. Случай настал. Кролик смотрит с осуждением.", EnJ = "Smoked potato sticks: they smell of a campfire someone has already lit for you. People carried these in a coat pocket just in case. The case has come. The rabbit looks on with disapproval.", Rare = false },
        new Def { Id = "HikoriSmoke", Kind = Kind.Snack, Shape = "bag", Mesh = "Hikori", Texture = "HikoriSmoke", Kg = 0.158f, Kcal = 810f, Thirst = -8f, Eat = 4f, Ru = "Картофельная соломка «Хикори Стикс»", En = "Hikori Stiks potato sticks", RuF = "двойной дым", EnF = "double smoke", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Копчёная картофельная соломка: пахнет костром, который за тебя уже кто-то развёл. Прежний хозяин оставил записку: «Не трогать». Записка сгорела. У костра вкуснее. У костра всё вкуснее.", EnJ = "Smoked potato sticks: they smell of a campfire someone has already lit for you. The last owner left a note: 'Do not touch'. The note burned. It tastes better by the fire. Everything does.", Rare = false },
        new Def { Id = "GreatBearMaple", Kind = Kind.Snack, Shape = "bag", Mesh = "GreatBear", Texture = "GreatBearMaple", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Грейт Бэр»", En = "Great Bear crisps", RuF = "кленовый бекон", EnF = "maple bacon", RuC = "Канада", EnC = "Canada", Fx = new[] { "SugarDry" }, RuJ = "На пачке медведь улыбается. На этом острове медведи улыбаются иначе. Такими торговали в поезде, пока поезд ходил. Упаковку не выбрасывайте: ею можно разжечь печь.", EnJ = "The bear on the pack is smiling. On this island bears smile differently. They sold these on the train, while the train ran. Keep the wrapper: it will light the stove.", Rare = false },
        new Def { Id = "GreatBearSalmon", Kind = Kind.Snack, Shape = "bag", Mesh = "GreatBear", Texture = "GreatBearSalmon", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Грейт Бэр»", En = "Great Bear crisps", RuF = "копчёный лосось", EnF = "smoked salmon", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "На пачке медведь улыбается. На этом острове медведи улыбаются иначе. Сторож шахты держал такое в ящике стола. Если это последняя на острове, вы её достойны.", EnJ = "The bear on the pack is smiling. On this island bears smile differently. The mine watchman kept these in his desk drawer. If this is the last one on the island, you have earned it.", Rare = false },
        new Def { Id = "GreatBearSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "GreatBear", Texture = "GreatBearSalt", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Грейт Бэр»", En = "Great Bear crisps", RuF = "морская соль", EnF = "sea salt", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "На пачке медведь улыбается. На этом острове медведи улыбаются иначе. Лавина прошла мимо, срок годности тоже. Желудок удивится, но возражать не станет.", EnJ = "The bear on the pack is smiling. On this island bears smile differently. The avalanche missed it, and so did the best-before date. Your stomach will be surprised but will not object.", Rare = false },
        new Def { Id = "GreatBearMoose", Kind = Kind.Snack, Shape = "bag", Mesh = "GreatBear", Texture = "GreatBearMoose", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Грейт Бэр»", En = "Great Bear crisps", RuF = "рагу из лося", EnF = "moose stew", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "На пачке медведь улыбается. На этом острове медведи улыбаются иначе. Такое всегда стояло на видном месте, поэтому никто не брал. Запах выдаёт вас за сто шагов. Оно того стоит.", EnJ = "The bear on the pack is smiling. On this island bears smile differently. These always stood in plain sight, which is why nobody took them. The smell gives you away at a hundred paces. Worth it.", Rare = false },
        new Def { Id = "GreatBearAurora", Kind = Kind.Snack, Shape = "bag", Mesh = "GreatBear", Texture = "GreatBearAurora", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Грейт Бэр»", En = "Great Bear crisps", RuF = "соль северного сияния", EnF = "aurora salt", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Зимняя серия: выпускали на один сезон, а зима тут навсегда. Кто-то открыл, передумал и умер. Не связано. Раньше это называли вредным. Теперь называют едой.", EnJ = "A winter edition: made for one season, and here winter is forever. Someone opened it, changed their mind and died. Unrelated. They used to call this unhealthy. Now they call it food.", Rare = true },
        new Def { Id = "GreatBearBlueberry", Kind = Kind.Snack, Shape = "bag", Mesh = "GreatBear", Texture = "GreatBearBlueberry", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Грейт Бэр»", En = "Great Bear crisps", RuF = "дикая голубика и барбекю", EnF = "wild blueberry barbecue", RuC = "Канада", EnC = "Canada", Fx = new[] { "SugarDry" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Такое вечно каталось под сиденьем пикапа. Спальный мешок потом вытряхните.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. One of these was always rolling under a pickup seat. Shake out your sleeping bag afterwards.", Rare = true },
        new Def { Id = "GreatBearSolstice", Kind = Kind.Snack, Shape = "bag", Mesh = "GreatBear", Texture = "GreatBearSolstice", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Грейт Бэр»", En = "Great Bear crisps", RuF = "к зимнему солнцестоянию", EnF = "winter solstice", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Зимняя серия: выпускали на один сезон, а зима тут навсегда. Привезено паромом, которого больше нет. Зимой такое идёт за валюту.", EnJ = "A winter edition: made for one season, and here winter is forever. Brought over by a ferry that no longer exists. In winter this passes for currency.", Rare = true },
        new Def { Id = "GreatBearThaw", Kind = Kind.Snack, Shape = "bag", Mesh = "GreatBear", Texture = "GreatBearThaw", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Грейт Бэр»", En = "Great Bear crisps", RuF = "первая оттепель", EnF = "first thaw", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Раньше это ели под телевизор. Телевизор молчит. Торговец дал бы за это тряпку. Вы дадите больше.", EnJ = "A spring edition: a rare pack from the days when spring still came. People ate this in front of the telly. The telly is silent. The trader would give a rag for it. You would give more.", Rare = true },
        new Def { Id = "GreatBearPoutine", Kind = Kind.Snack, Shape = "bag", Mesh = "GreatBear", Texture = "GreatBearPoutine", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Грейт Бэр»", En = "Great Bear crisps", RuF = "путин", EnF = "poutine", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "На пачке медведь улыбается. На этом острове медведи улыбаются иначе. Забыто туристами, которым повезло уехать. Пока жуёте, метель кажется короче.", EnJ = "The bear on the pack is smiling. On this island bears smile differently. Left behind by tourists who were lucky enough to leave. While you chew, the blizzard seems shorter.", Rare = false },
        new Def { Id = "GreatBearCedar", Kind = Kind.Snack, Shape = "bag", Mesh = "GreatBear", Texture = "GreatBearCedar", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Грейт Бэр»", En = "Great Bear crisps", RuF = "кедровый дым", EnF = "cedar smoke", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "На пачке медведь улыбается. На этом острове медведи улыбаются иначе. Механики заедали этим обед, не вытирая рук. Организм скажет спасибо. Или не скажет.", EnJ = "The bear on the pack is smiling. On this island bears smile differently. Mechanics ate these for lunch without wiping their hands. Your body will thank you. Or not.", Rare = false },
        new Def { Id = "GreatBearDill", Kind = Kind.Snack, Shape = "bag", Mesh = "GreatBear", Texture = "GreatBearDill", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Грейт Бэр»", En = "Great Bear crisps", RuF = "маринованный огурец", EnF = "dill pickle", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "На пачке медведь улыбается. На этом острове медведи улыбаются иначе. Последнее на всю Одинокую топь. Скорее всего. На третьей горсти забываешь, что вокруг конец света.", EnJ = "The bear on the pack is smiling. On this island bears smile differently. The last one in all of Forlorn Muskeg. Most likely. By the third handful you forget the world has ended.", Rare = false },
        new Def { Id = "GreatBearVenison", Kind = Kind.Snack, Shape = "bag", Mesh = "GreatBear", Texture = "GreatBearVenison", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Грейт Бэр»", En = "Great Bear crisps", RuF = "оленина на углях", EnF = "chargrilled venison", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "На пачке медведь улыбается. На этом острове медведи улыбаются иначе. Смотритель маяка грыз такое, ожидая кораблей. Рыба подо льдом завидует.", EnJ = "The bear on the pack is smiling. On this island bears smile differently. The lighthouse keeper munched these while waiting for ships. The fish under the ice are jealous.", Rare = false },
        new Def { Id = "GreatBearCheddar", Kind = Kind.Snack, Shape = "bag", Mesh = "GreatBear", Texture = "GreatBearCheddar", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Грейт Бэр»", En = "Great Bear crisps", RuF = "старый чеддер", EnF = "aged cheddar", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "На пачке медведь улыбается. На этом острове медведи улыбаются иначе. Полки рушились, а это уцелело. Олень от такого отказался бы. Олень не голодал.", EnJ = "The bear on the pack is smiling. On this island bears smile differently. Shelves collapsed and this survived. A deer would turn it down. A deer has never starved.", Rare = false },
        new Def { Id = "FritozOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "Fritoz", Texture = "FritozOriginal", Kg = 0.268f, Kcal = 1300f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Фритоз»", En = "Fritoz tortilla chips", RuF = "оригинальные", EnF = "original", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Кукурузные завитки, которыми в Техасе едят чили прямо из пакета. Смотритель заповедника называл это ужином. Соль есть, жир есть, совести нет.", EnJ = "Corn curls that Texans use to eat chili straight from the bag. The park ranger called this dinner. Salt: yes. Fat: yes. Conscience: none.", Rare = false },
        new Def { Id = "FritozChili", Kind = Kind.Snack, Shape = "bag", Mesh = "Fritoz", Texture = "FritozChili", Kg = 0.268f, Kcal = 1300f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Фритоз»", En = "Fritoz tortilla chips", RuF = "чили с сыром", EnF = "chili cheese", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Кукурузные завитки, которыми в Техасе едят чили прямо из пакета. Такое слали посылками с материка. Адресаты выбыли. Ешьте до темноты: в темноте крошки не найти.", EnJ = "Corn curls that Texans use to eat chili straight from the bag. These came in parcels from the mainland. The addressees are gone. Eat before dark: you cannot find crumbs in the dark.", Rare = false },
        new Def { Id = "FritozBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Fritoz", Texture = "FritozBBQ", Kg = 0.268f, Kcal = 1300f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Фритоз»", En = "Fritoz tortilla chips", RuF = "барбекю с мёдом", EnF = "honey bbq", RuC = "США", EnC = "USA", Fx = new[] { "SugarDry" }, RuJ = "Кукурузные завитки, которыми в Техасе едят чили прямо из пакета. Иные держали это за лекарство. Тоже лечит. Лучшее, что случится с вами сегодня.", EnJ = "Corn curls that Texans use to eat chili straight from the bag. Some people counted this as medicine. Also a cure. The best thing that will happen to you today.", Rare = false },
        new Def { Id = "FritozScoops", Kind = Kind.Snack, Shape = "bag", Mesh = "Fritoz", Texture = "FritozScoops", Kg = 0.268f, Kcal = 1300f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Фритоз»", En = "Fritoz tortilla chips", RuF = "ложечки", EnF = "scoops", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Кукурузные завитки, которыми в Техасе едят чили прямо из пакета. В школьном рюкзаке такое не доживало до обеда. Для полного счастья не хватает только дивана.", EnJ = "Corn curls that Texans use to eat chili straight from the bag. In a school bag this never lasted till lunch. All that is missing for perfect happiness is a sofa.", Rare = false },
        new Def { Id = "FritozTailgate", Kind = Kind.Snack, Shape = "bag", Mesh = "Fritoz", Texture = "FritozTailgate", Kg = 0.268f, Kcal = 1300f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Фритоз»", En = "Fritoz tortilla chips", RuF = "осенний чили", EnF = "autumn chilli", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Его обменяли бы на патрон, будь тут с кем меняться. Вкус детства, если детство было так себе.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. You could trade it for a cartridge, if there were anyone to trade with. The taste of childhood, if childhood was so-so.", Rare = true },
        new Def { Id = "FritozHoney", Kind = Kind.Snack, Shape = "bag", Mesh = "Fritoz", Texture = "FritozHoney", Kg = 0.268f, Kcal = 1300f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Фритоз»", En = "Fritoz tortilla chips", RuF = "мёд и барбекю", EnF = "honey barbecue", RuC = "США", EnC = "USA", Fx = new[] { "SugarDry" }, RuJ = "Кукурузные завитки, которыми в Техасе едят чили прямо из пакета. На вокзале это стоило втрое дороже. Теперь даром. Шуршит как надежда.", EnJ = "Corn curls that Texans use to eat chili straight from the bag. At the station it cost three times as much. Now it is free. It rustles like hope.", Rare = false },
        new Def { Id = "FritozHot", Kind = Kind.Snack, Shape = "bag", Mesh = "Fritoz", Texture = "FritozHot", Kg = 0.268f, Kcal = 1300f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Фритоз»", En = "Fritoz tortilla chips", RuF = "огненные", EnF = "flamin hot", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Кукурузные завитки, которыми в Техасе едят чили прямо из пакета. Пережило толчок и даже не помялось. Голод отступит, жажда придёт. Честный обмен.", EnJ = "Corn curls that Texans use to eat chili straight from the bag. It came through the quake without a dent. Hunger leaves, thirst arrives. A fair trade.", Rare = false },
        new Def { Id = "FritozLime", Kind = Kind.Snack, Shape = "bag", Mesh = "Fritoz", Texture = "FritozLime", Kg = 0.268f, Kcal = 1300f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Фритоз»", En = "Fritoz tortilla chips", RuF = "чили и лайм", EnF = "chilli lime", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Кукурузные завитки, которыми в Техасе едят чили прямо из пакета. Китобои такого не ели, но оценили бы. Не согреет, зато отвлечёт.", EnJ = "Corn curls that Texans use to eat chili straight from the bag. The whalers never ate this, but they would have approved. It will not warm you, but it will distract you.", Rare = false },
        new Def { Id = "FritozSalted", Kind = Kind.Snack, Shape = "bag", Mesh = "Fritoz", Texture = "FritozSalted", Kg = 0.268f, Kcal = 1300f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Фритоз»", En = "Fritoz tortilla chips", RuF = "слабосолёные", EnF = "lightly salted", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Кукурузные завитки, которыми в Техасе едят чили прямо из пакета. Осталось после чьего-то дня рождения. Гости не пришли. Пума предпочитает мясо. Вам повезло.", EnJ = "Corn curls that Texans use to eat chili straight from the bag. Left over from someone's birthday. The guests never came. The cougar prefers meat. Lucky you.", Rare = false },
        new Def { Id = "FritozQueso", Kind = Kind.Snack, Shape = "bag", Mesh = "Fritoz", Texture = "FritozQueso", Kg = 0.268f, Kcal = 1300f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Фритоз»", En = "Fritoz tortilla chips", RuF = "соус кесо", EnF = "queso", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Кукурузные завитки, которыми в Техасе едят чили прямо из пакета. Мерзлота хранит лучше любого холодильника. Сначала попробуйте одну штучку. Шутка: ешьте всё.", EnJ = "Corn curls that Texans use to eat chili straight from the bag. Permafrost keeps things better than any fridge. Try just one first. Joke: eat the lot.", Rare = false },
        new Def { Id = "KornNutzOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "KornNutz", Texture = "KornNutzOriginal", Kg = 0.121f, Kcal = 510f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Корн Натс»", En = "Korn Nutz toasted corn", RuF = "оригинальная", EnF = "original", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Жареная кукуруза твёрже, чем решение бросить есть на ночь. Такое добывали из автомата, который съедал последнюю монету. Такой ужин не стыдно записать в дневник.", EnJ = "Toasted corn, harder than your resolve not to eat at night. These came from the vending machine that ate your last coin. A dinner worth writing in the journal.", Rare = false },
        new Def { Id = "KornNutzRanch", Kind = Kind.Snack, Shape = "bag", Mesh = "KornNutz", Texture = "KornNutzRanch", Kg = 0.121f, Kcal = 510f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Корн Натс»", En = "Korn Nutz toasted corn", RuF = "ранч", EnF = "ranch", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Жареная кукуруза твёрже, чем решение бросить есть на ночь. Такое брали в лодку под брезент, на весь день. Силы прибавит на один сугроб.", EnJ = "Toasted corn, harder than your resolve not to eat at night. People took these out in the boat under the tarpaulin, for the whole day. It will carry you one snowdrift further.", Rare = false },
        new Def { Id = "KornNutzChile", Kind = Kind.Snack, Shape = "bag", Mesh = "KornNutz", Texture = "KornNutzChile", Kg = 0.121f, Kcal = 510f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Корн Натс»", En = "Korn Nutz toasted corn", RuF = "чили пиканте", EnF = "chile picante", RuC = "США", EnC = "USA", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Жареная кукуруза твёрже, чем решение бросить есть на ночь. С ним кто-то шёл к перевалу и не дошёл. Идеально к закату, которого не видно за бураном.", EnJ = "Toasted corn, harder than your resolve not to eat at night. Someone carried it towards the pass and never arrived. Perfect with a sunset you cannot see for the storm.", Rare = false },
        new Def { Id = "KornNutzBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "KornNutz", Texture = "KornNutzBBQ", Kg = 0.121f, Kcal = 510f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Корн Натс»", En = "Korn Nutz toasted corn", RuF = "барбекю", EnF = "barbecue", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Жареная кукуруза твёрже, чем решение бросить есть на ночь. С таким сидели у окна с видом на метель. Пахнет магазином. Помните магазины?", EnJ = "Toasted corn, harder than your resolve not to eat at night. People sat with these at a window with a view of the blizzard. It smells of a shop. Remember shops?", Rare = false },
        new Def { Id = "KornNutzGhost", Kind = Kind.Snack, Shape = "bag", Mesh = "KornNutz", Texture = "KornNutzGhost", Kg = 0.121f, Kcal = 510f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Корн Натс»", En = "Korn Nutz toasted corn", RuF = "перец-призрак", EnF = "ghost pepper", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Серия к Хэллоуину: редкость. Пугать тут и без неё есть кому. Уцелело там, где сгорело всё остальное. Мороз не испортил, время не взяло.", EnJ = "A Halloween edition: a rarity. There is plenty to scare you here without it. It survived where everything else burned. Frost did not spoil it and time could not take it.", Rare = true },
        new Def { Id = "KornNutzNacho", Kind = Kind.Snack, Shape = "bag", Mesh = "KornNutz", Texture = "KornNutzNacho", Kg = 0.121f, Kcal = 510f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Корн Натс»", En = "Korn Nutz toasted corn", RuF = "начо", EnF = "nacho", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Жареная кукуруза твёрже, чем решение бросить есть на ночь. Этим кормили сторожевого пса. Пёс ушёл в волки. В рюкзаке не мнётся. Почти.", EnJ = "Toasted corn, harder than your resolve not to eat at night. They fed the guard dog with this. The dog joined the wolves. It does not get crushed in a pack. Almost.", Rare = false },
        new Def { Id = "KornNutzSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "KornNutz", Texture = "KornNutzSalt", Kg = 0.121f, Kcal = 510f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Корн Натс»", En = "Korn Nutz toasted corn", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Жареная кукуруза твёрже, чем решение бросить есть на ночь. Из запасов лесорубов: брали ящиками. Съешьте сейчас: завтра может не быть аппетита.", EnJ = "Toasted corn, harder than your resolve not to eat at night. From the loggers' stores: they bought it by the crate. Eat it now: tomorrow you may have no appetite.", Rare = false },
        new Def { Id = "KornNutzJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "KornNutz", Texture = "KornNutzJalapeno", Kg = 0.121f, Kcal = 510f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Корн Натс»", En = "Korn Nutz toasted corn", RuF = "халапеньо и чеддер", EnF = "jalapeno cheddar", RuC = "США", EnC = "USA", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Жареная кукуруза твёрже, чем решение бросить есть на ночь. В пост такое не ели. Пост кончился вместе с миром. Хватит дойти до следующей хижины и пожалеть, что кончилось.", EnJ = "Toasted corn, harder than your resolve not to eat at night. Nobody ate these during a fast. The fast ended with the world. Enough to reach the next cabin and regret it is gone.", Rare = false },
        new Def { Id = "KornNutzTaco", Kind = Kind.Snack, Shape = "bag", Mesh = "KornNutz", Texture = "KornNutzTaco", Kg = 0.121f, Kcal = 510f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Корн Натс»", En = "Korn Nutz toasted corn", RuF = "тако", EnF = "taco", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Жареная кукуруза твёрже, чем решение бросить есть на ночь. Теперь это ценнее денег. Деньги оставьте. От такого не толстеют те, кто ходит по двадцать километров.", EnJ = "Toasted corn, harder than your resolve not to eat at night. It is worth more than money now. Leave the money. Nobody who walks twenty kilometres a day gets fat on this.", Rare = false },
        new Def { Id = "KornNutzLimon", Kind = Kind.Snack, Shape = "bag", Mesh = "KornNutz", Texture = "KornNutzLimon", Kg = 0.121f, Kcal = 510f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Корн Натс»", En = "Korn Nutz toasted corn", RuF = "лайм и соль", EnF = "lime & salt", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Жареная кукуруза твёрже, чем решение бросить есть на ночь. Его несли на пикник. Пикник отменили навсегда. Волчья стая не в курсе. Пусть так и будет.", EnJ = "Toasted corn, harder than your resolve not to eat at night. It was headed for a picnic. The picnic is cancelled forever. The wolf pack does not know. Keep it that way.", Rare = false },
        new Def { Id = "SnaiderzMini", Kind = Kind.Snack, Shape = "bag", Mesh = "Snaiderz", Texture = "SnaiderzMini", Kg = 0.258f, Kcal = 950f, Thirst = -8f, Eat = 4f, Ru = "Крендельки «Снайдерз»", En = "Snaiderz pretzels", RuF = "мини, с солью", EnF = "mini salted", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крендельки из Пенсильвании: узел завязан так, что моряки завидуют. Такое стояло у кассы на случай слабости. Хрустеть в засаде не рекомендуется.", EnJ = "Pennsylvania pretzels: tied in a knot sailors envy. These stood by the till for moments of weakness. Crunching in an ambush is not recommended.", Rare = false },
        new Def { Id = "SnaiderzMustard", Kind = Kind.Snack, Shape = "bag", Mesh = "Snaiderz", Texture = "SnaiderzMustard", Kg = 0.258f, Kcal = 950f, Thirst = -8f, Eat = 4f, Ru = "Крендельки «Снайдерз»", En = "Snaiderz pretzels", RuF = "мёд и горчица", EnF = "honey mustard & onion", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Крендельки из Пенсильвании: узел завязан так, что моряки завидуют. Досталось вам, потому что вы дошли первым. Лекарство от тоски, отпускается без рецепта.", EnJ = "Pennsylvania pretzels: tied in a knot sailors envy. It is yours because you got here first. A cure for the blues, no prescription needed.", Rare = false },
        new Def { Id = "SnaiderzJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "Snaiderz", Texture = "SnaiderzJalapeno", Kg = 0.258f, Kcal = 950f, Thirst = -8f, Eat = 4f, Ru = "Крендельки «Снайдерз»", En = "Snaiderz pretzels", RuF = "халапеньо", EnF = "jalapeno", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Крендельки из Пенсильвании: узел завязан так, что моряки завидуют. Упаковка выцвела, внутри время остановилось. Жуйте и думайте о хорошем. Например, о добавке.", EnJ = "Pennsylvania pretzels: tied in a knot sailors envy. The wrapper has faded; inside, time stood still. Chew and think of nice things. Seconds, for example.", Rare = false },
        new Def { Id = "SnaiderzSourdough", Kind = Kind.Snack, Shape = "bag", Mesh = "Snaiderz", Texture = "SnaiderzSourdough", Kg = 0.258f, Kcal = 950f, Thirst = -8f, Eat = 4f, Ru = "Крендельки «Снайдерз»", En = "Snaiderz pretzels", RuF = "на закваске", EnF = "sourdough", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крендельки из Пенсильвании: узел завязан так, что моряки завидуют. Из чемодана пассажира, который не долетел. К утру от него останется только запах на варежках.", EnJ = "Pennsylvania pretzels: tied in a knot sailors envy. From the suitcase of a passenger who never landed. By morning only the smell on your mittens will be left.", Rare = false },
        new Def { Id = "SnaiderzPumpkin", Kind = Kind.Snack, Shape = "bag", Mesh = "Snaiderz", Texture = "SnaiderzPumpkin", Kg = 0.258f, Kcal = 950f, Thirst = -8f, Eat = 4f, Ru = "Крендельки «Снайдерз»", En = "Snaiderz pretzels", RuF = "тыквенные специи", EnF = "pumpkin spice", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Перезимовало и ничуть не обиделось. Тишина вокруг такая, что слышно, как вы жуёте.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. It made it through the winter and bears no grudge. It is so quiet you can hear yourself chew.", Rare = true },
        new Def { Id = "SnaiderzHearts", Kind = Kind.Snack, Shape = "bag", Mesh = "Snaiderz", Texture = "SnaiderzHearts", Kg = 0.258f, Kcal = 950f, Thirst = -8f, Eat = 4f, Ru = "Крендельки «Снайдерз»", En = "Snaiderz pretzels", RuF = "сердечки в йогурте", EnF = "yoghurt hearts", RuC = "США", EnC = "USA", Fx = new[] { "SugarDry" }, RuJ = "Серия для влюблённых: редкость. Делить не с кем, зато вся ваша. Запасливая хозяйка купила по акции шесть штук. Не делите на завтра: завтра будет новый голод.", EnJ = "A Valentine edition: a rarity. No one to share it with, so it is all yours. A thrifty housewife bought six of these on offer. Do not save half for tomorrow: tomorrow brings its own hunger.", Rare = true },
        new Def { Id = "SnaiderzRods", Kind = Kind.Snack, Shape = "bag", Mesh = "Snaiderz", Texture = "SnaiderzRods", Kg = 0.258f, Kcal = 950f, Thirst = -8f, Eat = 4f, Ru = "Крендельки «Снайдерз»", En = "Snaiderz pretzels", RuF = "палочки", EnF = "pretzel rods", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крендельки из Пенсильвании: узел завязан так, что моряки завидуют. Кто-то написал на упаковке «моё». Уже нет. Сосны вокруг делают вид, что не смотрят.", EnJ = "Pennsylvania pretzels: tied in a knot sailors envy. Someone wrote 'mine' on it. Not any more. The pines around pretend not to watch.", Rare = false },
        new Def { Id = "SnaiderzButter", Kind = Kind.Snack, Shape = "bag", Mesh = "Snaiderz", Texture = "SnaiderzButter", Kg = 0.258f, Kcal = 950f, Thirst = -8f, Eat = 4f, Ru = "Крендельки «Снайдерз»", En = "Snaiderz pretzels", RuF = "масляные", EnF = "butter snaps", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крендельки из Пенсильвании: узел завязан так, что моряки завидуют. В консервном цеху это ели тайком от мастера. Калории мелкие, зато свои.", EnJ = "Pennsylvania pretzels: tied in a knot sailors envy. At the cannery they ate this behind the foreman's back. Small calories, but your own.", Rare = false },
        new Def { Id = "SnaiderzCheddar", Kind = Kind.Snack, Shape = "bag", Mesh = "Snaiderz", Texture = "SnaiderzCheddar", Kg = 0.258f, Kcal = 950f, Thirst = -8f, Eat = 4f, Ru = "Крендельки «Снайдерз»", En = "Snaiderz pretzels", RuF = "кусочки с чеддером", EnF = "cheddar pieces", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крендельки из Пенсильвании: узел завязан так, что моряки завидуют. Его не взяли даже мародёры. Они спешили. После этого даже крапивный чай покажется десертом.", EnJ = "Pennsylvania pretzels: tied in a knot sailors envy. Even the looters left it. They were in a hurry. After this even nettle tea feels like dessert.", Rare = false },
        new Def { Id = "SnaiderzBuffalo", Kind = Kind.Snack, Shape = "bag", Mesh = "Snaiderz", Texture = "SnaiderzBuffalo", Kg = 0.258f, Kcal = 950f, Thirst = -8f, Eat = 4f, Ru = "Крендельки «Снайдерз»", En = "Snaiderz pretzels", RuF = "острое крылышко", EnF = "hot buffalo wing", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Крендельки из Пенсильвании: узел завязан так, что моряки завидуют. Провело зиму на острове, как и вы. Нашедшему полагается всё.", EnJ = "Pennsylvania pretzels: tied in a knot sailors envy. It spent the winter on the island, same as you. Finders keepers, all of it.", Rare = false },
        new Def { Id = "SnaiderzGarlic", Kind = Kind.Snack, Shape = "bag", Mesh = "Snaiderz", Texture = "SnaiderzGarlic", Kg = 0.258f, Kcal = 950f, Thirst = -8f, Eat = 4f, Ru = "Крендельки «Снайдерз»", En = "Snaiderz pretzels", RuF = "чесночный хлеб", EnF = "garlic bread", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крендельки из Пенсильвании: узел завязан так, что моряки завидуют. Дети прятали такое под кроватью, в тайнике. Зубы целы? Тогда вперёд.", EnJ = "Pennsylvania pretzels: tied in a knot sailors envy. Children hid these under the bed, in a secret place. Teeth intact? Then go ahead.", Rare = false },
        new Def { Id = "SnaiderzSticks", Kind = Kind.Snack, Shape = "bag", Mesh = "Snaiderz", Texture = "SnaiderzSticks", Kg = 0.258f, Kcal = 950f, Thirst = -8f, Eat = 4f, Ru = "Крендельки «Снайдерз»", En = "Snaiderz pretzels", RuF = "тонкие палочки", EnF = "pretzel sticks", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крендельки из Пенсильвании: узел завязан так, что моряки завидуют. Осталось от геологов вместе с картой и долгами. Ночью приснится добавка.", EnJ = "Pennsylvania pretzels: tied in a knot sailors envy. Left by the geologists along with a map and some debts. Tonight you will dream of seconds.", Rare = false },
        new Def { Id = "MaksOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "Maks", Texture = "MaksOriginal", Kg = 0.148f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Свиные шкварки «Макс»", En = "Mak’s pork rinds", RuF = "оригинальные", EnF = "original", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Свиные шкварки: ноль углеводов и ноль сожалений. На острове такое было праздником и до катастрофы. С таким запасом можно пережить ещё один вечер.", EnJ = "Pork rinds: zero carbs and zero regrets. On the island this was a treat even before the disaster. With supplies like this you can survive one more evening.", Rare = false },
        new Def { Id = "MaksBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Maks", Texture = "MaksBBQ", Kg = 0.148f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Свиные шкварки «Макс»", En = "Mak’s pork rinds", RuF = "барбекю", EnF = "barbecue", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Свиные шкварки: ноль углеводов и ноль сожалений. С таким слушали радио, которое теперь ловит только треск. Пёс бы выпросил половину. Пса нет.", EnJ = "Pork rinds: zero carbs and zero regrets. People ate these by the radio, which picks up nothing but crackle now. A dog would beg half of it. There is no dog.", Rare = false },
        new Def { Id = "MaksHot", Kind = Kind.Snack, Shape = "bag", Mesh = "Maks", Texture = "MaksHot", Kg = 0.148f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Свиные шкварки «Макс»", En = "Mak’s pork rinds", RuF = "острые", EnF = "hot & spicy", RuC = "США", EnC = "USA", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Свиные шкварки: ноль углеводов и ноль сожалений. Крысы прогрызли соседнюю, эту пощадили. Съедено будет быстрее, чем найдено.", EnJ = "Pork rinds: zero carbs and zero regrets. The rats gnawed through the one next to it and spared this. It will be eaten faster than it was found.", Rare = false },
        new Def { Id = "MaksVinegar", Kind = Kind.Snack, Shape = "bag", Mesh = "Maks", Texture = "MaksVinegar", Kg = 0.148f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Свиные шкварки «Макс»", En = "Mak’s pork rinds", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Свиные шкварки: ноль углеводов и ноль сожалений. Бывший хозяин клялся бросить. Не успел. На вкус как выходной.", EnJ = "Pork rinds: zero carbs and zero regrets. The former owner swore to give these up. He ran out of time. It tastes like a day off.", Rare = false },
        new Def { Id = "MaksChile", Kind = Kind.Snack, Shape = "bag", Mesh = "Maks", Texture = "MaksChile", Kg = 0.148f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Свиные шкварки «Макс»", En = "Mak’s pork rinds", RuF = "чили и лайм", EnF = "chilli lime", RuC = "США", EnC = "USA", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Свиные шкварки: ноль углеводов и ноль сожалений. Его катали в кабине трактора три сезона. Ветер унесёт запах прямо к берлоге. Ешьте быстрее.", EnJ = "Pork rinds: zero carbs and zero regrets. It rode around in a tractor cab for three seasons. The wind carries the smell straight to the den. Eat faster.", Rare = false },
        new Def { Id = "MaksCracklins", Kind = Kind.Snack, Shape = "bag", Mesh = "Maks", Texture = "MaksCracklins", Kg = 0.148f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Свиные шкварки «Макс»", En = "Mak’s pork rinds", RuF = "шкварки", EnF = "cracklins", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Свиные шкварки: ноль углеводов и ноль сожалений. После бани такое шло лучше всего. Пополняет запас соли и веры в человечество.", EnJ = "Pork rinds: zero carbs and zero regrets. Nothing went down better after the sauna. Restores your salt and your faith in mankind.", Rare = false },
        new Def { Id = "MaksCheddar", Kind = Kind.Snack, Shape = "bag", Mesh = "Maks", Texture = "MaksCheddar", Kg = 0.148f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Свиные шкварки «Макс»", En = "Mak’s pork rinds", RuF = "начо чеддер", EnF = "nacho cheddar", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Свиные шкварки: ноль углеводов и ноль сожалений. В тюрьме на это выменивали что угодно. Хорошо идёт под треск поленьев.", EnJ = "Pork rinds: zero carbs and zero regrets. In the prison you could trade one of these for anything. Goes down well with crackling logs.", Rare = false },
        new Def { Id = "DeividOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "Deivid", Texture = "DeividOriginal", Kg = 0.158f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Дэйвид»", En = "Deivid seeds", RuF = "оригинальные", EnF = "original", RuC = "США", EnC = "USA", Fx = new[] { "SeedHabit" }, RuJ = "Семечки бейсболистов: главное в игре — красиво сплюнуть шелуху. Кто-то менял это на сигареты. Сделка сорвалась. Руки вытирать о штаны: салфеток не завезли.", EnJ = "Ballplayers' seeds: the point of the game is to spit the shell with style. Someone was trading this for cigarettes. The deal fell through. Wipe your hands on your trousers: no napkins were delivered.", Rare = false },
        new Def { Id = "DeividRanch", Kind = Kind.Snack, Shape = "bag", Mesh = "Deivid", Texture = "DeividRanch", Kg = 0.158f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Дэйвид»", En = "Deivid seeds", RuF = "ранч", EnF = "ranch", RuC = "США", EnC = "USA", Fx = new[] { "SeedHabit" }, RuJ = "Семечки бейсболистов: главное в игре — красиво сплюнуть шелуху. С ним зимовали на метеостанции, пока было с кем. Маленькая радость размером с ладонь.", EnJ = "Ballplayers' seeds: the point of the game is to spit the shell with style. They wintered with it at the weather station, while there was a 'they'. A small joy the size of your palm.", Rare = false },
        new Def { Id = "DeividBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Deivid", Texture = "DeividBBQ", Kg = 0.158f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Дэйвид»", En = "Deivid seeds", RuF = "барбекю", EnF = "barbecue", RuC = "США", EnC = "USA", Fx = new[] { "SeedHabit" }, RuJ = "Семечки бейсболистов: главное в игре — красиво сплюнуть шелуху. Такое терялось в кладовке среди крупы и надежд. Совесть молчит, живот поёт.", EnJ = "Ballplayers' seeds: the point of the game is to spit the shell with style. These got lost in the pantry among the grain and the hopes. Conscience is silent, the belly sings.", Rare = false },
        new Def { Id = "DeividDill", Kind = Kind.Snack, Shape = "bag", Mesh = "Deivid", Texture = "DeividDill", Kg = 0.158f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Дэйвид»", En = "Deivid seeds", RuF = "маринованный огурец", EnF = "dill pickle", RuC = "США", EnC = "USA", Fx = new[] { "SeedHabit" }, RuJ = "Семечки бейсболистов: главное в игре — красиво сплюнуть шелуху. Его берегли к приезду внуков. Проверено поколениями и одной катастрофой.", EnJ = "Ballplayers' seeds: the point of the game is to spit the shell with style. It was being saved for the grandchildren's visit. Tested by generations and one catastrophe.", Rare = false },
        new Def { Id = "DeividPickle", Kind = Kind.Snack, Shape = "bag", Mesh = "Deivid", Texture = "DeividPickle", Kg = 0.158f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Дэйвид»", En = "Deivid seeds", RuF = "осенний маринованный огурчик", EnF = "fall classic dill pickle", RuC = "США", EnC = "USA", Fx = new[] { "SeedHabit" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. В баре такое ставили на стойку, бесплатно к пиву. Пива нет. Оставьте пару штук на перевал. Не оставите.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. Bars put these out free with a beer. There is no beer. Save a couple for the pass. You will not.", Rare = true },
        new Def { Id = "DeividJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "Deivid", Texture = "DeividJalapeno", Kg = 0.158f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Дэйвид»", En = "Deivid seeds", RuF = "острый халапеньо", EnF = "hot jalapeno", RuC = "США", EnC = "USA", Fx = new[] { "SeedHabit", "PepperBlood", "Sweat" }, RuJ = "Семечки бейсболистов: главное в игре — красиво сплюнуть шелуху. Такое лежало в каждом доме, пока не погас свет. Здесь это считается ужином при свечах.", EnJ = "Ballplayers' seeds: the point of the game is to spit the shell with style. Every house had one of these until the lights went out. Round here this counts as a candlelit dinner.", Rare = false },
        new Def { Id = "DeividNacho", Kind = Kind.Snack, Shape = "bag", Mesh = "Deivid", Texture = "DeividNacho", Kg = 0.158f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Дэйвид»", En = "Deivid seeds", RuF = "сыр начо", EnF = "nacho cheese", RuC = "США", EnC = "USA", Fx = new[] { "SeedHabit" }, RuJ = "Семечки бейсболистов: главное в игре — красиво сплюнуть шелуху. Кто-то берёг это на чёрный день. Он настал. Луна светит, еда хрустит, жизнь налаживается.", EnJ = "Ballplayers' seeds: the point of the game is to spit the shell with style. Someone saved this for a rainy day. It came. The moon shines, the food crunches, life is looking up.", Rare = false },
        new Def { Id = "DeividSweet", Kind = Kind.Snack, Shape = "bag", Mesh = "Deivid", Texture = "DeividSweet", Kg = 0.158f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Дэйвид»", En = "Deivid seeds", RuF = "сладко-солёные", EnF = "sweet & salty", RuC = "США", EnC = "USA", Fx = new[] { "SeedHabit" }, RuJ = "Семечки бейсболистов: главное в игре — красиво сплюнуть шелуху. Пережило хозяина, кота и две зимы. Снег вокруг не солёный. Это солёное.", EnJ = "Ballplayers' seeds: the point of the game is to spit the shell with style. It outlived its owner, the cat and two winters. The snow around is not salty. This is.", Rare = false },
        new Def { Id = "DeividBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Deivid", Texture = "DeividBacon", Kg = 0.158f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Дэйвид»", En = "Deivid seeds", RuF = "бекон", EnF = "bacon", RuC = "США", EnC = "USA", Fx = new[] { "SeedHabit" }, RuJ = "Семечки бейсболистов: главное в игре — красиво сплюнуть шелуху. Такое обычно находили за диваном, как всё лучшее в жизни. Больше таких не делают. Совсем.", EnJ = "Ballplayers' seeds: the point of the game is to spit the shell with style. These were usually found behind the sofa, like all the best things in life. They do not make these any more. At all.", Rare = false },
        new Def { Id = "DeividPepper", Kind = Kind.Snack, Shape = "bag", Mesh = "Deivid", Texture = "DeividPepper", Kg = 0.158f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Дэйвид»", En = "Deivid seeds", RuF = "чёрный перец", EnF = "cracked pepper", RuC = "США", EnC = "USA", Fx = new[] { "SeedHabit" }, RuJ = "Семечки бейсболистов: главное в игре — красиво сплюнуть шелуху. Последний завоз был до того, как упали самолёты. Открывайте тихо: у волков отличный слух.", EnJ = "Ballplayers' seeds: the point of the game is to spit the shell with style. The last delivery came before the planes fell. Open it quietly: wolves have excellent hearing.", Rare = false },
        new Def { Id = "DeividKernels", Kind = Kind.Snack, Shape = "bag", Mesh = "Deivid", Texture = "DeividKernels", Kg = 0.158f, Kcal = 870f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Дэйвид»", En = "Deivid seeds", RuF = "очищенные ядра", EnF = "shelled kernels", RuC = "США", EnC = "USA", Fx = new[] { "SeedHabit" }, RuJ = "Семечки бейсболистов: главное в игре — красиво сплюнуть шелуху. Ценник оторван: теперь это бесценно. Одной не обойдётся, но вторая неизвестно где.", EnJ = "Ballplayers' seeds: the point of the game is to spit the shell with style. The price tag is torn off: it is priceless now. One won't be enough, and nobody knows where the second is.", Rare = false },
        new Def { Id = "MoskovskiySalt", Kind = Kind.Snack, Shape = "carton", Mesh = "Moskovskiy", Texture = "MoskovskiySalt", Kg = 0.058f, Kcal = 270f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Московский картофель»", En = "Moskovskiy crisps", RuF = "с солью", EnF = "salted", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold" }, RuJ = "Первые советские чипсы в картонной коробке: ломтики в масле, как и руки после них. Дата на шве стёрлась, и слава богу. Крошки с пола тоже считаются.", EnJ = "The first Soviet crisps in a carton: slices in oil, and so are your hands. The date on the seam has rubbed off, thank goodness. The crumbs on the floor count too.", Rare = false },
        new Def { Id = "MoskovskiyMushroom", Kind = Kind.Snack, Shape = "carton", Mesh = "Moskovskiy", Texture = "MoskovskiyMushroom", Kg = 0.058f, Kcal = 270f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Московский картофель»", En = "Moskovskiy crisps", RuF = "с грибами", EnF = "with mushrooms", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold" }, RuJ = "Первые советские чипсы в картонной коробке: ломтики в масле, как и руки после них. Пахнет заправкой у Прибрежного шоссе. Запейте чаем из шиповника и считайте это обедом.", EnJ = "The first Soviet crisps in a carton: slices in oil, and so are your hands. It smells of the petrol station on the Coastal Highway. Wash it down with rosehip tea and call it lunch.", Rare = false },
        new Def { Id = "MoskovskiyCheese", Kind = Kind.Snack, Shape = "carton", Mesh = "Moskovskiy", Texture = "MoskovskiyCheese", Kg = 0.058f, Kcal = 270f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Московский картофель»", En = "Moskovskiy crisps", RuF = "с сыром", EnF = "with cheese", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold" }, RuJ = "Первые советские чипсы в картонной коробке: ломтики в масле, как и руки после них. Такое возили в бардачке на дальнюю дорогу. Дороги кончились. Медведю не показывать: отнимет вместе с рукой.", EnJ = "The first Soviet crisps in a carton: slices in oil, and so are your hands. People kept these in the glovebox for long drives. The drives are over. Do not show the bear: he will take it, hand and all.", Rare = false },
        new Def { Id = "MoskovskiyDill", Kind = Kind.Snack, Shape = "carton", Mesh = "Moskovskiy", Texture = "MoskovskiyDill", Kg = 0.058f, Kcal = 270f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Московский картофель»", En = "Moskovskiy crisps", RuF = "с укропом", EnF = "dill", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold" }, RuJ = "Первые советские чипсы в картонной коробке: ломтики в масле, как и руки после них. Мыши не тронули. Думайте сами. Диетолог не одобрил бы. Диетолога тут нет.", EnJ = "The first Soviet crisps in a carton: slices in oil, and so are your hands. The mice left it alone. Draw your own conclusions. A dietitian would not approve. There is no dietitian here.", Rare = false },
        new Def { Id = "MoskovskiyOnion", Kind = Kind.Snack, Shape = "carton", Mesh = "Moskovskiy", Texture = "MoskovskiyOnion", Kg = 0.058f, Kcal = 270f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Московский картофель»", En = "Moskovskiy crisps", RuF = "с луком", EnF = "onion", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold" }, RuJ = "Первые советские чипсы в картонной коробке: ломтики в масле, как и руки после них. Рыбаки брали такое на лёд вместо обеда. Лучше, чем кора. Проверено.", EnJ = "The first Soviet crisps in a carton: slices in oil, and so are your hands. Fishermen took this onto the ice instead of lunch. Better than bark. Tested.", Rare = false },
        new Def { Id = "MoskovskiyBacon", Kind = Kind.Snack, Shape = "carton", Mesh = "Moskovskiy", Texture = "MoskovskiyBacon", Kg = 0.058f, Kcal = 270f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Московский картофель»", En = "Moskovskiy crisps", RuF = "с беконом", EnF = "bacon", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold" }, RuJ = "Первые советские чипсы в картонной коробке: ломтики в масле, как и руки после них. Смотритель плотины держал такое в заначке. Хруст разносится до соседней долины.", EnJ = "The first Soviet crisps in a carton: slices in oil, and so are your hands. The dam keeper kept a stash of these. The crunch carries to the next valley.", Rare = false },
        new Def { Id = "MoskovskiyPaprika", Kind = Kind.Snack, Shape = "carton", Mesh = "Moskovskiy", Texture = "MoskovskiyPaprika", Kg = 0.058f, Kcal = 270f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Московский картофель»", En = "Moskovskiy crisps", RuF = "с паприкой", EnF = "paprika", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold" }, RuJ = "Первые советские чипсы в картонной коробке: ломтики в масле, как и руки после них. Кто-то спрятал это от детей. Дети не нашли. Ешьте медленно: когда ещё такое найдёте.", EnJ = "The first Soviet crisps in a carton: slices in oil, and so are your hands. Someone hid it from the kids. The kids never found it. Eat slowly: who knows when you will find another.", Rare = false },
        new Def { Id = "BabulinyBlack", Kind = Kind.Snack, Shape = "bag", Mesh = "Babuliny", Texture = "BabulinyBlack", Kg = 0.208f, Kcal = 1160f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Бабулины»", En = "Babuliny seeds", RuF = "чёрные", EnF = "black sunflower", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Бабушка жарила на чугунной сковороде и говорила: по одной, а не горстью. В сельском магазине такое вечно заваливалось за прилавок. К этому просится пиво, а есть только талый снег.", EnJ = "Granny roasted them in a cast-iron pan and said: one at a time, not by the handful. In the village shop these kept slipping behind the counter. It begs for a beer, and there is only melted snow.", Rare = false },
        new Def { Id = "BabulinyWhite", Kind = Kind.Snack, Shape = "bag", Mesh = "Babuliny", Texture = "BabulinyWhite", Kg = 0.208f, Kcal = 1160f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Бабулины»", En = "Babuliny seeds", RuF = "белые", EnF = "white sunflower", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Бабушка жарила на чугунной сковороде и говорила: по одной, а не горстью. Ждало покупателя дольше, чем тот прожил. Сияние на вкус не влияет. Наверное.", EnJ = "Granny roasted them in a cast-iron pan and said: one at a time, not by the handful. It waited for a buyer longer than the buyer lived. The aurora does not affect the taste. Probably.", Rare = false },
        new Def { Id = "BabulinySalt", Kind = Kind.Snack, Shape = "bag", Mesh = "Babuliny", Texture = "BabulinySalt", Kg = 0.208f, Kcal = 1160f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Бабулины»", En = "Babuliny seeds", RuF = "с морской солью", EnF = "sea salted", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Бабушка жарила на чугунной сковороде и говорила: по одной, а не горстью. С материка такое больше не привезут. После тушёнки из банки это почти ресторан.", EnJ = "Granny roasted them in a cast-iron pan and said: one at a time, not by the handful. Nobody will bring this from the mainland again. After stew from a tin this is nearly a restaurant.", Rare = false },
        new Def { Id = "BabulinyPumpkin", Kind = Kind.Snack, Shape = "bag", Mesh = "Babuliny", Texture = "BabulinyPumpkin", Kg = 0.208f, Kcal = 1160f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Бабулины»", En = "Babuliny seeds", RuF = "тыквенные", EnF = "pumpkin", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Бабушка жарила на чугунной сковороде и говорила: по одной, а не горстью. На упаковке иней, внутри всё по-прежнему. Делиться не с кем, и это впервые радует.", EnJ = "Granny roasted them in a cast-iron pan and said: one at a time, not by the handful. Frost on the wrapper, business as usual inside. Nobody to share with, and for once that is good news.", Rare = false },
        new Def { Id = "BabulinyHarvest", Kind = Kind.Snack, Shape = "bag", Mesh = "Babuliny", Texture = "BabulinyHarvest", Kg = 0.208f, Kcal = 1160f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Бабулины»", En = "Babuliny seeds", RuF = "тыквенные нового урожая", EnF = "new harvest pumpkin", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Мороз ему нипочём: твёрже не стало, мягче тоже. Пальцы потом оближите: зимой калории не выбрасывают.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. The frost did nothing to it: no harder, no softer. Lick your fingers after: in winter you do not waste calories.", Rare = true },
        new Def { Id = "BabulinyMaslenitsa", Kind = Kind.Snack, Shape = "bag", Mesh = "Babuliny", Texture = "BabulinyMaslenitsa", Kg = 0.208f, Kcal = 1160f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Бабулины»", En = "Babuliny seeds", RuF = "медовые к Масленице", EnF = "honey for pancake week", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Из тех времён, когда еду выбирали по вкусу. Ворон на ветке уже ждёт свою долю.", EnJ = "A spring edition: a rare pack from the days when spring still came. From the days when people picked food for its taste. The crow on the branch is already waiting for its share.", Rare = true },
        new Def { Id = "BabulinyStriped", Kind = Kind.Snack, Shape = "bag", Mesh = "Babuliny", Texture = "BabulinyStriped", Kg = 0.208f, Kcal = 1160f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Бабулины»", En = "Babuliny seeds", RuF = "полосатые", EnF = "striped", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Бабушка жарила на чугунной сковороде и говорила: по одной, а не горстью. Чей-то перекус на ночную смену, которая не кончилась. На морозе хрустит вдвое громче.", EnJ = "Granny roasted them in a cast-iron pan and said: one at a time, not by the handful. Someone's snack for a night shift that never ended. In the frost it crunches twice as loud.", Rare = false },
        new Def { Id = "BabulinyShelled", Kind = Kind.Snack, Shape = "bag", Mesh = "Babuliny", Texture = "BabulinyShelled", Kg = 0.208f, Kcal = 1160f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Бабулины»", En = "Babuliny seeds", RuF = "очищенные", EnF = "shelled kernels", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Бабушка жарила на чугунной сковороде и говорила: по одной, а не горстью. В охотничьей вышке таким встречали рассвет. Не еда, а настроение. Настроение тоже греет.", EnJ = "Granny roasted them in a cast-iron pan and said: one at a time, not by the handful. In the hunting blind they met the dawn with this. Not food but a mood. A mood warms you too.", Rare = false },
        new Def { Id = "BabulinySmoked", Kind = Kind.Snack, Shape = "bag", Mesh = "Babuliny", Texture = "BabulinySmoked", Kg = 0.208f, Kcal = 1160f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Бабулины»", En = "Babuliny seeds", RuF = "с дымком", EnF = "smoked", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Бабушка жарила на чугунной сковороде и говорила: по одной, а не горстью. Такое носили в кармане куртки на всякий случай. Случай настал. Сытости на час, воспоминаний на неделю.", EnJ = "Granny roasted them in a cast-iron pan and said: one at a time, not by the handful. People carried these in a coat pocket just in case. The case has come. An hour of fullness, a week of memories.", Rare = false },
        new Def { Id = "BabulinyMix", Kind = Kind.Snack, Shape = "bag", Mesh = "Babuliny", Texture = "BabulinyMix", Kg = 0.208f, Kcal = 1160f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Бабулины»", En = "Babuliny seeds", RuF = "смесь семечек", EnF = "seed mix", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Бабушка жарила на чугунной сковороде и говорила: по одной, а не горстью. Прежний хозяин оставил записку: «Не трогать». Записка сгорела. Кролик смотрит с осуждением.", EnJ = "Granny roasted them in a cast-iron pan and said: one at a time, not by the handful. The last owner left a note: 'Do not touch'. The note burned. The rabbit looks on with disapproval.", Rare = false },
        new Def { Id = "BabulinyWatermelon", Kind = Kind.Snack, Shape = "bag", Mesh = "Babuliny", Texture = "BabulinyWatermelon", Kg = 0.208f, Kcal = 1160f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Бабулины»", En = "Babuliny seeds", RuF = "арбузные", EnF = "watermelon seeds", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Бабушка жарила на чугунной сковороде и говорила: по одной, а не горстью. Такими торговали в поезде, пока поезд ходил. У костра вкуснее. У костра всё вкуснее.", EnJ = "Granny roasted them in a cast-iron pan and said: one at a time, not by the handful. They sold these on the train, while the train ran. It tastes better by the fire. Everything does.", Rare = false },
        new Def { Id = "ChelnochokPoppy", Kind = Kind.Snack, Shape = "bag", Mesh = "Chelnochok", Texture = "ChelnochokPoppy", Kg = 0.208f, Kcal = 680f, Thirst = -3f, Eat = 5f, Ru = "Сушки «Челночок»", En = "Chelnochok sushki rings", RuF = "с маком", EnF = "with poppy seeds", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сушки на верёвочке: в детстве это были бусы, которые можно съесть. Сторож шахты держал такое в ящике стола. Упаковку не выбрасывайте: ею можно разжечь печь.", EnJ = "Sushki on a string: in childhood, a necklace you could eat. The mine watchman kept these in his desk drawer. Keep the wrapper: it will light the stove.", Rare = false },
        new Def { Id = "ChelnochokSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "Chelnochok", Texture = "ChelnochokSalt", Kg = 0.208f, Kcal = 680f, Thirst = -3f, Eat = 5f, Ru = "Сушки «Челночок»", En = "Chelnochok sushki rings", RuF = "с солью", EnF = "salted", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сушки на верёвочке: в детстве это были бусы, которые можно съесть. Лавина прошла мимо, срок годности тоже. Если это последняя на острове, вы её достойны.", EnJ = "Sushki on a string: in childhood, a necklace you could eat. The avalanche missed it, and so did the best-before date. If this is the last one on the island, you have earned it.", Rare = false },
        new Def { Id = "ChelnochokVanilla", Kind = Kind.Snack, Shape = "bag", Mesh = "Chelnochok", Texture = "ChelnochokVanilla", Kg = 0.208f, Kcal = 680f, Thirst = -3f, Eat = 5f, Ru = "Сушки «Челночок»", En = "Chelnochok sushki rings", RuF = "ванильные", EnF = "vanilla", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Сушки на верёвочке: в детстве это были бусы, которые можно съесть. Такое всегда стояло на видном месте, поэтому никто не брал. Желудок удивится, но возражать не станет.", EnJ = "Sushki on a string: in childhood, a necklace you could eat. These always stood in plain sight, which is why nobody took them. Your stomach will be surprised but will not object.", Rare = false },
        new Def { Id = "ChelnochokMustard", Kind = Kind.Snack, Shape = "bag", Mesh = "Chelnochok", Texture = "ChelnochokMustard", Kg = 0.208f, Kcal = 680f, Thirst = -3f, Eat = 5f, Ru = "Сушки «Челночок»", En = "Chelnochok sushki rings", RuF = "горчичные", EnF = "mustard", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Сушки на верёвочке: в детстве это были бусы, которые можно съесть. Кто-то открыл, передумал и умер. Не связано. Запах выдаёт вас за сто шагов. Оно того стоит.", EnJ = "Sushki on a string: in childhood, a necklace you could eat. Someone opened it, changed their mind and died. Unrelated. The smell gives you away at a hundred paces. Worth it.", Rare = false },
        new Def { Id = "ChelnochokEaster", Kind = Kind.Snack, Shape = "bag", Mesh = "Chelnochok", Texture = "ChelnochokEaster", Kg = 0.208f, Kcal = 680f, Thirst = -3f, Eat = 5f, Ru = "Сушки «Челночок»", En = "Chelnochok sushki rings", RuF = "пасхальные ванильные", EnF = "easter vanilla", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Такое вечно каталось под сиденьем пикапа. Раньше это называли вредным. Теперь называют едой.", EnJ = "A spring edition: a rare pack from the days when spring still came. One of these was always rolling under a pickup seat. They used to call this unhealthy. Now they call it food.", Rare = true },
        new Def { Id = "ChelnochokSesame", Kind = Kind.Snack, Shape = "bag", Mesh = "Chelnochok", Texture = "ChelnochokSesame", Kg = 0.208f, Kcal = 680f, Thirst = -3f, Eat = 5f, Ru = "Сушки «Челночок»", En = "Chelnochok sushki rings", RuF = "с кунжутом", EnF = "sesame", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сушки на верёвочке: в детстве это были бусы, которые можно съесть. Привезено паромом, которого больше нет. Спальный мешок потом вытряхните.", EnJ = "Sushki on a string: in childhood, a necklace you could eat. Brought over by a ferry that no longer exists. Shake out your sleeping bag afterwards.", Rare = false },
        new Def { Id = "ChelnochokCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Chelnochok", Texture = "ChelnochokCheese", Kg = 0.208f, Kcal = 680f, Thirst = -3f, Eat = 5f, Ru = "Сушки «Челночок»", En = "Chelnochok sushki rings", RuF = "с сыром", EnF = "cheese", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сушки на верёвочке: в детстве это были бусы, которые можно съесть. Раньше это ели под телевизор. Телевизор молчит. Зимой такое идёт за валюту.", EnJ = "Sushki on a string: in childhood, a necklace you could eat. People ate this in front of the telly. The telly is silent. In winter this passes for currency.", Rare = false },
        new Def { Id = "ChelnochokCaraway", Kind = Kind.Snack, Shape = "bag", Mesh = "Chelnochok", Texture = "ChelnochokCaraway", Kg = 0.208f, Kcal = 680f, Thirst = -3f, Eat = 5f, Ru = "Сушки «Челночок»", En = "Chelnochok sushki rings", RuF = "с тмином", EnF = "caraway", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сушки на верёвочке: в детстве это были бусы, которые можно съесть. Забыто туристами, которым повезло уехать. Торговец дал бы за это тряпку. Вы дадите больше.", EnJ = "Sushki on a string: in childhood, a necklace you could eat. Left behind by tourists who were lucky enough to leave. The trader would give a rag for it. You would give more.", Rare = false },
        new Def { Id = "ChelnochokHoney", Kind = Kind.Snack, Shape = "bag", Mesh = "Chelnochok", Texture = "ChelnochokHoney", Kg = 0.208f, Kcal = 680f, Thirst = -3f, Eat = 5f, Ru = "Сушки «Челночок»", En = "Chelnochok sushki rings", RuF = "медовые", EnF = "honey", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Сушки на верёвочке: в детстве это были бусы, которые можно съесть. Механики заедали этим обед, не вытирая рук. Пока жуёте, метель кажется короче.", EnJ = "Sushki on a string: in childhood, a necklace you could eat. Mechanics ate these for lunch without wiping their hands. While you chew, the blizzard seems shorter.", Rare = false },
        new Def { Id = "ChelnochokOnion", Kind = Kind.Snack, Shape = "bag", Mesh = "Chelnochok", Texture = "ChelnochokOnion", Kg = 0.208f, Kcal = 680f, Thirst = -3f, Eat = 5f, Ru = "Сушки «Челночок»", En = "Chelnochok sushki rings", RuF = "с луком", EnF = "onion", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сушки на верёвочке: в детстве это были бусы, которые можно съесть. Последнее на всю Одинокую топь. Скорее всего. Организм скажет спасибо. Или не скажет.", EnJ = "Sushki on a string: in childhood, a necklace you could eat. The last one in all of Forlorn Muskeg. Most likely. Your body will thank you. Or not.", Rare = false },
        new Def { Id = "BirkaGarlic", Kind = Kind.Snack, Shape = "bag", Mesh = "Birka", Texture = "BirkaGarlic", Kg = 0.068f, Kcal = 240f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Бирка»", En = "Birka croutons", RuF = "чеснок", EnF = "garlic", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Ржаные сухарики к пенному. Пенного нет, сухарики остались. Смотритель маяка грыз такое, ожидая кораблей. На третьей горсти забываешь, что вокруг конец света.", EnJ = "Rye croutons to go with beer. The beer is gone, the croutons remain. The lighthouse keeper munched these while waiting for ships. By the third handful you forget the world has ended.", Rare = false },
        new Def { Id = "BirkaHorseradish", Kind = Kind.Snack, Shape = "bag", Mesh = "Birka", Texture = "BirkaHorseradish", Kg = 0.068f, Kcal = 240f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Бирка»", En = "Birka croutons", RuF = "хрен", EnF = "horseradish", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Ржаные сухарики к пенному. Пенного нет, сухарики остались. Полки рушились, а это уцелело. Рыба подо льдом завидует.", EnJ = "Rye croutons to go with beer. The beer is gone, the croutons remain. Shelves collapsed and this survived. The fish under the ice are jealous.", Rare = false },
        new Def { Id = "BirkaAdjika", Kind = Kind.Snack, Shape = "bag", Mesh = "Birka", Texture = "BirkaAdjika", Kg = 0.068f, Kcal = 240f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Бирка»", En = "Birka croutons", RuF = "аджика", EnF = "adjika", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Ржаные сухарики к пенному. Пенного нет, сухарики остались. Смотритель заповедника называл это ужином. Олень от такого отказался бы. Олень не голодал.", EnJ = "Rye croutons to go with beer. The beer is gone, the croutons remain. The park ranger called this dinner. A deer would turn it down. A deer has never starved.", Rare = false },
        new Def { Id = "BirkaCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Birka", Texture = "BirkaCheese", Kg = 0.068f, Kcal = 240f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Бирка»", En = "Birka croutons", RuF = "сыр", EnF = "cheese", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Ржаные сухарики к пенному. Пенного нет, сухарики остались. Такое слали посылками с материка. Адресаты выбыли. Соль есть, жир есть, совести нет.", EnJ = "Rye croutons to go with beer. The beer is gone, the croutons remain. These came in parcels from the mainland. The addressees are gone. Salt: yes. Fat: yes. Conscience: none.", Rare = false },
        new Def { Id = "BirkaBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Birka", Texture = "BirkaBacon", Kg = 0.068f, Kcal = 240f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Бирка»", En = "Birka croutons", RuF = "бекон", EnF = "bacon", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Ржаные сухарики к пенному. Пенного нет, сухарики остались. Иные держали это за лекарство. Тоже лечит. Ешьте до темноты: в темноте крошки не найти.", EnJ = "Rye croutons to go with beer. The beer is gone, the croutons remain. Some people counted this as medicine. Also a cure. Eat before dark: you cannot find crumbs in the dark.", Rare = false },
        new Def { Id = "BirkaSalo", Kind = Kind.Snack, Shape = "bag", Mesh = "Birka", Texture = "BirkaSalo", Kg = 0.068f, Kcal = 240f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Бирка»", En = "Birka croutons", RuF = "сало с чесноком", EnF = "salo with garlic", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Ржаные сухарики к пенному. Пенного нет, сухарики остались. В школьном рюкзаке такое не доживало до обеда. Лучшее, что случится с вами сегодня.", EnJ = "Rye croutons to go with beer. The beer is gone, the croutons remain. In a school bag this never lasted till lunch. The best thing that will happen to you today.", Rare = false },
        new Def { Id = "BirkaCrayfish", Kind = Kind.Snack, Shape = "bag", Mesh = "Birka", Texture = "BirkaCrayfish", Kg = 0.068f, Kcal = 240f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Бирка»", En = "Birka croutons", RuF = "раки с укропом", EnF = "crayfish with dill", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Ржаные сухарики к пенному. Пенного нет, сухарики остались. Его обменяли бы на патрон, будь тут с кем меняться. Для полного счастья не хватает только дивана.", EnJ = "Rye croutons to go with beer. The beer is gone, the croutons remain. You could trade it for a cartridge, if there were anyone to trade with. All that is missing for perfect happiness is a sofa.", Rare = false },
        new Def { Id = "BirkaMustard", Kind = Kind.Snack, Shape = "bag", Mesh = "Birka", Texture = "BirkaMustard", Kg = 0.068f, Kcal = 240f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Бирка»", En = "Birka croutons", RuF = "горчица", EnF = "mustard", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Ржаные сухарики к пенному. Пенного нет, сухарики остались. На вокзале это стоило втрое дороже. Теперь даром. Вкус детства, если детство было так себе.", EnJ = "Rye croutons to go with beer. The beer is gone, the croutons remain. At the station it cost three times as much. Now it is free. The taste of childhood, if childhood was so-so.", Rare = false },
        new Def { Id = "BirkaSmelt", Kind = Kind.Snack, Shape = "bag", Mesh = "Birka", Texture = "BirkaSmelt", Kg = 0.068f, Kcal = 240f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Бирка»", En = "Birka croutons", RuF = "корюшка", EnF = "smelt", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Ржаные сухарики к пенному. Пенного нет, сухарики остались. Пережило толчок и даже не помялось. Шуршит как надежда.", EnJ = "Rye croutons to go with beer. The beer is gone, the croutons remain. It came through the quake without a dent. It rustles like hope.", Rare = false },
        new Def { Id = "KChayuSweet", Kind = Kind.Snack, Shape = "carton", Mesh = "KChayu", Texture = "KChayuSweet", Kg = 0.208f, Kcal = 780f, Thirst = -3f, Eat = 4f, Ru = "Соломка «К чаю»", En = "K Chayu sticks", RuF = "сладкая", EnF = "sweet", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Соломка «К чаю»: её макали в стакан в подстаканнике и молчали о важном. Китобои такого не ели, но оценили бы. Голод отступит, жажда придёт. Честный обмен.", EnJ = "Sticks ‘for tea’: dipped into a glass in a holder while keeping quiet about what matters. The whalers never ate this, but they would have approved. Hunger leaves, thirst arrives. A fair trade.", Rare = false },
        new Def { Id = "KChayuSalt", Kind = Kind.Snack, Shape = "carton", Mesh = "KChayu", Texture = "KChayuSalt", Kg = 0.208f, Kcal = 780f, Thirst = -3f, Eat = 4f, Ru = "Соломка «К чаю»", En = "K Chayu sticks", RuF = "солёная", EnF = "salted", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Соломка «К чаю»: её макали в стакан в подстаканнике и молчали о важном. Осталось после чьего-то дня рождения. Гости не пришли. Не согреет, зато отвлечёт.", EnJ = "Sticks ‘for tea’: dipped into a glass in a holder while keeping quiet about what matters. Left over from someone's birthday. The guests never came. It will not warm you, but it will distract you.", Rare = false },
        new Def { Id = "KChayuPoppy", Kind = Kind.Snack, Shape = "carton", Mesh = "KChayu", Texture = "KChayuPoppy", Kg = 0.208f, Kcal = 780f, Thirst = -3f, Eat = 4f, Ru = "Соломка «К чаю»", En = "K Chayu sticks", RuF = "с маком", EnF = "with poppy seeds", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Соломка «К чаю»: её макали в стакан в подстаканнике и молчали о важном. Мерзлота хранит лучше любого холодильника. Пума предпочитает мясо. Вам повезло.", EnJ = "Sticks ‘for tea’: dipped into a glass in a holder while keeping quiet about what matters. Permafrost keeps things better than any fridge. The cougar prefers meat. Lucky you.", Rare = false },
        new Def { Id = "KChayuVanilla", Kind = Kind.Snack, Shape = "carton", Mesh = "KChayu", Texture = "KChayuVanilla", Kg = 0.208f, Kcal = 780f, Thirst = -3f, Eat = 4f, Ru = "Соломка «К чаю»", En = "K Chayu sticks", RuF = "ванильная", EnF = "vanilla", RuC = "СССР", EnC = "USSR", Fx = new[] { "SugarDry" }, RuJ = "Соломка «К чаю»: её макали в стакан в подстаканнике и молчали о важном. Такое добывали из автомата, который съедал последнюю монету. Сначала попробуйте одну штучку. Шутка: ешьте всё.", EnJ = "Sticks ‘for tea’: dipped into a glass in a holder while keeping quiet about what matters. These came from the vending machine that ate your last coin. Try just one first. Joke: eat the lot.", Rare = false },
        new Def { Id = "KChayuSesame", Kind = Kind.Snack, Shape = "carton", Mesh = "KChayu", Texture = "KChayuSesame", Kg = 0.208f, Kcal = 780f, Thirst = -3f, Eat = 4f, Ru = "Соломка «К чаю»", En = "K Chayu sticks", RuF = "с кунжутом", EnF = "sesame", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Соломка «К чаю»: её макали в стакан в подстаканнике и молчали о важном. Такое брали в лодку под брезент, на весь день. Такой ужин не стыдно записать в дневник.", EnJ = "Sticks ‘for tea’: dipped into a glass in a holder while keeping quiet about what matters. People took these out in the boat under the tarpaulin, for the whole day. A dinner worth writing in the journal.", Rare = false },
        new Def { Id = "KChayuCaraway", Kind = Kind.Snack, Shape = "carton", Mesh = "KChayu", Texture = "KChayuCaraway", Kg = 0.208f, Kcal = 780f, Thirst = -3f, Eat = 4f, Ru = "Соломка «К чаю»", En = "K Chayu sticks", RuF = "с тмином", EnF = "caraway", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Соломка «К чаю»: её макали в стакан в подстаканнике и молчали о важном. С ним кто-то шёл к перевалу и не дошёл. Силы прибавит на один сугроб.", EnJ = "Sticks ‘for tea’: dipped into a glass in a holder while keeping quiet about what matters. Someone carried it towards the pass and never arrived. It will carry you one snowdrift further.", Rare = false },
        new Def { Id = "KChayuCheese", Kind = Kind.Snack, Shape = "carton", Mesh = "KChayu", Texture = "KChayuCheese", Kg = 0.208f, Kcal = 780f, Thirst = -3f, Eat = 4f, Ru = "Соломка «К чаю»", En = "K Chayu sticks", RuF = "сырная", EnF = "cheese", RuC = "СССР", EnC = "USSR", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Соломка «К чаю»: её макали в стакан в подстаканнике и молчали о важном. С таким сидели у окна с видом на метель. Идеально к закату, которого не видно за бураном.", EnJ = "Sticks ‘for tea’: dipped into a glass in a holder while keeping quiet about what matters. People sat with these at a window with a view of the blizzard. Perfect with a sunset you cannot see for the storm.", Rare = false },
        new Def { Id = "KarubiUsushio", Kind = Kind.Snack, Shape = "bag", Mesh = "Karubi", Texture = "KarubiUsushio", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби»", En = "Karubi crisps", RuF = "лёгкая соль", EnF = "lightly salted", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Японские чипсы: нарезаны так тонко, что сквозь ломтик видно будущее. Уцелело там, где сгорело всё остальное. Пахнет магазином. Помните магазины?", EnJ = "Japanese crisps: sliced so thin you can see the future through one. It survived where everything else burned. It smells of a shop. Remember shops?", Rare = false },
        new Def { Id = "KarubiConsomme", Kind = Kind.Snack, Shape = "bag", Mesh = "Karubi", Texture = "KarubiConsomme", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби»", En = "Karubi crisps", RuF = "консоме", EnF = "consomme punch", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Японские чипсы: нарезаны так тонко, что сквозь ломтик видно будущее. Этим кормили сторожевого пса. Пёс ушёл в волки. Мороз не испортил, время не взяло.", EnJ = "Japanese crisps: sliced so thin you can see the future through one. They fed the guard dog with this. The dog joined the wolves. Frost did not spoil it and time could not take it.", Rare = false },
        new Def { Id = "KarubiNorishio", Kind = Kind.Snack, Shape = "bag", Mesh = "Karubi", Texture = "KarubiNorishio", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби»", En = "Karubi crisps", RuF = "нори и соль", EnF = "seaweed salt", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Японские чипсы: нарезаны так тонко, что сквозь ломтик видно будущее. Из запасов лесорубов: брали ящиками. В рюкзаке не мнётся. Почти.", EnJ = "Japanese crisps: sliced so thin you can see the future through one. From the loggers' stores: they bought it by the crate. It does not get crushed in a pack. Almost.", Rare = false },
        new Def { Id = "KarubiShoyu", Kind = Kind.Snack, Shape = "bag", Mesh = "Karubi", Texture = "KarubiShoyu", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби»", En = "Karubi crisps", RuF = "соевый соус", EnF = "soy sauce", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Японские чипсы: нарезаны так тонко, что сквозь ломтик видно будущее. В пост такое не ели. Пост кончился вместе с миром. Съешьте сейчас: завтра может не быть аппетита.", EnJ = "Japanese crisps: sliced so thin you can see the future through one. Nobody ate these during a fast. The fast ended with the world. Eat it now: tomorrow you may have no appetite.", Rare = false },
        new Def { Id = "KarubiSakura", Kind = Kind.Snack, Shape = "bag", Mesh = "Karubi", Texture = "KarubiSakura", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби»", En = "Karubi crisps", RuF = "соль с сакурой", EnF = "sakura salt", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Теперь это ценнее денег. Деньги оставьте. Хватит дойти до следующей хижины и пожалеть, что кончилось.", EnJ = "A spring edition: a rare pack from the days when spring still came. It is worth more than money now. Leave the money. Enough to reach the next cabin and regret it is gone.", Rare = true },
        new Def { Id = "KarubiYuzu", Kind = Kind.Snack, Shape = "bag", Mesh = "Karubi", Texture = "KarubiYuzu", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби»", En = "Karubi crisps", RuF = "зимний юдзу с перцем", EnF = "winter yuzu pepper", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Зимняя серия: выпускали на один сезон, а зима тут навсегда. Его несли на пикник. Пикник отменили навсегда. От такого не толстеют те, кто ходит по двадцать километров.", EnJ = "A winter edition: made for one season, and here winter is forever. It was headed for a picnic. The picnic is cancelled forever. Nobody who walks twenty kilometres a day gets fat on this.", Rare = true },
        new Def { Id = "KarubiMomiji", Kind = Kind.Snack, Shape = "bag", Mesh = "Karubi", Texture = "KarubiMomiji", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби»", En = "Karubi crisps", RuF = "осенний батат", EnF = "autumn sweet potato", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Такое стояло у кассы на случай слабости. Волчья стая не в курсе. Пусть так и будет.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. These stood by the till for moments of weakness. The wolf pack does not know. Keep it that way.", Rare = true },
        new Def { Id = "KarubiNatsu", Kind = Kind.Snack, Shape = "bag", Mesh = "Karubi", Texture = "KarubiNatsu", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби»", En = "Karubi crisps", RuF = "летний лимон с солью", EnF = "summer salted lemon", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Досталось вам, потому что вы дошли первым. Хрустеть в засаде не рекомендуется.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. It is yours because you got here first. Crunching in an ambush is not recommended.", Rare = true },
        new Def { Id = "KarubiButter", Kind = Kind.Snack, Shape = "bag", Mesh = "Karubi", Texture = "KarubiButter", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби»", En = "Karubi crisps", RuF = "масло и соевый соус", EnF = "butter soy sauce", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Японские чипсы: нарезаны так тонко, что сквозь ломтик видно будущее. Упаковка выцвела, внутри время остановилось. Лекарство от тоски, отпускается без рецепта.", EnJ = "Japanese crisps: sliced so thin you can see the future through one. The wrapper has faded; inside, time stood still. A cure for the blues, no prescription needed.", Rare = false },
        new Def { Id = "KarubiPizza", Kind = Kind.Snack, Shape = "bag", Mesh = "Karubi", Texture = "KarubiPizza", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби»", En = "Karubi crisps", RuF = "пицца", EnF = "pizza", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Японские чипсы: нарезаны так тонко, что сквозь ломтик видно будущее. Из чемодана пассажира, который не долетел. Жуйте и думайте о хорошем. Например, о добавке.", EnJ = "Japanese crisps: sliced so thin you can see the future through one. From the suitcase of a passenger who never landed. Chew and think of nice things. Seconds, for example.", Rare = false },
        new Def { Id = "KarubiWasabi", Kind = Kind.Snack, Shape = "bag", Mesh = "Karubi", Texture = "KarubiWasabi", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби»", En = "Karubi crisps", RuF = "васаби", EnF = "wasabi", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Японские чипсы: нарезаны так тонко, что сквозь ломтик видно будущее. Перезимовало и ничуть не обиделось. К утру от него останется только запах на варежках.", EnJ = "Japanese crisps: sliced so thin you can see the future through one. It made it through the winter and bears no grudge. By morning only the smell on your mittens will be left.", Rare = false },
        new Def { Id = "KarubiPlum", Kind = Kind.Snack, Shape = "bag", Mesh = "Karubi", Texture = "KarubiPlum", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби»", En = "Karubi crisps", RuF = "слива умэ", EnF = "pickled plum", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Японские чипсы: нарезаны так тонко, что сквозь ломтик видно будущее. Запасливая хозяйка купила по акции шесть штук. Тишина вокруг такая, что слышно, как вы жуёте.", EnJ = "Japanese crisps: sliced so thin you can see the future through one. A thrifty housewife bought six of these on offer. It is so quiet you can hear yourself chew.", Rare = false },
        new Def { Id = "KarubiCurry", Kind = Kind.Snack, Shape = "bag", Mesh = "Karubi", Texture = "KarubiCurry", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби»", En = "Karubi crisps", RuF = "карри", EnF = "curry", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Японские чипсы: нарезаны так тонко, что сквозь ломтик видно будущее. Кто-то написал на упаковке «моё». Уже нет. Не делите на завтра: завтра будет новый голод.", EnJ = "Japanese crisps: sliced so thin you can see the future through one. Someone wrote 'mine' on it. Not any more. Do not save half for tomorrow: tomorrow brings its own hunger.", Rare = false },
        new Def { Id = "KarubiGarlic", Kind = Kind.Snack, Shape = "bag", Mesh = "Karubi", Texture = "KarubiGarlic", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби»", En = "Karubi crisps", RuF = "чеснок", EnF = "garlic", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Японские чипсы: нарезаны так тонко, что сквозь ломтик видно будущее. В консервном цеху это ели тайком от мастера. Сосны вокруг делают вид, что не смотрят.", EnJ = "Japanese crisps: sliced so thin you can see the future through one. At the cannery they ate this behind the foreman's back. The pines around pretend not to watch.", Rare = false },
        new Def { Id = "EbisenOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "Ebisen", Texture = "EbisenOriginal", Kg = 0.093f, Kcal = 420f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Эбисэн»", En = "Ebisen shrimp chips", RuF = "креветка", EnF = "shrimp", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Креветочные палочки: остановиться невозможно, это написано прямо на пачке. Его не взяли даже мародёры. Они спешили. Калории мелкие, зато свои.", EnJ = "Shrimp sticks: you can't stop, it says so right on the pack. Even the looters left it. They were in a hurry. Small calories, but your own.", Rare = false },
        new Def { Id = "EbisenWasabi", Kind = Kind.Snack, Shape = "bag", Mesh = "Ebisen", Texture = "EbisenWasabi", Kg = 0.093f, Kcal = 420f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Эбисэн»", En = "Ebisen shrimp chips", RuF = "васаби", EnF = "wasabi", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Креветочные палочки: остановиться невозможно, это написано прямо на пачке. Провело зиму на острове, как и вы. После этого даже крапивный чай покажется десертом.", EnJ = "Shrimp sticks: you can't stop, it says so right on the pack. It spent the winter on the island, same as you. After this even nettle tea feels like dessert.", Rare = false },
        new Def { Id = "EbisenUme", Kind = Kind.Snack, Shape = "bag", Mesh = "Ebisen", Texture = "EbisenUme", Kg = 0.093f, Kcal = 420f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Эбисэн»", En = "Ebisen shrimp chips", RuF = "слива умэ", EnF = "pickled plum", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Креветочные палочки: остановиться невозможно, это написано прямо на пачке. Дети прятали такое под кроватью, в тайнике. Нашедшему полагается всё.", EnJ = "Shrimp sticks: you can't stop, it says so right on the pack. Children hid these under the bed, in a secret place. Finders keepers, all of it.", Rare = false },
        new Def { Id = "EbisenNewYear", Kind = Kind.Snack, Shape = "bag", Mesh = "Ebisen", Texture = "EbisenNewYear", Kg = 0.093f, Kcal = 420f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Эбисэн»", En = "Ebisen shrimp chips", RuF = "новогодняя красная креветка", EnF = "new year red shrimp", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Новогодняя серия: куранты отбили, а пачка осталась. Редкость. Осталось от геологов вместе с картой и долгами. Зубы целы? Тогда вперёд.", EnJ = "A New Year edition: the clock has struck, the pack remains. A rarity. Left by the geologists along with a map and some debts. Teeth intact? Then go ahead.", Rare = true },
        new Def { Id = "EbisenCurry", Kind = Kind.Snack, Shape = "bag", Mesh = "Ebisen", Texture = "EbisenCurry", Kg = 0.093f, Kcal = 420f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Эбисэн»", En = "Ebisen shrimp chips", RuF = "карри", EnF = "curry", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Креветочные палочки: остановиться невозможно, это написано прямо на пачке. На острове такое было праздником и до катастрофы. Ночью приснится добавка.", EnJ = "Shrimp sticks: you can't stop, it says so right on the pack. On the island this was a treat even before the disaster. Tonight you will dream of seconds.", Rare = false },
        new Def { Id = "EbisenMayo", Kind = Kind.Snack, Shape = "bag", Mesh = "Ebisen", Texture = "EbisenMayo", Kg = 0.093f, Kcal = 420f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Эбисэн»", En = "Ebisen shrimp chips", RuF = "майонез", EnF = "mayonnaise", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Креветочные палочки: остановиться невозможно, это написано прямо на пачке. С таким слушали радио, которое теперь ловит только треск. С таким запасом можно пережить ещё один вечер.", EnJ = "Shrimp sticks: you can't stop, it says so right on the pack. People ate these by the radio, which picks up nothing but crackle now. With supplies like this you can survive one more evening.", Rare = false },
        new Def { Id = "EbisenNori", Kind = Kind.Snack, Shape = "bag", Mesh = "Ebisen", Texture = "EbisenNori", Kg = 0.093f, Kcal = 420f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Эбисэн»", En = "Ebisen shrimp chips", RuF = "нори", EnF = "seaweed", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Креветочные палочки: остановиться невозможно, это написано прямо на пачке. Крысы прогрызли соседнюю, эту пощадили. Пёс бы выпросил половину. Пса нет.", EnJ = "Shrimp sticks: you can't stop, it says so right on the pack. The rats gnawed through the one next to it and spared this. A dog would beg half of it. There is no dog.", Rare = false },
        new Def { Id = "EbisenGarlic", Kind = Kind.Snack, Shape = "bag", Mesh = "Ebisen", Texture = "EbisenGarlic", Kg = 0.093f, Kcal = 420f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Эбисэн»", En = "Ebisen shrimp chips", RuF = "чеснок", EnF = "garlic", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Креветочные палочки: остановиться невозможно, это написано прямо на пачке. Бывший хозяин клялся бросить. Не успел. Съедено будет быстрее, чем найдено.", EnJ = "Shrimp sticks: you can't stop, it says so right on the pack. The former owner swore to give these up. He ran out of time. It will be eaten faster than it was found.", Rare = false },
        new Def { Id = "EbisenKimchi", Kind = Kind.Snack, Shape = "bag", Mesh = "Ebisen", Texture = "EbisenKimchi", Kg = 0.093f, Kcal = 420f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Эбисэн»", En = "Ebisen shrimp chips", RuF = "кимчи", EnF = "kimchi", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Креветочные палочки: остановиться невозможно, это написано прямо на пачке. Его катали в кабине трактора три сезона. На вкус как выходной.", EnJ = "Shrimp sticks: you can't stop, it says so right on the pack. It rode around in a tractor cab for three seasons. It tastes like a day off.", Rare = false },
        new Def { Id = "PokiChoco", Kind = Kind.Snack, Shape = "carton", Mesh = "Poki", Texture = "PokiChoco", Kg = 0.078f, Kcal = 350f, Thirst = -2f, Eat = 4f, Ru = "Палочки в глазури «Поки»", En = "Poki coated biscuit sticks", RuF = "шоколад", EnF = "chocolate", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Палочки в глазури: один конец без шоколада, чтобы руки остались чистыми. Не остались. После бани такое шло лучше всего. Ветер унесёт запах прямо к берлоге. Ешьте быстрее.", EnJ = "Coated sticks: one end left bare to keep your hands clean. It didn't. Nothing went down better after the sauna. The wind carries the smell straight to the den. Eat faster.", Rare = false },
        new Def { Id = "PokiStrawberry", Kind = Kind.Snack, Shape = "carton", Mesh = "Poki", Texture = "PokiStrawberry", Kg = 0.078f, Kcal = 350f, Thirst = -2f, Eat = 4f, Ru = "Палочки в глазури «Поки»", En = "Poki coated biscuit sticks", RuF = "клубника", EnF = "strawberry", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Палочки в глазури: один конец без шоколада, чтобы руки остались чистыми. Не остались. В тюрьме на это выменивали что угодно. Проверено поколениями и одной катастрофой.", EnJ = "Coated sticks: one end left bare to keep your hands clean. It didn't. In the prison you could trade one of these for anything. Tested by generations and one catastrophe.", Rare = false },
        new Def { Id = "PokiMatcha", Kind = Kind.Snack, Shape = "carton", Mesh = "Poki", Texture = "PokiMatcha", Kg = 0.078f, Kcal = 350f, Thirst = -2f, Eat = 4f, Ru = "Палочки в глазури «Поки»", En = "Poki coated biscuit sticks", RuF = "чай матча", EnF = "matcha", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Палочки в глазури: один конец без шоколада, чтобы руки остались чистыми. Не остались. Кто-то менял это на сигареты. Сделка сорвалась. Хорошо идёт под треск поленьев.", EnJ = "Coated sticks: one end left bare to keep your hands clean. It didn't. Someone was trading this for cigarettes. The deal fell through. Goes down well with crackling logs.", Rare = false },
        new Def { Id = "PokiAlmond", Kind = Kind.Snack, Shape = "carton", Mesh = "Poki", Texture = "PokiAlmond", Kg = 0.078f, Kcal = 350f, Thirst = -2f, Eat = 4f, Ru = "Палочки в глазури «Поки»", En = "Poki coated biscuit sticks", RuF = "миндаль", EnF = "almond crush", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Палочки в глазури: один конец без шоколада, чтобы руки остались чистыми. Не остались. С ним зимовали на метеостанции, пока было с кем. Руки вытирать о штаны: салфеток не завезли.", EnJ = "Coated sticks: one end left bare to keep your hands clean. It didn't. They wintered with it at the weather station, while there was a 'they'. Wipe your hands on your trousers: no napkins were delivered.", Rare = false },
        new Def { Id = "PokiSakura", Kind = Kind.Snack, Shape = "carton", Mesh = "Poki", Texture = "PokiSakura", Kg = 0.078f, Kcal = 350f, Thirst = -2f, Eat = 4f, Ru = "Палочки в глазури «Поки»", En = "Poki coated biscuit sticks", RuF = "сакура и матча", EnF = "sakura matcha", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Такое терялось в кладовке среди крупы и надежд. Маленькая радость размером с ладонь.", EnJ = "A spring edition: a rare pack from the days when spring still came. These got lost in the pantry among the grain and the hopes. A small joy the size of your palm.", Rare = true },
        new Def { Id = "PokiWinter", Kind = Kind.Snack, Shape = "carton", Mesh = "Poki", Texture = "PokiWinter", Kg = 0.078f, Kcal = 350f, Thirst = -2f, Eat = 4f, Ru = "Палочки в глазури «Поки»", En = "Poki coated biscuit sticks", RuF = "зимнее тающее какао", EnF = "winter melty cocoa", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Зимняя серия: выпускали на один сезон, а зима тут навсегда. Его берегли к приезду внуков. Совесть молчит, живот поёт.", EnJ = "A winter edition: made for one season, and here winter is forever. It was being saved for the grandchildren's visit. Conscience is silent, the belly sings.", Rare = true },
        new Def { Id = "PokiValentine", Kind = Kind.Snack, Shape = "carton", Mesh = "Poki", Texture = "PokiValentine", Kg = 0.078f, Kcal = 350f, Thirst = -2f, Eat = 4f, Ru = "Палочки в глазури «Поки»", En = "Poki coated biscuit sticks", RuF = "клубничное сердце", EnF = "strawberry heart", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Серия для влюблённых: редкость. Делить не с кем, зато вся ваша. В баре такое ставили на стойку, бесплатно к пиву. Пива нет. Проверено поколениями и одной катастрофой.", EnJ = "A Valentine edition: a rarity. No one to share it with, so it is all yours. Bars put these out free with a beer. There is no beer. Tested by generations and one catastrophe.", Rare = true },
        new Def { Id = "PokiSummer", Kind = Kind.Snack, Shape = "carton", Mesh = "Poki", Texture = "PokiSummer", Kg = 0.078f, Kcal = 350f, Thirst = -2f, Eat = 4f, Ru = "Палочки в глазури «Поки»", En = "Poki coated biscuit sticks", RuF = "летний кокос", EnF = "summer coconut", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Такое лежало в каждом доме, пока не погас свет. Оставьте пару штук на перевал. Не оставите.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. Every house had one of these until the lights went out. Save a couple for the pass. You will not.", Rare = true },
        new Def { Id = "PokiAutumn", Kind = Kind.Snack, Shape = "carton", Mesh = "Poki", Texture = "PokiAutumn", Kg = 0.078f, Kcal = 350f, Thirst = -2f, Eat = 4f, Ru = "Палочки в глазури «Поки»", En = "Poki coated biscuit sticks", RuF = "осенний каштан", EnF = "autumn chestnut", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Кто-то берёг это на чёрный день. Он настал. Здесь это считается ужином при свечах.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. Someone saved this for a rainy day. It came. Round here this counts as a candlelit dinner.", Rare = true },
        new Def { Id = "PokiMilk", Kind = Kind.Snack, Shape = "carton", Mesh = "Poki", Texture = "PokiMilk", Kg = 0.078f, Kcal = 350f, Thirst = -2f, Eat = 4f, Ru = "Палочки в глазури «Поки»", En = "Poki coated biscuit sticks", RuF = "молочный", EnF = "milky", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Палочки в глазури: один конец без шоколада, чтобы руки остались чистыми. Не остались. Пережило хозяина, кота и две зимы. Запейте чаем из шиповника и считайте это обедом.", EnJ = "Coated sticks: one end left bare to keep your hands clean. It didn't. It outlived its owner, the cat and two winters. Wash it down with rosehip tea and call it lunch.", Rare = false },
        new Def { Id = "PokiCookie", Kind = Kind.Snack, Shape = "carton", Mesh = "Poki", Texture = "PokiCookie", Kg = 0.078f, Kcal = 350f, Thirst = -2f, Eat = 4f, Ru = "Палочки в глазури «Поки»", En = "Poki coated biscuit sticks", RuF = "печенье и крем", EnF = "cookies & cream", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Палочки в глазури: один конец без шоколада, чтобы руки остались чистыми. Не остались. Такое обычно находили за диваном, как всё лучшее в жизни. Медведю не показывать: отнимет вместе с рукой.", EnJ = "Coated sticks: one end left bare to keep your hands clean. It didn't. These were usually found behind the sofa, like all the best things in life. Do not show the bear: he will take it, hand and all.", Rare = false },
        new Def { Id = "PokiBanana", Kind = Kind.Snack, Shape = "carton", Mesh = "Poki", Texture = "PokiBanana", Kg = 0.078f, Kcal = 350f, Thirst = -2f, Eat = 4f, Ru = "Палочки в глазури «Поки»", En = "Poki coated biscuit sticks", RuF = "шоколадный банан", EnF = "chocolate banana", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Палочки в глазури: один конец без шоколада, чтобы руки остались чистыми. Не остались. Последний завоз был до того, как упали самолёты. Больше таких не делают. Совсем.", EnJ = "Coated sticks: one end left bare to keep your hands clean. It didn't. The last delivery came before the planes fell. They do not make these any more. At all.", Rare = false },
        new Def { Id = "PokiCoconut", Kind = Kind.Snack, Shape = "carton", Mesh = "Poki", Texture = "PokiCoconut", Kg = 0.078f, Kcal = 350f, Thirst = -2f, Eat = 4f, Ru = "Палочки в глазури «Поки»", En = "Poki coated biscuit sticks", RuF = "кокос", EnF = "coconut", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Палочки в глазури: один конец без шоколада, чтобы руки остались чистыми. Не остались. Ценник оторван: теперь это бесценно. Открывайте тихо: у волков отличный слух.", EnJ = "Coated sticks: one end left bare to keep your hands clean. It didn't. The price tag is torn off: it is priceless now. Open it quietly: wolves have excellent hearing.", Rare = false },
        new Def { Id = "PokiBitter", Kind = Kind.Snack, Shape = "carton", Mesh = "Poki", Texture = "PokiBitter", Kg = 0.078f, Kcal = 350f, Thirst = -2f, Eat = 4f, Ru = "Палочки в глазури «Поки»", En = "Poki coated biscuit sticks", RuF = "горький шоколад", EnF = "dark chocolate", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Палочки в глазури: один конец без шоколада, чтобы руки остались чистыми. Не остались. Дата на шве стёрлась, и слава богу. Одной не обойдётся, но вторая неизвестно где.", EnJ = "Coated sticks: one end left bare to keep your hands clean. It didn't. The date on the seam has rubbed off, thank goodness. One won't be enough, and nobody knows where the second is.", Rare = false },
        new Def { Id = "PokiMelon", Kind = Kind.Snack, Shape = "carton", Mesh = "Poki", Texture = "PokiMelon", Kg = 0.078f, Kcal = 350f, Thirst = -2f, Eat = 4f, Ru = "Палочки в глазури «Поки»", En = "Poki coated biscuit sticks", RuF = "дыня", EnF = "melon", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Палочки в глазури: один конец без шоколада, чтобы руки остались чистыми. Не остались. Пахнет заправкой у Прибрежного шоссе. Крошки с пола тоже считаются.", EnJ = "Coated sticks: one end left bare to keep your hands clean. It didn't. It smells of the petrol station on the Coastal Highway. The crumbs on the floor count too.", Rare = false },
        new Def { Id = "PokiBlueberry", Kind = Kind.Snack, Shape = "carton", Mesh = "Poki", Texture = "PokiBlueberry", Kg = 0.078f, Kcal = 350f, Thirst = -2f, Eat = 4f, Ru = "Палочки в глазури «Поки»", En = "Poki coated biscuit sticks", RuF = "черника", EnF = "blueberry", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Палочки в глазури: один конец без шоколада, чтобы руки остались чистыми. Не остались. Такое возили в бардачке на дальнюю дорогу. Дороги кончились. Запейте чаем из шиповника и считайте это обедом.", EnJ = "Coated sticks: one end left bare to keep your hands clean. It didn't. People kept these in the glovebox for long drives. The drives are over. Wash it down with rosehip tea and call it lunch.", Rare = false },
        new Def { Id = "KakipiOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "Kakipi", Texture = "KakipiOriginal", Kg = 0.098f, Kcal = 360f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Каки-пи»", En = "Kaki-pi rice crackers", RuF = "соевый соус", EnF = "soy sauce", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Рисовые полумесяцы с арахисом: японцы всерьёз спорят, шесть к четырём или семь к трём. Мыши не тронули. Думайте сами. Медведю не показывать: отнимет вместе с рукой.", EnJ = "Rice crescents with peanuts: the Japanese seriously argue whether it's six to four or seven to three. The mice left it alone. Draw your own conclusions. Do not show the bear: he will take it, hand and all.", Rare = false },
        new Def { Id = "KakipiWasabi", Kind = Kind.Snack, Shape = "bag", Mesh = "Kakipi", Texture = "KakipiWasabi", Kg = 0.098f, Kcal = 360f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Каки-пи»", En = "Kaki-pi rice crackers", RuF = "васаби", EnF = "wasabi", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Рисовые полумесяцы с арахисом: японцы всерьёз спорят, шесть к четырём или семь к трём. Рыбаки брали такое на лёд вместо обеда. Диетолог не одобрил бы. Диетолога тут нет.", EnJ = "Rice crescents with peanuts: the Japanese seriously argue whether it's six to four or seven to three. Fishermen took this onto the ice instead of lunch. A dietitian would not approve. There is no dietitian here.", Rare = false },
        new Def { Id = "KakipiUme", Kind = Kind.Snack, Shape = "bag", Mesh = "Kakipi", Texture = "KakipiUme", Kg = 0.098f, Kcal = 360f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Каки-пи»", En = "Kaki-pi rice crackers", RuF = "слива умэ", EnF = "plum", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Рисовые полумесяцы с арахисом: японцы всерьёз спорят, шесть к четырём или семь к трём. Смотритель плотины держал такое в заначке. Лучше, чем кора. Проверено.", EnJ = "Rice crescents with peanuts: the Japanese seriously argue whether it's six to four or seven to three. The dam keeper kept a stash of these. Better than bark. Tested.", Rare = false },
        new Def { Id = "KakipiBlossom", Kind = Kind.Snack, Shape = "bag", Mesh = "Kakipi", Texture = "KakipiBlossom", Kg = 0.098f, Kcal = 360f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Каки-пи»", En = "Kaki-pi rice crackers", RuF = "цветущая слива", EnF = "plum blossom", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Кто-то спрятал это от детей. Дети не нашли. Хруст разносится до соседней долины.", EnJ = "A spring edition: a rare pack from the days when spring still came. Someone hid it from the kids. The kids never found it. The crunch carries to the next valley.", Rare = true },
        new Def { Id = "KakipiChili", Kind = Kind.Snack, Shape = "bag", Mesh = "Kakipi", Texture = "KakipiChili", Kg = 0.098f, Kcal = 360f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Каки-пи»", En = "Kaki-pi rice crackers", RuF = "острые", EnF = "spicy", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Рисовые полумесяцы с арахисом: японцы всерьёз спорят, шесть к четырём или семь к трём. В сельском магазине такое вечно заваливалось за прилавок. Ешьте медленно: когда ещё такое найдёте.", EnJ = "Rice crescents with peanuts: the Japanese seriously argue whether it's six to four or seven to three. In the village shop these kept slipping behind the counter. Eat slowly: who knows when you will find another.", Rare = false },
        new Def { Id = "KakipiSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "Kakipi", Texture = "KakipiSalt", Kg = 0.098f, Kcal = 360f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Каки-пи»", En = "Kaki-pi rice crackers", RuF = "соль", EnF = "salted", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Рисовые полумесяцы с арахисом: японцы всерьёз спорят, шесть к четырём или семь к трём. Ждало покупателя дольше, чем тот прожил. К этому просится пиво, а есть только талый снег.", EnJ = "Rice crescents with peanuts: the Japanese seriously argue whether it's six to four or seven to three. It waited for a buyer longer than the buyer lived. It begs for a beer, and there is only melted snow.", Rare = false },
        new Def { Id = "KakipiCurry", Kind = Kind.Snack, Shape = "bag", Mesh = "Kakipi", Texture = "KakipiCurry", Kg = 0.098f, Kcal = 360f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Каки-пи»", En = "Kaki-pi rice crackers", RuF = "карри", EnF = "curry", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Рисовые полумесяцы с арахисом: японцы всерьёз спорят, шесть к четырём или семь к трём. С материка такое больше не привезут. Сияние на вкус не влияет. Наверное.", EnJ = "Rice crescents with peanuts: the Japanese seriously argue whether it's six to four or seven to three. Nobody will bring this from the mainland again. The aurora does not affect the taste. Probably.", Rare = false },
        new Def { Id = "KakipiMentai", Kind = Kind.Snack, Shape = "bag", Mesh = "Kakipi", Texture = "KakipiMentai", Kg = 0.098f, Kcal = 360f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Каки-пи»", En = "Kaki-pi rice crackers", RuF = "икра минтая", EnF = "spicy cod roe", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Рисовые полумесяцы с арахисом: японцы всерьёз спорят, шесть к четырём или семь к трём. На упаковке иней, внутри всё по-прежнему. После тушёнки из банки это почти ресторан.", EnJ = "Rice crescents with peanuts: the Japanese seriously argue whether it's six to four or seven to three. Frost on the wrapper, business as usual inside. After stew from a tin this is nearly a restaurant.", Rare = false },
        new Def { Id = "KakipiCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Kakipi", Texture = "KakipiCheese", Kg = 0.098f, Kcal = 360f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Каки-пи»", En = "Kaki-pi rice crackers", RuF = "сыр", EnF = "cheese", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Рисовые полумесяцы с арахисом: японцы всерьёз спорят, шесть к четырём или семь к трём. Мороз ему нипочём: твёрже не стало, мягче тоже. Делиться не с кем, и это впервые радует.", EnJ = "Rice crescents with peanuts: the Japanese seriously argue whether it's six to four or seven to three. The frost did nothing to it: no harder, no softer. Nobody to share with, and for once that is good news.", Rare = false },
        new Def { Id = "JagarikoSalad", Kind = Kind.Snack, Shape = "cup", Mesh = "Jagariko", Texture = "JagarikoSalad", Kg = 0.09f, Kcal = 300f, Thirst = -7f, Eat = 4f, Ru = "Картофельные палочки «Дзягарико»", En = "Jagariko potato sticks", RuF = "салат", EnF = "salad", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Стакан с жирафом: палочки хрустят «дзяга-дзяга», жираф ни при чём. Из тех времён, когда еду выбирали по вкусу. Пальцы потом оближите: зимой калории не выбрасывают.", EnJ = "A cup with a giraffe: the sticks go ‘jaga-jaga’, the giraffe has nothing to do with it. From the days when people picked food for its taste. Lick your fingers after: in winter you do not waste calories.", Rare = false },
        new Def { Id = "JagarikoCheese", Kind = Kind.Snack, Shape = "cup", Mesh = "Jagariko", Texture = "JagarikoCheese", Kg = 0.09f, Kcal = 300f, Thirst = -7f, Eat = 4f, Ru = "Картофельные палочки «Дзягарико»", En = "Jagariko potato sticks", RuF = "сыр", EnF = "cheese", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Стакан с жирафом: палочки хрустят «дзяга-дзяга», жираф ни при чём. Чей-то перекус на ночную смену, которая не кончилась. Ворон на ветке уже ждёт свою долю.", EnJ = "A cup with a giraffe: the sticks go ‘jaga-jaga’, the giraffe has nothing to do with it. Someone's snack for a night shift that never ended. The crow on the branch is already waiting for its share.", Rare = false },
        new Def { Id = "JagarikoButter", Kind = Kind.Snack, Shape = "cup", Mesh = "Jagariko", Texture = "JagarikoButter", Kg = 0.09f, Kcal = 300f, Thirst = -7f, Eat = 4f, Ru = "Картофельные палочки «Дзягарико»", En = "Jagariko potato sticks", RuF = "картофель с маслом", EnF = "buttered potato", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Стакан с жирафом: палочки хрустят «дзяга-дзяга», жираф ни при чём. В охотничьей вышке таким встречали рассвет. На морозе хрустит вдвое громче.", EnJ = "A cup with a giraffe: the sticks go ‘jaga-jaga’, the giraffe has nothing to do with it. In the hunting blind they met the dawn with this. In the frost it crunches twice as loud.", Rare = false },
        new Def { Id = "JagarikoCorn", Kind = Kind.Snack, Shape = "cup", Mesh = "Jagariko", Texture = "JagarikoCorn", Kg = 0.09f, Kcal = 300f, Thirst = -7f, Eat = 4f, Ru = "Картофельные палочки «Дзягарико»", En = "Jagariko potato sticks", RuF = "масляная кукуруза Хоккайдо", EnF = "hokkaido butter corn", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Такое носили в кармане куртки на всякий случай. Случай настал. Не еда, а настроение. Настроение тоже греет.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. People carried these in a coat pocket just in case. The case has come. Not food but a mood. A mood warms you too.", Rare = true },
        new Def { Id = "JagarikoSakura", Kind = Kind.Snack, Shape = "cup", Mesh = "Jagariko", Texture = "JagarikoSakura", Kg = 0.09f, Kcal = 300f, Thirst = -7f, Eat = 4f, Ru = "Картофельные палочки «Дзягарико»", En = "Jagariko potato sticks", RuF = "сакура и креветка", EnF = "sakura shrimp", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Прежний хозяин оставил записку: «Не трогать». Записка сгорела. Сытости на час, воспоминаний на неделю.", EnJ = "A spring edition: a rare pack from the days when spring still came. The last owner left a note: 'Do not touch'. The note burned. An hour of fullness, a week of memories.", Rare = true },
        new Def { Id = "JagarikoTarako", Kind = Kind.Snack, Shape = "cup", Mesh = "Jagariko", Texture = "JagarikoTarako", Kg = 0.09f, Kcal = 300f, Thirst = -7f, Eat = 4f, Ru = "Картофельные палочки «Дзягарико»", En = "Jagariko potato sticks", RuF = "икра трески с маслом", EnF = "cod roe butter", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Стакан с жирафом: палочки хрустят «дзяга-дзяга», жираф ни при чём. Такими торговали в поезде, пока поезд ходил. Кролик смотрит с осуждением.", EnJ = "A cup with a giraffe: the sticks go ‘jaga-jaga’, the giraffe has nothing to do with it. They sold these on the train, while the train ran. The rabbit looks on with disapproval.", Rare = false },
        new Def { Id = "JagarikoPotato", Kind = Kind.Snack, Shape = "cup", Mesh = "Jagariko", Texture = "JagarikoPotato", Kg = 0.09f, Kcal = 300f, Thirst = -7f, Eat = 4f, Ru = "Картофельные палочки «Дзягарико»", En = "Jagariko potato sticks", RuF = "картофель с беконом", EnF = "german potato", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Стакан с жирафом: палочки хрустят «дзяга-дзяга», жираф ни при чём. Сторож шахты держал такое в ящике стола. У костра вкуснее. У костра всё вкуснее.", EnJ = "A cup with a giraffe: the sticks go ‘jaga-jaga’, the giraffe has nothing to do with it. The mine watchman kept these in his desk drawer. It tastes better by the fire. Everything does.", Rare = false },
        new Def { Id = "JagarikoUme", Kind = Kind.Snack, Shape = "cup", Mesh = "Jagariko", Texture = "JagarikoUme", Kg = 0.09f, Kcal = 300f, Thirst = -7f, Eat = 4f, Ru = "Картофельные палочки «Дзягарико»", En = "Jagariko potato sticks", RuF = "слива умэ", EnF = "pickled plum", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Стакан с жирафом: палочки хрустят «дзяга-дзяга», жираф ни при чём. Лавина прошла мимо, срок годности тоже. Упаковку не выбрасывайте: ею можно разжечь печь.", EnJ = "A cup with a giraffe: the sticks go ‘jaga-jaga’, the giraffe has nothing to do with it. The avalanche missed it, and so did the best-before date. Keep the wrapper: it will light the stove.", Rare = false },
        new Def { Id = "JagarikoShoyu", Kind = Kind.Snack, Shape = "cup", Mesh = "Jagariko", Texture = "JagarikoShoyu", Kg = 0.09f, Kcal = 300f, Thirst = -7f, Eat = 4f, Ru = "Картофельные палочки «Дзягарико»", En = "Jagariko potato sticks", RuF = "соевый соус", EnF = "soy sauce", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Стакан с жирафом: палочки хрустят «дзяга-дзяга», жираф ни при чём. Такое всегда стояло на видном месте, поэтому никто не брал. Если это последняя на острове, вы её достойны.", EnJ = "A cup with a giraffe: the sticks go ‘jaga-jaga’, the giraffe has nothing to do with it. These always stood in plain sight, which is why nobody took them. If this is the last one on the island, you have earned it.", Rare = false },
        new Def { Id = "JagarikoCurry", Kind = Kind.Snack, Shape = "cup", Mesh = "Jagariko", Texture = "JagarikoCurry", Kg = 0.09f, Kcal = 300f, Thirst = -7f, Eat = 4f, Ru = "Картофельные палочки «Дзягарико»", En = "Jagariko potato sticks", RuF = "карри", EnF = "curry", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Стакан с жирафом: палочки хрустят «дзяга-дзяга», жираф ни при чём. Кто-то открыл, передумал и умер. Не связано. Желудок удивится, но возражать не станет.", EnJ = "A cup with a giraffe: the sticks go ‘jaga-jaga’, the giraffe has nothing to do with it. Someone opened it, changed their mind and died. Unrelated. Your stomach will be surprised but will not object.", Rare = false },
        new Def { Id = "SaeukkangOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "Saeukkang", Texture = "SaeukkangOriginal", Kg = 0.098f, Kcal = 440f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Сэуккан»", En = "Saeukkang shrimp chips", RuF = "креветка", EnF = "shrimp", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские креветочные палочки: рука тянется сама, так поётся в рекламе с семьдесят первого. Такое вечно каталось под сиденьем пикапа. Запах выдаёт вас за сто шагов. Оно того стоит.", EnJ = "Korean shrimp sticks: the hand reaches by itself, as the jingle has sung since '71. One of these was always rolling under a pickup seat. The smell gives you away at a hundred paces. Worth it.", Rare = false },
        new Def { Id = "SaeukkangSpicy", Kind = Kind.Snack, Shape = "bag", Mesh = "Saeukkang", Texture = "SaeukkangSpicy", Kg = 0.098f, Kcal = 440f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Сэуккан»", En = "Saeukkang shrimp chips", RuF = "острые", EnF = "spicy", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Корейские креветочные палочки: рука тянется сама, так поётся в рекламе с семьдесят первого. Привезено паромом, которого больше нет. Раньше это называли вредным. Теперь называют едой.", EnJ = "Korean shrimp sticks: the hand reaches by itself, as the jingle has sung since '71. Brought over by a ferry that no longer exists. They used to call this unhealthy. Now they call it food.", Rare = false },
        new Def { Id = "SaeukkangTruffle", Kind = Kind.Snack, Shape = "bag", Mesh = "Saeukkang", Texture = "SaeukkangTruffle", Kg = 0.098f, Kcal = 440f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Сэуккан»", En = "Saeukkang shrimp chips", RuF = "чёрный трюфель", EnF = "black truffle", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские креветочные палочки: рука тянется сама, так поётся в рекламе с семьдесят первого. Раньше это ели под телевизор. Телевизор молчит. Спальный мешок потом вытряхните.", EnJ = "Korean shrimp sticks: the hand reaches by itself, as the jingle has sung since '71. People ate this in front of the telly. The telly is silent. Shake out your sleeping bag afterwards.", Rare = false },
        new Def { Id = "SaeukkangChuseok", Kind = Kind.Snack, Shape = "bag", Mesh = "Saeukkang", Texture = "SaeukkangChuseok", Kg = 0.098f, Kcal = 440f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Сэуккан»", En = "Saeukkang shrimp chips", RuF = "к празднику урожая", EnF = "harvest festival", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Забыто туристами, которым повезло уехать. Зимой такое идёт за валюту.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. Left behind by tourists who were lucky enough to leave. In winter this passes for currency.", Rare = true },
        new Def { Id = "SaeukkangRice", Kind = Kind.Snack, Shape = "bag", Mesh = "Saeukkang", Texture = "SaeukkangRice", Kg = 0.098f, Kcal = 440f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Сэуккан»", En = "Saeukkang shrimp chips", RuF = "рисовые", EnF = "rice shrimp", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские креветочные палочки: рука тянется сама, так поётся в рекламе с семьдесят первого. Механики заедали этим обед, не вытирая рук. Торговец дал бы за это тряпку. Вы дадите больше.", EnJ = "Korean shrimp sticks: the hand reaches by itself, as the jingle has sung since '71. Mechanics ate these for lunch without wiping their hands. The trader would give a rag for it. You would give more.", Rare = false },
        new Def { Id = "SaeukkangWasabi", Kind = Kind.Snack, Shape = "bag", Mesh = "Saeukkang", Texture = "SaeukkangWasabi", Kg = 0.098f, Kcal = 440f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Сэуккан»", En = "Saeukkang shrimp chips", RuF = "васаби", EnF = "wasabi", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Корейские креветочные палочки: рука тянется сама, так поётся в рекламе с семьдесят первого. Последнее на всю Одинокую топь. Скорее всего. Пока жуёте, метель кажется короче.", EnJ = "Korean shrimp sticks: the hand reaches by itself, as the jingle has sung since '71. The last one in all of Forlorn Muskeg. Most likely. While you chew, the blizzard seems shorter.", Rare = false },
        new Def { Id = "SaeukkangGarlic", Kind = Kind.Snack, Shape = "bag", Mesh = "Saeukkang", Texture = "SaeukkangGarlic", Kg = 0.098f, Kcal = 440f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Сэуккан»", En = "Saeukkang shrimp chips", RuF = "чеснок", EnF = "garlic", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские креветочные палочки: рука тянется сама, так поётся в рекламе с семьдесят первого. Смотритель маяка грыз такое, ожидая кораблей. Организм скажет спасибо. Или не скажет.", EnJ = "Korean shrimp sticks: the hand reaches by itself, as the jingle has sung since '71. The lighthouse keeper munched these while waiting for ships. Your body will thank you. Or not.", Rare = false },
        new Def { Id = "SaeukkangButter", Kind = Kind.Snack, Shape = "bag", Mesh = "Saeukkang", Texture = "SaeukkangButter", Kg = 0.098f, Kcal = 440f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Сэуккан»", En = "Saeukkang shrimp chips", RuF = "масло", EnF = "butter", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские креветочные палочки: рука тянется сама, так поётся в рекламе с семьдесят первого. Полки рушились, а это уцелело. На третьей горсти забываешь, что вокруг конец света.", EnJ = "Korean shrimp sticks: the hand reaches by itself, as the jingle has sung since '71. Shelves collapsed and this survived. By the third handful you forget the world has ended.", Rare = false },
        new Def { Id = "HoneyButterHoney", Kind = Kind.Snack, Shape = "bag", Mesh = "HoneyButter", Texture = "HoneyButterHoney", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хани Батер Чип»", En = "Honey Butter Chip crisps", RuF = "мёд и масло", EnF = "honey butter", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Чипсы, за которыми в Сеуле стояли очереди и которые продавали с рук, как билеты. Смотритель заповедника называл это ужином. Рыба подо льдом завидует.", EnJ = "Crisps people queued for in Seoul and scalped like concert tickets. The park ranger called this dinner. The fish under the ice are jealous.", Rare = false },
        new Def { Id = "HoneyButterMaple", Kind = Kind.Snack, Shape = "bag", Mesh = "HoneyButter", Texture = "HoneyButterMaple", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хани Батер Чип»", En = "Honey Butter Chip crisps", RuF = "клён и сыр", EnF = "maple cheese", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Чипсы, за которыми в Сеуле стояли очереди и которые продавали с рук, как билеты. Такое слали посылками с материка. Адресаты выбыли. Олень от такого отказался бы. Олень не голодал.", EnJ = "Crisps people queued for in Seoul and scalped like concert tickets. These came in parcels from the mainland. The addressees are gone. A deer would turn it down. A deer has never starved.", Rare = false },
        new Def { Id = "HoneyButterCherry", Kind = Kind.Snack, Shape = "bag", Mesh = "HoneyButter", Texture = "HoneyButterCherry", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хани Батер Чип»", En = "Honey Butter Chip crisps", RuF = "цветы вишни", EnF = "cherry blossom", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Чипсы, за которыми в Сеуле стояли очереди и которые продавали с рук, как билеты. Иные держали это за лекарство. Тоже лечит. Голод отступит, жажда придёт. Честный обмен.", EnJ = "Crisps people queued for in Seoul and scalped like concert tickets. Some people counted this as medicine. Also a cure. Hunger leaves, thirst arrives. A fair trade.", Rare = false },
        new Def { Id = "HoneyButterBlossom", Kind = Kind.Snack, Shape = "bag", Mesh = "HoneyButter", Texture = "HoneyButterBlossom", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хани Батер Чип»", En = "Honey Butter Chip crisps", RuF = "вишнёвый цвет", EnF = "cherry blossom", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. В школьном рюкзаке такое не доживало до обеда. Ешьте до темноты: в темноте крошки не найти.", EnJ = "A spring edition: a rare pack from the days when spring still came. In a school bag this never lasted till lunch. Eat before dark: you cannot find crumbs in the dark.", Rare = true },
        new Def { Id = "HoneyButterValentine", Kind = Kind.Snack, Shape = "bag", Mesh = "HoneyButter", Texture = "HoneyButterValentine", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хани Батер Чип»", En = "Honey Butter Chip crisps", RuF = "клубника со сливками", EnF = "strawberry cream", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Серия для влюблённых: редкость. Делить не с кем, зато вся ваша. Его обменяли бы на патрон, будь тут с кем меняться. Лучшее, что случится с вами сегодня.", EnJ = "A Valentine edition: a rarity. No one to share it with, so it is all yours. You could trade it for a cartridge, if there were anyone to trade with. The best thing that will happen to you today.", Rare = true },
        new Def { Id = "HoneyButterAutumn", Kind = Kind.Snack, Shape = "bag", Mesh = "HoneyButter", Texture = "HoneyButterAutumn", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хани Батер Чип»", En = "Honey Butter Chip crisps", RuF = "осенний каштан", EnF = "autumn chestnut", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. На вокзале это стоило втрое дороже. Теперь даром. Для полного счастья не хватает только дивана.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. At the station it cost three times as much. Now it is free. All that is missing for perfect happiness is a sofa.", Rare = true },
        new Def { Id = "HoneyButterCheddar", Kind = Kind.Snack, Shape = "bag", Mesh = "HoneyButter", Texture = "HoneyButterCheddar", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хани Батер Чип»", En = "Honey Butter Chip crisps", RuF = "чеддер", EnF = "cheddar", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Чипсы, за которыми в Сеуле стояли очереди и которые продавали с рук, как билеты. Пережило толчок и даже не помялось. Вкус детства, если детство было так себе.", EnJ = "Crisps people queued for in Seoul and scalped like concert tickets. It came through the quake without a dent. The taste of childhood, if childhood was so-so.", Rare = false },
        new Def { Id = "HoneyButterGarlic", Kind = Kind.Snack, Shape = "bag", Mesh = "HoneyButter", Texture = "HoneyButterGarlic", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хани Батер Чип»", En = "Honey Butter Chip crisps", RuF = "чеснок и мёд", EnF = "honey garlic", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Чипсы, за которыми в Сеуле стояли очереди и которые продавали с рук, как билеты. Китобои такого не ели, но оценили бы. Шуршит как надежда.", EnJ = "Crisps people queued for in Seoul and scalped like concert tickets. The whalers never ate this, but they would have approved. It rustles like hope.", Rare = false },
        new Def { Id = "HoneyButterChoco", Kind = Kind.Snack, Shape = "bag", Mesh = "HoneyButter", Texture = "HoneyButterChoco", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хани Батер Чип»", En = "Honey Butter Chip crisps", RuF = "шоколад", EnF = "chocolate", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Чипсы, за которыми в Сеуле стояли очереди и которые продавали с рук, как билеты. Осталось после чьего-то дня рождения. Гости не пришли. Голод отступит, жажда придёт. Честный обмен.", EnJ = "Crisps people queued for in Seoul and scalped like concert tickets. Left over from someone's birthday. The guests never came. Hunger leaves, thirst arrives. A fair trade.", Rare = false },
        new Def { Id = "HoneyButterAlmond", Kind = Kind.Snack, Shape = "bag", Mesh = "HoneyButter", Texture = "HoneyButterAlmond", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хани Батер Чип»", En = "Honey Butter Chip crisps", RuF = "миндаль", EnF = "almond", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Чипсы, за которыми в Сеуле стояли очереди и которые продавали с рук, как билеты. Мерзлота хранит лучше любого холодильника. Не согреет, зато отвлечёт.", EnJ = "Crisps people queued for in Seoul and scalped like concert tickets. Permafrost keeps things better than any fridge. It will not warm you, but it will distract you.", Rare = false },
        new Def { Id = "HoneyButterYogurt", Kind = Kind.Snack, Shape = "bag", Mesh = "HoneyButter", Texture = "HoneyButterYogurt", Kg = 0.068f, Kcal = 320f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хани Батер Чип»", En = "Honey Butter Chip crisps", RuF = "йогурт", EnF = "yoghurt", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Чипсы, за которыми в Сеуле стояли очереди и которые продавали с рук, как билеты. Такое добывали из автомата, который съедал последнюю монету. Пума предпочитает мясо. Вам повезло.", EnJ = "Crisps people queued for in Seoul and scalped like concert tickets. These came from the vending machine that ate your last coin. The cougar prefers meat. Lucky you.", Rare = false },
        new Def { Id = "KkokkalRoast", Kind = Kind.Snack, Shape = "bag", Mesh = "Kkokkal", Texture = "KkokkalRoast", Kg = 0.08f, Kcal = 370f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные рожки «Ккоккалькон»", En = "Kkokkalcorn corn cones", RuF = "жареная кукуруза", EnF = "roasted corn", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские рожки: надеваются на пальцы, превращают взрослого в ведьму с когтями. Такое брали в лодку под брезент, на весь день. Сначала попробуйте одну штучку. Шутка: ешьте всё.", EnJ = "Korean cones: they go on your fingers and turn an adult into a clawed witch. People took these out in the boat under the tarpaulin, for the whole day. Try just one first. Joke: eat the lot.", Rare = false },
        new Def { Id = "KkokkalNutty", Kind = Kind.Snack, Shape = "bag", Mesh = "Kkokkal", Texture = "KkokkalNutty", Kg = 0.08f, Kcal = 370f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные рожки «Ккоккалькон»", En = "Kkokkalcorn corn cones", RuF = "ореховые", EnF = "nutty", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские рожки: надеваются на пальцы, превращают взрослого в ведьму с когтями. С ним кто-то шёл к перевалу и не дошёл. Такой ужин не стыдно записать в дневник.", EnJ = "Korean cones: they go on your fingers and turn an adult into a clawed witch. Someone carried it towards the pass and never arrived. A dinner worth writing in the journal.", Rare = false },
        new Def { Id = "KkokkalSpicy", Kind = Kind.Snack, Shape = "bag", Mesh = "Kkokkal", Texture = "KkokkalSpicy", Kg = 0.08f, Kcal = 370f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные рожки «Ккоккалькон»", En = "Kkokkalcorn corn cones", RuF = "острые", EnF = "spicy", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Корейские рожки: надеваются на пальцы, превращают взрослого в ведьму с когтями. С таким сидели у окна с видом на метель. Силы прибавит на один сугроб.", EnJ = "Korean cones: they go on your fingers and turn an adult into a clawed witch. People sat with these at a window with a view of the blizzard. It will carry you one snowdrift further.", Rare = false },
        new Def { Id = "KkokkalCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Kkokkal", Texture = "KkokkalCheese", Kg = 0.08f, Kcal = 370f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные рожки «Ккоккалькон»", En = "Kkokkalcorn corn cones", RuF = "сыр", EnF = "cheese", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские рожки: надеваются на пальцы, превращают взрослого в ведьму с когтями. Уцелело там, где сгорело всё остальное. Идеально к закату, которого не видно за бураном.", EnJ = "Korean cones: they go on your fingers and turn an adult into a clawed witch. It survived where everything else burned. Perfect with a sunset you cannot see for the storm.", Rare = false },
        new Def { Id = "KkokkalSweet", Kind = Kind.Snack, Shape = "bag", Mesh = "Kkokkal", Texture = "KkokkalSweet", Kg = 0.08f, Kcal = 370f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные рожки «Ккоккалькон»", En = "Kkokkalcorn corn cones", RuF = "сладкая кукуруза", EnF = "sweet corn", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские рожки: надеваются на пальцы, превращают взрослого в ведьму с когтями. Этим кормили сторожевого пса. Пёс ушёл в волки. Пахнет магазином. Помните магазины?", EnJ = "Korean cones: they go on your fingers and turn an adult into a clawed witch. They fed the guard dog with this. The dog joined the wolves. It smells of a shop. Remember shops?", Rare = false },
        new Def { Id = "KkokkalChoco", Kind = Kind.Snack, Shape = "bag", Mesh = "Kkokkal", Texture = "KkokkalChoco", Kg = 0.08f, Kcal = 370f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные рожки «Ккоккалькон»", En = "Kkokkalcorn corn cones", RuF = "шоколад", EnF = "chocolate", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Корейские рожки: надеваются на пальцы, превращают взрослого в ведьму с когтями. Из запасов лесорубов: брали ящиками. Мороз не испортил, время не взяло.", EnJ = "Korean cones: they go on your fingers and turn an adult into a clawed witch. From the loggers' stores: they bought it by the crate. Frost did not spoil it and time could not take it.", Rare = false },
        new Def { Id = "KkokkalButter", Kind = Kind.Snack, Shape = "bag", Mesh = "Kkokkal", Texture = "KkokkalButter", Kg = 0.08f, Kcal = 370f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные рожки «Ккоккалькон»", En = "Kkokkalcorn corn cones", RuF = "масляная кукуруза", EnF = "butter corn", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские рожки: надеваются на пальцы, превращают взрослого в ведьму с когтями. В пост такое не ели. Пост кончился вместе с миром. В рюкзаке не мнётся. Почти.", EnJ = "Korean cones: they go on your fingers and turn an adult into a clawed witch. Nobody ate these during a fast. The fast ended with the world. It does not get crushed in a pack. Almost.", Rare = false },
        new Def { Id = "WangWangSnow", Kind = Kind.Snack, Shape = "bag", Mesh = "WangWang", Texture = "WangWangSnow", Kg = 0.092f, Kcal = 340f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Ван-Ван»", En = "Wang Wang rice crackers", RuF = "снежные", EnF = "snow rice crackers", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Мальчик на пачке смотрит туда же, куда вертишь пачку. Не спрашивай как. Теперь это ценнее денег. Деньги оставьте. Съешьте сейчас: завтра может не быть аппетита.", EnJ = "The boy on the pack looks wherever you turn it. Don't ask how. It is worth more than money now. Leave the money. Eat it now: tomorrow you may have no appetite.", Rare = false },
        new Def { Id = "WangWangSenbei", Kind = Kind.Snack, Shape = "bag", Mesh = "WangWang", Texture = "WangWangSenbei", Kg = 0.092f, Kcal = 340f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Ван-Ван»", En = "Wang Wang rice crackers", RuF = "сэмбэй", EnF = "senbei", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Мальчик на пачке смотрит туда же, куда вертишь пачку. Не спрашивай как. Его несли на пикник. Пикник отменили навсегда. Хватит дойти до следующей хижины и пожалеть, что кончилось.", EnJ = "The boy on the pack looks wherever you turn it. Don't ask how. It was headed for a picnic. The picnic is cancelled forever. Enough to reach the next cabin and regret it is gone.", Rare = false },
        new Def { Id = "WangWangCrisp", Kind = Kind.Snack, Shape = "bag", Mesh = "WangWang", Texture = "WangWangCrisp", Kg = 0.092f, Kcal = 340f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Ван-Ван»", En = "Wang Wang rice crackers", RuF = "хрустики", EnF = "mini crisps", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Мальчик на пачке смотрит туда же, куда вертишь пачку. Не спрашивай как. Такое стояло у кассы на случай слабости. От такого не толстеют те, кто ходит по двадцать километров.", EnJ = "The boy on the pack looks wherever you turn it. Don't ask how. These stood by the till for moments of weakness. Nobody who walks twenty kilometres a day gets fat on this.", Rare = false },
        new Def { Id = "WangWangRedPack", Kind = Kind.Snack, Shape = "bag", Mesh = "WangWang", Texture = "WangWangRedPack", Kg = 0.092f, Kcal = 340f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Ван-Ван»", En = "Wang Wang rice crackers", RuF = "праздничные, красный конверт", EnF = "lunar new year", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Новогодняя серия: куранты отбили, а пачка осталась. Редкость. Досталось вам, потому что вы дошли первым. Волчья стая не в курсе. Пусть так и будет.", EnJ = "A New Year edition: the clock has struck, the pack remains. A rarity. It is yours because you got here first. The wolf pack does not know. Keep it that way.", Rare = true },
        new Def { Id = "WangWangLantern", Kind = Kind.Snack, Shape = "bag", Mesh = "WangWang", Texture = "WangWangLantern", Kg = 0.092f, Kcal = 340f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Ван-Ван»", En = "Wang Wang rice crackers", RuF = "к празднику фонарей", EnF = "lantern festival", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Зимняя серия: выпускали на один сезон, а зима тут навсегда. Упаковка выцвела, внутри время остановилось. Хрустеть в засаде не рекомендуется.", EnJ = "A winter edition: made for one season, and here winter is forever. The wrapper has faded; inside, time stood still. Crunching in an ambush is not recommended.", Rare = true },
        new Def { Id = "WangWangMilk", Kind = Kind.Snack, Shape = "bag", Mesh = "WangWang", Texture = "WangWangMilk", Kg = 0.092f, Kcal = 340f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Ван-Ван»", En = "Wang Wang rice crackers", RuF = "молочные", EnF = "milky", RuC = "Китай", EnC = "China", Fx = new[] { "SugarDry" }, RuJ = "Мальчик на пачке смотрит туда же, куда вертишь пачку. Не спрашивай как. Из чемодана пассажира, который не долетел. Лекарство от тоски, отпускается без рецепта.", EnJ = "The boy on the pack looks wherever you turn it. Don't ask how. From the suitcase of a passenger who never landed. A cure for the blues, no prescription needed.", Rare = false },
        new Def { Id = "WangWangSeaweed", Kind = Kind.Snack, Shape = "bag", Mesh = "WangWang", Texture = "WangWangSeaweed", Kg = 0.092f, Kcal = 340f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Ван-Ван»", En = "Wang Wang rice crackers", RuF = "нори", EnF = "seaweed", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Мальчик на пачке смотрит туда же, куда вертишь пачку. Не спрашивай как. Перезимовало и ничуть не обиделось. Жуйте и думайте о хорошем. Например, о добавке.", EnJ = "The boy on the pack looks wherever you turn it. Don't ask how. It made it through the winter and bears no grudge. Chew and think of nice things. Seconds, for example.", Rare = false },
        new Def { Id = "WangWangCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "WangWang", Texture = "WangWangCheese", Kg = 0.092f, Kcal = 340f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Ван-Ван»", En = "Wang Wang rice crackers", RuF = "сыр", EnF = "cheese", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Мальчик на пачке смотрит туда же, куда вертишь пачку. Не спрашивай как. Запасливая хозяйка купила по акции шесть штук. К утру от него останется только запах на варежках.", EnJ = "The boy on the pack looks wherever you turn it. Don't ask how. A thrifty housewife bought six of these on offer. By morning only the smell on your mittens will be left.", Rare = false },
        new Def { Id = "WangWangSpicy", Kind = Kind.Snack, Shape = "bag", Mesh = "WangWang", Texture = "WangWangSpicy", Kg = 0.092f, Kcal = 340f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Ван-Ван»", En = "Wang Wang rice crackers", RuF = "острые", EnF = "spicy", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Мальчик на пачке смотрит туда же, куда вертишь пачку. Не спрашивай как. Кто-то написал на упаковке «моё». Уже нет. Тишина вокруг такая, что слышно, как вы жуёте.", EnJ = "The boy on the pack looks wherever you turn it. Don't ask how. Someone wrote 'mine' on it. Not any more. It is so quiet you can hear yourself chew.", Rare = false },
        new Def { Id = "WangWangCorn", Kind = Kind.Snack, Shape = "bag", Mesh = "WangWang", Texture = "WangWangCorn", Kg = 0.092f, Kcal = 340f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Ван-Ван»", En = "Wang Wang rice crackers", RuF = "кукурузные", EnF = "corn", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Мальчик на пачке смотрит туда же, куда вертишь пачку. Не спрашивай как. В консервном цеху это ели тайком от мастера. Не делите на завтра: завтра будет новый голод.", EnJ = "The boy on the pack looks wherever you turn it. Don't ask how. At the cannery they ate this behind the foreman's back. Do not save half for tomorrow: tomorrow brings its own hunger.", Rare = false },
        new Def { Id = "LaLongBig", Kind = Kind.Snack, Shape = "bag", Mesh = "LaLong", Texture = "LaLongBig", Kg = 0.114f, Kcal = 350f, Thirst = -10f, Eat = 5f, Ru = "Острые полоски «Ла Лун»", En = "La Long spicy strips", RuF = "большие полоски", EnF = "big strips", RuC = "Китай", EnC = "China", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Острые полоски из китайской школьной лавки: красное масло, красные уши. Его не взяли даже мародёры. Они спешили. Сосны вокруг делают вид, что не смотрят.", EnJ = "Spicy strips from a Chinese school shop: red oil, red ears. Even the looters left it. They were in a hurry. The pines around pretend not to watch.", Rare = false },
        new Def { Id = "LaLongKiss", Kind = Kind.Snack, Shape = "bag", Mesh = "LaLong", Texture = "LaLongKiss", Kg = 0.114f, Kcal = 350f, Thirst = -10f, Eat = 5f, Ru = "Острые полоски «Ла Лун»", En = "La Long spicy strips", RuF = "жгучий поцелуй", EnF = "kiss burn", RuC = "Китай", EnC = "China", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Острые полоски из китайской школьной лавки: красное масло, красные уши. Провело зиму на острове, как и вы. Калории мелкие, зато свои.", EnJ = "Spicy strips from a Chinese school shop: red oil, red ears. It spent the winter on the island, same as you. Small calories, but your own.", Rare = false },
        new Def { Id = "LaLongSmall", Kind = Kind.Snack, Shape = "bag", Mesh = "LaLong", Texture = "LaLongSmall", Kg = 0.114f, Kcal = 350f, Thirst = -10f, Eat = 5f, Ru = "Острые полоски «Ла Лун»", En = "La Long spicy strips", RuF = "малые полоски", EnF = "small strips", RuC = "Китай", EnC = "China", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Острые полоски из китайской школьной лавки: красное масло, красные уши. Дети прятали такое под кроватью, в тайнике. После этого даже крапивный чай покажется десертом.", EnJ = "Spicy strips from a Chinese school shop: red oil, red ears. Children hid these under the bed, in a secret place. After this even nettle tea feels like dessert.", Rare = false },
        new Def { Id = "LaLongMala", Kind = Kind.Snack, Shape = "bag", Mesh = "LaLong", Texture = "LaLongMala", Kg = 0.114f, Kcal = 350f, Thirst = -10f, Eat = 5f, Ru = "Острые полоски «Ла Лун»", En = "La Long spicy strips", RuF = "жгучая мала", EnF = "spicy mala", RuC = "Китай", EnC = "China", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Острые полоски из китайской школьной лавки: красное масло, красные уши. Осталось от геологов вместе с картой и долгами. Нашедшему полагается всё.", EnJ = "Spicy strips from a Chinese school shop: red oil, red ears. Left by the geologists along with a map and some debts. Finders keepers, all of it.", Rare = false },
        new Def { Id = "LaLongKelp", Kind = Kind.Snack, Shape = "bag", Mesh = "LaLong", Texture = "LaLongKelp", Kg = 0.114f, Kcal = 350f, Thirst = -10f, Eat = 5f, Ru = "Острые полоски «Ла Лун»", En = "La Long spicy strips", RuF = "острая ламинария", EnF = "spicy kelp", RuC = "Китай", EnC = "China", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Острые полоски из китайской школьной лавки: красное масло, красные уши. На острове такое было праздником и до катастрофы. Зубы целы? Тогда вперёд.", EnJ = "Spicy strips from a Chinese school shop: red oil, red ears. On the island this was a treat even before the disaster. Teeth intact? Then go ahead.", Rare = false },
        new Def { Id = "LaLongKonjac", Kind = Kind.Snack, Shape = "bag", Mesh = "LaLong", Texture = "LaLongKonjac", Kg = 0.114f, Kcal = 350f, Thirst = -10f, Eat = 5f, Ru = "Острые полоски «Ла Лун»", En = "La Long spicy strips", RuF = "острый конжак", EnF = "spicy konjac", RuC = "Китай", EnC = "China", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Острые полоски из китайской школьной лавки: красное масло, красные уши. С таким слушали радио, которое теперь ловит только треск. Ночью приснится добавка.", EnJ = "Spicy strips from a Chinese school shop: red oil, red ears. People ate these by the radio, which picks up nothing but crackle now. Tonight you will dream of seconds.", Rare = false },
        new Def { Id = "LaLongBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "LaLong", Texture = "LaLongBBQ", Kg = 0.114f, Kcal = 350f, Thirst = -10f, Eat = 5f, Ru = "Острые полоски «Ла Лун»", En = "La Long spicy strips", RuF = "барбекю", EnF = "barbecue", RuC = "Китай", EnC = "China", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Острые полоски из китайской школьной лавки: красное масло, красные уши. Крысы прогрызли соседнюю, эту пощадили. С таким запасом можно пережить ещё один вечер.", EnJ = "Spicy strips from a Chinese school shop: red oil, red ears. The rats gnawed through the one next to it and spared this. With supplies like this you can survive one more evening.", Rare = false },
        new Def { Id = "LaLongSweet", Kind = Kind.Snack, Shape = "bag", Mesh = "LaLong", Texture = "LaLongSweet", Kg = 0.114f, Kcal = 350f, Thirst = -10f, Eat = 5f, Ru = "Острые полоски «Ла Лун»", En = "La Long spicy strips", RuF = "сладко-острые", EnF = "sweet & spicy", RuC = "Китай", EnC = "China", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Острые полоски из китайской школьной лавки: красное масло, красные уши. Бывший хозяин клялся бросить. Не успел. Пёс бы выпросил половину. Пса нет.", EnJ = "Spicy strips from a Chinese school shop: red oil, red ears. The former owner swore to give these up. He ran out of time. A dog would beg half of it. There is no dog.", Rare = false },
        new Def { Id = "ChaChaOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "ChaCha", Texture = "ChaChaOriginal", Kg = 0.168f, Kcal = 930f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Ча-Ча»", En = "Cha Cha seeds", RuF = "пять специй", EnF = "five spice", RuC = "Китай", EnC = "China", Fx = new[] { "SeedHabit" }, RuJ = "Китайские семечки, варёные с пряностями: Новый год под них пролетает за вечер. Его катали в кабине трактора три сезона. Съедено будет быстрее, чем найдено.", EnJ = "Chinese seeds boiled with spice: a New Year goes by in one evening with them. It rode around in a tractor cab for three seasons. It will be eaten faster than it was found.", Rare = false },
        new Def { Id = "ChaChaCaramel", Kind = Kind.Snack, Shape = "bag", Mesh = "ChaCha", Texture = "ChaChaCaramel", Kg = 0.168f, Kcal = 930f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Ча-Ча»", En = "Cha Cha seeds", RuF = "карамель", EnF = "caramel", RuC = "Китай", EnC = "China", Fx = new[] { "SugarDry" }, RuJ = "Китайские семечки, варёные с пряностями: Новый год под них пролетает за вечер. После бани такое шло лучше всего. На вкус как выходной.", EnJ = "Chinese seeds boiled with spice: a New Year goes by in one evening with them. Nothing went down better after the sauna. It tastes like a day off.", Rare = false },
        new Def { Id = "ChaChaPecan", Kind = Kind.Snack, Shape = "bag", Mesh = "ChaCha", Texture = "ChaChaPecan", Kg = 0.168f, Kcal = 930f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Ча-Ча»", En = "Cha Cha seeds", RuF = "орех пекан", EnF = "pecan", RuC = "Китай", EnC = "China", Fx = new[] { "SeedHabit" }, RuJ = "Китайские семечки, варёные с пряностями: Новый год под них пролетает за вечер. В тюрьме на это выменивали что угодно. Ветер унесёт запах прямо к берлоге. Ешьте быстрее.", EnJ = "Chinese seeds boiled with spice: a New Year goes by in one evening with them. In the prison you could trade one of these for anything. The wind carries the smell straight to the den. Eat faster.", Rare = false },
        new Def { Id = "ChaChaNewYear", Kind = Kind.Snack, Shape = "bag", Mesh = "ChaCha", Texture = "ChaChaNewYear", Kg = 0.168f, Kcal = 930f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Ча-Ча»", En = "Cha Cha seeds", RuF = "новогодний набор", EnF = "new year pack", RuC = "Китай", EnC = "China", Fx = new[] { "SeedHabit" }, RuJ = "Новогодняя серия: куранты отбили, а пачка осталась. Редкость. Кто-то менял это на сигареты. Сделка сорвалась. Пополняет запас соли и веры в человечество.", EnJ = "A New Year edition: the clock has struck, the pack remains. A rarity. Someone was trading this for cigarettes. The deal fell through. Restores your salt and your faith in mankind.", Rare = true },
        new Def { Id = "ChaChaWalnut", Kind = Kind.Snack, Shape = "bag", Mesh = "ChaCha", Texture = "ChaChaWalnut", Kg = 0.168f, Kcal = 930f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Ча-Ча»", En = "Cha Cha seeds", RuF = "грецкий орех", EnF = "walnut", RuC = "Китай", EnC = "China", Fx = new[] { "SeedHabit" }, RuJ = "Китайские семечки, варёные с пряностями: Новый год под них пролетает за вечер. С ним зимовали на метеостанции, пока было с кем. Хорошо идёт под треск поленьев.", EnJ = "Chinese seeds boiled with spice: a New Year goes by in one evening with them. They wintered with it at the weather station, while there was a 'they'. Goes down well with crackling logs.", Rare = false },
        new Def { Id = "ChaChaCoconut", Kind = Kind.Snack, Shape = "bag", Mesh = "ChaCha", Texture = "ChaChaCoconut", Kg = 0.168f, Kcal = 930f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Ча-Ча»", En = "Cha Cha seeds", RuF = "кокос", EnF = "coconut", RuC = "Китай", EnC = "China", Fx = new[] { "SugarDry" }, RuJ = "Китайские семечки, варёные с пряностями: Новый год под них пролетает за вечер. Такое терялось в кладовке среди крупы и надежд. Руки вытирать о штаны: салфеток не завезли.", EnJ = "Chinese seeds boiled with spice: a New Year goes by in one evening with them. These got lost in the pantry among the grain and the hopes. Wipe your hands on your trousers: no napkins were delivered.", Rare = false },
        new Def { Id = "ChaChaSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "ChaCha", Texture = "ChaChaSalt", Kg = 0.168f, Kcal = 930f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Ча-Ча»", En = "Cha Cha seeds", RuF = "морская соль", EnF = "sea salt", RuC = "Китай", EnC = "China", Fx = new[] { "SeedHabit" }, RuJ = "Китайские семечки, варёные с пряностями: Новый год под них пролетает за вечер. Его берегли к приезду внуков. Маленькая радость размером с ладонь.", EnJ = "Chinese seeds boiled with spice: a New Year goes by in one evening with them. It was being saved for the grandchildren's visit. A small joy the size of your palm.", Rare = false },
        new Def { Id = "ChaChaSpicy", Kind = Kind.Snack, Shape = "bag", Mesh = "ChaCha", Texture = "ChaChaSpicy", Kg = 0.168f, Kcal = 930f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Ча-Ча»", En = "Cha Cha seeds", RuF = "острые", EnF = "spicy", RuC = "Китай", EnC = "China", Fx = new[] { "SeedHabit", "PepperBlood", "Sweat" }, RuJ = "Китайские семечки, варёные с пряностями: Новый год под них пролетает за вечер. В баре такое ставили на стойку, бесплатно к пиву. Пива нет. Совесть молчит, живот поёт.", EnJ = "Chinese seeds boiled with spice: a New Year goes by in one evening with them. Bars put these out free with a beer. There is no beer. Conscience is silent, the belly sings.", Rare = false },
        new Def { Id = "ChaChaHoney", Kind = Kind.Snack, Shape = "bag", Mesh = "ChaCha", Texture = "ChaChaHoney", Kg = 0.168f, Kcal = 930f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Ча-Ча»", En = "Cha Cha seeds", RuF = "мёд и масло", EnF = "honey butter", RuC = "Китай", EnC = "China", Fx = new[] { "SugarDry" }, RuJ = "Китайские семечки, варёные с пряностями: Новый год под них пролетает за вечер. Такое лежало в каждом доме, пока не погас свет. Проверено поколениями и одной катастрофой.", EnJ = "Chinese seeds boiled with spice: a New Year goes by in one evening with them. Every house had one of these until the lights went out. Tested by generations and one catastrophe.", Rare = false },
        new Def { Id = "ChaChaPumpkin", Kind = Kind.Snack, Shape = "bag", Mesh = "ChaCha", Texture = "ChaChaPumpkin", Kg = 0.168f, Kcal = 930f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Ча-Ча»", En = "Cha Cha seeds", RuF = "тыквенные", EnF = "pumpkin seeds", RuC = "Китай", EnC = "China", Fx = new[] { "SeedHabit" }, RuJ = "Китайские семечки, варёные с пряностями: Новый год под них пролетает за вечер. Кто-то берёг это на чёрный день. Он настал. Оставьте пару штук на перевал. Не оставите.", EnJ = "Chinese seeds boiled with spice: a New Year goes by in one evening with them. Someone saved this for a rainy day. It came. Save a couple for the pass. You will not.", Rare = false },
        new Def { Id = "WolkersSalted", Kind = Kind.Snack, Shape = "bag", Mesh = "Wolkers", Texture = "WolkersSalted", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс»", En = "Wolkers crisps", RuF = "с солью", EnF = "ready salted", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Британские чипсы: цвета пачек перепутаны назло всей Европе, и никто не извинился. Пережило хозяина, кота и две зимы. Здесь это считается ужином при свечах.", EnJ = "British crisps: the pack colours are swapped to spite all of Europe, and nobody apologised. It outlived its owner, the cat and two winters. Round here this counts as a candlelit dinner.", Rare = false },
        new Def { Id = "WolkersCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Wolkers", Texture = "WolkersCheese", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс»", En = "Wolkers crisps", RuF = "сыр и лук", EnF = "cheese & onion", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Британские чипсы: цвета пачек перепутаны назло всей Европе, и никто не извинился. Такое обычно находили за диваном, как всё лучшее в жизни. Луна светит, еда хрустит, жизнь налаживается.", EnJ = "British crisps: the pack colours are swapped to spite all of Europe, and nobody apologised. These were usually found behind the sofa, like all the best things in life. The moon shines, the food crunches, life is looking up.", Rare = false },
        new Def { Id = "WolkersVinegar", Kind = Kind.Snack, Shape = "bag", Mesh = "Wolkers", Texture = "WolkersVinegar", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс»", En = "Wolkers crisps", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Британские чипсы: цвета пачек перепутаны назло всей Европе, и никто не извинился. Последний завоз был до того, как упали самолёты. Снег вокруг не солёный. Это солёное.", EnJ = "British crisps: the pack colours are swapped to spite all of Europe, and nobody apologised. The last delivery came before the planes fell. The snow around is not salty. This is.", Rare = false },
        new Def { Id = "WolkersPrawn", Kind = Kind.Snack, Shape = "bag", Mesh = "Wolkers", Texture = "WolkersPrawn", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс»", En = "Wolkers crisps", RuF = "креветочный коктейль", EnF = "prawn cocktail", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Британские чипсы: цвета пачек перепутаны назло всей Европе, и никто не извинился. Ценник оторван: теперь это бесценно. Больше таких не делают. Совсем.", EnJ = "British crisps: the pack colours are swapped to spite all of Europe, and nobody apologised. The price tag is torn off: it is priceless now. They do not make these any more. At all.", Rare = false },
        new Def { Id = "WolkersChicken", Kind = Kind.Snack, Shape = "bag", Mesh = "Wolkers", Texture = "WolkersChicken", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс»", En = "Wolkers crisps", RuF = "жареная курица", EnF = "roast chicken", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Британские чипсы: цвета пачек перепутаны назло всей Европе, и никто не извинился. Дата на шве стёрлась, и слава богу. Открывайте тихо: у волков отличный слух.", EnJ = "British crisps: the pack colours are swapped to spite all of Europe, and nobody apologised. The date on the seam has rubbed off, thank goodness. Open it quietly: wolves have excellent hearing.", Rare = false },
        new Def { Id = "WolkersSprout", Kind = Kind.Snack, Shape = "bag", Mesh = "Wolkers", Texture = "WolkersSprout", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс»", En = "Wolkers crisps", RuF = "брюссельская капуста", EnF = "brussels sprout", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Пахнет заправкой у Прибрежного шоссе. Одной не обойдётся, но вторая неизвестно где.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. It smells of the petrol station on the Coastal Highway. One won't be enough, and nobody knows where the second is.", Rare = true },
        new Def { Id = "WolkersCranberry", Kind = Kind.Snack, Shape = "bag", Mesh = "Wolkers", Texture = "WolkersCranberry", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс»", En = "Wolkers crisps", RuF = "сыр и клюква", EnF = "cheese & cranberry", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Зимняя серия: выпускали на один сезон, а зима тут навсегда. Такое возили в бардачке на дальнюю дорогу. Дороги кончились. Крошки с пола тоже считаются.", EnJ = "A winter edition: made for one season, and here winter is forever. People kept these in the glovebox for long drives. The drives are over. The crumbs on the floor count too.", Rare = true },
        new Def { Id = "WolkersTurkey", Kind = Kind.Snack, Shape = "bag", Mesh = "Wolkers", Texture = "WolkersTurkey", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс»", En = "Wolkers crisps", RuF = "индейка с начинкой", EnF = "turkey & stuffing", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Мыши не тронули. Думайте сами. Запейте чаем из шиповника и считайте это обедом.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. The mice left it alone. Draw your own conclusions. Wash it down with rosehip tea and call it lunch.", Rare = true },
        new Def { Id = "WolkersPigs", Kind = Kind.Snack, Shape = "bag", Mesh = "Wolkers", Texture = "WolkersPigs", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс»", En = "Wolkers crisps", RuF = "колбаски в беконе", EnF = "pigs in blankets", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Рыбаки брали такое на лёд вместо обеда. Медведю не показывать: отнимет вместе с рукой.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. Fishermen took this onto the ice instead of lunch. Do not show the bear: he will take it, hand and all.", Rare = true },
        new Def { Id = "WolkersMince", Kind = Kind.Snack, Shape = "bag", Mesh = "Wolkers", Texture = "WolkersMince", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс»", En = "Wolkers crisps", RuF = "сладкий пирожок", EnF = "mince pie", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Смотритель плотины держал такое в заначке. Диетолог не одобрил бы. Диетолога тут нет.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. The dam keeper kept a stash of these. A dietitian would not approve. There is no dietitian here.", Rare = true },
        new Def { Id = "WolkersSummerBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Wolkers", Texture = "WolkersSummerBBQ", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс»", En = "Wolkers crisps", RuF = "летний барбекю", EnF = "summer barbecue", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Кто-то спрятал это от детей. Дети не нашли. Лучше, чем кора. Проверено.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. Someone hid it from the kids. The kids never found it. Better than bark. Tested.", Rare = true },
        new Def { Id = "WolkersBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Wolkers", Texture = "WolkersBacon", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс»", En = "Wolkers crisps", RuF = "копчёный бекон", EnF = "smoky bacon", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Британские чипсы: цвета пачек перепутаны назло всей Европе, и никто не извинился. В сельском магазине такое вечно заваливалось за прилавок. Хруст разносится до соседней долины.", EnJ = "British crisps: the pack colours are swapped to spite all of Europe, and nobody apologised. In the village shop these kept slipping behind the counter. The crunch carries to the next valley.", Rare = false },
        new Def { Id = "WolkersBeef", Kind = Kind.Snack, Shape = "bag", Mesh = "Wolkers", Texture = "WolkersBeef", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс»", En = "Wolkers crisps", RuF = "говядина с луком", EnF = "beef & onion", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Британские чипсы: цвета пачек перепутаны назло всей Европе, и никто не извинился. Ждало покупателя дольше, чем тот прожил. Ешьте медленно: когда ещё такое найдёте.", EnJ = "British crisps: the pack colours are swapped to spite all of Europe, and nobody apologised. It waited for a buyer longer than the buyer lived. Eat slowly: who knows when you will find another.", Rare = false },
        new Def { Id = "WolkersPickled", Kind = Kind.Snack, Shape = "bag", Mesh = "Wolkers", Texture = "WolkersPickled", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс»", En = "Wolkers crisps", RuF = "маринованный лук", EnF = "pickled onion", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Британские чипсы: цвета пачек перепутаны назло всей Европе, и никто не извинился. С материка такое больше не привезут. К этому просится пиво, а есть только талый снег.", EnJ = "British crisps: the pack colours are swapped to spite all of Europe, and nobody apologised. Nobody will bring this from the mainland again. It begs for a beer, and there is only melted snow.", Rare = false },
        new Def { Id = "WolkersWorcester", Kind = Kind.Snack, Shape = "bag", Mesh = "Wolkers", Texture = "WolkersWorcester", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс»", En = "Wolkers crisps", RuF = "вустерский соус", EnF = "worcester sauce", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Британские чипсы: цвета пачек перепутаны назло всей Европе, и никто не извинился. На упаковке иней, внутри всё по-прежнему. Сияние на вкус не влияет. Наверное.", EnJ = "British crisps: the pack colours are swapped to spite all of Europe, and nobody apologised. Frost on the wrapper, business as usual inside. The aurora does not affect the taste. Probably.", Rare = false },
        new Def { Id = "WolkersKetchup", Kind = Kind.Snack, Shape = "bag", Mesh = "Wolkers", Texture = "WolkersKetchup", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс»", En = "Wolkers crisps", RuF = "томатный кетчуп", EnF = "tomato ketchup", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Британские чипсы: цвета пачек перепутаны назло всей Европе, и никто не извинился. Мороз ему нипочём: твёрже не стало, мягче тоже. После тушёнки из банки это почти ресторан.", EnJ = "British crisps: the pack colours are swapped to spite all of Europe, and nobody apologised. The frost did nothing to it: no harder, no softer. After stew from a tin this is nearly a restaurant.", Rare = false },
        new Def { Id = "WolkersMarmite", Kind = Kind.Snack, Shape = "bag", Mesh = "Wolkers", Texture = "WolkersMarmite", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс»", En = "Wolkers crisps", RuF = "дрожжевая паста", EnF = "yeast extract", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Британские чипсы: цвета пачек перепутаны назло всей Европе, и никто не извинился. Из тех времён, когда еду выбирали по вкусу. Делиться не с кем, и это впервые радует.", EnJ = "British crisps: the pack colours are swapped to spite all of Europe, and nobody apologised. From the days when people picked food for its taste. Nobody to share with, and for once that is good news.", Rare = false },
        new Def { Id = "WolkersBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Wolkers", Texture = "WolkersBBQ", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс»", En = "Wolkers crisps", RuF = "рёбрышки барбекю", EnF = "barbecue rib", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Британские чипсы: цвета пачек перепутаны назло всей Европе, и никто не извинился. Чей-то перекус на ночную смену, которая не кончилась. Пальцы потом оближите: зимой калории не выбрасывают.", EnJ = "British crisps: the pack colours are swapped to spite all of Europe, and nobody apologised. Someone's snack for a night shift that never ended. Lick your fingers after: in winter you do not waste calories.", Rare = false },
        new Def { Id = "MonstrOnion", Kind = Kind.Snack, Shape = "bag", Mesh = "Monstr", Texture = "MonstrOnion", Kg = 0.08f, Kcal = 400f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Монстр Манч»", En = "Monstr Manch corn puffs", RuF = "маринованный лук", EnF = "pickled onion", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Чипсы в форме лапы чудовища. Чудовище не возражало. В охотничьей вышке таким встречали рассвет. Ворон на ветке уже ждёт свою долю.", EnJ = "Crisps shaped like a monster's paw. The monster didn't object. In the hunting blind they met the dawn with this. The crow on the branch is already waiting for its share.", Rare = false },
        new Def { Id = "MonstrBeef", Kind = Kind.Snack, Shape = "bag", Mesh = "Monstr", Texture = "MonstrBeef", Kg = 0.08f, Kcal = 400f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Монстр Манч»", En = "Monstr Manch corn puffs", RuF = "ростбиф", EnF = "roast beef", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Чипсы в форме лапы чудовища. Чудовище не возражало. Такое носили в кармане куртки на всякий случай. Случай настал. На морозе хрустит вдвое громче.", EnJ = "Crisps shaped like a monster's paw. The monster didn't object. People carried these in a coat pocket just in case. The case has come. In the frost it crunches twice as loud.", Rare = false },
        new Def { Id = "MonstrHot", Kind = Kind.Snack, Shape = "bag", Mesh = "Monstr", Texture = "MonstrHot", Kg = 0.08f, Kcal = 400f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Монстр Манч»", En = "Monstr Manch corn puffs", RuF = "огненные", EnF = "flamin hot", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Чипсы в форме лапы чудовища. Чудовище не возражало. Прежний хозяин оставил записку: «Не трогать». Записка сгорела. Не еда, а настроение. Настроение тоже греет.", EnJ = "Crisps shaped like a monster's paw. The monster didn't object. The last owner left a note: 'Do not touch'. The note burned. Not food but a mood. A mood warms you too.", Rare = false },
        new Def { Id = "MonstrSpooky", Kind = Kind.Snack, Shape = "bag", Mesh = "Monstr", Texture = "MonstrSpooky", Kg = 0.08f, Kcal = 400f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Монстр Манч»", En = "Monstr Manch corn puffs", RuF = "жуткий маринованный лук", EnF = "spooky pickled onion", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Серия к Хэллоуину: редкость. Пугать тут и без неё есть кому. Такими торговали в поезде, пока поезд ходил. Сытости на час, воспоминаний на неделю.", EnJ = "A Halloween edition: a rarity. There is plenty to scare you here without it. They sold these on the train, while the train ran. An hour of fullness, a week of memories.", Rare = true },
        new Def { Id = "MonstrXmas", Kind = Kind.Snack, Shape = "bag", Mesh = "Monstr", Texture = "MonstrXmas", Kg = 0.08f, Kcal = 400f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Монстр Манч»", En = "Monstr Manch corn puffs", RuF = "рождественская индейка", EnF = "christmas turkey", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Сторож шахты держал такое в ящике стола. Кролик смотрит с осуждением.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. The mine watchman kept these in his desk drawer. The rabbit looks on with disapproval.", Rare = true },
        new Def { Id = "MonstrBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Monstr", Texture = "MonstrBacon", Kg = 0.08f, Kcal = 400f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Монстр Манч»", En = "Monstr Manch corn puffs", RuF = "бекон", EnF = "bacon", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Чипсы в форме лапы чудовища. Чудовище не возражало. Лавина прошла мимо, срок годности тоже. У костра вкуснее. У костра всё вкуснее.", EnJ = "Crisps shaped like a monster's paw. The monster didn't object. The avalanche missed it, and so did the best-before date. It tastes better by the fire. Everything does.", Rare = false },
        new Def { Id = "MonstrCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Monstr", Texture = "MonstrCheese", Kg = 0.08f, Kcal = 400f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Монстр Манч»", En = "Monstr Manch corn puffs", RuF = "сыр", EnF = "cheese", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Чипсы в форме лапы чудовища. Чудовище не возражало. Такое всегда стояло на видном месте, поэтому никто не брал. Упаковку не выбрасывайте: ею можно разжечь печь.", EnJ = "Crisps shaped like a monster's paw. The monster didn't object. These always stood in plain sight, which is why nobody took them. Keep the wrapper: it will light the stove.", Rare = false },
        new Def { Id = "MonstrVinegar", Kind = Kind.Snack, Shape = "bag", Mesh = "Monstr", Texture = "MonstrVinegar", Kg = 0.08f, Kcal = 400f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Монстр Манч»", En = "Monstr Manch corn puffs", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Чипсы в форме лапы чудовища. Чудовище не возражало. Кто-то открыл, передумал и умер. Не связано. Если это последняя на острове, вы её достойны.", EnJ = "Crisps shaped like a monster's paw. The monster didn't object. Someone opened it, changed their mind and died. Unrelated. If this is the last one on the island, you have earned it.", Rare = false },
        new Def { Id = "MonstrKetchup", Kind = Kind.Snack, Shape = "bag", Mesh = "Monstr", Texture = "MonstrKetchup", Kg = 0.08f, Kcal = 400f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Монстр Манч»", En = "Monstr Manch corn puffs", RuF = "кетчуп", EnF = "ketchup", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Чипсы в форме лапы чудовища. Чудовище не возражало. Такое вечно каталось под сиденьем пикапа. Желудок удивится, но возражать не станет.", EnJ = "Crisps shaped like a monster's paw. The monster didn't object. One of these was always rolling under a pickup seat. Your stomach will be surprised but will not object.", Rare = false },
        new Def { Id = "MonstrGiants", Kind = Kind.Snack, Shape = "bag", Mesh = "Monstr", Texture = "MonstrGiants", Kg = 0.08f, Kcal = 400f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Монстр Манч»", En = "Monstr Manch corn puffs", RuF = "гигантские", EnF = "giants", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Чипсы в форме лапы чудовища. Чудовище не возражало. Привезено паромом, которого больше нет. Запах выдаёт вас за сто шагов. Оно того стоит.", EnJ = "Crisps shaped like a monster's paw. The monster didn't object. Brought over by a ferry that no longer exists. The smell gives you away at a hundred paces. Worth it.", Rare = false },
        new Def { Id = "TwiglitzOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "Twiglitz", Texture = "TwiglitzOriginal", Kg = 0.113f, Kcal = 410f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Твиглитс»", En = "Twiglitz sticks", RuF = "дрожжевой экстракт", EnF = "original", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сучковатые палочки с дрожжевым вкусом: их либо любят, либо дарят. Раньше это ели под телевизор. Телевизор молчит. Раньше это называли вредным. Теперь называют едой.", EnJ = "Knobbly sticks with a yeasty taste: you either love them or give them away. People ate this in front of the telly. The telly is silent. They used to call this unhealthy. Now they call it food.", Rare = false },
        new Def { Id = "TwiglitzCurry", Kind = Kind.Snack, Shape = "bag", Mesh = "Twiglitz", Texture = "TwiglitzCurry", Kg = 0.113f, Kcal = 410f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Твиглитс»", En = "Twiglitz sticks", RuF = "карри", EnF = "curry", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Сучковатые палочки с дрожжевым вкусом: их либо любят, либо дарят. Забыто туристами, которым повезло уехать. Спальный мешок потом вытряхните.", EnJ = "Knobbly sticks with a yeasty taste: you either love them or give them away. Left behind by tourists who were lucky enough to leave. Shake out your sleeping bag afterwards.", Rare = false },
        new Def { Id = "TwiglitzWorcester", Kind = Kind.Snack, Shape = "bag", Mesh = "Twiglitz", Texture = "TwiglitzWorcester", Kg = 0.113f, Kcal = 410f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Твиглитс»", En = "Twiglitz sticks", RuF = "вустерский соус", EnF = "worcester sauce", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сучковатые палочки с дрожжевым вкусом: их либо любят, либо дарят. Механики заедали этим обед, не вытирая рук. Зимой такое идёт за валюту.", EnJ = "Knobbly sticks with a yeasty taste: you either love them or give them away. Mechanics ate these for lunch without wiping their hands. In winter this passes for currency.", Rare = false },
        new Def { Id = "TwiglitzXmas", Kind = Kind.Snack, Shape = "bag", Mesh = "Twiglitz", Texture = "TwiglitzXmas", Kg = 0.113f, Kcal = 410f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Твиглитс»", En = "Twiglitz sticks", RuF = "рождественские", EnF = "christmas", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Последнее на всю Одинокую топь. Скорее всего. Торговец дал бы за это тряпку. Вы дадите больше.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. The last one in all of Forlorn Muskeg. Most likely. The trader would give a rag for it. You would give more.", Rare = true },
        new Def { Id = "TwiglitzTangy", Kind = Kind.Snack, Shape = "bag", Mesh = "Twiglitz", Texture = "TwiglitzTangy", Kg = 0.113f, Kcal = 410f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Твиглитс»", En = "Twiglitz sticks", RuF = "пикантные", EnF = "tangy", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сучковатые палочки с дрожжевым вкусом: их либо любят, либо дарят. Смотритель маяка грыз такое, ожидая кораблей. Пока жуёте, метель кажется короче.", EnJ = "Knobbly sticks with a yeasty taste: you either love them or give them away. The lighthouse keeper munched these while waiting for ships. While you chew, the blizzard seems shorter.", Rare = false },
        new Def { Id = "TwiglitzCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Twiglitz", Texture = "TwiglitzCheese", Kg = 0.113f, Kcal = 410f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Твиглитс»", En = "Twiglitz sticks", RuF = "сыр", EnF = "cheese", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сучковатые палочки с дрожжевым вкусом: их либо любят, либо дарят. Полки рушились, а это уцелело. Организм скажет спасибо. Или не скажет.", EnJ = "Knobbly sticks with a yeasty taste: you either love them or give them away. Shelves collapsed and this survived. Your body will thank you. Or not.", Rare = false },
        new Def { Id = "TwiglitzChilli", Kind = Kind.Snack, Shape = "bag", Mesh = "Twiglitz", Texture = "TwiglitzChilli", Kg = 0.113f, Kcal = 410f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Твиглитс»", En = "Twiglitz sticks", RuF = "острые", EnF = "hot chilli", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Сучковатые палочки с дрожжевым вкусом: их либо любят, либо дарят. Смотритель заповедника называл это ужином. На третьей горсти забываешь, что вокруг конец света.", EnJ = "Knobbly sticks with a yeasty taste: you either love them or give them away. The park ranger called this dinner. By the third handful you forget the world has ended.", Rare = false },
        new Def { Id = "TwiglitzBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Twiglitz", Texture = "TwiglitzBacon", Kg = 0.113f, Kcal = 410f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Твиглитс»", En = "Twiglitz sticks", RuF = "бекон", EnF = "bacon", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сучковатые палочки с дрожжевым вкусом: их либо любят, либо дарят. Такое слали посылками с материка. Адресаты выбыли. Рыба подо льдом завидует.", EnJ = "Knobbly sticks with a yeasty taste: you either love them or give them away. These came in parcels from the mainland. The addressees are gone. The fish under the ice are jealous.", Rare = false },
        new Def { Id = "MrPorkiOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "MrPorki", Texture = "MrPorkiOriginal", Kg = 0.048f, Kcal = 220f, Thirst = -8f, Eat = 4f, Ru = "Свиные шкварки «Мистер Порки»", En = "Mr. Porki pork rinds", RuF = "оригинальные", EnF = "original", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "Sinew" }, RuJ = "Шкварки из паба: мистер на пачке при галстуке, содержимое без церемоний. Иные держали это за лекарство. Тоже лечит. Олень от такого отказался бы. Олень не голодал.", EnJ = "Pub pork scratchings: the mister on the pack wears a tie, the contents skip the ceremony. Some people counted this as medicine. Also a cure. A deer would turn it down. A deer has never starved.", Rare = false },
        new Def { Id = "MrPorkiCrispy", Kind = Kind.Snack, Shape = "bag", Mesh = "MrPorki", Texture = "MrPorkiCrispy", Kg = 0.048f, Kcal = 220f, Thirst = -8f, Eat = 4f, Ru = "Свиные шкварки «Мистер Порки»", En = "Mr. Porki pork rinds", RuF = "хрустящие", EnF = "crispy strips", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "Sinew" }, RuJ = "Шкварки из паба: мистер на пачке при галстуке, содержимое без церемоний. В школьном рюкзаке такое не доживало до обеда. Соль есть, жир есть, совести нет.", EnJ = "Pub pork scratchings: the mister on the pack wears a tie, the contents skip the ceremony. In a school bag this never lasted till lunch. Salt: yes. Fat: yes. Conscience: none.", Rare = false },
        new Def { Id = "MrPorkiHot", Kind = Kind.Snack, Shape = "bag", Mesh = "MrPorki", Texture = "MrPorkiHot", Kg = 0.048f, Kcal = 220f, Thirst = -8f, Eat = 4f, Ru = "Свиные шкварки «Мистер Порки»", En = "Mr. Porki pork rinds", RuF = "острые", EnF = "hot", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Шкварки из паба: мистер на пачке при галстуке, содержимое без церемоний. Его обменяли бы на патрон, будь тут с кем меняться. Ешьте до темноты: в темноте крошки не найти.", EnJ = "Pub pork scratchings: the mister on the pack wears a tie, the contents skip the ceremony. You could trade it for a cartridge, if there were anyone to trade with. Eat before dark: you cannot find crumbs in the dark.", Rare = false },
        new Def { Id = "MrPorkiBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "MrPorki", Texture = "MrPorkiBBQ", Kg = 0.048f, Kcal = 220f, Thirst = -8f, Eat = 4f, Ru = "Свиные шкварки «Мистер Порки»", En = "Mr. Porki pork rinds", RuF = "барбекю", EnF = "barbecue", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "Sinew" }, RuJ = "Шкварки из паба: мистер на пачке при галстуке, содержимое без церемоний. На вокзале это стоило втрое дороже. Теперь даром. Лучшее, что случится с вами сегодня.", EnJ = "Pub pork scratchings: the mister on the pack wears a tie, the contents skip the ceremony. At the station it cost three times as much. Now it is free. The best thing that will happen to you today.", Rare = false },
        new Def { Id = "MrPorkiVinegar", Kind = Kind.Snack, Shape = "bag", Mesh = "MrPorki", Texture = "MrPorkiVinegar", Kg = 0.048f, Kcal = 220f, Thirst = -8f, Eat = 4f, Ru = "Свиные шкварки «Мистер Порки»", En = "Mr. Porki pork rinds", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "Sinew" }, RuJ = "Шкварки из паба: мистер на пачке при галстуке, содержимое без церемоний. Пережило толчок и даже не помялось. Для полного счастья не хватает только дивана.", EnJ = "Pub pork scratchings: the mister on the pack wears a tie, the contents skip the ceremony. It came through the quake without a dent. All that is missing for perfect happiness is a sofa.", Rare = false },
        new Def { Id = "MrPorkiCrackles", Kind = Kind.Snack, Shape = "bag", Mesh = "MrPorki", Texture = "MrPorkiCrackles", Kg = 0.048f, Kcal = 220f, Thirst = -8f, Eat = 4f, Ru = "Свиные шкварки «Мистер Порки»", En = "Mr. Porki pork rinds", RuF = "шкварки", EnF = "crackles", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "Sinew" }, RuJ = "Шкварки из паба: мистер на пачке при галстуке, содержимое без церемоний. Китобои такого не ели, но оценили бы. Вкус детства, если детство было так себе.", EnJ = "Pub pork scratchings: the mister on the pack wears a tie, the contents skip the ceremony. The whalers never ate this, but they would have approved. The taste of childhood, if childhood was so-so.", Rare = false },
        new Def { Id = "MrPorkiMustard", Kind = Kind.Snack, Shape = "bag", Mesh = "MrPorki", Texture = "MrPorkiMustard", Kg = 0.048f, Kcal = 220f, Thirst = -8f, Eat = 4f, Ru = "Свиные шкварки «Мистер Порки»", En = "Mr. Porki pork rinds", RuF = "горчица", EnF = "mustard", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Шкварки из паба: мистер на пачке при галстуке, содержимое без церемоний. Осталось после чьего-то дня рождения. Гости не пришли. Шуршит как надежда.", EnJ = "Pub pork scratchings: the mister on the pack wears a tie, the contents skip the ceremony. Left over from someone's birthday. The guests never came. It rustles like hope.", Rare = false },
        new Def { Id = "FanniUngarisch", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanni", Texture = "FanniUngarisch", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш»", En = "Fanni-frisch crisps", RuF = "по-венгерски", EnF = "hungarian paprika", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкие чипсы: порядок на пачке, беспорядок на диване. Мерзлота хранит лучше любого холодильника. Голод отступит, жажда придёт. Честный обмен.", EnJ = "German crisps: order on the pack, disorder on the sofa. Permafrost keeps things better than any fridge. Hunger leaves, thirst arrives. A fair trade.", Rare = false },
        new Def { Id = "FanniOriental", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanni", Texture = "FanniOriental", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш»", En = "Fanni-frisch crisps", RuF = "ориентал", EnF = "oriental", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкие чипсы: порядок на пачке, беспорядок на диване. Такое добывали из автомата, который съедал последнюю монету. Не согреет, зато отвлечёт.", EnJ = "German crisps: order on the pack, disorder on the sofa. These came from the vending machine that ate your last coin. It will not warm you, but it will distract you.", Rare = false },
        new Def { Id = "FanniPeperoni", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanni", Texture = "FanniPeperoni", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш»", En = "Fanni-frisch crisps", RuF = "пеперони", EnF = "pepperoni", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Немецкие чипсы: порядок на пачке, беспорядок на диване. Такое брали в лодку под брезент, на весь день. Пума предпочитает мясо. Вам повезло.", EnJ = "German crisps: order on the pack, disorder on the sofa. People took these out in the boat under the tarpaulin, for the whole day. The cougar prefers meat. Lucky you.", Rare = false },
        new Def { Id = "FanniSour", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanni", Texture = "FanniSour", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш»", En = "Fanni-frisch crisps", RuF = "сметана", EnF = "sour cream", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкие чипсы: порядок на пачке, беспорядок на диване. С ним кто-то шёл к перевалу и не дошёл. Сначала попробуйте одну штучку. Шутка: ешьте всё.", EnJ = "German crisps: order on the pack, disorder on the sofa. Someone carried it towards the pass and never arrived. Try just one first. Joke: eat the lot.", Rare = false },
        new Def { Id = "FanniBratapfel", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanni", Texture = "FanniBratapfel", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш»", En = "Fanni-frisch crisps", RuF = "печёное яблоко с корицей", EnF = "baked apple cinnamon", RuC = "Германия", EnC = "Germany", Fx = new[] { "SugarDry" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. С таким сидели у окна с видом на метель. Такой ужин не стыдно записать в дневник.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. People sat with these at a window with a view of the blizzard. A dinner worth writing in the journal.", Rare = true },
        new Def { Id = "FanniGrill", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanni", Texture = "FanniGrill", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш»", En = "Fanni-frisch crisps", RuF = "летний гриль", EnF = "summer grill", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Уцелело там, где сгорело всё остальное. Силы прибавит на один сугроб.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. It survived where everything else burned. It will carry you one snowdrift further.", Rare = true },
        new Def { Id = "FanniZimt", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanni", Texture = "FanniZimt", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш»", En = "Fanni-frisch crisps", RuF = "корица и сахар", EnF = "cinnamon sugar", RuC = "Германия", EnC = "Germany", Fx = new[] { "SugarDry" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Этим кормили сторожевого пса. Пёс ушёл в волки. Идеально к закату, которого не видно за бураном.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. They fed the guard dog with this. The dog joined the wolves. Perfect with a sunset you cannot see for the storm.", Rare = true },
        new Def { Id = "FanniSalz", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanni", Texture = "FanniSalz", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш»", En = "Fanni-frisch crisps", RuF = "соль", EnF = "salted", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкие чипсы: порядок на пачке, беспорядок на диване. Из запасов лесорубов: брали ящиками. Пахнет магазином. Помните магазины?", EnJ = "German crisps: order on the pack, disorder on the sofa. From the loggers' stores: they bought it by the crate. It smells of a shop. Remember shops?", Rare = false },
        new Def { Id = "FanniZwiebel", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanni", Texture = "FanniZwiebel", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш»", En = "Fanni-frisch crisps", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкие чипсы: порядок на пачке, беспорядок на диване. В пост такое не ели. Пост кончился вместе с миром. Мороз не испортил, время не взяло.", EnJ = "German crisps: order on the pack, disorder on the sofa. Nobody ate these during a fast. The fast ended with the world. Frost did not spoil it and time could not take it.", Rare = false },
        new Def { Id = "FanniCurrywurst", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanni", Texture = "FanniCurrywurst", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш»", En = "Fanni-frisch crisps", RuF = "карривурст", EnF = "currywurst", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкие чипсы: порядок на пачке, беспорядок на диване. Теперь это ценнее денег. Деньги оставьте. В рюкзаке не мнётся. Почти.", EnJ = "German crisps: order on the pack, disorder on the sofa. It is worth more than money now. Leave the money. It does not get crushed in a pack. Almost.", Rare = false },
        new Def { Id = "FanniPommes", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanni", Texture = "FanniPommes", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш»", En = "Fanni-frisch crisps", RuF = "картошка фри с кетчупом", EnF = "fries with ketchup", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкие чипсы: порядок на пачке, беспорядок на диване. Его несли на пикник. Пикник отменили навсегда. Съешьте сейчас: завтра может не быть аппетита.", EnJ = "German crisps: order on the pack, disorder on the sofa. It was headed for a picnic. The picnic is cancelled forever. Eat it now: tomorrow you may have no appetite.", Rare = false },
        new Def { Id = "FanniKessel", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanni", Texture = "FanniKessel", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш»", En = "Fanni-frisch crisps", RuF = "котловые", EnF = "kettle cooked", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкие чипсы: порядок на пачке, беспорядок на диване. Такое стояло у кассы на случай слабости. Хватит дойти до следующей хижины и пожалеть, что кончилось.", EnJ = "German crisps: order on the pack, disorder on the sofa. These stood by the till for moments of weakness. Enough to reach the next cabin and regret it is gone.", Rare = false },
        new Def { Id = "FanniChakalaka", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanni", Texture = "FanniChakalaka", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш»", En = "Fanni-frisch crisps", RuF = "чакалака", EnF = "chakalaka", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкие чипсы: порядок на пачке, беспорядок на диване. Досталось вам, потому что вы дошли первым. От такого не толстеют те, кто ходит по двадцать километров.", EnJ = "German crisps: order on the pack, disorder on the sofa. It is yours because you got here first. Nobody who walks twenty kilometres a day gets fat on this.", Rare = false },
        new Def { Id = "FlippisKlassik", Kind = Kind.Snack, Shape = "bag", Mesh = "Flippis", Texture = "FlippisKlassik", Kg = 0.208f, Kcal = 1100f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Флиппис»", En = "Flippis corn puffs", RuF = "арахисовые", EnF = "peanut classic", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Арахисовые флипсы: выглядят как упаковочный наполнитель, едятся как праздник. Упаковка выцвела, внутри время остановилось. Волчья стая не в курсе. Пусть так и будет.", EnJ = "Peanut flips: they look like packing filler and eat like a holiday. The wrapper has faded; inside, time stood still. The wolf pack does not know. Keep it that way.", Rare = false },
        new Def { Id = "FlippisHonig", Kind = Kind.Snack, Shape = "bag", Mesh = "Flippis", Texture = "FlippisHonig", Kg = 0.208f, Kcal = 1100f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Флиппис»", En = "Flippis corn puffs", RuF = "мёд", EnF = "honey", RuC = "Германия", EnC = "Germany", Fx = new[] { "SugarDry" }, RuJ = "Арахисовые флипсы: выглядят как упаковочный наполнитель, едятся как праздник. Из чемодана пассажира, который не долетел. Калории мелкие, зато свои.", EnJ = "Peanut flips: they look like packing filler and eat like a holiday. From the suitcase of a passenger who never landed. Small calories, but your own.", Rare = false },
        new Def { Id = "FlippisPaprika", Kind = Kind.Snack, Shape = "bag", Mesh = "Flippis", Texture = "FlippisPaprika", Kg = 0.208f, Kcal = 1100f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Флиппис»", En = "Flippis corn puffs", RuF = "паприка", EnF = "paprika", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Арахисовые флипсы: выглядят как упаковочный наполнитель, едятся как праздник. Перезимовало и ничуть не обиделось. Лекарство от тоски, отпускается без рецепта.", EnJ = "Peanut flips: they look like packing filler and eat like a holiday. It made it through the winter and bears no grudge. A cure for the blues, no prescription needed.", Rare = false },
        new Def { Id = "FlippisLebkuchen", Kind = Kind.Snack, Shape = "bag", Mesh = "Flippis", Texture = "FlippisLebkuchen", Kg = 0.208f, Kcal = 1100f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Флиппис»", En = "Flippis corn puffs", RuF = "пряничные", EnF = "gingerbread", RuC = "Германия", EnC = "Germany", Fx = new[] { "SugarDry" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Запасливая хозяйка купила по акции шесть штук. Жуйте и думайте о хорошем. Например, о добавке.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. A thrifty housewife bought six of these on offer. Chew and think of nice things. Seconds, for example.", Rare = true },
        new Def { Id = "FlippisKase", Kind = Kind.Snack, Shape = "bag", Mesh = "Flippis", Texture = "FlippisKase", Kg = 0.208f, Kcal = 1100f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Флиппис»", En = "Flippis corn puffs", RuF = "сыр", EnF = "cheese", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Арахисовые флипсы: выглядят как упаковочный наполнитель, едятся как праздник. Кто-то написал на упаковке «моё». Уже нет. К утру от него останется только запах на варежках.", EnJ = "Peanut flips: they look like packing filler and eat like a holiday. Someone wrote 'mine' on it. Not any more. By morning only the smell on your mittens will be left.", Rare = false },
        new Def { Id = "FlippisMais", Kind = Kind.Snack, Shape = "bag", Mesh = "Flippis", Texture = "FlippisMais", Kg = 0.208f, Kcal = 1100f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Флиппис»", En = "Flippis corn puffs", RuF = "кукурузные", EnF = "corn", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Арахисовые флипсы: выглядят как упаковочный наполнитель, едятся как праздник. В консервном цеху это ели тайком от мастера. Тишина вокруг такая, что слышно, как вы жуёте.", EnJ = "Peanut flips: they look like packing filler and eat like a holiday. At the cannery they ate this behind the foreman's back. It is so quiet you can hear yourself chew.", Rare = false },
        new Def { Id = "FlippisSchoko", Kind = Kind.Snack, Shape = "bag", Mesh = "Flippis", Texture = "FlippisSchoko", Kg = 0.208f, Kcal = 1100f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Флиппис»", En = "Flippis corn puffs", RuF = "шоколад", EnF = "chocolate", RuC = "Германия", EnC = "Germany", Fx = new[] { "SugarDry" }, RuJ = "Арахисовые флипсы: выглядят как упаковочный наполнитель, едятся как праздник. Его не взяли даже мародёры. Они спешили. Не делите на завтра: завтра будет новый голод.", EnJ = "Peanut flips: they look like packing filler and eat like a holiday. Even the looters left it. They were in a hurry. Do not save half for tomorrow: tomorrow brings its own hunger.", Rare = false },
        new Def { Id = "FlippisScharf", Kind = Kind.Snack, Shape = "bag", Mesh = "Flippis", Texture = "FlippisScharf", Kg = 0.208f, Kcal = 1100f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Флиппис»", En = "Flippis corn puffs", RuF = "острые", EnF = "hot", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Арахисовые флипсы: выглядят как упаковочный наполнитель, едятся как праздник. Провело зиму на острове, как и вы. Сосны вокруг делают вид, что не смотрят.", EnJ = "Peanut flips: they look like packing filler and eat like a holiday. It spent the winter on the island, same as you. The pines around pretend not to watch.", Rare = false },
        new Def { Id = "SalzlettenKlassik", Kind = Kind.Snack, Shape = "carton", Mesh = "Salzletten", Texture = "SalzlettenKlassik", Kg = 0.258f, Kcal = 980f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Зальцлеттен»", En = "Salzletten sticks", RuF = "классические", EnF = "classic", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Солёная соломка в коробке: немецкая вечеринка началась, все сидят ровно. Дети прятали такое под кроватью, в тайнике. Калории мелкие, зато свои.", EnJ = "Salt sticks in a box: the German party has begun, everyone sits up straight. Children hid these under the bed, in a secret place. Small calories, but your own.", Rare = false },
        new Def { Id = "SalzlettenSesam", Kind = Kind.Snack, Shape = "carton", Mesh = "Salzletten", Texture = "SalzlettenSesam", Kg = 0.258f, Kcal = 980f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Зальцлеттен»", En = "Salzletten sticks", RuF = "кунжут", EnF = "sesame", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Солёная соломка в коробке: немецкая вечеринка началась, все сидят ровно. Осталось от геологов вместе с картой и долгами. После этого даже крапивный чай покажется десертом.", EnJ = "Salt sticks in a box: the German party has begun, everyone sits up straight. Left by the geologists along with a map and some debts. After this even nettle tea feels like dessert.", Rare = false },
        new Def { Id = "SalzlettenLaugen", Kind = Kind.Snack, Shape = "carton", Mesh = "Salzletten", Texture = "SalzlettenLaugen", Kg = 0.258f, Kcal = 980f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Зальцлеттен»", En = "Salzletten sticks", RuF = "брецель", EnF = "pretzel style", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Солёная соломка в коробке: немецкая вечеринка началась, все сидят ровно. На острове такое было праздником и до катастрофы. Нашедшему полагается всё.", EnJ = "Salt sticks in a box: the German party has begun, everyone sits up straight. On the island this was a treat even before the disaster. Finders keepers, all of it.", Rare = false },
        new Def { Id = "SalzlettenSilvester", Kind = Kind.Snack, Shape = "carton", Mesh = "Salzletten", Texture = "SalzlettenSilvester", Kg = 0.258f, Kcal = 980f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Зальцлеттен»", En = "Salzletten sticks", RuF = "новогодние", EnF = "new year", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Новогодняя серия: куранты отбили, а пачка осталась. Редкость. С таким слушали радио, которое теперь ловит только треск. Зубы целы? Тогда вперёд.", EnJ = "A New Year edition: the clock has struck, the pack remains. A rarity. People ate these by the radio, which picks up nothing but crackle now. Teeth intact? Then go ahead.", Rare = true },
        new Def { Id = "SalzlettenKummel", Kind = Kind.Snack, Shape = "carton", Mesh = "Salzletten", Texture = "SalzlettenKummel", Kg = 0.258f, Kcal = 980f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Зальцлеттен»", En = "Salzletten sticks", RuF = "с тмином", EnF = "caraway", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Солёная соломка в коробке: немецкая вечеринка началась, все сидят ровно. Крысы прогрызли соседнюю, эту пощадили. Ночью приснится добавка.", EnJ = "Salt sticks in a box: the German party has begun, everyone sits up straight. The rats gnawed through the one next to it and spared this. Tonight you will dream of seconds.", Rare = false },
        new Def { Id = "SalzlettenKase", Kind = Kind.Snack, Shape = "carton", Mesh = "Salzletten", Texture = "SalzlettenKase", Kg = 0.258f, Kcal = 980f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Зальцлеттен»", En = "Salzletten sticks", RuF = "с сыром", EnF = "cheese", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Солёная соломка в коробке: немецкая вечеринка началась, все сидят ровно. Бывший хозяин клялся бросить. Не успел. С таким запасом можно пережить ещё один вечер.", EnJ = "Salt sticks in a box: the German party has begun, everyone sits up straight. The former owner swore to give these up. He ran out of time. With supplies like this you can survive one more evening.", Rare = false },
        new Def { Id = "SalzlettenMohn", Kind = Kind.Snack, Shape = "carton", Mesh = "Salzletten", Texture = "SalzlettenMohn", Kg = 0.258f, Kcal = 980f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Зальцлеттен»", En = "Salzletten sticks", RuF = "с маком", EnF = "poppy seed", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Солёная соломка в коробке: немецкая вечеринка началась, все сидят ровно. Его катали в кабине трактора три сезона. Пёс бы выпросил половину. Пса нет.", EnJ = "Salt sticks in a box: the German party has begun, everyone sits up straight. It rode around in a tractor cab for three seasons. A dog would beg half of it. There is no dog.", Rare = false },
        new Def { Id = "SalzlettenDinkel", Kind = Kind.Snack, Shape = "carton", Mesh = "Salzletten", Texture = "SalzlettenDinkel", Kg = 0.258f, Kcal = 980f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Зальцлеттен»", En = "Salzletten sticks", RuF = "из спельты", EnF = "spelt", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Солёная соломка в коробке: немецкая вечеринка началась, все сидят ровно. После бани такое шло лучше всего. Съедено будет быстрее, чем найдено.", EnJ = "Salt sticks in a box: the German party has begun, everyone sits up straight. Nothing went down better after the sauna. It will be eaten faster than it was found.", Rare = false },
        new Def { Id = "SabritozSal", Kind = Kind.Snack, Shape = "bag", Mesh = "Sabritoz", Texture = "SabritozSal", Kg = 0.168f, Kcal = 860f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сабритоз»", En = "Sabritoz crisps", RuF = "с солью", EnF = "salted", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold" }, RuJ = "Мексиканские чипсы: без лимона и перца их там за еду не считают. В тюрьме на это выменивали что угодно. На вкус как выходной.", EnJ = "Mexican crisps: without lime and chilli nobody there calls them food. In the prison you could trade one of these for anything. It tastes like a day off.", Rare = false },
        new Def { Id = "SabritozAdobadas", Kind = Kind.Snack, Shape = "bag", Mesh = "Sabritoz", Texture = "SabritozAdobadas", Kg = 0.168f, Kcal = 860f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сабритоз»", En = "Sabritoz crisps", RuF = "адобо", EnF = "adobadas", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Мексиканские чипсы: без лимона и перца их там за еду не считают. Кто-то менял это на сигареты. Сделка сорвалась. Ветер унесёт запах прямо к берлоге. Ешьте быстрее.", EnJ = "Mexican crisps: without lime and chilli nobody there calls them food. Someone was trading this for cigarettes. The deal fell through. The wind carries the smell straight to the den. Eat faster.", Rare = false },
        new Def { Id = "SabritozLimon", Kind = Kind.Snack, Shape = "bag", Mesh = "Sabritoz", Texture = "SabritozLimon", Kg = 0.168f, Kcal = 860f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сабритоз»", En = "Sabritoz crisps", RuF = "лимон", EnF = "lime", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold" }, RuJ = "Мексиканские чипсы: без лимона и перца их там за еду не считают. С ним зимовали на метеостанции, пока было с кем. Пополняет запас соли и веры в человечество.", EnJ = "Mexican crisps: without lime and chilli nobody there calls them food. They wintered with it at the weather station, while there was a 'they'. Restores your salt and your faith in mankind.", Rare = false },
        new Def { Id = "SabritozHabanero", Kind = Kind.Snack, Shape = "bag", Mesh = "Sabritoz", Texture = "SabritozHabanero", Kg = 0.168f, Kcal = 860f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сабритоз»", En = "Sabritoz crisps", RuF = "хабанеро", EnF = "habanero", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Мексиканские чипсы: без лимона и перца их там за еду не считают. Такое терялось в кладовке среди крупы и надежд. Хорошо идёт под треск поленьев.", EnJ = "Mexican crisps: without lime and chilli nobody there calls them food. These got lost in the pantry among the grain and the hopes. Goes down well with crackling logs.", Rare = false },
        new Def { Id = "SabritozMole", Kind = Kind.Snack, Shape = "bag", Mesh = "Sabritoz", Texture = "SabritozMole", Kg = 0.168f, Kcal = 860f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сабритоз»", En = "Sabritoz crisps", RuF = "моле ко Дню мёртвых", EnF = "day of the dead mole", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold" }, RuJ = "Серия к Хэллоуину: редкость. Пугать тут и без неё есть кому. Его берегли к приезду внуков. Руки вытирать о штаны: салфеток не завезли.", EnJ = "A Halloween edition: a rarity. There is plenty to scare you here without it. It was being saved for the grandchildren's visit. Wipe your hands on your trousers: no napkins were delivered.", Rare = true },
        new Def { Id = "SabritozMuertos", Kind = Kind.Snack, Shape = "bag", Mesh = "Sabritoz", Texture = "SabritozMuertos", Kg = 0.168f, Kcal = 860f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сабритоз»", En = "Sabritoz crisps", RuF = "ко Дню мёртвых", EnF = "day of the dead", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold" }, RuJ = "Серия к Хэллоуину: редкость. Пугать тут и без неё есть кому. В баре такое ставили на стойку, бесплатно к пиву. Пива нет. Маленькая радость размером с ладонь.", EnJ = "A Halloween edition: a rarity. There is plenty to scare you here without it. Bars put these out free with a beer. There is no beer. A small joy the size of your palm.", Rare = true },
        new Def { Id = "SabritozQueso", Kind = Kind.Snack, Shape = "bag", Mesh = "Sabritoz", Texture = "SabritozQueso", Kg = 0.168f, Kcal = 860f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сабритоз»", En = "Sabritoz crisps", RuF = "сыр", EnF = "cheese", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold" }, RuJ = "Мексиканские чипсы: без лимона и перца их там за еду не считают. Такое лежало в каждом доме, пока не погас свет. Совесть молчит, живот поёт.", EnJ = "Mexican crisps: without lime and chilli nobody there calls them food. Every house had one of these until the lights went out. Conscience is silent, the belly sings.", Rare = false },
        new Def { Id = "SabritozChile", Kind = Kind.Snack, Shape = "bag", Mesh = "Sabritoz", Texture = "SabritozChile", Kg = 0.168f, Kcal = 860f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сабритоз»", En = "Sabritoz crisps", RuF = "чили и сыр", EnF = "chilli & cheese", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Мексиканские чипсы: без лимона и перца их там за еду не считают. Кто-то берёг это на чёрный день. Он настал. Проверено поколениями и одной катастрофой.", EnJ = "Mexican crisps: without lime and chilli nobody there calls them food. Someone saved this for a rainy day. It came. Tested by generations and one catastrophe.", Rare = false },
        new Def { Id = "SabritozCrema", Kind = Kind.Snack, Shape = "bag", Mesh = "Sabritoz", Texture = "SabritozCrema", Kg = 0.168f, Kcal = 860f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сабритоз»", En = "Sabritoz crisps", RuF = "сметана и специи", EnF = "cream & spices", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SugarDry" }, RuJ = "Мексиканские чипсы: без лимона и перца их там за еду не считают. Пережило хозяина, кота и две зимы. Оставьте пару штук на перевал. Не оставите.", EnJ = "Mexican crisps: without lime and chilli nobody there calls them food. It outlived its owner, the cat and two winters. Save a couple for the pass. You will not.", Rare = false },
        new Def { Id = "SabritozFlamin", Kind = Kind.Snack, Shape = "bag", Mesh = "Sabritoz", Texture = "SabritozFlamin", Kg = 0.168f, Kcal = 860f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сабритоз»", En = "Sabritoz crisps", RuF = "огненные", EnF = "flamin hot", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Мексиканские чипсы: без лимона и перца их там за еду не считают. Такое обычно находили за диваном, как всё лучшее в жизни. Здесь это считается ужином при свечах.", EnJ = "Mexican crisps: without lime and chilli nobody there calls them food. These were usually found behind the sofa, like all the best things in life. Round here this counts as a candlelit dinner.", Rare = false },
        new Def { Id = "SabritozJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "Sabritoz", Texture = "SabritozJalapeno", Kg = 0.168f, Kcal = 860f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сабритоз»", En = "Sabritoz crisps", RuF = "халапеньо", EnF = "jalapeno", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Мексиканские чипсы: без лимона и перца их там за еду не считают. Последний завоз был до того, как упали самолёты. Луна светит, еда хрустит, жизнь налаживается.", EnJ = "Mexican crisps: without lime and chilli nobody there calls them food. The last delivery came before the planes fell. The moon shines, the food crunches, life is looking up.", Rare = false },
        new Def { Id = "TakizFuego", Kind = Kind.Snack, Shape = "bag", Mesh = "Takiz", Texture = "TakizFuego", Kg = 0.288f, Kcal = 1400f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Такиз»", En = "Takiz rolled tortilla chips", RuF = "огонь: чили и лайм", EnF = "fuego", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Скрученные трубочки цвета пожарной машины: пальцы потом красные неделю. Ценник оторван: теперь это бесценно. Снег вокруг не солёный. Это солёное.", EnJ = "Rolled tubes the colour of a fire engine: your fingers stay red for a week. The price tag is torn off: it is priceless now. The snow around is not salty. This is.", Rare = false },
        new Def { Id = "TakizNitro", Kind = Kind.Snack, Shape = "bag", Mesh = "Takiz", Texture = "TakizNitro", Kg = 0.288f, Kcal = 1400f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Такиз»", En = "Takiz rolled tortilla chips", RuF = "нитро: хабанеро", EnF = "nitro", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Скрученные трубочки цвета пожарной машины: пальцы потом красные неделю. Дата на шве стёрлась, и слава богу. Больше таких не делают. Совсем.", EnJ = "Rolled tubes the colour of a fire engine: your fingers stay red for a week. The date on the seam has rubbed off, thank goodness. They do not make these any more. At all.", Rare = false },
        new Def { Id = "TakizGuacamole", Kind = Kind.Snack, Shape = "bag", Mesh = "Takiz", Texture = "TakizGuacamole", Kg = 0.288f, Kcal = 1400f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Такиз»", En = "Takiz rolled tortilla chips", RuF = "гуакамоле", EnF = "guacamole", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Скрученные трубочки цвета пожарной машины: пальцы потом красные неделю. Пахнет заправкой у Прибрежного шоссе. Открывайте тихо: у волков отличный слух.", EnJ = "Rolled tubes the colour of a fire engine: your fingers stay red for a week. It smells of the petrol station on the Coastal Highway. Open it quietly: wolves have excellent hearing.", Rare = false },
        new Def { Id = "TakizBlue", Kind = Kind.Snack, Shape = "bag", Mesh = "Takiz", Texture = "TakizBlue", Kg = 0.288f, Kcal = 1400f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Такиз»", En = "Takiz rolled tortilla chips", RuF = "синее пламя", EnF = "blue heat", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Скрученные трубочки цвета пожарной машины: пальцы потом красные неделю. Такое возили в бардачке на дальнюю дорогу. Дороги кончились. Одной не обойдётся, но вторая неизвестно где.", EnJ = "Rolled tubes the colour of a fire engine: your fingers stay red for a week. People kept these in the glovebox for long drives. The drives are over. One won't be enough, and nobody knows where the second is.", Rare = false },
        new Def { Id = "TakizZombie", Kind = Kind.Snack, Shape = "bag", Mesh = "Takiz", Texture = "TakizZombie", Kg = 0.288f, Kcal = 1400f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Такиз»", En = "Takiz rolled tortilla chips", RuF = "зомби: огурец и хабанеро", EnF = "zombie habanero cucumber", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Серия к Хэллоуину: редкость. Пугать тут и без неё есть кому. Мыши не тронули. Думайте сами. Крошки с пола тоже считаются.", EnJ = "A Halloween edition: a rarity. There is plenty to scare you here without it. The mice left it alone. Draw your own conclusions. The crumbs on the floor count too.", Rare = true },
        new Def { Id = "TakizNavidad", Kind = Kind.Snack, Shape = "bag", Mesh = "Takiz", Texture = "TakizNavidad", Kg = 0.288f, Kcal = 1400f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Такиз»", En = "Takiz rolled tortilla chips", RuF = "рождественский пунш", EnF = "christmas punch", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Рыбаки брали такое на лёд вместо обеда. Запейте чаем из шиповника и считайте это обедом.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. Fishermen took this onto the ice instead of lunch. Wash it down with rosehip tea and call it lunch.", Rare = true },
        new Def { Id = "TakizXplosion", Kind = Kind.Snack, Shape = "bag", Mesh = "Takiz", Texture = "TakizXplosion", Kg = 0.288f, Kcal = 1400f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Такиз»", En = "Takiz rolled tortilla chips", RuF = "сыр и чили", EnF = "cheese & chilli", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Скрученные трубочки цвета пожарной машины: пальцы потом красные неделю. Смотритель плотины держал такое в заначке. Медведю не показывать: отнимет вместе с рукой.", EnJ = "Rolled tubes the colour of a fire engine: your fingers stay red for a week. The dam keeper kept a stash of these. Do not show the bear: he will take it, hand and all.", Rare = false },
        new Def { Id = "TakizSalsa", Kind = Kind.Snack, Shape = "bag", Mesh = "Takiz", Texture = "TakizSalsa", Kg = 0.288f, Kcal = 1400f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Такиз»", En = "Takiz rolled tortilla chips", RuF = "острая сальса", EnF = "hot salsa", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Скрученные трубочки цвета пожарной машины: пальцы потом красные неделю. Кто-то спрятал это от детей. Дети не нашли. Диетолог не одобрил бы. Диетолога тут нет.", EnJ = "Rolled tubes the colour of a fire engine: your fingers stay red for a week. Someone hid it from the kids. The kids never found it. A dietitian would not approve. There is no dietitian here.", Rare = false },
        new Def { Id = "TakizWild", Kind = Kind.Snack, Shape = "bag", Mesh = "Takiz", Texture = "TakizWild", Kg = 0.288f, Kcal = 1400f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Такиз»", En = "Takiz rolled tortilla chips", RuF = "острый буйвол", EnF = "hot buffalo", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Скрученные трубочки цвета пожарной машины: пальцы потом красные неделю. В сельском магазине такое вечно заваливалось за прилавок. Лучше, чем кора. Проверено.", EnJ = "Rolled tubes the colour of a fire engine: your fingers stay red for a week. In the village shop these kept slipping behind the counter. Better than bark. Tested.", Rare = false },
        new Def { Id = "TakizCrunchy", Kind = Kind.Snack, Shape = "bag", Mesh = "Takiz", Texture = "TakizCrunchy", Kg = 0.288f, Kcal = 1400f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Такиз»", En = "Takiz rolled tortilla chips", RuF = "фахита", EnF = "fajita", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Скрученные трубочки цвета пожарной машины: пальцы потом красные неделю. Ждало покупателя дольше, чем тот прожил. Хруст разносится до соседней долины.", EnJ = "Rolled tubes the colour of a fire engine: your fingers stay red for a week. It waited for a buyer longer than the buyer lived. The crunch carries to the next valley.", Rare = false },
        new Def { Id = "TakizDragon", Kind = Kind.Snack, Shape = "bag", Mesh = "Takiz", Texture = "TakizDragon", Kg = 0.288f, Kcal = 1400f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Такиз»", En = "Takiz rolled tortilla chips", RuF = "сладкий чили", EnF = "sweet chilli", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Скрученные трубочки цвета пожарной машины: пальцы потом красные неделю. С материка такое больше не привезут. Ешьте медленно: когда ещё такое найдёте.", EnJ = "Rolled tubes the colour of a fire engine: your fingers stay red for a week. Nobody will bring this from the mainland again. Eat slowly: who knows when you will find another.", Rare = false },
        new Def { Id = "TakizIntense", Kind = Kind.Snack, Shape = "bag", Mesh = "Takiz", Texture = "TakizIntense", Kg = 0.288f, Kcal = 1400f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Такиз»", En = "Takiz rolled tortilla chips", RuF = "начо", EnF = "nacho", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Скрученные трубочки цвета пожарной машины: пальцы потом красные неделю. На упаковке иней, внутри всё по-прежнему. К этому просится пиво, а есть только талый снег.", EnJ = "Rolled tubes the colour of a fire engine: your fingers stay red for a week. Frost on the wrapper, business as usual inside. It begs for a beer, and there is only melted snow.", Rare = false },
        new Def { Id = "ChurritozLimon", Kind = Kind.Snack, Shape = "bag", Mesh = "Churritoz", Texture = "ChurritozLimon", Kg = 0.128f, Kcal = 650f, Thirst = -8f, Eat = 4f, Ru = "Картофельная соломка «Чурритоз»", En = "Churritoz potato sticks", RuF = "лимон и соль", EnF = "lime & salt", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold" }, RuJ = "Мексиканская соломка: её поливают соусом прямо в пакете и едят ложкой. Мороз ему нипочём: твёрже не стало, мягче тоже. Сияние на вкус не влияет. Наверное.", EnJ = "Mexican sticks: you pour sauce right into the bag and eat with a spoon. The frost did nothing to it: no harder, no softer. The aurora does not affect the taste. Probably.", Rare = false },
        new Def { Id = "ChurritozChile", Kind = Kind.Snack, Shape = "bag", Mesh = "Churritoz", Texture = "ChurritozChile", Kg = 0.128f, Kcal = 650f, Thirst = -8f, Eat = 4f, Ru = "Картофельная соломка «Чурритоз»", En = "Churritoz potato sticks", RuF = "чили", EnF = "chilli", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Мексиканская соломка: её поливают соусом прямо в пакете и едят ложкой. Из тех времён, когда еду выбирали по вкусу. После тушёнки из банки это почти ресторан.", EnJ = "Mexican sticks: you pour sauce right into the bag and eat with a spoon. From the days when people picked food for its taste. After stew from a tin this is nearly a restaurant.", Rare = false },
        new Def { Id = "ChurritozQueso", Kind = Kind.Snack, Shape = "bag", Mesh = "Churritoz", Texture = "ChurritozQueso", Kg = 0.128f, Kcal = 650f, Thirst = -8f, Eat = 4f, Ru = "Картофельная соломка «Чурритоз»", En = "Churritoz potato sticks", RuF = "сыр", EnF = "cheese", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold" }, RuJ = "Мексиканская соломка: её поливают соусом прямо в пакете и едят ложкой. Чей-то перекус на ночную смену, которая не кончилась. Делиться не с кем, и это впервые радует.", EnJ = "Mexican sticks: you pour sauce right into the bag and eat with a spoon. Someone's snack for a night shift that never ended. Nobody to share with, and for once that is good news.", Rare = false },
        new Def { Id = "ChurritozFuego", Kind = Kind.Snack, Shape = "bag", Mesh = "Churritoz", Texture = "ChurritozFuego", Kg = 0.128f, Kcal = 650f, Thirst = -8f, Eat = 4f, Ru = "Картофельная соломка «Чурритоз»", En = "Churritoz potato sticks", RuF = "огненные", EnF = "fiery hot", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Мексиканская соломка: её поливают соусом прямо в пакете и едят ложкой. В охотничьей вышке таким встречали рассвет. Пальцы потом оближите: зимой калории не выбрасывают.", EnJ = "Mexican sticks: you pour sauce right into the bag and eat with a spoon. In the hunting blind they met the dawn with this. Lick your fingers after: in winter you do not waste calories.", Rare = false },
        new Def { Id = "ChurritozSal", Kind = Kind.Snack, Shape = "bag", Mesh = "Churritoz", Texture = "ChurritozSal", Kg = 0.128f, Kcal = 650f, Thirst = -8f, Eat = 4f, Ru = "Картофельная соломка «Чурритоз»", En = "Churritoz potato sticks", RuF = "с солью", EnF = "salted", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold" }, RuJ = "Мексиканская соломка: её поливают соусом прямо в пакете и едят ложкой. Такое носили в кармане куртки на всякий случай. Случай настал. Ворон на ветке уже ждёт свою долю.", EnJ = "Mexican sticks: you pour sauce right into the bag and eat with a spoon. People carried these in a coat pocket just in case. The case has come. The crow on the branch is already waiting for its share.", Rare = false },
        new Def { Id = "ChurritozHabanero", Kind = Kind.Snack, Shape = "bag", Mesh = "Churritoz", Texture = "ChurritozHabanero", Kg = 0.128f, Kcal = 650f, Thirst = -8f, Eat = 4f, Ru = "Картофельная соломка «Чурритоз»", En = "Churritoz potato sticks", RuF = "хабанеро", EnF = "habanero", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Мексиканская соломка: её поливают соусом прямо в пакете и едят ложкой. Прежний хозяин оставил записку: «Не трогать». Записка сгорела. На морозе хрустит вдвое громче.", EnJ = "Mexican sticks: you pour sauce right into the bag and eat with a spoon. The last owner left a note: 'Do not touch'. The note burned. In the frost it crunches twice as loud.", Rare = false },
        new Def { Id = "ChurritozTamarindo", Kind = Kind.Snack, Shape = "bag", Mesh = "Churritoz", Texture = "ChurritozTamarindo", Kg = 0.128f, Kcal = 650f, Thirst = -8f, Eat = 4f, Ru = "Картофельная соломка «Чурритоз»", En = "Churritoz potato sticks", RuF = "тамаринд", EnF = "tamarind", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold" }, RuJ = "Мексиканская соломка: её поливают соусом прямо в пакете и едят ложкой. Такими торговали в поезде, пока поезд ходил. Не еда, а настроение. Настроение тоже греет.", EnJ = "Mexican sticks: you pour sauce right into the bag and eat with a spoon. They sold these on the train, while the train ran. Not food but a mood. A mood warms you too.", Rare = false },
        new Def { Id = "BretzPoulet", Kind = Kind.Snack, Shape = "bag", Mesh = "Bretz", Texture = "BretzPoulet", Kg = 0.133f, Kcal = 670f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Бретц»", En = "Bretz ridged crisps", RuF = "жареная курица", EnF = "braised chicken", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Французские чипсы со вкусами, которые придумали на спор. Сторож шахты держал такое в ящике стола. Сытости на час, воспоминаний на неделю.", EnJ = "French crisps in flavours invented on a dare. The mine watchman kept these in his desk drawer. An hour of fullness, a week of memories.", Rare = false },
        new Def { Id = "BretzFromage", Kind = Kind.Snack, Shape = "bag", Mesh = "Bretz", Texture = "BretzFromage", Kg = 0.133f, Kcal = 670f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Бретц»", En = "Bretz ridged crisps", RuF = "сыр из Юры", EnF = "Jura cheese", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Французские чипсы со вкусами, которые придумали на спор. Лавина прошла мимо, срок годности тоже. Кролик смотрит с осуждением.", EnJ = "French crisps in flavours invented on a dare. The avalanche missed it, and so did the best-before date. The rabbit looks on with disapproval.", Rare = false },
        new Def { Id = "BretzChevre", Kind = Kind.Snack, Shape = "bag", Mesh = "Bretz", Texture = "BretzChevre", Kg = 0.133f, Kcal = 670f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Бретц»", En = "Bretz ridged crisps", RuF = "козий сыр и перец", EnF = "goat cheese & chilli", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Французские чипсы со вкусами, которые придумали на спор. Такое всегда стояло на видном месте, поэтому никто не брал. У костра вкуснее. У костра всё вкуснее.", EnJ = "French crisps in flavours invented on a dare. These always stood in plain sight, which is why nobody took them. It tastes better by the fire. Everything does.", Rare = false },
        new Def { Id = "BretzNature", Kind = Kind.Snack, Shape = "bag", Mesh = "Bretz", Texture = "BretzNature", Kg = 0.133f, Kcal = 670f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Бретц»", En = "Bretz ridged crisps", RuF = "с солью", EnF = "salted", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Французские чипсы со вкусами, которые придумали на спор. Кто-то открыл, передумал и умер. Не связано. Упаковку не выбрасывайте: ею можно разжечь печь.", EnJ = "French crisps in flavours invented on a dare. Someone opened it, changed their mind and died. Unrelated. Keep the wrapper: it will light the stove.", Rare = false },
        new Def { Id = "BretzRaclette", Kind = Kind.Snack, Shape = "bag", Mesh = "Bretz", Texture = "BretzRaclette", Kg = 0.133f, Kcal = 670f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Бретц»", En = "Bretz ridged crisps", RuF = "раклет", EnF = "raclette", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Зимняя серия: выпускали на один сезон, а зима тут навсегда. Такое вечно каталось под сиденьем пикапа. Если это последняя на острове, вы её достойны.", EnJ = "A winter edition: made for one season, and here winter is forever. One of these was always rolling under a pickup seat. If this is the last one on the island, you have earned it.", Rare = true },
        new Def { Id = "BretzNoel", Kind = Kind.Snack, Shape = "bag", Mesh = "Bretz", Texture = "BretzNoel", Kg = 0.133f, Kcal = 670f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Бретц»", En = "Bretz ridged crisps", RuF = "рождественский фуа-гра", EnF = "christmas foie gras", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Привезено паромом, которого больше нет. Желудок удивится, но возражать не станет.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. Brought over by a ferry that no longer exists. Your stomach will be surprised but will not object.", Rare = true },
        new Def { Id = "BretzEte", Kind = Kind.Snack, Shape = "bag", Mesh = "Bretz", Texture = "BretzEte", Kg = 0.133f, Kcal = 670f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Бретц»", En = "Bretz ridged crisps", RuF = "летний рататуй", EnF = "summer ratatouille", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Раньше это ели под телевизор. Телевизор молчит. Запах выдаёт вас за сто шагов. Оно того стоит.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. People ate this in front of the telly. The telly is silent. The smell gives you away at a hundred paces. Worth it.", Rare = true },
        new Def { Id = "BretzBarbecue", Kind = Kind.Snack, Shape = "bag", Mesh = "Bretz", Texture = "BretzBarbecue", Kg = 0.133f, Kcal = 670f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Бретц»", En = "Bretz ridged crisps", RuF = "барбекю", EnF = "barbecue", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Французские чипсы со вкусами, которые придумали на спор. Забыто туристами, которым повезло уехать. Раньше это называли вредным. Теперь называют едой.", EnJ = "French crisps in flavours invented on a dare. Left behind by tourists who were lucky enough to leave. They used to call this unhealthy. Now they call it food.", Rare = false },
        new Def { Id = "BretzCarbonara", Kind = Kind.Snack, Shape = "bag", Mesh = "Bretz", Texture = "BretzCarbonara", Kg = 0.133f, Kcal = 670f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Бретц»", En = "Bretz ridged crisps", RuF = "карбонара", EnF = "carbonara", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Французские чипсы со вкусами, которые придумали на спор. Механики заедали этим обед, не вытирая рук. Спальный мешок потом вытряхните.", EnJ = "French crisps in flavours invented on a dare. Mechanics ate these for lunch without wiping their hands. Shake out your sleeping bag afterwards.", Rare = false },
        new Def { Id = "BretzAioli", Kind = Kind.Snack, Shape = "bag", Mesh = "Bretz", Texture = "BretzAioli", Kg = 0.133f, Kcal = 670f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Бретц»", En = "Bretz ridged crisps", RuF = "айоли", EnF = "aioli", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Французские чипсы со вкусами, которые придумали на спор. Последнее на всю Одинокую топь. Скорее всего. Зимой такое идёт за валюту.", EnJ = "French crisps in flavours invented on a dare. The last one in all of Forlorn Muskeg. Most likely. In winter this passes for currency.", Rare = false },
        new Def { Id = "BretzMoutarde", Kind = Kind.Snack, Shape = "bag", Mesh = "Bretz", Texture = "BretzMoutarde", Kg = 0.133f, Kcal = 670f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Бретц»", En = "Bretz ridged crisps", RuF = "горчица и соленья", EnF = "mustard & pickles", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Французские чипсы со вкусами, которые придумали на спор. Смотритель маяка грыз такое, ожидая кораблей. Торговец дал бы за это тряпку. Вы дадите больше.", EnJ = "French crisps in flavours invented on a dare. The lighthouse keeper munched these while waiting for ships. The trader would give a rag for it. You would give more.", Rare = false },
        new Def { Id = "BretzIndian", Kind = Kind.Snack, Shape = "bag", Mesh = "Bretz", Texture = "BretzIndian", Kg = 0.133f, Kcal = 670f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Бретц»", En = "Bretz ridged crisps", RuF = "карри по-индийски", EnF = "indian curry", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Французские чипсы со вкусами, которые придумали на спор. Полки рушились, а это уцелело. Пока жуёте, метель кажется короче.", EnJ = "French crisps in flavours invented on a dare. Shelves collapsed and this survived. While you chew, the blizzard seems shorter.", Rare = false },
        new Def { Id = "BretzBolognaise", Kind = Kind.Snack, Shape = "bag", Mesh = "Bretz", Texture = "BretzBolognaise", Kg = 0.133f, Kcal = 670f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Бретц»", En = "Bretz ridged crisps", RuF = "болоньезе", EnF = "bolognese", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Французские чипсы со вкусами, которые придумали на спор. Смотритель заповедника называл это ужином. Организм скажет спасибо. Или не скажет.", EnJ = "French crisps in flavours invented on a dare. The park ranger called this dinner. Your body will thank you. Or not.", Rare = false },
        new Def { Id = "BretzMiel", Kind = Kind.Snack, Shape = "bag", Mesh = "Bretz", Texture = "BretzMiel", Kg = 0.133f, Kcal = 670f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Бретц»", En = "Bretz ridged crisps", RuF = "мёд и горчица", EnF = "honey mustard", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Французские чипсы со вкусами, которые придумали на спор. Такое слали посылками с материка. Адресаты выбыли. На третьей горсти забываешь, что вокруг конец света.", EnJ = "French crisps in flavours invented on a dare. These came in parcels from the mainland. The addressees are gone. By the third handful you forget the world has ended.", Rare = false },
        new Def { Id = "FakundoSal", Kind = Kind.Snack, Shape = "bag", Mesh = "Fakundo", Texture = "FakundoSal", Kg = 0.168f, Kcal = 930f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Факундо»", En = "Fakundo seeds", RuF = "с солью", EnF = "salted", RuC = "Испания", EnC = "Spain", Fx = new[] { "SeedHabit" }, RuJ = "Испанские семечки: на пачке сеньор, под скамейкой гора шелухи. Иные держали это за лекарство. Тоже лечит. Рыба подо льдом завидует.", EnJ = "Spanish seeds: a señor on the pack, a hill of shells under the bench. Some people counted this as medicine. Also a cure. The fish under the ice are jealous.", Rare = false },
        new Def { Id = "FakundoSinsal", Kind = Kind.Snack, Shape = "bag", Mesh = "Fakundo", Texture = "FakundoSinsal", Kg = 0.168f, Kcal = 930f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Факундо»", En = "Fakundo seeds", RuF = "без соли", EnF = "unsalted", RuC = "Испания", EnC = "Spain", Fx = new[] { "SeedHabit" }, RuJ = "Испанские семечки: на пачке сеньор, под скамейкой гора шелухи. В школьном рюкзаке такое не доживало до обеда. Олень от такого отказался бы. Олень не голодал.", EnJ = "Spanish seeds: a señor on the pack, a hill of shells under the bench. In a school bag this never lasted till lunch. A deer would turn it down. A deer has never starved.", Rare = false },
        new Def { Id = "FakundoTijuana", Kind = Kind.Snack, Shape = "bag", Mesh = "Fakundo", Texture = "FakundoTijuana", Kg = 0.168f, Kcal = 930f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Факундо»", En = "Fakundo seeds", RuF = "тихуана, острые", EnF = "tijuana spicy", RuC = "Испания", EnC = "Spain", Fx = new[] { "SeedHabit", "PepperBlood", "Sweat" }, RuJ = "Испанские семечки: на пачке сеньор, под скамейкой гора шелухи. Его обменяли бы на патрон, будь тут с кем меняться. Соль есть, жир есть, совести нет.", EnJ = "Spanish seeds: a señor on the pack, a hill of shells under the bench. You could trade it for a cartridge, if there were anyone to trade with. Salt: yes. Fat: yes. Conscience: none.", Rare = false },
        new Def { Id = "FakundoBarbacoa", Kind = Kind.Snack, Shape = "bag", Mesh = "Fakundo", Texture = "FakundoBarbacoa", Kg = 0.168f, Kcal = 930f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Факундо»", En = "Fakundo seeds", RuF = "барбекю", EnF = "barbecue", RuC = "Испания", EnC = "Spain", Fx = new[] { "SeedHabit" }, RuJ = "Испанские семечки: на пачке сеньор, под скамейкой гора шелухи. На вокзале это стоило втрое дороже. Теперь даром. Ешьте до темноты: в темноте крошки не найти.", EnJ = "Spanish seeds: a señor on the pack, a hill of shells under the bench. At the station it cost three times as much. Now it is free. Eat before dark: you cannot find crumbs in the dark.", Rare = false },
        new Def { Id = "FakundoCalabaza", Kind = Kind.Snack, Shape = "bag", Mesh = "Fakundo", Texture = "FakundoCalabaza", Kg = 0.168f, Kcal = 930f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Факундо»", En = "Fakundo seeds", RuF = "тыквенные", EnF = "pumpkin seeds", RuC = "Испания", EnC = "Spain", Fx = new[] { "SeedHabit" }, RuJ = "Испанские семечки: на пачке сеньор, под скамейкой гора шелухи. Пережило толчок и даже не помялось. Лучшее, что случится с вами сегодня.", EnJ = "Spanish seeds: a señor on the pack, a hill of shells under the bench. It came through the quake without a dent. The best thing that will happen to you today.", Rare = false },
        new Def { Id = "FakundoQueso", Kind = Kind.Snack, Shape = "bag", Mesh = "Fakundo", Texture = "FakundoQueso", Kg = 0.168f, Kcal = 930f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Факундо»", En = "Fakundo seeds", RuF = "сыр", EnF = "cheese", RuC = "Испания", EnC = "Spain", Fx = new[] { "SeedHabit" }, RuJ = "Испанские семечки: на пачке сеньор, под скамейкой гора шелухи. Китобои такого не ели, но оценили бы. Для полного счастья не хватает только дивана.", EnJ = "Spanish seeds: a señor on the pack, a hill of shells under the bench. The whalers never ate this, but they would have approved. All that is missing for perfect happiness is a sofa.", Rare = false },
        new Def { Id = "FakundoGigantes", Kind = Kind.Snack, Shape = "bag", Mesh = "Fakundo", Texture = "FakundoGigantes", Kg = 0.168f, Kcal = 930f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Факундо»", En = "Fakundo seeds", RuF = "гигантские", EnF = "giant seeds", RuC = "Испания", EnC = "Spain", Fx = new[] { "SeedHabit" }, RuJ = "Испанские семечки: на пачке сеньор, под скамейкой гора шелухи. Осталось после чьего-то дня рождения. Гости не пришли. Вкус детства, если детство было так себе.", EnJ = "Spanish seeds: a señor on the pack, a hill of shells under the bench. Left over from someone's birthday. The guests never came. The taste of childhood, if childhood was so-so.", Rare = false },
        new Def { Id = "FakundoKikos", Kind = Kind.Snack, Shape = "bag", Mesh = "Fakundo", Texture = "FakundoKikos", Kg = 0.168f, Kcal = 930f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Факундо»", En = "Fakundo seeds", RuF = "жареная кукуруза", EnF = "toasted corn", RuC = "Испания", EnC = "Spain", Fx = new[] { "SeedHabit" }, RuJ = "Испанские семечки: на пачке сеньор, под скамейкой гора шелухи. Мерзлота хранит лучше любого холодильника. Шуршит как надежда.", EnJ = "Spanish seeds: a señor on the pack, a hill of shells under the bench. Permafrost keeps things better than any fridge. It rustles like hope.", Rare = false },
        new Def { Id = "HaldiramzBhujia", Kind = Kind.Snack, Shape = "bag", Mesh = "Haldiramz", Texture = "HaldiramzBhujia", Kg = 0.208f, Kcal = 1100f, Thirst = -8f, Eat = 5f, Ru = "Намкин «Халдирамз»", En = "Haldiramz namkeen", RuF = "алу бхуджия", EnF = "aloo bhujia", RuC = "Индия", EnC = "India", Fx = new[] { "Sinew" }, RuJ = "Индийский намкин: в одной горсти больше специй, чем во всей моей кухне. Такое добывали из автомата, который съедал последнюю монету. Голод отступит, жажда придёт. Честный обмен.", EnJ = "Indian namkeen: more spice in one handful than in my whole kitchen. These came from the vending machine that ate your last coin. Hunger leaves, thirst arrives. A fair trade.", Rare = false },
        new Def { Id = "HaldiramzMoong", Kind = Kind.Snack, Shape = "bag", Mesh = "Haldiramz", Texture = "HaldiramzMoong", Kg = 0.208f, Kcal = 1100f, Thirst = -8f, Eat = 5f, Ru = "Намкин «Халдирамз»", En = "Haldiramz namkeen", RuF = "мунг дал", EnF = "moong dal", RuC = "Индия", EnC = "India", Fx = new[] { "Sinew" }, RuJ = "Индийский намкин: в одной горсти больше специй, чем во всей моей кухне. Такое брали в лодку под брезент, на весь день. Не согреет, зато отвлечёт.", EnJ = "Indian namkeen: more spice in one handful than in my whole kitchen. People took these out in the boat under the tarpaulin, for the whole day. It will not warm you, but it will distract you.", Rare = false },
        new Def { Id = "HaldiramzKhatta", Kind = Kind.Snack, Shape = "bag", Mesh = "Haldiramz", Texture = "HaldiramzKhatta", Kg = 0.208f, Kcal = 1100f, Thirst = -8f, Eat = 5f, Ru = "Намкин «Халдирамз»", En = "Haldiramz namkeen", RuF = "кхатта митха", EnF = "khatta meetha", RuC = "Индия", EnC = "India", Fx = new[] { "Sinew" }, RuJ = "Индийский намкин: в одной горсти больше специй, чем во всей моей кухне. С ним кто-то шёл к перевалу и не дошёл. Пума предпочитает мясо. Вам повезло.", EnJ = "Indian namkeen: more spice in one handful than in my whole kitchen. Someone carried it towards the pass and never arrived. The cougar prefers meat. Lucky you.", Rare = false },
        new Def { Id = "HaldiramzNavratan", Kind = Kind.Snack, Shape = "bag", Mesh = "Haldiramz", Texture = "HaldiramzNavratan", Kg = 0.208f, Kcal = 1100f, Thirst = -8f, Eat = 5f, Ru = "Намкин «Халдирамз»", En = "Haldiramz namkeen", RuF = "навратан", EnF = "navratan mix", RuC = "Индия", EnC = "India", Fx = new[] { "Sinew" }, RuJ = "Индийский намкин: в одной горсти больше специй, чем во всей моей кухне. С таким сидели у окна с видом на метель. Сначала попробуйте одну штучку. Шутка: ешьте всё.", EnJ = "Indian namkeen: more spice in one handful than in my whole kitchen. People sat with these at a window with a view of the blizzard. Try just one first. Joke: eat the lot.", Rare = false },
        new Def { Id = "HaldiramzDiwali", Kind = Kind.Snack, Shape = "bag", Mesh = "Haldiramz", Texture = "HaldiramzDiwali", Kg = 0.208f, Kcal = 1100f, Thirst = -8f, Eat = 5f, Ru = "Намкин «Халдирамз»", En = "Haldiramz namkeen", RuF = "праздничная смесь к Дивали", EnF = "diwali festive mix", RuC = "Индия", EnC = "India", Fx = new[] { "Sinew" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Уцелело там, где сгорело всё остальное. Такой ужин не стыдно записать в дневник.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. It survived where everything else burned. A dinner worth writing in the journal.", Rare = true },
        new Def { Id = "HaldiramzHoli", Kind = Kind.Snack, Shape = "bag", Mesh = "Haldiramz", Texture = "HaldiramzHoli", Kg = 0.208f, Kcal = 1100f, Thirst = -8f, Eat = 5f, Ru = "Намкин «Халдирамз»", En = "Haldiramz namkeen", RuF = "сладкая смесь к Холи", EnF = "holi sweet mix", RuC = "Индия", EnC = "India", Fx = new[] { "Sinew" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Этим кормили сторожевого пса. Пёс ушёл в волки. Силы прибавит на один сугроб.", EnJ = "A spring edition: a rare pack from the days when spring still came. They fed the guard dog with this. The dog joined the wolves. It will carry you one snowdrift further.", Rare = true },
        new Def { Id = "HaldiramzSev", Kind = Kind.Snack, Shape = "bag", Mesh = "Haldiramz", Texture = "HaldiramzSev", Kg = 0.208f, Kcal = 1100f, Thirst = -8f, Eat = 5f, Ru = "Намкин «Халдирамз»", En = "Haldiramz namkeen", RuF = "нутовая лапша сев", EnF = "gram flour sev", RuC = "Индия", EnC = "India", Fx = new[] { "Sinew" }, RuJ = "Индийский намкин: в одной горсти больше специй, чем во всей моей кухне. Из запасов лесорубов: брали ящиками. Идеально к закату, которого не видно за бураном.", EnJ = "Indian namkeen: more spice in one handful than in my whole kitchen. From the loggers' stores: they bought it by the crate. Perfect with a sunset you cannot see for the storm.", Rare = false },
        new Def { Id = "HaldiramzPeanut", Kind = Kind.Snack, Shape = "bag", Mesh = "Haldiramz", Texture = "HaldiramzPeanut", Kg = 0.208f, Kcal = 1100f, Thirst = -8f, Eat = 5f, Ru = "Намкин «Халдирамз»", En = "Haldiramz namkeen", RuF = "арахис в специях", EnF = "spiced peanuts", RuC = "Индия", EnC = "India", Fx = new[] { "Sinew" }, RuJ = "Индийский намкин: в одной горсти больше специй, чем во всей моей кухне. В пост такое не ели. Пост кончился вместе с миром. Пахнет магазином. Помните магазины?", EnJ = "Indian namkeen: more spice in one handful than in my whole kitchen. Nobody ate these during a fast. The fast ended with the world. It smells of a shop. Remember shops?", Rare = false },
        new Def { Id = "HaldiramzChana", Kind = Kind.Snack, Shape = "bag", Mesh = "Haldiramz", Texture = "HaldiramzChana", Kg = 0.208f, Kcal = 1100f, Thirst = -8f, Eat = 5f, Ru = "Намкин «Халдирамз»", En = "Haldiramz namkeen", RuF = "жареный нут", EnF = "roasted chickpeas", RuC = "Индия", EnC = "India", Fx = new[] { "Sinew" }, RuJ = "Индийский намкин: в одной горсти больше специй, чем во всей моей кухне. Теперь это ценнее денег. Деньги оставьте. Мороз не испортил, время не взяло.", EnJ = "Indian namkeen: more spice in one handful than in my whole kitchen. It is worth more than money now. Leave the money. Frost did not spoil it and time could not take it.", Rare = false },
        new Def { Id = "HaldiramzMixture", Kind = Kind.Snack, Shape = "bag", Mesh = "Haldiramz", Texture = "HaldiramzMixture", Kg = 0.208f, Kcal = 1100f, Thirst = -8f, Eat = 5f, Ru = "Намкин «Халдирамз»", En = "Haldiramz namkeen", RuF = "острая смесь", EnF = "hot mixture", RuC = "Индия", EnC = "India", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Индийский намкин: в одной горсти больше специй, чем во всей моей кухне. Его несли на пикник. Пикник отменили навсегда. В рюкзаке не мнётся. Почти.", EnJ = "Indian namkeen: more spice in one handful than in my whole kitchen. It was headed for a picnic. The picnic is cancelled forever. It does not get crushed in a pack. Almost.", Rare = false },
        new Def { Id = "HaldiramzCornflake", Kind = Kind.Snack, Shape = "bag", Mesh = "Haldiramz", Texture = "HaldiramzCornflake", Kg = 0.208f, Kcal = 1100f, Thirst = -8f, Eat = 5f, Ru = "Намкин «Халдирамз»", En = "Haldiramz namkeen", RuF = "кукурузная смесь", EnF = "cornflake mix", RuC = "Индия", EnC = "India", Fx = new[] { "Sinew" }, RuJ = "Индийский намкин: в одной горсти больше специй, чем во всей моей кухне. Такое стояло у кассы на случай слабости. Съешьте сейчас: завтра может не быть аппетита.", EnJ = "Indian namkeen: more spice in one handful than in my whole kitchen. These stood by the till for moments of weakness. Eat it now: tomorrow you may have no appetite.", Rare = false },
        new Def { Id = "HaldiramzPunjabi", Kind = Kind.Snack, Shape = "bag", Mesh = "Haldiramz", Texture = "HaldiramzPunjabi", Kg = 0.208f, Kcal = 1100f, Thirst = -8f, Eat = 5f, Ru = "Намкин «Халдирамз»", En = "Haldiramz namkeen", RuF = "пенджабская смесь", EnF = "punjabi mix", RuC = "Индия", EnC = "India", Fx = new[] { "Sinew" }, RuJ = "Индийский намкин: в одной горсти больше специй, чем во всей моей кухне. Досталось вам, потому что вы дошли первым. Хватит дойти до следующей хижины и пожалеть, что кончилось.", EnJ = "Indian namkeen: more spice in one handful than in my whole kitchen. It is yours because you got here first. Enough to reach the next cabin and regret it is gone.", Rare = false },
        new Def { Id = "KurkurzMasala", Kind = Kind.Snack, Shape = "bag", Mesh = "Kurkurz", Texture = "KurkurzMasala", Kg = 0.098f, Kcal = 500f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Куркурз»", En = "Kurkurz corn puffs", RuF = "масала", EnF = "masala munch", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Кривые индийские палочки: хрустят громче, чем болливудский финал. Упаковка выцвела, внутри время остановилось. От такого не толстеют те, кто ходит по двадцать километров.", EnJ = "Crooked Indian sticks: louder than a Bollywood finale. The wrapper has faded; inside, time stood still. Nobody who walks twenty kilometres a day gets fat on this.", Rare = false },
        new Def { Id = "KurkurzChutney", Kind = Kind.Snack, Shape = "bag", Mesh = "Kurkurz", Texture = "KurkurzChutney", Kg = 0.098f, Kcal = 500f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Куркурз»", En = "Kurkurz corn puffs", RuF = "зелёный чатни", EnF = "green chutney", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold" }, RuJ = "Кривые индийские палочки: хрустят громче, чем болливудский финал. Из чемодана пассажира, который не долетел. Волчья стая не в курсе. Пусть так и будет.", EnJ = "Crooked Indian sticks: louder than a Bollywood finale. From the suitcase of a passenger who never landed. The wolf pack does not know. Keep it that way.", Rare = false },
        new Def { Id = "KurkurzChilli", Kind = Kind.Snack, Shape = "bag", Mesh = "Kurkurz", Texture = "KurkurzChilli", Kg = 0.098f, Kcal = 500f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Куркурз»", En = "Kurkurz corn puffs", RuF = "чили", EnF = "chilli chatka", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Кривые индийские палочки: хрустят громче, чем болливудский финал. Перезимовало и ничуть не обиделось. Хрустеть в засаде не рекомендуется.", EnJ = "Crooked Indian sticks: louder than a Bollywood finale. It made it through the winter and bears no grudge. Crunching in an ambush is not recommended.", Rare = false },
        new Def { Id = "KurkurzHoli", Kind = Kind.Snack, Shape = "bag", Mesh = "Kurkurz", Texture = "KurkurzHoli", Kg = 0.098f, Kcal = 500f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Куркурз»", En = "Kurkurz corn puffs", RuF = "масала к Холи", EnF = "holi masala", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Запасливая хозяйка купила по акции шесть штук. Лекарство от тоски, отпускается без рецепта.", EnJ = "A spring edition: a rare pack from the days when spring still came. A thrifty housewife bought six of these on offer. A cure for the blues, no prescription needed.", Rare = true },
        new Def { Id = "KurkurzDiwali", Kind = Kind.Snack, Shape = "bag", Mesh = "Kurkurz", Texture = "KurkurzDiwali", Kg = 0.098f, Kcal = 500f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Куркурз»", En = "Kurkurz corn puffs", RuF = "к Дивали", EnF = "diwali", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Кто-то написал на упаковке «моё». Уже нет. Жуйте и думайте о хорошем. Например, о добавке.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. Someone wrote 'mine' on it. Not any more. Chew and think of nice things. Seconds, for example.", Rare = true },
        new Def { Id = "KurkurzTomato", Kind = Kind.Snack, Shape = "bag", Mesh = "Kurkurz", Texture = "KurkurzTomato", Kg = 0.098f, Kcal = 500f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Куркурз»", En = "Kurkurz corn puffs", RuF = "томат", EnF = "tomato", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold" }, RuJ = "Кривые индийские палочки: хрустят громче, чем болливудский финал. В консервном цеху это ели тайком от мастера. К утру от него останется только запах на варежках.", EnJ = "Crooked Indian sticks: louder than a Bollywood finale. At the cannery they ate this behind the foreman's back. By morning only the smell on your mittens will be left.", Rare = false },
        new Def { Id = "KurkurzCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Kurkurz", Texture = "KurkurzCheese", Kg = 0.098f, Kcal = 500f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Куркурз»", En = "Kurkurz corn puffs", RuF = "сыр", EnF = "cheese", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold" }, RuJ = "Кривые индийские палочки: хрустят громче, чем болливудский финал. Его не взяли даже мародёры. Они спешили. Тишина вокруг такая, что слышно, как вы жуёте.", EnJ = "Crooked Indian sticks: louder than a Bollywood finale. Even the looters left it. They were in a hurry. It is so quiet you can hear yourself chew.", Rare = false },
        new Def { Id = "KurkurzNaughty", Kind = Kind.Snack, Shape = "bag", Mesh = "Kurkurz", Texture = "KurkurzNaughty", Kg = 0.098f, Kcal = 500f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Куркурз»", En = "Kurkurz corn puffs", RuF = "озорной томат", EnF = "naughty tomato", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold" }, RuJ = "Кривые индийские палочки: хрустят громче, чем болливудский финал. Провело зиму на острове, как и вы. Не делите на завтра: завтра будет новый голод.", EnJ = "Crooked Indian sticks: louder than a Bollywood finale. It spent the winter on the island, same as you. Do not save half for tomorrow: tomorrow brings its own hunger.", Rare = false },
        new Def { Id = "KurkurzSchezwan", Kind = Kind.Snack, Shape = "bag", Mesh = "Kurkurz", Texture = "KurkurzSchezwan", Kg = 0.098f, Kcal = 500f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Куркурз»", En = "Kurkurz corn puffs", RuF = "сычуаньский соус", EnF = "schezwan sauce", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Кривые индийские палочки: хрустят громче, чем болливудский финал. Дети прятали такое под кроватью, в тайнике. Сосны вокруг делают вид, что не смотрят.", EnJ = "Crooked Indian sticks: louder than a Bollywood finale. Children hid these under the bed, in a secret place. The pines around pretend not to watch.", Rare = false },
        new Def { Id = "KurkurzPuffcorn", Kind = Kind.Snack, Shape = "bag", Mesh = "Kurkurz", Texture = "KurkurzPuffcorn", Kg = 0.098f, Kcal = 500f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Куркурз»", En = "Kurkurz corn puffs", RuF = "йогурт и мята", EnF = "yoghurt & mint", RuC = "Индия", EnC = "India", Fx = new[] { "SugarDry" }, RuJ = "Кривые индийские палочки: хрустят громче, чем болливудский финал. Осталось от геологов вместе с картой и долгами. Калории мелкие, зато свои.", EnJ = "Crooked Indian sticks: louder than a Bollywood finale. Left by the geologists along with a map and some debts. Small calories, but your own.", Rare = false },
        new Def { Id = "TaoKeNoyClassic", Kind = Kind.Snack, Shape = "bag", Mesh = "TaoKeNoy", Texture = "TaoKeNoyClassic", Kg = 0.04f, Kcal = 110f, Thirst = -8f, Eat = 3f, Ru = "Хрустящие водоросли «Тао Кэ Ной»", En = "Tao Ke Noy crispy seaweed", RuF = "классические", EnF = "classic", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "SaltHold" }, RuJ = "Хрустящие водоросли: парень на пачке разбогател на них раньше, чем закончил школу. На острове такое было праздником и до катастрофы. После этого даже крапивный чай покажется десертом.", EnJ = "Crispy seaweed: the lad on the pack got rich on it before finishing school. On the island this was a treat even before the disaster. After this even nettle tea feels like dessert.", Rare = false },
        new Def { Id = "TaoKeNoySpicy", Kind = Kind.Snack, Shape = "bag", Mesh = "TaoKeNoy", Texture = "TaoKeNoySpicy", Kg = 0.04f, Kcal = 110f, Thirst = -8f, Eat = 3f, Ru = "Хрустящие водоросли «Тао Кэ Ной»", En = "Tao Ke Noy crispy seaweed", RuF = "острые", EnF = "hot & spicy", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Хрустящие водоросли: парень на пачке разбогател на них раньше, чем закончил школу. С таким слушали радио, которое теперь ловит только треск. Нашедшему полагается всё.", EnJ = "Crispy seaweed: the lad on the pack got rich on it before finishing school. People ate these by the radio, which picks up nothing but crackle now. Finders keepers, all of it.", Rare = false },
        new Def { Id = "TaoKeNoyTomyum", Kind = Kind.Snack, Shape = "bag", Mesh = "TaoKeNoy", Texture = "TaoKeNoyTomyum", Kg = 0.04f, Kcal = 110f, Thirst = -8f, Eat = 3f, Ru = "Хрустящие водоросли «Тао Кэ Ной»", En = "Tao Ke Noy crispy seaweed", RuF = "том-ям", EnF = "tom yum", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "SaltHold" }, RuJ = "Хрустящие водоросли: парень на пачке разбогател на них раньше, чем закончил школу. Крысы прогрызли соседнюю, эту пощадили. Зубы целы? Тогда вперёд.", EnJ = "Crispy seaweed: the lad on the pack got rich on it before finishing school. The rats gnawed through the one next to it and spared this. Teeth intact? Then go ahead.", Rare = false },
        new Def { Id = "TaoKeNoyMango", Kind = Kind.Snack, Shape = "bag", Mesh = "TaoKeNoy", Texture = "TaoKeNoyMango", Kg = 0.04f, Kcal = 110f, Thirst = -8f, Eat = 3f, Ru = "Хрустящие водоросли «Тао Кэ Ной»", En = "Tao Ke Noy crispy seaweed", RuF = "манго к Сонгкрану", EnF = "songkran mango", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "SugarDry" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Бывший хозяин клялся бросить. Не успел. Ночью приснится добавка.", EnJ = "A spring edition: a rare pack from the days when spring still came. The former owner swore to give these up. He ran out of time. Tonight you will dream of seconds.", Rare = true },
        new Def { Id = "TaoKeNoySongkran", Kind = Kind.Snack, Shape = "bag", Mesh = "TaoKeNoy", Texture = "TaoKeNoySongkran", Kg = 0.04f, Kcal = 110f, Thirst = -8f, Eat = 3f, Ru = "Хрустящие водоросли «Тао Кэ Ной»", En = "Tao Ke Noy crispy seaweed", RuF = "к Сонгкрану", EnF = "songkran", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "SaltHold" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Его катали в кабине трактора три сезона. С таким запасом можно пережить ещё один вечер.", EnJ = "A spring edition: a rare pack from the days when spring still came. It rode around in a tractor cab for three seasons. With supplies like this you can survive one more evening.", Rare = true },
        new Def { Id = "TaoKeNoyWasabi", Kind = Kind.Snack, Shape = "bag", Mesh = "TaoKeNoy", Texture = "TaoKeNoyWasabi", Kg = 0.04f, Kcal = 110f, Thirst = -8f, Eat = 3f, Ru = "Хрустящие водоросли «Тао Кэ Ной»", En = "Tao Ke Noy crispy seaweed", RuF = "васаби", EnF = "wasabi", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Хрустящие водоросли: парень на пачке разбогател на них раньше, чем закончил школу. После бани такое шло лучше всего. Пёс бы выпросил половину. Пса нет.", EnJ = "Crispy seaweed: the lad on the pack got rich on it before finishing school. Nothing went down better after the sauna. A dog would beg half of it. There is no dog.", Rare = false },
        new Def { Id = "TaoKeNoySquid", Kind = Kind.Snack, Shape = "bag", Mesh = "TaoKeNoy", Texture = "TaoKeNoySquid", Kg = 0.04f, Kcal = 110f, Thirst = -8f, Eat = 3f, Ru = "Хрустящие водоросли «Тао Кэ Ной»", En = "Tao Ke Noy crispy seaweed", RuF = "кальмар", EnF = "squid", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "SaltHold" }, RuJ = "Хрустящие водоросли: парень на пачке разбогател на них раньше, чем закончил школу. В тюрьме на это выменивали что угодно. Съедено будет быстрее, чем найдено.", EnJ = "Crispy seaweed: the lad on the pack got rich on it before finishing school. In the prison you could trade one of these for anything. It will be eaten faster than it was found.", Rare = false },
        new Def { Id = "TaoKeNoySauce", Kind = Kind.Snack, Shape = "bag", Mesh = "TaoKeNoy", Texture = "TaoKeNoySauce", Kg = 0.04f, Kcal = 110f, Thirst = -8f, Eat = 3f, Ru = "Хрустящие водоросли «Тао Кэ Ной»", En = "Tao Ke Noy crispy seaweed", RuF = "соус чили", EnF = "chilli sauce", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Хрустящие водоросли: парень на пачке разбогател на них раньше, чем закончил школу. Кто-то менял это на сигареты. Сделка сорвалась. На вкус как выходной.", EnJ = "Crispy seaweed: the lad on the pack got rich on it before finishing school. Someone was trading this for cigarettes. The deal fell through. It tastes like a day off.", Rare = false },
        new Def { Id = "TaoKeNoyKimchi", Kind = Kind.Snack, Shape = "bag", Mesh = "TaoKeNoy", Texture = "TaoKeNoyKimchi", Kg = 0.04f, Kcal = 110f, Thirst = -8f, Eat = 3f, Ru = "Хрустящие водоросли «Тао Кэ Ной»", En = "Tao Ke Noy crispy seaweed", RuF = "кимчи", EnF = "kimchi", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Хрустящие водоросли: парень на пачке разбогател на них раньше, чем закончил школу. С ним зимовали на метеостанции, пока было с кем. Ветер унесёт запах прямо к берлоге. Ешьте быстрее.", EnJ = "Crispy seaweed: the lad on the pack got rich on it before finishing school. They wintered with it at the weather station, while there was a 'they'. The wind carries the smell straight to the den. Eat faster.", Rare = false },
        new Def { Id = "TaoKeNoyCoconut", Kind = Kind.Snack, Shape = "bag", Mesh = "TaoKeNoy", Texture = "TaoKeNoyCoconut", Kg = 0.04f, Kcal = 110f, Thirst = -8f, Eat = 3f, Ru = "Хрустящие водоросли «Тао Кэ Ной»", En = "Tao Ke Noy crispy seaweed", RuF = "кокос", EnF = "coconut", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "SugarDry" }, RuJ = "Хрустящие водоросли: парень на пачке разбогател на них раньше, чем закончил школу. Такое терялось в кладовке среди крупы и надежд. Больше таких не делают. Совсем.", EnJ = "Crispy seaweed: the lad on the pack got rich on it before finishing school. These got lost in the pantry among the grain and the hopes. They do not make these any more. At all.", Rare = false },
        new Def { Id = "TaoKeNoyTempura", Kind = Kind.Snack, Shape = "bag", Mesh = "TaoKeNoy", Texture = "TaoKeNoyTempura", Kg = 0.04f, Kcal = 110f, Thirst = -8f, Eat = 3f, Ru = "Хрустящие водоросли «Тао Кэ Ной»", En = "Tao Ke Noy crispy seaweed", RuF = "темпура", EnF = "tempura", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "SaltHold" }, RuJ = "Хрустящие водоросли: парень на пачке разбогател на них раньше, чем закончил школу. Его берегли к приезду внуков. Хорошо идёт под треск поленьев.", EnJ = "Crispy seaweed: the lad on the pack got rich on it before finishing school. It was being saved for the grandchildren's visit. Goes down well with crackling logs.", Rare = false },
        new Def { Id = "TwistizCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Twistiz", Texture = "TwistizCheese", Kg = 0.098f, Kcal = 500f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Твистиз»", En = "Twistiz corn puffs", RuF = "сыр", EnF = "cheese", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Австралийские сырные завитки: жизнь там и так перевёрнута, снеки тоже кривые. В баре такое ставили на стойку, бесплатно к пиву. Пива нет. Руки вытирать о штаны: салфеток не завезли.", EnJ = "Australian cheese twists: life is upside down there anyway, and so are the snacks. Bars put these out free with a beer. There is no beer. Wipe your hands on your trousers: no napkins were delivered.", Rare = false },
