        new Def { Id = "TwistizChilli", Kind = Kind.Snack, Shape = "bag", Mesh = "Twistiz", Texture = "TwistizChilli", Kg = 0.098f, Kcal = 500f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Твистиз»", En = "Twistiz corn puffs", RuF = "чили", EnF = "chilli", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Австралийские сырные завитки: жизнь там и так перевёрнута, снеки тоже кривые. Кто-то берёг это на чёрный день. Он настал. Совесть молчит, живот поёт.", EnJ = "Australian cheese twists: life is upside down there anyway, and so are the snacks. Someone saved this for a rainy day. It came. Conscience is silent, the belly sings.", Rare = false },
        new Def { Id = "TwistizXmas", Kind = Kind.Snack, Shape = "bag", Mesh = "Twistiz", Texture = "TwistizXmas", Kg = 0.098f, Kcal = 500f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Твистиз»", En = "Twistiz corn puffs", RuF = "рождественские звёзды", EnF = "christmas stars", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Пережило хозяина, кота и две зимы. Проверено поколениями и одной катастрофой.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. It outlived its owner, the cat and two winters. Tested by generations and one catastrophe.", Rare = true },
        new Def { Id = "TwistizBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Twistiz", Texture = "TwistizBBQ", Kg = 0.098f, Kcal = 500f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Твистиз»", En = "Twistiz corn puffs", RuF = "барбекю", EnF = "barbecue", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Австралийские сырные завитки: жизнь там и так перевёрнута, снеки тоже кривые. Такое обычно находили за диваном, как всё лучшее в жизни. Оставьте пару штук на перевал. Не оставите.", EnJ = "Australian cheese twists: life is upside down there anyway, and so are the snacks. These were usually found behind the sofa, like all the best things in life. Save a couple for the pass. You will not.", Rare = false },
        new Def { Id = "TwistizBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Twistiz", Texture = "TwistizBacon", Kg = 0.098f, Kcal = 500f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Твистиз»", En = "Twistiz corn puffs", RuF = "сыр и бекон", EnF = "cheese & bacon", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Австралийские сырные завитки: жизнь там и так перевёрнута, снеки тоже кривые. Последний завоз был до того, как упали самолёты. Здесь это считается ужином при свечах.", EnJ = "Australian cheese twists: life is upside down there anyway, and so are the snacks. The last delivery came before the planes fell. Round here this counts as a candlelit dinner.", Rare = false },
        new Def { Id = "TwistizPizza", Kind = Kind.Snack, Shape = "bag", Mesh = "Twistiz", Texture = "TwistizPizza", Kg = 0.098f, Kcal = 500f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Твистиз»", En = "Twistiz corn puffs", RuF = "пицца", EnF = "pizza", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Австралийские сырные завитки: жизнь там и так перевёрнута, снеки тоже кривые. Ценник оторван: теперь это бесценно. Луна светит, еда хрустит, жизнь налаживается.", EnJ = "Australian cheese twists: life is upside down there anyway, and so are the snacks. The price tag is torn off: it is priceless now. The moon shines, the food crunches, life is looking up.", Rare = false },
        new Def { Id = "TwistizTomato", Kind = Kind.Snack, Shape = "bag", Mesh = "Twistiz", Texture = "TwistizTomato", Kg = 0.098f, Kcal = 500f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Твистиз»", En = "Twistiz corn puffs", RuF = "томатный соус", EnF = "tomato sauce", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Австралийские сырные завитки: жизнь там и так перевёрнута, снеки тоже кривые. Дата на шве стёрлась, и слава богу. Снег вокруг не солёный. Это солёное.", EnJ = "Australian cheese twists: life is upside down there anyway, and so are the snacks. The date on the seam has rubbed off, thank goodness. The snow around is not salty. This is.", Rare = false },
        new Def { Id = "TwistizWicked", Kind = Kind.Snack, Shape = "bag", Mesh = "Twistiz", Texture = "TwistizWicked", Kg = 0.098f, Kcal = 500f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Твистиз»", En = "Twistiz corn puffs", RuF = "жгучий сыр", EnF = "fiery cheese", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Австралийские сырные завитки: жизнь там и так перевёрнута, снеки тоже кривые. Пахнет заправкой у Прибрежного шоссе. Больше таких не делают. Совсем.", EnJ = "Australian cheese twists: life is upside down there anyway, and so are the snacks. It smells of the petrol station on the Coastal Highway. They do not make these any more. At all.", Rare = false },
        new Def { Id = "SanChipsOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "SanChips", Texture = "SanChipsOriginal", Kg = 0.192f, Kcal = 980f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Чипс»", En = "SanChips crisps", RuF = "оригинальные", EnF = "original", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Волнистые чипсы из цельного зерна: почти полезно, если не читать состав. Такое возили в бардачке на дальнюю дорогу. Дороги кончились. Открывайте тихо: у волков отличный слух.", EnJ = "Wavy whole-grain crisps: almost healthy if you don't read the label. People kept these in the glovebox for long drives. The drives are over. Open it quietly: wolves have excellent hearing.", Rare = false },
        new Def { Id = "SanChipsCheddar", Kind = Kind.Snack, Shape = "bag", Mesh = "SanChips", Texture = "SanChipsCheddar", Kg = 0.192f, Kcal = 980f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Чипс»", En = "SanChips crisps", RuF = "чеддер", EnF = "harvest cheddar", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Волнистые чипсы из цельного зерна: почти полезно, если не читать состав. Мыши не тронули. Думайте сами. Одной не обойдётся, но вторая неизвестно где.", EnJ = "Wavy whole-grain crisps: almost healthy if you don't read the label. The mice left it alone. Draw your own conclusions. One won't be enough, and nobody knows where the second is.", Rare = false },
        new Def { Id = "SanChipsSalsa", Kind = Kind.Snack, Shape = "bag", Mesh = "SanChips", Texture = "SanChipsSalsa", Kg = 0.192f, Kcal = 980f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Чипс»", En = "SanChips crisps", RuF = "садовая сальса", EnF = "garden salsa", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Волнистые чипсы из цельного зерна: почти полезно, если не читать состав. Рыбаки брали такое на лёд вместо обеда. Крошки с пола тоже считаются.", EnJ = "Wavy whole-grain crisps: almost healthy if you don't read the label. Fishermen took this onto the ice instead of lunch. The crumbs on the floor count too.", Rare = false },
        new Def { Id = "SanChipsOnion", Kind = Kind.Snack, Shape = "bag", Mesh = "SanChips", Texture = "SanChipsOnion", Kg = 0.192f, Kcal = 980f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Чипс»", En = "SanChips crisps", RuF = "французский лук", EnF = "french onion", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Волнистые чипсы из цельного зерна: почти полезно, если не читать состав. Смотритель плотины держал такое в заначке. Запейте чаем из шиповника и считайте это обедом.", EnJ = "Wavy whole-grain crisps: almost healthy if you don't read the label. The dam keeper kept a stash of these. Wash it down with rosehip tea and call it lunch.", Rare = false },
        new Def { Id = "SanChipsJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "SanChips", Texture = "SanChipsJalapeno", Kg = 0.192f, Kcal = 980f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Чипс»", En = "SanChips crisps", RuF = "халапеньо", EnF = "jalapeno jack", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Волнистые чипсы из цельного зерна: почти полезно, если не читать состав. Кто-то спрятал это от детей. Дети не нашли. Медведю не показывать: отнимет вместе с рукой.", EnJ = "Wavy whole-grain crisps: almost healthy if you don't read the label. Someone hid it from the kids. The kids never found it. Do not show the bear: he will take it, hand and all.", Rare = false },
        new Def { Id = "SanChipsChili", Kind = Kind.Snack, Shape = "bag", Mesh = "SanChips", Texture = "SanChipsChili", Kg = 0.192f, Kcal = 980f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Чипс»", En = "SanChips crisps", RuF = "сладкий чили", EnF = "sweet chilli", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Волнистые чипсы из цельного зерна: почти полезно, если не читать состав. В сельском магазине такое вечно заваливалось за прилавок. Диетолог не одобрил бы. Диетолога тут нет.", EnJ = "Wavy whole-grain crisps: almost healthy if you don't read the label. In the village shop these kept slipping behind the counter. A dietitian would not approve. There is no dietitian here.", Rare = false },
        new Def { Id = "SanChipsBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "SanChips", Texture = "SanChipsBBQ", Kg = 0.192f, Kcal = 980f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Чипс»", En = "SanChips crisps", RuF = "сладкий барбекю", EnF = "sweet barbecue", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Волнистые чипсы из цельного зерна: почти полезно, если не читать состав. Ждало покупателя дольше, чем тот прожил. Лучше, чем кора. Проверено.", EnJ = "Wavy whole-grain crisps: almost healthy if you don't read the label. It waited for a buyer longer than the buyer lived. Better than bark. Tested.", Rare = false },
        new Def { Id = "KetlSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "Ketl", Texture = "KetlSalt", Kg = 0.15f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кетл»", En = "Ketl crisps", RuF = "морская соль", EnF = "sea salt", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из котла: толстые, гнутые, каждый со своим характером. С материка такое больше не привезут. Хруст разносится до соседней долины.", EnJ = "Kettle crisps: thick, bent, each with a character of its own. Nobody will bring this from the mainland again. The crunch carries to the next valley.", Rare = false },
        new Def { Id = "KetlVinegar", Kind = Kind.Snack, Shape = "bag", Mesh = "Ketl", Texture = "KetlVinegar", Kg = 0.15f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кетл»", En = "Ketl crisps", RuF = "соль и уксус", EnF = "sea salt & vinegar", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из котла: толстые, гнутые, каждый со своим характером. На упаковке иней, внутри всё по-прежнему. Ешьте медленно: когда ещё такое найдёте.", EnJ = "Kettle crisps: thick, bent, each with a character of its own. Frost on the wrapper, business as usual inside. Eat slowly: who knows when you will find another.", Rare = false },
        new Def { Id = "KetlDijon", Kind = Kind.Snack, Shape = "bag", Mesh = "Ketl", Texture = "KetlDijon", Kg = 0.15f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кетл»", En = "Ketl crisps", RuF = "мёд и дижонская горчица", EnF = "honey dijon", RuC = "США", EnC = "USA", Fx = new[] { "SugarDry" }, RuJ = "Чипсы из котла: толстые, гнутые, каждый со своим характером. Мороз ему нипочём: твёрже не стало, мягче тоже. Кролик смотрит с осуждением.", EnJ = "Kettle crisps: thick, bent, each with a character of its own. The frost did nothing to it: no harder, no softer. The rabbit looks on with disapproval.", Rare = false },
        new Def { Id = "KetlJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "Ketl", Texture = "KetlJalapeno", Kg = 0.15f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кетл»", En = "Ketl crisps", RuF = "халапеньо", EnF = "jalapeno", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Чипсы из котла: толстые, гнутые, каждый со своим характером. Из тех времён, когда еду выбирали по вкусу. Сияние на вкус не влияет. Наверное.", EnJ = "Kettle crisps: thick, bent, each with a character of its own. From the days when people picked food for its taste. The aurora does not affect the taste. Probably.", Rare = false },
        new Def { Id = "KetlBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Ketl", Texture = "KetlBBQ", Kg = 0.15f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кетл»", En = "Ketl crisps", RuF = "барбекю", EnF = "backyard barbeque", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из котла: толстые, гнутые, каждый со своим характером. Чей-то перекус на ночную смену, которая не кончилась. После тушёнки из банки это почти ресторан.", EnJ = "Kettle crisps: thick, bent, each with a character of its own. Someone's snack for a night shift that never ended. After stew from a tin this is nearly a restaurant.", Rare = false },
        new Def { Id = "KetlPumpkin", Kind = Kind.Snack, Shape = "bag", Mesh = "Ketl", Texture = "KetlPumpkin", Kg = 0.15f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кетл»", En = "Ketl crisps", RuF = "тыква с корицей", EnF = "pumpkin & cinnamon", RuC = "США", EnC = "USA", Fx = new[] { "SugarDry" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. В охотничьей вышке таким встречали рассвет. Делиться не с кем, и это впервые радует.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. In the hunting blind they met the dawn with this. Nobody to share with, and for once that is good news.", Rare = true },
        new Def { Id = "KetlGingerbread", Kind = Kind.Snack, Shape = "bag", Mesh = "Ketl", Texture = "KetlGingerbread", Kg = 0.15f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кетл»", En = "Ketl crisps", RuF = "имбирный пряник", EnF = "gingerbread", RuC = "США", EnC = "USA", Fx = new[] { "SugarDry" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Такое носили в кармане куртки на всякий случай. Случай настал. Пальцы потом оближите: зимой калории не выбрасывают.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. People carried these in a coat pocket just in case. The case has come. Lick your fingers after: in winter you do not waste calories.", Rare = true },
        new Def { Id = "KetlCheddar", Kind = Kind.Snack, Shape = "bag", Mesh = "Ketl", Texture = "KetlCheddar", Kg = 0.15f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кетл»", En = "Ketl crisps", RuF = "нью-йоркский чеддер", EnF = "new york cheddar", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из котла: толстые, гнутые, каждый со своим характером. Прежний хозяин оставил записку: «Не трогать». Записка сгорела. Ворон на ветке уже ждёт свою долю.", EnJ = "Kettle crisps: thick, bent, each with a character of its own. The last owner left a note: 'Do not touch'. The note burned. The crow on the branch is already waiting for its share.", Rare = false },
        new Def { Id = "KetlPepper", Kind = Kind.Snack, Shape = "bag", Mesh = "Ketl", Texture = "KetlPepper", Kg = 0.15f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кетл»", En = "Ketl crisps", RuF = "соль и чёрный перец", EnF = "salt & pepper", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из котла: толстые, гнутые, каждый со своим характером. Такими торговали в поезде, пока поезд ходил. На морозе хрустит вдвое громче.", EnJ = "Kettle crisps: thick, bent, each with a character of its own. They sold these on the train, while the train ran. In the frost it crunches twice as loud.", Rare = false },
        new Def { Id = "KetlUnsalted", Kind = Kind.Snack, Shape = "bag", Mesh = "Ketl", Texture = "KetlUnsalted", Kg = 0.15f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кетл»", En = "Ketl crisps", RuF = "без соли", EnF = "unsalted", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из котла: толстые, гнутые, каждый со своим характером. Сторож шахты держал такое в ящике стола. Не еда, а настроение. Настроение тоже греет.", EnJ = "Kettle crisps: thick, bent, each with a character of its own. The mine watchman kept these in his desk drawer. Not food but a mood. A mood warms you too.", Rare = false },
        new Def { Id = "KetlPepperoncini", Kind = Kind.Snack, Shape = "bag", Mesh = "Ketl", Texture = "KetlPepperoncini", Kg = 0.15f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кетл»", En = "Ketl crisps", RuF = "пеперончини", EnF = "pepperoncini", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из котла: толстые, гнутые, каждый со своим характером. Лавина прошла мимо, срок годности тоже. Сытости на час, воспоминаний на неделю.", EnJ = "Kettle crisps: thick, bent, each with a character of its own. The avalanche missed it, and so did the best-before date. An hour of fullness, a week of memories.", Rare = false },
        new Def { Id = "KetlTruffle", Kind = Kind.Snack, Shape = "bag", Mesh = "Ketl", Texture = "KetlTruffle", Kg = 0.15f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кетл»", En = "Ketl crisps", RuF = "трюфель и соль", EnF = "truffle & sea salt", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из котла: толстые, гнутые, каждый со своим характером. Такое всегда стояло на видном месте, поэтому никто не брал. Кролик смотрит с осуждением.", EnJ = "Kettle crisps: thick, bent, each with a character of its own. These always stood in plain sight, which is why nobody took them. The rabbit looks on with disapproval.", Rare = false },
        new Def { Id = "KetlMaui", Kind = Kind.Snack, Shape = "bag", Mesh = "Ketl", Texture = "KetlMaui", Kg = 0.15f, Kcal = 760f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кетл»", En = "Ketl crisps", RuF = "сладкий лук", EnF = "sweet onion", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из котла: толстые, гнутые, каждый со своим характером. Кто-то открыл, передумал и умер. Не связано. У костра вкуснее. У костра всё вкуснее.", EnJ = "Kettle crisps: thick, bent, each with a character of its own. Someone opened it, changed their mind and died. Unrelated. It tastes better by the fire. Everything does.", Rare = false },
        new Def { Id = "TostitozRestaurant", Kind = Kind.Snack, Shape = "bag", Mesh = "Tostitoz", Texture = "TostitozRestaurant", Kg = 0.291f, Kcal = 1420f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Тоститоз»", En = "Tostitoz tortilla chips", RuF = "ресторанные", EnF = "restaurant style", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Чипсы для сальсы. Сальсы нет, придётся макать в воспоминания. Такое вечно каталось под сиденьем пикапа. Упаковку не выбрасывайте: ею можно разжечь печь.", EnJ = "Chips made for salsa. No salsa, so you'll have to dip them in memories. One of these was always rolling under a pickup seat. Keep the wrapper: it will light the stove.", Rare = false },
        new Def { Id = "TostitozScoops", Kind = Kind.Snack, Shape = "bag", Mesh = "Tostitoz", Texture = "TostitozScoops", Kg = 0.291f, Kcal = 1420f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Тоститоз»", En = "Tostitoz tortilla chips", RuF = "ложечки", EnF = "scoops", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Чипсы для сальсы. Сальсы нет, придётся макать в воспоминания. Привезено паромом, которого больше нет. Если это последняя на острове, вы её достойны.", EnJ = "Chips made for salsa. No salsa, so you'll have to dip them in memories. Brought over by a ferry that no longer exists. If this is the last one on the island, you have earned it.", Rare = false },
        new Def { Id = "TostitozLime", Kind = Kind.Snack, Shape = "bag", Mesh = "Tostitoz", Texture = "TostitozLime", Kg = 0.291f, Kcal = 1420f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Тоститоз»", En = "Tostitoz tortilla chips", RuF = "с лаймом", EnF = "hint of lime", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Чипсы для сальсы. Сальсы нет, придётся макать в воспоминания. Раньше это ели под телевизор. Телевизор молчит. Желудок удивится, но возражать не станет.", EnJ = "Chips made for salsa. No salsa, so you'll have to dip them in memories. People ate this in front of the telly. The telly is silent. Your stomach will be surprised but will not object.", Rare = false },
        new Def { Id = "TostitozGameDay", Kind = Kind.Snack, Shape = "bag", Mesh = "Tostitoz", Texture = "TostitozGameDay", Kg = 0.291f, Kcal = 1420f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Тоститоз»", En = "Tostitoz tortilla chips", RuF = "семь слоёв к большой игре", EnF = "game day seven layer", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Зимняя серия: выпускали на один сезон, а зима тут навсегда. Забыто туристами, которым повезло уехать. Запах выдаёт вас за сто шагов. Оно того стоит.", EnJ = "A winter edition: made for one season, and here winter is forever. Left behind by tourists who were lucky enough to leave. The smell gives you away at a hundred paces. Worth it.", Rare = true },
        new Def { Id = "TostitozRounds", Kind = Kind.Snack, Shape = "bag", Mesh = "Tostitoz", Texture = "TostitozRounds", Kg = 0.291f, Kcal = 1420f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Тоститоз»", En = "Tostitoz tortilla chips", RuF = "кругляши", EnF = "bite size rounds", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Чипсы для сальсы. Сальсы нет, придётся макать в воспоминания. Механики заедали этим обед, не вытирая рук. Раньше это называли вредным. Теперь называют едой.", EnJ = "Chips made for salsa. No salsa, so you'll have to dip them in memories. Mechanics ate these for lunch without wiping their hands. They used to call this unhealthy. Now they call it food.", Rare = false },
        new Def { Id = "TostitozMultigrain", Kind = Kind.Snack, Shape = "bag", Mesh = "Tostitoz", Texture = "TostitozMultigrain", Kg = 0.291f, Kcal = 1420f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Тоститоз»", En = "Tostitoz tortilla chips", RuF = "злаковые", EnF = "multigrain", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Чипсы для сальсы. Сальсы нет, придётся макать в воспоминания. Последнее на всю Одинокую топь. Скорее всего. Спальный мешок потом вытряхните.", EnJ = "Chips made for salsa. No salsa, so you'll have to dip them in memories. The last one in all of Forlorn Muskeg. Most likely. Shake out your sleeping bag afterwards.", Rare = false },
        new Def { Id = "TostitozCantina", Kind = Kind.Snack, Shape = "bag", Mesh = "Tostitoz", Texture = "TostitozCantina", Kg = 0.291f, Kcal = 1420f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Тоститоз»", En = "Tostitoz tortilla chips", RuF = "тонкие хрустящие", EnF = "thin & crispy", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Чипсы для сальсы. Сальсы нет, придётся макать в воспоминания. Смотритель маяка грыз такое, ожидая кораблей. Зимой такое идёт за валюту.", EnJ = "Chips made for salsa. No salsa, so you'll have to dip them in memories. The lighthouse keeper munched these while waiting for ships. In winter this passes for currency.", Rare = false },
        new Def { Id = "TostitozSalsa", Kind = Kind.Snack, Shape = "bag", Mesh = "Tostitoz", Texture = "TostitozSalsa", Kg = 0.291f, Kcal = 1420f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Тоститоз»", En = "Tostitoz tortilla chips", RuF = "сальса верде", EnF = "salsa verde", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Чипсы для сальсы. Сальсы нет, придётся макать в воспоминания. Полки рушились, а это уцелело. Торговец дал бы за это тряпку. Вы дадите больше.", EnJ = "Chips made for salsa. No salsa, so you'll have to dip them in memories. Shelves collapsed and this survived. The trader would give a rag for it. You would give more.", Rare = false },
        new Def { Id = "TostitozBlue", Kind = Kind.Snack, Shape = "bag", Mesh = "Tostitoz", Texture = "TostitozBlue", Kg = 0.291f, Kcal = 1420f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Тоститоз»", En = "Tostitoz tortilla chips", RuF = "синяя кукуруза", EnF = "blue corn", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Чипсы для сальсы. Сальсы нет, придётся макать в воспоминания. Смотритель заповедника называл это ужином. Пока жуёте, метель кажется короче.", EnJ = "Chips made for salsa. No salsa, so you'll have to dip them in memories. The park ranger called this dinner. While you chew, the blizzard seems shorter.", Rare = false },
        new Def { Id = "FanyunzOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanyunz", Texture = "FanyunzOriginal", Kg = 0.171f, Kcal = 820f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Фаньюнз»", En = "Fanyunz onion rings", RuF = "оригинальные", EnF = "original", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Луковые кольца, после которых разговаривать лучше против ветра. Такое слали посылками с материка. Адресаты выбыли. Организм скажет спасибо. Или не скажет.", EnJ = "Onion rings after which you'd better talk downwind. These came in parcels from the mainland. The addressees are gone. Your body will thank you. Or not.", Rare = false },
        new Def { Id = "FanyunzHot", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanyunz", Texture = "FanyunzHot", Kg = 0.171f, Kcal = 820f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Фаньюнз»", En = "Fanyunz onion rings", RuF = "огненные", EnF = "flamin hot", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Луковые кольца, после которых разговаривать лучше против ветра. Иные держали это за лекарство. Тоже лечит. На третьей горсти забываешь, что вокруг конец света.", EnJ = "Onion rings after which you'd better talk downwind. Some people counted this as medicine. Also a cure. By the third handful you forget the world has ended.", Rare = false },
        new Def { Id = "FanyunzSteak", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanyunz", Texture = "FanyunzSteak", Kg = 0.171f, Kcal = 820f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Фаньюнз»", En = "Fanyunz onion rings", RuF = "стейкхаус", EnF = "steakhouse onion", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Луковые кольца, после которых разговаривать лучше против ветра. В школьном рюкзаке такое не доживало до обеда. Рыба подо льдом завидует.", EnJ = "Onion rings after which you'd better talk downwind. In a school bag this never lasted till lunch. The fish under the ice are jealous.", Rare = false },
        new Def { Id = "FanyunzBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanyunz", Texture = "FanyunzBBQ", Kg = 0.171f, Kcal = 820f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Фаньюнз»", En = "Fanyunz onion rings", RuF = "барбекю", EnF = "barbecue", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Луковые кольца, после которых разговаривать лучше против ветра. Его обменяли бы на патрон, будь тут с кем меняться. Олень от такого отказался бы. Олень не голодал.", EnJ = "Onion rings after which you'd better talk downwind. You could trade it for a cartridge, if there were anyone to trade with. A deer would turn it down. A deer has never starved.", Rare = false },
        new Def { Id = "FanyunzChile", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanyunz", Texture = "FanyunzChile", Kg = 0.171f, Kcal = 820f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Фаньюнз»", En = "Fanyunz onion rings", RuF = "чили и лайм", EnF = "chilli lime", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Луковые кольца, после которых разговаривать лучше против ветра. На вокзале это стоило втрое дороже. Теперь даром. Соль есть, жир есть, совести нет.", EnJ = "Onion rings after which you'd better talk downwind. At the station it cost three times as much. Now it is free. Salt: yes. Fat: yes. Conscience: none.", Rare = false },
        new Def { Id = "FanyunzRanch", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanyunz", Texture = "FanyunzRanch", Kg = 0.171f, Kcal = 820f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Фаньюнз»", En = "Fanyunz onion rings", RuF = "ранч", EnF = "ranch", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Луковые кольца, после которых разговаривать лучше против ветра. Пережило толчок и даже не помялось. Ешьте до темноты: в темноте крошки не найти.", EnJ = "Onion rings after which you'd better talk downwind. It came through the quake without a dent. Eat before dark: you cannot find crumbs in the dark.", Rare = false },
        new Def { Id = "FanyunzCheddar", Kind = Kind.Snack, Shape = "bag", Mesh = "Fanyunz", Texture = "FanyunzCheddar", Kg = 0.171f, Kcal = 820f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Фаньюнз»", En = "Fanyunz onion rings", RuF = "чеддер", EnF = "cheddar", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold" }, RuJ = "Луковые кольца, после которых разговаривать лучше против ветра. Китобои такого не ели, но оценили бы. Лучшее, что случится с вами сегодня.", EnJ = "Onion rings after which you'd better talk downwind. The whalers never ate this, but they would have approved. The best thing that will happen to you today.", Rare = false },
        new Def { Id = "GoldfyshCheddar", Kind = Kind.Snack, Shape = "bag", Mesh = "Goldfysh", Texture = "GoldfyshCheddar", Kg = 0.195f, Kcal = 900f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Голдфиш»", En = "Goldfysh crackers", RuF = "чеддер", EnF = "cheddar", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крекеры-рыбки: улыбаются, пока их едят. Оптимисты. Осталось после чьего-то дня рождения. Гости не пришли. Для полного счастья не хватает только дивана.", EnJ = "Fish-shaped crackers: they smile while being eaten. Optimists. Left over from someone's birthday. The guests never came. All that is missing for perfect happiness is a sofa.", Rare = false },
        new Def { Id = "GoldfyshPizza", Kind = Kind.Snack, Shape = "bag", Mesh = "Goldfysh", Texture = "GoldfyshPizza", Kg = 0.195f, Kcal = 900f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Голдфиш»", En = "Goldfysh crackers", RuF = "пицца", EnF = "pizza", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крекеры-рыбки: улыбаются, пока их едят. Оптимисты. Мерзлота хранит лучше любого холодильника. Вкус детства, если детство было так себе.", EnJ = "Fish-shaped crackers: they smile while being eaten. Optimists. Permafrost keeps things better than any fridge. The taste of childhood, if childhood was so-so.", Rare = false },
        new Def { Id = "GoldfyshPretzel", Kind = Kind.Snack, Shape = "bag", Mesh = "Goldfysh", Texture = "GoldfyshPretzel", Kg = 0.195f, Kcal = 900f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Голдфиш»", En = "Goldfysh crackers", RuF = "крендель", EnF = "pretzel", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крекеры-рыбки: улыбаются, пока их едят. Оптимисты. Такое добывали из автомата, который съедал последнюю монету. Шуршит как надежда.", EnJ = "Fish-shaped crackers: they smile while being eaten. Optimists. These came from the vending machine that ate your last coin. It rustles like hope.", Rare = false },
        new Def { Id = "GoldfyshParmesan", Kind = Kind.Snack, Shape = "bag", Mesh = "Goldfysh", Texture = "GoldfyshParmesan", Kg = 0.195f, Kcal = 900f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Голдфиш»", En = "Goldfysh crackers", RuF = "пармезан", EnF = "parmesan", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крекеры-рыбки: улыбаются, пока их едят. Оптимисты. Такое брали в лодку под брезент, на весь день. Голод отступит, жажда придёт. Честный обмен.", EnJ = "Fish-shaped crackers: they smile while being eaten. Optimists. People took these out in the boat under the tarpaulin, for the whole day. Hunger leaves, thirst arrives. A fair trade.", Rare = false },
        new Def { Id = "GoldfyshGingerbread", Kind = Kind.Snack, Shape = "bag", Mesh = "Goldfysh", Texture = "GoldfyshGingerbread", Kg = 0.195f, Kcal = 900f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Голдфиш»", En = "Goldfysh crackers", RuF = "имбирный пряник", EnF = "gingerbread", RuC = "США", EnC = "USA", Fx = new[] { "SugarDry" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. С ним кто-то шёл к перевалу и не дошёл. Не согреет, зато отвлечёт.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. Someone carried it towards the pass and never arrived. It will not warm you, but it will distract you.", Rare = true },
        new Def { Id = "GoldfyshSpooky", Kind = Kind.Snack, Shape = "bag", Mesh = "Goldfysh", Texture = "GoldfyshSpooky", Kg = 0.195f, Kcal = 900f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Голдфиш»", En = "Goldfysh crackers", RuF = "страшилки", EnF = "spooky shapes", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Серия к Хэллоуину: редкость. Пугать тут и без неё есть кому. С таким сидели у окна с видом на метель. Пума предпочитает мясо. Вам повезло.", EnJ = "A Halloween edition: a rarity. There is plenty to scare you here without it. People sat with these at a window with a view of the blizzard. The cougar prefers meat. Lucky you.", Rare = true },
        new Def { Id = "GoldfyshHearts", Kind = Kind.Snack, Shape = "bag", Mesh = "Goldfysh", Texture = "GoldfyshHearts", Kg = 0.195f, Kcal = 900f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Голдфиш»", En = "Goldfysh crackers", RuF = "сердечки", EnF = "hearts", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Серия для влюблённых: редкость. Делить не с кем, зато вся ваша. Уцелело там, где сгорело всё остальное. Сначала попробуйте одну штучку. Шутка: ешьте всё.", EnJ = "A Valentine edition: a rarity. No one to share it with, so it is all yours. It survived where everything else burned. Try just one first. Joke: eat the lot.", Rare = true },
        new Def { Id = "GoldfyshColors", Kind = Kind.Snack, Shape = "bag", Mesh = "Goldfysh", Texture = "GoldfyshColors", Kg = 0.195f, Kcal = 900f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Голдфиш»", En = "Goldfysh crackers", RuF = "цветные", EnF = "colours", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крекеры-рыбки: улыбаются, пока их едят. Оптимисты. Этим кормили сторожевого пса. Пёс ушёл в волки. Такой ужин не стыдно записать в дневник.", EnJ = "Fish-shaped crackers: they smile while being eaten. Optimists. They fed the guard dog with this. The dog joined the wolves. A dinner worth writing in the journal.", Rare = false },
        new Def { Id = "GoldfyshSour", Kind = Kind.Snack, Shape = "bag", Mesh = "Goldfysh", Texture = "GoldfyshSour", Kg = 0.195f, Kcal = 900f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Голдфиш»", En = "Goldfysh crackers", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крекеры-рыбки: улыбаются, пока их едят. Оптимисты. Из запасов лесорубов: брали ящиками. Силы прибавит на один сугроб.", EnJ = "Fish-shaped crackers: they smile while being eaten. Optimists. From the loggers' stores: they bought it by the crate. It will carry you one snowdrift further.", Rare = false },
        new Def { Id = "GoldfyshHot", Kind = Kind.Snack, Shape = "bag", Mesh = "Goldfysh", Texture = "GoldfyshHot", Kg = 0.195f, Kcal = 900f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Голдфиш»", En = "Goldfysh crackers", RuF = "острые", EnF = "hot & spicy", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Крекеры-рыбки: улыбаются, пока их едят. Оптимисты. В пост такое не ели. Пост кончился вместе с миром. Идеально к закату, которого не видно за бураном.", EnJ = "Fish-shaped crackers: they smile while being eaten. Optimists. Nobody ate these during a fast. The fast ended with the world. Perfect with a sunset you cannot see for the storm.", Rare = false },
        new Def { Id = "GoldfyshGraham", Kind = Kind.Snack, Shape = "bag", Mesh = "Goldfysh", Texture = "GoldfyshGraham", Kg = 0.195f, Kcal = 900f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Голдфиш»", En = "Goldfysh crackers", RuF = "сладкие ванильные", EnF = "vanilla grahams", RuC = "США", EnC = "USA", Fx = new[] { "SugarDry" }, RuJ = "Крекеры-рыбки: улыбаются, пока их едят. Оптимисты. Теперь это ценнее денег. Деньги оставьте. Пахнет магазином. Помните магазины?", EnJ = "Fish-shaped crackers: they smile while being eaten. Optimists. It is worth more than money now. Leave the money. It smells of a shop. Remember shops?", Rare = false },
        new Def { Id = "GoldfyshSmores", Kind = Kind.Snack, Shape = "bag", Mesh = "Goldfysh", Texture = "GoldfyshSmores", Kg = 0.195f, Kcal = 900f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Голдфиш»", En = "Goldfysh crackers", RuF = "шоколад и зефир", EnF = "chocolate & marshmallow", RuC = "США", EnC = "USA", Fx = new[] { "SugarDry" }, RuJ = "Крекеры-рыбки: улыбаются, пока их едят. Оптимисты. Его несли на пикник. Пикник отменили навсегда. Мороз не испортил, время не взяло.", EnJ = "Fish-shaped crackers: they smile while being eaten. Optimists. It was headed for a picnic. The picnic is cancelled forever. Frost did not spoil it and time could not take it.", Rare = false },
        new Def { Id = "GoldfyshOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "Goldfysh", Texture = "GoldfyshOriginal", Kg = 0.195f, Kcal = 900f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Голдфиш»", En = "Goldfysh crackers", RuF = "солёные", EnF = "original saltine", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крекеры-рыбки: улыбаются, пока их едят. Оптимисты. Такое стояло у кассы на случай слабости. В рюкзаке не мнётся. Почти.", EnJ = "Fish-shaped crackers: they smile while being eaten. Optimists. These stood by the till for moments of weakness. It does not get crushed in a pack. Almost.", Rare = false },
        new Def { Id = "ChizItOriginal", Kind = Kind.Snack, Shape = "carton", Mesh = "ChizIt", Texture = "ChizItOriginal", Kg = 0.358f, Kcal = 1680f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Чиз-Ит»", En = "Chiz-It crackers", RuF = "оригинальные", EnF = "original", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сырные квадратики с дыркой посередине: дырку сделали, чтобы не вздулись от гордости. Досталось вам, потому что вы дошли первым. Съешьте сейчас: завтра может не быть аппетита.", EnJ = "Cheese squares with a hole in the middle: the hole keeps them from puffing up with pride. It is yours because you got here first. Eat it now: tomorrow you may have no appetite.", Rare = false },
        new Def { Id = "ChizItWhite", Kind = Kind.Snack, Shape = "carton", Mesh = "ChizIt", Texture = "ChizItWhite", Kg = 0.358f, Kcal = 1680f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Чиз-Ит»", En = "Chiz-It crackers", RuF = "белый чеддер", EnF = "white cheddar", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сырные квадратики с дыркой посередине: дырку сделали, чтобы не вздулись от гордости. Упаковка выцвела, внутри время остановилось. Хватит дойти до следующей хижины и пожалеть, что кончилось.", EnJ = "Cheese squares with a hole in the middle: the hole keeps them from puffing up with pride. The wrapper has faded; inside, time stood still. Enough to reach the next cabin and regret it is gone.", Rare = false },
        new Def { Id = "ChizItToasty", Kind = Kind.Snack, Shape = "carton", Mesh = "ChizIt", Texture = "ChizItToasty", Kg = 0.358f, Kcal = 1680f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Чиз-Ит»", En = "Chiz-It crackers", RuF = "сильно поджаренные", EnF = "extra toasty", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сырные квадратики с дыркой посередине: дырку сделали, чтобы не вздулись от гордости. Из чемодана пассажира, который не долетел. От такого не толстеют те, кто ходит по двадцать километров.", EnJ = "Cheese squares with a hole in the middle: the hole keeps them from puffing up with pride. From the suitcase of a passenger who never landed. Nobody who walks twenty kilometres a day gets fat on this.", Rare = false },
        new Def { Id = "ChizItHot", Kind = Kind.Snack, Shape = "carton", Mesh = "ChizIt", Texture = "ChizItHot", Kg = 0.358f, Kcal = 1680f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Чиз-Ит»", En = "Chiz-It crackers", RuF = "острые", EnF = "hot & spicy", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Сырные квадратики с дыркой посередине: дырку сделали, чтобы не вздулись от гордости. Перезимовало и ничуть не обиделось. Волчья стая не в курсе. Пусть так и будет.", EnJ = "Cheese squares with a hole in the middle: the hole keeps them from puffing up with pride. It made it through the winter and bears no grudge. The wolf pack does not know. Keep it that way.", Rare = false },
        new Def { Id = "ChizItSnowmen", Kind = Kind.Snack, Shape = "carton", Mesh = "ChizIt", Texture = "ChizItSnowmen", Kg = 0.358f, Kcal = 1680f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Чиз-Ит»", En = "Chiz-It crackers", RuF = "снеговики", EnF = "snowmen", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Зимняя серия: выпускали на один сезон, а зима тут навсегда. Запасливая хозяйка купила по акции шесть штук. Хрустеть в засаде не рекомендуется.", EnJ = "A winter edition: made for one season, and here winter is forever. A thrifty housewife bought six of these on offer. Crunching in an ambush is not recommended.", Rare = true },
        new Def { Id = "ChizItPepper", Kind = Kind.Snack, Shape = "carton", Mesh = "ChizIt", Texture = "ChizItPepper", Kg = 0.358f, Kcal = 1680f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Чиз-Ит»", En = "Chiz-It crackers", RuF = "перечный сыр", EnF = "pepper jack", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сырные квадратики с дыркой посередине: дырку сделали, чтобы не вздулись от гордости. Кто-то написал на упаковке «моё». Уже нет. Лекарство от тоски, отпускается без рецепта.", EnJ = "Cheese squares with a hole in the middle: the hole keeps them from puffing up with pride. Someone wrote 'mine' on it. Not any more. A cure for the blues, no prescription needed.", Rare = false },
        new Def { Id = "ChizItBacon", Kind = Kind.Snack, Shape = "carton", Mesh = "ChizIt", Texture = "ChizItBacon", Kg = 0.358f, Kcal = 1680f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Чиз-Ит»", En = "Chiz-It crackers", RuF = "чеддер и бекон", EnF = "cheddar & bacon", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сырные квадратики с дыркой посередине: дырку сделали, чтобы не вздулись от гордости. В консервном цеху это ели тайком от мастера. Жуйте и думайте о хорошем. Например, о добавке.", EnJ = "Cheese squares with a hole in the middle: the hole keeps them from puffing up with pride. At the cannery they ate this behind the foreman's back. Chew and think of nice things. Seconds, for example.", Rare = false },
        new Def { Id = "ChizItExtra", Kind = Kind.Snack, Shape = "carton", Mesh = "ChizIt", Texture = "ChizItExtra", Kg = 0.358f, Kcal = 1680f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Чиз-Ит»", En = "Chiz-It crackers", RuF = "двойной сыр", EnF = "extra cheesy", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сырные квадратики с дыркой посередине: дырку сделали, чтобы не вздулись от гордости. Его не взяли даже мародёры. Они спешили. К утру от него останется только запах на варежках.", EnJ = "Cheese squares with a hole in the middle: the hole keeps them from puffing up with pride. Even the looters left it. They were in a hurry. By morning only the smell on your mittens will be left.", Rare = false },
        new Def { Id = "ChizItPizza", Kind = Kind.Snack, Shape = "carton", Mesh = "ChizIt", Texture = "ChizItPizza", Kg = 0.358f, Kcal = 1680f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Чиз-Ит»", En = "Chiz-It crackers", RuF = "пицца", EnF = "pizza", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сырные квадратики с дыркой посередине: дырку сделали, чтобы не вздулись от гордости. Провело зиму на острове, как и вы. Тишина вокруг такая, что слышно, как вы жуёте.", EnJ = "Cheese squares with a hole in the middle: the hole keeps them from puffing up with pride. It spent the winter on the island, same as you. It is so quiet you can hear yourself chew.", Rare = false },
        new Def { Id = "ChizItGrooves", Kind = Kind.Snack, Shape = "carton", Mesh = "ChizIt", Texture = "ChizItGrooves", Kg = 0.358f, Kcal = 1680f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Чиз-Ит»", En = "Chiz-It crackers", RuF = "рифлёные ранч", EnF = "grooved ranch", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сырные квадратики с дыркой посередине: дырку сделали, чтобы не вздулись от гордости. Дети прятали такое под кроватью, в тайнике. Не делите на завтра: завтра будет новый голод.", EnJ = "Cheese squares with a hole in the middle: the hole keeps them from puffing up with pride. Children hid these under the bed, in a secret place. Do not save half for tomorrow: tomorrow brings its own hunger.", Rare = false },
        new Def { Id = "KombozCheddar", Kind = Kind.Snack, Shape = "bag", Mesh = "Komboz", Texture = "KombozCheddar", Kg = 0.186f, Kcal = 680f, Thirst = -8f, Eat = 4f, Ru = "Крендельки «Комбоз»", En = "Komboz pretzels", RuF = "крендель с чеддером", EnF = "cheddar cheese pretzel", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крендельные трубочки с начинкой: еда дальнобойщиков и ночных заправок. Осталось от геологов вместе с картой и долгами. Сосны вокруг делают вид, что не смотрят.", EnJ = "Filled pretzel tubes: the food of truckers and midnight gas stations. Left by the geologists along with a map and some debts. The pines around pretend not to watch.", Rare = false },
        new Def { Id = "KombozPizza", Kind = Kind.Snack, Shape = "bag", Mesh = "Komboz", Texture = "KombozPizza", Kg = 0.186f, Kcal = 680f, Thirst = -8f, Eat = 4f, Ru = "Крендельки «Комбоз»", En = "Komboz pretzels", RuF = "пиццерия", EnF = "pizzeria pretzel", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крендельные трубочки с начинкой: еда дальнобойщиков и ночных заправок. На острове такое было праздником и до катастрофы. Калории мелкие, зато свои.", EnJ = "Filled pretzel tubes: the food of truckers and midnight gas stations. On the island this was a treat even before the disaster. Small calories, but your own.", Rare = false },
        new Def { Id = "KombozBuffalo", Kind = Kind.Snack, Shape = "bag", Mesh = "Komboz", Texture = "KombozBuffalo", Kg = 0.186f, Kcal = 680f, Thirst = -8f, Eat = 4f, Ru = "Крендельки «Комбоз»", En = "Komboz pretzels", RuF = "соус баффало", EnF = "buffalo blue cheese", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Крендельные трубочки с начинкой: еда дальнобойщиков и ночных заправок. С таким слушали радио, которое теперь ловит только треск. После этого даже крапивный чай покажется десертом.", EnJ = "Filled pretzel tubes: the food of truckers and midnight gas stations. People ate these by the radio, which picks up nothing but crackle now. After this even nettle tea feels like dessert.", Rare = false },
        new Def { Id = "KombozPepperoni", Kind = Kind.Snack, Shape = "bag", Mesh = "Komboz", Texture = "KombozPepperoni", Kg = 0.186f, Kcal = 680f, Thirst = -8f, Eat = 4f, Ru = "Крендельки «Комбоз»", En = "Komboz pretzels", RuF = "пепперони", EnF = "pepperoni pizza", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Крендельные трубочки с начинкой: еда дальнобойщиков и ночных заправок. Крысы прогрызли соседнюю, эту пощадили. Нашедшему полагается всё.", EnJ = "Filled pretzel tubes: the food of truckers and midnight gas stations. The rats gnawed through the one next to it and spared this. Finders keepers, all of it.", Rare = false },
        new Def { Id = "KombozNacho", Kind = Kind.Snack, Shape = "bag", Mesh = "Komboz", Texture = "KombozNacho", Kg = 0.186f, Kcal = 680f, Thirst = -8f, Eat = 4f, Ru = "Крендельки «Комбоз»", En = "Komboz pretzels", RuF = "сыр начо", EnF = "nacho cheese", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крендельные трубочки с начинкой: еда дальнобойщиков и ночных заправок. Бывший хозяин клялся бросить. Не успел. Зубы целы? Тогда вперёд.", EnJ = "Filled pretzel tubes: the food of truckers and midnight gas stations. The former owner swore to give these up. He ran out of time. Teeth intact? Then go ahead.", Rare = false },
        new Def { Id = "KombozHoney", Kind = Kind.Snack, Shape = "bag", Mesh = "Komboz", Texture = "KombozHoney", Kg = 0.186f, Kcal = 680f, Thirst = -8f, Eat = 4f, Ru = "Крендельки «Комбоз»", En = "Komboz pretzels", RuF = "мёд и горчица", EnF = "honey mustard", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Крендельные трубочки с начинкой: еда дальнобойщиков и ночных заправок. Его катали в кабине трактора три сезона. Ночью приснится добавка.", EnJ = "Filled pretzel tubes: the food of truckers and midnight gas stations. It rode around in a tractor cab for three seasons. Tonight you will dream of seconds.", Rare = false },
        new Def { Id = "KombozBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Komboz", Texture = "KombozBacon", Kg = 0.186f, Kcal = 680f, Thirst = -8f, Eat = 4f, Ru = "Крендельки «Комбоз»", En = "Komboz pretzels", RuF = "бекон и чеддер", EnF = "bacon cheddar", RuC = "США", EnC = "USA", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Крендельные трубочки с начинкой: еда дальнобойщиков и ночных заправок. После бани такое шло лучше всего. С таким запасом можно пережить ещё один вечер.", EnJ = "Filled pretzel tubes: the food of truckers and midnight gas stations. Nothing went down better after the sauna. With supplies like this you can survive one more evening.", Rare = false },
        new Def { Id = "CheksMixTraditional", Kind = Kind.Snack, Shape = "bag", Mesh = "CheksMix", Texture = "CheksMixTraditional", Kg = 0.256f, Kcal = 1120f, Thirst = -7f, Eat = 5f, Ru = "Снек-микс «Чекс Микс»", En = "Cheks Mix snack mix", RuF = "традиционный", EnF = "traditional", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Снек-микс: все выбирают из него любимое, на дне остаются крендельки. В тюрьме на это выменивали что угодно. Пёс бы выпросил половину. Пса нет.", EnJ = "Snack mix: everyone picks out their favourite, the pretzels stay at the bottom. In the prison you could trade one of these for anything. A dog would beg half of it. There is no dog.", Rare = false },
        new Def { Id = "CheksMixBold", Kind = Kind.Snack, Shape = "bag", Mesh = "CheksMix", Texture = "CheksMixBold", Kg = 0.256f, Kcal = 1120f, Thirst = -7f, Eat = 5f, Ru = "Снек-микс «Чекс Микс»", En = "Cheks Mix snack mix", RuF = "смелый", EnF = "bold party blend", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Снек-микс: все выбирают из него любимое, на дне остаются крендельки. Кто-то менял это на сигареты. Сделка сорвалась. Съедено будет быстрее, чем найдено.", EnJ = "Snack mix: everyone picks out their favourite, the pretzels stay at the bottom. Someone was trading this for cigarettes. The deal fell through. It will be eaten faster than it was found.", Rare = false },
        new Def { Id = "CheksMixCheddar", Kind = Kind.Snack, Shape = "bag", Mesh = "CheksMix", Texture = "CheksMixCheddar", Kg = 0.256f, Kcal = 1120f, Thirst = -7f, Eat = 5f, Ru = "Снек-микс «Чекс Микс»", En = "Cheks Mix snack mix", RuF = "чеддер", EnF = "cheddar", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Снек-микс: все выбирают из него любимое, на дне остаются крендельки. С ним зимовали на метеостанции, пока было с кем. На вкус как выходной.", EnJ = "Snack mix: everyone picks out their favourite, the pretzels stay at the bottom. They wintered with it at the weather station, while there was a 'they'. It tastes like a day off.", Rare = false },
        new Def { Id = "CheksMixXmas", Kind = Kind.Snack, Shape = "bag", Mesh = "CheksMix", Texture = "CheksMixXmas", Kg = 0.256f, Kcal = 1120f, Thirst = -7f, Eat = 5f, Ru = "Снек-микс «Чекс Микс»", En = "Cheks Mix snack mix", RuF = "рождественская смесь с корицей", EnF = "christmas cinnamon mix", RuC = "США", EnC = "USA", Fx = new[] { "SugarDry" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Такое терялось в кладовке среди крупы и надежд. Ветер унесёт запах прямо к берлоге. Ешьте быстрее.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. These got lost in the pantry among the grain and the hopes. The wind carries the smell straight to the den. Eat faster.", Rare = true },
        new Def { Id = "CheksMixHoney", Kind = Kind.Snack, Shape = "bag", Mesh = "CheksMix", Texture = "CheksMixHoney", Kg = 0.256f, Kcal = 1120f, Thirst = -7f, Eat = 5f, Ru = "Снек-микс «Чекс Микс»", En = "Cheks Mix snack mix", RuF = "ореховый мёд", EnF = "honey nut", RuC = "США", EnC = "USA", Fx = new[] { "SugarDry" }, RuJ = "Снек-микс: все выбирают из него любимое, на дне остаются крендельки. Его берегли к приезду внуков. Больше таких не делают. Совсем.", EnJ = "Snack mix: everyone picks out their favourite, the pretzels stay at the bottom. It was being saved for the grandchildren's visit. They do not make these any more. At all.", Rare = false },
        new Def { Id = "CheksMixHot", Kind = Kind.Snack, Shape = "bag", Mesh = "CheksMix", Texture = "CheksMixHot", Kg = 0.256f, Kcal = 1120f, Thirst = -7f, Eat = 5f, Ru = "Снек-микс «Чекс Микс»", En = "Cheks Mix snack mix", RuF = "острый", EnF = "hot & spicy", RuC = "США", EnC = "USA", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Снек-микс: все выбирают из него любимое, на дне остаются крендельки. В баре такое ставили на стойку, бесплатно к пиву. Пива нет. Хорошо идёт под треск поленьев.", EnJ = "Snack mix: everyone picks out their favourite, the pretzels stay at the bottom. Bars put these out free with a beer. There is no beer. Goes down well with crackling logs.", Rare = false },
        new Def { Id = "CheksMixMuddy", Kind = Kind.Snack, Shape = "bag", Mesh = "CheksMix", Texture = "CheksMixMuddy", Kg = 0.256f, Kcal = 1120f, Thirst = -7f, Eat = 5f, Ru = "Снек-микс «Чекс Микс»", En = "Cheks Mix snack mix", RuF = "шоколад и арахис", EnF = "chocolate peanut butter", RuC = "США", EnC = "USA", Fx = new[] { "SugarDry" }, RuJ = "Снек-микс: все выбирают из него любимое, на дне остаются крендельки. Такое лежало в каждом доме, пока не погас свет. Руки вытирать о штаны: салфеток не завезли.", EnJ = "Snack mix: everyone picks out their favourite, the pretzels stay at the bottom. Every house had one of these until the lights went out. Wipe your hands on your trousers: no napkins were delivered.", Rare = false },
        new Def { Id = "CheksMixSour", Kind = Kind.Snack, Shape = "bag", Mesh = "CheksMix", Texture = "CheksMixSour", Kg = 0.256f, Kcal = 1120f, Thirst = -7f, Eat = 5f, Ru = "Снек-микс «Чекс Микс»", En = "Cheks Mix snack mix", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Снек-микс: все выбирают из него любимое, на дне остаются крендельки. Кто-то берёг это на чёрный день. Он настал. Маленькая радость размером с ладонь.", EnJ = "Snack mix: everyone picks out their favourite, the pretzels stay at the bottom. Someone saved this for a rainy day. It came. A small joy the size of your palm.", Rare = false },
        new Def { Id = "CheksMixJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "CheksMix", Texture = "CheksMixJalapeno", Kg = 0.256f, Kcal = 1120f, Thirst = -7f, Eat = 5f, Ru = "Снек-микс «Чекс Микс»", En = "Cheks Mix snack mix", RuF = "халапеньо и чеддер", EnF = "jalapeno cheddar", RuC = "США", EnC = "USA", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Снек-микс: все выбирают из него любимое, на дне остаются крендельки. Пережило хозяина, кота и две зимы. Совесть молчит, живот поёт.", EnJ = "Snack mix: everyone picks out their favourite, the pretzels stay at the bottom. It outlived its owner, the cat and two winters. Conscience is silent, the belly sings.", Rare = false },
        new Def { Id = "WanderfulSalted", Kind = Kind.Snack, Shape = "bag", Mesh = "Wanderful", Texture = "WanderfulSalted", Kg = 0.178f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Фисташки «Уандерфул»", En = "Wanderful nuts", RuF = "жареные солёные", EnF = "roasted & salted", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Фисташки: закрытую всегда оставляют напоследок, а потом кладут обратно. Такое обычно находили за диваном, как всё лучшее в жизни. Проверено поколениями и одной катастрофой.", EnJ = "Pistachios: the closed one is always left for last and then put back. These were usually found behind the sofa, like all the best things in life. Tested by generations and one catastrophe.", Rare = false },
        new Def { Id = "WanderfulChili", Kind = Kind.Snack, Shape = "bag", Mesh = "Wanderful", Texture = "WanderfulChili", Kg = 0.178f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Фисташки «Уандерфул»", En = "Wanderful nuts", RuF = "чили и лайм", EnF = "chili roasted", RuC = "США", EnC = "USA", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Фисташки: закрытую всегда оставляют напоследок, а потом кладут обратно. Последний завоз был до того, как упали самолёты. Оставьте пару штук на перевал. Не оставите.", EnJ = "Pistachios: the closed one is always left for last and then put back. The last delivery came before the planes fell. Save a couple for the pass. You will not.", Rare = false },
        new Def { Id = "WanderfulPepper", Kind = Kind.Snack, Shape = "bag", Mesh = "Wanderful", Texture = "WanderfulPepper", Kg = 0.178f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Фисташки «Уандерфул»", En = "Wanderful nuts", RuF = "соль и перец", EnF = "salt & pepper", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Фисташки: закрытую всегда оставляют напоследок, а потом кладут обратно. Ценник оторван: теперь это бесценно. Здесь это считается ужином при свечах.", EnJ = "Pistachios: the closed one is always left for last and then put back. The price tag is torn off: it is priceless now. Round here this counts as a candlelit dinner.", Rare = false },
        new Def { Id = "WanderfulNoShells", Kind = Kind.Snack, Shape = "bag", Mesh = "Wanderful", Texture = "WanderfulNoShells", Kg = 0.178f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Фисташки «Уандерфул»", En = "Wanderful nuts", RuF = "очищенные", EnF = "no shells", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Фисташки: закрытую всегда оставляют напоследок, а потом кладут обратно. Дата на шве стёрлась, и слава богу. Луна светит, еда хрустит, жизнь налаживается.", EnJ = "Pistachios: the closed one is always left for last and then put back. The date on the seam has rubbed off, thank goodness. The moon shines, the food crunches, life is looking up.", Rare = false },
        new Def { Id = "WanderfulSummer", Kind = Kind.Snack, Shape = "bag", Mesh = "Wanderful", Texture = "WanderfulSummer", Kg = 0.178f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Фисташки «Уандерфул»", En = "Wanderful nuts", RuF = "лимон и соль", EnF = "lemon & salt", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Пахнет заправкой у Прибрежного шоссе. Снег вокруг не солёный. Это солёное.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. It smells of the petrol station on the Coastal Highway. The snow around is not salty. This is.", Rare = true },
        new Def { Id = "WanderfulUnsalted", Kind = Kind.Snack, Shape = "bag", Mesh = "Wanderful", Texture = "WanderfulUnsalted", Kg = 0.178f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Фисташки «Уандерфул»", En = "Wanderful nuts", RuF = "без соли", EnF = "unsalted", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Фисташки: закрытую всегда оставляют напоследок, а потом кладут обратно. Такое возили в бардачке на дальнюю дорогу. Дороги кончились. Больше таких не делают. Совсем.", EnJ = "Pistachios: the closed one is always left for last and then put back. People kept these in the glovebox for long drives. The drives are over. They do not make these any more. At all.", Rare = false },
        new Def { Id = "WanderfulVinegar", Kind = Kind.Snack, Shape = "bag", Mesh = "Wanderful", Texture = "WanderfulVinegar", Kg = 0.178f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Фисташки «Уандерфул»", En = "Wanderful nuts", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Фисташки: закрытую всегда оставляют напоследок, а потом кладут обратно. Мыши не тронули. Думайте сами. Открывайте тихо: у волков отличный слух.", EnJ = "Pistachios: the closed one is always left for last and then put back. The mice left it alone. Draw your own conclusions. Open it quietly: wolves have excellent hearing.", Rare = false },
        new Def { Id = "WanderfulSweet", Kind = Kind.Snack, Shape = "bag", Mesh = "Wanderful", Texture = "WanderfulSweet", Kg = 0.178f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Фисташки «Уандерфул»", En = "Wanderful nuts", RuF = "сладкий чили", EnF = "sweet chilli", RuC = "США", EnC = "USA", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Фисташки: закрытую всегда оставляют напоследок, а потом кладут обратно. Рыбаки брали такое на лёд вместо обеда. Одной не обойдётся, но вторая неизвестно где.", EnJ = "Pistachios: the closed one is always left for last and then put back. Fishermen took this onto the ice instead of lunch. One won't be enough, and nobody knows where the second is.", Rare = false },
        new Def { Id = "WanderfulBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Wanderful", Texture = "WanderfulBBQ", Kg = 0.178f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Фисташки «Уандерфул»", En = "Wanderful nuts", RuF = "барбекю", EnF = "barbecue", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Фисташки: закрытую всегда оставляют напоследок, а потом кладут обратно. Смотритель плотины держал такое в заначке. Крошки с пола тоже считаются.", EnJ = "Pistachios: the closed one is always left for last and then put back. The dam keeper kept a stash of these. The crumbs on the floor count too.", Rare = false },
        new Def { Id = "WanderfulJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "Wanderful", Texture = "WanderfulJalapeno", Kg = 0.178f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Фисташки «Уандерфул»", En = "Wanderful nuts", RuF = "халапеньо и лайм", EnF = "jalapeno lime", RuC = "США", EnC = "USA", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Фисташки: закрытую всегда оставляют напоследок, а потом кладут обратно. Кто-то спрятал это от детей. Дети не нашли. Запейте чаем из шиповника и считайте это обедом.", EnJ = "Pistachios: the closed one is always left for last and then put back. Someone hid it from the kids. The kids never found it. Wash it down with rosehip tea and call it lunch.", Rare = false },
        new Def { Id = "WanderfulGarlic", Kind = Kind.Snack, Shape = "bag", Mesh = "Wanderful", Texture = "WanderfulGarlic", Kg = 0.178f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Фисташки «Уандерфул»", En = "Wanderful nuts", RuF = "копчёный чеснок", EnF = "smoked garlic", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Фисташки: закрытую всегда оставляют напоследок, а потом кладут обратно. В сельском магазине такое вечно заваливалось за прилавок. Медведю не показывать: отнимет вместе с рукой.", EnJ = "Pistachios: the closed one is always left for last and then put back. In the village shop these kept slipping behind the counter. Do not show the bear: he will take it, hand and all.", Rare = false },
        new Def { Id = "BluDaimondSmoke", Kind = Kind.Snack, Shape = "can", Mesh = "BluDaimond", Texture = "BluDaimondSmoke", Kg = 0.2f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Миндаль «Блю Даймонд»", En = "Blu Daimond nuts", RuF = "с дымком", EnF = "smokehouse", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Калифорнийский миндаль: банка синяя, как небо, которого тут не видно неделями. Ждало покупателя дольше, чем тот прожил. Диетолог не одобрил бы. Диетолога тут нет.", EnJ = "California almonds: the can is as blue as the sky you don't see here for weeks. It waited for a buyer longer than the buyer lived. A dietitian would not approve. There is no dietitian here.", Rare = false },
        new Def { Id = "BluDaimondWasabi", Kind = Kind.Snack, Shape = "can", Mesh = "BluDaimond", Texture = "BluDaimondWasabi", Kg = 0.2f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Миндаль «Блю Даймонд»", En = "Blu Daimond nuts", RuF = "васаби и соевый соус", EnF = "wasabi & soy sauce", RuC = "США", EnC = "USA", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Калифорнийский миндаль: банка синяя, как небо, которого тут не видно неделями. С материка такое больше не привезут. Лучше, чем кора. Проверено.", EnJ = "California almonds: the can is as blue as the sky you don't see here for weeks. Nobody will bring this from the mainland again. Better than bark. Tested.", Rare = false },
        new Def { Id = "BluDaimondVinegar", Kind = Kind.Snack, Shape = "can", Mesh = "BluDaimond", Texture = "BluDaimondVinegar", Kg = 0.2f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Миндаль «Блю Даймонд»", En = "Blu Daimond nuts", RuF = "соль и уксус", EnF = "salt n vinegar", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Калифорнийский миндаль: банка синяя, как небо, которого тут не видно неделями. На упаковке иней, внутри всё по-прежнему. Хруст разносится до соседней долины.", EnJ = "California almonds: the can is as blue as the sky you don't see here for weeks. Frost on the wrapper, business as usual inside. The crunch carries to the next valley.", Rare = false },
        new Def { Id = "BluDaimondHoney", Kind = Kind.Snack, Shape = "can", Mesh = "BluDaimond", Texture = "BluDaimondHoney", Kg = 0.2f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Миндаль «Блю Даймонд»", En = "Blu Daimond nuts", RuF = "в меду", EnF = "honey roasted", RuC = "США", EnC = "USA", Fx = new[] { "SugarDry" }, RuJ = "Калифорнийский миндаль: банка синяя, как небо, которого тут не видно неделями. Мороз ему нипочём: твёрже не стало, мягче тоже. Ешьте медленно: когда ещё такое найдёте.", EnJ = "California almonds: the can is as blue as the sky you don't see here for weeks. The frost did nothing to it: no harder, no softer. Eat slowly: who knows when you will find another.", Rare = false },
        new Def { Id = "BluDaimondPumpkin", Kind = Kind.Snack, Shape = "can", Mesh = "BluDaimond", Texture = "BluDaimondPumpkin", Kg = 0.2f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Миндаль «Блю Даймонд»", En = "Blu Daimond nuts", RuF = "тыквенные специи", EnF = "pumpkin spice", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Из тех времён, когда еду выбирали по вкусу. К этому просится пиво, а есть только талый снег.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. From the days when people picked food for its taste. It begs for a beer, and there is only melted snow.", Rare = true },
        new Def { Id = "BluDaimondPeppermint", Kind = Kind.Snack, Shape = "can", Mesh = "BluDaimond", Texture = "BluDaimondPeppermint", Kg = 0.2f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Миндаль «Блю Даймонд»", En = "Blu Daimond nuts", RuF = "мятное какао", EnF = "peppermint cocoa", RuC = "США", EnC = "USA", Fx = new[] { "SugarDry" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Чей-то перекус на ночную смену, которая не кончилась. Сияние на вкус не влияет. Наверное.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. Someone's snack for a night shift that never ended. The aurora does not affect the taste. Probably.", Rare = true },
        new Def { Id = "BluDaimondSalt", Kind = Kind.Snack, Shape = "can", Mesh = "BluDaimond", Texture = "BluDaimondSalt", Kg = 0.2f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Миндаль «Блю Даймонд»", En = "Blu Daimond nuts", RuF = "морская соль", EnF = "sea salt", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Калифорнийский миндаль: банка синяя, как небо, которого тут не видно неделями. В охотничьей вышке таким встречали рассвет. После тушёнки из банки это почти ресторан.", EnJ = "California almonds: the can is as blue as the sky you don't see here for weeks. In the hunting blind they met the dawn with this. After stew from a tin this is nearly a restaurant.", Rare = false },
        new Def { Id = "BluDaimondHabanero", Kind = Kind.Snack, Shape = "can", Mesh = "BluDaimond", Texture = "BluDaimondHabanero", Kg = 0.2f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Миндаль «Блю Даймонд»", En = "Blu Daimond nuts", RuF = "хабанеро барбекю", EnF = "habanero barbecue", RuC = "США", EnC = "USA", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Калифорнийский миндаль: банка синяя, как небо, которого тут не видно неделями. Такое носили в кармане куртки на всякий случай. Случай настал. Делиться не с кем, и это впервые радует.", EnJ = "California almonds: the can is as blue as the sky you don't see here for weeks. People carried these in a coat pocket just in case. The case has come. Nobody to share with, and for once that is good news.", Rare = false },
        new Def { Id = "BluDaimondLime", Kind = Kind.Snack, Shape = "can", Mesh = "BluDaimond", Texture = "BluDaimondLime", Kg = 0.2f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Миндаль «Блю Даймонд»", En = "Blu Daimond nuts", RuF = "чили и лайм", EnF = "chilli lime", RuC = "США", EnC = "USA", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Калифорнийский миндаль: банка синяя, как небо, которого тут не видно неделями. Прежний хозяин оставил записку: «Не трогать». Записка сгорела. Пальцы потом оближите: зимой калории не выбрасывают.", EnJ = "California almonds: the can is as blue as the sky you don't see here for weeks. The last owner left a note: 'Do not touch'. The note burned. Lick your fingers after: in winter you do not waste calories.", Rare = false },
        new Def { Id = "BluDaimondCocoa", Kind = Kind.Snack, Shape = "can", Mesh = "BluDaimond", Texture = "BluDaimondCocoa", Kg = 0.2f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Миндаль «Блю Даймонд»", En = "Blu Daimond nuts", RuF = "тёмное какао", EnF = "dark chocolate cocoa", RuC = "США", EnC = "USA", Fx = new[] { "SugarDry" }, RuJ = "Калифорнийский миндаль: банка синяя, как небо, которого тут не видно неделями. Такими торговали в поезде, пока поезд ходил. Ворон на ветке уже ждёт свою долю.", EnJ = "California almonds: the can is as blue as the sky you don't see here for weeks. They sold these on the train, while the train ran. The crow on the branch is already waiting for its share.", Rare = false },
        new Def { Id = "BluDaimondDill", Kind = Kind.Snack, Shape = "can", Mesh = "BluDaimond", Texture = "BluDaimondDill", Kg = 0.2f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Миндаль «Блю Даймонд»", En = "Blu Daimond nuts", RuF = "маринованный огурец", EnF = "dill pickle", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Калифорнийский миндаль: банка синяя, как небо, которого тут не видно неделями. Сторож шахты держал такое в ящике стола. На морозе хрустит вдвое громче.", EnJ = "California almonds: the can is as blue as the sky you don't see here for weeks. The mine watchman kept these in his desk drawer. In the frost it crunches twice as loud.", Rare = false },
        new Def { Id = "BluDaimondToffee", Kind = Kind.Snack, Shape = "can", Mesh = "BluDaimond", Texture = "BluDaimondToffee", Kg = 0.2f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Миндаль «Блю Даймонд»", En = "Blu Daimond nuts", RuF = "сливочная ириска", EnF = "butter toffee", RuC = "США", EnC = "USA", Fx = new[] { "SugarDry" }, RuJ = "Калифорнийский миндаль: банка синяя, как небо, которого тут не видно неделями. Лавина прошла мимо, срок годности тоже. Не еда, а настроение. Настроение тоже греет.", EnJ = "California almonds: the can is as blue as the sky you don't see here for weeks. The avalanche missed it, and so did the best-before date. Not food but a mood. A mood warms you too.", Rare = false },
        new Def { Id = "BluDaimondBlueberry", Kind = Kind.Snack, Shape = "can", Mesh = "BluDaimond", Texture = "BluDaimondBlueberry", Kg = 0.2f, Kcal = 1020f, Thirst = -8f, Eat = 6f, Ru = "Миндаль «Блю Даймонд»", En = "Blu Daimond nuts", RuF = "черника", EnF = "blueberry", RuC = "США", EnC = "USA", Fx = new[] { "SugarDry" }, RuJ = "Калифорнийский миндаль: банка синяя, как небо, которого тут не видно неделями. Такое всегда стояло на видном месте, поэтому никто не брал. Сытости на час, воспоминаний на неделю.", EnJ = "California almonds: the can is as blue as the sky you don't see here for weeks. These always stood in plain sight, which is why nobody took them. An hour of fullness, a week of memories.", Rare = false },
        new Def { Id = "JekLinksOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "JekLinks", Texture = "JekLinksOriginal", Kg = 0.088f, Kcal = 240f, Thirst = -10f, Eat = 8f, Ru = "Вяленая говядина «Джек Линкс»", En = "Jek Links beef jerky", RuF = "оригинальная", EnF = "original", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Вяленая говядина: на рекламе с ней дразнили снежного человека. Зря. Кто-то открыл, передумал и умер. Не связано. Кролик смотрит с осуждением.", EnJ = "Beef jerky: in the adverts they teased Sasquatch with it. A mistake. Someone opened it, changed their mind and died. Unrelated. The rabbit looks on with disapproval.", Rare = false },
        new Def { Id = "JekLinksTeriyaki", Kind = Kind.Snack, Shape = "bag", Mesh = "JekLinks", Texture = "JekLinksTeriyaki", Kg = 0.088f, Kcal = 240f, Thirst = -10f, Eat = 8f, Ru = "Вяленая говядина «Джек Линкс»", En = "Jek Links beef jerky", RuF = "терияки", EnF = "teriyaki", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Вяленая говядина: на рекламе с ней дразнили снежного человека. Зря. Такое вечно каталось под сиденьем пикапа. У костра вкуснее. У костра всё вкуснее.", EnJ = "Beef jerky: in the adverts they teased Sasquatch with it. A mistake. One of these was always rolling under a pickup seat. It tastes better by the fire. Everything does.", Rare = false },
        new Def { Id = "JekLinksPeppered", Kind = Kind.Snack, Shape = "bag", Mesh = "JekLinks", Texture = "JekLinksPeppered", Kg = 0.088f, Kcal = 240f, Thirst = -10f, Eat = 8f, Ru = "Вяленая говядина «Джек Линкс»", En = "Jek Links beef jerky", RuF = "с перцем", EnF = "peppered", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Вяленая говядина: на рекламе с ней дразнили снежного человека. Зря. Привезено паромом, которого больше нет. Упаковку не выбрасывайте: ею можно разжечь печь.", EnJ = "Beef jerky: in the adverts they teased Sasquatch with it. A mistake. Brought over by a ferry that no longer exists. Keep the wrapper: it will light the stove.", Rare = false },
        new Def { Id = "JekLinksVenison", Kind = Kind.Snack, Shape = "bag", Mesh = "JekLinks", Texture = "JekLinksVenison", Kg = 0.088f, Kcal = 240f, Thirst = -10f, Eat = 8f, Ru = "Вяленая говядина «Джек Линкс»", En = "Jek Links beef jerky", RuF = "оленина, охотничий сезон", EnF = "hunting season venison", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Раньше это ели под телевизор. Телевизор молчит. Если это последняя на острове, вы её достойны.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. People ate this in front of the telly. The telly is silent. If this is the last one on the island, you have earned it.", Rare = true },
        new Def { Id = "JekLinksCranberry", Kind = Kind.Snack, Shape = "bag", Mesh = "JekLinks", Texture = "JekLinksCranberry", Kg = 0.088f, Kcal = 240f, Thirst = -10f, Eat = 8f, Ru = "Вяленая говядина «Джек Линкс»", En = "Jek Links beef jerky", RuF = "индейка с клюквой", EnF = "turkey & cranberry", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Забыто туристами, которым повезло уехать. Желудок удивится, но возражать не станет.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. Left behind by tourists who were lucky enough to leave. Your stomach will be surprised but will not object.", Rare = true },
        new Def { Id = "JekLinksHot", Kind = Kind.Snack, Shape = "bag", Mesh = "JekLinks", Texture = "JekLinksHot", Kg = 0.088f, Kcal = 240f, Thirst = -10f, Eat = 8f, Ru = "Вяленая говядина «Джек Линкс»", En = "Jek Links beef jerky", RuF = "острая", EnF = "hot", RuC = "США", EnC = "USA", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Вяленая говядина: на рекламе с ней дразнили снежного человека. Зря. Механики заедали этим обед, не вытирая рук. Запах выдаёт вас за сто шагов. Оно того стоит.", EnJ = "Beef jerky: in the adverts they teased Sasquatch with it. A mistake. Mechanics ate these for lunch without wiping their hands. The smell gives you away at a hundred paces. Worth it.", Rare = false },
        new Def { Id = "JekLinksJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "JekLinks", Texture = "JekLinksJalapeno", Kg = 0.088f, Kcal = 240f, Thirst = -10f, Eat = 8f, Ru = "Вяленая говядина «Джек Линкс»", En = "Jek Links beef jerky", RuF = "халапеньо", EnF = "jalapeno", RuC = "США", EnC = "USA", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Вяленая говядина: на рекламе с ней дразнили снежного человека. Зря. Последнее на всю Одинокую топь. Скорее всего. Раньше это называли вредным. Теперь называют едой.", EnJ = "Beef jerky: in the adverts they teased Sasquatch with it. A mistake. The last one in all of Forlorn Muskeg. Most likely. They used to call this unhealthy. Now they call it food.", Rare = false },
        new Def { Id = "JekLinksBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "JekLinks", Texture = "JekLinksBBQ", Kg = 0.088f, Kcal = 240f, Thirst = -10f, Eat = 8f, Ru = "Вяленая говядина «Джек Линкс»", En = "Jek Links beef jerky", RuF = "барбекю", EnF = "barbecue", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Вяленая говядина: на рекламе с ней дразнили снежного человека. Зря. Смотритель маяка грыз такое, ожидая кораблей. Спальный мешок потом вытряхните.", EnJ = "Beef jerky: in the adverts they teased Sasquatch with it. A mistake. The lighthouse keeper munched these while waiting for ships. Shake out your sleeping bag afterwards.", Rare = false },
        new Def { Id = "JekLinksHickory", Kind = Kind.Snack, Shape = "bag", Mesh = "JekLinks", Texture = "JekLinksHickory", Kg = 0.088f, Kcal = 240f, Thirst = -10f, Eat = 8f, Ru = "Вяленая говядина «Джек Линкс»", En = "Jek Links beef jerky", RuF = "дым гикори", EnF = "hickory smoke", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Вяленая говядина: на рекламе с ней дразнили снежного человека. Зря. Полки рушились, а это уцелело. Зимой такое идёт за валюту.", EnJ = "Beef jerky: in the adverts they teased Sasquatch with it. A mistake. Shelves collapsed and this survived. In winter this passes for currency.", Rare = false },
        new Def { Id = "JekLinksTurkey", Kind = Kind.Snack, Shape = "bag", Mesh = "JekLinks", Texture = "JekLinksTurkey", Kg = 0.088f, Kcal = 240f, Thirst = -10f, Eat = 8f, Ru = "Вяленая говядина «Джек Линкс»", En = "Jek Links beef jerky", RuF = "индейка", EnF = "turkey", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Вяленая говядина: на рекламе с ней дразнили снежного человека. Зря. Смотритель заповедника называл это ужином. Торговец дал бы за это тряпку. Вы дадите больше.", EnJ = "Beef jerky: in the adverts they teased Sasquatch with it. A mistake. The park ranger called this dinner. The trader would give a rag for it. You would give more.", Rare = false },
        new Def { Id = "JekLinksBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "JekLinks", Texture = "JekLinksBacon", Kg = 0.088f, Kcal = 240f, Thirst = -10f, Eat = 8f, Ru = "Вяленая говядина «Джек Линкс»", En = "Jek Links beef jerky", RuF = "бекон-джерки", EnF = "bacon jerky", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Вяленая говядина: на рекламе с ней дразнили снежного человека. Зря. Такое слали посылками с материка. Адресаты выбыли. Пока жуёте, метель кажется короче.", EnJ = "Beef jerky: in the adverts they teased Sasquatch with it. A mistake. These came in parcels from the mainland. The addressees are gone. While you chew, the blizzard seems shorter.", Rare = false },
        new Def { Id = "JekLinksSticks", Kind = Kind.Snack, Shape = "bag", Mesh = "JekLinks", Texture = "JekLinksSticks", Kg = 0.088f, Kcal = 240f, Thirst = -10f, Eat = 8f, Ru = "Вяленая говядина «Джек Линкс»", En = "Jek Links beef jerky", RuF = "колбаски", EnF = "beef sticks", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Вяленая говядина: на рекламе с ней дразнили снежного человека. Зря. Иные держали это за лекарство. Тоже лечит. Организм скажет спасибо. Или не скажет.", EnJ = "Beef jerky: in the adverts they teased Sasquatch with it. A mistake. Some people counted this as medicine. Also a cure. Your body will thank you. Or not.", Rare = false },
        new Def { Id = "JekLinksGarlic", Kind = Kind.Snack, Shape = "bag", Mesh = "JekLinks", Texture = "JekLinksGarlic", Kg = 0.088f, Kcal = 240f, Thirst = -10f, Eat = 8f, Ru = "Вяленая говядина «Джек Линкс»", En = "Jek Links beef jerky", RuF = "чеснок и перец", EnF = "garlic pepper", RuC = "США", EnC = "USA", Fx = new[] { "Sinew" }, RuJ = "Вяленая говядина: на рекламе с ней дразнили снежного человека. Зря. В школьном рюкзаке такое не доживало до обеда. На третьей горсти забываешь, что вокруг конец света.", EnJ = "Beef jerky: in the adverts they teased Sasquatch with it. A mistake. In a school bag this never lasted till lunch. By the third handful you forget the world has ended.", Rare = false },
        new Def { Id = "HamptiBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Hampti", Texture = "HamptiBBQ", Kg = 0.253f, Kcal = 1310f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хампти Дампти»", En = "Hampti Dampti crisps", RuF = "барбекю", EnF = "bar-b-q", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Чипсы с яйцом в шляпе: он сидел на стене, а теперь на пачке, тут безопаснее. Его обменяли бы на патрон, будь тут с кем меняться. Рыба подо льдом завидует.", EnJ = "Crisps with an egg in a hat: he sat on a wall, now he sits on a pack, it's safer. You could trade it for a cartridge, if there were anyone to trade with. The fish under the ice are jealous.", Rare = false },
        new Def { Id = "HamptiKetchup", Kind = Kind.Snack, Shape = "bag", Mesh = "Hampti", Texture = "HamptiKetchup", Kg = 0.253f, Kcal = 1310f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хампти Дампти»", En = "Hampti Dampti crisps", RuF = "кетчуп", EnF = "ketchup", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Чипсы с яйцом в шляпе: он сидел на стене, а теперь на пачке, тут безопаснее. На вокзале это стоило втрое дороже. Теперь даром. Олень от такого отказался бы. Олень не голодал.", EnJ = "Crisps with an egg in a hat: he sat on a wall, now he sits on a pack, it's safer. At the station it cost three times as much. Now it is free. A deer would turn it down. A deer has never starved.", Rare = false },
        new Def { Id = "HamptiClam", Kind = Kind.Snack, Shape = "bag", Mesh = "Hampti", Texture = "HamptiClam", Kg = 0.253f, Kcal = 1310f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хампти Дампти»", En = "Hampti Dampti crisps", RuF = "сметана и моллюски", EnF = "sour cream & clam", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Чипсы с яйцом в шляпе: он сидел на стене, а теперь на пачке, тут безопаснее. Пережило толчок и даже не помялось. Соль есть, жир есть, совести нет.", EnJ = "Crisps with an egg in a hat: he sat on a wall, now he sits on a pack, it's safer. It came through the quake without a dent. Salt: yes. Fat: yes. Conscience: none.", Rare = false },
        new Def { Id = "HamptiParty", Kind = Kind.Snack, Shape = "bag", Mesh = "Hampti", Texture = "HamptiParty", Kg = 0.253f, Kcal = 1310f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хампти Дампти»", En = "Hampti Dampti crisps", RuF = "смесь для вечеринки", EnF = "party mix", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Чипсы с яйцом в шляпе: он сидел на стене, а теперь на пачке, тут безопаснее. Китобои такого не ели, но оценили бы. Ешьте до темноты: в темноте крошки не найти.", EnJ = "Crisps with an egg in a hat: he sat on a wall, now he sits on a pack, it's safer. The whalers never ate this, but they would have approved. Eat before dark: you cannot find crumbs in the dark.", Rare = false },
        new Def { Id = "HamptiSugarShack", Kind = Kind.Snack, Shape = "bag", Mesh = "Hampti", Texture = "HamptiSugarShack", Kg = 0.253f, Kcal = 1310f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хампти Дампти»", En = "Hampti Dampti crisps", RuF = "кленовая сахарная хижина", EnF = "sugar shack maple", RuC = "Канада", EnC = "Canada", Fx = new[] { "SugarDry" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Осталось после чьего-то дня рождения. Гости не пришли. Лучшее, что случится с вами сегодня.", EnJ = "A spring edition: a rare pack from the days when spring still came. Left over from someone's birthday. The guests never came. The best thing that will happen to you today.", Rare = true },
        new Def { Id = "HamptiPumpkin", Kind = Kind.Snack, Shape = "bag", Mesh = "Hampti", Texture = "HamptiPumpkin", Kg = 0.253f, Kcal = 1310f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хампти Дампти»", En = "Hampti Dampti crisps", RuF = "тыквенный пирог", EnF = "pumpkin pie", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Серия к Хэллоуину: редкость. Пугать тут и без неё есть кому. Мерзлота хранит лучше любого холодильника. Для полного счастья не хватает только дивана.", EnJ = "A Halloween edition: a rarity. There is plenty to scare you here without it. Permafrost keeps things better than any fridge. All that is missing for perfect happiness is a sofa.", Rare = true },
        new Def { Id = "HamptiVinegar", Kind = Kind.Snack, Shape = "bag", Mesh = "Hampti", Texture = "HamptiVinegar", Kg = 0.253f, Kcal = 1310f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хампти Дампти»", En = "Hampti Dampti crisps", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Чипсы с яйцом в шляпе: он сидел на стене, а теперь на пачке, тут безопаснее. Такое добывали из автомата, который съедал последнюю монету. Вкус детства, если детство было так себе.", EnJ = "Crisps with an egg in a hat: he sat on a wall, now he sits on a pack, it's safer. These came from the vending machine that ate your last coin. The taste of childhood, if childhood was so-so.", Rare = false },
        new Def { Id = "HamptiOnion", Kind = Kind.Snack, Shape = "bag", Mesh = "Hampti", Texture = "HamptiOnion", Kg = 0.253f, Kcal = 1310f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хампти Дампти»", En = "Hampti Dampti crisps", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Чипсы с яйцом в шляпе: он сидел на стене, а теперь на пачке, тут безопаснее. Такое брали в лодку под брезент, на весь день. Шуршит как надежда.", EnJ = "Crisps with an egg in a hat: he sat on a wall, now he sits on a pack, it's safer. People took these out in the boat under the tarpaulin, for the whole day. It rustles like hope.", Rare = false },
        new Def { Id = "HamptiOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "Hampti", Texture = "HamptiOriginal", Kg = 0.253f, Kcal = 1310f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хампти Дампти»", En = "Hampti Dampti crisps", RuF = "оригинальные", EnF = "original", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Чипсы с яйцом в шляпе: он сидел на стене, а теперь на пачке, тут безопаснее. С ним кто-то шёл к перевалу и не дошёл. Голод отступит, жажда придёт. Честный обмен.", EnJ = "Crisps with an egg in a hat: he sat on a wall, now he sits on a pack, it's safer. Someone carried it towards the pass and never arrived. Hunger leaves, thirst arrives. A fair trade.", Rare = false },
        new Def { Id = "HamptiDill", Kind = Kind.Snack, Shape = "bag", Mesh = "Hampti", Texture = "HamptiDill", Kg = 0.253f, Kcal = 1310f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хампти Дампти»", En = "Hampti Dampti crisps", RuF = "маринованный огурец", EnF = "dill pickle", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Чипсы с яйцом в шляпе: он сидел на стене, а теперь на пачке, тут безопаснее. С таким сидели у окна с видом на метель. Не согреет, зато отвлечёт.", EnJ = "Crisps with an egg in a hat: he sat on a wall, now he sits on a pack, it's safer. People sat with these at a window with a view of the blizzard. It will not warm you, but it will distract you.", Rare = false },
        new Def { Id = "HamptiRoast", Kind = Kind.Snack, Shape = "bag", Mesh = "Hampti", Texture = "HamptiRoast", Kg = 0.253f, Kcal = 1310f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Хампти Дампти»", En = "Hampti Dampti crisps", RuF = "жареная курица", EnF = "roast chicken", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Чипсы с яйцом в шляпе: он сидел на стене, а теперь на пачке, тут безопаснее. Уцелело там, где сгорело всё остальное. Пума предпочитает мясо. Вам повезло.", EnJ = "Crisps with an egg in a hat: he sat on a wall, now he sits on a pack, it's safer. It survived where everything else burned. The cougar prefers meat. Lucky you.", Rare = false },
        new Def { Id = "KoverdSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "Koverd", Texture = "KoverdSalt", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Коверд Бридж»", En = "Koverd Bridj crisps", RuF = "морская соль", EnF = "sea salt", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из Нью-Брансуика: красная картошка и крытый мост на пачке. Этим кормили сторожевого пса. Пёс ушёл в волки. Сначала попробуйте одну штучку. Шутка: ешьте всё.", EnJ = "Crisps from New Brunswick: red potatoes and a covered bridge on the pack. They fed the guard dog with this. The dog joined the wolves. Try just one first. Joke: eat the lot.", Rare = false },
        new Def { Id = "KoverdStorm", Kind = Kind.Snack, Shape = "bag", Mesh = "Koverd", Texture = "KoverdStorm", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Коверд Бридж»", En = "Koverd Bridj crisps", RuF = "штормовые: всё сразу", EnF = "storm chips", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из Нью-Брансуика: красная картошка и крытый мост на пачке. Из запасов лесорубов: брали ящиками. Такой ужин не стыдно записать в дневник.", EnJ = "Crisps from New Brunswick: red potatoes and a covered bridge on the pack. From the loggers' stores: they bought it by the crate. A dinner worth writing in the journal.", Rare = false },
        new Def { Id = "KoverdDill", Kind = Kind.Snack, Shape = "bag", Mesh = "Koverd", Texture = "KoverdDill", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Коверд Бридж»", En = "Koverd Bridj crisps", RuF = "сливочный укроп", EnF = "creamy dill", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из Нью-Брансуика: красная картошка и крытый мост на пачке. В пост такое не ели. Пост кончился вместе с миром. Силы прибавит на один сугроб.", EnJ = "Crisps from New Brunswick: red potatoes and a covered bridge on the pack. Nobody ate these during a fast. The fast ended with the world. It will carry you one snowdrift further.", Rare = false },
        new Def { Id = "KoverdBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Koverd", Texture = "KoverdBBQ", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Коверд Бридж»", En = "Koverd Bridj crisps", RuF = "сладкое копчёное барбекю", EnF = "smokin sweet bbq", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из Нью-Брансуика: красная картошка и крытый мост на пачке. Теперь это ценнее денег. Деньги оставьте. Идеально к закату, которого не видно за бураном.", EnJ = "Crisps from New Brunswick: red potatoes and a covered bridge on the pack. It is worth more than money now. Leave the money. Perfect with a sunset you cannot see for the storm.", Rare = false },
        new Def { Id = "KoverdWinter", Kind = Kind.Snack, Shape = "bag", Mesh = "Koverd", Texture = "KoverdWinter", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Коверд Бридж»", En = "Koverd Bridj crisps", RuF = "зимний шторм", EnF = "winter storm", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Зимняя серия: выпускали на один сезон, а зима тут навсегда. Его несли на пикник. Пикник отменили навсегда. Пахнет магазином. Помните магазины?", EnJ = "A winter edition: made for one season, and here winter is forever. It was headed for a picnic. The picnic is cancelled forever. It smells of a shop. Remember shops?", Rare = true },
        new Def { Id = "KoverdMaple", Kind = Kind.Snack, Shape = "bag", Mesh = "Koverd", Texture = "KoverdMaple", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Коверд Бридж»", En = "Koverd Bridj crisps", RuF = "кленовый бекон", EnF = "maple bacon", RuC = "Канада", EnC = "Canada", Fx = new[] { "SugarDry" }, RuJ = "Чипсы из Нью-Брансуика: красная картошка и крытый мост на пачке. Такое стояло у кассы на случай слабости. Мороз не испортил, время не взяло.", EnJ = "Crisps from New Brunswick: red potatoes and a covered bridge on the pack. These stood by the till for moments of weakness. Frost did not spoil it and time could not take it.", Rare = false },
        new Def { Id = "KoverdLobster", Kind = Kind.Snack, Shape = "bag", Mesh = "Koverd", Texture = "KoverdLobster", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Коверд Бридж»", En = "Koverd Bridj crisps", RuF = "лобстер", EnF = "lobster", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из Нью-Брансуика: красная картошка и крытый мост на пачке. Досталось вам, потому что вы дошли первым. В рюкзаке не мнётся. Почти.", EnJ = "Crisps from New Brunswick: red potatoes and a covered bridge on the pack. It is yours because you got here first. It does not get crushed in a pack. Almost.", Rare = false },
        new Def { Id = "KoverdJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "Koverd", Texture = "KoverdJalapeno", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Коверд Бридж»", En = "Koverd Bridj crisps", RuF = "халапеньо", EnF = "jalapeno", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Чипсы из Нью-Брансуика: красная картошка и крытый мост на пачке. Упаковка выцвела, внутри время остановилось. Съешьте сейчас: завтра может не быть аппетита.", EnJ = "Crisps from New Brunswick: red potatoes and a covered bridge on the pack. The wrapper has faded; inside, time stood still. Eat it now: tomorrow you may have no appetite.", Rare = false },
        new Def { Id = "KoverdVinegar", Kind = Kind.Snack, Shape = "bag", Mesh = "Koverd", Texture = "KoverdVinegar", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Коверд Бридж»", En = "Koverd Bridj crisps", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из Нью-Брансуика: красная картошка и крытый мост на пачке. Из чемодана пассажира, который не долетел. Хватит дойти до следующей хижины и пожалеть, что кончилось.", EnJ = "Crisps from New Brunswick: red potatoes and a covered bridge on the pack. From the suitcase of a passenger who never landed. Enough to reach the next cabin and regret it is gone.", Rare = false },
        new Def { Id = "KoverdPepper", Kind = Kind.Snack, Shape = "bag", Mesh = "Koverd", Texture = "KoverdPepper", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Коверд Бридж»", En = "Koverd Bridj crisps", RuF = "чёрный перец", EnF = "cracked pepper", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из Нью-Брансуика: красная картошка и крытый мост на пачке. Перезимовало и ничуть не обиделось. От такого не толстеют те, кто ходит по двадцать километров.", EnJ = "Crisps from New Brunswick: red potatoes and a covered bridge on the pack. It made it through the winter and bears no grudge. Nobody who walks twenty kilometres a day gets fat on this.", Rare = false },
        new Def { Id = "YamYamNature", Kind = Kind.Snack, Shape = "bag", Mesh = "YamYam", Texture = "YamYamNature", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Ям Ям»", En = "Yam Yam crisps", RuF = "с солью", EnF = "plain", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Квебекские чипсы: название читается так, как звучит человек с набитым ртом. Запасливая хозяйка купила по акции шесть штук. Волчья стая не в курсе. Пусть так и будет.", EnJ = "Québec crisps: the name reads the way a person with a full mouth sounds. A thrifty housewife bought six of these on offer. The wolf pack does not know. Keep it that way.", Rare = false },
        new Def { Id = "YamYamKetchup", Kind = Kind.Snack, Shape = "bag", Mesh = "YamYam", Texture = "YamYamKetchup", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Ям Ям»", En = "Yam Yam crisps", RuF = "кетчуп", EnF = "ketchup", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Квебекские чипсы: название читается так, как звучит человек с набитым ртом. Кто-то написал на упаковке «моё». Уже нет. Хрустеть в засаде не рекомендуется.", EnJ = "Québec crisps: the name reads the way a person with a full mouth sounds. Someone wrote 'mine' on it. Not any more. Crunching in an ambush is not recommended.", Rare = false },
        new Def { Id = "YamYamVinaigre", Kind = Kind.Snack, Shape = "bag", Mesh = "YamYam", Texture = "YamYamVinaigre", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Ям Ям»", En = "Yam Yam crisps", RuF = "уксус", EnF = "vinegar", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Квебекские чипсы: название читается так, как звучит человек с набитым ртом. В консервном цеху это ели тайком от мастера. Лекарство от тоски, отпускается без рецепта.", EnJ = "Québec crisps: the name reads the way a person with a full mouth sounds. At the cannery they ate this behind the foreman's back. A cure for the blues, no prescription needed.", Rare = false },
        new Def { Id = "YamYamBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "YamYam", Texture = "YamYamBBQ", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Ям Ям»", En = "Yam Yam crisps", RuF = "барбекю", EnF = "barbecue", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Квебекские чипсы: название читается так, как звучит человек с набитым ртом. Его не взяли даже мародёры. Они спешили. Жуйте и думайте о хорошем. Например, о добавке.", EnJ = "Québec crisps: the name reads the way a person with a full mouth sounds. Even the looters left it. They were in a hurry. Chew and think of nice things. Seconds, for example.", Rare = false },
        new Def { Id = "YamYamPoutine", Kind = Kind.Snack, Shape = "bag", Mesh = "YamYam", Texture = "YamYamPoutine", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Ям Ям»", En = "Yam Yam crisps", RuF = "путин", EnF = "poutine", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Квебекские чипсы: название читается так, как звучит человек с набитым ртом. Провело зиму на острове, как и вы. К утру от него останется только запах на варежках.", EnJ = "Québec crisps: the name reads the way a person with a full mouth sounds. It spent the winter on the island, same as you. By morning only the smell on your mittens will be left.", Rare = false },
        new Def { Id = "YamYamFines", Kind = Kind.Snack, Shape = "bag", Mesh = "YamYam", Texture = "YamYamFines", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Ям Ям»", En = "Yam Yam crisps", RuF = "сметана и зелень", EnF = "sour cream & herbs", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Квебекские чипсы: название читается так, как звучит человек с набитым ртом. Дети прятали такое под кроватью, в тайнике. Тишина вокруг такая, что слышно, как вы жуёте.", EnJ = "Québec crisps: the name reads the way a person with a full mouth sounds. Children hid these under the bed, in a secret place. It is so quiet you can hear yourself chew.", Rare = false },
        new Def { Id = "YamYamCornichon", Kind = Kind.Snack, Shape = "bag", Mesh = "YamYam", Texture = "YamYamCornichon", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Ям Ям»", En = "Yam Yam crisps", RuF = "корнишоны", EnF = "dill pickle", RuC = "Канада", EnC = "Canada", Fx = new[] { "SaltHold" }, RuJ = "Квебекские чипсы: название читается так, как звучит человек с набитым ртом. Осталось от геологов вместе с картой и долгами. Не делите на завтра: завтра будет новый голод.", EnJ = "Québec crisps: the name reads the way a person with a full mouth sounds. Left by the geologists along with a map and some debts. Do not save half for tomorrow: tomorrow brings its own hunger.", Rare = false },
        new Def { Id = "NashaSour", Kind = Kind.Snack, Shape = "bag", Mesh = "Nasha", Texture = "NashaSour", Kg = 0.088f, Kcal = 430f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Наша картошка»", En = "Nasha Kartoshka crisps", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold" }, RuJ = "«Наша картошка»: чья именно, на пачке не уточняется. На острове такое было праздником и до катастрофы. Сосны вокруг делают вид, что не смотрят.", EnJ = "‘Our Potato’: the pack doesn't say whose exactly. On the island this was a treat even before the disaster. The pines around pretend not to watch.", Rare = false },
        new Def { Id = "NashaBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Nasha", Texture = "NashaBacon", Kg = 0.088f, Kcal = 430f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Наша картошка»", En = "Nasha Kartoshka crisps", RuF = "бекон", EnF = "bacon", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold" }, RuJ = "«Наша картошка»: чья именно, на пачке не уточняется. С таким слушали радио, которое теперь ловит только треск. Калории мелкие, зато свои.", EnJ = "‘Our Potato’: the pack doesn't say whose exactly. People ate these by the radio, which picks up nothing but crackle now. Small calories, but your own.", Rare = false },
        new Def { Id = "NashaCrab", Kind = Kind.Snack, Shape = "bag", Mesh = "Nasha", Texture = "NashaCrab", Kg = 0.088f, Kcal = 430f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Наша картошка»", En = "Nasha Kartoshka crisps", RuF = "краб", EnF = "crab", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold" }, RuJ = "«Наша картошка»: чья именно, на пачке не уточняется. Крысы прогрызли соседнюю, эту пощадили. После этого даже крапивный чай покажется десертом.", EnJ = "‘Our Potato’: the pack doesn't say whose exactly. The rats gnawed through the one next to it and spared this. After this even nettle tea feels like dessert.", Rare = false },
        new Def { Id = "NashaCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Nasha", Texture = "NashaCheese", Kg = 0.088f, Kcal = 430f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Наша картошка»", En = "Nasha Kartoshka crisps", RuF = "сыр", EnF = "cheese", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold" }, RuJ = "«Наша картошка»: чья именно, на пачке не уточняется. Бывший хозяин клялся бросить. Не успел. Нашедшему полагается всё.", EnJ = "‘Our Potato’: the pack doesn't say whose exactly. The former owner swore to give these up. He ran out of time. Finders keepers, all of it.", Rare = false },
        new Def { Id = "NashaDacha", Kind = Kind.Snack, Shape = "bag", Mesh = "Nasha", Texture = "NashaDacha", Kg = 0.088f, Kcal = 430f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Наша картошка»", En = "Nasha Kartoshka crisps", RuF = "дачный шашлык", EnF = "dacha shashlik", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Его катали в кабине трактора три сезона. Зубы целы? Тогда вперёд.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. It rode around in a tractor cab for three seasons. Teeth intact? Then go ahead.", Rare = true },
        new Def { Id = "NashaOlivier", Kind = Kind.Snack, Shape = "bag", Mesh = "Nasha", Texture = "NashaOlivier", Kg = 0.088f, Kcal = 430f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Наша картошка»", En = "Nasha Kartoshka crisps", RuF = "оливье", EnF = "olivier salad", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold" }, RuJ = "Новогодняя серия: куранты отбили, а пачка осталась. Редкость. После бани такое шло лучше всего. Ночью приснится добавка.", EnJ = "A New Year edition: the clock has struck, the pack remains. A rarity. Nothing went down better after the sauna. Tonight you will dream of seconds.", Rare = true },
        new Def { Id = "NashaDill", Kind = Kind.Snack, Shape = "bag", Mesh = "Nasha", Texture = "NashaDill", Kg = 0.088f, Kcal = 430f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Наша картошка»", En = "Nasha Kartoshka crisps", RuF = "укроп", EnF = "dill", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold" }, RuJ = "«Наша картошка»: чья именно, на пачке не уточняется. В тюрьме на это выменивали что угодно. С таким запасом можно пережить ещё один вечер.", EnJ = "‘Our Potato’: the pack doesn't say whose exactly. In the prison you could trade one of these for anything. With supplies like this you can survive one more evening.", Rare = false },
        new Def { Id = "NashaShashlik", Kind = Kind.Snack, Shape = "bag", Mesh = "Nasha", Texture = "NashaShashlik", Kg = 0.088f, Kcal = 430f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Наша картошка»", En = "Nasha Kartoshka crisps", RuF = "шашлык", EnF = "shashlik", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold" }, RuJ = "«Наша картошка»: чья именно, на пачке не уточняется. Кто-то менял это на сигареты. Сделка сорвалась. Пёс бы выпросил половину. Пса нет.", EnJ = "‘Our Potato’: the pack doesn't say whose exactly. Someone was trading this for cigarettes. The deal fell through. A dog would beg half of it. There is no dog.", Rare = false },
        new Def { Id = "NashaMushroom", Kind = Kind.Snack, Shape = "bag", Mesh = "Nasha", Texture = "NashaMushroom", Kg = 0.088f, Kcal = 430f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Наша картошка»", En = "Nasha Kartoshka crisps", RuF = "грибы", EnF = "mushroom", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold" }, RuJ = "«Наша картошка»: чья именно, на пачке не уточняется. С ним зимовали на метеостанции, пока было с кем. Съедено будет быстрее, чем найдено.", EnJ = "‘Our Potato’: the pack doesn't say whose exactly. They wintered with it at the weather station, while there was a 'they'. It will be eaten faster than it was found.", Rare = false },
        new Def { Id = "NashaSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "Nasha", Texture = "NashaSalt", Kg = 0.088f, Kcal = 430f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Наша картошка»", En = "Nasha Kartoshka crisps", RuF = "соль", EnF = "salted", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold" }, RuJ = "«Наша картошка»: чья именно, на пачке не уточняется. Такое терялось в кладовке среди крупы и надежд. На вкус как выходной.", EnJ = "‘Our Potato’: the pack doesn't say whose exactly. These got lost in the pantry among the grain and the hopes. It tastes like a day off.", Rare = false },
        new Def { Id = "NashaPickle", Kind = Kind.Snack, Shape = "bag", Mesh = "Nasha", Texture = "NashaPickle", Kg = 0.088f, Kcal = 430f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Наша картошка»", En = "Nasha Kartoshka crisps", RuF = "солёный огурец", EnF = "pickle", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold" }, RuJ = "«Наша картошка»: чья именно, на пачке не уточняется. Его берегли к приезду внуков. Ветер унесёт запах прямо к берлоге. Ешьте быстрее.", EnJ = "‘Our Potato’: the pack doesn't say whose exactly. It was being saved for the grandchildren's visit. The wind carries the smell straight to the den. Eat faster.", Rare = false },
        new Def { Id = "NashaPaprika", Kind = Kind.Snack, Shape = "bag", Mesh = "Nasha", Texture = "NashaPaprika", Kg = 0.088f, Kcal = 430f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Наша картошка»", En = "Nasha Kartoshka crisps", RuF = "паприка", EnF = "paprika", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold" }, RuJ = "«Наша картошка»: чья именно, на пачке не уточняется. В баре такое ставили на стойку, бесплатно к пиву. Пива нет. Пополняет запас соли и веры в человечество.", EnJ = "‘Our Potato’: the pack doesn't say whose exactly. Bars put these out free with a beer. There is no beer. Restores your salt and your faith in mankind.", Rare = false },
        new Def { Id = "SukhoplavVobla", Kind = Kind.Snack, Shape = "bag", Mesh = "Sukhoplav", Texture = "SukhoplavVobla", Kg = 0.078f, Kcal = 180f, Thirst = -10f, Eat = 8f, Ru = "Сушёная рыба «Сухоплав»", En = "Sukhoplav dried fish", RuF = "вобла", EnF = "roach", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Сушёная рыбка: пахнет так, что в электричке вам уступят весь вагон. Такое лежало в каждом доме, пока не погас свет. Хорошо идёт под треск поленьев.", EnJ = "Dried fish: it smells so that a commuter train will give you the whole carriage. Every house had one of these until the lights went out. Goes down well with crackling logs.", Rare = false },
        new Def { Id = "SukhoplavSmelt", Kind = Kind.Snack, Shape = "bag", Mesh = "Sukhoplav", Texture = "SukhoplavSmelt", Kg = 0.078f, Kcal = 180f, Thirst = -10f, Eat = 8f, Ru = "Сушёная рыба «Сухоплав»", En = "Sukhoplav dried fish", RuF = "корюшка", EnF = "smelt", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Сушёная рыбка: пахнет так, что в электричке вам уступят весь вагон. Кто-то берёг это на чёрный день. Он настал. Руки вытирать о штаны: салфеток не завезли.", EnJ = "Dried fish: it smells so that a commuter train will give you the whole carriage. Someone saved this for a rainy day. It came. Wipe your hands on your trousers: no napkins were delivered.", Rare = false },
        new Def { Id = "SukhoplavRings", Kind = Kind.Snack, Shape = "bag", Mesh = "Sukhoplav", Texture = "SukhoplavRings", Kg = 0.078f, Kcal = 180f, Thirst = -10f, Eat = 8f, Ru = "Сушёная рыба «Сухоплав»", En = "Sukhoplav dried fish", RuF = "кольца кальмара", EnF = "squid rings", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Сушёная рыбка: пахнет так, что в электричке вам уступят весь вагон. Пережило хозяина, кота и две зимы. Маленькая радость размером с ладонь.", EnJ = "Dried fish: it smells so that a commuter train will give you the whole carriage. It outlived its owner, the cat and two winters. A small joy the size of your palm.", Rare = false },
        new Def { Id = "SukhoplavPike", Kind = Kind.Snack, Shape = "bag", Mesh = "Sukhoplav", Texture = "SukhoplavPike", Kg = 0.078f, Kcal = 180f, Thirst = -10f, Eat = 8f, Ru = "Сушёная рыба «Сухоплав»", En = "Sukhoplav dried fish", RuF = "щучка", EnF = "pike straws", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Сушёная рыбка: пахнет так, что в электричке вам уступят весь вагон. Такое обычно находили за диваном, как всё лучшее в жизни. Совесть молчит, живот поёт.", EnJ = "Dried fish: it smells so that a commuter train will give you the whole carriage. These were usually found behind the sofa, like all the best things in life. Conscience is silent, the belly sings.", Rare = false },
        new Def { Id = "SukhoplavBream", Kind = Kind.Snack, Shape = "bag", Mesh = "Sukhoplav", Texture = "SukhoplavBream", Kg = 0.078f, Kcal = 180f, Thirst = -10f, Eat = 8f, Ru = "Сушёная рыба «Сухоплав»", En = "Sukhoplav dried fish", RuF = "лещ", EnF = "bream", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Сушёная рыбка: пахнет так, что в электричке вам уступят весь вагон. Последний завоз был до того, как упали самолёты. Проверено поколениями и одной катастрофой.", EnJ = "Dried fish: it smells so that a commuter train will give you the whole carriage. The last delivery came before the planes fell. Tested by generations and one catastrophe.", Rare = false },
        new Def { Id = "SukhoplavPerch", Kind = Kind.Snack, Shape = "bag", Mesh = "Sukhoplav", Texture = "SukhoplavPerch", Kg = 0.078f, Kcal = 180f, Thirst = -10f, Eat = 8f, Ru = "Сушёная рыба «Сухоплав»", En = "Sukhoplav dried fish", RuF = "окунь", EnF = "perch", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Сушёная рыбка: пахнет так, что в электричке вам уступят весь вагон. Ценник оторван: теперь это бесценно. Оставьте пару штук на перевал. Не оставите.", EnJ = "Dried fish: it smells so that a commuter train will give you the whole carriage. The price tag is torn off: it is priceless now. Save a couple for the pass. You will not.", Rare = false },
        new Def { Id = "SukhoplavAnchovy", Kind = Kind.Snack, Shape = "bag", Mesh = "Sukhoplav", Texture = "SukhoplavAnchovy", Kg = 0.078f, Kcal = 180f, Thirst = -10f, Eat = 8f, Ru = "Сушёная рыба «Сухоплав»", En = "Sukhoplav dried fish", RuF = "анчоус", EnF = "anchovy", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Сушёная рыбка: пахнет так, что в электричке вам уступят весь вагон. Дата на шве стёрлась, и слава богу. Здесь это считается ужином при свечах.", EnJ = "Dried fish: it smells so that a commuter train will give you the whole carriage. The date on the seam has rubbed off, thank goodness. Round here this counts as a candlelit dinner.", Rare = false },
        new Def { Id = "SukhoplavStraw", Kind = Kind.Snack, Shape = "bag", Mesh = "Sukhoplav", Texture = "SukhoplavStraw", Kg = 0.078f, Kcal = 180f, Thirst = -10f, Eat = 8f, Ru = "Сушёная рыба «Сухоплав»", En = "Sukhoplav dried fish", RuF = "рыбная соломка", EnF = "fish straws", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Сушёная рыбка: пахнет так, что в электричке вам уступят весь вагон. Пахнет заправкой у Прибрежного шоссе. Луна светит, еда хрустит, жизнь налаживается.", EnJ = "Dried fish: it smells so that a commuter train will give you the whole carriage. It smells of the petrol station on the Coastal Highway. The moon shines, the food crunches, life is looking up.", Rare = false },
        new Def { Id = "SukhoplavRoach", Kind = Kind.Snack, Shape = "bag", Mesh = "Sukhoplav", Texture = "SukhoplavRoach", Kg = 0.078f, Kcal = 180f, Thirst = -10f, Eat = 8f, Ru = "Сушёная рыба «Сухоплав»", En = "Sukhoplav dried fish", RuF = "тарань", EnF = "azov roach", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Сушёная рыбка: пахнет так, что в электричке вам уступят весь вагон. Такое возили в бардачке на дальнюю дорогу. Дороги кончились. Снег вокруг не солёный. Это солёное.", EnJ = "Dried fish: it smells so that a commuter train will give you the whole carriage. People kept these in the glovebox for long drives. The drives are over. The snow around is not salty. This is.", Rare = false },
        new Def { Id = "SukhoplavGoby", Kind = Kind.Snack, Shape = "bag", Mesh = "Sukhoplav", Texture = "SukhoplavGoby", Kg = 0.078f, Kcal = 180f, Thirst = -10f, Eat = 8f, Ru = "Сушёная рыба «Сухоплав»", En = "Sukhoplav dried fish", RuF = "бычок", EnF = "goby", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Сушёная рыбка: пахнет так, что в электричке вам уступят весь вагон. Мыши не тронули. Думайте сами. Больше таких не делают. Совсем.", EnJ = "Dried fish: it smells so that a commuter train will give you the whole carriage. The mice left it alone. Draw your own conclusions. They do not make these any more. At all.", Rare = false },
        new Def { Id = "BlyuzPistachio", Kind = Kind.Snack, Shape = "bag", Mesh = "Blyuz", Texture = "BlyuzPistachio", Kg = 0.138f, Kcal = 780f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Блюз»", En = "Blyuz nuts", RuF = "фисташки", EnF = "pistachios", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Орешки «Блюз»: солёные, как песня про ушедший поезд. Рыбаки брали такое на лёд вместо обеда. Открывайте тихо: у волков отличный слух.", EnJ = "‘Blues’ nuts: salty as a song about a train that left. Fishermen took this onto the ice instead of lunch. Open it quietly: wolves have excellent hearing.", Rare = false },
        new Def { Id = "BlyuzAlmond", Kind = Kind.Snack, Shape = "bag", Mesh = "Blyuz", Texture = "BlyuzAlmond", Kg = 0.138f, Kcal = 780f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Блюз»", En = "Blyuz nuts", RuF = "миндаль", EnF = "almonds", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Орешки «Блюз»: солёные, как песня про ушедший поезд. Смотритель плотины держал такое в заначке. Одной не обойдётся, но вторая неизвестно где.", EnJ = "‘Blues’ nuts: salty as a song about a train that left. The dam keeper kept a stash of these. One won't be enough, and nobody knows where the second is.", Rare = false },
        new Def { Id = "BlyuzCashew", Kind = Kind.Snack, Shape = "bag", Mesh = "Blyuz", Texture = "BlyuzCashew", Kg = 0.138f, Kcal = 780f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Блюз»", En = "Blyuz nuts", RuF = "кешью", EnF = "cashews", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Орешки «Блюз»: солёные, как песня про ушедший поезд. Кто-то спрятал это от детей. Дети не нашли. Крошки с пола тоже считаются.", EnJ = "‘Blues’ nuts: salty as a song about a train that left. Someone hid it from the kids. The kids never found it. The crumbs on the floor count too.", Rare = false },
        new Def { Id = "BlyuzHazelnut", Kind = Kind.Snack, Shape = "bag", Mesh = "Blyuz", Texture = "BlyuzHazelnut", Kg = 0.138f, Kcal = 780f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Блюз»", En = "Blyuz nuts", RuF = "фундук", EnF = "hazelnuts", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Орешки «Блюз»: солёные, как песня про ушедший поезд. В сельском магазине такое вечно заваливалось за прилавок. Запейте чаем из шиповника и считайте это обедом.", EnJ = "‘Blues’ nuts: salty as a song about a train that left. In the village shop these kept slipping behind the counter. Wash it down with rosehip tea and call it lunch.", Rare = false },
        new Def { Id = "BlyuzPeanut", Kind = Kind.Snack, Shape = "bag", Mesh = "Blyuz", Texture = "BlyuzPeanut", Kg = 0.138f, Kcal = 780f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Блюз»", En = "Blyuz nuts", RuF = "арахис", EnF = "peanuts", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Орешки «Блюз»: солёные, как песня про ушедший поезд. Ждало покупателя дольше, чем тот прожил. Медведю не показывать: отнимет вместе с рукой.", EnJ = "‘Blues’ nuts: salty as a song about a train that left. It waited for a buyer longer than the buyer lived. Do not show the bear: he will take it, hand and all.", Rare = false },
        new Def { Id = "BlyuzWalnut", Kind = Kind.Snack, Shape = "bag", Mesh = "Blyuz", Texture = "BlyuzWalnut", Kg = 0.138f, Kcal = 780f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Блюз»", En = "Blyuz nuts", RuF = "грецкий орех", EnF = "walnuts", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Орешки «Блюз»: солёные, как песня про ушедший поезд. С материка такое больше не привезут. Диетолог не одобрил бы. Диетолога тут нет.", EnJ = "‘Blues’ nuts: salty as a song about a train that left. Nobody will bring this from the mainland again. A dietitian would not approve. There is no dietitian here.", Rare = false },
        new Def { Id = "BlyuzCedar", Kind = Kind.Snack, Shape = "bag", Mesh = "Blyuz", Texture = "BlyuzCedar", Kg = 0.138f, Kcal = 780f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Блюз»", En = "Blyuz nuts", RuF = "кедровый орех", EnF = "pine nuts", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Орешки «Блюз»: солёные, как песня про ушедший поезд. На упаковке иней, внутри всё по-прежнему. Лучше, чем кора. Проверено.", EnJ = "‘Blues’ nuts: salty as a song about a train that left. Frost on the wrapper, business as usual inside. Better than bark. Tested.", Rare = false },
        new Def { Id = "BlyuzMix", Kind = Kind.Snack, Shape = "bag", Mesh = "Blyuz", Texture = "BlyuzMix", Kg = 0.138f, Kcal = 780f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Блюз»", En = "Blyuz nuts", RuF = "ореховая смесь", EnF = "nut mix", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Орешки «Блюз»: солёные, как песня про ушедший поезд. Мороз ему нипочём: твёрже не стало, мягче тоже. Хруст разносится до соседней долины.", EnJ = "‘Blues’ nuts: salty as a song about a train that left. The frost did nothing to it: no harder, no softer. The crunch carries to the next valley.", Rare = false },
        new Def { Id = "BlyuzMacadamia", Kind = Kind.Snack, Shape = "bag", Mesh = "Blyuz", Texture = "BlyuzMacadamia", Kg = 0.138f, Kcal = 780f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Блюз»", En = "Blyuz nuts", RuF = "макадамия", EnF = "macadamia", RuC = "Россия", EnC = "Russia", Fx = new[] { "Sinew" }, RuJ = "Орешки «Блюз»: солёные, как песня про ушедший поезд. Из тех времён, когда еду выбирали по вкусу. Ешьте медленно: когда ещё такое найдёте.", EnJ = "‘Blues’ nuts: salty as a song about a train that left. From the days when people picked food for its taste. Eat slowly: who knows when you will find another.", Rare = false },
        new Def { Id = "KupecheskieRaisin", Kind = Kind.Snack, Shape = "bag", Mesh = "Kupecheskie", Texture = "KupecheskieRaisin", Kg = 0.258f, Kcal = 980f, Thirst = -3f, Eat = 5f, Ru = "Сухари «Купеческие»", En = "Kupecheskie sweet rusks", RuF = "с изюмом", EnF = "with raisins", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Купеческие сухари: их макали в чай из блюдца, степенно, как положено. Чей-то перекус на ночную смену, которая не кончилась. Упаковку не выбрасывайте: ею можно разжечь печь.", EnJ = "Merchant rusks: dunked in tea from the saucer, sedately, as is proper. Someone's snack for a night shift that never ended. Keep the wrapper: it will light the stove.", Rare = false },
        new Def { Id = "KupecheskiePoppy", Kind = Kind.Snack, Shape = "bag", Mesh = "Kupecheskie", Texture = "KupecheskiePoppy", Kg = 0.258f, Kcal = 980f, Thirst = -3f, Eat = 5f, Ru = "Сухари «Купеческие»", En = "Kupecheskie sweet rusks", RuF = "с маком", EnF = "with poppy seeds", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Купеческие сухари: их макали в чай из блюдца, степенно, как положено. В охотничьей вышке таким встречали рассвет. Сияние на вкус не влияет. Наверное.", EnJ = "Merchant rusks: dunked in tea from the saucer, sedately, as is proper. In the hunting blind they met the dawn with this. The aurora does not affect the taste. Probably.", Rare = false },
        new Def { Id = "KupecheskieVanilla", Kind = Kind.Snack, Shape = "bag", Mesh = "Kupecheskie", Texture = "KupecheskieVanilla", Kg = 0.258f, Kcal = 980f, Thirst = -3f, Eat = 5f, Ru = "Сухари «Купеческие»", En = "Kupecheskie sweet rusks", RuF = "ванильные", EnF = "vanilla", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Купеческие сухари: их макали в чай из блюдца, степенно, как положено. Такое носили в кармане куртки на всякий случай. Случай настал. После тушёнки из банки это почти ресторан.", EnJ = "Merchant rusks: dunked in tea from the saucer, sedately, as is proper. People carried these in a coat pocket just in case. The case has come. After stew from a tin this is nearly a restaurant.", Rare = false },
        new Def { Id = "KupecheskieSugar", Kind = Kind.Snack, Shape = "bag", Mesh = "Kupecheskie", Texture = "KupecheskieSugar", Kg = 0.258f, Kcal = 980f, Thirst = -3f, Eat = 5f, Ru = "Сухари «Купеческие»", En = "Kupecheskie sweet rusks", RuF = "сахарные", EnF = "sugared", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Купеческие сухари: их макали в чай из блюдца, степенно, как положено. Прежний хозяин оставил записку: «Не трогать». Записка сгорела. Делиться не с кем, и это впервые радует.", EnJ = "Merchant rusks: dunked in tea from the saucer, sedately, as is proper. The last owner left a note: 'Do not touch'. The note burned. Nobody to share with, and for once that is good news.", Rare = false },
        new Def { Id = "KupecheskieCream", Kind = Kind.Snack, Shape = "bag", Mesh = "Kupecheskie", Texture = "KupecheskieCream", Kg = 0.258f, Kcal = 980f, Thirst = -3f, Eat = 5f, Ru = "Сухари «Купеческие»", En = "Kupecheskie sweet rusks", RuF = "сливочные", EnF = "cream", RuC = "Россия", EnC = "Russia", Fx = new[] { "SugarDry" }, RuJ = "Купеческие сухари: их макали в чай из блюдца, степенно, как положено. Такими торговали в поезде, пока поезд ходил. Пальцы потом оближите: зимой калории не выбрасывают.", EnJ = "Merchant rusks: dunked in tea from the saucer, sedately, as is proper. They sold these on the train, while the train ran. Lick your fingers after: in winter you do not waste calories.", Rare = false },
        new Def { Id = "KupecheskieMustard", Kind = Kind.Snack, Shape = "bag", Mesh = "Kupecheskie", Texture = "KupecheskieMustard", Kg = 0.258f, Kcal = 980f, Thirst = -3f, Eat = 5f, Ru = "Сухари «Купеческие»", En = "Kupecheskie sweet rusks", RuF = "горчичные", EnF = "mustard", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Купеческие сухари: их макали в чай из блюдца, степенно, как положено. Сторож шахты держал такое в ящике стола. Ворон на ветке уже ждёт свою долю.", EnJ = "Merchant rusks: dunked in tea from the saucer, sedately, as is proper. The mine watchman kept these in his desk drawer. The crow on the branch is already waiting for its share.", Rare = false },
        new Def { Id = "KupecheskieNut", Kind = Kind.Snack, Shape = "bag", Mesh = "Kupecheskie", Texture = "KupecheskieNut", Kg = 0.258f, Kcal = 980f, Thirst = -3f, Eat = 5f, Ru = "Сухари «Купеческие»", En = "Kupecheskie sweet rusks", RuF = "ореховые", EnF = "nut", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Купеческие сухари: их макали в чай из блюдца, степенно, как положено. Лавина прошла мимо, срок годности тоже. На морозе хрустит вдвое громче.", EnJ = "Merchant rusks: dunked in tea from the saucer, sedately, as is proper. The avalanche missed it, and so did the best-before date. In the frost it crunches twice as loud.", Rare = false },
        new Def { Id = "KupecheskieCranberry", Kind = Kind.Snack, Shape = "bag", Mesh = "Kupecheskie", Texture = "KupecheskieCranberry", Kg = 0.258f, Kcal = 980f, Thirst = -3f, Eat = 5f, Ru = "Сухари «Купеческие»", En = "Kupecheskie sweet rusks", RuF = "с клюквой", EnF = "cranberry", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Купеческие сухари: их макали в чай из блюдца, степенно, как положено. Такое всегда стояло на видном месте, поэтому никто не брал. Не еда, а настроение. Настроение тоже греет.", EnJ = "Merchant rusks: dunked in tea from the saucer, sedately, as is proper. These always stood in plain sight, which is why nobody took them. Not food but a mood. A mood warms you too.", Rare = false },
        new Def { Id = "KupecheskieRye", Kind = Kind.Snack, Shape = "bag", Mesh = "Kupecheskie", Texture = "KupecheskieRye", Kg = 0.258f, Kcal = 980f, Thirst = -3f, Eat = 5f, Ru = "Сухари «Купеческие»", En = "Kupecheskie sweet rusks", RuF = "ржаные", EnF = "rye", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Купеческие сухари: их макали в чай из блюдца, степенно, как положено. Кто-то открыл, передумал и умер. Не связано. Сытости на час, воспоминаний на неделю.", EnJ = "Merchant rusks: dunked in tea from the saucer, sedately, as is proper. Someone opened it, changed their mind and died. Unrelated. An hour of fullness, a week of memories.", Rare = false },
        new Def { Id = "YuzhnayaNochSugar", Kind = Kind.Snack, Shape = "carton", Mesh = "YuzhnayaNoch", Texture = "YuzhnayaNochSugar", Kg = 0.158f, Kcal = 720f, Thirst = -2f, Eat = 5f, Ru = "Драже «Южная ночь»", En = "Yuzhnaya Noch coated peanuts", RuF = "арахис в сахаре", EnF = "sugared peanuts", RuC = "СССР", EnC = "USSR", Fx = new[] { "SugarDry" }, RuJ = "Драже «Южная ночь»: арахис в шоколаде и тёплое море на крышке. Такое вечно каталось под сиденьем пикапа. Кролик смотрит с осуждением.", EnJ = "‘Southern Night’ dragée: peanuts in chocolate and a warm sea on the lid. One of these was always rolling under a pickup seat. The rabbit looks on with disapproval.", Rare = false },
        new Def { Id = "YuzhnayaNochCocoa", Kind = Kind.Snack, Shape = "carton", Mesh = "YuzhnayaNoch", Texture = "YuzhnayaNochCocoa", Kg = 0.158f, Kcal = 720f, Thirst = -2f, Eat = 5f, Ru = "Драже «Южная ночь»", En = "Yuzhnaya Noch coated peanuts", RuF = "арахис в какао", EnF = "cocoa peanuts", RuC = "СССР", EnC = "USSR", Fx = new[] { "SugarDry" }, RuJ = "Драже «Южная ночь»: арахис в шоколаде и тёплое море на крышке. Привезено паромом, которого больше нет. У костра вкуснее. У костра всё вкуснее.", EnJ = "‘Southern Night’ dragée: peanuts in chocolate and a warm sea on the lid. Brought over by a ferry that no longer exists. It tastes better by the fire. Everything does.", Rare = false },
        new Def { Id = "YuzhnayaNochSesame", Kind = Kind.Snack, Shape = "carton", Mesh = "YuzhnayaNoch", Texture = "YuzhnayaNochSesame", Kg = 0.158f, Kcal = 720f, Thirst = -2f, Eat = 5f, Ru = "Драже «Южная ночь»", En = "Yuzhnaya Noch coated peanuts", RuF = "арахис в кунжуте", EnF = "sesame peanuts", RuC = "СССР", EnC = "USSR", Fx = new[] { "SugarDry" }, RuJ = "Драже «Южная ночь»: арахис в шоколаде и тёплое море на крышке. Раньше это ели под телевизор. Телевизор молчит. Упаковку не выбрасывайте: ею можно разжечь печь.", EnJ = "‘Southern Night’ dragée: peanuts in chocolate and a warm sea on the lid. People ate this in front of the telly. The telly is silent. Keep the wrapper: it will light the stove.", Rare = false },
        new Def { Id = "YuzhnayaNochMandarin", Kind = Kind.Snack, Shape = "carton", Mesh = "YuzhnayaNoch", Texture = "YuzhnayaNochMandarin", Kg = 0.158f, Kcal = 720f, Thirst = -2f, Eat = 5f, Ru = "Драже «Южная ночь»", En = "Yuzhnaya Noch coated peanuts", RuF = "мандарин в шоколаде", EnF = "mandarin in chocolate", RuC = "СССР", EnC = "USSR", Fx = new[] { "SugarDry" }, RuJ = "Новогодняя серия: куранты отбили, а пачка осталась. Редкость. Забыто туристами, которым повезло уехать. Если это последняя на острове, вы её достойны.", EnJ = "A New Year edition: the clock has struck, the pack remains. A rarity. Left behind by tourists who were lucky enough to leave. If this is the last one on the island, you have earned it.", Rare = true },
        new Def { Id = "YuzhnayaNochValentine", Kind = Kind.Snack, Shape = "carton", Mesh = "YuzhnayaNoch", Texture = "YuzhnayaNochValentine", Kg = 0.158f, Kcal = 720f, Thirst = -2f, Eat = 5f, Ru = "Драже «Южная ночь»", En = "Yuzhnaya Noch coated peanuts", RuF = "вишня в шоколаде", EnF = "cherry in chocolate", RuC = "СССР", EnC = "USSR", Fx = new[] { "SugarDry" }, RuJ = "Серия для влюблённых: редкость. Делить не с кем, зато вся ваша. Механики заедали этим обед, не вытирая рук. Желудок удивится, но возражать не станет.", EnJ = "A Valentine edition: a rarity. No one to share it with, so it is all yours. Mechanics ate these for lunch without wiping their hands. Your stomach will be surprised but will not object.", Rare = true },
        new Def { Id = "YuzhnayaNochChoco", Kind = Kind.Snack, Shape = "carton", Mesh = "YuzhnayaNoch", Texture = "YuzhnayaNochChoco", Kg = 0.158f, Kcal = 720f, Thirst = -2f, Eat = 5f, Ru = "Драже «Южная ночь»", En = "Yuzhnaya Noch coated peanuts", RuF = "в шоколаде", EnF = "chocolate", RuC = "СССР", EnC = "USSR", Fx = new[] { "SugarDry" }, RuJ = "Драже «Южная ночь»: арахис в шоколаде и тёплое море на крышке. Последнее на всю Одинокую топь. Скорее всего. Запах выдаёт вас за сто шагов. Оно того стоит.", EnJ = "‘Southern Night’ dragée: peanuts in chocolate and a warm sea on the lid. The last one in all of Forlorn Muskeg. Most likely. The smell gives you away at a hundred paces. Worth it.", Rare = false },
        new Def { Id = "YuzhnayaNochRaisin", Kind = Kind.Snack, Shape = "carton", Mesh = "YuzhnayaNoch", Texture = "YuzhnayaNochRaisin", Kg = 0.158f, Kcal = 720f, Thirst = -2f, Eat = 5f, Ru = "Драже «Южная ночь»", En = "Yuzhnaya Noch coated peanuts", RuF = "изюм в глазури", EnF = "glazed raisins", RuC = "СССР", EnC = "USSR", Fx = new[] { "SugarDry" }, RuJ = "Драже «Южная ночь»: арахис в шоколаде и тёплое море на крышке. Смотритель маяка грыз такое, ожидая кораблей. Раньше это называли вредным. Теперь называют едой.", EnJ = "‘Southern Night’ dragée: peanuts in chocolate and a warm sea on the lid. The lighthouse keeper munched these while waiting for ships. They used to call this unhealthy. Now they call it food.", Rare = false },
        new Def { Id = "YuzhnayaNochYogurt", Kind = Kind.Snack, Shape = "carton", Mesh = "YuzhnayaNoch", Texture = "YuzhnayaNochYogurt", Kg = 0.158f, Kcal = 720f, Thirst = -2f, Eat = 5f, Ru = "Драже «Южная ночь»", En = "Yuzhnaya Noch coated peanuts", RuF = "в йогурте", EnF = "yoghurt coated", RuC = "СССР", EnC = "USSR", Fx = new[] { "SugarDry" }, RuJ = "Драже «Южная ночь»: арахис в шоколаде и тёплое море на крышке. Полки рушились, а это уцелело. Спальный мешок потом вытряхните.", EnJ = "‘Southern Night’ dragée: peanuts in chocolate and a warm sea on the lid. Shelves collapsed and this survived. Shake out your sleeping bag afterwards.", Rare = false },
        new Def { Id = "YuzhnayaNochCoffee", Kind = Kind.Snack, Shape = "carton", Mesh = "YuzhnayaNoch", Texture = "YuzhnayaNochCoffee", Kg = 0.158f, Kcal = 720f, Thirst = -2f, Eat = 5f, Ru = "Драже «Южная ночь»", En = "Yuzhnaya Noch coated peanuts", RuF = "кофейное", EnF = "coffee", RuC = "СССР", EnC = "USSR", Fx = new[] { "SugarDry" }, RuJ = "Драже «Южная ночь»: арахис в шоколаде и тёплое море на крышке. Смотритель заповедника называл это ужином. Зимой такое идёт за валюту.", EnJ = "‘Southern Night’ dragée: peanuts in chocolate and a warm sea on the lid. The park ranger called this dinner. In winter this passes for currency.", Rare = false },
        new Def { Id = "YuzhnayaNochHoney", Kind = Kind.Snack, Shape = "carton", Mesh = "YuzhnayaNoch", Texture = "YuzhnayaNochHoney", Kg = 0.158f, Kcal = 720f, Thirst = -2f, Eat = 5f, Ru = "Драже «Южная ночь»", En = "Yuzhnaya Noch coated peanuts", RuF = "медовое", EnF = "honey", RuC = "СССР", EnC = "USSR", Fx = new[] { "SugarDry" }, RuJ = "Драже «Южная ночь»: арахис в шоколаде и тёплое море на крышке. Такое слали посылками с материка. Адресаты выбыли. Торговец дал бы за это тряпку. Вы дадите больше.", EnJ = "‘Southern Night’ dragée: peanuts in chocolate and a warm sea on the lid. These came in parcels from the mainland. The addressees are gone. The trader would give a rag for it. You would give more.", Rare = false },
        new Def { Id = "FlinkCrab", Kind = Kind.Snack, Shape = "bag", Mesh = "Flink", Texture = "FlinkCrab", Kg = 0.078f, Kcal = 280f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Флинк»", En = "Flink croutons", RuF = "краб", EnF = "crab", RuC = "Украина", EnC = "Ukraine", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сухарики с такими вкусами, будто пачку собирали прямо с праздничного стола. Иные держали это за лекарство. Тоже лечит. Пока жуёте, метель кажется короче.", EnJ = "Croutons in flavours picked straight off a holiday table. Some people counted this as medicine. Also a cure. While you chew, the blizzard seems shorter.", Rare = false },
        new Def { Id = "FlinkBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Flink", Texture = "FlinkBacon", Kg = 0.078f, Kcal = 280f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Флинк»", En = "Flink croutons", RuF = "бекон", EnF = "bacon", RuC = "Украина", EnC = "Ukraine", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сухарики с такими вкусами, будто пачку собирали прямо с праздничного стола. В школьном рюкзаке такое не доживало до обеда. Организм скажет спасибо. Или не скажет.", EnJ = "Croutons in flavours picked straight off a holiday table. In a school bag this never lasted till lunch. Your body will thank you. Or not.", Rare = false },
        new Def { Id = "FlinkAspic", Kind = Kind.Snack, Shape = "bag", Mesh = "Flink", Texture = "FlinkAspic", Kg = 0.078f, Kcal = 280f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Флинк»", En = "Flink croutons", RuF = "холодец с хреном", EnF = "aspic with horseradish", RuC = "Украина", EnC = "Ukraine", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Сухарики с такими вкусами, будто пачку собирали прямо с праздничного стола. Его обменяли бы на патрон, будь тут с кем меняться. На третьей горсти забываешь, что вокруг конец света.", EnJ = "Croutons in flavours picked straight off a holiday table. You could trade it for a cartridge, if there were anyone to trade with. By the third handful you forget the world has ended.", Rare = false },
        new Def { Id = "FlinkSour", Kind = Kind.Snack, Shape = "bag", Mesh = "Flink", Texture = "FlinkSour", Kg = 0.078f, Kcal = 280f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Флинк»", En = "Flink croutons", RuF = "сметана с зеленью", EnF = "sour cream & herbs", RuC = "Украина", EnC = "Ukraine", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сухарики с такими вкусами, будто пачку собирали прямо с праздничного стола. На вокзале это стоило втрое дороже. Теперь даром. Рыба подо льдом завидует.", EnJ = "Croutons in flavours picked straight off a holiday table. At the station it cost three times as much. Now it is free. The fish under the ice are jealous.", Rare = false },
        new Def { Id = "FlinkCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Flink", Texture = "FlinkCheese", Kg = 0.078f, Kcal = 280f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Флинк»", En = "Flink croutons", RuF = "сыр", EnF = "cheese", RuC = "Украина", EnC = "Ukraine", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сухарики с такими вкусами, будто пачку собирали прямо с праздничного стола. Пережило толчок и даже не помялось. Олень от такого отказался бы. Олень не голодал.", EnJ = "Croutons in flavours picked straight off a holiday table. It came through the quake without a dent. A deer would turn it down. A deer has never starved.", Rare = false },
        new Def { Id = "FlinkShashlik", Kind = Kind.Snack, Shape = "bag", Mesh = "Flink", Texture = "FlinkShashlik", Kg = 0.078f, Kcal = 280f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Флинк»", En = "Flink croutons", RuF = "шашлык", EnF = "shashlik", RuC = "Украина", EnC = "Ukraine", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сухарики с такими вкусами, будто пачку собирали прямо с праздничного стола. Китобои такого не ели, но оценили бы. Соль есть, жир есть, совести нет.", EnJ = "Croutons in flavours picked straight off a holiday table. The whalers never ate this, but they would have approved. Salt: yes. Fat: yes. Conscience: none.", Rare = false },
        new Def { Id = "FlinkGarlic", Kind = Kind.Snack, Shape = "bag", Mesh = "Flink", Texture = "FlinkGarlic", Kg = 0.078f, Kcal = 280f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Флинк»", En = "Flink croutons", RuF = "чеснок", EnF = "garlic", RuC = "Украина", EnC = "Ukraine", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сухарики с такими вкусами, будто пачку собирали прямо с праздничного стола. Осталось после чьего-то дня рождения. Гости не пришли. Ешьте до темноты: в темноте крошки не найти.", EnJ = "Croutons in flavours picked straight off a holiday table. Left over from someone's birthday. The guests never came. Eat before dark: you cannot find crumbs in the dark.", Rare = false },
        new Def { Id = "FlinkSalo", Kind = Kind.Snack, Shape = "bag", Mesh = "Flink", Texture = "FlinkSalo", Kg = 0.078f, Kcal = 280f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Флинк»", En = "Flink croutons", RuF = "сало", EnF = "salo", RuC = "Украина", EnC = "Ukraine", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сухарики с такими вкусами, будто пачку собирали прямо с праздничного стола. Мерзлота хранит лучше любого холодильника. Лучшее, что случится с вами сегодня.", EnJ = "Croutons in flavours picked straight off a holiday table. Permafrost keeps things better than any fridge. The best thing that will happen to you today.", Rare = false },
        new Def { Id = "FlinkMushroom", Kind = Kind.Snack, Shape = "bag", Mesh = "Flink", Texture = "FlinkMushroom", Kg = 0.078f, Kcal = 280f, Thirst = -5f, Eat = 3f, Ru = "Сухарики «Флинк»", En = "Flink croutons", RuF = "грибы", EnF = "mushroom", RuC = "Украина", EnC = "Ukraine", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Сухарики с такими вкусами, будто пачку собирали прямо с праздничного стола. Такое добывали из автомата, который съедал последнюю монету. Для полного счастья не хватает только дивана.", EnJ = "Croutons in flavours picked straight off a holiday table. These came from the vending machine that ate your last coin. All that is missing for perfect happiness is a sofa.", Rare = false },
        new Def { Id = "AnegaBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Anega", Texture = "AnegaBacon", Kg = 0.083f, Kcal = 400f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Анега»", En = "Anega crisps", RuF = "бекон", EnF = "bacon", RuC = "Беларусь", EnC = "Belarus", Fx = new[] { "SaltHold" }, RuJ = "Белорусские чипсы: картошка из страны, где в ней разбираются всерьёз. Такое брали в лодку под брезент, на весь день. Вкус детства, если детство было так себе.", EnJ = "Belarusian crisps: potatoes from a country that takes them seriously. People took these out in the boat under the tarpaulin, for the whole day. The taste of childhood, if childhood was so-so.", Rare = false },
        new Def { Id = "AnegaSour", Kind = Kind.Snack, Shape = "bag", Mesh = "Anega", Texture = "AnegaSour", Kg = 0.083f, Kcal = 400f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Анега»", En = "Anega crisps", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "Беларусь", EnC = "Belarus", Fx = new[] { "SaltHold" }, RuJ = "Белорусские чипсы: картошка из страны, где в ней разбираются всерьёз. С ним кто-то шёл к перевалу и не дошёл. Шуршит как надежда.", EnJ = "Belarusian crisps: potatoes from a country that takes them seriously. Someone carried it towards the pass and never arrived. It rustles like hope.", Rare = false },
        new Def { Id = "AnegaCrab", Kind = Kind.Snack, Shape = "bag", Mesh = "Anega", Texture = "AnegaCrab", Kg = 0.083f, Kcal = 400f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Анега»", En = "Anega crisps", RuF = "краб", EnF = "crab", RuC = "Беларусь", EnC = "Belarus", Fx = new[] { "SaltHold" }, RuJ = "Белорусские чипсы: картошка из страны, где в ней разбираются всерьёз. С таким сидели у окна с видом на метель. Голод отступит, жажда придёт. Честный обмен.", EnJ = "Belarusian crisps: potatoes from a country that takes them seriously. People sat with these at a window with a view of the blizzard. Hunger leaves, thirst arrives. A fair trade.", Rare = false },
        new Def { Id = "AnegaCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Anega", Texture = "AnegaCheese", Kg = 0.083f, Kcal = 400f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Анега»", En = "Anega crisps", RuF = "сыр", EnF = "cheese", RuC = "Беларусь", EnC = "Belarus", Fx = new[] { "SaltHold" }, RuJ = "Белорусские чипсы: картошка из страны, где в ней разбираются всерьёз. Уцелело там, где сгорело всё остальное. Не согреет, зато отвлечёт.", EnJ = "Belarusian crisps: potatoes from a country that takes them seriously. It survived where everything else burned. It will not warm you, but it will distract you.", Rare = false },
        new Def { Id = "AnegaDill", Kind = Kind.Snack, Shape = "bag", Mesh = "Anega", Texture = "AnegaDill", Kg = 0.083f, Kcal = 400f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Анега»", En = "Anega crisps", RuF = "укроп", EnF = "dill", RuC = "Беларусь", EnC = "Belarus", Fx = new[] { "SaltHold" }, RuJ = "Белорусские чипсы: картошка из страны, где в ней разбираются всерьёз. Этим кормили сторожевого пса. Пёс ушёл в волки. Пума предпочитает мясо. Вам повезло.", EnJ = "Belarusian crisps: potatoes from a country that takes them seriously. They fed the guard dog with this. The dog joined the wolves. The cougar prefers meat. Lucky you.", Rare = false },
        new Def { Id = "AnegaMushroom", Kind = Kind.Snack, Shape = "bag", Mesh = "Anega", Texture = "AnegaMushroom", Kg = 0.083f, Kcal = 400f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Анега»", En = "Anega crisps", RuF = "грибы", EnF = "mushroom", RuC = "Беларусь", EnC = "Belarus", Fx = new[] { "SaltHold" }, RuJ = "Белорусские чипсы: картошка из страны, где в ней разбираются всерьёз. Из запасов лесорубов: брали ящиками. Сначала попробуйте одну штучку. Шутка: ешьте всё.", EnJ = "Belarusian crisps: potatoes from a country that takes them seriously. From the loggers' stores: they bought it by the crate. Try just one first. Joke: eat the lot.", Rare = false },
        new Def { Id = "AnegaDraniki", Kind = Kind.Snack, Shape = "bag", Mesh = "Anega", Texture = "AnegaDraniki", Kg = 0.083f, Kcal = 400f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Анега»", En = "Anega crisps", RuF = "драники со сметаной", EnF = "draniki with sour cream", RuC = "Беларусь", EnC = "Belarus", Fx = new[] { "SaltHold" }, RuJ = "Белорусские чипсы: картошка из страны, где в ней разбираются всерьёз. В пост такое не ели. Пост кончился вместе с миром. Такой ужин не стыдно записать в дневник.", EnJ = "Belarusian crisps: potatoes from a country that takes them seriously. Nobody ate these during a fast. The fast ended with the world. A dinner worth writing in the journal.", Rare = false },
        new Def { Id = "AnegaSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "Anega", Texture = "AnegaSalt", Kg = 0.083f, Kcal = 400f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Анега»", En = "Anega crisps", RuF = "соль", EnF = "salted", RuC = "Беларусь", EnC = "Belarus", Fx = new[] { "SaltHold" }, RuJ = "Белорусские чипсы: картошка из страны, где в ней разбираются всерьёз. Теперь это ценнее денег. Деньги оставьте. Силы прибавит на один сугроб.", EnJ = "Belarusian crisps: potatoes from a country that takes them seriously. It is worth more than money now. Leave the money. It will carry you one snowdrift further.", Rare = false },
        new Def { Id = "UmaibouPotage", Kind = Kind.Snack, Shape = "bag", Mesh = "Umaibou", Texture = "UmaibouPotage", Kg = 0.014f, Kcal = 30f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Умайбо»", En = "Umaibou corn puffs", RuF = "кукурузный суп", EnF = "corn potage", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Кукурузная трубка за десять иен: кот на пачке в суде клянётся, что он не тот кот. Его несли на пикник. Пикник отменили навсегда. Идеально к закату, которого не видно за бураном.", EnJ = "A ten-yen corn tube: the cat on the pack swears in court he is not that other cat. It was headed for a picnic. The picnic is cancelled forever. Perfect with a sunset you cannot see for the storm.", Rare = false },
        new Def { Id = "UmaibouCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Umaibou", Texture = "UmaibouCheese", Kg = 0.014f, Kcal = 30f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Умайбо»", En = "Umaibou corn puffs", RuF = "сыр", EnF = "cheese", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Кукурузная трубка за десять иен: кот на пачке в суде клянётся, что он не тот кот. Такое стояло у кассы на случай слабости. Пахнет магазином. Помните магазины?", EnJ = "A ten-yen corn tube: the cat on the pack swears in court he is not that other cat. These stood by the till for moments of weakness. It smells of a shop. Remember shops?", Rare = false },
        new Def { Id = "UmaibouMentai", Kind = Kind.Snack, Shape = "bag", Mesh = "Umaibou", Texture = "UmaibouMentai", Kg = 0.014f, Kcal = 30f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Умайбо»", En = "Umaibou corn puffs", RuF = "икра минтая", EnF = "mentaiko", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Кукурузная трубка за десять иен: кот на пачке в суде клянётся, что он не тот кот. Досталось вам, потому что вы дошли первым. Мороз не испортил, время не взяло.", EnJ = "A ten-yen corn tube: the cat on the pack swears in court he is not that other cat. It is yours because you got here first. Frost did not spoil it and time could not take it.", Rare = false },
        new Def { Id = "UmaibouTakoyaki", Kind = Kind.Snack, Shape = "bag", Mesh = "Umaibou", Texture = "UmaibouTakoyaki", Kg = 0.014f, Kcal = 30f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Умайбо»", En = "Umaibou corn puffs", RuF = "такояки", EnF = "takoyaki", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Кукурузная трубка за десять иен: кот на пачке в суде клянётся, что он не тот кот. Упаковка выцвела, внутри время остановилось. В рюкзаке не мнётся. Почти.", EnJ = "A ten-yen corn tube: the cat on the pack swears in court he is not that other cat. The wrapper has faded; inside, time stood still. It does not get crushed in a pack. Almost.", Rare = false },
        new Def { Id = "UmaibouTeriyaki", Kind = Kind.Snack, Shape = "bag", Mesh = "Umaibou", Texture = "UmaibouTeriyaki", Kg = 0.014f, Kcal = 30f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Умайбо»", En = "Umaibou corn puffs", RuF = "терияки-бургер", EnF = "teriyaki burger", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Кукурузная трубка за десять иен: кот на пачке в суде клянётся, что он не тот кот. Из чемодана пассажира, который не долетел. Съешьте сейчас: завтра может не быть аппетита.", EnJ = "A ten-yen corn tube: the cat on the pack swears in court he is not that other cat. From the suitcase of a passenger who never landed. Eat it now: tomorrow you may have no appetite.", Rare = false },
        new Def { Id = "UmaibouMochi", Kind = Kind.Snack, Shape = "bag", Mesh = "Umaibou", Texture = "UmaibouMochi", Kg = 0.014f, Kcal = 30f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Умайбо»", En = "Umaibou corn puffs", RuF = "новогодние моти", EnF = "new year mochi", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Новогодняя серия: куранты отбили, а пачка осталась. Редкость. Перезимовало и ничуть не обиделось. Хватит дойти до следующей хижины и пожалеть, что кончилось.", EnJ = "A New Year edition: the clock has struck, the pack remains. A rarity. It made it through the winter and bears no grudge. Enough to reach the next cabin and regret it is gone.", Rare = true },
        new Def { Id = "UmaibouSakura", Kind = Kind.Snack, Shape = "bag", Mesh = "Umaibou", Texture = "UmaibouSakura", Kg = 0.014f, Kcal = 30f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Умайбо»", En = "Umaibou corn puffs", RuF = "сакура", EnF = "sakura", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Запасливая хозяйка купила по акции шесть штук. От такого не толстеют те, кто ходит по двадцать километров.", EnJ = "A spring edition: a rare pack from the days when spring still came. A thrifty housewife bought six of these on offer. Nobody who walks twenty kilometres a day gets fat on this.", Rare = true },
        new Def { Id = "UmaibouPumpkin", Kind = Kind.Snack, Shape = "bag", Mesh = "Umaibou", Texture = "UmaibouPumpkin", Kg = 0.014f, Kcal = 30f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Умайбо»", En = "Umaibou corn puffs", RuF = "тыквенный суп", EnF = "pumpkin potage", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Серия к Хэллоуину: редкость. Пугать тут и без неё есть кому. Кто-то написал на упаковке «моё». Уже нет. Волчья стая не в курсе. Пусть так и будет.", EnJ = "A Halloween edition: a rarity. There is plenty to scare you here without it. Someone wrote 'mine' on it. Not any more. The wolf pack does not know. Keep it that way.", Rare = true },
        new Def { Id = "UmaibouSalami", Kind = Kind.Snack, Shape = "bag", Mesh = "Umaibou", Texture = "UmaibouSalami", Kg = 0.014f, Kcal = 30f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Умайбо»", En = "Umaibou corn puffs", RuF = "салями", EnF = "salami", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Кукурузная трубка за десять иен: кот на пачке в суде клянётся, что он не тот кот. В консервном цеху это ели тайком от мастера. Хрустеть в засаде не рекомендуется.", EnJ = "A ten-yen corn tube: the cat on the pack swears in court he is not that other cat. At the cannery they ate this behind the foreman's back. Crunching in an ambush is not recommended.", Rare = false },
        new Def { Id = "UmaibouYasai", Kind = Kind.Snack, Shape = "bag", Mesh = "Umaibou", Texture = "UmaibouYasai", Kg = 0.014f, Kcal = 30f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Умайбо»", En = "Umaibou corn puffs", RuF = "овощной салат", EnF = "vegetable salad", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Кукурузная трубка за десять иен: кот на пачке в суде клянётся, что он не тот кот. Его не взяли даже мародёры. Они спешили. Лекарство от тоски, отпускается без рецепта.", EnJ = "A ten-yen corn tube: the cat on the pack swears in court he is not that other cat. Even the looters left it. They were in a hurry. A cure for the blues, no prescription needed.", Rare = false },
        new Def { Id = "UmaibouTonkatsu", Kind = Kind.Snack, Shape = "bag", Mesh = "Umaibou", Texture = "UmaibouTonkatsu", Kg = 0.014f, Kcal = 30f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Умайбо»", En = "Umaibou corn puffs", RuF = "соус тонкацу", EnF = "tonkatsu sauce", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Кукурузная трубка за десять иен: кот на пачке в суде клянётся, что он не тот кот. Провело зиму на острове, как и вы. Жуйте и думайте о хорошем. Например, о добавке.", EnJ = "A ten-yen corn tube: the cat on the pack swears in court he is not that other cat. It spent the winter on the island, same as you. Chew and think of nice things. Seconds, for example.", Rare = false },
        new Def { Id = "UmaibouShrimp", Kind = Kind.Snack, Shape = "bag", Mesh = "Umaibou", Texture = "UmaibouShrimp", Kg = 0.014f, Kcal = 30f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Умайбо»", En = "Umaibou corn puffs", RuF = "креветка с майонезом", EnF = "shrimp mayonnaise", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Кукурузная трубка за десять иен: кот на пачке в суде клянётся, что он не тот кот. Дети прятали такое под кроватью, в тайнике. К утру от него останется только запах на варежках.", EnJ = "A ten-yen corn tube: the cat on the pack swears in court he is not that other cat. Children hid these under the bed, in a secret place. By morning only the smell on your mittens will be left.", Rare = false },
        new Def { Id = "UmaibouNatto", Kind = Kind.Snack, Shape = "bag", Mesh = "Umaibou", Texture = "UmaibouNatto", Kg = 0.014f, Kcal = 30f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Умайбо»", En = "Umaibou corn puffs", RuF = "натто", EnF = "natto", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Кукурузная трубка за десять иен: кот на пачке в суде клянётся, что он не тот кот. Осталось от геологов вместе с картой и долгами. Тишина вокруг такая, что слышно, как вы жуёте.", EnJ = "A ten-yen corn tube: the cat on the pack swears in court he is not that other cat. Left by the geologists along with a map and some debts. It is so quiet you can hear yourself chew.", Rare = false },
        new Def { Id = "UmaibouChicken", Kind = Kind.Snack, Shape = "bag", Mesh = "Umaibou", Texture = "UmaibouChicken", Kg = 0.014f, Kcal = 30f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Умайбо»", En = "Umaibou corn puffs", RuF = "курица карри", EnF = "chicken curry", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Кукурузная трубка за десять иен: кот на пачке в суде клянётся, что он не тот кот. На острове такое было праздником и до катастрофы. Не делите на завтра: завтра будет новый голод.", EnJ = "A ten-yen corn tube: the cat on the pack swears in court he is not that other cat. On the island this was a treat even before the disaster. Do not save half for tomorrow: tomorrow brings its own hunger.", Rare = false },
        new Def { Id = "UmaibouSugar", Kind = Kind.Snack, Shape = "bag", Mesh = "Umaibou", Texture = "UmaibouSugar", Kg = 0.014f, Kcal = 30f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Умайбо»", En = "Umaibou corn puffs", RuF = "сахарный сухарик", EnF = "sugar rusk", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Кукурузная трубка за десять иен: кот на пачке в суде клянётся, что он не тот кот. С таким слушали радио, которое теперь ловит только треск. Сосны вокруг делают вид, что не смотрят.", EnJ = "A ten-yen corn tube: the cat on the pack swears in court he is not that other cat. People ate these by the radio, which picks up nothing but crackle now. The pines around pretend not to watch.", Rare = false },
        new Def { Id = "UmaibouChoco", Kind = Kind.Snack, Shape = "bag", Mesh = "Umaibou", Texture = "UmaibouChoco", Kg = 0.014f, Kcal = 30f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Умайбо»", En = "Umaibou corn puffs", RuF = "шоколад", EnF = "chocolate", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Кукурузная трубка за десять иен: кот на пачке в суде клянётся, что он не тот кот. Крысы прогрызли соседнюю, эту пощадили. Калории мелкие, зато свои.", EnJ = "A ten-yen corn tube: the cat on the pack swears in court he is not that other cat. The rats gnawed through the one next to it and spared this. Small calories, but your own.", Rare = false },
        new Def { Id = "PuretsuSalad", Kind = Kind.Snack, Shape = "carton", Mesh = "Puretsu", Texture = "PuretsuSalad", Kg = 0.077f, Kcal = 270f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Пурэцу»", En = "Puretsu sticks", RuF = "салат", EnF = "salad", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Японская соломка с салатным вкусом: салата внутри нет, совесть чиста. Бывший хозяин клялся бросить. Не успел. После этого даже крапивный чай покажется десертом.", EnJ = "Japanese sticks, salad flavour: no salad inside, conscience clear. The former owner swore to give these up. He ran out of time. After this even nettle tea feels like dessert.", Rare = false },
        new Def { Id = "PuretsuTomato", Kind = Kind.Snack, Shape = "carton", Mesh = "Puretsu", Texture = "PuretsuTomato", Kg = 0.077f, Kcal = 270f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Пурэцу»", En = "Puretsu sticks", RuF = "томат", EnF = "tomato", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Японская соломка с салатным вкусом: салата внутри нет, совесть чиста. Его катали в кабине трактора три сезона. Нашедшему полагается всё.", EnJ = "Japanese sticks, salad flavour: no salad inside, conscience clear. It rode around in a tractor cab for three seasons. Finders keepers, all of it.", Rare = false },
        new Def { Id = "PuretsuButter", Kind = Kind.Snack, Shape = "carton", Mesh = "Puretsu", Texture = "PuretsuButter", Kg = 0.077f, Kcal = 270f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Пурэцу»", En = "Puretsu sticks", RuF = "жареное масло", EnF = "roast butter", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Японская соломка с салатным вкусом: салата внутри нет, совесть чиста. После бани такое шло лучше всего. Зубы целы? Тогда вперёд.", EnJ = "Japanese sticks, salad flavour: no salad inside, conscience clear. Nothing went down better after the sauna. Teeth intact? Then go ahead.", Rare = false },
        new Def { Id = "PuretsuRoast", Kind = Kind.Snack, Shape = "carton", Mesh = "Puretsu", Texture = "PuretsuRoast", Kg = 0.077f, Kcal = 270f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Пурэцу»", En = "Puretsu sticks", RuF = "обжаренные", EnF = "roasted", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Японская соломка с салатным вкусом: салата внутри нет, совесть чиста. В тюрьме на это выменивали что угодно. Ночью приснится добавка.", EnJ = "Japanese sticks, salad flavour: no salad inside, conscience clear. In the prison you could trade one of these for anything. Tonight you will dream of seconds.", Rare = false },
        new Def { Id = "PuretsuCheese", Kind = Kind.Snack, Shape = "carton", Mesh = "Puretsu", Texture = "PuretsuCheese", Kg = 0.077f, Kcal = 270f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Пурэцу»", En = "Puretsu sticks", RuF = "сыр", EnF = "cheese", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Японская соломка с салатным вкусом: салата внутри нет, совесть чиста. Кто-то менял это на сигареты. Сделка сорвалась. С таким запасом можно пережить ещё один вечер.", EnJ = "Japanese sticks, salad flavour: no salad inside, conscience clear. Someone was trading this for cigarettes. The deal fell through. With supplies like this you can survive one more evening.", Rare = false },
        new Def { Id = "PuretsuGarlic", Kind = Kind.Snack, Shape = "carton", Mesh = "Puretsu", Texture = "PuretsuGarlic", Kg = 0.077f, Kcal = 270f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Пурэцу»", En = "Puretsu sticks", RuF = "чеснок", EnF = "garlic", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Японская соломка с салатным вкусом: салата внутри нет, совесть чиста. С ним зимовали на метеостанции, пока было с кем. Пёс бы выпросил половину. Пса нет.", EnJ = "Japanese sticks, salad flavour: no salad inside, conscience clear. They wintered with it at the weather station, while there was a 'they'. A dog would beg half of it. There is no dog.", Rare = false },
        new Def { Id = "PuretsuUme", Kind = Kind.Snack, Shape = "carton", Mesh = "Puretsu", Texture = "PuretsuUme", Kg = 0.077f, Kcal = 270f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Пурэцу»", En = "Puretsu sticks", RuF = "слива умэ", EnF = "pickled plum", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Японская соломка с салатным вкусом: салата внутри нет, совесть чиста. Такое терялось в кладовке среди крупы и надежд. Съедено будет быстрее, чем найдено.", EnJ = "Japanese sticks, salad flavour: no salad inside, conscience clear. These got lost in the pantry among the grain and the hopes. It will be eaten faster than it was found.", Rare = false },
        new Def { Id = "KaramuchoChili", Kind = Kind.Snack, Shape = "bag", Mesh = "Karamucho", Texture = "KaramuchoChili", Kg = 0.063f, Kcal = 290f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Карамуча»", En = "Karamucha crisps", RuF = "острый чили", EnF = "hot chili", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Острые японские чипсы: бабушка на пачке злая, потому что тоже попробовала. Его берегли к приезду внуков. На вкус как выходной.", EnJ = "Hot Japanese crisps: the granny on the pack is angry because she tried them too. It was being saved for the grandchildren's visit. It tastes like a day off.", Rare = false },
        new Def { Id = "KaramuchoUme", Kind = Kind.Snack, Shape = "bag", Mesh = "Karamucho", Texture = "KaramuchoUme", Kg = 0.063f, Kcal = 290f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Карамуча»", En = "Karamucha crisps", RuF = "кислая слива", EnF = "sour plum", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Острые японские чипсы: бабушка на пачке злая, потому что тоже попробовала. В баре такое ставили на стойку, бесплатно к пиву. Пива нет. Ветер унесёт запах прямо к берлоге. Ешьте быстрее.", EnJ = "Hot Japanese crisps: the granny on the pack is angry because she tried them too. Bars put these out free with a beer. There is no beer. The wind carries the smell straight to the den. Eat faster.", Rare = false },
        new Def { Id = "KaramuchoNori", Kind = Kind.Snack, Shape = "bag", Mesh = "Karamucho", Texture = "KaramuchoNori", Kg = 0.063f, Kcal = 290f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Карамуча»", En = "Karamucha crisps", RuF = "нори и соль", EnF = "seaweed salt", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Острые японские чипсы: бабушка на пачке злая, потому что тоже попробовала. Такое лежало в каждом доме, пока не погас свет. Пополняет запас соли и веры в человечество.", EnJ = "Hot Japanese crisps: the granny on the pack is angry because she tried them too. Every house had one of these until the lights went out. Restores your salt and your faith in mankind.", Rare = false },
        new Def { Id = "KaramuchoSummer", Kind = Kind.Snack, Shape = "bag", Mesh = "Karamucho", Texture = "KaramuchoSummer", Kg = 0.063f, Kcal = 290f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Карамуча»", En = "Karamucha crisps", RuF = "летний адский чили", EnF = "summer hell chilli", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Кто-то берёг это на чёрный день. Он настал. Хорошо идёт под треск поленьев.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. Someone saved this for a rainy day. It came. Goes down well with crackling logs.", Rare = true },
        new Def { Id = "KaramuchoKimchi", Kind = Kind.Snack, Shape = "bag", Mesh = "Karamucho", Texture = "KaramuchoKimchi", Kg = 0.063f, Kcal = 290f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Карамуча»", En = "Karamucha crisps", RuF = "кимчи", EnF = "kimchi", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Острые японские чипсы: бабушка на пачке злая, потому что тоже попробовала. Пережило хозяина, кота и две зимы. Руки вытирать о штаны: салфеток не завезли.", EnJ = "Hot Japanese crisps: the granny on the pack is angry because she tried them too. It outlived its owner, the cat and two winters. Wipe your hands on your trousers: no napkins were delivered.", Rare = false },
        new Def { Id = "KaramuchoWasabi", Kind = Kind.Snack, Shape = "bag", Mesh = "Karamucho", Texture = "KaramuchoWasabi", Kg = 0.063f, Kcal = 290f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Карамуча»", En = "Karamucha crisps", RuF = "васаби", EnF = "wasabi", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Острые японские чипсы: бабушка на пачке злая, потому что тоже попробовала. Такое обычно находили за диваном, как всё лучшее в жизни. Маленькая радость размером с ладонь.", EnJ = "Hot Japanese crisps: the granny on the pack is angry because she tried them too. These were usually found behind the sofa, like all the best things in life. A small joy the size of your palm.", Rare = false },
        new Def { Id = "KaramuchoGarlic", Kind = Kind.Snack, Shape = "bag", Mesh = "Karamucho", Texture = "KaramuchoGarlic", Kg = 0.063f, Kcal = 290f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Карамуча»", En = "Karamucha crisps", RuF = "чеснок", EnF = "garlic", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Острые японские чипсы: бабушка на пачке злая, потому что тоже попробовала. Последний завоз был до того, как упали самолёты. Совесть молчит, живот поёт.", EnJ = "Hot Japanese crisps: the granny on the pack is angry because she tried them too. The last delivery came before the planes fell. Conscience is silent, the belly sings.", Rare = false },
        new Def { Id = "KaramuchoCurry", Kind = Kind.Snack, Shape = "bag", Mesh = "Karamucho", Texture = "KaramuchoCurry", Kg = 0.063f, Kcal = 290f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Карамуча»", En = "Karamucha crisps", RuF = "острый карри", EnF = "hot curry", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Острые японские чипсы: бабушка на пачке злая, потому что тоже попробовала. Ценник оторван: теперь это бесценно. Проверено поколениями и одной катастрофой.", EnJ = "Hot Japanese crisps: the granny on the pack is angry because she tried them too. The price tag is torn off: it is priceless now. Tested by generations and one catastrophe.", Rare = false },
        new Def { Id = "KaramuchoMiso", Kind = Kind.Snack, Shape = "bag", Mesh = "Karamucho", Texture = "KaramuchoMiso", Kg = 0.063f, Kcal = 290f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Карамуча»", En = "Karamucha crisps", RuF = "мисо", EnF = "miso", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Острые японские чипсы: бабушка на пачке злая, потому что тоже попробовала. Дата на шве стёрлась, и слава богу. Оставьте пару штук на перевал. Не оставите.", EnJ = "Hot Japanese crisps: the granny on the pack is angry because she tried them too. The date on the seam has rubbed off, thank goodness. Save a couple for the pass. You will not.", Rare = false },
        new Def { Id = "HappiTanOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "HappiTan", Texture = "HappiTanOriginal", Kg = 0.104f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Хаппи Тан»", En = "Happi Tan rice crackers", RuF = "сладко-солёные", EnF = "sweet & salty", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Рисовые крекеры в волшебной пудре: пудру слизывают первой, это закон. Пахнет заправкой у Прибрежного шоссе. Здесь это считается ужином при свечах.", EnJ = "Rice crackers in magic powder: you lick the powder first, that's the law. It smells of the petrol station on the Coastal Highway. Round here this counts as a candlelit dinner.", Rare = false },
        new Def { Id = "HappiTanPowder", Kind = Kind.Snack, Shape = "bag", Mesh = "HappiTan", Texture = "HappiTanPowder", Kg = 0.104f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Хаппи Тан»", En = "Happi Tan rice crackers", RuF = "двойная посыпка", EnF = "double powder", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Рисовые крекеры в волшебной пудре: пудру слизывают первой, это закон. Такое возили в бардачке на дальнюю дорогу. Дороги кончились. Луна светит, еда хрустит, жизнь налаживается.", EnJ = "Rice crackers in magic powder: you lick the powder first, that's the law. People kept these in the glovebox for long drives. The drives are over. The moon shines, the food crunches, life is looking up.", Rare = false },
        new Def { Id = "HappiTanButter", Kind = Kind.Snack, Shape = "bag", Mesh = "HappiTan", Texture = "HappiTanButter", Kg = 0.104f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Хаппи Тан»", En = "Happi Tan rice crackers", RuF = "с маслом", EnF = "butter", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Рисовые крекеры в волшебной пудре: пудру слизывают первой, это закон. Мыши не тронули. Думайте сами. Снег вокруг не солёный. Это солёное.", EnJ = "Rice crackers in magic powder: you lick the powder first, that's the law. The mice left it alone. Draw your own conclusions. The snow around is not salty. This is.", Rare = false },
        new Def { Id = "HappiTanWinter", Kind = Kind.Snack, Shape = "bag", Mesh = "HappiTan", Texture = "HappiTanWinter", Kg = 0.104f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Хаппи Тан»", En = "Happi Tan rice crackers", RuF = "зимнее масло", EnF = "winter butter", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Зимняя серия: выпускали на один сезон, а зима тут навсегда. Рыбаки брали такое на лёд вместо обеда. Больше таких не делают. Совсем.", EnJ = "A winter edition: made for one season, and here winter is forever. Fishermen took this onto the ice instead of lunch. They do not make these any more. At all.", Rare = true },
        new Def { Id = "HappiTanCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "HappiTan", Texture = "HappiTanCheese", Kg = 0.104f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Хаппи Тан»", En = "Happi Tan rice crackers", RuF = "сыр", EnF = "cheese", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Рисовые крекеры в волшебной пудре: пудру слизывают первой, это закон. Смотритель плотины держал такое в заначке. Открывайте тихо: у волков отличный слух.", EnJ = "Rice crackers in magic powder: you lick the powder first, that's the law. The dam keeper kept a stash of these. Open it quietly: wolves have excellent hearing.", Rare = false },
        new Def { Id = "HappiTanShoyu", Kind = Kind.Snack, Shape = "bag", Mesh = "HappiTan", Texture = "HappiTanShoyu", Kg = 0.104f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Хаппи Тан»", En = "Happi Tan rice crackers", RuF = "соевый соус", EnF = "soy sauce", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Рисовые крекеры в волшебной пудре: пудру слизывают первой, это закон. Кто-то спрятал это от детей. Дети не нашли. Одной не обойдётся, но вторая неизвестно где.", EnJ = "Rice crackers in magic powder: you lick the powder first, that's the law. Someone hid it from the kids. The kids never found it. One won't be enough, and nobody knows where the second is.", Rare = false },
        new Def { Id = "HappiTanUme", Kind = Kind.Snack, Shape = "bag", Mesh = "HappiTan", Texture = "HappiTanUme", Kg = 0.104f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Хаппи Тан»", En = "Happi Tan rice crackers", RuF = "слива умэ", EnF = "pickled plum", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Рисовые крекеры в волшебной пудре: пудру слизывают первой, это закон. В сельском магазине такое вечно заваливалось за прилавок. Крошки с пола тоже считаются.", EnJ = "Rice crackers in magic powder: you lick the powder first, that's the law. In the village shop these kept slipping behind the counter. The crumbs on the floor count too.", Rare = false },
        new Def { Id = "HappiTanMatcha", Kind = Kind.Snack, Shape = "bag", Mesh = "HappiTan", Texture = "HappiTanMatcha", Kg = 0.104f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Хаппи Тан»", En = "Happi Tan rice crackers", RuF = "матча", EnF = "matcha", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Рисовые крекеры в волшебной пудре: пудру слизывают первой, это закон. Ждало покупателя дольше, чем тот прожил. Запейте чаем из шиповника и считайте это обедом.", EnJ = "Rice crackers in magic powder: you lick the powder first, that's the law. It waited for a buyer longer than the buyer lived. Wash it down with rosehip tea and call it lunch.", Rare = false },
        new Def { Id = "HappiTanKinako", Kind = Kind.Snack, Shape = "bag", Mesh = "HappiTan", Texture = "HappiTanKinako", Kg = 0.104f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Рисовые крекеры «Хаппи Тан»", En = "Happi Tan rice crackers", RuF = "соевая мука с мёдом", EnF = "honey soybean flour", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Рисовые крекеры в волшебной пудре: пудру слизывают первой, это закон. С материка такое больше не привезут. Медведю не показывать: отнимет вместе с рукой.", EnJ = "Rice crackers in magic powder: you lick the powder first, that's the law. Nobody will bring this from the mainland again. Do not show the bear: he will take it, hand and all.", Rare = false },
        new Def { Id = "KyarameruKonOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "KyarameruKon", Texture = "KyarameruKonOriginal", Kg = 0.078f, Kcal = 380f, Thirst = -2f, Eat = 4f, Ru = "Кукурузные снеки «Карамель Кон»", En = "Kyarameru Kon corn puffs", RuF = "карамель", EnF = "caramel", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Карамельная кукуруза: на дне пакета арахис, как клад для терпеливых. На упаковке иней, внутри всё по-прежнему. Диетолог не одобрил бы. Диетолога тут нет.", EnJ = "Caramel corn: peanuts at the bottom of the bag, a treasure for the patient. Frost on the wrapper, business as usual inside. A dietitian would not approve. There is no dietitian here.", Rare = false },
        new Def { Id = "KyarameruKonAlmond", Kind = Kind.Snack, Shape = "bag", Mesh = "KyarameruKon", Texture = "KyarameruKonAlmond", Kg = 0.078f, Kcal = 380f, Thirst = -2f, Eat = 4f, Ru = "Кукурузные снеки «Карамель Кон»", En = "Kyarameru Kon corn puffs", RuF = "миндаль", EnF = "almond", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Карамельная кукуруза: на дне пакета арахис, как клад для терпеливых. Мороз ему нипочём: твёрже не стало, мягче тоже. Лучше, чем кора. Проверено.", EnJ = "Caramel corn: peanuts at the bottom of the bag, a treasure for the patient. The frost did nothing to it: no harder, no softer. Better than bark. Tested.", Rare = false },
        new Def { Id = "KyarameruKonMatcha", Kind = Kind.Snack, Shape = "bag", Mesh = "KyarameruKon", Texture = "KyarameruKonMatcha", Kg = 0.078f, Kcal = 380f, Thirst = -2f, Eat = 4f, Ru = "Кукурузные снеки «Карамель Кон»", En = "Kyarameru Kon corn puffs", RuF = "матча", EnF = "matcha", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Карамельная кукуруза: на дне пакета арахис, как клад для терпеливых. Из тех времён, когда еду выбирали по вкусу. У костра вкуснее. У костра всё вкуснее.", EnJ = "Caramel corn: peanuts at the bottom of the bag, a treasure for the patient. From the days when people picked food for its taste. It tastes better by the fire. Everything does.", Rare = false },
        new Def { Id = "KyarameruKonChestnut", Kind = Kind.Snack, Shape = "bag", Mesh = "KyarameruKon", Texture = "KyarameruKonChestnut", Kg = 0.078f, Kcal = 380f, Thirst = -2f, Eat = 4f, Ru = "Кукурузные снеки «Карамель Кон»", En = "Kyarameru Kon corn puffs", RuF = "осенний каштан", EnF = "autumn chestnut", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Чей-то перекус на ночную смену, которая не кончилась. Ешьте медленно: когда ещё такое найдёте.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. Someone's snack for a night shift that never ended. Eat slowly: who knows when you will find another.", Rare = true },
        new Def { Id = "KyarameruKonChoco", Kind = Kind.Snack, Shape = "bag", Mesh = "KyarameruKon", Texture = "KyarameruKonChoco", Kg = 0.078f, Kcal = 380f, Thirst = -2f, Eat = 4f, Ru = "Кукурузные снеки «Карамель Кон»", En = "Kyarameru Kon corn puffs", RuF = "шоколад", EnF = "chocolate", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Карамельная кукуруза: на дне пакета арахис, как клад для терпеливых. В охотничьей вышке таким встречали рассвет. Если это последняя на острове, вы её достойны.", EnJ = "Caramel corn: peanuts at the bottom of the bag, a treasure for the patient. In the hunting blind they met the dawn with this. If this is the last one on the island, you have earned it.", Rare = false },
        new Def { Id = "KyarameruKonSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "KyarameruKon", Texture = "KyarameruKonSalt", Kg = 0.078f, Kcal = 380f, Thirst = -2f, Eat = 4f, Ru = "Кукурузные снеки «Карамель Кон»", En = "Kyarameru Kon corn puffs", RuF = "солёная карамель", EnF = "salted caramel", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Карамельная кукуруза: на дне пакета арахис, как клад для терпеливых. Такое носили в кармане куртки на всякий случай. Случай настал. Сияние на вкус не влияет. Наверное.", EnJ = "Caramel corn: peanuts at the bottom of the bag, a treasure for the patient. People carried these in a coat pocket just in case. The case has come. The aurora does not affect the taste. Probably.", Rare = false },
        new Def { Id = "KyarameruKonMaple", Kind = Kind.Snack, Shape = "bag", Mesh = "KyarameruKon", Texture = "KyarameruKonMaple", Kg = 0.078f, Kcal = 380f, Thirst = -2f, Eat = 4f, Ru = "Кукурузные снеки «Карамель Кон»", En = "Kyarameru Kon corn puffs", RuF = "кленовый сироп", EnF = "maple", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Карамельная кукуруза: на дне пакета арахис, как клад для терпеливых. Прежний хозяин оставил записку: «Не трогать». Записка сгорела. После тушёнки из банки это почти ресторан.", EnJ = "Caramel corn: peanuts at the bottom of the bag, a treasure for the patient. The last owner left a note: 'Do not touch'. The note burned. After stew from a tin this is nearly a restaurant.", Rare = false },
        new Def { Id = "KyarameruKonStrawberry", Kind = Kind.Snack, Shape = "bag", Mesh = "KyarameruKon", Texture = "KyarameruKonStrawberry", Kg = 0.078f, Kcal = 380f, Thirst = -2f, Eat = 4f, Ru = "Кукурузные снеки «Карамель Кон»", En = "Kyarameru Kon corn puffs", RuF = "клубника", EnF = "strawberry", RuC = "Япония", EnC = "Japan", Fx = new[] { "SugarDry" }, RuJ = "Карамельная кукуруза: на дне пакета арахис, как клад для терпеливых. Такими торговали в поезде, пока поезд ходил. Делиться не с кем, и это впервые радует.", EnJ = "Caramel corn: peanuts at the bottom of the bag, a treasure for the patient. They sold these on the train, while the train ran. Nobody to share with, and for once that is good news.", Rare = false },
        new Def { Id = "PokaChipOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "PokaChip", Texture = "PokaChipOriginal", Kg = 0.074f, Kcal = 350f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пока Чип»", En = "Poka Chip crisps", RuF = "оригинальные", EnF = "original", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские чипсы: пакет на две трети из воздуха, из таких студенты связали плот. Сторож шахты держал такое в ящике стола. Пальцы потом оближите: зимой калории не выбрасывают.", EnJ = "Korean crisps: the bag is two-thirds air, students once built a raft of them. The mine watchman kept these in his desk drawer. Lick your fingers after: in winter you do not waste calories.", Rare = false },
        new Def { Id = "PokaChipOnion", Kind = Kind.Snack, Shape = "bag", Mesh = "PokaChip", Texture = "PokaChipOnion", Kg = 0.074f, Kcal = 350f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пока Чип»", En = "Poka Chip crisps", RuF = "лук", EnF = "onion", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские чипсы: пакет на две трети из воздуха, из таких студенты связали плот. Лавина прошла мимо, срок годности тоже. Ворон на ветке уже ждёт свою долю.", EnJ = "Korean crisps: the bag is two-thirds air, students once built a raft of them. The avalanche missed it, and so did the best-before date. The crow on the branch is already waiting for its share.", Rare = false },
        new Def { Id = "PokaChipCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "PokaChip", Texture = "PokaChipCheese", Kg = 0.074f, Kcal = 350f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пока Чип»", En = "Poka Chip crisps", RuF = "сладкий сыр", EnF = "sweet cheese", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские чипсы: пакет на две трети из воздуха, из таких студенты связали плот. Такое всегда стояло на видном месте, поэтому никто не брал. На морозе хрустит вдвое громче.", EnJ = "Korean crisps: the bag is two-thirds air, students once built a raft of them. These always stood in plain sight, which is why nobody took them. In the frost it crunches twice as loud.", Rare = false },
        new Def { Id = "PokaChipLime", Kind = Kind.Snack, Shape = "bag", Mesh = "PokaChip", Texture = "PokaChipLime", Kg = 0.074f, Kcal = 350f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пока Чип»", En = "Poka Chip crisps", RuF = "летний лайм с чили", EnF = "summer lime chili", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Кто-то открыл, передумал и умер. Не связано. Не еда, а настроение. Настроение тоже греет.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. Someone opened it, changed their mind and died. Unrelated. Not food but a mood. A mood warms you too.", Rare = true },
        new Def { Id = "PokaChipWinter", Kind = Kind.Snack, Shape = "bag", Mesh = "PokaChip", Texture = "PokaChipWinter", Kg = 0.074f, Kcal = 350f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пока Чип»", En = "Poka Chip crisps", RuF = "зимний сливочный суп", EnF = "winter cream soup", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Зимняя серия: выпускали на один сезон, а зима тут навсегда. Такое вечно каталось под сиденьем пикапа. Сытости на час, воспоминаний на неделю.", EnJ = "A winter edition: made for one season, and here winter is forever. One of these was always rolling under a pickup seat. An hour of fullness, a week of memories.", Rare = true },
        new Def { Id = "PokaChipSeaweed", Kind = Kind.Snack, Shape = "bag", Mesh = "PokaChip", Texture = "PokaChipSeaweed", Kg = 0.074f, Kcal = 350f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пока Чип»", En = "Poka Chip crisps", RuF = "нори", EnF = "seaweed", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские чипсы: пакет на две трети из воздуха, из таких студенты связали плот. Привезено паромом, которого больше нет. Кролик смотрит с осуждением.", EnJ = "Korean crisps: the bag is two-thirds air, students once built a raft of them. Brought over by a ferry that no longer exists. The rabbit looks on with disapproval.", Rare = false },
        new Def { Id = "PokaChipHot", Kind = Kind.Snack, Shape = "bag", Mesh = "PokaChip", Texture = "PokaChipHot", Kg = 0.074f, Kcal = 350f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пока Чип»", En = "Poka Chip crisps", RuF = "острые", EnF = "spicy", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Корейские чипсы: пакет на две трети из воздуха, из таких студенты связали плот. Раньше это ели под телевизор. Телевизор молчит. У костра вкуснее. У костра всё вкуснее.", EnJ = "Korean crisps: the bag is two-thirds air, students once built a raft of them. People ate this in front of the telly. The telly is silent. It tastes better by the fire. Everything does.", Rare = false },
        new Def { Id = "PokaChipButter", Kind = Kind.Snack, Shape = "bag", Mesh = "PokaChip", Texture = "PokaChipButter", Kg = 0.074f, Kcal = 350f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пока Чип»", En = "Poka Chip crisps", RuF = "мёд и масло", EnF = "honey butter", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Корейские чипсы: пакет на две трети из воздуха, из таких студенты связали плот. Забыто туристами, которым повезло уехать. Упаковку не выбрасывайте: ею можно разжечь печь.", EnJ = "Korean crisps: the bag is two-thirds air, students once built a raft of them. Left behind by tourists who were lucky enough to leave. Keep the wrapper: it will light the stove.", Rare = false },
        new Def { Id = "PokaChipPepper", Kind = Kind.Snack, Shape = "bag", Mesh = "PokaChip", Texture = "PokaChipPepper", Kg = 0.074f, Kcal = 350f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пока Чип»", En = "Poka Chip crisps", RuF = "соль и перец", EnF = "salt & pepper", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские чипсы: пакет на две трети из воздуха, из таких студенты связали плот. Механики заедали этим обед, не вытирая рук. Если это последняя на острове, вы её достойны.", EnJ = "Korean crisps: the bag is two-thirds air, students once built a raft of them. Mechanics ate these for lunch without wiping their hands. If this is the last one on the island, you have earned it.", Rare = false },
        new Def { Id = "PokaChipWasabi", Kind = Kind.Snack, Shape = "bag", Mesh = "PokaChip", Texture = "PokaChipWasabi", Kg = 0.074f, Kcal = 350f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пока Чип»", En = "Poka Chip crisps", RuF = "васаби", EnF = "wasabi", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Корейские чипсы: пакет на две трети из воздуха, из таких студенты связали плот. Последнее на всю Одинокую топь. Скорее всего. Желудок удивится, но возражать не станет.", EnJ = "Korean crisps: the bag is two-thirds air, students once built a raft of them. The last one in all of Forlorn Muskeg. Most likely. Your stomach will be surprised but will not object.", Rare = false },
        new Def { Id = "KkobukCorn", Kind = Kind.Snack, Shape = "bag", Mesh = "Kkobuk", Texture = "KkobukCorn", Kg = 0.088f, Kcal = 440f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Ккобук Чип»", En = "Kkobuk Chip corn puffs", RuF = "кукурузный суп", EnF = "corn soup", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Чипсы-черепашки в четыре слоя: черепаха хрустит, но никуда не спешит. Смотритель маяка грыз такое, ожидая кораблей. Запах выдаёт вас за сто шагов. Оно того стоит.", EnJ = "Four-layer turtle chips: the turtle crunches but is in no hurry. The lighthouse keeper munched these while waiting for ships. The smell gives you away at a hundred paces. Worth it.", Rare = false },
        new Def { Id = "KkobukChoco", Kind = Kind.Snack, Shape = "bag", Mesh = "Kkobuk", Texture = "KkobukChoco", Kg = 0.088f, Kcal = 440f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Ккобук Чип»", En = "Kkobuk Chip corn puffs", RuF = "шоколадные чуррос", EnF = "choco churros", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Чипсы-черепашки в четыре слоя: черепаха хрустит, но никуда не спешит. Полки рушились, а это уцелело. Раньше это называли вредным. Теперь называют едой.", EnJ = "Four-layer turtle chips: the turtle crunches but is in no hurry. Shelves collapsed and this survived. They used to call this unhealthy. Now they call it food.", Rare = false },
        new Def { Id = "KkobukVanilla", Kind = Kind.Snack, Shape = "bag", Mesh = "Kkobuk", Texture = "KkobukVanilla", Kg = 0.088f, Kcal = 440f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Ккобук Чип»", En = "Kkobuk Chip corn puffs", RuF = "сладкая ваниль", EnF = "sweet vanilla", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Чипсы-черепашки в четыре слоя: черепаха хрустит, но никуда не спешит. Смотритель заповедника называл это ужином. Спальный мешок потом вытряхните.", EnJ = "Four-layer turtle chips: the turtle crunches but is in no hurry. The park ranger called this dinner. Shake out your sleeping bag afterwards.", Rare = false },
        new Def { Id = "KkobukPepero", Kind = Kind.Snack, Shape = "bag", Mesh = "Kkobuk", Texture = "KkobukPepero", Kg = 0.088f, Kcal = 440f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Ккобук Чип»", En = "Kkobuk Chip corn puffs", RuF = "шоколад ко дню влюблённых", EnF = "valentine chocolate", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Серия для влюблённых: редкость. Делить не с кем, зато вся ваша. Такое слали посылками с материка. Адресаты выбыли. Зимой такое идёт за валюту.", EnJ = "A Valentine edition: a rarity. No one to share it with, so it is all yours. These came in parcels from the mainland. The addressees are gone. In winter this passes for currency.", Rare = true },
        new Def { Id = "KkobukInjeolmi", Kind = Kind.Snack, Shape = "bag", Mesh = "Kkobuk", Texture = "KkobukInjeolmi", Kg = 0.088f, Kcal = 440f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Ккобук Чип»", En = "Kkobuk Chip corn puffs", RuF = "рисовый пирог инджольми", EnF = "injeolmi rice cake", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Чипсы-черепашки в четыре слоя: черепаха хрустит, но никуда не спешит. Иные держали это за лекарство. Тоже лечит. Торговец дал бы за это тряпку. Вы дадите больше.", EnJ = "Four-layer turtle chips: the turtle crunches but is in no hurry. Some people counted this as medicine. Also a cure. The trader would give a rag for it. You would give more.", Rare = false },
        new Def { Id = "KkobukShrimp", Kind = Kind.Snack, Shape = "bag", Mesh = "Kkobuk", Texture = "KkobukShrimp", Kg = 0.088f, Kcal = 440f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Ккобук Чип»", En = "Kkobuk Chip corn puffs", RuF = "креветка", EnF = "shrimp", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Чипсы-черепашки в четыре слоя: черепаха хрустит, но никуда не спешит. В школьном рюкзаке такое не доживало до обеда. Пока жуёте, метель кажется короче.", EnJ = "Four-layer turtle chips: the turtle crunches but is in no hurry. In a school bag this never lasted till lunch. While you chew, the blizzard seems shorter.", Rare = false },
        new Def { Id = "KkobukMint", Kind = Kind.Snack, Shape = "bag", Mesh = "Kkobuk", Texture = "KkobukMint", Kg = 0.088f, Kcal = 440f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Ккобук Чип»", En = "Kkobuk Chip corn puffs", RuF = "мятный шоколад", EnF = "mint chocolate", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Чипсы-черепашки в четыре слоя: черепаха хрустит, но никуда не спешит. Его обменяли бы на патрон, будь тут с кем меняться. Организм скажет спасибо. Или не скажет.", EnJ = "Four-layer turtle chips: the turtle crunches but is in no hurry. You could trade it for a cartridge, if there were anyone to trade with. Your body will thank you. Or not.", Rare = false },
        new Def { Id = "KkobukCinnamon", Kind = Kind.Snack, Shape = "bag", Mesh = "Kkobuk", Texture = "KkobukCinnamon", Kg = 0.088f, Kcal = 440f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Ккобук Чип»", En = "Kkobuk Chip corn puffs", RuF = "корица", EnF = "cinnamon", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Чипсы-черепашки в четыре слоя: черепаха хрустит, но никуда не спешит. На вокзале это стоило втрое дороже. Теперь даром. На третьей горсти забываешь, что вокруг конец света.", EnJ = "Four-layer turtle chips: the turtle crunches but is in no hurry. At the station it cost three times as much. Now it is free. By the third handful you forget the world has ended.", Rare = false },
        new Def { Id = "KkobukMala", Kind = Kind.Snack, Shape = "bag", Mesh = "Kkobuk", Texture = "KkobukMala", Kg = 0.088f, Kcal = 440f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Ккобук Чип»", En = "Kkobuk Chip corn puffs", RuF = "острая мала", EnF = "spicy mala", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Чипсы-черепашки в четыре слоя: черепаха хрустит, но никуда не спешит. Пережило толчок и даже не помялось. Рыба подо льдом завидует.", EnJ = "Four-layer turtle chips: the turtle crunches but is in no hurry. It came through the quake without a dent. The fish under the ice are jealous.", Rare = false },
        new Def { Id = "BananaKickBanana", Kind = Kind.Snack, Shape = "bag", Mesh = "BananaKick", Texture = "BananaKickBanana", Kg = 0.083f, Kcal = 410f, Thirst = -2f, Eat = 4f, Ru = "Кукурузные снеки «Банана Кок»", En = "Banana Kok corn puffs", RuF = "банан", EnF = "banana", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Банановые палочки: пахнут тропиками, которых на этой широте не будет никогда. Китобои такого не ели, но оценили бы. Олень от такого отказался бы. Олень не голодал.", EnJ = "Banana puffs: they smell of tropics this latitude will never see. The whalers never ate this, but they would have approved. A deer would turn it down. A deer has never starved.", Rare = false },
        new Def { Id = "BananaKickStrawberry", Kind = Kind.Snack, Shape = "bag", Mesh = "BananaKick", Texture = "BananaKickStrawberry", Kg = 0.083f, Kcal = 410f, Thirst = -2f, Eat = 4f, Ru = "Кукурузные снеки «Банана Кок»", En = "Banana Kok corn puffs", RuF = "клубника", EnF = "strawberry", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Банановые палочки: пахнут тропиками, которых на этой широте не будет никогда. Осталось после чьего-то дня рождения. Гости не пришли. Идеально к закату, которого не видно за бураном.", EnJ = "Banana puffs: they smell of tropics this latitude will never see. Left over from someone's birthday. The guests never came. Perfect with a sunset you cannot see for the storm.", Rare = false },
        new Def { Id = "BananaKickChoco", Kind = Kind.Snack, Shape = "bag", Mesh = "BananaKick", Texture = "BananaKickChoco", Kg = 0.083f, Kcal = 410f, Thirst = -2f, Eat = 4f, Ru = "Кукурузные снеки «Банана Кок»", En = "Banana Kok corn puffs", RuF = "шоколад", EnF = "chocolate", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Банановые палочки: пахнут тропиками, которых на этой широте не будет никогда. Мерзлота хранит лучше любого холодильника. Ешьте до темноты: в темноте крошки не найти.", EnJ = "Banana puffs: they smell of tropics this latitude will never see. Permafrost keeps things better than any fridge. Eat before dark: you cannot find crumbs in the dark.", Rare = false },
        new Def { Id = "BananaKickSummer", Kind = Kind.Snack, Shape = "bag", Mesh = "BananaKick", Texture = "BananaKickSummer", Kg = 0.083f, Kcal = 410f, Thirst = -2f, Eat = 4f, Ru = "Кукурузные снеки «Банана Кок»", En = "Banana Kok corn puffs", RuF = "летний арбуз", EnF = "summer watermelon", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Такое добывали из автомата, который съедал последнюю монету. Лучшее, что случится с вами сегодня.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. These came from the vending machine that ate your last coin. The best thing that will happen to you today.", Rare = true },
        new Def { Id = "BananaKickMelon", Kind = Kind.Snack, Shape = "bag", Mesh = "BananaKick", Texture = "BananaKickMelon", Kg = 0.083f, Kcal = 410f, Thirst = -2f, Eat = 4f, Ru = "Кукурузные снеки «Банана Кок»", En = "Banana Kok corn puffs", RuF = "дыня", EnF = "melon", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Банановые палочки: пахнут тропиками, которых на этой широте не будет никогда. Такое брали в лодку под брезент, на весь день. Для полного счастья не хватает только дивана.", EnJ = "Banana puffs: they smell of tropics this latitude will never see. People took these out in the boat under the tarpaulin, for the whole day. All that is missing for perfect happiness is a sofa.", Rare = false },
        new Def { Id = "BananaKickMilk", Kind = Kind.Snack, Shape = "bag", Mesh = "BananaKick", Texture = "BananaKickMilk", Kg = 0.083f, Kcal = 410f, Thirst = -2f, Eat = 4f, Ru = "Кукурузные снеки «Банана Кок»", En = "Banana Kok corn puffs", RuF = "молочный", EnF = "milky", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Банановые палочки: пахнут тропиками, которых на этой широте не будет никогда. С ним кто-то шёл к перевалу и не дошёл. Вкус детства, если детство было так себе.", EnJ = "Banana puffs: they smell of tropics this latitude will never see. Someone carried it towards the pass and never arrived. The taste of childhood, if childhood was so-so.", Rare = false },
        new Def { Id = "BananaKickMango", Kind = Kind.Snack, Shape = "bag", Mesh = "BananaKick", Texture = "BananaKickMango", Kg = 0.083f, Kcal = 410f, Thirst = -2f, Eat = 4f, Ru = "Кукурузные снеки «Банана Кок»", En = "Banana Kok corn puffs", RuF = "манго", EnF = "mango", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Банановые палочки: пахнут тропиками, которых на этой широте не будет никогда. С таким сидели у окна с видом на метель. Шуршит как надежда.", EnJ = "Banana puffs: they smell of tropics this latitude will never see. People sat with these at a window with a view of the blizzard. It rustles like hope.", Rare = false },
        new Def { Id = "BananaKickCream", Kind = Kind.Snack, Shape = "bag", Mesh = "BananaKick", Texture = "BananaKickCream", Kg = 0.083f, Kcal = 410f, Thirst = -2f, Eat = 4f, Ru = "Кукурузные снеки «Банана Кок»", En = "Banana Kok corn puffs", RuF = "сливочный сыр", EnF = "cream cheese", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Банановые палочки: пахнут тропиками, которых на этой широте не будет никогда. Уцелело там, где сгорело всё остальное. Голод отступит, жажда придёт. Честный обмен.", EnJ = "Banana puffs: they smell of tropics this latitude will never see. It survived where everything else burned. Hunger leaves, thirst arrives. A fair trade.", Rare = false },
        new Def { Id = "YangpaOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "Yangpa", Texture = "YangpaOriginal", Kg = 0.092f, Kcal = 420f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Янпарин»", En = "Yangparing onion rings", RuF = "оригинальные", EnF = "original", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские луковые кольца: лук нарисован весёлым, он ещё не знает. Этим кормили сторожевого пса. Пёс ушёл в волки. Не согреет, зато отвлечёт.", EnJ = "Korean onion rings: the onion is drawn cheerful, it doesn't know yet. They fed the guard dog with this. The dog joined the wolves. It will not warm you, but it will distract you.", Rare = false },
        new Def { Id = "YangpaSpicy", Kind = Kind.Snack, Shape = "bag", Mesh = "Yangpa", Texture = "YangpaSpicy", Kg = 0.092f, Kcal = 420f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Янпарин»", En = "Yangparing onion rings", RuF = "острые", EnF = "spicy", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Корейские луковые кольца: лук нарисован весёлым, он ещё не знает. Из запасов лесорубов: брали ящиками. Пума предпочитает мясо. Вам повезло.", EnJ = "Korean onion rings: the onion is drawn cheerful, it doesn't know yet. From the loggers' stores: they bought it by the crate. The cougar prefers meat. Lucky you.", Rare = false },
        new Def { Id = "YangpaGarlic", Kind = Kind.Snack, Shape = "bag", Mesh = "Yangpa", Texture = "YangpaGarlic", Kg = 0.092f, Kcal = 420f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Янпарин»", En = "Yangparing onion rings", RuF = "чеснок", EnF = "garlic", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские луковые кольца: лук нарисован весёлым, он ещё не знает. В пост такое не ели. Пост кончился вместе с миром. Сначала попробуйте одну штучку. Шутка: ешьте всё.", EnJ = "Korean onion rings: the onion is drawn cheerful, it doesn't know yet. Nobody ate these during a fast. The fast ended with the world. Try just one first. Joke: eat the lot.", Rare = false },
        new Def { Id = "YangpaCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Yangpa", Texture = "YangpaCheese", Kg = 0.092f, Kcal = 420f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Янпарин»", En = "Yangparing onion rings", RuF = "сыр", EnF = "cheese", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские луковые кольца: лук нарисован весёлым, он ещё не знает. Теперь это ценнее денег. Деньги оставьте. Такой ужин не стыдно записать в дневник.", EnJ = "Korean onion rings: the onion is drawn cheerful, it doesn't know yet. It is worth more than money now. Leave the money. A dinner worth writing in the journal.", Rare = false },
        new Def { Id = "YangpaHoney", Kind = Kind.Snack, Shape = "bag", Mesh = "Yangpa", Texture = "YangpaHoney", Kg = 0.092f, Kcal = 420f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Янпарин»", En = "Yangparing onion rings", RuF = "мёд", EnF = "honey", RuC = "Корея", EnC = "Korea", Fx = new[] { "SugarDry" }, RuJ = "Корейские луковые кольца: лук нарисован весёлым, он ещё не знает. Его несли на пикник. Пикник отменили навсегда. Силы прибавит на один сугроб.", EnJ = "Korean onion rings: the onion is drawn cheerful, it doesn't know yet. It was headed for a picnic. The picnic is cancelled forever. It will carry you one snowdrift further.", Rare = false },
        new Def { Id = "YangpaBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Yangpa", Texture = "YangpaBBQ", Kg = 0.092f, Kcal = 420f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Янпарин»", En = "Yangparing onion rings", RuF = "барбекю", EnF = "barbecue", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские луковые кольца: лук нарисован весёлым, он ещё не знает. Такое стояло у кассы на случай слабости. Идеально к закату, которого не видно за бураном.", EnJ = "Korean onion rings: the onion is drawn cheerful, it doesn't know yet. These stood by the till for moments of weakness. Perfect with a sunset you cannot see for the storm.", Rare = false },
        new Def { Id = "YangpaSour", Kind = Kind.Snack, Shape = "bag", Mesh = "Yangpa", Texture = "YangpaSour", Kg = 0.092f, Kcal = 420f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Янпарин»", En = "Yangparing onion rings", RuF = "сметана", EnF = "sour cream", RuC = "Корея", EnC = "Korea", Fx = new[] { "SaltHold" }, RuJ = "Корейские луковые кольца: лук нарисован весёлым, он ещё не знает. Досталось вам, потому что вы дошли первым. Пахнет магазином. Помните магазины?", EnJ = "Korean onion rings: the onion is drawn cheerful, it doesn't know yet. It is yours because you got here first. It smells of a shop. Remember shops?", Rare = false },
        new Def { Id = "LeshiCucumber", Kind = Kind.Snack, Shape = "bag", Mesh = "Leshi", Texture = "LeshiCucumber", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лэши»", En = "Leshi crisps", RuF = "огурец", EnF = "cucumber", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Китайские чипсы: там бывает даже вкус огурца, и он лучший. Упаковка выцвела, внутри время остановилось. Мороз не испортил, время не взяло.", EnJ = "Chinese crisps: they even come in cucumber, and it's the best one. The wrapper has faded; inside, time stood still. Frost did not spoil it and time could not take it.", Rare = false },
        new Def { Id = "LeshiCrayfish", Kind = Kind.Snack, Shape = "bag", Mesh = "Leshi", Texture = "LeshiCrayfish", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лэши»", En = "Leshi crisps", RuF = "острые раки", EnF = "spicy crayfish", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Китайские чипсы: там бывает даже вкус огурца, и он лучший. Из чемодана пассажира, который не долетел. В рюкзаке не мнётся. Почти.", EnJ = "Chinese crisps: they even come in cucumber, and it's the best one. From the suitcase of a passenger who never landed. It does not get crushed in a pack. Almost.", Rare = false },
        new Def { Id = "LeshiTomato", Kind = Kind.Snack, Shape = "bag", Mesh = "Leshi", Texture = "LeshiTomato", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лэши»", En = "Leshi crisps", RuF = "томат", EnF = "tomato", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Китайские чипсы: там бывает даже вкус огурца, и он лучший. Перезимовало и ничуть не обиделось. Съешьте сейчас: завтра может не быть аппетита.", EnJ = "Chinese crisps: they even come in cucumber, and it's the best one. It made it through the winter and bears no grudge. Eat it now: tomorrow you may have no appetite.", Rare = false },
        new Def { Id = "LeshiBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Leshi", Texture = "LeshiBBQ", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лэши»", En = "Leshi crisps", RuF = "шашлык", EnF = "barbecue", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Китайские чипсы: там бывает даже вкус огурца, и он лучший. Запасливая хозяйка купила по акции шесть штук. Хватит дойти до следующей хижины и пожалеть, что кончилось.", EnJ = "Chinese crisps: they even come in cucumber, and it's the best one. A thrifty housewife bought six of these on offer. Enough to reach the next cabin and regret it is gone.", Rare = false },
        new Def { Id = "LeshiHotPot", Kind = Kind.Snack, Shape = "bag", Mesh = "Leshi", Texture = "LeshiHotPot", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лэши»", En = "Leshi crisps", RuF = "зимний хого", EnF = "winter hot pot", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Зимняя серия: выпускали на один сезон, а зима тут навсегда. Кто-то написал на упаковке «моё». Уже нет. От такого не толстеют те, кто ходит по двадцать километров.", EnJ = "A winter edition: made for one season, and here winter is forever. Someone wrote 'mine' on it. Not any more. Nobody who walks twenty kilometres a day gets fat on this.", Rare = true },
        new Def { Id = "LeshiMooncake", Kind = Kind.Snack, Shape = "bag", Mesh = "Leshi", Texture = "LeshiMooncake", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лэши»", En = "Leshi crisps", RuF = "лунный пряник", EnF = "mooncake", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. В консервном цеху это ели тайком от мастера. Волчья стая не в курсе. Пусть так и будет.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. At the cannery they ate this behind the foreman's back. The wolf pack does not know. Keep it that way.", Rare = true },
        new Def { Id = "LeshiZongzi", Kind = Kind.Snack, Shape = "bag", Mesh = "Leshi", Texture = "LeshiZongzi", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лэши»", En = "Leshi crisps", RuF = "рисовый цзунцзы", EnF = "zongzi rice dumpling", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Его не взяли даже мародёры. Они спешили. Хрустеть в засаде не рекомендуется.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. Even the looters left it. They were in a hurry. Crunching in an ambush is not recommended.", Rare = true },
        new Def { Id = "LeshiSpring", Kind = Kind.Snack, Shape = "bag", Mesh = "Leshi", Texture = "LeshiSpring", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лэши»", En = "Leshi crisps", RuF = "весенняя сакура", EnF = "spring cherry blossom", RuC = "Китай", EnC = "China", Fx = new[] { "SugarDry" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Провело зиму на острове, как и вы. Лекарство от тоски, отпускается без рецепта.", EnJ = "A spring edition: a rare pack from the days when spring still came. It spent the winter on the island, same as you. A cure for the blues, no prescription needed.", Rare = true },
        new Def { Id = "LeshiLime", Kind = Kind.Snack, Shape = "bag", Mesh = "Leshi", Texture = "LeshiLime", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лэши»", En = "Leshi crisps", RuF = "лайм", EnF = "lime", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Китайские чипсы: там бывает даже вкус огурца, и он лучший. Дети прятали такое под кроватью, в тайнике. Жуйте и думайте о хорошем. Например, о добавке.", EnJ = "Chinese crisps: they even come in cucumber, and it's the best one. Children hid these under the bed, in a secret place. Chew and think of nice things. Seconds, for example.", Rare = false },
        new Def { Id = "LeshiChicken", Kind = Kind.Snack, Shape = "bag", Mesh = "Leshi", Texture = "LeshiChicken", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лэши»", En = "Leshi crisps", RuF = "жареные крылышки", EnF = "roast chicken wings", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Китайские чипсы: там бывает даже вкус огурца, и он лучший. Осталось от геологов вместе с картой и долгами. К утру от него останется только запах на варежках.", EnJ = "Chinese crisps: they even come in cucumber, and it's the best one. Left by the geologists along with a map and some debts. By morning only the smell on your mittens will be left.", Rare = false },
        new Def { Id = "LeshiSeaweed", Kind = Kind.Snack, Shape = "bag", Mesh = "Leshi", Texture = "LeshiSeaweed", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лэши»", En = "Leshi crisps", RuF = "нори", EnF = "seaweed", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Китайские чипсы: там бывает даже вкус огурца, и он лучший. На острове такое было праздником и до катастрофы. Тишина вокруг такая, что слышно, как вы жуёте.", EnJ = "Chinese crisps: they even come in cucumber, and it's the best one. On the island this was a treat even before the disaster. It is so quiet you can hear yourself chew.", Rare = false },
        new Def { Id = "LeshiSpicy", Kind = Kind.Snack, Shape = "bag", Mesh = "Leshi", Texture = "LeshiSpicy", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лэши»", En = "Leshi crisps", RuF = "сычуаньские острые", EnF = "sichuan spicy", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Китайские чипсы: там бывает даже вкус огурца, и он лучший. С таким слушали радио, которое теперь ловит только треск. Не делите на завтра: завтра будет новый голод.", EnJ = "Chinese crisps: they even come in cucumber, and it's the best one. People ate these by the radio, which picks up nothing but crackle now. Do not save half for tomorrow: tomorrow brings its own hunger.", Rare = false },
        new Def { Id = "LeshiOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "Leshi", Texture = "LeshiOriginal", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лэши»", En = "Leshi crisps", RuF = "оригинальные", EnF = "original", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Китайские чипсы: там бывает даже вкус огурца, и он лучший. Крысы прогрызли соседнюю, эту пощадили. Сосны вокруг делают вид, что не смотрят.", EnJ = "Chinese crisps: they even come in cucumber, and it's the best one. The rats gnawed through the one next to it and spared this. The pines around pretend not to watch.", Rare = false },
        new Def { Id = "LeshiFish", Kind = Kind.Snack, Shape = "bag", Mesh = "Leshi", Texture = "LeshiFish", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лэши»", En = "Leshi crisps", RuF = "рыба в остром масле", EnF = "fish in spicy oil", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Китайские чипсы: там бывает даже вкус огурца, и он лучший. Бывший хозяин клялся бросить. Не успел. Калории мелкие, зато свои.", EnJ = "Chinese crisps: they even come in cucumber, and it's the best one. The former owner swore to give these up. He ran out of time. Small calories, but your own.", Rare = false },
        new Def { Id = "LeshiDuck", Kind = Kind.Snack, Shape = "bag", Mesh = "Leshi", Texture = "LeshiDuck", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лэши»", En = "Leshi crisps", RuF = "утка по-пекински", EnF = "peking duck", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Китайские чипсы: там бывает даже вкус огурца, и он лучший. Его катали в кабине трактора три сезона. После этого даже крапивный чай покажется десертом.", EnJ = "Chinese crisps: they even come in cucumber, and it's the best one. It rode around in a tractor cab for three seasons. After this even nettle tea feels like dessert.", Rare = false },
        new Def { Id = "ShanghaojiaShrimp", Kind = Kind.Snack, Shape = "bag", Mesh = "Shanghaojia", Texture = "ShanghaojiaShrimp", Kg = 0.088f, Kcal = 390f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Шанхаоцзя»", En = "Shanghaojia shrimp chips", RuF = "креветочные", EnF = "prawn crackers", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Креветочные палочки из Китая: креветка на пачке крупнее, чем весь пакет. После бани такое шло лучше всего. Нашедшему полагается всё.", EnJ = "Shrimp sticks from China: the shrimp on the pack is bigger than the bag. Nothing went down better after the sauna. Finders keepers, all of it.", Rare = false },
        new Def { Id = "ShanghaojiaOnion", Kind = Kind.Snack, Shape = "bag", Mesh = "Shanghaojia", Texture = "ShanghaojiaOnion", Kg = 0.088f, Kcal = 390f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Шанхаоцзя»", En = "Shanghaojia shrimp chips", RuF = "луковые кольца", EnF = "onion rings", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Креветочные палочки из Китая: креветка на пачке крупнее, чем весь пакет. В тюрьме на это выменивали что угодно. Зубы целы? Тогда вперёд.", EnJ = "Shrimp sticks from China: the shrimp on the pack is bigger than the bag. In the prison you could trade one of these for anything. Teeth intact? Then go ahead.", Rare = false },
        new Def { Id = "ShanghaojiaGarden", Kind = Kind.Snack, Shape = "bag", Mesh = "Shanghaojia", Texture = "ShanghaojiaGarden", Kg = 0.088f, Kcal = 390f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Шанхаоцзя»", En = "Shanghaojia shrimp chips", RuF = "овощные", EnF = "garden puffs", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Креветочные палочки из Китая: креветка на пачке крупнее, чем весь пакет. Кто-то менял это на сигареты. Сделка сорвалась. Ночью приснится добавка.", EnJ = "Shrimp sticks from China: the shrimp on the pack is bigger than the bag. Someone was trading this for cigarettes. The deal fell through. Tonight you will dream of seconds.", Rare = false },
        new Def { Id = "ShanghaojiaPotato", Kind = Kind.Snack, Shape = "bag", Mesh = "Shanghaojia", Texture = "ShanghaojiaPotato", Kg = 0.088f, Kcal = 390f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Шанхаоцзя»", En = "Shanghaojia shrimp chips", RuF = "картофельные палочки", EnF = "potato sticks", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Креветочные палочки из Китая: креветка на пачке крупнее, чем весь пакет. С ним зимовали на метеостанции, пока было с кем. С таким запасом можно пережить ещё один вечер.", EnJ = "Shrimp sticks from China: the shrimp on the pack is bigger than the bag. They wintered with it at the weather station, while there was a 'they'. With supplies like this you can survive one more evening.", Rare = false },
        new Def { Id = "ShanghaojiaSquid", Kind = Kind.Snack, Shape = "bag", Mesh = "Shanghaojia", Texture = "ShanghaojiaSquid", Kg = 0.088f, Kcal = 390f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Шанхаоцзя»", En = "Shanghaojia shrimp chips", RuF = "кальмар", EnF = "squid", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Креветочные палочки из Китая: креветка на пачке крупнее, чем весь пакет. Такое терялось в кладовке среди крупы и надежд. Пёс бы выпросил половину. Пса нет.", EnJ = "Shrimp sticks from China: the shrimp on the pack is bigger than the bag. These got lost in the pantry among the grain and the hopes. A dog would beg half of it. There is no dog.", Rare = false },
        new Def { Id = "ShanghaojiaCorn", Kind = Kind.Snack, Shape = "bag", Mesh = "Shanghaojia", Texture = "ShanghaojiaCorn", Kg = 0.088f, Kcal = 390f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Шанхаоцзя»", En = "Shanghaojia shrimp chips", RuF = "кукурузные трубочки", EnF = "corn rolls", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "Креветочные палочки из Китая: креветка на пачке крупнее, чем весь пакет. Его берегли к приезду внуков. Съедено будет быстрее, чем найдено.", EnJ = "Shrimp sticks from China: the shrimp on the pack is bigger than the bag. It was being saved for the grandchildren's visit. It will be eaten faster than it was found.", Rare = false },
        new Def { Id = "ShanghaojiaSpicy", Kind = Kind.Snack, Shape = "bag", Mesh = "Shanghaojia", Texture = "ShanghaojiaSpicy", Kg = 0.088f, Kcal = 390f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Шанхаоцзя»", En = "Shanghaojia shrimp chips", RuF = "острые", EnF = "spicy", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Креветочные палочки из Китая: креветка на пачке крупнее, чем весь пакет. В баре такое ставили на стойку, бесплатно к пиву. Пива нет. На вкус как выходной.", EnJ = "Shrimp sticks from China: the shrimp on the pack is bigger than the bag. Bars put these out free with a beer. There is no beer. It tastes like a day off.", Rare = false },
        new Def { Id = "SanzhiHuliPecan", Kind = Kind.Snack, Shape = "bag", Mesh = "SanzhiHuli", Texture = "SanzhiHuliPecan", Kg = 0.168f, Kcal = 960f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Три лисы»", En = "Three Foxes nuts", RuF = "пекан", EnF = "pecans", RuC = "Китай", EnC = "China", Fx = new[] { "Sinew" }, RuJ = "Три лисы с пачки смотрят хитро: орехи расколоты заранее, подвох в цене. Такое лежало в каждом доме, пока не погас свет. Ветер унесёт запах прямо к берлоге. Ешьте быстрее.", EnJ = "Three foxes on the pack look sly: the nuts are pre-cracked, the catch is the price. Every house had one of these until the lights went out. The wind carries the smell straight to the den. Eat faster.", Rare = false },
        new Def { Id = "SanzhiHuliMacadamia", Kind = Kind.Snack, Shape = "bag", Mesh = "SanzhiHuli", Texture = "SanzhiHuliMacadamia", Kg = 0.168f, Kcal = 960f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Три лисы»", En = "Three Foxes nuts", RuF = "макадамия", EnF = "macadamia", RuC = "Китай", EnC = "China", Fx = new[] { "Sinew" }, RuJ = "Три лисы с пачки смотрят хитро: орехи расколоты заранее, подвох в цене. Кто-то берёг это на чёрный день. Он настал. Пополняет запас соли и веры в человечество.", EnJ = "Three foxes on the pack look sly: the nuts are pre-cracked, the catch is the price. Someone saved this for a rainy day. It came. Restores your salt and your faith in mankind.", Rare = false },
        new Def { Id = "SanzhiHuliPistachio", Kind = Kind.Snack, Shape = "bag", Mesh = "SanzhiHuli", Texture = "SanzhiHuliPistachio", Kg = 0.168f, Kcal = 960f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Три лисы»", En = "Three Foxes nuts", RuF = "фисташки", EnF = "pistachios", RuC = "Китай", EnC = "China", Fx = new[] { "Sinew" }, RuJ = "Три лисы с пачки смотрят хитро: орехи расколоты заранее, подвох в цене. Пережило хозяина, кота и две зимы. Хорошо идёт под треск поленьев.", EnJ = "Three foxes on the pack look sly: the nuts are pre-cracked, the catch is the price. It outlived its owner, the cat and two winters. Goes down well with crackling logs.", Rare = false },
        new Def { Id = "SanzhiHuliNewYear", Kind = Kind.Snack, Shape = "bag", Mesh = "SanzhiHuli", Texture = "SanzhiHuliNewYear", Kg = 0.168f, Kcal = 960f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Три лисы»", En = "Three Foxes nuts", RuF = "новогодние орехи", EnF = "new year nuts", RuC = "Китай", EnC = "China", Fx = new[] { "Sinew" }, RuJ = "Новогодняя серия: куранты отбили, а пачка осталась. Редкость. Такое обычно находили за диваном, как всё лучшее в жизни. Руки вытирать о штаны: салфеток не завезли.", EnJ = "A New Year edition: the clock has struck, the pack remains. A rarity. These were usually found behind the sofa, like all the best things in life. Wipe your hands on your trousers: no napkins were delivered.", Rare = true },
        new Def { Id = "SanzhiHuliAlmond", Kind = Kind.Snack, Shape = "bag", Mesh = "SanzhiHuli", Texture = "SanzhiHuliAlmond", Kg = 0.168f, Kcal = 960f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Три лисы»", En = "Three Foxes nuts", RuF = "миндаль", EnF = "almonds", RuC = "Китай", EnC = "China", Fx = new[] { "Sinew" }, RuJ = "Три лисы с пачки смотрят хитро: орехи расколоты заранее, подвох в цене. Последний завоз был до того, как упали самолёты. Маленькая радость размером с ладонь.", EnJ = "Three foxes on the pack look sly: the nuts are pre-cracked, the catch is the price. The last delivery came before the planes fell. A small joy the size of your palm.", Rare = false },
        new Def { Id = "SanzhiHuliCashew", Kind = Kind.Snack, Shape = "bag", Mesh = "SanzhiHuli", Texture = "SanzhiHuliCashew", Kg = 0.168f, Kcal = 960f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Три лисы»", En = "Three Foxes nuts", RuF = "кешью", EnF = "cashews", RuC = "Китай", EnC = "China", Fx = new[] { "Sinew" }, RuJ = "Три лисы с пачки смотрят хитро: орехи расколоты заранее, подвох в цене. Ценник оторван: теперь это бесценно. Совесть молчит, живот поёт.", EnJ = "Three foxes on the pack look sly: the nuts are pre-cracked, the catch is the price. The price tag is torn off: it is priceless now. Conscience is silent, the belly sings.", Rare = false },
        new Def { Id = "SanzhiHuliMix", Kind = Kind.Snack, Shape = "bag", Mesh = "SanzhiHuli", Texture = "SanzhiHuliMix", Kg = 0.168f, Kcal = 960f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Три лисы»", En = "Three Foxes nuts", RuF = "ореховая смесь", EnF = "daily nuts", RuC = "Китай", EnC = "China", Fx = new[] { "Sinew" }, RuJ = "Три лисы с пачки смотрят хитро: орехи расколоты заранее, подвох в цене. Дата на шве стёрлась, и слава богу. Проверено поколениями и одной катастрофой.", EnJ = "Three foxes on the pack look sly: the nuts are pre-cracked, the catch is the price. The date on the seam has rubbed off, thank goodness. Tested by generations and one catastrophe.", Rare = false },
        new Def { Id = "SanzhiHuliWalnut", Kind = Kind.Snack, Shape = "bag", Mesh = "SanzhiHuli", Texture = "SanzhiHuliWalnut", Kg = 0.168f, Kcal = 960f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Три лисы»", En = "Three Foxes nuts", RuF = "грецкий орех", EnF = "walnuts", RuC = "Китай", EnC = "China", Fx = new[] { "Sinew" }, RuJ = "Три лисы с пачки смотрят хитро: орехи расколоты заранее, подвох в цене. Пахнет заправкой у Прибрежного шоссе. Оставьте пару штук на перевал. Не оставите.", EnJ = "Three foxes on the pack look sly: the nuts are pre-cracked, the catch is the price. It smells of the petrol station on the Coastal Highway. Save a couple for the pass. You will not.", Rare = false },
        new Def { Id = "SanzhiHuliChestnut", Kind = Kind.Snack, Shape = "bag", Mesh = "SanzhiHuli", Texture = "SanzhiHuliChestnut", Kg = 0.168f, Kcal = 960f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Три лисы»", En = "Three Foxes nuts", RuF = "каштаны", EnF = "chestnuts", RuC = "Китай", EnC = "China", Fx = new[] { "Sinew" }, RuJ = "Три лисы с пачки смотрят хитро: орехи расколоты заранее, подвох в цене. Такое возили в бардачке на дальнюю дорогу. Дороги кончились. Здесь это считается ужином при свечах.", EnJ = "Three foxes on the pack look sly: the nuts are pre-cracked, the catch is the price. People kept these in the glovebox for long drives. The drives are over. Round here this counts as a candlelit dinner.", Rare = false },
        new Def { Id = "HulaHupzOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "HulaHupz", Texture = "HulaHupzOriginal", Kg = 0.042f, Kcal = 170f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Хула Хупс»", En = "Hula Hupz onion rings", RuF = "с солью", EnF = "original", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Колечки, которые надевают на все десять пальцев и съедают по кругу. Мыши не тронули. Думайте сами. Луна светит, еда хрустит, жизнь налаживается.", EnJ = "Hoops you put on all ten fingers and eat round the clock face. The mice left it alone. Draw your own conclusions. The moon shines, the food crunches, life is looking up.", Rare = false },
        new Def { Id = "HulaHupzBeef", Kind = Kind.Snack, Shape = "bag", Mesh = "HulaHupz", Texture = "HulaHupzBeef", Kg = 0.042f, Kcal = 170f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Хула Хупс»", En = "Hula Hupz onion rings", RuF = "говядина барбекю", EnF = "bbq beef", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Колечки, которые надевают на все десять пальцев и съедают по кругу. Рыбаки брали такое на лёд вместо обеда. Снег вокруг не солёный. Это солёное.", EnJ = "Hoops you put on all ten fingers and eat round the clock face. Fishermen took this onto the ice instead of lunch. The snow around is not salty. This is.", Rare = false },
        new Def { Id = "HulaHupzVinegar", Kind = Kind.Snack, Shape = "bag", Mesh = "HulaHupz", Texture = "HulaHupzVinegar", Kg = 0.042f, Kcal = 170f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Хула Хупс»", En = "Hula Hupz onion rings", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Колечки, которые надевают на все десять пальцев и съедают по кругу. Смотритель плотины держал такое в заначке. Больше таких не делают. Совсем.", EnJ = "Hoops you put on all ten fingers and eat round the clock face. The dam keeper kept a stash of these. They do not make these any more. At all.", Rare = false },
        new Def { Id = "HulaHupzCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "HulaHupz", Texture = "HulaHupzCheese", Kg = 0.042f, Kcal = 170f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Хула Хупс»", En = "Hula Hupz onion rings", RuF = "сыр и лук", EnF = "cheese & onion", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Колечки, которые надевают на все десять пальцев и съедают по кругу. Кто-то спрятал это от детей. Дети не нашли. Открывайте тихо: у волков отличный слух.", EnJ = "Hoops you put on all ten fingers and eat round the clock face. Someone hid it from the kids. The kids never found it. Open it quietly: wolves have excellent hearing.", Rare = false },
        new Def { Id = "HulaHupzBonfire", Kind = Kind.Snack, Shape = "bag", Mesh = "HulaHupz", Texture = "HulaHupzBonfire", Kg = 0.042f, Kcal = 170f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Хула Хупс»", En = "Hula Hupz onion rings", RuF = "барбекю к Ночи костров", EnF = "bonfire night barbecue", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. В сельском магазине такое вечно заваливалось за прилавок. Одной не обойдётся, но вторая неизвестно где.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. In the village shop these kept slipping behind the counter. One won't be enough, and nobody knows where the second is.", Rare = true },
        new Def { Id = "HulaHupzSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "HulaHupz", Texture = "HulaHupzSalt", Kg = 0.042f, Kcal = 170f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Хула Хупс»", En = "Hula Hupz onion rings", RuF = "соль", EnF = "ready salted", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Колечки, которые надевают на все десять пальцев и съедают по кругу. Ждало покупателя дольше, чем тот прожил. Крошки с пола тоже считаются.", EnJ = "Hoops you put on all ten fingers and eat round the clock face. It waited for a buyer longer than the buyer lived. The crumbs on the floor count too.", Rare = false },
        new Def { Id = "HulaHupzBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "HulaHupz", Texture = "HulaHupzBacon", Kg = 0.042f, Kcal = 170f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Хула Хупс»", En = "Hula Hupz onion rings", RuF = "бекон", EnF = "smoky bacon", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Колечки, которые надевают на все десять пальцев и съедают по кругу. С материка такое больше не привезут. Запейте чаем из шиповника и считайте это обедом.", EnJ = "Hoops you put on all ten fingers and eat round the clock face. Nobody will bring this from the mainland again. Wash it down with rosehip tea and call it lunch.", Rare = false },
        new Def { Id = "HulaHupzChilli", Kind = Kind.Snack, Shape = "bag", Mesh = "HulaHupz", Texture = "HulaHupzChilli", Kg = 0.042f, Kcal = 170f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Хула Хупс»", En = "Hula Hupz onion rings", RuF = "сладкий чили", EnF = "sweet chilli", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Колечки, которые надевают на все десять пальцев и съедают по кругу. На упаковке иней, внутри всё по-прежнему. Медведю не показывать: отнимет вместе с рукой.", EnJ = "Hoops you put on all ten fingers and eat round the clock face. Frost on the wrapper, business as usual inside. Do not show the bear: he will take it, hand and all.", Rare = false },
        new Def { Id = "HulaHupzSour", Kind = Kind.Snack, Shape = "bag", Mesh = "HulaHupz", Texture = "HulaHupzSour", Kg = 0.042f, Kcal = 170f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Хула Хупс»", En = "Hula Hupz onion rings", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Колечки, которые надевают на все десять пальцев и съедают по кругу. Мороз ему нипочём: твёрже не стало, мягче тоже. Диетолог не одобрил бы. Диетолога тут нет.", EnJ = "Hoops you put on all ten fingers and eat round the clock face. The frost did nothing to it: no harder, no softer. A dietitian would not approve. There is no dietitian here.", Rare = false },
        new Def { Id = "HulaHupzBig", Kind = Kind.Snack, Shape = "bag", Mesh = "HulaHupz", Texture = "HulaHupzBig", Kg = 0.042f, Kcal = 170f, Thirst = -7f, Eat = 4f, Ru = "Луковые кольца «Хула Хупс»", En = "Hula Hupz onion rings", RuF = "большие кольца", EnF = "big hoops", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Колечки, которые надевают на все десять пальцев и съедают по кругу. Из тех времён, когда еду выбирали по вкусу. Лучше, чем кора. Проверено.", EnJ = "Hoops you put on all ten fingers and eat round the clock face. From the days when people picked food for its taste. Better than bark. Tested.", Rare = false },
        new Def { Id = "WotsitzCheesy", Kind = Kind.Snack, Shape = "bag", Mesh = "Wotsitz", Texture = "WotsitzCheesy", Kg = 0.068f, Kcal = 330f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Вотситс»", En = "Wotsitz corn puffs", RuF = "очень сырные", EnF = "really cheesy", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Сырные завитки, тающие во рту: что это такое, не знает даже название. Чей-то перекус на ночную смену, которая не кончилась. Хруст разносится до соседней долины.", EnJ = "Cheesy curls that melt in the mouth: even the name doesn't know what they are. Someone's snack for a night shift that never ended. The crunch carries to the next valley.", Rare = false },
        new Def { Id = "WotsitzHot", Kind = Kind.Snack, Shape = "bag", Mesh = "Wotsitz", Texture = "WotsitzHot", Kg = 0.068f, Kcal = 330f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Вотситс»", En = "Wotsitz corn puffs", RuF = "огненные", EnF = "flamin hot", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Сырные завитки, тающие во рту: что это такое, не знает даже название. В охотничьей вышке таким встречали рассвет. Ешьте медленно: когда ещё такое найдёте.", EnJ = "Cheesy curls that melt in the mouth: even the name doesn't know what they are. In the hunting blind they met the dawn with this. Eat slowly: who knows when you will find another.", Rare = false },
        new Def { Id = "WotsitzBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Wotsitz", Texture = "WotsitzBacon", Kg = 0.068f, Kcal = 330f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Вотситс»", En = "Wotsitz corn puffs", RuF = "бекон", EnF = "sizzling bacon", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Сырные завитки, тающие во рту: что это такое, не знает даже название. Такое носили в кармане куртки на всякий случай. Случай настал. К этому просится пиво, а есть только талый снег.", EnJ = "Cheesy curls that melt in the mouth: even the name doesn't know what they are. People carried these in a coat pocket just in case. The case has come. It begs for a beer, and there is only melted snow.", Rare = false },
        new Def { Id = "WotsitzSpooky", Kind = Kind.Snack, Shape = "bag", Mesh = "Wotsitz", Texture = "WotsitzSpooky", Kg = 0.068f, Kcal = 330f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Вотситс»", En = "Wotsitz corn puffs", RuF = "призраки с сыром", EnF = "cheesy ghosts", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Серия к Хэллоуину: редкость. Пугать тут и без неё есть кому. Прежний хозяин оставил записку: «Не трогать». Записка сгорела. Сияние на вкус не влияет. Наверное.", EnJ = "A Halloween edition: a rarity. There is plenty to scare you here without it. The last owner left a note: 'Do not touch'. The note burned. The aurora does not affect the taste. Probably.", Rare = true },
        new Def { Id = "WotsitzPrawn", Kind = Kind.Snack, Shape = "bag", Mesh = "Wotsitz", Texture = "WotsitzPrawn", Kg = 0.068f, Kcal = 330f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Вотситс»", En = "Wotsitz corn puffs", RuF = "креветочный коктейль", EnF = "prawn cocktail", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Сырные завитки, тающие во рту: что это такое, не знает даже название. Такими торговали в поезде, пока поезд ходил. После тушёнки из банки это почти ресторан.", EnJ = "Cheesy curls that melt in the mouth: even the name doesn't know what they are. They sold these on the train, while the train ran. After stew from a tin this is nearly a restaurant.", Rare = false },
        new Def { Id = "WotsitzBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Wotsitz", Texture = "WotsitzBBQ", Kg = 0.068f, Kcal = 330f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Вотситс»", En = "Wotsitz corn puffs", RuF = "барбекю", EnF = "barbecue", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Сырные завитки, тающие во рту: что это такое, не знает даже название. Сторож шахты держал такое в ящике стола. Делиться не с кем, и это впервые радует.", EnJ = "Cheesy curls that melt in the mouth: even the name doesn't know what they are. The mine watchman kept these in his desk drawer. Nobody to share with, and for once that is good news.", Rare = false },
        new Def { Id = "WotsitzGiants", Kind = Kind.Snack, Shape = "bag", Mesh = "Wotsitz", Texture = "WotsitzGiants", Kg = 0.068f, Kcal = 330f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Вотситс»", En = "Wotsitz corn puffs", RuF = "гигантские", EnF = "giants", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Сырные завитки, тающие во рту: что это такое, не знает даже название. Лавина прошла мимо, срок годности тоже. Пальцы потом оближите: зимой калории не выбрасывают.", EnJ = "Cheesy curls that melt in the mouth: even the name doesn't know what they are. The avalanche missed it, and so did the best-before date. Lick your fingers after: in winter you do not waste calories.", Rare = false },
        new Def { Id = "WotsitzSizzling", Kind = Kind.Snack, Shape = "bag", Mesh = "Wotsitz", Texture = "WotsitzSizzling", Kg = 0.068f, Kcal = 330f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Вотситс»", En = "Wotsitz corn puffs", RuF = "шкворчащий стейк", EnF = "sizzling steak", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Сырные завитки, тающие во рту: что это такое, не знает даже название. Такое всегда стояло на видном месте, поэтому никто не брал. Ворон на ветке уже ждёт свою долю.", EnJ = "Cheesy curls that melt in the mouth: even the name doesn't know what they are. These always stood in plain sight, which is why nobody took them. The crow on the branch is already waiting for its share.", Rare = false },
        new Def { Id = "WotsitzSweet", Kind = Kind.Snack, Shape = "bag", Mesh = "Wotsitz", Texture = "WotsitzSweet", Kg = 0.068f, Kcal = 330f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Вотситс»", En = "Wotsitz corn puffs", RuF = "сладкий чили", EnF = "sweet chilli", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Сырные завитки, тающие во рту: что это такое, не знает даже название. Кто-то открыл, передумал и умер. Не связано. На морозе хрустит вдвое громче.", EnJ = "Cheesy curls that melt in the mouth: even the name doesn't know what they are. Someone opened it, changed their mind and died. Unrelated. In the frost it crunches twice as loud.", Rare = false },
        new Def { Id = "KwaverzCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Kwaverz", Texture = "KwaverzCheese", Kg = 0.062f, Kcal = 290f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Квейверс»", En = "Kwaverz crisps", RuF = "сыр", EnF = "cheese", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Гнутые сырные чипсы: лёгкие настолько, что пакет держат двумя руками, чтобы не улетел. Такое вечно каталось под сиденьем пикапа. Не еда, а настроение. Настроение тоже греет.", EnJ = "Curly cheese crisps so light you hold the bag with both hands to keep it from flying off. One of these was always rolling under a pickup seat. Not food but a mood. A mood warms you too.", Rare = false },
        new Def { Id = "KwaverzPrawn", Kind = Kind.Snack, Shape = "bag", Mesh = "Kwaverz", Texture = "KwaverzPrawn", Kg = 0.062f, Kcal = 290f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Квейверс»", En = "Kwaverz crisps", RuF = "креветочный коктейль", EnF = "prawn cocktail", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Гнутые сырные чипсы: лёгкие настолько, что пакет держат двумя руками, чтобы не улетел. Привезено паромом, которого больше нет. Сытости на час, воспоминаний на неделю.", EnJ = "Curly cheese crisps so light you hold the bag with both hands to keep it from flying off. Brought over by a ferry that no longer exists. An hour of fullness, a week of memories.", Rare = false },
        new Def { Id = "KwaverzVinegar", Kind = Kind.Snack, Shape = "bag", Mesh = "Kwaverz", Texture = "KwaverzVinegar", Kg = 0.062f, Kcal = 290f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Квейверс»", En = "Kwaverz crisps", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Гнутые сырные чипсы: лёгкие настолько, что пакет держат двумя руками, чтобы не улетел. Раньше это ели под телевизор. Телевизор молчит. Кролик смотрит с осуждением.", EnJ = "Curly cheese crisps so light you hold the bag with both hands to keep it from flying off. People ate this in front of the telly. The telly is silent. The rabbit looks on with disapproval.", Rare = false },
        new Def { Id = "KwaverzXmas", Kind = Kind.Snack, Shape = "bag", Mesh = "Kwaverz", Texture = "KwaverzXmas", Kg = 0.062f, Kcal = 290f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Квейверс»", En = "Kwaverz crisps", RuF = "сыр с клюквой", EnF = "cheese & cranberry", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Забыто туристами, которым повезло уехать. У костра вкуснее. У костра всё вкуснее.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. Left behind by tourists who were lucky enough to leave. It tastes better by the fire. Everything does.", Rare = true },
        new Def { Id = "KwaverzBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Kwaverz", Texture = "KwaverzBacon", Kg = 0.062f, Kcal = 290f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Квейверс»", En = "Kwaverz crisps", RuF = "бекон", EnF = "bacon", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Гнутые сырные чипсы: лёгкие настолько, что пакет держат двумя руками, чтобы не улетел. Механики заедали этим обед, не вытирая рук. Упаковку не выбрасывайте: ею можно разжечь печь.", EnJ = "Curly cheese crisps so light you hold the bag with both hands to keep it from flying off. Mechanics ate these for lunch without wiping their hands. Keep the wrapper: it will light the stove.", Rare = false },
        new Def { Id = "KwaverzKetchup", Kind = Kind.Snack, Shape = "bag", Mesh = "Kwaverz", Texture = "KwaverzKetchup", Kg = 0.062f, Kcal = 290f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Квейверс»", En = "Kwaverz crisps", RuF = "кетчуп", EnF = "ketchup", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Гнутые сырные чипсы: лёгкие настолько, что пакет держат двумя руками, чтобы не улетел. Последнее на всю Одинокую топь. Скорее всего. Если это последняя на острове, вы её достойны.", EnJ = "Curly cheese crisps so light you hold the bag with both hands to keep it from flying off. The last one in all of Forlorn Muskeg. Most likely. If this is the last one on the island, you have earned it.", Rare = false },
        new Def { Id = "KwaverzBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Kwaverz", Texture = "KwaverzBBQ", Kg = 0.062f, Kcal = 290f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Квейверс»", En = "Kwaverz crisps", RuF = "барбекю", EnF = "barbecue", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Гнутые сырные чипсы: лёгкие настолько, что пакет держат двумя руками, чтобы не улетел. Смотритель маяка грыз такое, ожидая кораблей. Желудок удивится, но возражать не станет.", EnJ = "Curly cheese crisps so light you hold the bag with both hands to keep it from flying off. The lighthouse keeper munched these while waiting for ships. Your stomach will be surprised but will not object.", Rare = false },
        new Def { Id = "KwaverzOnion", Kind = Kind.Snack, Shape = "bag", Mesh = "Kwaverz", Texture = "KwaverzOnion", Kg = 0.062f, Kcal = 290f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Квейверс»", En = "Kwaverz crisps", RuF = "сыр и лук", EnF = "cheese & onion", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Гнутые сырные чипсы: лёгкие настолько, что пакет держат двумя руками, чтобы не улетел. Полки рушились, а это уцелело. Запах выдаёт вас за сто шагов. Оно того стоит.", EnJ = "Curly cheese crisps so light you hold the bag with both hands to keep it from flying off. Shelves collapsed and this survived. The smell gives you away at a hundred paces. Worth it.", Rare = false },
        new Def { Id = "MakKoysSteak", Kind = Kind.Snack, Shape = "bag", Mesh = "MakKoys", Texture = "MakKoysSteak", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «МакКойз»", En = "MakKoy’s ridged crisps", RuF = "стейк на огне", EnF = "flame grilled steak", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Рифлёные чипсы «для мужчин»: так было написано, никто не проверял. Смотритель заповедника называл это ужином. Раньше это называли вредным. Теперь называют едой.", EnJ = "Ridged ‘man crisps’: so it said, nobody ever checked. The park ranger called this dinner. They used to call this unhealthy. Now they call it food.", Rare = false },
        new Def { Id = "MakKoysVinegar", Kind = Kind.Snack, Shape = "bag", Mesh = "MakKoys", Texture = "MakKoysVinegar", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «МакКойз»", En = "MakKoy’s ridged crisps", RuF = "соль и солодовый уксус", EnF = "salt & malt vinegar", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Рифлёные чипсы «для мужчин»: так было написано, никто не проверял. Такое слали посылками с материка. Адресаты выбыли. Спальный мешок потом вытряхните.", EnJ = "Ridged ‘man crisps’: so it said, nobody ever checked. These came in parcels from the mainland. The addressees are gone. Shake out your sleeping bag afterwards.", Rare = false },
        new Def { Id = "MakKoysCheddar", Kind = Kind.Snack, Shape = "bag", Mesh = "MakKoys", Texture = "MakKoysCheddar", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «МакКойз»", En = "MakKoy’s ridged crisps", RuF = "чеддер и лук", EnF = "cheddar & onion", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Рифлёные чипсы «для мужчин»: так было написано, никто не проверял. Иные держали это за лекарство. Тоже лечит. Зимой такое идёт за валюту.", EnJ = "Ridged ‘man crisps’: so it said, nobody ever checked. Some people counted this as medicine. Also a cure. In winter this passes for currency.", Rare = false },
        new Def { Id = "MakKoysThai", Kind = Kind.Snack, Shape = "bag", Mesh = "MakKoys", Texture = "MakKoysThai", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «МакКойз»", En = "MakKoy’s ridged crisps", RuF = "тайская сладкая курица", EnF = "thai sweet chicken", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Рифлёные чипсы «для мужчин»: так было написано, никто не проверял. В школьном рюкзаке такое не доживало до обеда. Торговец дал бы за это тряпку. Вы дадите больше.", EnJ = "Ridged ‘man crisps’: so it said, nobody ever checked. In a school bag this never lasted till lunch. The trader would give a rag for it. You would give more.", Rare = false },
        new Def { Id = "MakKoysSummer", Kind = Kind.Snack, Shape = "bag", Mesh = "MakKoys", Texture = "MakKoysSummer", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «МакКойз»", En = "MakKoy’s ridged crisps", RuF = "летний стейк с дымком", EnF = "summer smoky steak", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Его обменяли бы на патрон, будь тут с кем меняться. Пока жуёте, метель кажется короче.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. You could trade it for a cartridge, if there were anyone to trade with. While you chew, the blizzard seems shorter.", Rare = true },
        new Def { Id = "MakKoysSalted", Kind = Kind.Snack, Shape = "bag", Mesh = "MakKoys", Texture = "MakKoysSalted", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «МакКойз»", En = "MakKoy’s ridged crisps", RuF = "соль", EnF = "salted", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Рифлёные чипсы «для мужчин»: так было написано, никто не проверял. На вокзале это стоило втрое дороже. Теперь даром. Организм скажет спасибо. Или не скажет.", EnJ = "Ridged ‘man crisps’: so it said, nobody ever checked. At the station it cost three times as much. Now it is free. Your body will thank you. Or not.", Rare = false },
        new Def { Id = "MakKoysPrawn", Kind = Kind.Snack, Shape = "bag", Mesh = "MakKoys", Texture = "MakKoysPrawn", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «МакКойз»", En = "MakKoy’s ridged crisps", RuF = "королевская креветка", EnF = "king prawn", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Рифлёные чипсы «для мужчин»: так было написано, никто не проверял. Пережило толчок и даже не помялось. На третьей горсти забываешь, что вокруг конец света.", EnJ = "Ridged ‘man crisps’: so it said, nobody ever checked. It came through the quake without a dent. By the third handful you forget the world has ended.", Rare = false },
        new Def { Id = "MakKoysBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "MakKoys", Texture = "MakKoysBacon", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «МакКойз»", En = "MakKoy’s ridged crisps", RuF = "бекон на гриле", EnF = "grilled bacon", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Рифлёные чипсы «для мужчин»: так было написано, никто не проверял. Китобои такого не ели, но оценили бы. Рыба подо льдом завидует.", EnJ = "Ridged ‘man crisps’: so it said, nobody ever checked. The whalers never ate this, but they would have approved. The fish under the ice are jealous.", Rare = false },
        new Def { Id = "MakKoysRibs", Kind = Kind.Snack, Shape = "bag", Mesh = "MakKoys", Texture = "MakKoysRibs", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «МакКойз»", En = "MakKoy’s ridged crisps", RuF = "рёбрышки", EnF = "barbecue ribs", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Рифлёные чипсы «для мужчин»: так было написано, никто не проверял. Осталось после чьего-то дня рождения. Гости не пришли. Олень от такого отказался бы. Олень не голодал.", EnJ = "Ridged ‘man crisps’: so it said, nobody ever checked. Left over from someone's birthday. The guests never came. A deer would turn it down. A deer has never starved.", Rare = false },
        new Def { Id = "MakKoysChilli", Kind = Kind.Snack, Shape = "bag", Mesh = "MakKoys", Texture = "MakKoysChilli", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «МакКойз»", En = "MakKoy’s ridged crisps", RuF = "мексиканский чили", EnF = "mexican chilli", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Рифлёные чипсы «для мужчин»: так было написано, никто не проверял. Мерзлота хранит лучше любого холодильника. Соль есть, жир есть, совести нет.", EnJ = "Ridged ‘man crisps’: so it said, nobody ever checked. Permafrost keeps things better than any fridge. Salt: yes. Fat: yes. Conscience: none.", Rare = false },
        new Def { Id = "MakKoysCurry", Kind = Kind.Snack, Shape = "bag", Mesh = "MakKoys", Texture = "MakKoysCurry", Kg = 0.053f, Kcal = 240f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «МакКойз»", En = "MakKoy’s ridged crisps", RuF = "карри", EnF = "curry", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Рифлёные чипсы «для мужчин»: так было написано, никто не проверял. Такое добывали из автомата, который съедал последнюю монету. Ешьте до темноты: в темноте крошки не найти.", EnJ = "Ridged ‘man crisps’: so it said, nobody ever checked. These came from the vending machine that ate your last coin. Eat before dark: you cannot find crumbs in the dark.", Rare = false },
        new Def { Id = "LorentzPaprika", Kind = Kind.Snack, Shape = "bag", Mesh = "Lorentz", Texture = "LorentzPaprika", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Кранчипс»", En = "Kranchips ridged crisps", RuF = "паприка", EnF = "paprika", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкие рифлёные чипсы: волна к волне, как по линейке. Такое брали в лодку под брезент, на весь день. Лучшее, что случится с вами сегодня.", EnJ = "German ridged crisps: wave to wave, as if by ruler. People took these out in the boat under the tarpaulin, for the whole day. The best thing that will happen to you today.", Rare = false },
        new Def { Id = "LorentzWestern", Kind = Kind.Snack, Shape = "bag", Mesh = "Lorentz", Texture = "LorentzWestern", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Кранчипс»", En = "Kranchips ridged crisps", RuF = "вестерн", EnF = "western style", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкие рифлёные чипсы: волна к волне, как по линейке. С ним кто-то шёл к перевалу и не дошёл. Для полного счастья не хватает только дивана.", EnJ = "German ridged crisps: wave to wave, as if by ruler. Someone carried it towards the pass and never arrived. All that is missing for perfect happiness is a sofa.", Rare = false },
        new Def { Id = "LorentzCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Lorentz", Texture = "LorentzCheese", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Кранчипс»", En = "Kranchips ridged crisps", RuF = "сыр и лук", EnF = "cheese & onion", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкие рифлёные чипсы: волна к волне, как по линейке. С таким сидели у окна с видом на метель. Вкус детства, если детство было так себе.", EnJ = "German ridged crisps: wave to wave, as if by ruler. People sat with these at a window with a view of the blizzard. The taste of childhood, if childhood was so-so.", Rare = false },
        new Def { Id = "LorentzSalted", Kind = Kind.Snack, Shape = "bag", Mesh = "Lorentz", Texture = "LorentzSalted", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Кранчипс»", En = "Kranchips ridged crisps", RuF = "с солью", EnF = "salted", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкие рифлёные чипсы: волна к волне, как по линейке. Уцелело там, где сгорело всё остальное. Шуршит как надежда.", EnJ = "German ridged crisps: wave to wave, as if by ruler. It survived where everything else burned. It rustles like hope.", Rare = false },
        new Def { Id = "LorentzOktoberfest", Kind = Kind.Snack, Shape = "bag", Mesh = "Lorentz", Texture = "LorentzOktoberfest", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Кранчипс»", En = "Kranchips ridged crisps", RuF = "брецель и обацда", EnF = "pretzel & obatzda", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Этим кормили сторожевого пса. Пёс ушёл в волки. Голод отступит, жажда придёт. Честный обмен.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. They fed the guard dog with this. The dog joined the wolves. Hunger leaves, thirst arrives. A fair trade.", Rare = true },
        new Def { Id = "LorentzWeihnacht", Kind = Kind.Snack, Shape = "bag", Mesh = "Lorentz", Texture = "LorentzWeihnacht", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Кранчипс»", En = "Kranchips ridged crisps", RuF = "рождественский гусь", EnF = "christmas goose", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Из запасов лесорубов: брали ящиками. Не согреет, зато отвлечёт.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. From the loggers' stores: they bought it by the crate. It will not warm you, but it will distract you.", Rare = true },
        new Def { Id = "LorentzSour", Kind = Kind.Snack, Shape = "bag", Mesh = "Lorentz", Texture = "LorentzSour", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Кранчипс»", En = "Kranchips ridged crisps", RuF = "сметана", EnF = "sour cream", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкие рифлёные чипсы: волна к волне, как по линейке. В пост такое не ели. Пост кончился вместе с миром. Пума предпочитает мясо. Вам повезло.", EnJ = "German ridged crisps: wave to wave, as if by ruler. Nobody ate these during a fast. The fast ended with the world. The cougar prefers meat. Lucky you.", Rare = false },
        new Def { Id = "LorentzChili", Kind = Kind.Snack, Shape = "bag", Mesh = "Lorentz", Texture = "LorentzChili", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Кранчипс»", En = "Kranchips ridged crisps", RuF = "сладкий чили", EnF = "sweet chilli", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Немецкие рифлёные чипсы: волна к волне, как по линейке. Теперь это ценнее денег. Деньги оставьте. Сначала попробуйте одну штучку. Шутка: ешьте всё.", EnJ = "German ridged crisps: wave to wave, as if by ruler. It is worth more than money now. Leave the money. Try just one first. Joke: eat the lot.", Rare = false },
        new Def { Id = "LorentzKebab", Kind = Kind.Snack, Shape = "bag", Mesh = "Lorentz", Texture = "LorentzKebab", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Кранчипс»", En = "Kranchips ridged crisps", RuF = "кебаб", EnF = "kebab", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкие рифлёные чипсы: волна к волне, как по линейке. Его несли на пикник. Пикник отменили навсегда. Такой ужин не стыдно записать в дневник.", EnJ = "German ridged crisps: wave to wave, as if by ruler. It was headed for a picnic. The picnic is cancelled forever. A dinner worth writing in the journal.", Rare = false },
        new Def { Id = "LorentzAfrican", Kind = Kind.Snack, Shape = "bag", Mesh = "Lorentz", Texture = "LorentzAfrican", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Кранчипс»", En = "Kranchips ridged crisps", RuF = "африканские специи", EnF = "african spice", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкие рифлёные чипсы: волна к волне, как по линейке. Такое стояло у кассы на случай слабости. Силы прибавит на один сугроб.", EnJ = "German ridged crisps: wave to wave, as if by ruler. These stood by the till for moments of weakness. It will carry you one snowdrift further.", Rare = false },
        new Def { Id = "LorentzPommes", Kind = Kind.Snack, Shape = "bag", Mesh = "Lorentz", Texture = "LorentzPommes", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Кранчипс»", En = "Kranchips ridged crisps", RuF = "картошка фри", EnF = "fries", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкие рифлёные чипсы: волна к волне, как по линейке. Досталось вам, потому что вы дошли первым. Идеально к закату, которого не видно за бураном.", EnJ = "German ridged crisps: wave to wave, as if by ruler. It is yours because you got here first. Perfect with a sunset you cannot see for the storm.", Rare = false },
        new Def { Id = "LorentzBarbecue", Kind = Kind.Snack, Shape = "bag", Mesh = "Lorentz", Texture = "LorentzBarbecue", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Кранчипс»", En = "Kranchips ridged crisps", RuF = "барбекю", EnF = "barbecue", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкие рифлёные чипсы: волна к волне, как по линейке. Упаковка выцвела, внутри время остановилось. Пахнет магазином. Помните магазины?", EnJ = "German ridged crisps: wave to wave, as if by ruler. The wrapper has faded; inside, time stood still. It smells of a shop. Remember shops?", Rare = false },
        new Def { Id = "PomBerOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "PomBer", Texture = "PomBerOriginal", Kg = 0.083f, Kcal = 400f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пом-Бер»", En = "Pom-Bär crisps", RuF = "оригинальные", EnF = "original", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Чипсы в форме медвежат: первым откусывают ухо, так принято. Из чемодана пассажира, который не долетел. Мороз не испортил, время не взяло.", EnJ = "Bear-shaped crisps: the ear goes first, that's the custom. From the suitcase of a passenger who never landed. Frost did not spoil it and time could not take it.", Rare = false },
        new Def { Id = "PomBerKetchup", Kind = Kind.Snack, Shape = "bag", Mesh = "PomBer", Texture = "PomBerKetchup", Kg = 0.083f, Kcal = 400f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пом-Бер»", En = "Pom-Bär crisps", RuF = "кетчуп", EnF = "ketchup", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Чипсы в форме медвежат: первым откусывают ухо, так принято. Перезимовало и ничуть не обиделось. В рюкзаке не мнётся. Почти.", EnJ = "Bear-shaped crisps: the ear goes first, that's the custom. It made it through the winter and bears no grudge. It does not get crushed in a pack. Almost.", Rare = false },
        new Def { Id = "PomBerSour", Kind = Kind.Snack, Shape = "bag", Mesh = "PomBer", Texture = "PomBerSour", Kg = 0.083f, Kcal = 400f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пом-Бер»", En = "Pom-Bär crisps", RuF = "сметана", EnF = "sour cream", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Чипсы в форме медвежат: первым откусывают ухо, так принято. Запасливая хозяйка купила по акции шесть штук. Съешьте сейчас: завтра может не быть аппетита.", EnJ = "Bear-shaped crisps: the ear goes first, that's the custom. A thrifty housewife bought six of these on offer. Eat it now: tomorrow you may have no appetite.", Rare = false },
        new Def { Id = "PomBerPaprika", Kind = Kind.Snack, Shape = "bag", Mesh = "PomBer", Texture = "PomBerPaprika", Kg = 0.083f, Kcal = 400f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пом-Бер»", En = "Pom-Bär crisps", RuF = "паприка", EnF = "paprika", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Чипсы в форме медвежат: первым откусывают ухо, так принято. Кто-то написал на упаковке «моё». Уже нет. Хватит дойти до следующей хижины и пожалеть, что кончилось.", EnJ = "Bear-shaped crisps: the ear goes first, that's the custom. Someone wrote 'mine' on it. Not any more. Enough to reach the next cabin and regret it is gone.", Rare = false },
        new Def { Id = "PomBerKase", Kind = Kind.Snack, Shape = "bag", Mesh = "PomBer", Texture = "PomBerKase", Kg = 0.083f, Kcal = 400f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пом-Бер»", En = "Pom-Bär crisps", RuF = "сыр", EnF = "cheese", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Чипсы в форме медвежат: первым откусывают ухо, так принято. В консервном цеху это ели тайком от мастера. От такого не толстеют те, кто ходит по двадцать километров.", EnJ = "Bear-shaped crisps: the ear goes first, that's the custom. At the cannery they ate this behind the foreman's back. Nobody who walks twenty kilometres a day gets fat on this.", Rare = false },
        new Def { Id = "PomBerBarbecue", Kind = Kind.Snack, Shape = "bag", Mesh = "PomBer", Texture = "PomBerBarbecue", Kg = 0.083f, Kcal = 400f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пом-Бер»", En = "Pom-Bär crisps", RuF = "барбекю", EnF = "barbecue", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Чипсы в форме медвежат: первым откусывают ухо, так принято. Его не взяли даже мародёры. Они спешили. Волчья стая не в курсе. Пусть так и будет.", EnJ = "Bear-shaped crisps: the ear goes first, that's the custom. Even the looters left it. They were in a hurry. The wolf pack does not know. Keep it that way.", Rare = false },
        new Def { Id = "PomBerSchoko", Kind = Kind.Snack, Shape = "bag", Mesh = "PomBer", Texture = "PomBerSchoko", Kg = 0.083f, Kcal = 400f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пом-Бер»", En = "Pom-Bär crisps", RuF = "шоколадные", EnF = "chocolate", RuC = "Германия", EnC = "Germany", Fx = new[] { "SugarDry" }, RuJ = "Чипсы в форме медвежат: первым откусывают ухо, так принято. Провело зиму на острове, как и вы. Пёс бы выпросил половину. Пса нет.", EnJ = "Bear-shaped crisps: the ear goes first, that's the custom. It spent the winter on the island, same as you. A dog would beg half of it. There is no dog.", Rare = false },
        new Def { Id = "NikNaksOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "NikNaks", Texture = "NikNaksOriginal", Kg = 0.133f, Kcal = 650f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «НикНакс»", En = "NikNak’s coated peanuts", RuF = "паприка", EnF = "original paprika", RuC = "Германия", EnC = "Germany", Fx = new[] { "Sinew" }, RuJ = "Арахис в хрустящей шубе: орех оделся теплее, чем я. Дети прятали такое под кроватью, в тайнике. Лекарство от тоски, отпускается без рецепта.", EnJ = "Peanuts in a crunchy coat: the nut is dressed warmer than I am. Children hid these under the bed, in a secret place. A cure for the blues, no prescription needed.", Rare = false },
        new Def { Id = "NikNaksDouble", Kind = Kind.Snack, Shape = "bag", Mesh = "NikNaks", Texture = "NikNaksDouble", Kg = 0.133f, Kcal = 650f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «НикНакс»", En = "NikNak’s coated peanuts", RuF = "двойной хруст", EnF = "double crunch", RuC = "Германия", EnC = "Germany", Fx = new[] { "Sinew" }, RuJ = "Арахис в хрустящей шубе: орех оделся теплее, чем я. Осталось от геологов вместе с картой и долгами. Жуйте и думайте о хорошем. Например, о добавке.", EnJ = "Peanuts in a crunchy coat: the nut is dressed warmer than I am. Left by the geologists along with a map and some debts. Chew and think of nice things. Seconds, for example.", Rare = false },
        new Def { Id = "NikNaksBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "NikNaks", Texture = "NikNaksBBQ", Kg = 0.133f, Kcal = 650f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «НикНакс»", En = "NikNak’s coated peanuts", RuF = "барбекю", EnF = "barbecue", RuC = "Германия", EnC = "Germany", Fx = new[] { "Sinew" }, RuJ = "Арахис в хрустящей шубе: орех оделся теплее, чем я. На острове такое было праздником и до катастрофы. К утру от него останется только запах на варежках.", EnJ = "Peanuts in a crunchy coat: the nut is dressed warmer than I am. On the island this was a treat even before the disaster. By morning only the smell on your mittens will be left.", Rare = false },
        new Def { Id = "NikNaksSweet", Kind = Kind.Snack, Shape = "bag", Mesh = "NikNaks", Texture = "NikNaksSweet", Kg = 0.133f, Kcal = 650f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «НикНакс»", En = "NikNak’s coated peanuts", RuF = "сладкий чили", EnF = "sweet chilli", RuC = "Германия", EnC = "Germany", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Арахис в хрустящей шубе: орех оделся теплее, чем я. С таким слушали радио, которое теперь ловит только треск. Тишина вокруг такая, что слышно, как вы жуёте.", EnJ = "Peanuts in a crunchy coat: the nut is dressed warmer than I am. People ate these by the radio, which picks up nothing but crackle now. It is so quiet you can hear yourself chew.", Rare = false },
        new Def { Id = "NikNaksWasabi", Kind = Kind.Snack, Shape = "bag", Mesh = "NikNaks", Texture = "NikNaksWasabi", Kg = 0.133f, Kcal = 650f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «НикНакс»", En = "NikNak’s coated peanuts", RuF = "васаби", EnF = "wasabi", RuC = "Германия", EnC = "Germany", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Арахис в хрустящей шубе: орех оделся теплее, чем я. Крысы прогрызли соседнюю, эту пощадили. Не делите на завтра: завтра будет новый голод.", EnJ = "Peanuts in a crunchy coat: the nut is dressed warmer than I am. The rats gnawed through the one next to it and spared this. Do not save half for tomorrow: tomorrow brings its own hunger.", Rare = false },
        new Def { Id = "NikNaksPaprika", Kind = Kind.Snack, Shape = "bag", Mesh = "NikNaks", Texture = "NikNaksPaprika", Kg = 0.133f, Kcal = 650f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «НикНакс»", En = "NikNak’s coated peanuts", RuF = "паприка", EnF = "paprika", RuC = "Германия", EnC = "Germany", Fx = new[] { "Sinew" }, RuJ = "Арахис в хрустящей шубе: орех оделся теплее, чем я. Бывший хозяин клялся бросить. Не успел. Сосны вокруг делают вид, что не смотрят.", EnJ = "Peanuts in a crunchy coat: the nut is dressed warmer than I am. The former owner swore to give these up. He ran out of time. The pines around pretend not to watch.", Rare = false },
        new Def { Id = "NikNaksCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "NikNaks", Texture = "NikNaksCheese", Kg = 0.133f, Kcal = 650f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «НикНакс»", En = "NikNak’s coated peanuts", RuF = "сыр", EnF = "cheese", RuC = "Германия", EnC = "Germany", Fx = new[] { "Sinew" }, RuJ = "Арахис в хрустящей шубе: орех оделся теплее, чем я. Его катали в кабине трактора три сезона. Калории мелкие, зато свои.", EnJ = "Peanuts in a crunchy coat: the nut is dressed warmer than I am. It rode around in a tractor cab for three seasons. Small calories, but your own.", Rare = false },
        new Def { Id = "UltcheSalted", Kind = Kind.Snack, Shape = "can", Mesh = "Ultche", Texture = "UltcheSalted", Kg = 0.23f, Kcal = 1200f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Ильтье»", En = "Ültche nuts", RuF = "солёный", EnF = "salted", RuC = "Германия", EnC = "Germany", Fx = new[] { "Sinew" }, RuJ = "Немецкие орешки в банке: крышка щёлкает, вечер начинается. После бани такое шло лучше всего. После этого даже крапивный чай покажется десертом.", EnJ = "German nuts in a can: the lid clicks, the evening begins. Nothing went down better after the sauna. After this even nettle tea feels like dessert.", Rare = false },
        new Def { Id = "UltchePlain", Kind = Kind.Snack, Shape = "can", Mesh = "Ultche", Texture = "UltchePlain", Kg = 0.23f, Kcal = 1200f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Ильтье»", En = "Ültche nuts", RuF = "без соли", EnF = "unsalted", RuC = "Германия", EnC = "Germany", Fx = new[] { "Sinew" }, RuJ = "Немецкие орешки в банке: крышка щёлкает, вечер начинается. В тюрьме на это выменивали что угодно. Нашедшему полагается всё.", EnJ = "German nuts in a can: the lid clicks, the evening begins. In the prison you could trade one of these for anything. Finders keepers, all of it.", Rare = false },
        new Def { Id = "UltcheSpicy", Kind = Kind.Snack, Shape = "can", Mesh = "Ultche", Texture = "UltcheSpicy", Kg = 0.23f, Kcal = 1200f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Ильтье»", En = "Ültche nuts", RuF = "пикантный", EnF = "spicy", RuC = "Германия", EnC = "Germany", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Немецкие орешки в банке: крышка щёлкает, вечер начинается. Кто-то менял это на сигареты. Сделка сорвалась. Зубы целы? Тогда вперёд.", EnJ = "German nuts in a can: the lid clicks, the evening begins. Someone was trading this for cigarettes. The deal fell through. Teeth intact? Then go ahead.", Rare = false },
        new Def { Id = "UltcheHonig", Kind = Kind.Snack, Shape = "can", Mesh = "Ultche", Texture = "UltcheHonig", Kg = 0.23f, Kcal = 1200f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Ильтье»", En = "Ültche nuts", RuF = "мёд и соль", EnF = "honey & salt", RuC = "Германия", EnC = "Germany", Fx = new[] { "SugarDry" }, RuJ = "Немецкие орешки в банке: крышка щёлкает, вечер начинается. С ним зимовали на метеостанции, пока было с кем. Ночью приснится добавка.", EnJ = "German nuts in a can: the lid clicks, the evening begins. They wintered with it at the weather station, while there was a 'they'. Tonight you will dream of seconds.", Rare = false },
        new Def { Id = "UltchePaprika", Kind = Kind.Snack, Shape = "can", Mesh = "Ultche", Texture = "UltchePaprika", Kg = 0.23f, Kcal = 1200f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Ильтье»", En = "Ültche nuts", RuF = "паприка", EnF = "paprika", RuC = "Германия", EnC = "Germany", Fx = new[] { "Sinew" }, RuJ = "Немецкие орешки в банке: крышка щёлкает, вечер начинается. Такое терялось в кладовке среди крупы и надежд. С таким запасом можно пережить ещё один вечер.", EnJ = "German nuts in a can: the lid clicks, the evening begins. These got lost in the pantry among the grain and the hopes. With supplies like this you can survive one more evening.", Rare = false },
        new Def { Id = "UltcheCashew", Kind = Kind.Snack, Shape = "can", Mesh = "Ultche", Texture = "UltcheCashew", Kg = 0.23f, Kcal = 1200f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Ильтье»", En = "Ültche nuts", RuF = "кешью", EnF = "cashews", RuC = "Германия", EnC = "Germany", Fx = new[] { "Sinew" }, RuJ = "Немецкие орешки в банке: крышка щёлкает, вечер начинается. Его берегли к приезду внуков. Пёс бы выпросил половину. Пса нет.", EnJ = "German nuts in a can: the lid clicks, the evening begins. It was being saved for the grandchildren's visit. A dog would beg half of it. There is no dog.", Rare = false },
        new Def { Id = "UltcheMix", Kind = Kind.Snack, Shape = "can", Mesh = "Ultche", Texture = "UltcheMix", Kg = 0.23f, Kcal = 1200f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Ильтье»", En = "Ültche nuts", RuF = "ореховая смесь", EnF = "nut mix", RuC = "Германия", EnC = "Germany", Fx = new[] { "Sinew" }, RuJ = "Немецкие орешки в банке: крышка щёлкает, вечер начинается. В баре такое ставили на стойку, бесплатно к пиву. Пива нет. Съедено будет быстрее, чем найдено.", EnJ = "German nuts in a can: the lid clicks, the evening begins. Bars put these out free with a beer. There is no beer. It will be eaten faster than it was found.", Rare = false },
        new Def { Id = "UltcheWasabi", Kind = Kind.Snack, Shape = "can", Mesh = "Ultche", Texture = "UltcheWasabi", Kg = 0.23f, Kcal = 1200f, Thirst = -8f, Eat = 6f, Ru = "Орешки «Ильтье»", En = "Ültche nuts", RuF = "васаби", EnF = "wasabi", RuC = "Германия", EnC = "Germany", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Немецкие орешки в банке: крышка щёлкает, вечер начинается. Такое лежало в каждом доме, пока не погас свет. На вкус как выходной.", EnJ = "German nuts in a can: the lid clicks, the evening begins. Every house had one of these until the lights went out. It tastes like a day off.", Rare = false },
        new Def { Id = "BarselFuego", Kind = Kind.Snack, Shape = "bag", Mesh = "Barsel", Texture = "BarselFuego", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Чипс Барсель»", En = "Chips Barsel crisps", RuF = "огонь", EnF = "fuego", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Мексиканские чипсы из котла: соус в отдельном пакетике, потому что доверяют. Кто-то берёг это на чёрный день. Он настал. Ветер унесёт запах прямо к берлоге. Ешьте быстрее.", EnJ = "Mexican kettle crisps: the sauce comes in its own sachet, because they trust you. Someone saved this for a rainy day. It came. The wind carries the smell straight to the den. Eat faster.", Rare = false },
        new Def { Id = "BarselJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "Barsel", Texture = "BarselJalapeno", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Чипс Барсель»", En = "Chips Barsel crisps", RuF = "халапеньо", EnF = "jalapeno", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Мексиканские чипсы из котла: соус в отдельном пакетике, потому что доверяют. Пережило хозяина, кота и две зимы. Пополняет запас соли и веры в человечество.", EnJ = "Mexican kettle crisps: the sauce comes in its own sachet, because they trust you. It outlived its owner, the cat and two winters. Restores your salt and your faith in mankind.", Rare = false },
        new Def { Id = "BarselSal", Kind = Kind.Snack, Shape = "bag", Mesh = "Barsel", Texture = "BarselSal", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Чипс Барсель»", En = "Chips Barsel crisps", RuF = "морская соль", EnF = "sea salt", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold" }, RuJ = "Мексиканские чипсы из котла: соус в отдельном пакетике, потому что доверяют. Такое обычно находили за диваном, как всё лучшее в жизни. Хорошо идёт под треск поленьев.", EnJ = "Mexican kettle crisps: the sauce comes in its own sachet, because they trust you. These were usually found behind the sofa, like all the best things in life. Goes down well with crackling logs.", Rare = false },
        new Def { Id = "BarselAdobadas", Kind = Kind.Snack, Shape = "bag", Mesh = "Barsel", Texture = "BarselAdobadas", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Чипс Барсель»", En = "Chips Barsel crisps", RuF = "адобо", EnF = "adobadas", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Мексиканские чипсы из котла: соус в отдельном пакетике, потому что доверяют. Последний завоз был до того, как упали самолёты. Руки вытирать о штаны: салфеток не завезли.", EnJ = "Mexican kettle crisps: the sauce comes in its own sachet, because they trust you. The last delivery came before the planes fell. Wipe your hands on your trousers: no napkins were delivered.", Rare = false },
        new Def { Id = "BarselNavidad", Kind = Kind.Snack, Shape = "bag", Mesh = "Barsel", Texture = "BarselNavidad", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Чипс Барсель»", En = "Chips Barsel crisps", RuF = "рождественский чипотле", EnF = "christmas chipotle", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Ценник оторван: теперь это бесценно. Маленькая радость размером с ладонь.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. The price tag is torn off: it is priceless now. A small joy the size of your palm.", Rare = true },
        new Def { Id = "BarselVerano", Kind = Kind.Snack, Shape = "bag", Mesh = "Barsel", Texture = "BarselVerano", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Чипс Барсель»", En = "Chips Barsel crisps", RuF = "летний манго с чили", EnF = "summer mango chilli", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Дата на шве стёрлась, и слава богу. Совесть молчит, живот поёт.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. The date on the seam has rubbed off, thank goodness. Conscience is silent, the belly sings.", Rare = true },
        new Def { Id = "BarselQueso", Kind = Kind.Snack, Shape = "bag", Mesh = "Barsel", Texture = "BarselQueso", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Чипс Барсель»", En = "Chips Barsel crisps", RuF = "сыр", EnF = "cheese", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold" }, RuJ = "Мексиканские чипсы из котла: соус в отдельном пакетике, потому что доверяют. Пахнет заправкой у Прибрежного шоссе. Проверено поколениями и одной катастрофой.", EnJ = "Mexican kettle crisps: the sauce comes in its own sachet, because they trust you. It smells of the petrol station on the Coastal Highway. Tested by generations and one catastrophe.", Rare = false },
        new Def { Id = "BarselToreadas", Kind = Kind.Snack, Shape = "bag", Mesh = "Barsel", Texture = "BarselToreadas", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Чипс Барсель»", En = "Chips Barsel crisps", RuF = "жареный чили", EnF = "roasted chilli", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Мексиканские чипсы из котла: соус в отдельном пакетике, потому что доверяют. Такое возили в бардачке на дальнюю дорогу. Дороги кончились. Оставьте пару штук на перевал. Не оставите.", EnJ = "Mexican kettle crisps: the sauce comes in its own sachet, because they trust you. People kept these in the glovebox for long drives. The drives are over. Save a couple for the pass. You will not.", Rare = false },
        new Def { Id = "BarselDiabla", Kind = Kind.Snack, Shape = "bag", Mesh = "Barsel", Texture = "BarselDiabla", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Чипс Барсель»", En = "Chips Barsel crisps", RuF = "дьявольски острые", EnF = "devil hot", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Мексиканские чипсы из котла: соус в отдельном пакетике, потому что доверяют. Мыши не тронули. Думайте сами. Здесь это считается ужином при свечах.", EnJ = "Mexican kettle crisps: the sauce comes in its own sachet, because they trust you. The mice left it alone. Draw your own conclusions. Round here this counts as a candlelit dinner.", Rare = false },
        new Def { Id = "BarselLimon", Kind = Kind.Snack, Shape = "bag", Mesh = "Barsel", Texture = "BarselLimon", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Чипс Барсель»", En = "Chips Barsel crisps", RuF = "лимон", EnF = "lemon", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold" }, RuJ = "Мексиканские чипсы из котла: соус в отдельном пакетике, потому что доверяют. Рыбаки брали такое на лёд вместо обеда. Луна светит, еда хрустит, жизнь налаживается.", EnJ = "Mexican kettle crisps: the sauce comes in its own sachet, because they trust you. Fishermen took this onto the ice instead of lunch. The moon shines, the food crunches, life is looking up.", Rare = false },
        new Def { Id = "BarselWavy", Kind = Kind.Snack, Shape = "bag", Mesh = "Barsel", Texture = "BarselWavy", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Чипс Барсель»", En = "Chips Barsel crisps", RuF = "волнистые сыр", EnF = "wavy cheese", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold" }, RuJ = "Мексиканские чипсы из котла: соус в отдельном пакетике, потому что доверяют. Смотритель плотины держал такое в заначке. Снег вокруг не солёный. Это солёное.", EnJ = "Mexican kettle crisps: the sauce comes in its own sachet, because they trust you. The dam keeper kept a stash of these. The snow around is not salty. This is.", Rare = false },
        new Def { Id = "NishikavaClasico", Kind = Kind.Snack, Shape = "bag", Mesh = "Nishikava", Texture = "NishikavaClasico", Kg = 0.188f, Kcal = 940f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «Нишикава»", En = "Nishikava coated peanuts", RuF = "классический", EnF = "classic", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "Sinew" }, RuJ = "Японский арахис, придуманный в Мексике. География вышла покурить. Кто-то спрятал это от детей. Дети не нашли. Больше таких не делают. Совсем.", EnJ = "Japanese peanuts invented in Mexico. Geography stepped out for a smoke. Someone hid it from the kids. The kids never found it. They do not make these any more. At all.", Rare = false },
        new Def { Id = "NishikavaLimon", Kind = Kind.Snack, Shape = "bag", Mesh = "Nishikava", Texture = "NishikavaLimon", Kg = 0.188f, Kcal = 940f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «Нишикава»", En = "Nishikava coated peanuts", RuF = "лимон", EnF = "lime", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "Sinew" }, RuJ = "Японский арахис, придуманный в Мексике. География вышла покурить. В сельском магазине такое вечно заваливалось за прилавок. Открывайте тихо: у волков отличный слух.", EnJ = "Japanese peanuts invented in Mexico. Geography stepped out for a smoke. In the village shop these kept slipping behind the counter. Open it quietly: wolves have excellent hearing.", Rare = false },
        new Def { Id = "NishikavaEnchilado", Kind = Kind.Snack, Shape = "bag", Mesh = "Nishikava", Texture = "NishikavaEnchilado", Kg = 0.188f, Kcal = 940f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «Нишикава»", En = "Nishikava coated peanuts", RuF = "с чили", EnF = "chilli", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Японский арахис, придуманный в Мексике. География вышла покурить. Ждало покупателя дольше, чем тот прожил. Одной не обойдётся, но вторая неизвестно где.", EnJ = "Japanese peanuts invented in Mexico. Geography stepped out for a smoke. It waited for a buyer longer than the buyer lived. One won't be enough, and nobody knows where the second is.", Rare = false },
        new Def { Id = "NishikavaHabanero", Kind = Kind.Snack, Shape = "bag", Mesh = "Nishikava", Texture = "NishikavaHabanero", Kg = 0.188f, Kcal = 940f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «Нишикава»", En = "Nishikava coated peanuts", RuF = "хабанеро", EnF = "habanero", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Японский арахис, придуманный в Мексике. География вышла покурить. С материка такое больше не привезут. Крошки с пола тоже считаются.", EnJ = "Japanese peanuts invented in Mexico. Geography stepped out for a smoke. Nobody will bring this from the mainland again. The crumbs on the floor count too.", Rare = false },
        new Def { Id = "NishikavaSalado", Kind = Kind.Snack, Shape = "bag", Mesh = "Nishikava", Texture = "NishikavaSalado", Kg = 0.188f, Kcal = 940f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «Нишикава»", En = "Nishikava coated peanuts", RuF = "солёный", EnF = "salted", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "Sinew" }, RuJ = "Японский арахис, придуманный в Мексике. География вышла покурить. На упаковке иней, внутри всё по-прежнему. Запейте чаем из шиповника и считайте это обедом.", EnJ = "Japanese peanuts invented in Mexico. Geography stepped out for a smoke. Frost on the wrapper, business as usual inside. Wash it down with rosehip tea and call it lunch.", Rare = false },
        new Def { Id = "NishikavaChipotle", Kind = Kind.Snack, Shape = "bag", Mesh = "Nishikava", Texture = "NishikavaChipotle", Kg = 0.188f, Kcal = 940f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «Нишикава»", En = "Nishikava coated peanuts", RuF = "чипотле", EnF = "chipotle", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Японский арахис, придуманный в Мексике. География вышла покурить. Мороз ему нипочём: твёрже не стало, мягче тоже. Медведю не показывать: отнимет вместе с рукой.", EnJ = "Japanese peanuts invented in Mexico. Geography stepped out for a smoke. The frost did nothing to it: no harder, no softer. Do not show the bear: he will take it, hand and all.", Rare = false },
        new Def { Id = "NishikavaAjo", Kind = Kind.Snack, Shape = "bag", Mesh = "Nishikava", Texture = "NishikavaAjo", Kg = 0.188f, Kcal = 940f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «Нишикава»", En = "Nishikava coated peanuts", RuF = "чеснок", EnF = "garlic", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "Sinew" }, RuJ = "Японский арахис, придуманный в Мексике. География вышла покурить. Из тех времён, когда еду выбирали по вкусу. Диетолог не одобрил бы. Диетолога тут нет.", EnJ = "Japanese peanuts invented in Mexico. Geography stepped out for a smoke. From the days when people picked food for its taste. A dietitian would not approve. There is no dietitian here.", Rare = false },
        new Def { Id = "TorsidaChurrasco", Kind = Kind.Snack, Shape = "bag", Mesh = "Torsida", Texture = "TorsidaChurrasco", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Торсида»", En = "Torsida corn puffs", RuF = "шурраско", EnF = "churrasco", RuC = "Бразилия", EnC = "Brazil", Fx = new[] { "SaltHold" }, RuJ = "Бразильские сухарики-шарики: на пачке трибуна болеет, гол пока не забит. Чей-то перекус на ночную смену, которая не кончилась. Лучше, чем кора. Проверено.", EnJ = "Brazilian snack balls: the stand on the pack is cheering, no goal yet. Someone's snack for a night shift that never ended. Better than bark. Tested.", Rare = false },
        new Def { Id = "TorsidaPimenta", Kind = Kind.Snack, Shape = "bag", Mesh = "Torsida", Texture = "TorsidaPimenta", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Торсида»", En = "Torsida corn puffs", RuF = "мексиканский перец", EnF = "mexican pepper", RuC = "Бразилия", EnC = "Brazil", Fx = new[] { "SaltHold" }, RuJ = "Бразильские сухарики-шарики: на пачке трибуна болеет, гол пока не забит. В охотничьей вышке таким встречали рассвет. Хруст разносится до соседней долины.", EnJ = "Brazilian snack balls: the stand on the pack is cheering, no goal yet. In the hunting blind they met the dawn with this. The crunch carries to the next valley.", Rare = false },
        new Def { Id = "TorsidaBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Torsida", Texture = "TorsidaBacon", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Торсида»", En = "Torsida corn puffs", RuF = "бекон", EnF = "bacon", RuC = "Бразилия", EnC = "Brazil", Fx = new[] { "SaltHold" }, RuJ = "Бразильские сухарики-шарики: на пачке трибуна болеет, гол пока не забит. Такое носили в кармане куртки на всякий случай. Случай настал. Ешьте медленно: когда ещё такое найдёте.", EnJ = "Brazilian snack balls: the stand on the pack is cheering, no goal yet. People carried these in a coat pocket just in case. The case has come. Eat slowly: who knows when you will find another.", Rare = false },
        new Def { Id = "TorsidaCostela", Kind = Kind.Snack, Shape = "bag", Mesh = "Torsida", Texture = "TorsidaCostela", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Торсида»", En = "Torsida corn puffs", RuF = "рёбрышки с лаймом", EnF = "ribs with lime", RuC = "Бразилия", EnC = "Brazil", Fx = new[] { "SaltHold" }, RuJ = "Бразильские сухарики-шарики: на пачке трибуна болеет, гол пока не забит. Прежний хозяин оставил записку: «Не трогать». Записка сгорела. К этому просится пиво, а есть только талый снег.", EnJ = "Brazilian snack balls: the stand on the pack is cheering, no goal yet. The last owner left a note: 'Do not touch'. The note burned. It begs for a beer, and there is only melted snow.", Rare = false },
        new Def { Id = "TorsidaJunina", Kind = Kind.Snack, Shape = "bag", Mesh = "Torsida", Texture = "TorsidaJunina", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Торсида»", En = "Torsida corn puffs", RuF = "кукуруза к июньскому празднику", EnF = "festa junina corn", RuC = "Бразилия", EnC = "Brazil", Fx = new[] { "SaltHold" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Такими торговали в поезде, пока поезд ходил. Сияние на вкус не влияет. Наверное.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. They sold these on the train, while the train ran. The aurora does not affect the taste. Probably.", Rare = true },
        new Def { Id = "TorsidaNatal", Kind = Kind.Snack, Shape = "bag", Mesh = "Torsida", Texture = "TorsidaNatal", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Торсида»", En = "Torsida corn puffs", RuF = "рождественская индейка", EnF = "christmas turkey", RuC = "Бразилия", EnC = "Brazil", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Сторож шахты держал такое в ящике стола. После тушёнки из банки это почти ресторан.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. The mine watchman kept these in his desk drawer. After stew from a tin this is nearly a restaurant.", Rare = true },
        new Def { Id = "TorsidaCebola", Kind = Kind.Snack, Shape = "bag", Mesh = "Torsida", Texture = "TorsidaCebola", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Торсида»", En = "Torsida corn puffs", RuF = "лук", EnF = "onion", RuC = "Бразилия", EnC = "Brazil", Fx = new[] { "SaltHold" }, RuJ = "Бразильские сухарики-шарики: на пачке трибуна болеет, гол пока не забит. Лавина прошла мимо, срок годности тоже. Делиться не с кем, и это впервые радует.", EnJ = "Brazilian snack balls: the stand on the pack is cheering, no goal yet. The avalanche missed it, and so did the best-before date. Nobody to share with, and for once that is good news.", Rare = false },
        new Def { Id = "TorsidaQueijo", Kind = Kind.Snack, Shape = "bag", Mesh = "Torsida", Texture = "TorsidaQueijo", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Торсида»", En = "Torsida corn puffs", RuF = "сыр", EnF = "cheese", RuC = "Бразилия", EnC = "Brazil", Fx = new[] { "SaltHold" }, RuJ = "Бразильские сухарики-шарики: на пачке трибуна болеет, гол пока не забит. Такое всегда стояло на видном месте, поэтому никто не брал. Пальцы потом оближите: зимой калории не выбрасывают.", EnJ = "Brazilian snack balls: the stand on the pack is cheering, no goal yet. These always stood in plain sight, which is why nobody took them. Lick your fingers after: in winter you do not waste calories.", Rare = false },
        new Def { Id = "TorsidaCamarao", Kind = Kind.Snack, Shape = "bag", Mesh = "Torsida", Texture = "TorsidaCamarao", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Торсида»", En = "Torsida corn puffs", RuF = "креветка", EnF = "shrimp", RuC = "Бразилия", EnC = "Brazil", Fx = new[] { "SaltHold" }, RuJ = "Бразильские сухарики-шарики: на пачке трибуна болеет, гол пока не забит. Кто-то открыл, передумал и умер. Не связано. Ворон на ветке уже ждёт свою долю.", EnJ = "Brazilian snack balls: the stand on the pack is cheering, no goal yet. Someone opened it, changed their mind and died. Unrelated. The crow on the branch is already waiting for its share.", Rare = false },
        new Def { Id = "TorsidaVinagrete", Kind = Kind.Snack, Shape = "bag", Mesh = "Torsida", Texture = "TorsidaVinagrete", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Торсида»", En = "Torsida corn puffs", RuF = "винегрет", EnF = "vinaigrette", RuC = "Бразилия", EnC = "Brazil", Fx = new[] { "SaltHold" }, RuJ = "Бразильские сухарики-шарики: на пачке трибуна болеет, гол пока не забит. Такое вечно каталось под сиденьем пикапа. На морозе хрустит вдвое громче.", EnJ = "Brazilian snack balls: the stand on the pack is cheering, no goal yet. One of these was always rolling under a pickup seat. In the frost it crunches twice as loud.", Rare = false },
        new Def { Id = "TorsidaCaipira", Kind = Kind.Snack, Shape = "bag", Mesh = "Torsida", Texture = "TorsidaCaipira", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Торсида»", En = "Torsida corn puffs", RuF = "курица по-деревенски", EnF = "country chicken", RuC = "Бразилия", EnC = "Brazil", Fx = new[] { "SaltHold" }, RuJ = "Бразильские сухарики-шарики: на пачке трибуна болеет, гол пока не забит. Привезено паромом, которого больше нет. Не еда, а настроение. Настроение тоже греет.", EnJ = "Brazilian snack balls: the stand on the pack is cheering, no goal yet. Brought over by a ferry that no longer exists. Not food but a mood. A mood warms you too.", Rare = false },
        new Def { Id = "FandangozPresunto", Kind = Kind.Snack, Shape = "bag", Mesh = "Fandangoz", Texture = "FandangozPresunto", Kg = 0.148f, Kcal = 770f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Фандангос»", En = "Fandangoz corn puffs", RuF = "ветчина", EnF = "ham", RuC = "Бразилия", EnC = "Brazil", Fx = new[] { "SaltHold" }, RuJ = "Кукурузные волны из Бразилии: танцуют фанданго прямо в пакете. Раньше это ели под телевизор. Телевизор молчит. Сытости на час, воспоминаний на неделю.", EnJ = "Corn waves from Brazil: dancing a fandango right in the bag. People ate this in front of the telly. The telly is silent. An hour of fullness, a week of memories.", Rare = false },
        new Def { Id = "FandangozQueijo", Kind = Kind.Snack, Shape = "bag", Mesh = "Fandangoz", Texture = "FandangozQueijo", Kg = 0.148f, Kcal = 770f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Фандангос»", En = "Fandangoz corn puffs", RuF = "сыр", EnF = "cheese", RuC = "Бразилия", EnC = "Brazil", Fx = new[] { "SaltHold" }, RuJ = "Кукурузные волны из Бразилии: танцуют фанданго прямо в пакете. Забыто туристами, которым повезло уехать. Кролик смотрит с осуждением.", EnJ = "Corn waves from Brazil: dancing a fandango right in the bag. Left behind by tourists who were lucky enough to leave. The rabbit looks on with disapproval.", Rare = false },
        new Def { Id = "FandangozChurrasco", Kind = Kind.Snack, Shape = "bag", Mesh = "Fandangoz", Texture = "FandangozChurrasco", Kg = 0.148f, Kcal = 770f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Фандангос»", En = "Fandangoz corn puffs", RuF = "шурраско", EnF = "churrasco", RuC = "Бразилия", EnC = "Brazil", Fx = new[] { "SaltHold" }, RuJ = "Кукурузные волны из Бразилии: танцуют фанданго прямо в пакете. Механики заедали этим обед, не вытирая рук. У костра вкуснее. У костра всё вкуснее.", EnJ = "Corn waves from Brazil: dancing a fandango right in the bag. Mechanics ate these for lunch without wiping their hands. It tastes better by the fire. Everything does.", Rare = false },
        new Def { Id = "FandangozPizza", Kind = Kind.Snack, Shape = "bag", Mesh = "Fandangoz", Texture = "FandangozPizza", Kg = 0.148f, Kcal = 770f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Фандангос»", En = "Fandangoz corn puffs", RuF = "пицца", EnF = "pizza", RuC = "Бразилия", EnC = "Brazil", Fx = new[] { "SaltHold" }, RuJ = "Кукурузные волны из Бразилии: танцуют фанданго прямо в пакете. Последнее на всю Одинокую топь. Скорее всего. Упаковку не выбрасывайте: ею можно разжечь печь.", EnJ = "Corn waves from Brazil: dancing a fandango right in the bag. The last one in all of Forlorn Muskeg. Most likely. Keep the wrapper: it will light the stove.", Rare = false },
        new Def { Id = "FandangozRequeijao", Kind = Kind.Snack, Shape = "bag", Mesh = "Fandangoz", Texture = "FandangozRequeijao", Kg = 0.148f, Kcal = 770f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Фандангос»", En = "Fandangoz corn puffs", RuF = "сливочный сыр", EnF = "cream cheese", RuC = "Бразилия", EnC = "Brazil", Fx = new[] { "SaltHold" }, RuJ = "Кукурузные волны из Бразилии: танцуют фанданго прямо в пакете. Смотритель маяка грыз такое, ожидая кораблей. Если это последняя на острове, вы её достойны.", EnJ = "Corn waves from Brazil: dancing a fandango right in the bag. The lighthouse keeper munched these while waiting for ships. If this is the last one on the island, you have earned it.", Rare = false },
        new Def { Id = "FandangozGalinha", Kind = Kind.Snack, Shape = "bag", Mesh = "Fandangoz", Texture = "FandangozGalinha", Kg = 0.148f, Kcal = 770f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Фандангос»", En = "Fandangoz corn puffs", RuF = "курица", EnF = "chicken", RuC = "Бразилия", EnC = "Brazil", Fx = new[] { "SaltHold" }, RuJ = "Кукурузные волны из Бразилии: танцуют фанданго прямо в пакете. Полки рушились, а это уцелело. Желудок удивится, но возражать не станет.", EnJ = "Corn waves from Brazil: dancing a fandango right in the bag. Shelves collapsed and this survived. Your stomach will be surprised but will not object.", Rare = false },
        new Def { Id = "FandangozMilho", Kind = Kind.Snack, Shape = "bag", Mesh = "Fandangoz", Texture = "FandangozMilho", Kg = 0.148f, Kcal = 770f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Фандангос»", En = "Fandangoz corn puffs", RuF = "кукуруза с маслом", EnF = "buttered corn", RuC = "Бразилия", EnC = "Brazil", Fx = new[] { "SaltHold" }, RuJ = "Кукурузные волны из Бразилии: танцуют фанданго прямо в пакете. Смотритель заповедника называл это ужином. Запах выдаёт вас за сто шагов. Оно того стоит.", EnJ = "Corn waves from Brazil: dancing a fandango right in the bag. The park ranger called this dinner. The smell gives you away at a hundred paces. Worth it.", Rare = false },
        new Def { Id = "VikoClassique", Kind = Kind.Snack, Shape = "bag", Mesh = "Viko", Texture = "VikoClassique", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Вико»", En = "Viko crisps", RuF = "классические", EnF = "classic", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Французские чипсы: в багет с ними кладут ветчину и называют обедом. Такое слали посылками с материка. Адресаты выбыли. Раньше это называли вредным. Теперь называют едой.", EnJ = "French crisps: put in a baguette with ham and called lunch. These came in parcels from the mainland. The addressees are gone. They used to call this unhealthy. Now they call it food.", Rare = false },
        new Def { Id = "VikoPoulet", Kind = Kind.Snack, Shape = "bag", Mesh = "Viko", Texture = "VikoPoulet", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Вико»", En = "Viko crisps", RuF = "жареная курица", EnF = "roast chicken", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Французские чипсы: в багет с ними кладут ветчину и называют обедом. Иные держали это за лекарство. Тоже лечит. Спальный мешок потом вытряхните.", EnJ = "French crisps: put in a baguette with ham and called lunch. Some people counted this as medicine. Also a cure. Shake out your sleeping bag afterwards.", Rare = false },
        new Def { Id = "VikoBarbecue", Kind = Kind.Snack, Shape = "bag", Mesh = "Viko", Texture = "VikoBarbecue", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Вико»", En = "Viko crisps", RuF = "барбекю", EnF = "barbecue", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Французские чипсы: в багет с ними кладут ветчину и называют обедом. В школьном рюкзаке такое не доживало до обеда. Зимой такое идёт за валюту.", EnJ = "French crisps: put in a baguette with ham and called lunch. In a school bag this never lasted till lunch. In winter this passes for currency.", Rare = false },
        new Def { Id = "VikoFondue", Kind = Kind.Snack, Shape = "bag", Mesh = "Viko", Texture = "VikoFondue", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Вико»", En = "Viko crisps", RuF = "савойское фондю", EnF = "savoyard fondue", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Зимняя серия: выпускали на один сезон, а зима тут навсегда. Его обменяли бы на патрон, будь тут с кем меняться. Торговец дал бы за это тряпку. Вы дадите больше.", EnJ = "A winter edition: made for one season, and here winter is forever. You could trade it for a cartridge, if there were anyone to trade with. The trader would give a rag for it. You would give more.", Rare = true },
        new Def { Id = "VikoNoel", Kind = Kind.Snack, Shape = "bag", Mesh = "Viko", Texture = "VikoNoel", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Вико»", En = "Viko crisps", RuF = "каштаны", EnF = "roasted chestnuts", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. На вокзале это стоило втрое дороже. Теперь даром. Пока жуёте, метель кажется короче.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. At the station it cost three times as much. Now it is free. While you chew, the blizzard seems shorter.", Rare = true },
        new Def { Id = "VikoPaysanne", Kind = Kind.Snack, Shape = "bag", Mesh = "Viko", Texture = "VikoPaysanne", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Вико»", En = "Viko crisps", RuF = "по-деревенски", EnF = "country style", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Французские чипсы: в багет с ними кладут ветчину и называют обедом. Пережило толчок и даже не помялось. Организм скажет спасибо. Или не скажет.", EnJ = "French crisps: put in a baguette with ham and called lunch. It came through the quake without a dent. Your body will thank you. Or not.", Rare = false },
        new Def { Id = "VikoSel", Kind = Kind.Snack, Shape = "bag", Mesh = "Viko", Texture = "VikoSel", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Вико»", En = "Viko crisps", RuF = "морская соль", EnF = "sea salt", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Французские чипсы: в багет с ними кладут ветчину и называют обедом. Китобои такого не ели, но оценили бы. На третьей горсти забываешь, что вокруг конец света.", EnJ = "French crisps: put in a baguette with ham and called lunch. The whalers never ate this, but they would have approved. By the third handful you forget the world has ended.", Rare = false },
        new Def { Id = "VikoBolognaise", Kind = Kind.Snack, Shape = "bag", Mesh = "Viko", Texture = "VikoBolognaise", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Вико»", En = "Viko crisps", RuF = "болоньезе", EnF = "bolognese", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Французские чипсы: в багет с ними кладут ветчину и называют обедом. Осталось после чьего-то дня рождения. Гости не пришли. Рыба подо льдом завидует.", EnJ = "French crisps: put in a baguette with ham and called lunch. Left over from someone's birthday. The guests never came. The fish under the ice are jealous.", Rare = false },
        new Def { Id = "VikoChevre", Kind = Kind.Snack, Shape = "bag", Mesh = "Viko", Texture = "VikoChevre", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Вико»", En = "Viko crisps", RuF = "козий сыр", EnF = "goat's cheese", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Французские чипсы: в багет с ними кладут ветчину и называют обедом. Мерзлота хранит лучше любого холодильника. Олень от такого отказался бы. Олень не голодал.", EnJ = "French crisps: put in a baguette with ham and called lunch. Permafrost keeps things better than any fridge. A deer would turn it down. A deer has never starved.", Rare = false },
        new Def { Id = "VikoMoutarde", Kind = Kind.Snack, Shape = "bag", Mesh = "Viko", Texture = "VikoMoutarde", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Вико»", En = "Viko crisps", RuF = "горчица", EnF = "mustard", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Французские чипсы: в багет с ними кладут ветчину и называют обедом. Такое добывали из автомата, который съедал последнюю монету. Соль есть, жир есть, совести нет.", EnJ = "French crisps: put in a baguette with ham and called lunch. These came from the vending machine that ate your last coin. Salt: yes. Fat: yes. Conscience: none.", Rare = false },
        new Def { Id = "VikoOignon", Kind = Kind.Snack, Shape = "bag", Mesh = "Viko", Texture = "VikoOignon", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Вико»", En = "Viko crisps", RuF = "сметана и лук", EnF = "cream & onion", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold" }, RuJ = "Французские чипсы: в багет с ними кладут ветчину и называют обедом. Такое брали в лодку под брезент, на весь день. Ешьте до темноты: в темноте крошки не найти.", EnJ = "French crisps: put in a baguette with ham and called lunch. People took these out in the boat under the tarpaulin, for the whole day. Eat before dark: you cannot find crumbs in the dark.", Rare = false },
        new Def { Id = "BelenMonaco", Kind = Kind.Snack, Shape = "carton", Mesh = "Belen", Texture = "BelenMonaco", Kg = 0.108f, Kcal = 480f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Белен»", En = "Belen crackers", RuF = "эмменталь", EnF = "emmental", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Французские крекеры к аперитиву. Аперитив перенесён на неопределённый срок. С ним кто-то шёл к перевалу и не дошёл. Лучшее, что случится с вами сегодня.", EnJ = "French crackers for the apéritif. The apéritif is postponed indefinitely. Someone carried it towards the pass and never arrived. The best thing that will happen to you today.", Rare = false },
        new Def { Id = "BelenCroustilles", Kind = Kind.Snack, Shape = "carton", Mesh = "Belen", Texture = "BelenCroustilles", Kg = 0.108f, Kcal = 480f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Белен»", En = "Belen crackers", RuF = "сырные", EnF = "cheese crisps", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Французские крекеры к аперитиву. Аперитив перенесён на неопределённый срок. С таким сидели у окна с видом на метель. Для полного счастья не хватает только дивана.", EnJ = "French crackers for the apéritif. The apéritif is postponed indefinitely. People sat with these at a window with a view of the blizzard. All that is missing for perfect happiness is a sofa.", Rare = false },
        new Def { Id = "BelenChipster", Kind = Kind.Snack, Shape = "carton", Mesh = "Belen", Texture = "BelenChipster", Kg = 0.108f, Kcal = 480f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Белен»", En = "Belen crackers", RuF = "воздушные лепестки", EnF = "salted petals", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Французские крекеры к аперитиву. Аперитив перенесён на неопределённый срок. Уцелело там, где сгорело всё остальное. Вкус детства, если детство было так себе.", EnJ = "French crackers for the apéritif. The apéritif is postponed indefinitely. It survived where everything else burned. The taste of childhood, if childhood was so-so.", Rare = false },
        new Def { Id = "BelenPizza", Kind = Kind.Snack, Shape = "carton", Mesh = "Belen", Texture = "BelenPizza", Kg = 0.108f, Kcal = 480f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Белен»", En = "Belen crackers", RuF = "пицца", EnF = "pizza", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Французские крекеры к аперитиву. Аперитив перенесён на неопределённый срок. Этим кормили сторожевого пса. Пёс ушёл в волки. Шуршит как надежда.", EnJ = "French crackers for the apéritif. The apéritif is postponed indefinitely. They fed the guard dog with this. The dog joined the wolves. It rustles like hope.", Rare = false },
        new Def { Id = "BelenBacon", Kind = Kind.Snack, Shape = "carton", Mesh = "Belen", Texture = "BelenBacon", Kg = 0.108f, Kcal = 480f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Белен»", En = "Belen crackers", RuF = "бекон", EnF = "bacon", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Французские крекеры к аперитиву. Аперитив перенесён на неопределённый срок. Из запасов лесорубов: брали ящиками. Голод отступит, жажда придёт. Честный обмен.", EnJ = "French crackers for the apéritif. The apéritif is postponed indefinitely. From the loggers' stores: they bought it by the crate. Hunger leaves, thirst arrives. A fair trade.", Rare = false },
        new Def { Id = "BelenSesame", Kind = Kind.Snack, Shape = "carton", Mesh = "Belen", Texture = "BelenSesame", Kg = 0.108f, Kcal = 480f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Белен»", En = "Belen crackers", RuF = "кунжут", EnF = "sesame", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Французские крекеры к аперитиву. Аперитив перенесён на неопределённый срок. В пост такое не ели. Пост кончился вместе с миром. Не согреет, зато отвлечёт.", EnJ = "French crackers for the apéritif. The apéritif is postponed indefinitely. Nobody ate these during a fast. The fast ended with the world. It will not warm you, but it will distract you.", Rare = false },
        new Def { Id = "BelenChevre", Kind = Kind.Snack, Shape = "carton", Mesh = "Belen", Texture = "BelenChevre", Kg = 0.108f, Kcal = 480f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Белен»", En = "Belen crackers", RuF = "козий сыр", EnF = "goat's cheese", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Французские крекеры к аперитиву. Аперитив перенесён на неопределённый срок. Теперь это ценнее денег. Деньги оставьте. Пума предпочитает мясо. Вам повезло.", EnJ = "French crackers for the apéritif. The apéritif is postponed indefinitely. It is worth more than money now. Leave the money. The cougar prefers meat. Lucky you.", Rare = false },
        new Def { Id = "BelenTomate", Kind = Kind.Snack, Shape = "carton", Mesh = "Belen", Texture = "BelenTomate", Kg = 0.108f, Kcal = 480f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Белен»", En = "Belen crackers", RuF = "томат и орегано", EnF = "tomato & oregano", RuC = "Франция", EnC = "France", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Французские крекеры к аперитиву. Аперитив перенесён на неопределённый срок. Его несли на пикник. Пикник отменили навсегда. Сначала попробуйте одну штучку. Шутка: ешьте всё.", EnJ = "French crackers for the apéritif. The apéritif is postponed indefinitely. It was headed for a picnic. The picnic is cancelled forever. Try just one first. Joke: eat the lot.", Rare = false },
        new Def { Id = "RisketozQueso", Kind = Kind.Snack, Shape = "bag", Mesh = "Risketoz", Texture = "RisketozQueso", Kg = 0.128f, Kcal = 660f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Рискетос»", En = "Risketoz corn puffs", RuF = "сыр", EnF = "cheese", RuC = "Испания", EnC = "Spain", Fx = new[] { "SaltHold" }, RuJ = "Испанские сырные червячки: рискуешь только цветом пальцев. Такое стояло у кассы на случай слабости. Такой ужин не стыдно записать в дневник.", EnJ = "Spanish cheese worms: the only risk is the colour of your fingers. These stood by the till for moments of weakness. A dinner worth writing in the journal.", Rare = false },
        new Def { Id = "RisketozJamon", Kind = Kind.Snack, Shape = "bag", Mesh = "Risketoz", Texture = "RisketozJamon", Kg = 0.128f, Kcal = 660f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Рискетос»", En = "Risketoz corn puffs", RuF = "хамон", EnF = "ham", RuC = "Испания", EnC = "Spain", Fx = new[] { "SaltHold" }, RuJ = "Испанские сырные червячки: рискуешь только цветом пальцев. Досталось вам, потому что вы дошли первым. Силы прибавит на один сугроб.", EnJ = "Spanish cheese worms: the only risk is the colour of your fingers. It is yours because you got here first. It will carry you one snowdrift further.", Rare = false },
        new Def { Id = "RisketozBarbacoa", Kind = Kind.Snack, Shape = "bag", Mesh = "Risketoz", Texture = "RisketozBarbacoa", Kg = 0.128f, Kcal = 660f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Рискетос»", En = "Risketoz corn puffs", RuF = "барбекю", EnF = "barbecue", RuC = "Испания", EnC = "Spain", Fx = new[] { "SaltHold" }, RuJ = "Испанские сырные червячки: рискуешь только цветом пальцев. Упаковка выцвела, внутри время остановилось. Идеально к закату, которого не видно за бураном.", EnJ = "Spanish cheese worms: the only risk is the colour of your fingers. The wrapper has faded; inside, time stood still. Perfect with a sunset you cannot see for the storm.", Rare = false },
        new Def { Id = "RisketozKetchup", Kind = Kind.Snack, Shape = "bag", Mesh = "Risketoz", Texture = "RisketozKetchup", Kg = 0.128f, Kcal = 660f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Рискетос»", En = "Risketoz corn puffs", RuF = "кетчуп", EnF = "ketchup", RuC = "Испания", EnC = "Spain", Fx = new[] { "SaltHold" }, RuJ = "Испанские сырные червячки: рискуешь только цветом пальцев. Из чемодана пассажира, который не долетел. Пахнет магазином. Помните магазины?", EnJ = "Spanish cheese worms: the only risk is the colour of your fingers. From the suitcase of a passenger who never landed. It smells of a shop. Remember shops?", Rare = false },
        new Def { Id = "RisketozPizza", Kind = Kind.Snack, Shape = "bag", Mesh = "Risketoz", Texture = "RisketozPizza", Kg = 0.128f, Kcal = 660f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Рискетос»", En = "Risketoz corn puffs", RuF = "пицца", EnF = "pizza", RuC = "Испания", EnC = "Spain", Fx = new[] { "SaltHold" }, RuJ = "Испанские сырные червячки: рискуешь только цветом пальцев. Перезимовало и ничуть не обиделось. Мороз не испортил, время не взяло.", EnJ = "Spanish cheese worms: the only risk is the colour of your fingers. It made it through the winter and bears no grudge. Frost did not spoil it and time could not take it.", Rare = false },
        new Def { Id = "RisketozPicante", Kind = Kind.Snack, Shape = "bag", Mesh = "Risketoz", Texture = "RisketozPicante", Kg = 0.128f, Kcal = 660f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Рискетос»", En = "Risketoz corn puffs", RuF = "острые", EnF = "hot", RuC = "Испания", EnC = "Spain", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Испанские сырные червячки: рискуешь только цветом пальцев. Запасливая хозяйка купила по акции шесть штук. В рюкзаке не мнётся. Почти.", EnJ = "Spanish cheese worms: the only risk is the colour of your fingers. A thrifty housewife bought six of these on offer. It does not get crushed in a pack. Almost.", Rare = false },
        new Def { Id = "RisketozBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Risketoz", Texture = "RisketozBacon", Kg = 0.128f, Kcal = 660f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Рискетос»", En = "Risketoz corn puffs", RuF = "бекон", EnF = "bacon", RuC = "Испания", EnC = "Spain", Fx = new[] { "SaltHold" }, RuJ = "Испанские сырные червячки: рискуешь только цветом пальцев. Кто-то написал на упаковке «моё». Уже нет. Съешьте сейчас: завтра может не быть аппетита.", EnJ = "Spanish cheese worms: the only risk is the colour of your fingers. Someone wrote 'mine' on it. Not any more. Eat it now: tomorrow you may have no appetite.", Rare = false },
        new Def { Id = "SanKarloClassica", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarlo", Texture = "SanKarloClassica", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло»", En = "San Karlo crisps", RuF = "классические", EnF = "classic", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Итальянские чипсы: едят стоя у бара, жестикулируя свободной рукой. В консервном цеху это ели тайком от мастера. Хватит дойти до следующей хижины и пожалеть, что кончилось.", EnJ = "Italian crisps: eaten standing at the bar, gesturing with the free hand. At the cannery they ate this behind the foreman's back. Enough to reach the next cabin and regret it is gone.", Rare = false },
        new Def { Id = "SanKarloRustica", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarlo", Texture = "SanKarloRustica", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло»", En = "San Karlo crisps", RuF = "деревенские", EnF = "rustic", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Итальянские чипсы: едят стоя у бара, жестикулируя свободной рукой. Его не взяли даже мародёры. Они спешили. От такого не толстеют те, кто ходит по двадцать километров.", EnJ = "Italian crisps: eaten standing at the bar, gesturing with the free hand. Even the looters left it. They were in a hurry. Nobody who walks twenty kilometres a day gets fat on this.", Rare = false },
        new Def { Id = "SanKarloLime", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarlo", Texture = "SanKarloLime", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло»", En = "San Karlo crisps", RuF = "лайм и розовый перец", EnF = "lime & pink pepper", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Итальянские чипсы: едят стоя у бара, жестикулируя свободной рукой. Провело зиму на острове, как и вы. Волчья стая не в курсе. Пусть так и будет.", EnJ = "Italian crisps: eaten standing at the bar, gesturing with the free hand. It spent the winter on the island, same as you. The wolf pack does not know. Keep it that way.", Rare = false },
        new Def { Id = "SanKarloPaprika", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarlo", Texture = "SanKarloPaprika", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло»", En = "San Karlo crisps", RuF = "паприка", EnF = "paprika", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Итальянские чипсы: едят стоя у бара, жестикулируя свободной рукой. Дети прятали такое под кроватью, в тайнике. Хрустеть в засаде не рекомендуется.", EnJ = "Italian crisps: eaten standing at the bar, gesturing with the free hand. Children hid these under the bed, in a secret place. Crunching in an ambush is not recommended.", Rare = false },
        new Def { Id = "SanKarloTartufo", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarlo", Texture = "SanKarloTartufo", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло»", En = "San Karlo crisps", RuF = "осенний трюфель", EnF = "autumn truffle", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Осенняя серия: выпускали, пока падали листья. Редкая пачка. Осталось от геологов вместе с картой и долгами. Лекарство от тоски, отпускается без рецепта.", EnJ = "An autumn edition: made while the leaves fell. A rare pack. Left by the geologists along with a map and some debts. A cure for the blues, no prescription needed.", Rare = true },
        new Def { Id = "SanKarloEstate", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarlo", Texture = "SanKarloEstate", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло»", En = "San Karlo crisps", RuF = "летний лимон", EnF = "summer lemon", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. На острове такое было праздником и до катастрофы. Жуйте и думайте о хорошем. Например, о добавке.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. On the island this was a treat even before the disaster. Chew and think of nice things. Seconds, for example.", Rare = true },
        new Def { Id = "SanKarloPomodoro", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarlo", Texture = "SanKarloPomodoro", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло»", En = "San Karlo crisps", RuF = "томат", EnF = "tomato", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Итальянские чипсы: едят стоя у бара, жестикулируя свободной рукой. С таким слушали радио, которое теперь ловит только треск. К утру от него останется только запах на варежках.", EnJ = "Italian crisps: eaten standing at the bar, gesturing with the free hand. People ate these by the radio, which picks up nothing but crackle now. By morning only the smell on your mittens will be left.", Rare = false },
        new Def { Id = "SanKarloLight", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarlo", Texture = "SanKarloLight", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло»", En = "San Karlo crisps", RuF = "лёгкие", EnF = "light", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Итальянские чипсы: едят стоя у бара, жестикулируя свободной рукой. Крысы прогрызли соседнюю, эту пощадили. Тишина вокруг такая, что слышно, как вы жуёте.", EnJ = "Italian crisps: eaten standing at the bar, gesturing with the free hand. The rats gnawed through the one next to it and spared this. It is so quiet you can hear yourself chew.", Rare = false },
        new Def { Id = "SanKarloRosmarino", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarlo", Texture = "SanKarloRosmarino", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло»", En = "San Karlo crisps", RuF = "розмарин", EnF = "rosemary", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Итальянские чипсы: едят стоя у бара, жестикулируя свободной рукой. Бывший хозяин клялся бросить. Не успел. Не делите на завтра: завтра будет новый голод.", EnJ = "Italian crisps: eaten standing at the bar, gesturing with the free hand. The former owner swore to give these up. He ran out of time. Do not save half for tomorrow: tomorrow brings its own hunger.", Rare = false },
        new Def { Id = "SanKarloPepe", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarlo", Texture = "SanKarloPepe", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло»", En = "San Karlo crisps", RuF = "перец и лайм", EnF = "pepper & lime", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Итальянские чипсы: едят стоя у бара, жестикулируя свободной рукой. Его катали в кабине трактора три сезона. Сосны вокруг делают вид, что не смотрят.", EnJ = "Italian crisps: eaten standing at the bar, gesturing with the free hand. It rode around in a tractor cab for three seasons. The pines around pretend not to watch.", Rare = false },
        new Def { Id = "SanKarloPizza", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarlo", Texture = "SanKarloPizza", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло»", En = "San Karlo crisps", RuF = "пицца", EnF = "pizza", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Итальянские чипсы: едят стоя у бара, жестикулируя свободной рукой. После бани такое шло лучше всего. Калории мелкие, зато свои.", EnJ = "Italian crisps: eaten standing at the bar, gesturing with the free hand. Nothing went down better after the sauna. Small calories, but your own.", Rare = false },
        new Def { Id = "SanKarloBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarlo", Texture = "SanKarloBacon", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло»", En = "San Karlo crisps", RuF = "бекон", EnF = "bacon", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Итальянские чипсы: едят стоя у бара, жестикулируя свободной рукой. В тюрьме на это выменивали что угодно. После этого даже крапивный чай покажется десертом.", EnJ = "Italian crisps: eaten standing at the bar, gesturing with the free hand. In the prison you could trade one of these for anything. After this even nettle tea feels like dessert.", Rare = false },
        new Def { Id = "SanKarloPesto", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarlo", Texture = "SanKarloPesto", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло»", En = "San Karlo crisps", RuF = "песто", EnF = "pesto", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Итальянские чипсы: едят стоя у бара, жестикулируя свободной рукой. Кто-то менял это на сигареты. Сделка сорвалась. Нашедшему полагается всё.", EnJ = "Italian crisps: eaten standing at the bar, gesturing with the free hand. Someone was trading this for cigarettes. The deal fell through. Finders keepers, all of it.", Rare = false },
        new Def { Id = "NonnaPiaClassici", Kind = Kind.Snack, Shape = "bag", Mesh = "NonnaPia", Texture = "NonnaPiaClassici", Kg = 0.258f, Kcal = 850f, Thirst = -6f, Eat = 5f, Ru = "Таралли «Нонна Пиа»", En = "Nonna Pia sushki rings", RuF = "классические", EnF = "classic", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Таралли от нонны: варёные, потом печёные, потом съеденные до приезда гостей. С ним зимовали на метеостанции, пока было с кем. Зубы целы? Тогда вперёд.", EnJ = "Nonna's taralli: boiled, then baked, then eaten before the guests arrive. They wintered with it at the weather station, while there was a 'they'. Teeth intact? Then go ahead.", Rare = false },
        new Def { Id = "NonnaPiaFinocchio", Kind = Kind.Snack, Shape = "bag", Mesh = "NonnaPia", Texture = "NonnaPiaFinocchio", Kg = 0.258f, Kcal = 850f, Thirst = -6f, Eat = 5f, Ru = "Таралли «Нонна Пиа»", En = "Nonna Pia sushki rings", RuF = "с фенхелем", EnF = "fennel", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Таралли от нонны: варёные, потом печёные, потом съеденные до приезда гостей. Такое терялось в кладовке среди крупы и надежд. Ночью приснится добавка.", EnJ = "Nonna's taralli: boiled, then baked, then eaten before the guests arrive. These got lost in the pantry among the grain and the hopes. Tonight you will dream of seconds.", Rare = false },
        new Def { Id = "NonnaPiaPeperoncino", Kind = Kind.Snack, Shape = "bag", Mesh = "NonnaPia", Texture = "NonnaPiaPeperoncino", Kg = 0.258f, Kcal = 850f, Thirst = -6f, Eat = 5f, Ru = "Таралли «Нонна Пиа»", En = "Nonna Pia sushki rings", RuF = "с перчиком", EnF = "chilli", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Таралли от нонны: варёные, потом печёные, потом съеденные до приезда гостей. Его берегли к приезду внуков. С таким запасом можно пережить ещё один вечер.", EnJ = "Nonna's taralli: boiled, then baked, then eaten before the guests arrive. It was being saved for the grandchildren's visit. With supplies like this you can survive one more evening.", Rare = false },
        new Def { Id = "NonnaPiaCipolla", Kind = Kind.Snack, Shape = "bag", Mesh = "NonnaPia", Texture = "NonnaPiaCipolla", Kg = 0.258f, Kcal = 850f, Thirst = -6f, Eat = 5f, Ru = "Таралли «Нонна Пиа»", En = "Nonna Pia sushki rings", RuF = "с луком", EnF = "onion", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Таралли от нонны: варёные, потом печёные, потом съеденные до приезда гостей. В баре такое ставили на стойку, бесплатно к пиву. Пива нет. Пёс бы выпросил половину. Пса нет.", EnJ = "Nonna's taralli: boiled, then baked, then eaten before the guests arrive. Bars put these out free with a beer. There is no beer. A dog would beg half of it. There is no dog.", Rare = false },
        new Def { Id = "NonnaPiaNatale", Kind = Kind.Snack, Shape = "bag", Mesh = "NonnaPia", Texture = "NonnaPiaNatale", Kg = 0.258f, Kcal = 850f, Thirst = -6f, Eat = 5f, Ru = "Таралли «Нонна Пиа»", En = "Nonna Pia sushki rings", RuF = "рождественские, фенхель и апельсин", EnF = "christmas fennel & orange", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Такое лежало в каждом доме, пока не погас свет. Съедено будет быстрее, чем найдено.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. Every house had one of these until the lights went out. It will be eaten faster than it was found.", Rare = true },
        new Def { Id = "NonnaPiaPasqua", Kind = Kind.Snack, Shape = "bag", Mesh = "NonnaPia", Texture = "NonnaPiaPasqua", Kg = 0.258f, Kcal = 850f, Thirst = -6f, Eat = 5f, Ru = "Таралли «Нонна Пиа»", En = "Nonna Pia sushki rings", RuF = "пасхальные", EnF = "easter", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Кто-то берёг это на чёрный день. Он настал. На вкус как выходной.", EnJ = "A spring edition: a rare pack from the days when spring still came. Someone saved this for a rainy day. It came. It tastes like a day off.", Rare = true },
        new Def { Id = "NonnaPiaOlive", Kind = Kind.Snack, Shape = "bag", Mesh = "NonnaPia", Texture = "NonnaPiaOlive", Kg = 0.258f, Kcal = 850f, Thirst = -6f, Eat = 5f, Ru = "Таралли «Нонна Пиа»", En = "Nonna Pia sushki rings", RuF = "с оливками", EnF = "olive", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Таралли от нонны: варёные, потом печёные, потом съеденные до приезда гостей. Пережило хозяина, кота и две зимы. Ветер унесёт запах прямо к берлоге. Ешьте быстрее.", EnJ = "Nonna's taralli: boiled, then baked, then eaten before the guests arrive. It outlived its owner, the cat and two winters. The wind carries the smell straight to the den. Eat faster.", Rare = false },
        new Def { Id = "NonnaPiaPizza", Kind = Kind.Snack, Shape = "bag", Mesh = "NonnaPia", Texture = "NonnaPiaPizza", Kg = 0.258f, Kcal = 850f, Thirst = -6f, Eat = 5f, Ru = "Таралли «Нонна Пиа»", En = "Nonna Pia sushki rings", RuF = "пицца", EnF = "pizza", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Таралли от нонны: варёные, потом печёные, потом съеденные до приезда гостей. Такое обычно находили за диваном, как всё лучшее в жизни. Пополняет запас соли и веры в человечество.", EnJ = "Nonna's taralli: boiled, then baked, then eaten before the guests arrive. These were usually found behind the sofa, like all the best things in life. Restores your salt and your faith in mankind.", Rare = false },
        new Def { Id = "NonnaPiaVino", Kind = Kind.Snack, Shape = "bag", Mesh = "NonnaPia", Texture = "NonnaPiaVino", Kg = 0.258f, Kcal = 850f, Thirst = -6f, Eat = 5f, Ru = "Таралли «Нонна Пиа»", En = "Nonna Pia sushki rings", RuF = "на белом вине", EnF = "white wine", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Таралли от нонны: варёные, потом печёные, потом съеденные до приезда гостей. Последний завоз был до того, как упали самолёты. Хорошо идёт под треск поленьев.", EnJ = "Nonna's taralli: boiled, then baked, then eaten before the guests arrive. The last delivery came before the planes fell. Goes down well with crackling logs.", Rare = false },
        new Def { Id = "NonnaPiaRosmarino", Kind = Kind.Snack, Shape = "bag", Mesh = "NonnaPia", Texture = "NonnaPiaRosmarino", Kg = 0.258f, Kcal = 850f, Thirst = -6f, Eat = 5f, Ru = "Таралли «Нонна Пиа»", En = "Nonna Pia sushki rings", RuF = "с розмарином", EnF = "rosemary", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Таралли от нонны: варёные, потом печёные, потом съеденные до приезда гостей. Ценник оторван: теперь это бесценно. Руки вытирать о штаны: салфеток не завезли.", EnJ = "Nonna's taralli: boiled, then baked, then eaten before the guests arrive. The price tag is torn off: it is priceless now. Wipe your hands on your trousers: no napkins were delivered.", Rare = false },
        new Def { Id = "NonnaPiaDolci", Kind = Kind.Snack, Shape = "bag", Mesh = "NonnaPia", Texture = "NonnaPiaDolci", Kg = 0.258f, Kcal = 850f, Thirst = -6f, Eat = 5f, Ru = "Таралли «Нонна Пиа»", En = "Nonna Pia sushki rings", RuF = "сладкие с сахаром", EnF = "sugar glazed", RuC = "Италия", EnC = "Italy", Fx = new[] { "SugarDry" }, RuJ = "Таралли от нонны: варёные, потом печёные, потом съеденные до приезда гостей. Дата на шве стёрлась, и слава богу. Маленькая радость размером с ладонь.", EnJ = "Nonna's taralli: boiled, then baked, then eaten before the guests arrive. The date on the seam has rubbed off, thank goodness. A small joy the size of your palm.", Rare = false },
        new Def { Id = "KrokiNaturel", Kind = Kind.Snack, Shape = "bag", Mesh = "Kroki", Texture = "KrokiNaturel", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кроки»", En = "Kroki crisps", RuF = "с солью", EnF = "salted", RuC = "Нидерланды", EnC = "Netherlands", Fx = new[] { "SaltHold" }, RuJ = "Голландские чипсы: внутри когда-то лежали фишки, из-за которых дрались на переменах. Пахнет заправкой у Прибрежного шоссе. Совесть молчит, живот поёт.", EnJ = "Dutch crisps: there used to be flippos inside worth a fight at recess. It smells of the petrol station on the Coastal Highway. Conscience is silent, the belly sings.", Rare = false },
        new Def { Id = "KrokiPaprika", Kind = Kind.Snack, Shape = "bag", Mesh = "Kroki", Texture = "KrokiPaprika", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кроки»", En = "Kroki crisps", RuF = "паприка", EnF = "paprika", RuC = "Нидерланды", EnC = "Netherlands", Fx = new[] { "SaltHold" }, RuJ = "Голландские чипсы: внутри когда-то лежали фишки, из-за которых дрались на переменах. Такое возили в бардачке на дальнюю дорогу. Дороги кончились. Проверено поколениями и одной катастрофой.", EnJ = "Dutch crisps: there used to be flippos inside worth a fight at recess. People kept these in the glovebox for long drives. The drives are over. Tested by generations and one catastrophe.", Rare = false },
        new Def { Id = "KrokiBolognese", Kind = Kind.Snack, Shape = "bag", Mesh = "Kroki", Texture = "KrokiBolognese", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кроки»", En = "Kroki crisps", RuF = "болоньезе", EnF = "bolognese", RuC = "Нидерланды", EnC = "Netherlands", Fx = new[] { "SaltHold" }, RuJ = "Голландские чипсы: внутри когда-то лежали фишки, из-за которых дрались на переменах. Мыши не тронули. Думайте сами. Оставьте пару штук на перевал. Не оставите.", EnJ = "Dutch crisps: there used to be flippos inside worth a fight at recess. The mice left it alone. Draw your own conclusions. Save a couple for the pass. You will not.", Rare = false },
        new Def { Id = "KrokiPickles", Kind = Kind.Snack, Shape = "bag", Mesh = "Kroki", Texture = "KrokiPickles", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кроки»", En = "Kroki crisps", RuF = "пиклз", EnF = "pickles", RuC = "Нидерланды", EnC = "Netherlands", Fx = new[] { "SaltHold" }, RuJ = "Голландские чипсы: внутри когда-то лежали фишки, из-за которых дрались на переменах. Рыбаки брали такое на лёд вместо обеда. Здесь это считается ужином при свечах.", EnJ = "Dutch crisps: there used to be flippos inside worth a fight at recess. Fishermen took this onto the ice instead of lunch. Round here this counts as a candlelit dinner.", Rare = false },
        new Def { Id = "KrokiSpeculaas", Kind = Kind.Snack, Shape = "bag", Mesh = "Kroki", Texture = "KrokiSpeculaas", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кроки»", En = "Kroki crisps", RuF = "спекулас", EnF = "speculaas spice", RuC = "Нидерланды", EnC = "Netherlands", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Смотритель плотины держал такое в заначке. Луна светит, еда хрустит, жизнь налаживается.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. The dam keeper kept a stash of these. The moon shines, the food crunches, life is looking up.", Rare = true },
        new Def { Id = "KrokiOranje", Kind = Kind.Snack, Shape = "bag", Mesh = "Kroki", Texture = "KrokiOranje", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кроки»", En = "Kroki crisps", RuF = "оранжевые ко Дню короля", EnF = "king's day orange", RuC = "Нидерланды", EnC = "Netherlands", Fx = new[] { "SaltHold" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Кто-то спрятал это от детей. Дети не нашли. Снег вокруг не солёный. Это солёное.", EnJ = "A spring edition: a rare pack from the days when spring still came. Someone hid it from the kids. The kids never found it. The snow around is not salty. This is.", Rare = true },
        new Def { Id = "KrokiKetchup", Kind = Kind.Snack, Shape = "bag", Mesh = "Kroki", Texture = "KrokiKetchup", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кроки»", En = "Kroki crisps", RuF = "кетчуп", EnF = "ketchup", RuC = "Нидерланды", EnC = "Netherlands", Fx = new[] { "SaltHold" }, RuJ = "Голландские чипсы: внутри когда-то лежали фишки, из-за которых дрались на переменах. В сельском магазине такое вечно заваливалось за прилавок. Больше таких не делают. Совсем.", EnJ = "Dutch crisps: there used to be flippos inside worth a fight at recess. In the village shop these kept slipping behind the counter. They do not make these any more. At all.", Rare = false },
        new Def { Id = "KrokiCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Kroki", Texture = "KrokiCheese", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кроки»", En = "Kroki crisps", RuF = "сыр и лук", EnF = "cheese & onion", RuC = "Нидерланды", EnC = "Netherlands", Fx = new[] { "SaltHold" }, RuJ = "Голландские чипсы: внутри когда-то лежали фишки, из-за которых дрались на переменах. Ждало покупателя дольше, чем тот прожил. Открывайте тихо: у волков отличный слух.", EnJ = "Dutch crisps: there used to be flippos inside worth a fight at recess. It waited for a buyer longer than the buyer lived. Open it quietly: wolves have excellent hearing.", Rare = false },
        new Def { Id = "KrokiBarbecue", Kind = Kind.Snack, Shape = "bag", Mesh = "Kroki", Texture = "KrokiBarbecue", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кроки»", En = "Kroki crisps", RuF = "барбекю ветчина", EnF = "barbecue ham", RuC = "Нидерланды", EnC = "Netherlands", Fx = new[] { "SaltHold" }, RuJ = "Голландские чипсы: внутри когда-то лежали фишки, из-за которых дрались на переменах. С материка такое больше не привезут. Одной не обойдётся, но вторая неизвестно где.", EnJ = "Dutch crisps: there used to be flippos inside worth a fight at recess. Nobody will bring this from the mainland again. One won't be enough, and nobody knows where the second is.", Rare = false },
        new Def { Id = "KrokiPatatje", Kind = Kind.Snack, Shape = "bag", Mesh = "Kroki", Texture = "KrokiPatatje", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кроки»", En = "Kroki crisps", RuF = "картошка фри с майонезом и луком", EnF = "fries with mayo & onion", RuC = "Нидерланды", EnC = "Netherlands", Fx = new[] { "SaltHold" }, RuJ = "Голландские чипсы: внутри когда-то лежали фишки, из-за которых дрались на переменах. На упаковке иней, внутри всё по-прежнему. Крошки с пола тоже считаются.", EnJ = "Dutch crisps: there used to be flippos inside worth a fight at recess. Frost on the wrapper, business as usual inside. The crumbs on the floor count too.", Rare = false },
        new Def { Id = "KrokiHeinz", Kind = Kind.Snack, Shape = "bag", Mesh = "Kroki", Texture = "KrokiHeinz", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кроки»", En = "Kroki crisps", RuF = "томат и зелень", EnF = "tomato & herbs", RuC = "Нидерланды", EnC = "Netherlands", Fx = new[] { "SaltHold" }, RuJ = "Голландские чипсы: внутри когда-то лежали фишки, из-за которых дрались на переменах. Мороз ему нипочём: твёрже не стало, мягче тоже. Запейте чаем из шиповника и считайте это обедом.", EnJ = "Dutch crisps: there used to be flippos inside worth a fight at recess. The frost did nothing to it: no harder, no softer. Wash it down with rosehip tea and call it lunch.", Rare = false },
        new Def { Id = "KrokiSate", Kind = Kind.Snack, Shape = "bag", Mesh = "Kroki", Texture = "KrokiSate", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Кроки»", En = "Kroki crisps", RuF = "сатай", EnF = "satay", RuC = "Нидерланды", EnC = "Netherlands", Fx = new[] { "SaltHold" }, RuJ = "Голландские чипсы: внутри когда-то лежали фишки, из-за которых дрались на переменах. Из тех времён, когда еду выбирали по вкусу. Медведю не показывать: отнимет вместе с рукой.", EnJ = "Dutch crisps: there used to be flippos inside worth a fight at recess. From the days when people picked food for its taste. Do not show the bear: he will take it, hand and all.", Rare = false },
        new Def { Id = "LajkonykSolone", Kind = Kind.Snack, Shape = "bag", Mesh = "Lajkonyk", Texture = "LajkonykSolone", Kg = 0.208f, Kcal = 780f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Лайконик»", En = "Lajkonyk sticks", RuF = "с солью", EnF = "salted", RuC = "Польша", EnC = "Poland", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Краковская соломка: всадник на пачке скачет к чаю с четырнадцатого века. Чей-то перекус на ночную смену, которая не кончилась. Диетолог не одобрил бы. Диетолога тут нет.", EnJ = "Kraków sticks: the rider on the pack has been galloping to tea since the fourteenth century. Someone's snack for a night shift that never ended. A dietitian would not approve. There is no dietitian here.", Rare = false },
        new Def { Id = "LajkonykSezam", Kind = Kind.Snack, Shape = "bag", Mesh = "Lajkonyk", Texture = "LajkonykSezam", Kg = 0.208f, Kcal = 780f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Лайконик»", En = "Lajkonyk sticks", RuF = "с кунжутом", EnF = "sesame", RuC = "Польша", EnC = "Poland", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Краковская соломка: всадник на пачке скачет к чаю с четырнадцатого века. В охотничьей вышке таким встречали рассвет. Лучше, чем кора. Проверено.", EnJ = "Kraków sticks: the rider on the pack has been galloping to tea since the fourteenth century. In the hunting blind they met the dawn with this. Better than bark. Tested.", Rare = false },
        new Def { Id = "LajkonykMak", Kind = Kind.Snack, Shape = "bag", Mesh = "Lajkonyk", Texture = "LajkonykMak", Kg = 0.208f, Kcal = 780f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Лайконик»", En = "Lajkonyk sticks", RuF = "с маком", EnF = "poppy seed", RuC = "Польша", EnC = "Poland", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Краковская соломка: всадник на пачке скачет к чаю с четырнадцатого века. Такое носили в кармане куртки на всякий случай. Случай настал. Хруст разносится до соседней долины.", EnJ = "Kraków sticks: the rider on the pack has been galloping to tea since the fourteenth century. People carried these in a coat pocket just in case. The case has come. The crunch carries to the next valley.", Rare = false },
        new Def { Id = "LajkonykWigilia", Kind = Kind.Snack, Shape = "bag", Mesh = "Lajkonyk", Texture = "LajkonykWigilia", Kg = 0.208f, Kcal = 780f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Лайконик»", En = "Lajkonyk sticks", RuF = "маковые к сочельнику", EnF = "christmas eve poppy", RuC = "Польша", EnC = "Poland", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Прежний хозяин оставил записку: «Не трогать». Записка сгорела. Ешьте медленно: когда ещё такое найдёте.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. The last owner left a note: 'Do not touch'. The note burned. Eat slowly: who knows when you will find another.", Rare = true },
        new Def { Id = "LajkonykWielkanoc", Kind = Kind.Snack, Shape = "bag", Mesh = "Lajkonyk", Texture = "LajkonykWielkanoc", Kg = 0.208f, Kcal = 780f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Лайконик»", En = "Lajkonyk sticks", RuF = "пасхальные с хреном", EnF = "easter horseradish", RuC = "Польша", EnC = "Poland", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Такими торговали в поезде, пока поезд ходил. К этому просится пиво, а есть только талый снег.", EnJ = "A spring edition: a rare pack from the days when spring still came. They sold these on the train, while the train ran. It begs for a beer, and there is only melted snow.", Rare = true },
        new Def { Id = "LajkonykSer", Kind = Kind.Snack, Shape = "bag", Mesh = "Lajkonyk", Texture = "LajkonykSer", Kg = 0.208f, Kcal = 780f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Лайконик»", En = "Lajkonyk sticks", RuF = "с сыром", EnF = "cheese", RuC = "Польша", EnC = "Poland", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Краковская соломка: всадник на пачке скачет к чаю с четырнадцатого века. Сторож шахты держал такое в ящике стола. Сияние на вкус не влияет. Наверное.", EnJ = "Kraków sticks: the rider on the pack has been galloping to tea since the fourteenth century. The mine watchman kept these in his desk drawer. The aurora does not affect the taste. Probably.", Rare = false },
        new Def { Id = "LajkonykCebula", Kind = Kind.Snack, Shape = "bag", Mesh = "Lajkonyk", Texture = "LajkonykCebula", Kg = 0.208f, Kcal = 780f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Лайконик»", En = "Lajkonyk sticks", RuF = "с луком", EnF = "onion", RuC = "Польша", EnC = "Poland", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Краковская соломка: всадник на пачке скачет к чаю с четырнадцатого века. Лавина прошла мимо, срок годности тоже. После тушёнки из банки это почти ресторан.", EnJ = "Kraków sticks: the rider on the pack has been galloping to tea since the fourteenth century. The avalanche missed it, and so did the best-before date. After stew from a tin this is nearly a restaurant.", Rare = false },
        new Def { Id = "LajkonykPrecelki", Kind = Kind.Snack, Shape = "bag", Mesh = "Lajkonyk", Texture = "LajkonykPrecelki", Kg = 0.208f, Kcal = 780f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Лайконик»", En = "Lajkonyk sticks", RuF = "крендельки", EnF = "mini pretzels", RuC = "Польша", EnC = "Poland", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Краковская соломка: всадник на пачке скачет к чаю с четырнадцатого века. Такое всегда стояло на видном месте, поэтому никто не брал. Делиться не с кем, и это впервые радует.", EnJ = "Kraków sticks: the rider on the pack has been galloping to tea since the fourteenth century. These always stood in plain sight, which is why nobody took them. Nobody to share with, and for once that is good news.", Rare = false },
        new Def { Id = "LajkonykKminek", Kind = Kind.Snack, Shape = "bag", Mesh = "Lajkonyk", Texture = "LajkonykKminek", Kg = 0.208f, Kcal = 780f, Thirst = -6f, Eat = 4f, Ru = "Соломка «Лайконик»", En = "Lajkonyk sticks", RuF = "с тмином", EnF = "caraway", RuC = "Польша", EnC = "Poland", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Краковская соломка: всадник на пачке скачет к чаю с четырнадцатого века. Кто-то открыл, передумал и умер. Не связано. Пальцы потом оближите: зимой калории не выбрасывают.", EnJ = "Kraków sticks: the rider on the pack has been galloping to tea since the fourteenth century. Someone opened it, changed their mind and died. Unrelated. Lick your fingers after: in winter you do not waste calories.", Rare = false },
        new Def { Id = "TsakiriSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "Tsakiri", Texture = "TsakiriSalt", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Цакири»", En = "Tsakiri crisps", RuF = "с солью", EnF = "salted", RuC = "Греция", EnC = "Greece", Fx = new[] { "SaltHold" }, RuJ = "Греческие чипсы: пахнут летом, островом и не этим островом. Такое вечно каталось под сиденьем пикапа. Ворон на ветке уже ждёт свою долю.", EnJ = "Greek crisps: they smell of summer, of an island, and not of this one. One of these was always rolling under a pickup seat. The crow on the branch is already waiting for its share.", Rare = false },
        new Def { Id = "TsakiriOregano", Kind = Kind.Snack, Shape = "bag", Mesh = "Tsakiri", Texture = "TsakiriOregano", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Цакири»", En = "Tsakiri crisps", RuF = "орегано", EnF = "oregano", RuC = "Греция", EnC = "Greece", Fx = new[] { "SaltHold" }, RuJ = "Греческие чипсы: пахнут летом, островом и не этим островом. Привезено паромом, которого больше нет. На морозе хрустит вдвое громче.", EnJ = "Greek crisps: they smell of summer, of an island, and not of this one. Brought over by a ferry that no longer exists. In the frost it crunches twice as loud.", Rare = false },
        new Def { Id = "TsakiriBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Tsakiri", Texture = "TsakiriBBQ", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Цакири»", En = "Tsakiri crisps", RuF = "барбекю", EnF = "barbecue", RuC = "Греция", EnC = "Greece", Fx = new[] { "SaltHold" }, RuJ = "Греческие чипсы: пахнут летом, островом и не этим островом. Раньше это ели под телевизор. Телевизор молчит. Не еда, а настроение. Настроение тоже греет.", EnJ = "Greek crisps: they smell of summer, of an island, and not of this one. People ate this in front of the telly. The telly is silent. Not food but a mood. A mood warms you too.", Rare = false },
        new Def { Id = "TsakiriEaster", Kind = Kind.Snack, Shape = "bag", Mesh = "Tsakiri", Texture = "TsakiriEaster", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Цакири»", En = "Tsakiri crisps", RuF = "пасхальный лимон и орегано", EnF = "easter lemon oregano", RuC = "Греция", EnC = "Greece", Fx = new[] { "SaltHold" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Забыто туристами, которым повезло уехать. Сытости на час, воспоминаний на неделю.", EnJ = "A spring edition: a rare pack from the days when spring still came. Left behind by tourists who were lucky enough to leave. An hour of fullness, a week of memories.", Rare = true },
        new Def { Id = "TsakiriSummer", Kind = Kind.Snack, Shape = "bag", Mesh = "Tsakiri", Texture = "TsakiriSummer", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Цакири»", En = "Tsakiri crisps", RuF = "летний греческий салат", EnF = "summer greek salad", RuC = "Греция", EnC = "Greece", Fx = new[] { "SaltHold" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Механики заедали этим обед, не вытирая рук. Кролик смотрит с осуждением.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. Mechanics ate these for lunch without wiping their hands. The rabbit looks on with disapproval.", Rare = true },
        new Def { Id = "TsakiriVinegar", Kind = Kind.Snack, Shape = "bag", Mesh = "Tsakiri", Texture = "TsakiriVinegar", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Цакири»", En = "Tsakiri crisps", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "Греция", EnC = "Greece", Fx = new[] { "SaltHold" }, RuJ = "Греческие чипсы: пахнут летом, островом и не этим островом. Последнее на всю Одинокую топь. Скорее всего. У костра вкуснее. У костра всё вкуснее.", EnJ = "Greek crisps: they smell of summer, of an island, and not of this one. The last one in all of Forlorn Muskeg. Most likely. It tastes better by the fire. Everything does.", Rare = false },
        new Def { Id = "TsakiriFeta", Kind = Kind.Snack, Shape = "bag", Mesh = "Tsakiri", Texture = "TsakiriFeta", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Цакири»", En = "Tsakiri crisps", RuF = "фета", EnF = "feta cheese", RuC = "Греция", EnC = "Greece", Fx = new[] { "SaltHold" }, RuJ = "Греческие чипсы: пахнут летом, островом и не этим островом. Смотритель маяка грыз такое, ожидая кораблей. Упаковку не выбрасывайте: ею можно разжечь печь.", EnJ = "Greek crisps: they smell of summer, of an island, and not of this one. The lighthouse keeper munched these while waiting for ships. Keep the wrapper: it will light the stove.", Rare = false },
        new Def { Id = "TsakiriTomato", Kind = Kind.Snack, Shape = "bag", Mesh = "Tsakiri", Texture = "TsakiriTomato", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Цакири»", En = "Tsakiri crisps", RuF = "томат и базилик", EnF = "tomato & basil", RuC = "Греция", EnC = "Greece", Fx = new[] { "SaltHold" }, RuJ = "Греческие чипсы: пахнут летом, островом и не этим островом. Полки рушились, а это уцелело. Если это последняя на острове, вы её достойны.", EnJ = "Greek crisps: they smell of summer, of an island, and not of this one. Shelves collapsed and this survived. If this is the last one on the island, you have earned it.", Rare = false },
        new Def { Id = "TsakiriTzatziki", Kind = Kind.Snack, Shape = "bag", Mesh = "Tsakiri", Texture = "TsakiriTzatziki", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Цакири»", En = "Tsakiri crisps", RuF = "цацики", EnF = "tzatziki", RuC = "Греция", EnC = "Greece", Fx = new[] { "SaltHold" }, RuJ = "Греческие чипсы: пахнут летом, островом и не этим островом. Смотритель заповедника называл это ужином. Желудок удивится, но возражать не станет.", EnJ = "Greek crisps: they smell of summer, of an island, and not of this one. The park ranger called this dinner. Your stomach will be surprised but will not object.", Rare = false },
        new Def { Id = "TsakiriOlive", Kind = Kind.Snack, Shape = "bag", Mesh = "Tsakiri", Texture = "TsakiriOlive", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Цакири»", En = "Tsakiri crisps", RuF = "на оливковом масле", EnF = "olive oil", RuC = "Греция", EnC = "Greece", Fx = new[] { "SaltHold" }, RuJ = "Греческие чипсы: пахнут летом, островом и не этим островом. Такое слали посылками с материка. Адресаты выбыли. Запах выдаёт вас за сто шагов. Оно того стоит.", EnJ = "Greek crisps: they smell of summer, of an island, and not of this one. These came in parcels from the mainland. The addressees are gone. The smell gives you away at a hundred paces. Worth it.", Rare = false },
        new Def { Id = "TadimTuzlu", Kind = Kind.Snack, Shape = "bag", Mesh = "Tadim", Texture = "TadimTuzlu", Kg = 0.188f, Kcal = 1040f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Тадым»", En = "Tadim seeds", RuF = "солёные", EnF = "salted", RuC = "Турция", EnC = "Turkey", Fx = new[] { "SeedHabit" }, RuJ = "Турецкие семечки: под них на набережной решаются все вопросы. Иные держали это за лекарство. Тоже лечит. Раньше это называли вредным. Теперь называют едой.", EnJ = "Turkish seeds: every matter gets settled over them on the waterfront. Some people counted this as medicine. Also a cure. They used to call this unhealthy. Now they call it food.", Rare = false },
        new Def { Id = "TadimSiyah", Kind = Kind.Snack, Shape = "bag", Mesh = "Tadim", Texture = "TadimSiyah", Kg = 0.188f, Kcal = 1040f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Тадым»", En = "Tadim seeds", RuF = "чёрные", EnF = "black", RuC = "Турция", EnC = "Turkey", Fx = new[] { "SeedHabit" }, RuJ = "Турецкие семечки: под них на набережной решаются все вопросы. В школьном рюкзаке такое не доживало до обеда. Спальный мешок потом вытряхните.", EnJ = "Turkish seeds: every matter gets settled over them on the waterfront. In a school bag this never lasted till lunch. Shake out your sleeping bag afterwards.", Rare = false },
        new Def { Id = "TadimKabak", Kind = Kind.Snack, Shape = "bag", Mesh = "Tadim", Texture = "TadimKabak", Kg = 0.188f, Kcal = 1040f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Тадым»", En = "Tadim seeds", RuF = "тыквенные", EnF = "pumpkin", RuC = "Турция", EnC = "Turkey", Fx = new[] { "SeedHabit" }, RuJ = "Турецкие семечки: под них на набережной решаются все вопросы. Его обменяли бы на патрон, будь тут с кем меняться. Зимой такое идёт за валюту.", EnJ = "Turkish seeds: every matter gets settled over them on the waterfront. You could trade it for a cartridge, if there were anyone to trade with. In winter this passes for currency.", Rare = false },
        new Def { Id = "TadimBayram", Kind = Kind.Snack, Shape = "bag", Mesh = "Tadim", Texture = "TadimBayram", Kg = 0.188f, Kcal = 1040f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Тадым»", En = "Tadim seeds", RuF = "праздничная смесь", EnF = "festive mix", RuC = "Турция", EnC = "Turkey", Fx = new[] { "SeedHabit" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. На вокзале это стоило втрое дороже. Теперь даром. Торговец дал бы за это тряпку. Вы дадите больше.", EnJ = "A spring edition: a rare pack from the days when spring still came. At the station it cost three times as much. Now it is free. The trader would give a rag for it. You would give more.", Rare = true },
        new Def { Id = "TadimCekirdek", Kind = Kind.Snack, Shape = "bag", Mesh = "Tadim", Texture = "TadimCekirdek", Kg = 0.188f, Kcal = 1040f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Тадым»", En = "Tadim seeds", RuF = "жареные без соли", EnF = "roasted unsalted", RuC = "Турция", EnC = "Turkey", Fx = new[] { "SeedHabit" }, RuJ = "Турецкие семечки: под них на набережной решаются все вопросы. Пережило толчок и даже не помялось. Пока жуёте, метель кажется короче.", EnJ = "Turkish seeds: every matter gets settled over them on the waterfront. It came through the quake without a dent. While you chew, the blizzard seems shorter.", Rare = false },
        new Def { Id = "TadimFistik", Kind = Kind.Snack, Shape = "bag", Mesh = "Tadim", Texture = "TadimFistik", Kg = 0.188f, Kcal = 1040f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Тадым»", En = "Tadim seeds", RuF = "фисташки", EnF = "pistachios", RuC = "Турция", EnC = "Turkey", Fx = new[] { "SeedHabit" }, RuJ = "Турецкие семечки: под них на набережной решаются все вопросы. Китобои такого не ели, но оценили бы. Организм скажет спасибо. Или не скажет.", EnJ = "Turkish seeds: every matter gets settled over them on the waterfront. The whalers never ate this, but they would have approved. Your body will thank you. Or not.", Rare = false },
        new Def { Id = "TadimLeblebi", Kind = Kind.Snack, Shape = "bag", Mesh = "Tadim", Texture = "TadimLeblebi", Kg = 0.188f, Kcal = 1040f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Тадым»", En = "Tadim seeds", RuF = "жареный нут", EnF = "roasted chickpeas", RuC = "Турция", EnC = "Turkey", Fx = new[] { "SeedHabit" }, RuJ = "Турецкие семечки: под них на набережной решаются все вопросы. Осталось после чьего-то дня рождения. Гости не пришли. На третьей горсти забываешь, что вокруг конец света.", EnJ = "Turkish seeds: every matter gets settled over them on the waterfront. Left over from someone's birthday. The guests never came. By the third handful you forget the world has ended.", Rare = false },
        new Def { Id = "TadimKarisik", Kind = Kind.Snack, Shape = "bag", Mesh = "Tadim", Texture = "TadimKarisik", Kg = 0.188f, Kcal = 1040f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Тадым»", En = "Tadim seeds", RuF = "смесь орехов", EnF = "mixed nuts", RuC = "Турция", EnC = "Turkey", Fx = new[] { "SeedHabit" }, RuJ = "Турецкие семечки: под них на набережной решаются все вопросы. Мерзлота хранит лучше любого холодильника. Рыба подо льдом завидует.", EnJ = "Turkish seeds: every matter gets settled over them on the waterfront. Permafrost keeps things better than any fridge. The fish under the ice are jealous.", Rare = false },
        new Def { Id = "TadimFindik", Kind = Kind.Snack, Shape = "bag", Mesh = "Tadim", Texture = "TadimFindik", Kg = 0.188f, Kcal = 1040f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Тадым»", En = "Tadim seeds", RuF = "фундук", EnF = "hazelnuts", RuC = "Турция", EnC = "Turkey", Fx = new[] { "SeedHabit" }, RuJ = "Турецкие семечки: под них на набережной решаются все вопросы. Такое добывали из автомата, который съедал последнюю монету. Олень от такого отказался бы. Олень не голодал.", EnJ = "Turkish seeds: every matter gets settled over them on the waterfront. These came from the vending machine that ate your last coin. A deer would turn it down. A deer has never starved.", Rare = false },
        new Def { Id = "TadimMisir", Kind = Kind.Snack, Shape = "bag", Mesh = "Tadim", Texture = "TadimMisir", Kg = 0.188f, Kcal = 1040f, Thirst = -6f, Eat = 25f, Ru = "Семечки «Тадым»", En = "Tadim seeds", RuF = "жареная кукуруза", EnF = "toasted corn", RuC = "Турция", EnC = "Turkey", Fx = new[] { "SeedHabit" }, RuJ = "Турецкие семечки: под них на набережной решаются все вопросы. Такое брали в лодку под брезент, на весь день. Соль есть, жир есть, совести нет.", EnJ = "Turkish seeds: every matter gets settled over them on the waterfront. People took these out in the boat under the tarpaulin, for the whole day. Salt: yes. Fat: yes. Conscience: none.", Rare = false },
        new Def { Id = "OLVCheez", Kind = Kind.Snack, Shape = "bag", Mesh = "OLV", Texture = "OLVCheez", Kg = 0.168f, Kcal = 880f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «ОЛВ»", En = "OLV corn puffs", RuF = "сырные", EnF = "cheez doodles", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведские сырные дуги: названы в честь завода, а не викинга, увы. С ним кто-то шёл к перевалу и не дошёл. Ешьте до темноты: в темноте крошки не найти.", EnJ = "Swedish cheese arcs: named after the factory, not a Viking, alas. Someone carried it towards the pass and never arrived. Eat before dark: you cannot find crumbs in the dark.", Rare = false },
        new Def { Id = "OLVGrill", Kind = Kind.Snack, Shape = "bag", Mesh = "OLV", Texture = "OLVGrill", Kg = 0.168f, Kcal = 880f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «ОЛВ»", En = "OLV corn puffs", RuF = "гриль", EnF = "grill", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведские сырные дуги: названы в честь завода, а не викинга, увы. С таким сидели у окна с видом на метель. Лучшее, что случится с вами сегодня.", EnJ = "Swedish cheese arcs: named after the factory, not a Viking, alas. People sat with these at a window with a view of the blizzard. The best thing that will happen to you today.", Rare = false },
        new Def { Id = "OLVSourcream", Kind = Kind.Snack, Shape = "bag", Mesh = "OLV", Texture = "OLVSourcream", Kg = 0.168f, Kcal = 880f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «ОЛВ»", En = "OLV corn puffs", RuF = "сметана и лук", EnF = "sourcream & onion", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведские сырные дуги: названы в честь завода, а не викинга, увы. Уцелело там, где сгорело всё остальное. Для полного счастья не хватает только дивана.", EnJ = "Swedish cheese arcs: named after the factory, not a Viking, alas. It survived where everything else burned. All that is missing for perfect happiness is a sofa.", Rare = false },
        new Def { Id = "OLVCrayfish", Kind = Kind.Snack, Shape = "bag", Mesh = "OLV", Texture = "OLVCrayfish", Kg = 0.168f, Kcal = 880f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «ОЛВ»", En = "OLV corn puffs", RuF = "раки с укропом", EnF = "crayfish party dill", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Этим кормили сторожевого пса. Пёс ушёл в волки. Вкус детства, если детство было так себе.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. They fed the guard dog with this. The dog joined the wolves. The taste of childhood, if childhood was so-so.", Rare = true },
        new Def { Id = "OLVJul", Kind = Kind.Snack, Shape = "bag", Mesh = "OLV", Texture = "OLVJul", Kg = 0.168f, Kcal = 880f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «ОЛВ»", En = "OLV corn puffs", RuF = "рождественские пряные", EnF = "christmas spice", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Из запасов лесорубов: брали ящиками. Шуршит как надежда.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. From the loggers' stores: they bought it by the crate. It rustles like hope.", Rare = true },
        new Def { Id = "OLVDill", Kind = Kind.Snack, Shape = "bag", Mesh = "OLV", Texture = "OLVDill", Kg = 0.168f, Kcal = 880f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «ОЛВ»", En = "OLV corn puffs", RuF = "укроп и лук", EnF = "dill & chives", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведские сырные дуги: названы в честь завода, а не викинга, увы. В пост такое не ели. Пост кончился вместе с миром. Голод отступит, жажда придёт. Честный обмен.", EnJ = "Swedish cheese arcs: named after the factory, not a Viking, alas. Nobody ate these during a fast. The fast ended with the world. Hunger leaves, thirst arrives. A fair trade.", Rare = false },
        new Def { Id = "OLVSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "OLV", Texture = "OLVSalt", Kg = 0.168f, Kcal = 880f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «ОЛВ»", En = "OLV corn puffs", RuF = "соль", EnF = "salted", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведские сырные дуги: названы в честь завода, а не викинга, увы. Теперь это ценнее денег. Деньги оставьте. Не согреет, зато отвлечёт.", EnJ = "Swedish cheese arcs: named after the factory, not a Viking, alas. It is worth more than money now. Leave the money. It will not warm you, but it will distract you.", Rare = false },
        new Def { Id = "OLVBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "OLV", Texture = "OLVBacon", Kg = 0.168f, Kcal = 880f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «ОЛВ»", En = "OLV corn puffs", RuF = "бекон", EnF = "bacon", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведские сырные дуги: названы в честь завода, а не викинга, увы. Его несли на пикник. Пикник отменили навсегда. Пума предпочитает мясо. Вам повезло.", EnJ = "Swedish cheese arcs: named after the factory, not a Viking, alas. It was headed for a picnic. The picnic is cancelled forever. The cougar prefers meat. Lucky you.", Rare = false },
        new Def { Id = "OLVHot", Kind = Kind.Snack, Shape = "bag", Mesh = "OLV", Texture = "OLVHot", Kg = 0.168f, Kcal = 880f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «ОЛВ»", En = "OLV corn puffs", RuF = "острый сыр", EnF = "hot cheese", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Шведские сырные дуги: названы в честь завода, а не викинга, увы. Такое стояло у кассы на случай слабости. Сначала попробуйте одну штучку. Шутка: ешьте всё.", EnJ = "Swedish cheese arcs: named after the factory, not a Viking, alas. These stood by the till for moments of weakness. Try just one first. Joke: eat the lot.", Rare = false },
        new Def { Id = "OLVRanch", Kind = Kind.Snack, Shape = "bag", Mesh = "OLV", Texture = "OLVRanch", Kg = 0.168f, Kcal = 880f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «ОЛВ»", En = "OLV corn puffs", RuF = "ранч", EnF = "ranch", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведские сырные дуги: названы в честь завода, а не викинга, увы. Досталось вам, потому что вы дошли первым. Такой ужин не стыдно записать в дневник.", EnJ = "Swedish cheese arcs: named after the factory, not a Viking, alas. It is yours because you got here first. A dinner worth writing in the journal.", Rare = false },
        new Def { Id = "OLVNut", Kind = Kind.Snack, Shape = "bag", Mesh = "OLV", Texture = "OLVNut", Kg = 0.168f, Kcal = 880f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «ОЛВ»", En = "OLV corn puffs", RuF = "арахисовые", EnF = "peanut rings", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведские сырные дуги: названы в честь завода, а не викинга, увы. Упаковка выцвела, внутри время остановилось. Силы прибавит на один сугроб.", EnJ = "Swedish cheese arcs: named after the factory, not a Viking, alas. The wrapper has faded; inside, time stood still. It will carry you one snowdrift further.", Rare = false },
        new Def { Id = "SorlandHavsalt", Kind = Kind.Snack, Shape = "bag", Mesh = "Sorland", Texture = "SorlandHavsalt", Kg = 0.198f, Kcal = 1020f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сёрланнсфлак»", En = "Sorlandsflak crisps", RuF = "морская соль", EnF = "sea salt", RuC = "Норвегия", EnC = "Norway", Fx = new[] { "SaltHold" }, RuJ = "Норвежские чипсы с юга: по их меркам там тепло, всего минус пять. Из чемодана пассажира, который не долетел. Идеально к закату, которого не видно за бураном.", EnJ = "Norwegian crisps from the south: warm by their standards, only minus five. From the suitcase of a passenger who never landed. Perfect with a sunset you cannot see for the storm.", Rare = false },
        new Def { Id = "SorlandPaprika", Kind = Kind.Snack, Shape = "bag", Mesh = "Sorland", Texture = "SorlandPaprika", Kg = 0.198f, Kcal = 1020f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сёрланнсфлак»", En = "Sorlandsflak crisps", RuF = "паприка", EnF = "paprika", RuC = "Норвегия", EnC = "Norway", Fx = new[] { "SaltHold" }, RuJ = "Норвежские чипсы с юга: по их меркам там тепло, всего минус пять. Перезимовало и ничуть не обиделось. Пахнет магазином. Помните магазины?", EnJ = "Norwegian crisps from the south: warm by their standards, only minus five. It made it through the winter and bears no grudge. It smells of a shop. Remember shops?", Rare = false },
        new Def { Id = "SorlandChili", Kind = Kind.Snack, Shape = "bag", Mesh = "Sorland", Texture = "SorlandChili", Kg = 0.198f, Kcal = 1020f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сёрланнсфлак»", En = "Sorlandsflak crisps", RuF = "испанский чили", EnF = "spanish chilli", RuC = "Норвегия", EnC = "Norway", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Норвежские чипсы с юга: по их меркам там тепло, всего минус пять. Запасливая хозяйка купила по акции шесть штук. Мороз не испортил, время не взяло.", EnJ = "Norwegian crisps from the south: warm by their standards, only minus five. A thrifty housewife bought six of these on offer. Frost did not spoil it and time could not take it.", Rare = false },
        new Def { Id = "SorlandRibbe", Kind = Kind.Snack, Shape = "bag", Mesh = "Sorland", Texture = "SorlandRibbe", Kg = 0.198f, Kcal = 1020f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сёрланнсфлак»", En = "Sorlandsflak crisps", RuF = "рождественские рёбрышки", EnF = "christmas pork rib", RuC = "Норвегия", EnC = "Norway", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Кто-то написал на упаковке «моё». Уже нет. В рюкзаке не мнётся. Почти.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. Someone wrote 'mine' on it. Not any more. It does not get crushed in a pack. Almost.", Rare = true },
        new Def { Id = "SorlandPaske", Kind = Kind.Snack, Shape = "bag", Mesh = "Sorland", Texture = "SorlandPaske", Kg = 0.198f, Kcal = 1020f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сёрланнсфлак»", En = "Sorlandsflak crisps", RuF = "пасхальный ягнёнок", EnF = "easter lamb", RuC = "Норвегия", EnC = "Norway", Fx = new[] { "SaltHold" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. В консервном цеху это ели тайком от мастера. Съешьте сейчас: завтра может не быть аппетита.", EnJ = "A spring edition: a rare pack from the days when spring still came. At the cannery they ate this behind the foreman's back. Eat it now: tomorrow you may have no appetite.", Rare = true },
        new Def { Id = "SorlandRomme", Kind = Kind.Snack, Shape = "bag", Mesh = "Sorland", Texture = "SorlandRomme", Kg = 0.198f, Kcal = 1020f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сёрланнсфлак»", En = "Sorlandsflak crisps", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "Норвегия", EnC = "Norway", Fx = new[] { "SaltHold" }, RuJ = "Норвежские чипсы с юга: по их меркам там тепло, всего минус пять. Его не взяли даже мародёры. Они спешили. Хватит дойти до следующей хижины и пожалеть, что кончилось.", EnJ = "Norwegian crisps from the south: warm by their standards, only minus five. Even the looters left it. They were in a hurry. Enough to reach the next cabin and regret it is gone.", Rare = false },
        new Def { Id = "SorlandPepper", Kind = Kind.Snack, Shape = "bag", Mesh = "Sorland", Texture = "SorlandPepper", Kg = 0.198f, Kcal = 1020f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сёрланнсфлак»", En = "Sorlandsflak crisps", RuF = "соль и перец", EnF = "salt & pepper", RuC = "Норвегия", EnC = "Norway", Fx = new[] { "SaltHold" }, RuJ = "Норвежские чипсы с юга: по их меркам там тепло, всего минус пять. Провело зиму на острове, как и вы. От такого не толстеют те, кто ходит по двадцать километров.", EnJ = "Norwegian crisps from the south: warm by their standards, only minus five. It spent the winter on the island, same as you. Nobody who walks twenty kilometres a day gets fat on this.", Rare = false },
        new Def { Id = "SorlandOst", Kind = Kind.Snack, Shape = "bag", Mesh = "Sorland", Texture = "SorlandOst", Kg = 0.198f, Kcal = 1020f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сёрланнсфлак»", En = "Sorlandsflak crisps", RuF = "сыр и лук", EnF = "cheese & onion", RuC = "Норвегия", EnC = "Norway", Fx = new[] { "SaltHold" }, RuJ = "Норвежские чипсы с юга: по их меркам там тепло, всего минус пять. Дети прятали такое под кроватью, в тайнике. Волчья стая не в курсе. Пусть так и будет.", EnJ = "Norwegian crisps from the south: warm by their standards, only minus five. Children hid these under the bed, in a secret place. The wolf pack does not know. Keep it that way.", Rare = false },
        new Def { Id = "SorlandSpansk", Kind = Kind.Snack, Shape = "bag", Mesh = "Sorland", Texture = "SorlandSpansk", Kg = 0.198f, Kcal = 1020f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сёрланнсфлак»", En = "Sorlandsflak crisps", RuF = "испанский чоризо", EnF = "spanish chorizo", RuC = "Норвегия", EnC = "Norway", Fx = new[] { "SaltHold" }, RuJ = "Норвежские чипсы с юга: по их меркам там тепло, всего минус пять. Осталось от геологов вместе с картой и долгами. Хрустеть в засаде не рекомендуется.", EnJ = "Norwegian crisps from the south: warm by their standards, only minus five. Left by the geologists along with a map and some debts. Crunching in an ambush is not recommended.", Rare = false },
        new Def { Id = "SorlandDill", Kind = Kind.Snack, Shape = "bag", Mesh = "Sorland", Texture = "SorlandDill", Kg = 0.198f, Kcal = 1020f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сёрланнсфлак»", En = "Sorlandsflak crisps", RuF = "укроп", EnF = "dill", RuC = "Норвегия", EnC = "Norway", Fx = new[] { "SaltHold" }, RuJ = "Норвежские чипсы с юга: по их меркам там тепло, всего минус пять. На острове такое было праздником и до катастрофы. Лекарство от тоски, отпускается без рецепта.", EnJ = "Norwegian crisps from the south: warm by their standards, only minus five. On the island this was a treat even before the disaster. A cure for the blues, no prescription needed.", Rare = false },
        new Def { Id = "TaffellBroadway", Kind = Kind.Snack, Shape = "bag", Mesh = "Taffell", Texture = "TaffellBroadway", Kg = 0.243f, Kcal = 1260f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Таффель»", En = "Taffell crisps", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "Финляндия", EnC = "Finland", Fx = new[] { "SaltHold" }, RuJ = "Финские чипсы: к ним положен соус, сауна и молчание. С таким слушали радио, которое теперь ловит только треск. Жуйте и думайте о хорошем. Например, о добавке.", EnJ = "Finnish crisps: served with dip, a sauna and silence. People ate these by the radio, which picks up nothing but crackle now. Chew and think of nice things. Seconds, for example.", Rare = false },
        new Def { Id = "TaffellGrill", Kind = Kind.Snack, Shape = "bag", Mesh = "Taffell", Texture = "TaffellGrill", Kg = 0.243f, Kcal = 1260f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Таффель»", En = "Taffell crisps", RuF = "гриль", EnF = "grill", RuC = "Финляндия", EnC = "Finland", Fx = new[] { "SaltHold" }, RuJ = "Финские чипсы: к ним положен соус, сауна и молчание. Крысы прогрызли соседнюю, эту пощадили. К утру от него останется только запах на варежках.", EnJ = "Finnish crisps: served with dip, a sauna and silence. The rats gnawed through the one next to it and spared this. By morning only the smell on your mittens will be left.", Rare = false },
        new Def { Id = "TaffellJuusto", Kind = Kind.Snack, Shape = "bag", Mesh = "Taffell", Texture = "TaffellJuusto", Kg = 0.243f, Kcal = 1260f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Таффель»", En = "Taffell crisps", RuF = "сыр", EnF = "cheese", RuC = "Финляндия", EnC = "Finland", Fx = new[] { "SaltHold" }, RuJ = "Финские чипсы: к ним положен соус, сауна и молчание. Бывший хозяин клялся бросить. Не успел. Тишина вокруг такая, что слышно, как вы жуёте.", EnJ = "Finnish crisps: served with dip, a sauna and silence. The former owner swore to give these up. He ran out of time. It is so quiet you can hear yourself chew.", Rare = false },
        new Def { Id = "TaffellJuhannus", Kind = Kind.Snack, Shape = "bag", Mesh = "Taffell", Texture = "TaffellJuhannus", Kg = 0.243f, Kcal = 1260f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Таффель»", En = "Taffell crisps", RuF = "укроп к Юханнусу", EnF = "midsummer dill", RuC = "Финляндия", EnC = "Finland", Fx = new[] { "SaltHold" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Его катали в кабине трактора три сезона. Не делите на завтра: завтра будет новый голод.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. It rode around in a tractor cab for three seasons. Do not save half for tomorrow: tomorrow brings its own hunger.", Rare = true },
        new Def { Id = "TaffellJoulu", Kind = Kind.Snack, Shape = "bag", Mesh = "Taffell", Texture = "TaffellJoulu", Kg = 0.243f, Kcal = 1260f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Таффель»", En = "Taffell crisps", RuF = "рождественский окорок", EnF = "christmas ham", RuC = "Финляндия", EnC = "Finland", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. После бани такое шло лучше всего. Сосны вокруг делают вид, что не смотрят.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. Nothing went down better after the sauna. The pines around pretend not to watch.", Rare = true },
        new Def { Id = "TaffellSuola", Kind = Kind.Snack, Shape = "bag", Mesh = "Taffell", Texture = "TaffellSuola", Kg = 0.243f, Kcal = 1260f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Таффель»", En = "Taffell crisps", RuF = "соль", EnF = "salted", RuC = "Финляндия", EnC = "Finland", Fx = new[] { "SaltHold" }, RuJ = "Финские чипсы: к ним положен соус, сауна и молчание. В тюрьме на это выменивали что угодно. Калории мелкие, зато свои.", EnJ = "Finnish crisps: served with dip, a sauna and silence. In the prison you could trade one of these for anything. Small calories, but your own.", Rare = false },
        new Def { Id = "TaffellDippi", Kind = Kind.Snack, Shape = "bag", Mesh = "Taffell", Texture = "TaffellDippi", Kg = 0.243f, Kcal = 1260f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Таффель»", En = "Taffell crisps", RuF = "луковый дип", EnF = "onion dip", RuC = "Финляндия", EnC = "Finland", Fx = new[] { "SaltHold" }, RuJ = "Финские чипсы: к ним положен соус, сауна и молчание. Кто-то менял это на сигареты. Сделка сорвалась. После этого даже крапивный чай покажется десертом.", EnJ = "Finnish crisps: served with dip, a sauna and silence. Someone was trading this for cigarettes. The deal fell through. After this even nettle tea feels like dessert.", Rare = false },
        new Def { Id = "TaffellTilli", Kind = Kind.Snack, Shape = "bag", Mesh = "Taffell", Texture = "TaffellTilli", Kg = 0.243f, Kcal = 1260f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Таффель»", En = "Taffell crisps", RuF = "укроп", EnF = "dill", RuC = "Финляндия", EnC = "Finland", Fx = new[] { "SaltHold" }, RuJ = "Финские чипсы: к ним положен соус, сауна и молчание. С ним зимовали на метеостанции, пока было с кем. Нашедшему полагается всё.", EnJ = "Finnish crisps: served with dip, a sauna and silence. They wintered with it at the weather station, while there was a 'they'. Finders keepers, all of it.", Rare = false },
        new Def { Id = "TaffellSavu", Kind = Kind.Snack, Shape = "bag", Mesh = "Taffell", Texture = "TaffellSavu", Kg = 0.243f, Kcal = 1260f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Таффель»", En = "Taffell crisps", RuF = "копчёные", EnF = "smoked", RuC = "Финляндия", EnC = "Finland", Fx = new[] { "SaltHold" }, RuJ = "Финские чипсы: к ним положен соус, сауна и молчание. Такое терялось в кладовке среди крупы и надежд. Зубы целы? Тогда вперёд.", EnJ = "Finnish crisps: served with dip, a sauna and silence. These got lost in the pantry among the grain and the hopes. Teeth intact? Then go ahead.", Rare = false },
        new Def { Id = "BalaajiSalted", Kind = Kind.Snack, Shape = "bag", Mesh = "Balaaji", Texture = "BalaajiSalted", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Баладжи»", En = "Balaaji ridged crisps", RuF = "с солью", EnF = "simply salted", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold" }, RuJ = "Индийские рифлёные чипсы: масала сыплется с них, как снег с ёлки. Его берегли к приезду внуков. Ночью приснится добавка.", EnJ = "Indian ridged crisps: masala falls off them like snow off a spruce. It was being saved for the grandchildren's visit. Tonight you will dream of seconds.", Rare = false },
        new Def { Id = "BalaajiMasala", Kind = Kind.Snack, Shape = "bag", Mesh = "Balaaji", Texture = "BalaajiMasala", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Баладжи»", En = "Balaaji ridged crisps", RuF = "масала", EnF = "masala masti", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Индийские рифлёные чипсы: масала сыплется с них, как снег с ёлки. В баре такое ставили на стойку, бесплатно к пиву. Пива нет. С таким запасом можно пережить ещё один вечер.", EnJ = "Indian ridged crisps: masala falls off them like snow off a spruce. Bars put these out free with a beer. There is no beer. With supplies like this you can survive one more evening.", Rare = false },
        new Def { Id = "BalaajiTomato", Kind = Kind.Snack, Shape = "bag", Mesh = "Balaaji", Texture = "BalaajiTomato", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Баладжи»", En = "Balaaji ridged crisps", RuF = "томат", EnF = "tomato twist", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold" }, RuJ = "Индийские рифлёные чипсы: масала сыплется с них, как снег с ёлки. Такое лежало в каждом доме, пока не погас свет. Пёс бы выпросил половину. Пса нет.", EnJ = "Indian ridged crisps: masala falls off them like snow off a spruce. Every house had one of these until the lights went out. A dog would beg half of it. There is no dog.", Rare = false },
        new Def { Id = "BalaajiChaat", Kind = Kind.Snack, Shape = "bag", Mesh = "Balaaji", Texture = "BalaajiChaat", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Баладжи»", En = "Balaaji ridged crisps", RuF = "чаат", EnF = "chaat chaska", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold" }, RuJ = "Индийские рифлёные чипсы: масала сыплется с них, как снег с ёлки. Кто-то берёг это на чёрный день. Он настал. Съедено будет быстрее, чем найдено.", EnJ = "Indian ridged crisps: masala falls off them like snow off a spruce. Someone saved this for a rainy day. It came. It will be eaten faster than it was found.", Rare = false },
        new Def { Id = "BalaajiMonsoon", Kind = Kind.Snack, Shape = "bag", Mesh = "Balaaji", Texture = "BalaajiMonsoon", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Баладжи»", En = "Balaaji ridged crisps", RuF = "к сезону дождей", EnF = "monsoon masala", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Пережило хозяина, кота и две зимы. На вкус как выходной.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. It outlived its owner, the cat and two winters. It tastes like a day off.", Rare = true },
        new Def { Id = "BalaajiChilli", Kind = Kind.Snack, Shape = "bag", Mesh = "Balaaji", Texture = "BalaajiChilli", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Баладжи»", En = "Balaaji ridged crisps", RuF = "зелёный чили", EnF = "green chilli", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Индийские рифлёные чипсы: масала сыплется с них, как снег с ёлки. Такое обычно находили за диваном, как всё лучшее в жизни. Ветер унесёт запах прямо к берлоге. Ешьте быстрее.", EnJ = "Indian ridged crisps: masala falls off them like snow off a spruce. These were usually found behind the sofa, like all the best things in life. The wind carries the smell straight to the den. Eat faster.", Rare = false },
        new Def { Id = "BalaajiCream", Kind = Kind.Snack, Shape = "bag", Mesh = "Balaaji", Texture = "BalaajiCream", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Баладжи»", En = "Balaaji ridged crisps", RuF = "сметана и лук", EnF = "cream & onion", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold" }, RuJ = "Индийские рифлёные чипсы: масала сыплется с них, как снег с ёлки. Последний завоз был до того, как упали самолёты. Пополняет запас соли и веры в человечество.", EnJ = "Indian ridged crisps: masala falls off them like snow off a spruce. The last delivery came before the planes fell. Restores your salt and your faith in mankind.", Rare = false },
        new Def { Id = "BalaajiCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Balaaji", Texture = "BalaajiCheese", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Баладжи»", En = "Balaaji ridged crisps", RuF = "сыр", EnF = "cheese", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold" }, RuJ = "Индийские рифлёные чипсы: масала сыплется с них, как снег с ёлки. Ценник оторван: теперь это бесценно. Хорошо идёт под треск поленьев.", EnJ = "Indian ridged crisps: masala falls off them like snow off a spruce. The price tag is torn off: it is priceless now. Goes down well with crackling logs.", Rare = false },
        new Def { Id = "BalaajiPudina", Kind = Kind.Snack, Shape = "bag", Mesh = "Balaaji", Texture = "BalaajiPudina", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Баладжи»", En = "Balaaji ridged crisps", RuF = "мята", EnF = "mint", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold" }, RuJ = "Индийские рифлёные чипсы: масала сыплется с них, как снег с ёлки. Дата на шве стёрлась, и слава богу. Руки вытирать о штаны: салфеток не завезли.", EnJ = "Indian ridged crisps: masala falls off them like snow off a spruce. The date on the seam has rubbed off, thank goodness. Wipe your hands on your trousers: no napkins were delivered.", Rare = false },
        new Def { Id = "BalaajiPeri", Kind = Kind.Snack, Shape = "bag", Mesh = "Balaaji", Texture = "BalaajiPeri", Kg = 0.143f, Kcal = 720f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Баладжи»", En = "Balaaji ridged crisps", RuF = "пери-пери", EnF = "peri peri", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Индийские рифлёные чипсы: масала сыплется с них, как снег с ёлки. Пахнет заправкой у Прибрежного шоссе. Маленькая радость размером с ладонь.", EnJ = "Indian ridged crisps: masala falls off them like snow off a spruce. It smells of the petrol station on the Coastal Highway. A small joy the size of your palm.", Rare = false },
        new Def { Id = "MadEnglesAchaari", Kind = Kind.Snack, Shape = "bag", Mesh = "MadEngles", Texture = "MadEnglesAchaari", Kg = 0.08f, Kcal = 360f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Мэд Энглс»", En = "Mad Engles tortilla chips", RuF = "ачари", EnF = "achaari masti", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold" }, RuJ = "Острые треугольники из Индии: углы острые, вкус острее. Такое возили в бардачке на дальнюю дорогу. Дороги кончились. Совесть молчит, живот поёт.", EnJ = "Spicy triangles from India: sharp corners, a sharper taste. People kept these in the glovebox for long drives. The drives are over. Conscience is silent, the belly sings.", Rare = false },
        new Def { Id = "MadEnglesTomato", Kind = Kind.Snack, Shape = "bag", Mesh = "MadEngles", Texture = "MadEnglesTomato", Kg = 0.08f, Kcal = 360f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Мэд Энглс»", En = "Mad Engles tortilla chips", RuF = "томат", EnF = "tomato madness", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold" }, RuJ = "Острые треугольники из Индии: углы острые, вкус острее. Мыши не тронули. Думайте сами. Проверено поколениями и одной катастрофой.", EnJ = "Spicy triangles from India: sharp corners, a sharper taste. The mice left it alone. Draw your own conclusions. Tested by generations and one catastrophe.", Rare = false },
        new Def { Id = "MadEnglesMasala", Kind = Kind.Snack, Shape = "bag", Mesh = "MadEngles", Texture = "MadEnglesMasala", Kg = 0.08f, Kcal = 360f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Мэд Энглс»", En = "Mad Engles tortilla chips", RuF = "масала", EnF = "very peri peri", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Острые треугольники из Индии: углы острые, вкус острее. Рыбаки брали такое на лёд вместо обеда. Оставьте пару штук на перевал. Не оставите.", EnJ = "Spicy triangles from India: sharp corners, a sharper taste. Fishermen took this onto the ice instead of lunch. Save a couple for the pass. You will not.", Rare = false },
        new Def { Id = "MadEnglesChilli", Kind = Kind.Snack, Shape = "bag", Mesh = "MadEngles", Texture = "MadEnglesChilli", Kg = 0.08f, Kcal = 360f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Мэд Энглс»", En = "Mad Engles tortilla chips", RuF = "чили", EnF = "chilli", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Острые треугольники из Индии: углы острые, вкус острее. Смотритель плотины держал такое в заначке. Здесь это считается ужином при свечах.", EnJ = "Spicy triangles from India: sharp corners, a sharper taste. The dam keeper kept a stash of these. Round here this counts as a candlelit dinner.", Rare = false },
        new Def { Id = "MadEnglesCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "MadEngles", Texture = "MadEnglesCheese", Kg = 0.08f, Kcal = 360f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Мэд Энглс»", En = "Mad Engles tortilla chips", RuF = "сыр", EnF = "cheese", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold" }, RuJ = "Острые треугольники из Индии: углы острые, вкус острее. Кто-то спрятал это от детей. Дети не нашли. Луна светит, еда хрустит, жизнь налаживается.", EnJ = "Spicy triangles from India: sharp corners, a sharper taste. Someone hid it from the kids. The kids never found it. The moon shines, the food crunches, life is looking up.", Rare = false },
        new Def { Id = "MadEnglesPizza", Kind = Kind.Snack, Shape = "bag", Mesh = "MadEngles", Texture = "MadEnglesPizza", Kg = 0.08f, Kcal = 360f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Мэд Энглс»", En = "Mad Engles tortilla chips", RuF = "пицца", EnF = "pizza", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold" }, RuJ = "Острые треугольники из Индии: углы острые, вкус острее. В сельском магазине такое вечно заваливалось за прилавок. Снег вокруг не солёный. Это солёное.", EnJ = "Spicy triangles from India: sharp corners, a sharper taste. In the village shop these kept slipping behind the counter. The snow around is not salty. This is.", Rare = false },
        new Def { Id = "MadEnglesMint", Kind = Kind.Snack, Shape = "bag", Mesh = "MadEngles", Texture = "MadEnglesMint", Kg = 0.08f, Kcal = 360f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Мэд Энглс»", En = "Mad Engles tortilla chips", RuF = "мята", EnF = "mint", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold" }, RuJ = "Острые треугольники из Индии: углы острые, вкус острее. Ждало покупателя дольше, чем тот прожил. Больше таких не делают. Совсем.", EnJ = "Spicy triangles from India: sharp corners, a sharper taste. It waited for a buyer longer than the buyer lived. They do not make these any more. At all.", Rare = false },
        new Def { Id = "MadEnglesSizzlin", Kind = Kind.Snack, Shape = "bag", Mesh = "MadEngles", Texture = "MadEnglesSizzlin", Kg = 0.08f, Kcal = 360f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Мэд Энглс»", En = "Mad Engles tortilla chips", RuF = "острый барбекю", EnF = "hot barbecue", RuC = "Индия", EnC = "India", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Острые треугольники из Индии: углы острые, вкус острее. С материка такое больше не привезут. Открывайте тихо: у волков отличный слух.", EnJ = "Spicy triangles from India: sharp corners, a sharper taste. Nobody will bring this from the mainland again. Open it quietly: wolves have excellent hearing.", Rare = false },
        new Def { Id = "HanamyOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "Hanamy", Texture = "HanamyOriginal", Kg = 0.068f, Kcal = 290f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Ханами»", En = "Hanamy shrimp chips", RuF = "оригинальные", EnF = "original", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "SaltHold" }, RuJ = "Тайские креветочные палочки: кривые, как дорога к морю. На упаковке иней, внутри всё по-прежнему. Одной не обойдётся, но вторая неизвестно где.", EnJ = "Thai shrimp sticks: crooked as the road to the sea. Frost on the wrapper, business as usual inside. One won't be enough, and nobody knows where the second is.", Rare = false },
        new Def { Id = "HanamyTomyum", Kind = Kind.Snack, Shape = "bag", Mesh = "Hanamy", Texture = "HanamyTomyum", Kg = 0.068f, Kcal = 290f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Ханами»", En = "Hanamy shrimp chips", RuF = "том-ям", EnF = "tom yum", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "SaltHold" }, RuJ = "Тайские креветочные палочки: кривые, как дорога к морю. Мороз ему нипочём: твёрже не стало, мягче тоже. Крошки с пола тоже считаются.", EnJ = "Thai shrimp sticks: crooked as the road to the sea. The frost did nothing to it: no harder, no softer. The crumbs on the floor count too.", Rare = false },
        new Def { Id = "HanamyNori", Kind = Kind.Snack, Shape = "bag", Mesh = "Hanamy", Texture = "HanamyNori", Kg = 0.068f, Kcal = 290f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Ханами»", En = "Hanamy shrimp chips", RuF = "нори", EnF = "seaweed", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "SaltHold" }, RuJ = "Тайские креветочные палочки: кривые, как дорога к морю. Из тех времён, когда еду выбирали по вкусу. Запейте чаем из шиповника и считайте это обедом.", EnJ = "Thai shrimp sticks: crooked as the road to the sea. From the days when people picked food for its taste. Wash it down with rosehip tea and call it lunch.", Rare = false },
        new Def { Id = "HanamySeafood", Kind = Kind.Snack, Shape = "bag", Mesh = "Hanamy", Texture = "HanamySeafood", Kg = 0.068f, Kcal = 290f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Ханами»", En = "Hanamy shrimp chips", RuF = "морепродукты", EnF = "seafood", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "SaltHold" }, RuJ = "Тайские креветочные палочки: кривые, как дорога к морю. Чей-то перекус на ночную смену, которая не кончилась. Медведю не показывать: отнимет вместе с рукой.", EnJ = "Thai shrimp sticks: crooked as the road to the sea. Someone's snack for a night shift that never ended. Do not show the bear: he will take it, hand and all.", Rare = false },
        new Def { Id = "HanamyChili", Kind = Kind.Snack, Shape = "bag", Mesh = "Hanamy", Texture = "HanamyChili", Kg = 0.068f, Kcal = 290f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Ханами»", En = "Hanamy shrimp chips", RuF = "сладкий чили", EnF = "sweet chilli", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Тайские креветочные палочки: кривые, как дорога к морю. В охотничьей вышке таким встречали рассвет. Диетолог не одобрил бы. Диетолога тут нет.", EnJ = "Thai shrimp sticks: crooked as the road to the sea. In the hunting blind they met the dawn with this. A dietitian would not approve. There is no dietitian here.", Rare = false },
        new Def { Id = "HanamyGarlic", Kind = Kind.Snack, Shape = "bag", Mesh = "Hanamy", Texture = "HanamyGarlic", Kg = 0.068f, Kcal = 290f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Ханами»", En = "Hanamy shrimp chips", RuF = "чеснок", EnF = "garlic", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "SaltHold" }, RuJ = "Тайские креветочные палочки: кривые, как дорога к морю. Такое носили в кармане куртки на всякий случай. Случай настал. Лучше, чем кора. Проверено.", EnJ = "Thai shrimp sticks: crooked as the road to the sea. People carried these in a coat pocket just in case. The case has come. Better than bark. Tested.", Rare = false },
        new Def { Id = "HanamyCrab", Kind = Kind.Snack, Shape = "bag", Mesh = "Hanamy", Texture = "HanamyCrab", Kg = 0.068f, Kcal = 290f, Thirst = -7f, Eat = 4f, Ru = "Креветочные чипсы «Ханами»", En = "Hanamy shrimp chips", RuF = "краб карри", EnF = "crab curry", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Тайские креветочные палочки: кривые, как дорога к морю. Прежний хозяин оставил записку: «Не трогать». Записка сгорела. Хруст разносится до соседней долины.", EnJ = "Thai shrimp sticks: crooked as the road to the sea. The last owner left a note: 'Do not touch'. The note burned. The crunch carries to the next valley.", Rare = false },
        new Def { Id = "KoKeCoconut", Kind = Kind.Snack, Shape = "can", Mesh = "KoKe", Texture = "KoKeCoconut", Kg = 0.26f, Kcal = 1200f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «Ко-Кэ»", En = "Ko-Ke coated peanuts", RuF = "кокосовые сливки", EnF = "coconut cream", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "SugarDry" }, RuJ = "Тайский арахис в хрустящей корочке: банка открывается с хлопком, как праздник. Такими торговали в поезде, пока поезд ходил. Ешьте медленно: когда ещё такое найдёте.", EnJ = "Thai peanuts in a crunchy crust: the can opens with a pop, like a holiday. They sold these on the train, while the train ran. Eat slowly: who knows when you will find another.", Rare = false },
        new Def { Id = "KoKeTomyum", Kind = Kind.Snack, Shape = "can", Mesh = "KoKe", Texture = "KoKeTomyum", Kg = 0.26f, Kcal = 1200f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «Ко-Кэ»", En = "Ko-Ke coated peanuts", RuF = "том-ям", EnF = "tom yum", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "Sinew" }, RuJ = "Тайский арахис в хрустящей корочке: банка открывается с хлопком, как праздник. Сторож шахты держал такое в ящике стола. К этому просится пиво, а есть только талый снег.", EnJ = "Thai peanuts in a crunchy crust: the can opens with a pop, like a holiday. The mine watchman kept these in his desk drawer. It begs for a beer, and there is only melted snow.", Rare = false },
        new Def { Id = "KoKeWasabi", Kind = Kind.Snack, Shape = "can", Mesh = "KoKe", Texture = "KoKeWasabi", Kg = 0.26f, Kcal = 1200f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «Ко-Кэ»", En = "Ko-Ke coated peanuts", RuF = "васаби", EnF = "nori wasabi", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Тайский арахис в хрустящей корочке: банка открывается с хлопком, как праздник. Лавина прошла мимо, срок годности тоже. Сияние на вкус не влияет. Наверное.", EnJ = "Thai peanuts in a crunchy crust: the can opens with a pop, like a holiday. The avalanche missed it, and so did the best-before date. The aurora does not affect the taste. Probably.", Rare = false },
        new Def { Id = "KoKeShrimp", Kind = Kind.Snack, Shape = "can", Mesh = "KoKe", Texture = "KoKeShrimp", Kg = 0.26f, Kcal = 1200f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «Ко-Кэ»", En = "Ko-Ke coated peanuts", RuF = "креветка", EnF = "shrimp", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "Sinew" }, RuJ = "Тайский арахис в хрустящей корочке: банка открывается с хлопком, как праздник. Такое всегда стояло на видном месте, поэтому никто не брал. После тушёнки из банки это почти ресторан.", EnJ = "Thai peanuts in a crunchy crust: the can opens with a pop, like a holiday. These always stood in plain sight, which is why nobody took them. After stew from a tin this is nearly a restaurant.", Rare = false },
        new Def { Id = "KoKeBBQ", Kind = Kind.Snack, Shape = "can", Mesh = "KoKe", Texture = "KoKeBBQ", Kg = 0.26f, Kcal = 1200f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «Ко-Кэ»", En = "Ko-Ke coated peanuts", RuF = "барбекю", EnF = "barbecue", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "Sinew" }, RuJ = "Тайский арахис в хрустящей корочке: банка открывается с хлопком, как праздник. Кто-то открыл, передумал и умер. Не связано. Делиться не с кем, и это впервые радует.", EnJ = "Thai peanuts in a crunchy crust: the can opens with a pop, like a holiday. Someone opened it, changed their mind and died. Unrelated. Nobody to share with, and for once that is good news.", Rare = false },
        new Def { Id = "KoKeChicken", Kind = Kind.Snack, Shape = "can", Mesh = "KoKe", Texture = "KoKeChicken", Kg = 0.26f, Kcal = 1200f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «Ко-Кэ»", En = "Ko-Ke coated peanuts", RuF = "курица", EnF = "chicken", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "Sinew" }, RuJ = "Тайский арахис в хрустящей корочке: банка открывается с хлопком, как праздник. Такое вечно каталось под сиденьем пикапа. Пальцы потом оближите: зимой калории не выбрасывают.", EnJ = "Thai peanuts in a crunchy crust: the can opens with a pop, like a holiday. One of these was always rolling under a pickup seat. Lick your fingers after: in winter you do not waste calories.", Rare = false },
        new Def { Id = "KoKeCoffee", Kind = Kind.Snack, Shape = "can", Mesh = "KoKe", Texture = "KoKeCoffee", Kg = 0.26f, Kcal = 1200f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «Ко-Кэ»", En = "Ko-Ke coated peanuts", RuF = "кофе", EnF = "coffee", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "Sinew" }, RuJ = "Тайский арахис в хрустящей корочке: банка открывается с хлопком, как праздник. Привезено паромом, которого больше нет. Ворон на ветке уже ждёт свою долю.", EnJ = "Thai peanuts in a crunchy crust: the can opens with a pop, like a holiday. Brought over by a ferry that no longer exists. The crow on the branch is already waiting for its share.", Rare = false },
        new Def { Id = "KoKeChili", Kind = Kind.Snack, Shape = "can", Mesh = "KoKe", Texture = "KoKeChili", Kg = 0.26f, Kcal = 1200f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «Ко-Кэ»", En = "Ko-Ke coated peanuts", RuF = "сладкий чили", EnF = "sweet chilli", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Тайский арахис в хрустящей корочке: банка открывается с хлопком, как праздник. Раньше это ели под телевизор. Телевизор молчит. На морозе хрустит вдвое громче.", EnJ = "Thai peanuts in a crunchy crust: the can opens with a pop, like a holiday. People ate this in front of the telly. The telly is silent. In the frost it crunches twice as loud.", Rare = false },
        new Def { Id = "KoKeNori", Kind = Kind.Snack, Shape = "can", Mesh = "KoKe", Texture = "KoKeNori", Kg = 0.26f, Kcal = 1200f, Thirst = -7f, Eat = 5f, Ru = "Арахис в хрустящей корочке «Ко-Кэ»", En = "Ko-Ke coated peanuts", RuF = "нори", EnF = "seaweed", RuC = "Таиланд", EnC = "Thailand", Fx = new[] { "Sinew" }, RuJ = "Тайский арахис в хрустящей корочке: банка открывается с хлопком, как праздник. Забыто туристами, которым повезло уехать. Не еда, а настроение. Настроение тоже греет.", EnJ = "Thai peanuts in a crunchy crust: the can opens with a pop, like a holiday. Left behind by tourists who were lucky enough to leave. Not food but a mood. A mood warms you too.", Rare = false },
        new Def { Id = "ChitattoSapi", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitatto", Texture = "ChitattoSapi", Kg = 0.076f, Kcal = 360f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Читатто»", En = "Chitatto ridged crisps", RuF = "говядина на углях", EnF = "beef barbeque", RuC = "Индонезия", EnC = "Indonesia", Fx = new[] { "SaltHold" }, RuJ = "Индонезийские рифлёные чипсы: у каждого вкуса характер уличной кухни Джакарты. Механики заедали этим обед, не вытирая рук. Сытости на час, воспоминаний на неделю.", EnJ = "Indonesian ridged crisps: every flavour has the temper of a Jakarta street kitchen. Mechanics ate these for lunch without wiping their hands. An hour of fullness, a week of memories.", Rare = false },
        new Def { Id = "ChitattoAyam", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitatto", Texture = "ChitattoAyam", Kg = 0.076f, Kcal = 360f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Читатто»", En = "Chitatto ridged crisps", RuF = "курица со специями", EnF = "spiced chicken", RuC = "Индонезия", EnC = "Indonesia", Fx = new[] { "SaltHold" }, RuJ = "Индонезийские рифлёные чипсы: у каждого вкуса характер уличной кухни Джакарты. Последнее на всю Одинокую топь. Скорее всего. Кролик смотрит с осуждением.", EnJ = "Indonesian ridged crisps: every flavour has the temper of a Jakarta street kitchen. The last one in all of Forlorn Muskeg. Most likely. The rabbit looks on with disapproval.", Rare = false },
        new Def { Id = "ChitattoGoreng", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitatto", Texture = "ChitattoGoreng", Kg = 0.076f, Kcal = 360f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Читатто»", En = "Chitatto ridged crisps", RuF = "ми горенг", EnF = "mi goreng", RuC = "Индонезия", EnC = "Indonesia", Fx = new[] { "SaltHold" }, RuJ = "Индонезийские рифлёные чипсы: у каждого вкуса характер уличной кухни Джакарты. Смотритель маяка грыз такое, ожидая кораблей. У костра вкуснее. У костра всё вкуснее.", EnJ = "Indonesian ridged crisps: every flavour has the temper of a Jakarta street kitchen. The lighthouse keeper munched these while waiting for ships. It tastes better by the fire. Everything does.", Rare = false },
        new Def { Id = "ChitattoLebaran", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitatto", Texture = "ChitattoLebaran", Kg = 0.076f, Kcal = 360f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Читатто»", En = "Chitatto ridged crisps", RuF = "праздничные", EnF = "festive", RuC = "Индонезия", EnC = "Indonesia", Fx = new[] { "SaltHold" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Полки рушились, а это уцелело. Упаковку не выбрасывайте: ею можно разжечь печь.", EnJ = "A spring edition: a rare pack from the days when spring still came. Shelves collapsed and this survived. Keep the wrapper: it will light the stove.", Rare = true },
        new Def { Id = "ChitattoKeju", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitatto", Texture = "ChitattoKeju", Kg = 0.076f, Kcal = 360f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Читатто»", En = "Chitatto ridged crisps", RuF = "сыр", EnF = "cheese", RuC = "Индонезия", EnC = "Indonesia", Fx = new[] { "SaltHold" }, RuJ = "Индонезийские рифлёные чипсы: у каждого вкуса характер уличной кухни Джакарты. Смотритель заповедника называл это ужином. Если это последняя на острове, вы её достойны.", EnJ = "Indonesian ridged crisps: every flavour has the temper of a Jakarta street kitchen. The park ranger called this dinner. If this is the last one on the island, you have earned it.", Rare = false },
        new Def { Id = "ChitattoRendang", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitatto", Texture = "ChitattoRendang", Kg = 0.076f, Kcal = 360f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Читатто»", En = "Chitatto ridged crisps", RuF = "ренданг", EnF = "rendang", RuC = "Индонезия", EnC = "Indonesia", Fx = new[] { "SaltHold" }, RuJ = "Индонезийские рифлёные чипсы: у каждого вкуса характер уличной кухни Джакарты. Такое слали посылками с материка. Адресаты выбыли. Желудок удивится, но возражать не станет.", EnJ = "Indonesian ridged crisps: every flavour has the temper of a Jakarta street kitchen. These came in parcels from the mainland. The addressees are gone. Your stomach will be surprised but will not object.", Rare = false },
        new Def { Id = "ChitattoSambal", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitatto", Texture = "ChitattoSambal", Kg = 0.076f, Kcal = 360f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Читатто»", En = "Chitatto ridged crisps", RuF = "самбал", EnF = "sambal", RuC = "Индонезия", EnC = "Indonesia", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Индонезийские рифлёные чипсы: у каждого вкуса характер уличной кухни Джакарты. Иные держали это за лекарство. Тоже лечит. Запах выдаёт вас за сто шагов. Оно того стоит.", EnJ = "Indonesian ridged crisps: every flavour has the temper of a Jakarta street kitchen. Some people counted this as medicine. Also a cure. The smell gives you away at a hundred paces. Worth it.", Rare = false },
        new Def { Id = "ChitattoRumput", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitatto", Texture = "ChitattoRumput", Kg = 0.076f, Kcal = 360f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Читатто»", En = "Chitatto ridged crisps", RuF = "нори", EnF = "seaweed", RuC = "Индонезия", EnC = "Indonesia", Fx = new[] { "SaltHold" }, RuJ = "Индонезийские рифлёные чипсы: у каждого вкуса характер уличной кухни Джакарты. В школьном рюкзаке такое не доживало до обеда. Раньше это называли вредным. Теперь называют едой.", EnJ = "Indonesian ridged crisps: every flavour has the temper of a Jakarta street kitchen. In a school bag this never lasted till lunch. They used to call this unhealthy. Now they call it food.", Rare = false },
        new Def { Id = "ChitattoIndomi", Kind = Kind.Snack, Shape = "bag", Mesh = "Chitatto", Texture = "ChitattoIndomi", Kg = 0.076f, Kcal = 360f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Читатто»", En = "Chitatto ridged crisps", RuF = "жареная лапша", EnF = "fried noodles", RuC = "Индонезия", EnC = "Indonesia", Fx = new[] { "SaltHold" }, RuJ = "Индонезийские рифлёные чипсы: у каждого вкуса характер уличной кухни Джакарты. Его обменяли бы на патрон, будь тут с кем меняться. Спальный мешок потом вытряхните.", EnJ = "Indonesian ridged crisps: every flavour has the temper of a Jakarta street kitchen. You could trade it for a cartridge, if there were anyone to trade with. Shake out your sleeping bag afterwards.", Rare = false },
        new Def { Id = "KutelaOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "Kutela", Texture = "KutelaOriginal", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы из маниоки «Кутела»", En = "Kutela crisps", RuF = "оригинальные", EnF = "original", RuC = "Индонезия", EnC = "Indonesia", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из маниоки: картошка тропиков, твёрже характером. На вокзале это стоило втрое дороже. Теперь даром. Зимой такое идёт за валюту.", EnJ = "Cassava crisps: the potato of the tropics, with a harder temper. At the station it cost three times as much. Now it is free. In winter this passes for currency.", Rare = false },
        new Def { Id = "KutelaBalado", Kind = Kind.Snack, Shape = "bag", Mesh = "Kutela", Texture = "KutelaBalado", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы из маниоки «Кутела»", En = "Kutela crisps", RuF = "баладо, острые", EnF = "balado", RuC = "Индонезия", EnC = "Indonesia", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из маниоки: картошка тропиков, твёрже характером. Пережило толчок и даже не помялось. Торговец дал бы за это тряпку. Вы дадите больше.", EnJ = "Cassava crisps: the potato of the tropics, with a harder temper. It came through the quake without a dent. The trader would give a rag for it. You would give more.", Rare = false },
        new Def { Id = "KutelaBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Kutela", Texture = "KutelaBBQ", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы из маниоки «Кутела»", En = "Kutela crisps", RuF = "барбекю", EnF = "barbeque", RuC = "Индонезия", EnC = "Indonesia", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из маниоки: картошка тропиков, твёрже характером. Китобои такого не ели, но оценили бы. Пока жуёте, метель кажется короче.", EnJ = "Cassava crisps: the potato of the tropics, with a harder temper. The whalers never ate this, but they would have approved. While you chew, the blizzard seems shorter.", Rare = false },
        new Def { Id = "KutelaKeju", Kind = Kind.Snack, Shape = "bag", Mesh = "Kutela", Texture = "KutelaKeju", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы из маниоки «Кутела»", En = "Kutela crisps", RuF = "сыр", EnF = "cheese", RuC = "Индонезия", EnC = "Indonesia", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из маниоки: картошка тропиков, твёрже характером. Осталось после чьего-то дня рождения. Гости не пришли. Организм скажет спасибо. Или не скажет.", EnJ = "Cassava crisps: the potato of the tropics, with a harder temper. Left over from someone's birthday. The guests never came. Your body will thank you. Or not.", Rare = false },
        new Def { Id = "KutelaJagung", Kind = Kind.Snack, Shape = "bag", Mesh = "Kutela", Texture = "KutelaJagung", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы из маниоки «Кутела»", En = "Kutela crisps", RuF = "жареная кукуруза", EnF = "roasted corn", RuC = "Индонезия", EnC = "Indonesia", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из маниоки: картошка тропиков, твёрже характером. Мерзлота хранит лучше любого холодильника. На третьей горсти забываешь, что вокруг конец света.", EnJ = "Cassava crisps: the potato of the tropics, with a harder temper. Permafrost keeps things better than any fridge. By the third handful you forget the world has ended.", Rare = false },
        new Def { Id = "KutelaPedas", Kind = Kind.Snack, Shape = "bag", Mesh = "Kutela", Texture = "KutelaPedas", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы из маниоки «Кутела»", En = "Kutela crisps", RuF = "острые", EnF = "hot", RuC = "Индонезия", EnC = "Indonesia", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Чипсы из маниоки: картошка тропиков, твёрже характером. Такое добывали из автомата, который съедал последнюю монету. Рыба подо льдом завидует.", EnJ = "Cassava crisps: the potato of the tropics, with a harder temper. These came from the vending machine that ate your last coin. The fish under the ice are jealous.", Rare = false },
        new Def { Id = "KutelaAyam", Kind = Kind.Snack, Shape = "bag", Mesh = "Kutela", Texture = "KutelaAyam", Kg = 0.188f, Kcal = 960f, Thirst = -8f, Eat = 4f, Ru = "Чипсы из маниоки «Кутела»", En = "Kutela crisps", RuF = "курица", EnF = "chicken", RuC = "Индонезия", EnC = "Indonesia", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из маниоки: картошка тропиков, твёрже характером. Такое брали в лодку под брезент, на весь день. Олень от такого отказался бы. Олень не голодал.", EnJ = "Cassava crisps: the potato of the tropics, with a harder temper. People took these out in the boat under the tarpaulin, for the whole day. A deer would turn it down. A deer has never starved.", Rare = false },
        new Def { Id = "PiatozCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Piatoz", Texture = "PiatozCheese", Kg = 0.093f, Kcal = 450f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пиатос»", En = "Piatoz crisps", RuF = "сыр", EnF = "cheese", RuC = "Филиппины", EnC = "Philippines", Fx = new[] { "SaltHold" }, RuJ = "Филиппинские шестиугольные чипсы: пчёлы одобряют форму. С ним кто-то шёл к перевалу и не дошёл. Соль есть, жир есть, совести нет.", EnJ = "Filipino hexagon crisps: the bees approve of the shape. Someone carried it towards the pass and never arrived. Salt: yes. Fat: yes. Conscience: none.", Rare = false },
        new Def { Id = "PiatozSour", Kind = Kind.Snack, Shape = "bag", Mesh = "Piatoz", Texture = "PiatozSour", Kg = 0.093f, Kcal = 450f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пиатос»", En = "Piatoz crisps", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "Филиппины", EnC = "Philippines", Fx = new[] { "SaltHold" }, RuJ = "Филиппинские шестиугольные чипсы: пчёлы одобряют форму. С таким сидели у окна с видом на метель. Ешьте до темноты: в темноте крошки не найти.", EnJ = "Filipino hexagon crisps: the bees approve of the shape. People sat with these at a window with a view of the blizzard. Eat before dark: you cannot find crumbs in the dark.", Rare = false },
        new Def { Id = "PiatozBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Piatoz", Texture = "PiatozBBQ", Kg = 0.093f, Kcal = 450f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пиатос»", En = "Piatoz crisps", RuF = "барбекю", EnF = "roadhouse barbecue", RuC = "Филиппины", EnC = "Philippines", Fx = new[] { "SaltHold" }, RuJ = "Филиппинские шестиугольные чипсы: пчёлы одобряют форму. Уцелело там, где сгорело всё остальное. Лучшее, что случится с вами сегодня.", EnJ = "Filipino hexagon crisps: the bees approve of the shape. It survived where everything else burned. The best thing that will happen to you today.", Rare = false },
        new Def { Id = "PiatozPasko", Kind = Kind.Snack, Shape = "bag", Mesh = "Piatoz", Texture = "PiatozPasko", Kg = 0.093f, Kcal = 450f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пиатос»", En = "Piatoz crisps", RuF = "рождественский окорок", EnF = "christmas ham", RuC = "Филиппины", EnC = "Philippines", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Этим кормили сторожевого пса. Пёс ушёл в волки. Для полного счастья не хватает только дивана.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. They fed the guard dog with this. The dog joined the wolves. All that is missing for perfect happiness is a sofa.", Rare = true },
        new Def { Id = "PiatozBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "Piatoz", Texture = "PiatozBacon", Kg = 0.093f, Kcal = 450f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пиатос»", En = "Piatoz crisps", RuF = "бекон", EnF = "bacon", RuC = "Филиппины", EnC = "Philippines", Fx = new[] { "SaltHold" }, RuJ = "Филиппинские шестиугольные чипсы: пчёлы одобряют форму. Из запасов лесорубов: брали ящиками. Вкус детства, если детство было так себе.", EnJ = "Filipino hexagon crisps: the bees approve of the shape. From the loggers' stores: they bought it by the crate. The taste of childhood, if childhood was so-so.", Rare = false },
        new Def { Id = "PiatozRoast", Kind = Kind.Snack, Shape = "bag", Mesh = "Piatoz", Texture = "PiatozRoast", Kg = 0.093f, Kcal = 450f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пиатос»", En = "Piatoz crisps", RuF = "ростбиф", EnF = "roast beef", RuC = "Филиппины", EnC = "Philippines", Fx = new[] { "SaltHold" }, RuJ = "Филиппинские шестиугольные чипсы: пчёлы одобряют форму. В пост такое не ели. Пост кончился вместе с миром. Шуршит как надежда.", EnJ = "Filipino hexagon crisps: the bees approve of the shape. Nobody ate these during a fast. The fast ended with the world. It rustles like hope.", Rare = false },
        new Def { Id = "PiatozNacho", Kind = Kind.Snack, Shape = "bag", Mesh = "Piatoz", Texture = "PiatozNacho", Kg = 0.093f, Kcal = 450f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пиатос»", En = "Piatoz crisps", RuF = "пицца начо", EnF = "nacho pizza", RuC = "Филиппины", EnC = "Philippines", Fx = new[] { "SaltHold" }, RuJ = "Филиппинские шестиугольные чипсы: пчёлы одобряют форму. Теперь это ценнее денег. Деньги оставьте. Голод отступит, жажда придёт. Честный обмен.", EnJ = "Filipino hexagon crisps: the bees approve of the shape. It is worth more than money now. Leave the money. Hunger leaves, thirst arrives. A fair trade.", Rare = false },
        new Def { Id = "PiatozSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "Piatoz", Texture = "PiatozSalt", Kg = 0.093f, Kcal = 450f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Пиатос»", En = "Piatoz crisps", RuF = "соль", EnF = "salted", RuC = "Филиппины", EnC = "Philippines", Fx = new[] { "SaltHold" }, RuJ = "Филиппинские шестиугольные чипсы: пчёлы одобряют форму. Его несли на пикник. Пикник отменили навсегда. Не согреет, зато отвлечёт.", EnJ = "Filipino hexagon crisps: the bees approve of the shape. It was headed for a picnic. The picnic is cancelled forever. It will not warm you, but it will distract you.", Rare = false },
        new Def { Id = "BoiBawangGarlic", Kind = Kind.Snack, Shape = "bag", Mesh = "BoiBawang", Texture = "BoiBawangGarlic", Kg = 0.108f, Kcal = 450f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Бой Баванг»", En = "Boi Bawang toasted corn", RuF = "чеснок", EnF = "garlic", RuC = "Филиппины", EnC = "Philippines", Fx = new[] { "Sinew" }, RuJ = "Филиппинская жареная кукуруза: «бой баванг» значит «чесночный парень», вампиры обходят стороной. Такое стояло у кассы на случай слабости. Пума предпочитает мясо. Вам повезло.", EnJ = "Filipino toasted corn: ‘boy bawang’ means ‘garlic boy’, vampires keep away. These stood by the till for moments of weakness. The cougar prefers meat. Lucky you.", Rare = false },
        new Def { Id = "BoiBawangChili", Kind = Kind.Snack, Shape = "bag", Mesh = "BoiBawang", Texture = "BoiBawangChili", Kg = 0.108f, Kcal = 450f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Бой Баванг»", En = "Boi Bawang toasted corn", RuF = "чили и сыр", EnF = "chili cheese", RuC = "Филиппины", EnC = "Philippines", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Филиппинская жареная кукуруза: «бой баванг» значит «чесночный парень», вампиры обходят стороной. Досталось вам, потому что вы дошли первым. Сначала попробуйте одну штучку. Шутка: ешьте всё.", EnJ = "Filipino toasted corn: ‘boy bawang’ means ‘garlic boy’, vampires keep away. It is yours because you got here first. Try just one first. Joke: eat the lot.", Rare = false },
        new Def { Id = "BoiBawangAdobo", Kind = Kind.Snack, Shape = "bag", Mesh = "BoiBawang", Texture = "BoiBawangAdobo", Kg = 0.108f, Kcal = 450f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Бой Баванг»", En = "Boi Bawang toasted corn", RuF = "адобо", EnF = "adobo", RuC = "Филиппины", EnC = "Philippines", Fx = new[] { "Sinew" }, RuJ = "Филиппинская жареная кукуруза: «бой баванг» значит «чесночный парень», вампиры обходят стороной. Упаковка выцвела, внутри время остановилось. Такой ужин не стыдно записать в дневник.", EnJ = "Filipino toasted corn: ‘boy bawang’ means ‘garlic boy’, vampires keep away. The wrapper has faded; inside, time stood still. A dinner worth writing in the journal.", Rare = false },
        new Def { Id = "BoiBawangLechon", Kind = Kind.Snack, Shape = "bag", Mesh = "BoiBawang", Texture = "BoiBawangLechon", Kg = 0.108f, Kcal = 450f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Бой Баванг»", En = "Boi Bawang toasted corn", RuF = "жареная курица", EnF = "lechon manok", RuC = "Филиппины", EnC = "Philippines", Fx = new[] { "Sinew" }, RuJ = "Филиппинская жареная кукуруза: «бой баванг» значит «чесночный парень», вампиры обходят стороной. Из чемодана пассажира, который не долетел. Силы прибавит на один сугроб.", EnJ = "Filipino toasted corn: ‘boy bawang’ means ‘garlic boy’, vampires keep away. From the suitcase of a passenger who never landed. It will carry you one snowdrift further.", Rare = false },
        new Def { Id = "BoiBawangNocheBuena", Kind = Kind.Snack, Shape = "bag", Mesh = "BoiBawang", Texture = "BoiBawangNocheBuena", Kg = 0.108f, Kcal = 450f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Бой Баванг»", En = "Boi Bawang toasted corn", RuF = "праздничный окорок", EnF = "noche buena ham", RuC = "Филиппины", EnC = "Philippines", Fx = new[] { "Sinew" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Перезимовало и ничуть не обиделось. Идеально к закату, которого не видно за бураном.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. It made it through the winter and bears no grudge. Perfect with a sunset you cannot see for the storm.", Rare = true },
        new Def { Id = "BoiBawangBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "BoiBawang", Texture = "BoiBawangBBQ", Kg = 0.108f, Kcal = 450f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Бой Баванг»", En = "Boi Bawang toasted corn", RuF = "барбекю", EnF = "barbecue", RuC = "Филиппины", EnC = "Philippines", Fx = new[] { "Sinew" }, RuJ = "Филиппинская жареная кукуруза: «бой баванг» значит «чесночный парень», вампиры обходят стороной. Запасливая хозяйка купила по акции шесть штук. Пахнет магазином. Помните магазины?", EnJ = "Filipino toasted corn: ‘boy bawang’ means ‘garlic boy’, vampires keep away. A thrifty housewife bought six of these on offer. It smells of a shop. Remember shops?", Rare = false },
        new Def { Id = "BoiBawangHot", Kind = Kind.Snack, Shape = "bag", Mesh = "BoiBawang", Texture = "BoiBawangHot", Kg = 0.108f, Kcal = 450f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Бой Баванг»", En = "Boi Bawang toasted corn", RuF = "острый чеснок", EnF = "hot garlic", RuC = "Филиппины", EnC = "Philippines", Fx = new[] { "Sinew", "PepperBlood", "Sweat" }, RuJ = "Филиппинская жареная кукуруза: «бой баванг» значит «чесночный парень», вампиры обходят стороной. Кто-то написал на упаковке «моё». Уже нет. Мороз не испортил, время не взяло.", EnJ = "Filipino toasted corn: ‘boy bawang’ means ‘garlic boy’, vampires keep away. Someone wrote 'mine' on it. Not any more. Frost did not spoil it and time could not take it.", Rare = false },
        new Def { Id = "BoiBawangButter", Kind = Kind.Snack, Shape = "bag", Mesh = "BoiBawang", Texture = "BoiBawangButter", Kg = 0.108f, Kcal = 450f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Бой Баванг»", En = "Boi Bawang toasted corn", RuF = "масло", EnF = "butter", RuC = "Филиппины", EnC = "Philippines", Fx = new[] { "Sinew" }, RuJ = "Филиппинская жареная кукуруза: «бой баванг» значит «чесночный парень», вампиры обходят стороной. В консервном цеху это ели тайком от мастера. В рюкзаке не мнётся. Почти.", EnJ = "Filipino toasted corn: ‘boy bawang’ means ‘garlic boy’, vampires keep away. At the cannery they ate this behind the foreman's back. It does not get crushed in a pack. Almost.", Rare = false },
        new Def { Id = "BoiBawangSisig", Kind = Kind.Snack, Shape = "bag", Mesh = "BoiBawang", Texture = "BoiBawangSisig", Kg = 0.108f, Kcal = 450f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Бой Баванг»", En = "Boi Bawang toasted corn", RuF = "сисиг", EnF = "sisig", RuC = "Филиппины", EnC = "Philippines", Fx = new[] { "Sinew" }, RuJ = "Филиппинская жареная кукуруза: «бой баванг» значит «чесночный парень», вампиры обходят стороной. Его не взяли даже мародёры. Они спешили. Съешьте сейчас: завтра может не быть аппетита.", EnJ = "Filipino toasted corn: ‘boy bawang’ means ‘garlic boy’, vampires keep away. Even the looters left it. They were in a hurry. Eat it now: tomorrow you may have no appetite.", Rare = false },
        new Def { Id = "BoiBawangVinegar", Kind = Kind.Snack, Shape = "bag", Mesh = "BoiBawang", Texture = "BoiBawangVinegar", Kg = 0.108f, Kcal = 450f, Thirst = -8f, Eat = 6f, Ru = "Жареная кукуруза «Бой Баванг»", En = "Boi Bawang toasted corn", RuF = "уксус и чеснок", EnF = "vinegar & garlic", RuC = "Филиппины", EnC = "Philippines", Fx = new[] { "Sinew" }, RuJ = "Филиппинская жареная кукуруза: «бой баванг» значит «чесночный парень», вампиры обходят стороной. Провело зиму на острове, как и вы. Хватит дойти до следующей хижины и пожалеть, что кончилось.", EnJ = "Filipino toasted corn: ‘boy bawang’ means ‘garlic boy’, vampires keep away. It spent the winter on the island, same as you. Enough to reach the next cabin and regret it is gone.", Rare = false },
        new Def { Id = "SmifsOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "Smifs", Texture = "SmifsOriginal", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Смифс»", En = "Smif’s ridged crisps", RuF = "оригинальные", EnF = "original", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Австралийские рифлёные чипсы: едят на пляже, отбиваясь от чаек. Дети прятали такое под кроватью, в тайнике. От такого не толстеют те, кто ходит по двадцать километров.", EnJ = "Australian crinkle crisps: eaten on the beach while fighting off the gulls. Children hid these under the bed, in a secret place. Nobody who walks twenty kilometres a day gets fat on this.", Rare = false },
        new Def { Id = "SmifsChicken", Kind = Kind.Snack, Shape = "bag", Mesh = "Smifs", Texture = "SmifsChicken", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Смифс»", En = "Smif’s ridged crisps", RuF = "курица", EnF = "chicken", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Австралийские рифлёные чипсы: едят на пляже, отбиваясь от чаек. Осталось от геологов вместе с картой и долгами. Волчья стая не в курсе. Пусть так и будет.", EnJ = "Australian crinkle crisps: eaten on the beach while fighting off the gulls. Left by the geologists along with a map and some debts. The wolf pack does not know. Keep it that way.", Rare = false },
        new Def { Id = "SmifsVinegar", Kind = Kind.Snack, Shape = "bag", Mesh = "Smifs", Texture = "SmifsVinegar", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Смифс»", En = "Smif’s ridged crisps", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Австралийские рифлёные чипсы: едят на пляже, отбиваясь от чаек. На острове такое было праздником и до катастрофы. Хрустеть в засаде не рекомендуется.", EnJ = "Australian crinkle crisps: eaten on the beach while fighting off the gulls. On the island this was a treat even before the disaster. Crunching in an ambush is not recommended.", Rare = false },
        new Def { Id = "SmifsCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Smifs", Texture = "SmifsCheese", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Смифс»", En = "Smif’s ridged crisps", RuF = "сыр и лук", EnF = "cheese & onion", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Австралийские рифлёные чипсы: едят на пляже, отбиваясь от чаек. С таким слушали радио, которое теперь ловит только треск. Лекарство от тоски, отпускается без рецепта.", EnJ = "Australian crinkle crisps: eaten on the beach while fighting off the gulls. People ate these by the radio, which picks up nothing but crackle now. A cure for the blues, no prescription needed.", Rare = false },
        new Def { Id = "SmifsPrawn", Kind = Kind.Snack, Shape = "bag", Mesh = "Smifs", Texture = "SmifsPrawn", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Смифс»", En = "Smif’s ridged crisps", RuF = "рождественский коктейль из креветок", EnF = "christmas prawn cocktail", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Крысы прогрызли соседнюю, эту пощадили. Жуйте и думайте о хорошем. Например, о добавке.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. The rats gnawed through the one next to it and spared this. Chew and think of nice things. Seconds, for example.", Rare = true },
        new Def { Id = "SmifsXmas", Kind = Kind.Snack, Shape = "bag", Mesh = "Smifs", Texture = "SmifsXmas", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Смифс»", En = "Smif’s ridged crisps", RuF = "рождественская ветчина", EnF = "christmas ham", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Рождественская серия: редкая находка, под ёлку такую уже никто не положит. Бывший хозяин клялся бросить. Не успел. К утру от него останется только запах на варежках.", EnJ = "A Christmas edition: a rare find, nobody will put it under a tree any more. The former owner swore to give these up. He ran out of time. By morning only the smell on your mittens will be left.", Rare = true },
        new Def { Id = "SmifsBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Smifs", Texture = "SmifsBBQ", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Смифс»", En = "Smif’s ridged crisps", RuF = "барбекю", EnF = "barbecue", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Австралийские рифлёные чипсы: едят на пляже, отбиваясь от чаек. Его катали в кабине трактора три сезона. Тишина вокруг такая, что слышно, как вы жуёте.", EnJ = "Australian crinkle crisps: eaten on the beach while fighting off the gulls. It rode around in a tractor cab for three seasons. It is so quiet you can hear yourself chew.", Rare = false },
        new Def { Id = "SmifsSour", Kind = Kind.Snack, Shape = "bag", Mesh = "Smifs", Texture = "SmifsSour", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Смифс»", En = "Smif’s ridged crisps", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Австралийские рифлёные чипсы: едят на пляже, отбиваясь от чаек. После бани такое шло лучше всего. Не делите на завтра: завтра будет новый голод.", EnJ = "Australian crinkle crisps: eaten on the beach while fighting off the gulls. Nothing went down better after the sauna. Do not save half for tomorrow: tomorrow brings its own hunger.", Rare = false },
        new Def { Id = "SmifsTomato", Kind = Kind.Snack, Shape = "bag", Mesh = "Smifs", Texture = "SmifsTomato", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Смифс»", En = "Smif’s ridged crisps", RuF = "томатный соус", EnF = "tomato sauce", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Австралийские рифлёные чипсы: едят на пляже, отбиваясь от чаек. В тюрьме на это выменивали что угодно. Сосны вокруг делают вид, что не смотрят.", EnJ = "Australian crinkle crisps: eaten on the beach while fighting off the gulls. In the prison you could trade one of these for anything. The pines around pretend not to watch.", Rare = false },
        new Def { Id = "SmifsBurger", Kind = Kind.Snack, Shape = "bag", Mesh = "Smifs", Texture = "SmifsBurger", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Смифс»", En = "Smif’s ridged crisps", RuF = "чизбургер", EnF = "cheeseburger", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Австралийские рифлёные чипсы: едят на пляже, отбиваясь от чаек. Кто-то менял это на сигареты. Сделка сорвалась. Калории мелкие, зато свои.", EnJ = "Australian crinkle crisps: eaten on the beach while fighting off the gulls. Someone was trading this for cigarettes. The deal fell through. Small calories, but your own.", Rare = false },
        new Def { Id = "SmifsLamb", Kind = Kind.Snack, Shape = "bag", Mesh = "Smifs", Texture = "SmifsLamb", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Смифс»", En = "Smif’s ridged crisps", RuF = "ягнёнок с мятой", EnF = "lamb & mint", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Австралийские рифлёные чипсы: едят на пляже, отбиваясь от чаек. С ним зимовали на метеостанции, пока было с кем. После этого даже крапивный чай покажется десертом.", EnJ = "Australian crinkle crisps: eaten on the beach while fighting off the gulls. They wintered with it at the weather station, while there was a 'they'. After this even nettle tea feels like dessert.", Rare = false },
        new Def { Id = "SmifsPie", Kind = Kind.Snack, Shape = "bag", Mesh = "Smifs", Texture = "SmifsPie", Kg = 0.178f, Kcal = 910f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Смифс»", En = "Smif’s ridged crisps", RuF = "мясной пирог", EnF = "meat pie", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Австралийские рифлёные чипсы: едят на пляже, отбиваясь от чаек. Такое терялось в кладовке среди крупы и надежд. Нашедшему полагается всё.", EnJ = "Australian crinkle crisps: eaten on the beach while fighting off the gulls. These got lost in the pantry among the grain and the hopes. Finders keepers, all of it.", Rare = false },
        new Def { Id = "SheipsBBQ", Kind = Kind.Snack, Shape = "carton", Mesh = "Sheips", Texture = "SheipsBBQ", Kg = 0.183f, Kcal = 840f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Шейпс»", En = "Sheips crackers", RuF = "барбекю", EnF = "barbecue", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Австралийские крекеры: вкус насыпан сверху так щедро, что пачку вытряхивают в рот. Его берегли к приезду внуков. Зубы целы? Тогда вперёд.", EnJ = "Australian crackers: so much flavour dusted on top that people tip the box into their mouth. It was being saved for the grandchildren's visit. Teeth intact? Then go ahead.", Rare = false },
        new Def { Id = "SheipsPizza", Kind = Kind.Snack, Shape = "carton", Mesh = "Sheips", Texture = "SheipsPizza", Kg = 0.183f, Kcal = 840f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Шейпс»", En = "Sheips crackers", RuF = "пицца", EnF = "pizza", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Австралийские крекеры: вкус насыпан сверху так щедро, что пачку вытряхивают в рот. В баре такое ставили на стойку, бесплатно к пиву. Пива нет. Ночью приснится добавка.", EnJ = "Australian crackers: so much flavour dusted on top that people tip the box into their mouth. Bars put these out free with a beer. There is no beer. Tonight you will dream of seconds.", Rare = false },
        new Def { Id = "SheipsChicken", Kind = Kind.Snack, Shape = "carton", Mesh = "Sheips", Texture = "SheipsChicken", Kg = 0.183f, Kcal = 840f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Шейпс»", En = "Sheips crackers", RuF = "курица", EnF = "chicken crimpy", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Австралийские крекеры: вкус насыпан сверху так щедро, что пачку вытряхивают в рот. Такое лежало в каждом доме, пока не погас свет. С таким запасом можно пережить ещё один вечер.", EnJ = "Australian crackers: so much flavour dusted on top that people tip the box into their mouth. Every house had one of these until the lights went out. With supplies like this you can survive one more evening.", Rare = false },
        new Def { Id = "SheipsCheddar", Kind = Kind.Snack, Shape = "carton", Mesh = "Sheips", Texture = "SheipsCheddar", Kg = 0.183f, Kcal = 840f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Шейпс»", En = "Sheips crackers", RuF = "чеддер", EnF = "cheddar", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Австралийские крекеры: вкус насыпан сверху так щедро, что пачку вытряхивают в рот. Кто-то берёг это на чёрный день. Он настал. Пёс бы выпросил половину. Пса нет.", EnJ = "Australian crackers: so much flavour dusted on top that people tip the box into their mouth. Someone saved this for a rainy day. It came. A dog would beg half of it. There is no dog.", Rare = false },
        new Def { Id = "SheipsFooty", Kind = Kind.Snack, Shape = "carton", Mesh = "Sheips", Texture = "SheipsFooty", Kg = 0.183f, Kcal = 840f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Шейпс»", En = "Sheips crackers", RuF = "к летнему матчу", EnF = "summer match", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Пережило хозяина, кота и две зимы. Съедено будет быстрее, чем найдено.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. It outlived its owner, the cat and two winters. It will be eaten faster than it was found.", Rare = true },
        new Def { Id = "SheipsNacho", Kind = Kind.Snack, Shape = "carton", Mesh = "Sheips", Texture = "SheipsNacho", Kg = 0.183f, Kcal = 840f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Шейпс»", En = "Sheips crackers", RuF = "сыр начо", EnF = "nacho cheese", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Австралийские крекеры: вкус насыпан сверху так щедро, что пачку вытряхивают в рот. Такое обычно находили за диваном, как всё лучшее в жизни. На вкус как выходной.", EnJ = "Australian crackers: so much flavour dusted on top that people tip the box into their mouth. These were usually found behind the sofa, like all the best things in life. It tastes like a day off.", Rare = false },
        new Def { Id = "SheipsSavoury", Kind = Kind.Snack, Shape = "carton", Mesh = "Sheips", Texture = "SheipsSavoury", Kg = 0.183f, Kcal = 840f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Шейпс»", En = "Sheips crackers", RuF = "пряные", EnF = "savoury", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Австралийские крекеры: вкус насыпан сверху так щедро, что пачку вытряхивают в рот. Последний завоз был до того, как упали самолёты. Ветер унесёт запах прямо к берлоге. Ешьте быстрее.", EnJ = "Australian crackers: so much flavour dusted on top that people tip the box into their mouth. The last delivery came before the planes fell. The wind carries the smell straight to the den. Eat faster.", Rare = false },
        new Def { Id = "SheipsBacon", Kind = Kind.Snack, Shape = "carton", Mesh = "Sheips", Texture = "SheipsBacon", Kg = 0.183f, Kcal = 840f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Шейпс»", En = "Sheips crackers", RuF = "сыр и бекон", EnF = "cheese & bacon", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Австралийские крекеры: вкус насыпан сверху так щедро, что пачку вытряхивают в рот. Ценник оторван: теперь это бесценно. Пополняет запас соли и веры в человечество.", EnJ = "Australian crackers: so much flavour dusted on top that people tip the box into their mouth. The price tag is torn off: it is priceless now. Restores your salt and your faith in mankind.", Rare = false },
        new Def { Id = "SheipsCrimpy", Kind = Kind.Snack, Shape = "carton", Mesh = "Sheips", Texture = "SheipsCrimpy", Kg = 0.183f, Kcal = 840f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Шейпс»", En = "Sheips crackers", RuF = "курица с волной", EnF = "crimpy chicken", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Австралийские крекеры: вкус насыпан сверху так щедро, что пачку вытряхивают в рот. Дата на шве стёрлась, и слава богу. Хорошо идёт под треск поленьев.", EnJ = "Australian crackers: so much flavour dusted on top that people tip the box into their mouth. The date on the seam has rubbed off, thank goodness. Goes down well with crackling logs.", Rare = false },
        new Def { Id = "SheipsVegemate", Kind = Kind.Snack, Shape = "carton", Mesh = "Sheips", Texture = "SheipsVegemate", Kg = 0.183f, Kcal = 840f, Thirst = -6f, Eat = 4f, Ru = "Крекеры «Шейпс»", En = "Sheips crackers", RuF = "дрожжевая паста с сыром", EnF = "yeast spread & cheese", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Австралийские крекеры: вкус насыпан сверху так щедро, что пачку вытряхивают в рот. Пахнет заправкой у Прибрежного шоссе. Руки вытирать о штаны: салфеток не завезли.", EnJ = "Australian crackers: so much flavour dusted on top that people tip the box into their mouth. It smells of the petrol station on the Coastal Highway. Wipe your hands on your trousers: no napkins were delivered.", Rare = false },
        new Def { Id = "SymbaBeef", Kind = Kind.Snack, Shape = "bag", Mesh = "Symba", Texture = "SymbaBeef", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Симба»", En = "Symba crisps", RuF = "копчёная говядина", EnF = "smoked beef", RuC = "ЮАР", EnC = "South Africa", Fx = new[] { "SaltHold" }, RuJ = "Южноафриканские чипсы со львом: лев рычит, пачка шуршит. Такое возили в бардачке на дальнюю дорогу. Дороги кончились. Маленькая радость размером с ладонь.", EnJ = "South African crisps with a lion: the lion roars, the bag rustles. People kept these in the glovebox for long drives. The drives are over. A small joy the size of your palm.", Rare = false },
        new Def { Id = "SymbaChutney", Kind = Kind.Snack, Shape = "bag", Mesh = "Symba", Texture = "SymbaChutney", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Симба»", En = "Symba crisps", RuF = "фруктовый чатни", EnF = "fruit chutney", RuC = "ЮАР", EnC = "South Africa", Fx = new[] { "SaltHold" }, RuJ = "Южноафриканские чипсы со львом: лев рычит, пачка шуршит. Мыши не тронули. Думайте сами. Совесть молчит, живот поёт.", EnJ = "South African crisps with a lion: the lion roars, the bag rustles. The mice left it alone. Draw your own conclusions. Conscience is silent, the belly sings.", Rare = false },
        new Def { Id = "SymbaVinegar", Kind = Kind.Snack, Shape = "bag", Mesh = "Symba", Texture = "SymbaVinegar", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Симба»", En = "Symba crisps", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "ЮАР", EnC = "South Africa", Fx = new[] { "SaltHold" }, RuJ = "Южноафриканские чипсы со львом: лев рычит, пачка шуршит. Рыбаки брали такое на лёд вместо обеда. Проверено поколениями и одной катастрофой.", EnJ = "South African crisps with a lion: the lion roars, the bag rustles. Fishermen took this onto the ice instead of lunch. Tested by generations and one catastrophe.", Rare = false },
        new Def { Id = "SymbaCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "Symba", Texture = "SymbaCheese", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Симба»", En = "Symba crisps", RuF = "сыр и лук", EnF = "cheese & onion", RuC = "ЮАР", EnC = "South Africa", Fx = new[] { "SaltHold" }, RuJ = "Южноафриканские чипсы со львом: лев рычит, пачка шуршит. Смотритель плотины держал такое в заначке. Оставьте пару штук на перевал. Не оставите.", EnJ = "South African crisps with a lion: the lion roars, the bag rustles. The dam keeper kept a stash of these. Save a couple for the pass. You will not.", Rare = false },
        new Def { Id = "SymbaBraai", Kind = Kind.Snack, Shape = "bag", Mesh = "Symba", Texture = "SymbaBraai", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Симба»", En = "Symba crisps", RuF = "летний браай", EnF = "summer braai", RuC = "ЮАР", EnC = "South Africa", Fx = new[] { "SaltHold" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Кто-то спрятал это от детей. Дети не нашли. Здесь это считается ужином при свечах.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. Someone hid it from the kids. The kids never found it. Round here this counts as a candlelit dinner.", Rare = true },
        new Def { Id = "SymbaSummer", Kind = Kind.Snack, Shape = "bag", Mesh = "Symba", Texture = "SymbaSummer", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Симба»", En = "Symba crisps", RuF = "летние рёбрышки", EnF = "summer ribs", RuC = "ЮАР", EnC = "South Africa", Fx = new[] { "SaltHold" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. В сельском магазине такое вечно заваливалось за прилавок. Луна светит, еда хрустит, жизнь налаживается.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. In the village shop these kept slipping behind the counter. The moon shines, the food crunches, life is looking up.", Rare = true },
        new Def { Id = "SymbaTomato", Kind = Kind.Snack, Shape = "bag", Mesh = "Symba", Texture = "SymbaTomato", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Симба»", En = "Symba crisps", RuF = "томатный соус", EnF = "tomato sauce", RuC = "ЮАР", EnC = "South Africa", Fx = new[] { "SaltHold" }, RuJ = "Южноафриканские чипсы со львом: лев рычит, пачка шуршит. Ждало покупателя дольше, чем тот прожил. Снег вокруг не солёный. Это солёное.", EnJ = "South African crisps with a lion: the lion roars, the bag rustles. It waited for a buyer longer than the buyer lived. The snow around is not salty. This is.", Rare = false },
        new Def { Id = "SymbaChilli", Kind = Kind.Snack, Shape = "bag", Mesh = "Symba", Texture = "SymbaChilli", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Симба»", En = "Symba crisps", RuF = "мексиканский чили", EnF = "mexican chilli", RuC = "ЮАР", EnC = "South Africa", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Южноафриканские чипсы со львом: лев рычит, пачка шуршит. С материка такое больше не привезут. Больше таких не делают. Совсем.", EnJ = "South African crisps with a lion: the lion roars, the bag rustles. Nobody will bring this from the mainland again. They do not make these any more. At all.", Rare = false },
        new Def { Id = "SymbaSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "Symba", Texture = "SymbaSalt", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Симба»", En = "Symba crisps", RuF = "соль", EnF = "salted", RuC = "ЮАР", EnC = "South Africa", Fx = new[] { "SaltHold" }, RuJ = "Южноафриканские чипсы со львом: лев рычит, пачка шуршит. На упаковке иней, внутри всё по-прежнему. Открывайте тихо: у волков отличный слух.", EnJ = "South African crisps with a lion: the lion roars, the bag rustles. Frost on the wrapper, business as usual inside. Open it quietly: wolves have excellent hearing.", Rare = false },
        new Def { Id = "SymbaCreamy", Kind = Kind.Snack, Shape = "bag", Mesh = "Symba", Texture = "SymbaCreamy", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Симба»", En = "Symba crisps", RuF = "сливочный чеддер", EnF = "creamy cheddar", RuC = "ЮАР", EnC = "South Africa", Fx = new[] { "SaltHold" }, RuJ = "Южноафриканские чипсы со львом: лев рычит, пачка шуршит. Мороз ему нипочём: твёрже не стало, мягче тоже. Одной не обойдётся, но вторая неизвестно где.", EnJ = "South African crisps with a lion: the lion roars, the bag rustles. The frost did nothing to it: no harder, no softer. One won't be enough, and nobody knows where the second is.", Rare = false },
        new Def { Id = "SymbaBiltong", Kind = Kind.Snack, Shape = "bag", Mesh = "Symba", Texture = "SymbaBiltong", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Симба»", En = "Symba crisps", RuF = "билтонг", EnF = "biltong", RuC = "ЮАР", EnC = "South Africa", Fx = new[] { "SaltHold" }, RuJ = "Южноафриканские чипсы со львом: лев рычит, пачка шуршит. Из тех времён, когда еду выбирали по вкусу. Крошки с пола тоже считаются.", EnJ = "South African crisps with a lion: the lion roars, the bag rustles. From the days when people picked food for its taste. The crumbs on the floor count too.", Rare = false },
        new Def { Id = "SymbaMonkey", Kind = Kind.Snack, Shape = "bag", Mesh = "Symba", Texture = "SymbaMonkey", Kg = 0.128f, Kcal = 640f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Симба»", En = "Symba crisps", RuF = "соус обезьяний желудок", EnF = "monkey gland sauce", RuC = "ЮАР", EnC = "South Africa", Fx = new[] { "SaltHold" }, RuJ = "Южноафриканские чипсы со львом: лев рычит, пачка шуршит. Чей-то перекус на ночную смену, которая не кончилась. Запейте чаем из шиповника и считайте это обедом.", EnJ = "South African crisps with a lion: the lion roars, the bag rustles. Someone's snack for a night shift that never ended. Wash it down with rosehip tea and call it lunch.", Rare = false },
        new Def { Id = "BambahPeanut", Kind = Kind.Snack, Shape = "bag", Mesh = "Bambah", Texture = "BambahPeanut", Kg = 0.088f, Kcal = 440f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бамба»", En = "Bambah corn puffs", RuF = "арахисовые", EnF = "peanut", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SaltHold" }, RuJ = "Арахисовые палочки из Израиля: первое слово ребёнка там часто «бамба». В охотничьей вышке таким встречали рассвет. Медведю не показывать: отнимет вместе с рукой.", EnJ = "Peanut puffs from Israel: a child's first word there is often ‘bamba’. In the hunting blind they met the dawn with this. Do not show the bear: he will take it, hand and all.", Rare = false },
        new Def { Id = "BambahNougat", Kind = Kind.Snack, Shape = "bag", Mesh = "Bambah", Texture = "BambahNougat", Kg = 0.088f, Kcal = 440f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бамба»", En = "Bambah corn puffs", RuF = "с нугой внутри", EnF = "nougat filled", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SugarDry" }, RuJ = "Арахисовые палочки из Израиля: первое слово ребёнка там часто «бамба». Такое носили в кармане куртки на всякий случай. Случай настал. Диетолог не одобрил бы. Диетолога тут нет.", EnJ = "Peanut puffs from Israel: a child's first word there is often ‘bamba’. People carried these in a coat pocket just in case. The case has come. A dietitian would not approve. There is no dietitian here.", Rare = false },
        new Def { Id = "BambahSweet", Kind = Kind.Snack, Shape = "bag", Mesh = "Bambah", Texture = "BambahSweet", Kg = 0.088f, Kcal = 440f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бамба»", En = "Bambah corn puffs", RuF = "сладкие красные", EnF = "sweet strawberry", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SugarDry" }, RuJ = "Арахисовые палочки из Израиля: первое слово ребёнка там часто «бамба». Прежний хозяин оставил записку: «Не трогать». Записка сгорела. Лучше, чем кора. Проверено.", EnJ = "Peanut puffs from Israel: a child's first word there is often ‘bamba’. The last owner left a note: 'Do not touch'. The note burned. Better than bark. Tested.", Rare = false },
        new Def { Id = "BambahSufganiyah", Kind = Kind.Snack, Shape = "bag", Mesh = "Bambah", Texture = "BambahSufganiyah", Kg = 0.088f, Kcal = 440f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бамба»", En = "Bambah corn puffs", RuF = "зимний пончик с джемом", EnF = "winter jelly doughnut", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SaltHold" }, RuJ = "Зимняя серия: выпускали на один сезон, а зима тут навсегда. Такими торговали в поезде, пока поезд ходил. Хруст разносится до соседней долины.", EnJ = "A winter edition: made for one season, and here winter is forever. They sold these on the train, while the train ran. The crunch carries to the next valley.", Rare = true },
        new Def { Id = "BambahPurim", Kind = Kind.Snack, Shape = "bag", Mesh = "Bambah", Texture = "BambahPurim", Kg = 0.088f, Kcal = 440f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бамба»", En = "Bambah corn puffs", RuF = "к Пуриму", EnF = "purim", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SaltHold" }, RuJ = "Весенняя серия: редкая пачка из тех времён, когда весна ещё приходила. Сторож шахты держал такое в ящике стола. Ешьте медленно: когда ещё такое найдёте.", EnJ = "A spring edition: a rare pack from the days when spring still came. The mine watchman kept these in his desk drawer. Eat slowly: who knows when you will find another.", Rare = true },
        new Def { Id = "BambahHalva", Kind = Kind.Snack, Shape = "bag", Mesh = "Bambah", Texture = "BambahHalva", Kg = 0.088f, Kcal = 440f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бамба»", En = "Bambah corn puffs", RuF = "с халвой", EnF = "halva filled", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SugarDry" }, RuJ = "Арахисовые палочки из Израиля: первое слово ребёнка там часто «бамба». Лавина прошла мимо, срок годности тоже. Зимой такое идёт за валюту.", EnJ = "Peanut puffs from Israel: a child's first word there is often ‘bamba’. The avalanche missed it, and so did the best-before date. In winter this passes for currency.", Rare = false },
        new Def { Id = "BambahStrawberry", Kind = Kind.Snack, Shape = "bag", Mesh = "Bambah", Texture = "BambahStrawberry", Kg = 0.088f, Kcal = 440f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бамба»", En = "Bambah corn puffs", RuF = "клубничная", EnF = "strawberry", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SugarDry" }, RuJ = "Арахисовые палочки из Израиля: первое слово ребёнка там часто «бамба». Такое всегда стояло на видном месте, поэтому никто не брал. Сияние на вкус не влияет. Наверное.", EnJ = "Peanut puffs from Israel: a child's first word there is often ‘bamba’. These always stood in plain sight, which is why nobody took them. The aurora does not affect the taste. Probably.", Rare = false },
        new Def { Id = "BambahChoco", Kind = Kind.Snack, Shape = "bag", Mesh = "Bambah", Texture = "BambahChoco", Kg = 0.088f, Kcal = 440f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бамба»", En = "Bambah corn puffs", RuF = "в шоколаде", EnF = "chocolate coated", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SugarDry" }, RuJ = "Арахисовые палочки из Израиля: первое слово ребёнка там часто «бамба». Кто-то открыл, передумал и умер. Не связано. После тушёнки из банки это почти ресторан.", EnJ = "Peanut puffs from Israel: a child's first word there is often ‘bamba’. Someone opened it, changed their mind and died. Unrelated. After stew from a tin this is nearly a restaurant.", Rare = false },
        new Def { Id = "BambahHazelnut", Kind = Kind.Snack, Shape = "bag", Mesh = "Bambah", Texture = "BambahHazelnut", Kg = 0.088f, Kcal = 440f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бамба»", En = "Bambah corn puffs", RuF = "с фундучным кремом", EnF = "hazelnut cream", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SugarDry" }, RuJ = "Арахисовые палочки из Израиля: первое слово ребёнка там часто «бамба». Такое вечно каталось под сиденьем пикапа. Делиться не с кем, и это впервые радует.", EnJ = "Peanut puffs from Israel: a child's first word there is often ‘bamba’. One of these was always rolling under a pickup seat. Nobody to share with, and for once that is good news.", Rare = false },
        new Def { Id = "BambahHoney", Kind = Kind.Snack, Shape = "bag", Mesh = "Bambah", Texture = "BambahHoney", Kg = 0.088f, Kcal = 440f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бамба»", En = "Bambah corn puffs", RuF = "мёд", EnF = "honey", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SugarDry" }, RuJ = "Арахисовые палочки из Израиля: первое слово ребёнка там часто «бамба». Привезено паромом, которого больше нет. Пальцы потом оближите: зимой калории не выбрасывают.", EnJ = "Peanut puffs from Israel: a child's first word there is often ‘bamba’. Brought over by a ferry that no longer exists. Lick your fingers after: in winter you do not waste calories.", Rare = false },
        new Def { Id = "BislyGrill", Kind = Kind.Snack, Shape = "bag", Mesh = "Bisly", Texture = "BislyGrill", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бисли»", En = "Bisly corn puffs", RuF = "гриль", EnF = "grill", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SaltHold" }, RuJ = "Израильские хрустяшки: гриль остался дома, вкус поехал с тобой. Раньше это ели под телевизор. Телевизор молчит. Ворон на ветке уже ждёт свою долю.", EnJ = "Israeli crunchies: the grill stayed home, the taste came along. People ate this in front of the telly. The telly is silent. The crow on the branch is already waiting for its share.", Rare = false },
        new Def { Id = "BislyOnion", Kind = Kind.Snack, Shape = "bag", Mesh = "Bisly", Texture = "BislyOnion", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бисли»", En = "Bisly corn puffs", RuF = "лук", EnF = "onion", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SaltHold" }, RuJ = "Израильские хрустяшки: гриль остался дома, вкус поехал с тобой. Забыто туристами, которым повезло уехать. На морозе хрустит вдвое громче.", EnJ = "Israeli crunchies: the grill stayed home, the taste came along. Left behind by tourists who were lucky enough to leave. In the frost it crunches twice as loud.", Rare = false },
        new Def { Id = "BislyFalafel", Kind = Kind.Snack, Shape = "bag", Mesh = "Bisly", Texture = "BislyFalafel", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бисли»", En = "Bisly corn puffs", RuF = "фалафель", EnF = "falafel", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SaltHold" }, RuJ = "Израильские хрустяшки: гриль остался дома, вкус поехал с тобой. Механики заедали этим обед, не вытирая рук. Не еда, а настроение. Настроение тоже греет.", EnJ = "Israeli crunchies: the grill stayed home, the taste came along. Mechanics ate these for lunch without wiping their hands. Not food but a mood. A mood warms you too.", Rare = false },
        new Def { Id = "BislyPizza", Kind = Kind.Snack, Shape = "bag", Mesh = "Bisly", Texture = "BislyPizza", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бисли»", En = "Bisly corn puffs", RuF = "пицца", EnF = "pizza", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SaltHold" }, RuJ = "Израильские хрустяшки: гриль остался дома, вкус поехал с тобой. Последнее на всю Одинокую топь. Скорее всего. Сытости на час, воспоминаний на неделю.", EnJ = "Israeli crunchies: the grill stayed home, the taste came along. The last one in all of Forlorn Muskeg. Most likely. An hour of fullness, a week of memories.", Rare = false },
        new Def { Id = "BislySummer", Kind = Kind.Snack, Shape = "bag", Mesh = "Bisly", Texture = "BislySummer", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бисли»", En = "Bisly corn puffs", RuF = "летний мангал", EnF = "summer barbecue", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SaltHold" }, RuJ = "Летняя серия: редкость. Лето на пачке, сугроб за окном. Смотритель маяка грыз такое, ожидая кораблей. Кролик смотрит с осуждением.", EnJ = "A summer edition: a rarity. Summer on the pack, a snowdrift outside. The lighthouse keeper munched these while waiting for ships. The rabbit looks on with disapproval.", Rare = true },
        new Def { Id = "BislyHanukkah", Kind = Kind.Snack, Shape = "bag", Mesh = "Bisly", Texture = "BislyHanukkah", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бисли»", En = "Bisly corn puffs", RuF = "к Хануке", EnF = "hanukkah", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SaltHold" }, RuJ = "Зимняя серия: выпускали на один сезон, а зима тут навсегда. Полки рушились, а это уцелело. У костра вкуснее. У костра всё вкуснее.", EnJ = "A winter edition: made for one season, and here winter is forever. Shelves collapsed and this survived. It tastes better by the fire. Everything does.", Rare = true },
        new Def { Id = "BislyBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "Bisly", Texture = "BislyBBQ", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бисли»", En = "Bisly corn puffs", RuF = "барбекю", EnF = "barbecue", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SaltHold" }, RuJ = "Израильские хрустяшки: гриль остался дома, вкус поехал с тобой. Смотритель заповедника называл это ужином. Упаковку не выбрасывайте: ею можно разжечь печь.", EnJ = "Israeli crunchies: the grill stayed home, the taste came along. The park ranger called this dinner. Keep the wrapper: it will light the stove.", Rare = false },
        new Def { Id = "BislyTaco", Kind = Kind.Snack, Shape = "bag", Mesh = "Bisly", Texture = "BislyTaco", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бисли»", En = "Bisly corn puffs", RuF = "тако", EnF = "taco", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SaltHold" }, RuJ = "Израильские хрустяшки: гриль остался дома, вкус поехал с тобой. Такое слали посылками с материка. Адресаты выбыли. Если это последняя на острове, вы её достойны.", EnJ = "Israeli crunchies: the grill stayed home, the taste came along. These came in parcels from the mainland. The addressees are gone. If this is the last one on the island, you have earned it.", Rare = false },
        new Def { Id = "BislySmoky", Kind = Kind.Snack, Shape = "bag", Mesh = "Bisly", Texture = "BislySmoky", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бисли»", En = "Bisly corn puffs", RuF = "копчёные", EnF = "smoked", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SaltHold" }, RuJ = "Израильские хрустяшки: гриль остался дома, вкус поехал с тобой. Иные держали это за лекарство. Тоже лечит. Желудок удивится, но возражать не станет.", EnJ = "Israeli crunchies: the grill stayed home, the taste came along. Some people counted this as medicine. Also a cure. Your stomach will be surprised but will not object.", Rare = false },
        new Def { Id = "BislyHot", Kind = Kind.Snack, Shape = "bag", Mesh = "Bisly", Texture = "BislyHot", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бисли»", En = "Bisly corn puffs", RuF = "острые", EnF = "hot", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Израильские хрустяшки: гриль остался дома, вкус поехал с тобой. В школьном рюкзаке такое не доживало до обеда. Запах выдаёт вас за сто шагов. Оно того стоит.", EnJ = "Israeli crunchies: the grill stayed home, the taste came along. In a school bag this never lasted till lunch. The smell gives you away at a hundred paces. Worth it.", Rare = false },
        new Def { Id = "BislyShawarma", Kind = Kind.Snack, Shape = "bag", Mesh = "Bisly", Texture = "BislyShawarma", Kg = 0.078f, Kcal = 380f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные снеки «Бисли»", En = "Bisly corn puffs", RuF = "шаурма", EnF = "shawarma", RuC = "Израиль", EnC = "Israel", Fx = new[] { "SaltHold" }, RuJ = "Израильские хрустяшки: гриль остался дома, вкус поехал с тобой. Его обменяли бы на патрон, будь тут с кем меняться. Раньше это называли вредным. Теперь называют едой.", EnJ = "Israeli crunchies: the grill stayed home, the taste came along. You could trade it for a cartridge, if there were anyone to trade with. They used to call this unhealthy. Now they call it food.", Rare = false },
        new Def { Id = "LeizMaxCheddar", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizMax", Texture = "LeizMaxCheddar", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лейз Макс»", En = "Leiz Max ridged crisps", RuF = "чеддер и лук", EnF = "cheddar & onion", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рёбра глубже, чем мысли в три часа ночи. На вокзале это стоило втрое дороже. Теперь даром. Спальный мешок потом вытряхните.", EnJ = "Ridges deeper than three-in-the-morning thoughts. At the station it cost three times as much. Now it is free. Shake out your sleeping bag afterwards.", Rare = false },
        new Def { Id = "LeizMaxWings", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizMax", Texture = "LeizMaxWings", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лейз Макс»", En = "Leiz Max ridged crisps", RuF = "острые крылышки", EnF = "hot wings", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Рёбра глубже, чем мысли в три часа ночи. Пережило толчок и даже не помялось. Зимой такое идёт за валюту.", EnJ = "Ridges deeper than three-in-the-morning thoughts. It came through the quake without a dent. In winter this passes for currency.", Rare = false },
        new Def { Id = "LeizMaxRibs", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizMax", Texture = "LeizMaxRibs", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лейз Макс»", En = "Leiz Max ridged crisps", RuF = "рёбрышки гриль", EnF = "grilled ribs", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рёбра глубже, чем мысли в три часа ночи. Китобои такого не ели, но оценили бы. Торговец дал бы за это тряпку. Вы дадите больше.", EnJ = "Ridges deeper than three-in-the-morning thoughts. The whalers never ate this, but they would have approved. The trader would give a rag for it. You would give more.", Rare = false },
        new Def { Id = "LeizMaxSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizMax", Texture = "LeizMaxSalt", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лейз Макс»", En = "Leiz Max ridged crisps", RuF = "морская соль", EnF = "sea salt", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рёбра глубже, чем мысли в три часа ночи. Осталось после чьего-то дня рождения. Гости не пришли. Пока жуёте, метель кажется короче.", EnJ = "Ridges deeper than three-in-the-morning thoughts. Left over from someone's birthday. The guests never came. While you chew, the blizzard seems shorter.", Rare = false },
        new Def { Id = "LeizMaxPaprika", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizMax", Texture = "LeizMaxPaprika", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лейз Макс»", En = "Leiz Max ridged crisps", RuF = "копчёная паприка", EnF = "smoked paprika", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рёбра глубже, чем мысли в три часа ночи. Мерзлота хранит лучше любого холодильника. Организм скажет спасибо. Или не скажет.", EnJ = "Ridges deeper than three-in-the-morning thoughts. Permafrost keeps things better than any fridge. Your body will thank you. Or not.", Rare = false },
        new Def { Id = "LeizMaxSour", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizMax", Texture = "LeizMaxSour", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лейз Макс»", En = "Leiz Max ridged crisps", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рёбра глубже, чем мысли в три часа ночи. Такое добывали из автомата, который съедал последнюю монету. На третьей горсти забываешь, что вокруг конец света.", EnJ = "Ridges deeper than three-in-the-morning thoughts. These came from the vending machine that ate your last coin. By the third handful you forget the world has ended.", Rare = false },
        new Def { Id = "LeizMaxPizza", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizMax", Texture = "LeizMaxPizza", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лейз Макс»", En = "Leiz Max ridged crisps", RuF = "пицца четыре сыра", EnF = "four cheese pizza", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рёбра глубже, чем мысли в три часа ночи. Такое брали в лодку под брезент, на весь день. Рыба подо льдом завидует.", EnJ = "Ridges deeper than three-in-the-morning thoughts. People took these out in the boat under the tarpaulin, for the whole day. The fish under the ice are jealous.", Rare = false },
        new Def { Id = "LeizMaxBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizMax", Texture = "LeizMaxBacon", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лейз Макс»", En = "Leiz Max ridged crisps", RuF = "бекон на гриле", EnF = "grilled bacon", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рёбра глубже, чем мысли в три часа ночи. С ним кто-то шёл к перевалу и не дошёл. Олень от такого отказался бы. Олень не голодал.", EnJ = "Ridges deeper than three-in-the-morning thoughts. Someone carried it towards the pass and never arrived. A deer would turn it down. A deer has never starved.", Rare = false },
        new Def { Id = "LeizMaxChili", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizMax", Texture = "LeizMaxChili", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лейз Макс»", En = "Leiz Max ridged crisps", RuF = "чили и лайм", EnF = "chilli lime", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Рёбра глубже, чем мысли в три часа ночи. С таким сидели у окна с видом на метель. Соль есть, жир есть, совести нет.", EnJ = "Ridges deeper than three-in-the-morning thoughts. People sat with these at a window with a view of the blizzard. Salt: yes. Fat: yes. Conscience: none.", Rare = false },
        new Def { Id = "LeizMaxKebab", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizMax", Texture = "LeizMaxKebab", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лейз Макс»", En = "Leiz Max ridged crisps", RuF = "кебаб", EnF = "kebab", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рёбра глубже, чем мысли в три часа ночи. Уцелело там, где сгорело всё остальное. Ешьте до темноты: в темноте крошки не найти.", EnJ = "Ridges deeper than three-in-the-morning thoughts. It survived where everything else burned. Eat before dark: you cannot find crumbs in the dark.", Rare = false },
        new Def { Id = "LeizOvenSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizOven", Texture = "LeizOvenSalt", Kg = 0.133f, Kcal = 550f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лейз из печи»", En = "Leiz Oven Baked crisps", RuF = "нежная соль", EnF = "lightly salted", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Запечены, а не жарены: совесть чиста, пальцы тоже. Этим кормили сторожевого пса. Пёс ушёл в волки. Лучшее, что случится с вами сегодня.", EnJ = "Baked, not fried: a clean conscience and clean fingers. They fed the guard dog with this. The dog joined the wolves. The best thing that will happen to you today.", Rare = false },
        new Def { Id = "LeizOvenTzatziki", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizOven", Texture = "LeizOvenTzatziki", Kg = 0.133f, Kcal = 550f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лейз из печи»", En = "Leiz Oven Baked crisps", RuF = "цацики", EnF = "tzatziki", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Запечены, а не жарены: совесть чиста, пальцы тоже. Из запасов лесорубов: брали ящиками. Для полного счастья не хватает только дивана.", EnJ = "Baked, not fried: a clean conscience and clean fingers. From the loggers' stores: they bought it by the crate. All that is missing for perfect happiness is a sofa.", Rare = false },
        new Def { Id = "LeizOvenMushroom", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizOven", Texture = "LeizOvenMushroom", Kg = 0.133f, Kcal = 550f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лейз из печи»", En = "Leiz Oven Baked crisps", RuF = "лисички в сметане", EnF = "chanterelles in sour cream", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Запечены, а не жарены: совесть чиста, пальцы тоже. В пост такое не ели. Пост кончился вместе с миром. Вкус детства, если детство было так себе.", EnJ = "Baked, not fried: a clean conscience and clean fingers. Nobody ate these during a fast. The fast ended with the world. The taste of childhood, if childhood was so-so.", Rare = false },
        new Def { Id = "LeizOvenPaprika", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizOven", Texture = "LeizOvenPaprika", Kg = 0.133f, Kcal = 550f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лейз из печи»", En = "Leiz Oven Baked crisps", RuF = "паприка на гриле", EnF = "grilled paprika", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Запечены, а не жарены: совесть чиста, пальцы тоже. Теперь это ценнее денег. Деньги оставьте. Шуршит как надежда.", EnJ = "Baked, not fried: a clean conscience and clean fingers. It is worth more than money now. Leave the money. It rustles like hope.", Rare = false },
        new Def { Id = "LeizOvenCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizOven", Texture = "LeizOvenCheese", Kg = 0.133f, Kcal = 550f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лейз из печи»", En = "Leiz Oven Baked crisps", RuF = "сыр и зелень", EnF = "cheese & herbs", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Запечены, а не жарены: совесть чиста, пальцы тоже. Его несли на пикник. Пикник отменили навсегда. Голод отступит, жажда придёт. Честный обмен.", EnJ = "Baked, not fried: a clean conscience and clean fingers. It was headed for a picnic. The picnic is cancelled forever. Hunger leaves, thirst arrives. A fair trade.", Rare = false },
        new Def { Id = "LeizOvenTomato", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizOven", Texture = "LeizOvenTomato", Kg = 0.133f, Kcal = 550f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лейз из печи»", En = "Leiz Oven Baked crisps", RuF = "томаты и базилик", EnF = "tomato & basil", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Запечены, а не жарены: совесть чиста, пальцы тоже. Такое стояло у кассы на случай слабости. Не согреет, зато отвлечёт.", EnJ = "Baked, not fried: a clean conscience and clean fingers. These stood by the till for moments of weakness. It will not warm you, but it will distract you.", Rare = false },
        new Def { Id = "LeizOvenBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizOven", Texture = "LeizOvenBBQ", Kg = 0.133f, Kcal = 550f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лейз из печи»", En = "Leiz Oven Baked crisps", RuF = "барбекю", EnF = "barbecue", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Запечены, а не жарены: совесть чиста, пальцы тоже. Досталось вам, потому что вы дошли первым. Пума предпочитает мясо. Вам повезло.", EnJ = "Baked, not fried: a clean conscience and clean fingers. It is yours because you got here first. The cougar prefers meat. Lucky you.", Rare = false },
        new Def { Id = "LeizOvenYogurt", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizOven", Texture = "LeizOvenYogurt", Kg = 0.133f, Kcal = 550f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лейз из печи»", En = "Leiz Oven Baked crisps", RuF = "йогурт и зелень", EnF = "yoghurt & herbs", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Запечены, а не жарены: совесть чиста, пальцы тоже. Упаковка выцвела, внутри время остановилось. Сначала попробуйте одну штучку. Шутка: ешьте всё.", EnJ = "Baked, not fried: a clean conscience and clean fingers. The wrapper has faded; inside, time stood still. Try just one first. Joke: eat the lot.", Rare = false },
        new Def { Id = "LeizStrongJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizStrong", Texture = "LeizStrongJalapeno", Kg = 0.148f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лейз Стронг»", En = "Leiz Strong ridged crisps", RuF = "халапеньо и сыр", EnF = "jalapeno & cheese", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Вкус бьёт так, что пачку держат двумя руками. Из чемодана пассажира, который не долетел. Такой ужин не стыдно записать в дневник.", EnJ = "The flavour hits so hard you hold the bag with both hands. From the suitcase of a passenger who never landed. A dinner worth writing in the journal.", Rare = false },
        new Def { Id = "LeizStrongWasabi", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizStrong", Texture = "LeizStrongWasabi", Kg = 0.148f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лейз Стронг»", En = "Leiz Strong ridged crisps", RuF = "васаби", EnF = "wasabi", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Вкус бьёт так, что пачку держат двумя руками. Перезимовало и ничуть не обиделось. Силы прибавит на один сугроб.", EnJ = "The flavour hits so hard you hold the bag with both hands. It made it through the winter and bears no grudge. It will carry you one snowdrift further.", Rare = false },
        new Def { Id = "LeizStrongShrimp", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizStrong", Texture = "LeizStrongShrimp", Kg = 0.148f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лейз Стронг»", En = "Leiz Strong ridged crisps", RuF = "королевская креветка", EnF = "king prawn", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Вкус бьёт так, что пачку держат двумя руками. Запасливая хозяйка купила по акции шесть штук. Идеально к закату, которого не видно за бураном.", EnJ = "The flavour hits so hard you hold the bag with both hands. A thrifty housewife bought six of these on offer. Perfect with a sunset you cannot see for the storm.", Rare = false },
        new Def { Id = "LeizStrongChili", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizStrong", Texture = "LeizStrongChili", Kg = 0.148f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лейз Стронг»", En = "Leiz Strong ridged crisps", RuF = "чили и лайм", EnF = "chilli lime", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Вкус бьёт так, что пачку держат двумя руками. Кто-то написал на упаковке «моё». Уже нет. Пахнет магазином. Помните магазины?", EnJ = "The flavour hits so hard you hold the bag with both hands. Someone wrote 'mine' on it. Not any more. It smells of a shop. Remember shops?", Rare = false },
        new Def { Id = "LeizStrongPepper", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizStrong", Texture = "LeizStrongPepper", Kg = 0.148f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лейз Стронг»", En = "Leiz Strong ridged crisps", RuF = "чёрный перец", EnF = "black pepper", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Вкус бьёт так, что пачку держат двумя руками. В консервном цеху это ели тайком от мастера. Мороз не испортил, время не взяло.", EnJ = "The flavour hits so hard you hold the bag with both hands. At the cannery they ate this behind the foreman's back. Frost did not spoil it and time could not take it.", Rare = false },
        new Def { Id = "LeizStrongHorseradish", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizStrong", Texture = "LeizStrongHorseradish", Kg = 0.148f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лейз Стронг»", En = "Leiz Strong ridged crisps", RuF = "холодец с хреном", EnF = "aspic with horseradish", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Вкус бьёт так, что пачку держат двумя руками. Его не взяли даже мародёры. Они спешили. В рюкзаке не мнётся. Почти.", EnJ = "The flavour hits so hard you hold the bag with both hands. Even the looters left it. They were in a hurry. It does not get crushed in a pack. Almost.", Rare = false },
        new Def { Id = "LeizStrongMustard", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizStrong", Texture = "LeizStrongMustard", Kg = 0.148f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лейз Стронг»", En = "Leiz Strong ridged crisps", RuF = "охотничьи колбаски с горчицей", EnF = "hunter's sausages & mustard", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Вкус бьёт так, что пачку держат двумя руками. Провело зиму на острове, как и вы. Съешьте сейчас: завтра может не быть аппетита.", EnJ = "The flavour hits so hard you hold the bag with both hands. It spent the winter on the island, same as you. Eat it now: tomorrow you may have no appetite.", Rare = false },
        new Def { Id = "LeizStrongGarlic", Kind = Kind.Snack, Shape = "bag", Mesh = "LeizStrong", Texture = "LeizStrongGarlic", Kg = 0.148f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лейз Стронг»", En = "Leiz Strong ridged crisps", RuF = "чеснок", EnF = "garlic", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Вкус бьёт так, что пачку держат двумя руками. Дети прятали такое под кроватью, в тайнике. Хватит дойти до следующей хижины и пожалеть, что кончилось.", EnJ = "The flavour hits so hard you hold the bag with both hands. Children hid these under the bed, in a secret place. Enough to reach the next cabin and regret it is gone.", Rare = false },
        new Def { Id = "LeizStaxOriginal", Kind = Kind.Snack, Shape = "tube", Mesh = "LeizStax", Texture = "LeizStaxOriginal", Kg = 0.17f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лейз Стакс»", En = "Leiz Stax stacked crisps", RuF = "оригинальные", EnF = "original", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Чипсы построились в колонну и ждут команды. Осталось от геологов вместе с картой и долгами. От такого не толстеют те, кто ходит по двадцать километров.", EnJ = "The crisps have fallen in line and await the order. Left by the geologists along with a map and some debts. Nobody who walks twenty kilometres a day gets fat on this.", Rare = false },
        new Def { Id = "LeizStaxSour", Kind = Kind.Snack, Shape = "tube", Mesh = "LeizStax", Texture = "LeizStaxSour", Kg = 0.17f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лейз Стакс»", En = "Leiz Stax stacked crisps", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Чипсы построились в колонну и ждут команды. На острове такое было праздником и до катастрофы. Волчья стая не в курсе. Пусть так и будет.", EnJ = "The crisps have fallen in line and await the order. On the island this was a treat even before the disaster. The wolf pack does not know. Keep it that way.", Rare = false },
        new Def { Id = "LeizStaxBBQ", Kind = Kind.Snack, Shape = "tube", Mesh = "LeizStax", Texture = "LeizStaxBBQ", Kg = 0.17f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лейз Стакс»", En = "Leiz Stax stacked crisps", RuF = "мескит-барбекю", EnF = "mesquite barbecue", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Чипсы построились в колонну и ждут команды. С таким слушали радио, которое теперь ловит только треск. Хрустеть в засаде не рекомендуется.", EnJ = "The crisps have fallen in line and await the order. People ate these by the radio, which picks up nothing but crackle now. Crunching in an ambush is not recommended.", Rare = false },
        new Def { Id = "LeizStaxCheese", Kind = Kind.Snack, Shape = "tube", Mesh = "LeizStax", Texture = "LeizStaxCheese", Kg = 0.17f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лейз Стакс»", En = "Leiz Stax stacked crisps", RuF = "сыр", EnF = "cheese", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Чипсы построились в колонну и ждут команды. Крысы прогрызли соседнюю, эту пощадили. Лекарство от тоски, отпускается без рецепта.", EnJ = "The crisps have fallen in line and await the order. The rats gnawed through the one next to it and spared this. A cure for the blues, no prescription needed.", Rare = false },
        new Def { Id = "LeizStaxBacon", Kind = Kind.Snack, Shape = "tube", Mesh = "LeizStax", Texture = "LeizStaxBacon", Kg = 0.17f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лейз Стакс»", En = "Leiz Stax stacked crisps", RuF = "бекон", EnF = "bacon", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Чипсы построились в колонну и ждут команды. Бывший хозяин клялся бросить. Не успел. Жуйте и думайте о хорошем. Например, о добавке.", EnJ = "The crisps have fallen in line and await the order. The former owner swore to give these up. He ran out of time. Chew and think of nice things. Seconds, for example.", Rare = false },
        new Def { Id = "LeizStaxPaprika", Kind = Kind.Snack, Shape = "tube", Mesh = "LeizStax", Texture = "LeizStaxPaprika", Kg = 0.17f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лейз Стакс»", En = "Leiz Stax stacked crisps", RuF = "паприка", EnF = "paprika", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Чипсы построились в колонну и ждут команды. Его катали в кабине трактора три сезона. К утру от него останется только запах на варежках.", EnJ = "The crisps have fallen in line and await the order. It rode around in a tractor cab for three seasons. By morning only the smell on your mittens will be left.", Rare = false },
        new Def { Id = "LeizStaxSalt", Kind = Kind.Snack, Shape = "tube", Mesh = "LeizStax", Texture = "LeizStaxSalt", Kg = 0.17f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Лейз Стакс»", En = "Leiz Stax stacked crisps", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Чипсы построились в колонну и ждут команды. После бани такое шло лучше всего. Тишина вокруг такая, что слышно, как вы жуёте.", EnJ = "The crisps have fallen in line and await the order. Nothing went down better after the sauna. It is so quiet you can hear yourself chew.", Rare = false },
