        new Def { Id = "PringlzXtraDill", Kind = Kind.Snack, Shape = "tube", Mesh = "PringlzXtra", Texture = "PringlzXtraDill", Kg = 0.18f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Принглз Экстра»", En = "Pringlz Xtra crisps", RuF = "жгучий огурец", EnF = "hot dill pickle", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Усач на тубе надел тёмные очки: внутри вкуса вдвое больше, чем приличий. Пережило хозяина, кота и две зимы. Пёс бы выпросил половину. Пса нет.", EnJ = "The moustached man put on shades: twice the flavour, half the manners. It outlived its owner, the cat and two winters. A dog would beg half of it. There is no dog.", Rare = false },
        new Def { Id = "PringlzTortillaNacho", Kind = Kind.Snack, Shape = "tube", Mesh = "PringlzTortilla", Texture = "PringlzTortillaNacho", Kg = 0.19f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Принглз Тортилья»", En = "Pringlz Tortilla chips", RuF = "начо-сыр", EnF = "nacho cheese", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Кукуруза, уложенная в тубу: Мексика, но по линейке. Такое обычно находили за диваном, как всё лучшее в жизни. Съедено будет быстрее, чем найдено.", EnJ = "Corn stacked in a tube: Mexico, but by the ruler. These were usually found behind the sofa, like all the best things in life. It will be eaten faster than it was found.", Rare = false },
        new Def { Id = "PringlzTortillaSalsa", Kind = Kind.Snack, Shape = "tube", Mesh = "PringlzTortilla", Texture = "PringlzTortillaSalsa", Kg = 0.19f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Принглз Тортилья»", En = "Pringlz Tortilla chips", RuF = "сальса", EnF = "zesty salsa", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Кукуруза, уложенная в тубу: Мексика, но по линейке. Последний завоз был до того, как упали самолёты. На вкус как выходной.", EnJ = "Corn stacked in a tube: Mexico, but by the ruler. The last delivery came before the planes fell. It tastes like a day off.", Rare = false },
        new Def { Id = "PringlzTortillaOriginal", Kind = Kind.Snack, Shape = "tube", Mesh = "PringlzTortilla", Texture = "PringlzTortillaOriginal", Kg = 0.19f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Принглз Тортилья»", En = "Pringlz Tortilla chips", RuF = "оригинальные", EnF = "original", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Кукуруза, уложенная в тубу: Мексика, но по линейке. Ценник оторван: теперь это бесценно. Ветер унесёт запах прямо к берлоге. Ешьте быстрее.", EnJ = "Corn stacked in a tube: Mexico, but by the ruler. The price tag is torn off: it is priceless now. The wind carries the smell straight to the den. Eat faster.", Rare = false },
        new Def { Id = "PringlzTortillaRanch", Kind = Kind.Snack, Shape = "tube", Mesh = "PringlzTortilla", Texture = "PringlzTortillaRanch", Kg = 0.19f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Принглз Тортилья»", En = "Pringlz Tortilla chips", RuF = "ранч", EnF = "ranch", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Кукуруза, уложенная в тубу: Мексика, но по линейке. Дата на шве стёрлась, и слава богу. Пополняет запас соли и веры в человечество.", EnJ = "Corn stacked in a tube: Mexico, but by the ruler. The date on the seam has rubbed off, thank goodness. Restores your salt and your faith in mankind.", Rare = false },
        new Def { Id = "PringlzTortillaChili", Kind = Kind.Snack, Shape = "tube", Mesh = "PringlzTortilla", Texture = "PringlzTortillaChili", Kg = 0.19f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Принглз Тортилья»", En = "Pringlz Tortilla chips", RuF = "сладкий чили", EnF = "sweet chilli", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Кукуруза, уложенная в тубу: Мексика, но по линейке. Пахнет заправкой у Прибрежного шоссе. Хорошо идёт под треск поленьев.", EnJ = "Corn stacked in a tube: Mexico, but by the ruler. It smells of the petrol station on the Coastal Highway. Goes down well with crackling logs.", Rare = false },
