        new Def { Id = "PringlzTortillaSour", Kind = Kind.Snack, Shape = "tube", Mesh = "PringlzTortilla", Texture = "PringlzTortillaSour", Kg = 0.19f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Кукурузные чипсы «Принглз Тортилья»", En = "Pringlz Tortilla chips", RuF = "сметана", EnF = "sour cream", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Кукуруза, уложенная в тубу: Мексика, но по линейке. Мыши не тронули. Думайте сами. Маленькая радость размером с ладонь.", EnJ = "Corn stacked in a tube: Mexico, but by the ruler. The mice left it alone. Draw your own conclusions. A small joy the size of your palm.", Rare = false },
