        new Def { Id = "ChitozPuffsJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "ChitozPuffs", Texture = "ChitozPuffsJalapeno", Kg = 0.138f, Kcal = 720f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные шары «Читоз Паффс»", En = "Chitoz Jumbo Puffs", RuF = "халапеньо", EnF = "jalapeno", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Гепард надул щёки: шары тают раньше, чем успеваешь пожалеть. Ждало покупателя дольше, чем тот прожил. Луна светит, еда хрустит, жизнь налаживается.", EnJ = "The cheetah puffed his cheeks: they melt before you can regret it. It waited for a buyer longer than the buyer lived. The moon shines, the food crunches, life is looking up.", Rare = false },
        new Def { Id = "ChitozPuffsHoney", Kind = Kind.Snack, Shape = "bag", Mesh = "ChitozPuffs", Texture = "ChitozPuffsHoney", Kg = 0.138f, Kcal = 720f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные шары «Читоз Паффс»", En = "Chitoz Jumbo Puffs", RuF = "мёд и барбекю", EnF = "honey barbecue", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SugarDry" }, RuJ = "Гепард надул щёки: шары тают раньше, чем успеваешь пожалеть. С материка такое больше не привезут. Не еда, а настроение. Настроение тоже греет.", EnJ = "The cheetah puffed his cheeks: they melt before you can regret it. Nobody will bring this from the mainland again. Not food but a mood. A mood warms you too.", Rare = false },
        new Def { Id = "ChitozPuffsBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "ChitozPuffs", Texture = "ChitozPuffsBacon", Kg = 0.138f, Kcal = 720f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные шары «Читоз Паффс»", En = "Chitoz Jumbo Puffs", RuF = "бекон и чеддер", EnF = "bacon cheddar", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Гепард надул щёки: шары тают раньше, чем успеваешь пожалеть. На упаковке иней, внутри всё по-прежнему. Больше таких не делают. Совсем.", EnJ = "The cheetah puffed his cheeks: they melt before you can regret it. Frost on the wrapper, business as usual inside. They do not make these any more. At all.", Rare = false },
        new Def { Id = "ChitozPuffsCaramel", Kind = Kind.Snack, Shape = "bag", Mesh = "ChitozPuffs", Texture = "ChitozPuffsCaramel", Kg = 0.138f, Kcal = 720f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные шары «Читоз Паффс»", En = "Chitoz Jumbo Puffs", RuF = "карамель", EnF = "caramel", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SugarDry" }, RuJ = "Гепард надул щёки: шары тают раньше, чем успеваешь пожалеть. Мороз ему нипочём: твёрже не стало, мягче тоже. Открывайте тихо: у волков отличный слух.", EnJ = "The cheetah puffed his cheeks: they melt before you can regret it. The frost did nothing to it: no harder, no softer. Open it quietly: wolves have excellent hearing.", Rare = false },
        new Def { Id = "ChitozPuffsCinnamon", Kind = Kind.Snack, Shape = "bag", Mesh = "ChitozPuffs", Texture = "ChitozPuffsCinnamon", Kg = 0.138f, Kcal = 720f, Thirst = -6f, Eat = 4f, Ru = "Кукурузные шары «Читоз Паффс»", En = "Chitoz Jumbo Puffs", RuF = "корица и сахар", EnF = "cinnamon sugar", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SugarDry" }, RuJ = "Гепард надул щёки: шары тают раньше, чем успеваешь пожалеть. Из тех времён, когда еду выбирали по вкусу. Одной не обойдётся, но вторая неизвестно где.", EnJ = "The cheetah puffed his cheeks: they melt before you can regret it. From the days when people picked food for its taste. One won't be enough, and nobody knows where the second is.", Rare = false },
        new Def { Id = "DoritozDinamitaChileLimon", Kind = Kind.Snack, Shape = "bag", Mesh = "DoritozDinamita", Texture = "DoritozDinamitaChileLimon", Kg = 0.148f, Kcal = 700f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Доритоз Динамита»", En = "Doritoz Dinamita rolled chips", RuF = "чили и лимон", EnF = "chile limon", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Треугольник скрутили в динамитную шашку. Фитиль прилагается к языку. Чей-то перекус на ночную смену, которая не кончилась. Крошки с пола тоже считаются.", EnJ = "They rolled the triangle into a stick of dynamite. The fuse comes with your tongue. Someone's snack for a night shift that never ended. The crumbs on the floor count too.", Rare = false },
        new Def { Id = "DoritozDinamitaQueso", Kind = Kind.Snack, Shape = "bag", Mesh = "DoritozDinamita", Texture = "DoritozDinamitaQueso", Kg = 0.148f, Kcal = 700f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Доритоз Динамита»", En = "Doritoz Dinamita rolled chips", RuF = "огненный сыр", EnF = "fiery queso", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Треугольник скрутили в динамитную шашку. Фитиль прилагается к языку. В охотничьей вышке таким встречали рассвет. Запейте чаем из шиповника и считайте это обедом.", EnJ = "They rolled the triangle into a stick of dynamite. The fuse comes with your tongue. In the hunting blind they met the dawn with this. Wash it down with rosehip tea and call it lunch.", Rare = false },
        new Def { Id = "DoritozDinamitaSmoky", Kind = Kind.Snack, Shape = "bag", Mesh = "DoritozDinamita", Texture = "DoritozDinamitaSmoky", Kg = 0.148f, Kcal = 700f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Доритоз Динамита»", En = "Doritoz Dinamita rolled chips", RuF = "дымный чили", EnF = "smoky chile", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Треугольник скрутили в динамитную шашку. Фитиль прилагается к языку. Такое носили в кармане куртки на всякий случай. Случай настал. Медведю не показывать: отнимет вместе с рукой.", EnJ = "They rolled the triangle into a stick of dynamite. The fuse comes with your tongue. People carried these in a coat pocket just in case. The case has come. Do not show the bear: he will take it, hand and all.", Rare = false },
        new Def { Id = "DoritozDinamitaNitro", Kind = Kind.Snack, Shape = "bag", Mesh = "DoritozDinamita", Texture = "DoritozDinamitaNitro", Kg = 0.148f, Kcal = 700f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Доритоз Динамита»", En = "Doritoz Dinamita rolled chips", RuF = "хабанеро и лайм", EnF = "habanero lime", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Треугольник скрутили в динамитную шашку. Фитиль прилагается к языку. Прежний хозяин оставил записку: «Не трогать». Записка сгорела. Диетолог не одобрил бы. Диетолога тут нет.", EnJ = "They rolled the triangle into a stick of dynamite. The fuse comes with your tongue. The last owner left a note: 'Do not touch'. The note burned. A dietitian would not approve. There is no dietitian here.", Rare = false },
        new Def { Id = "DoritozDinamitaFiery", Kind = Kind.Snack, Shape = "bag", Mesh = "DoritozDinamita", Texture = "DoritozDinamitaFiery", Kg = 0.148f, Kcal = 700f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Доритоз Динамита»", En = "Doritoz Dinamita rolled chips", RuF = "огненный лайм", EnF = "fiery lime", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Треугольник скрутили в динамитную шашку. Фитиль прилагается к языку. Такими торговали в поезде, пока поезд ходил. Лучше, чем кора. Проверено.", EnJ = "They rolled the triangle into a stick of dynamite. The fuse comes with your tongue. They sold these on the train, while the train ran. Better than bark. Tested.", Rare = false },
        new Def { Id = "DoritozDinamitaTangy", Kind = Kind.Snack, Shape = "bag", Mesh = "DoritozDinamita", Texture = "DoritozDinamitaTangy", Kg = 0.148f, Kcal = 700f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Доритоз Динамита»", En = "Doritoz Dinamita rolled chips", RuF = "пикантный сыр", EnF = "tangy cheese", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Треугольник скрутили в динамитную шашку. Фитиль прилагается к языку. Сторож шахты держал такое в ящике стола. Хруст разносится до соседней долины.", EnJ = "They rolled the triangle into a stick of dynamite. The fuse comes with your tongue. The mine watchman kept these in his desk drawer. The crunch carries to the next valley.", Rare = false },
        new Def { Id = "DoritozDinamitaMojo", Kind = Kind.Snack, Shape = "bag", Mesh = "DoritozDinamita", Texture = "DoritozDinamitaMojo", Kg = 0.148f, Kcal = 700f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Доритоз Динамита»", En = "Doritoz Dinamita rolled chips", RuF = "чеснок и цитрус", EnF = "garlic & citrus", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Треугольник скрутили в динамитную шашку. Фитиль прилагается к языку. Лавина прошла мимо, срок годности тоже. Ешьте медленно: когда ещё такое найдёте.", EnJ = "They rolled the triangle into a stick of dynamite. The fuse comes with your tongue. The avalanche missed it, and so did the best-before date. Eat slowly: who knows when you will find another.", Rare = false },
        new Def { Id = "DoritozDinamitaSticks", Kind = Kind.Snack, Shape = "bag", Mesh = "DoritozDinamita", Texture = "DoritozDinamitaSticks", Kg = 0.148f, Kcal = 700f, Thirst = -10f, Eat = 4f, Ru = "Кукурузные трубочки «Доритоз Динамита»", En = "Doritoz Dinamita rolled chips", RuF = "острые палочки", EnF = "hot sticks", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Треугольник скрутили в динамитную шашку. Фитиль прилагается к языку. Такое всегда стояло на видном месте, поэтому никто не брал. К этому просится пиво, а есть только талый снег.", EnJ = "They rolled the triangle into a stick of dynamite. The fuse comes with your tongue. These always stood in plain sight, which is why nobody took them. It begs for a beer, and there is only melted snow.", Rare = false },
        new Def { Id = "RufflzDoubleCheddar", Kind = Kind.Snack, Shape = "bag", Mesh = "RufflzDouble", Texture = "RufflzDoubleCheddar", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Раффлз Дабл Кранч»", En = "Rufflz Double Crunch ridged crisps", RuF = "острый чеддер", EnF = "zesty cheddar", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рёбра вдвое выше: хрустит так, что отвечает эхо. Кто-то открыл, передумал и умер. Не связано. Сияние на вкус не влияет. Наверное.", EnJ = "Ridges twice as tall: the crunch gets an echo back. Someone opened it, changed their mind and died. Unrelated. The aurora does not affect the taste. Probably.", Rare = false },
        new Def { Id = "RufflzDoubleBuffalo", Kind = Kind.Snack, Shape = "bag", Mesh = "RufflzDouble", Texture = "RufflzDoubleBuffalo", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Раффлз Дабл Кранч»", En = "Rufflz Double Crunch ridged crisps", RuF = "соус баффало", EnF = "hot buffalo", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Рёбра вдвое выше: хрустит так, что отвечает эхо. Такое вечно каталось под сиденьем пикапа. После тушёнки из банки это почти ресторан.", EnJ = "Ridges twice as tall: the crunch gets an echo back. One of these was always rolling under a pickup seat. After stew from a tin this is nearly a restaurant.", Rare = false },
        new Def { Id = "RufflzDoubleRanch", Kind = Kind.Snack, Shape = "bag", Mesh = "RufflzDouble", Texture = "RufflzDoubleRanch", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Раффлз Дабл Кранч»", En = "Rufflz Double Crunch ridged crisps", RuF = "бекон и ранч", EnF = "bacon ranch", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рёбра вдвое выше: хрустит так, что отвечает эхо. Привезено паромом, которого больше нет. Делиться не с кем, и это впервые радует.", EnJ = "Ridges twice as tall: the crunch gets an echo back. Brought over by a ferry that no longer exists. Nobody to share with, and for once that is good news.", Rare = false },
        new Def { Id = "RufflzDoubleJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "RufflzDouble", Texture = "RufflzDoubleJalapeno", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Раффлз Дабл Кранч»", En = "Rufflz Double Crunch ridged crisps", RuF = "острый халапеньо", EnF = "hot jalapeno", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Рёбра вдвое выше: хрустит так, что отвечает эхо. Раньше это ели под телевизор. Телевизор молчит. Пальцы потом оближите: зимой калории не выбрасывают.", EnJ = "Ridges twice as tall: the crunch gets an echo back. People ate this in front of the telly. The telly is silent. Lick your fingers after: in winter you do not waste calories.", Rare = false },
        new Def { Id = "RufflzDoubleBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "RufflzDouble", Texture = "RufflzDoubleBBQ", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Раффлз Дабл Кранч»", En = "Rufflz Double Crunch ridged crisps", RuF = "медовый барбекю", EnF = "honey barbecue", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SugarDry" }, RuJ = "Рёбра вдвое выше: хрустит так, что отвечает эхо. Забыто туристами, которым повезло уехать. Ворон на ветке уже ждёт свою долю.", EnJ = "Ridges twice as tall: the crunch gets an echo back. Left behind by tourists who were lucky enough to leave. The crow on the branch is already waiting for its share.", Rare = false },
        new Def { Id = "RufflzDoubleBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "RufflzDouble", Texture = "RufflzDoubleBacon", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Раффлз Дабл Кранч»", En = "Rufflz Double Crunch ridged crisps", RuF = "бекон и сыр", EnF = "bacon & cheese", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рёбра вдвое выше: хрустит так, что отвечает эхо. Механики заедали этим обед, не вытирая рук. На морозе хрустит вдвое громче.", EnJ = "Ridges twice as tall: the crunch gets an echo back. Mechanics ate these for lunch without wiping their hands. In the frost it crunches twice as loud.", Rare = false },
        new Def { Id = "RufflzDoubleQueso", Kind = Kind.Snack, Shape = "bag", Mesh = "RufflzDouble", Texture = "RufflzDoubleQueso", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Раффлз Дабл Кранч»", En = "Rufflz Double Crunch ridged crisps", RuF = "соус кесо", EnF = "queso", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рёбра вдвое выше: хрустит так, что отвечает эхо. Последнее на всю Одинокую топь. Скорее всего. Не еда, а настроение. Настроение тоже греет.", EnJ = "Ridges twice as tall: the crunch gets an echo back. The last one in all of Forlorn Muskeg. Most likely. Not food but a mood. A mood warms you too.", Rare = false },
        new Def { Id = "RufflzDoubleSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "RufflzDouble", Texture = "RufflzDoubleSalt", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Раффлз Дабл Кранч»", En = "Rufflz Double Crunch ridged crisps", RuF = "соль", EnF = "salted", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SaltHold" }, RuJ = "Рёбра вдвое выше: хрустит так, что отвечает эхо. Смотритель маяка грыз такое, ожидая кораблей. Сытости на час, воспоминаний на неделю.", EnJ = "Ridges twice as tall: the crunch gets an echo back. The lighthouse keeper munched these while waiting for ships. An hour of fullness, a week of memories.", Rare = false },
        new Def { Id = "EstrelyaGrillGrill", Kind = Kind.Snack, Shape = "bag", Mesh = "EstrelyaGrill", Texture = "EstrelyaGrillGrill", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Эстрелья Гриль»", En = "Estrelya Grill ridged crisps", RuF = "гриль", EnF = "grill", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведские волны: к ним положен соус и долгий светлый вечер. Полки рушились, а это уцелело. Кролик смотрит с осуждением.", EnJ = "Swedish waves: served with dip and a long light evening. Shelves collapsed and this survived. The rabbit looks on with disapproval.", Rare = false },
        new Def { Id = "EstrelyaGrillDill", Kind = Kind.Snack, Shape = "bag", Mesh = "EstrelyaGrill", Texture = "EstrelyaGrillDill", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Эстрелья Гриль»", En = "Estrelya Grill ridged crisps", RuF = "укроп и лук", EnF = "dill & chives", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведские волны: к ним положен соус и долгий светлый вечер. Смотритель заповедника называл это ужином. У костра вкуснее. У костра всё вкуснее.", EnJ = "Swedish waves: served with dip and a long light evening. The park ranger called this dinner. It tastes better by the fire. Everything does.", Rare = false },
        new Def { Id = "EstrelyaGrillHoliday", Kind = Kind.Snack, Shape = "bag", Mesh = "EstrelyaGrill", Texture = "EstrelyaGrillHoliday", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Эстрелья Гриль»", En = "Estrelya Grill ridged crisps", RuF = "сметана и лук", EnF = "sourcream & onion", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведские волны: к ним положен соус и долгий светлый вечер. Такое слали посылками с материка. Адресаты выбыли. Упаковку не выбрасывайте: ею можно разжечь печь.", EnJ = "Swedish waves: served with dip and a long light evening. These came in parcels from the mainland. The addressees are gone. Keep the wrapper: it will light the stove.", Rare = false },
        new Def { Id = "EstrelyaGrillCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "EstrelyaGrill", Texture = "EstrelyaGrillCheese", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Эстрелья Гриль»", En = "Estrelya Grill ridged crisps", RuF = "сыр и лук", EnF = "cheese & onion", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведские волны: к ним положен соус и долгий светлый вечер. Иные держали это за лекарство. Тоже лечит. Если это последняя на острове, вы её достойны.", EnJ = "Swedish waves: served with dip and a long light evening. Some people counted this as medicine. Also a cure. If this is the last one on the island, you have earned it.", Rare = false },
        new Def { Id = "EstrelyaGrillHot", Kind = Kind.Snack, Shape = "bag", Mesh = "EstrelyaGrill", Texture = "EstrelyaGrillHot", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Эстрелья Гриль»", En = "Estrelya Grill ridged crisps", RuF = "острые", EnF = "hot", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Шведские волны: к ним положен соус и долгий светлый вечер. В школьном рюкзаке такое не доживало до обеда. Желудок удивится, но возражать не станет.", EnJ = "Swedish waves: served with dip and a long light evening. In a school bag this never lasted till lunch. Your stomach will be surprised but will not object.", Rare = false },
        new Def { Id = "EstrelyaGrillBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "EstrelyaGrill", Texture = "EstrelyaGrillBBQ", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Эстрелья Гриль»", En = "Estrelya Grill ridged crisps", RuF = "барбекю", EnF = "barbecue", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведские волны: к ним положен соус и долгий светлый вечер. Его обменяли бы на патрон, будь тут с кем меняться. Запах выдаёт вас за сто шагов. Оно того стоит.", EnJ = "Swedish waves: served with dip and a long light evening. You could trade it for a cartridge, if there were anyone to trade with. The smell gives you away at a hundred paces. Worth it.", Rare = false },
        new Def { Id = "EstrelyaGrillRanch", Kind = Kind.Snack, Shape = "bag", Mesh = "EstrelyaGrill", Texture = "EstrelyaGrillRanch", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Эстрелья Гриль»", En = "Estrelya Grill ridged crisps", RuF = "ранч", EnF = "ranch", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведские волны: к ним положен соус и долгий светлый вечер. На вокзале это стоило втрое дороже. Теперь даром. Раньше это называли вредным. Теперь называют едой.", EnJ = "Swedish waves: served with dip and a long light evening. At the station it cost three times as much. Now it is free. They used to call this unhealthy. Now they call it food.", Rare = false },
        new Def { Id = "EstrelyaGrillSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "EstrelyaGrill", Texture = "EstrelyaGrillSalt", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Эстрелья Гриль»", En = "Estrelya Grill ridged crisps", RuF = "соль", EnF = "salted", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Шведские волны: к ним положен соус и долгий светлый вечер. Пережило толчок и даже не помялось. Спальный мешок потом вытряхните.", EnJ = "Swedish waves: served with dip and a long light evening. It came through the quake without a dent. Shake out your sleeping bag afterwards.", Rare = false },
        new Def { Id = "EstrelyaLinsSourCream", Kind = Kind.Snack, Shape = "bag", Mesh = "EstrelyaLins", Texture = "EstrelyaLinsSourCream", Kg = 0.118f, Kcal = 480f, Thirst = -8f, Eat = 4f, Ru = "Чечевичные чипсы «Эстрелья Линс»", En = "Estrelya Lentil chips", RuF = "сметана и лук", EnF = "sourcream & onion", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из чечевицы: пачку покупают ради здоровья, вторую уже ради вкуса. Китобои такого не ели, но оценили бы. Зимой такое идёт за валюту.", EnJ = "Lentil chips: the first bag is for health, the second for taste. The whalers never ate this, but they would have approved. In winter this passes for currency.", Rare = false },
        new Def { Id = "EstrelyaLinsChili", Kind = Kind.Snack, Shape = "bag", Mesh = "EstrelyaLins", Texture = "EstrelyaLinsChili", Kg = 0.118f, Kcal = 480f, Thirst = -8f, Eat = 4f, Ru = "Чечевичные чипсы «Эстрелья Линс»", En = "Estrelya Lentil chips", RuF = "сладкий чили", EnF = "sweet chili", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Чипсы из чечевицы: пачку покупают ради здоровья, вторую уже ради вкуса. Осталось после чьего-то дня рождения. Гости не пришли. Торговец дал бы за это тряпку. Вы дадите больше.", EnJ = "Lentil chips: the first bag is for health, the second for taste. Left over from someone's birthday. The guests never came. The trader would give a rag for it. You would give more.", Rare = false },
        new Def { Id = "EstrelyaLinsSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "EstrelyaLins", Texture = "EstrelyaLinsSalt", Kg = 0.118f, Kcal = 480f, Thirst = -8f, Eat = 4f, Ru = "Чечевичные чипсы «Эстрелья Линс»", En = "Estrelya Lentil chips", RuF = "морская соль", EnF = "sea salt", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из чечевицы: пачку покупают ради здоровья, вторую уже ради вкуса. Мерзлота хранит лучше любого холодильника. Пока жуёте, метель кажется короче.", EnJ = "Lentil chips: the first bag is for health, the second for taste. Permafrost keeps things better than any fridge. While you chew, the blizzard seems shorter.", Rare = false },
        new Def { Id = "EstrelyaLinsPaprika", Kind = Kind.Snack, Shape = "bag", Mesh = "EstrelyaLins", Texture = "EstrelyaLinsPaprika", Kg = 0.118f, Kcal = 480f, Thirst = -8f, Eat = 4f, Ru = "Чечевичные чипсы «Эстрелья Линс»", En = "Estrelya Lentil chips", RuF = "паприка", EnF = "paprika", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из чечевицы: пачку покупают ради здоровья, вторую уже ради вкуса. Такое добывали из автомата, который съедал последнюю монету. Организм скажет спасибо. Или не скажет.", EnJ = "Lentil chips: the first bag is for health, the second for taste. These came from the vending machine that ate your last coin. Your body will thank you. Or not.", Rare = false },
        new Def { Id = "EstrelyaLinsTomato", Kind = Kind.Snack, Shape = "bag", Mesh = "EstrelyaLins", Texture = "EstrelyaLinsTomato", Kg = 0.118f, Kcal = 480f, Thirst = -8f, Eat = 4f, Ru = "Чечевичные чипсы «Эстрелья Линс»", En = "Estrelya Lentil chips", RuF = "томат и зелень", EnF = "tomato & herbs", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из чечевицы: пачку покупают ради здоровья, вторую уже ради вкуса. Такое брали в лодку под брезент, на весь день. На третьей горсти забываешь, что вокруг конец света.", EnJ = "Lentil chips: the first bag is for health, the second for taste. People took these out in the boat under the tarpaulin, for the whole day. By the third handful you forget the world has ended.", Rare = false },
        new Def { Id = "EstrelyaLinsOnion", Kind = Kind.Snack, Shape = "bag", Mesh = "EstrelyaLins", Texture = "EstrelyaLinsOnion", Kg = 0.118f, Kcal = 480f, Thirst = -8f, Eat = 4f, Ru = "Чечевичные чипсы «Эстрелья Линс»", En = "Estrelya Lentil chips", RuF = "лук", EnF = "onion", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из чечевицы: пачку покупают ради здоровья, вторую уже ради вкуса. С ним кто-то шёл к перевалу и не дошёл. Рыба подо льдом завидует.", EnJ = "Lentil chips: the first bag is for health, the second for taste. Someone carried it towards the pass and never arrived. The fish under the ice are jealous.", Rare = false },
        new Def { Id = "EstrelyaLinsCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "EstrelyaLins", Texture = "EstrelyaLinsCheese", Kg = 0.118f, Kcal = 480f, Thirst = -8f, Eat = 4f, Ru = "Чечевичные чипсы «Эстрелья Линс»", En = "Estrelya Lentil chips", RuF = "сыр", EnF = "cheese", RuC = "Швеция", EnC = "Sweden", Fx = new[] { "SaltHold" }, RuJ = "Чипсы из чечевицы: пачку покупают ради здоровья, вторую уже ради вкуса. С таким сидели у окна с видом на метель. Олень от такого отказался бы. Олень не голодал.", EnJ = "Lentil chips: the first bag is for health, the second for taste. People sat with these at a window with a view of the blizzard. A deer would turn it down. A deer has never starved.", Rare = false },
        new Def { Id = "WolkersMaxSteak", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersMax", Texture = "WolkersMaxSteak", Kg = 0.148f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Уолкерс Макс»", En = "Wolkers Max ridged crisps", RuF = "стейк на огне", EnF = "flame grilled steak", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Британская сдержанность кончилась на слове «Макс». Уцелело там, где сгорело всё остальное. Соль есть, жир есть, совести нет.", EnJ = "British restraint ends at the word ‘Max’. It survived where everything else burned. Salt: yes. Fat: yes. Conscience: none.", Rare = false },
        new Def { Id = "WolkersMaxPaprika", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersMax", Texture = "WolkersMaxPaprika", Kg = 0.148f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Уолкерс Макс»", En = "Wolkers Max ridged crisps", RuF = "паприка", EnF = "paprika", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Британская сдержанность кончилась на слове «Макс». Этим кормили сторожевого пса. Пёс ушёл в волки. Ешьте до темноты: в темноте крошки не найти.", EnJ = "British restraint ends at the word ‘Max’. They fed the guard dog with this. The dog joined the wolves. Eat before dark: you cannot find crumbs in the dark.", Rare = false },
        new Def { Id = "WolkersMaxCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersMax", Texture = "WolkersMaxCheese", Kg = 0.148f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Уолкерс Макс»", En = "Wolkers Max ridged crisps", RuF = "сыр и лук", EnF = "cheese & onion", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Британская сдержанность кончилась на слове «Макс». Из запасов лесорубов: брали ящиками. Лучшее, что случится с вами сегодня.", EnJ = "British restraint ends at the word ‘Max’. From the loggers' stores: they bought it by the crate. The best thing that will happen to you today.", Rare = false },
        new Def { Id = "WolkersMaxChicken", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersMax", Texture = "WolkersMaxChicken", Kg = 0.148f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Уолкерс Макс»", En = "Wolkers Max ridged crisps", RuF = "острая курица", EnF = "hot chicken", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Британская сдержанность кончилась на слове «Макс». В пост такое не ели. Пост кончился вместе с миром. Для полного счастья не хватает только дивана.", EnJ = "British restraint ends at the word ‘Max’. Nobody ate these during a fast. The fast ended with the world. All that is missing for perfect happiness is a sofa.", Rare = false },
        new Def { Id = "WolkersMaxRibs", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersMax", Texture = "WolkersMaxRibs", Kg = 0.148f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Уолкерс Макс»", En = "Wolkers Max ridged crisps", RuF = "рёбрышки", EnF = "barbecue ribs", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Британская сдержанность кончилась на слове «Макс». Теперь это ценнее денег. Деньги оставьте. Вкус детства, если детство было так себе.", EnJ = "British restraint ends at the word ‘Max’. It is worth more than money now. Leave the money. The taste of childhood, if childhood was so-so.", Rare = false },
        new Def { Id = "WolkersMaxPickle", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersMax", Texture = "WolkersMaxPickle", Kg = 0.148f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Уолкерс Макс»", En = "Wolkers Max ridged crisps", RuF = "маринованный лук", EnF = "pickled onion", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Британская сдержанность кончилась на слове «Макс». Его несли на пикник. Пикник отменили навсегда. Шуршит как надежда.", EnJ = "British restraint ends at the word ‘Max’. It was headed for a picnic. The picnic is cancelled forever. It rustles like hope.", Rare = false },
        new Def { Id = "WolkersMaxBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersMax", Texture = "WolkersMaxBacon", Kg = 0.148f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Уолкерс Макс»", En = "Wolkers Max ridged crisps", RuF = "бекон", EnF = "bacon", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Британская сдержанность кончилась на слове «Макс». Такое стояло у кассы на случай слабости. Голод отступит, жажда придёт. Честный обмен.", EnJ = "British restraint ends at the word ‘Max’. These stood by the till for moments of weakness. Hunger leaves, thirst arrives. A fair trade.", Rare = false },
        new Def { Id = "WolkersMaxJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersMax", Texture = "WolkersMaxJalapeno", Kg = 0.148f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Уолкерс Макс»", En = "Wolkers Max ridged crisps", RuF = "халапеньо и сыр", EnF = "jalapeno & cheese", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Британская сдержанность кончилась на слове «Макс». Досталось вам, потому что вы дошли первым. Не согреет, зато отвлечёт.", EnJ = "British restraint ends at the word ‘Max’. It is yours because you got here first. It will not warm you, but it will distract you.", Rare = false },
        new Def { Id = "WolkersMaxWasabi", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersMax", Texture = "WolkersMaxWasabi", Kg = 0.148f, Kcal = 750f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Уолкерс Макс»", En = "Wolkers Max ridged crisps", RuF = "васаби", EnF = "wasabi", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Британская сдержанность кончилась на слове «Макс». Упаковка выцвела, внутри время остановилось. Пума предпочитает мясо. Вам повезло.", EnJ = "British restraint ends at the word ‘Max’. The wrapper has faded; inside, time stood still. The cougar prefers meat. Lucky you.", Rare = false },
        new Def { Id = "WolkersBakedSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersBaked", Texture = "WolkersBakedSalt", Kg = 0.118f, Kcal = 480f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс из печи»", En = "Wolkers Baked crisps", RuF = "морская соль", EnF = "sea salt", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "На 50% меньше жира и на 100% больше оправданий взять вторую пачку. Из чемодана пассажира, который не долетел. Сначала попробуйте одну штучку. Шутка: ешьте всё.", EnJ = "50% less fat and 100% more excuses for a second bag. From the suitcase of a passenger who never landed. Try just one first. Joke: eat the lot.", Rare = false },
        new Def { Id = "WolkersBakedCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersBaked", Texture = "WolkersBakedCheese", Kg = 0.118f, Kcal = 480f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс из печи»", En = "Wolkers Baked crisps", RuF = "сыр и лук", EnF = "cheese & onion", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "На 50% меньше жира и на 100% больше оправданий взять вторую пачку. Перезимовало и ничуть не обиделось. Такой ужин не стыдно записать в дневник.", EnJ = "50% less fat and 100% more excuses for a second bag. It made it through the winter and bears no grudge. A dinner worth writing in the journal.", Rare = false },
        new Def { Id = "WolkersBakedVinegar", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersBaked", Texture = "WolkersBakedVinegar", Kg = 0.118f, Kcal = 480f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс из печи»", En = "Wolkers Baked crisps", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "На 50% меньше жира и на 100% больше оправданий взять вторую пачку. Запасливая хозяйка купила по акции шесть штук. Силы прибавит на один сугроб.", EnJ = "50% less fat and 100% more excuses for a second bag. A thrifty housewife bought six of these on offer. It will carry you one snowdrift further.", Rare = false },
        new Def { Id = "WolkersBakedPrawn", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersBaked", Texture = "WolkersBakedPrawn", Kg = 0.118f, Kcal = 480f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс из печи»", En = "Wolkers Baked crisps", RuF = "креветочный коктейль", EnF = "prawn cocktail", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "На 50% меньше жира и на 100% больше оправданий взять вторую пачку. Кто-то написал на упаковке «моё». Уже нет. Идеально к закату, которого не видно за бураном.", EnJ = "50% less fat and 100% more excuses for a second bag. Someone wrote 'mine' on it. Not any more. Perfect with a sunset you cannot see for the storm.", Rare = false },
        new Def { Id = "WolkersBakedBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersBaked", Texture = "WolkersBakedBBQ", Kg = 0.118f, Kcal = 480f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс из печи»", En = "Wolkers Baked crisps", RuF = "барбекю", EnF = "barbecue", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "На 50% меньше жира и на 100% больше оправданий взять вторую пачку. В консервном цеху это ели тайком от мастера. Пахнет магазином. Помните магазины?", EnJ = "50% less fat and 100% more excuses for a second bag. At the cannery they ate this behind the foreman's back. It smells of a shop. Remember shops?", Rare = false },
        new Def { Id = "WolkersBakedSour", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersBaked", Texture = "WolkersBakedSour", Kg = 0.118f, Kcal = 480f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс из печи»", En = "Wolkers Baked crisps", RuF = "сметана и лук-резанец", EnF = "sour cream & chive", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "На 50% меньше жира и на 100% больше оправданий взять вторую пачку. Его не взяли даже мародёры. Они спешили. Мороз не испортил, время не взяло.", EnJ = "50% less fat and 100% more excuses for a second bag. Even the looters left it. They were in a hurry. Frost did not spoil it and time could not take it.", Rare = false },
        new Def { Id = "WolkersSensationsThaiChilli", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersSensations", Texture = "WolkersSensationsThaiChilli", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс Сенсейшнз»", En = "Wolkers Sensations crisps", RuF = "тайский сладкий чили", EnF = "thai sweet chilli", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Чипсы для гостей: чёрная пачка, длинные названия, короткая жизнь. Провело зиму на острове, как и вы. В рюкзаке не мнётся. Почти.", EnJ = "Crisps for company: a black bag, long names, a short life. It spent the winter on the island, same as you. It does not get crushed in a pack. Almost.", Rare = false },
        new Def { Id = "WolkersSensationsChicken", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersSensations", Texture = "WolkersSensationsChicken", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс Сенсейшнз»", En = "Wolkers Sensations crisps", RuF = "курица с тимьяном", EnF = "roast chicken & thyme", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Чипсы для гостей: чёрная пачка, длинные названия, короткая жизнь. Дети прятали такое под кроватью, в тайнике. Съешьте сейчас: завтра может не быть аппетита.", EnJ = "Crisps for company: a black bag, long names, a short life. Children hid these under the bed, in a secret place. Eat it now: tomorrow you may have no appetite.", Rare = false },
        new Def { Id = "WolkersSensationsBalsamic", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersSensations", Texture = "WolkersSensationsBalsamic", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс Сенсейшнз»", En = "Wolkers Sensations crisps", RuF = "бальзамик и лук", EnF = "balsamic vinegar & onion", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Чипсы для гостей: чёрная пачка, длинные названия, короткая жизнь. Осталось от геологов вместе с картой и долгами. Хватит дойти до следующей хижины и пожалеть, что кончилось.", EnJ = "Crisps for company: a black bag, long names, a short life. Left by the geologists along with a map and some debts. Enough to reach the next cabin and regret it is gone.", Rare = false },
        new Def { Id = "WolkersSensationsLime", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersSensations", Texture = "WolkersSensationsLime", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс Сенсейшнз»", En = "Wolkers Sensations crisps", RuF = "лайм и кориандр", EnF = "lime & coriander", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Чипсы для гостей: чёрная пачка, длинные названия, короткая жизнь. На острове такое было праздником и до катастрофы. От такого не толстеют те, кто ходит по двадцать километров.", EnJ = "Crisps for company: a black bag, long names, a short life. On the island this was a treat even before the disaster. Nobody who walks twenty kilometres a day gets fat on this.", Rare = false },
        new Def { Id = "WolkersSensationsOnion", Kind = Kind.Snack, Shape = "bag", Mesh = "WolkersSensations", Texture = "WolkersSensationsOnion", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Уолкерс Сенсейшнз»", En = "Wolkers Sensations crisps", RuF = "карамелизованный лук", EnF = "caramelised onion", RuC = "Великобритания", EnC = "United Kingdom", Fx = new[] { "SaltHold" }, RuJ = "Чипсы для гостей: чёрная пачка, длинные названия, короткая жизнь. С таким слушали радио, которое теперь ловит только треск. Волчья стая не в курсе. Пусть так и будет.", EnJ = "Crisps for company: a black bag, long names, a short life. People ate these by the radio, which picks up nothing but crackle now. The wolf pack does not know. Keep it that way.", Rare = false },
