        new Def { Id = "FanniRiffelsSour", Kind = Kind.Snack, Shape = "bag", Mesh = "FanniRiffels", Texture = "FanniRiffelsSour", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Фанни-фриш Риффельс»", En = "Fanni-frisch Riffels ridged crisps", RuF = "сметана", EnF = "sour cream", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкая волна: ровная, как автобан, и такая же быстрая. Кто-то спрятал это от детей. Дети не нашли. Проверено поколениями и одной катастрофой.", EnJ = "A German wave: even as the autobahn and just as fast. Someone hid it from the kids. The kids never found it. Tested by generations and one catastrophe.", Rare = false },
        new Def { Id = "FanniRiffelsKase", Kind = Kind.Snack, Shape = "bag", Mesh = "FanniRiffels", Texture = "FanniRiffelsKase", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Фанни-фриш Риффельс»", En = "Fanni-frisch Riffels ridged crisps", RuF = "сыр и лук", EnF = "cheese & onion", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкая волна: ровная, как автобан, и такая же быстрая. В сельском магазине такое вечно заваливалось за прилавок. Оставьте пару штук на перевал. Не оставите.", EnJ = "A German wave: even as the autobahn and just as fast. In the village shop these kept slipping behind the counter. Save a couple for the pass. You will not.", Rare = false },
        new Def { Id = "FanniRiffelsBarbecue", Kind = Kind.Snack, Shape = "bag", Mesh = "FanniRiffels", Texture = "FanniRiffelsBarbecue", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Фанни-фриш Риффельс»", En = "Fanni-frisch Riffels ridged crisps", RuF = "барбекю", EnF = "barbecue", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкая волна: ровная, как автобан, и такая же быстрая. Ждало покупателя дольше, чем тот прожил. Здесь это считается ужином при свечах.", EnJ = "A German wave: even as the autobahn and just as fast. It waited for a buyer longer than the buyer lived. Round here this counts as a candlelit dinner.", Rare = false },
        new Def { Id = "FanniRiffelsDoppel", Kind = Kind.Snack, Shape = "bag", Mesh = "FanniRiffels", Texture = "FanniRiffelsDoppel", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Фанни-фриш Риффельс»", En = "Fanni-frisch Riffels ridged crisps", RuF = "двойная паприка", EnF = "double paprika", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Немецкая волна: ровная, как автобан, и такая же быстрая. С материка такое больше не привезут. Луна светит, еда хрустит, жизнь налаживается.", EnJ = "A German wave: even as the autobahn and just as fast. Nobody will bring this from the mainland again. The moon shines, the food crunches, life is looking up.", Rare = false },
        new Def { Id = "FanniOfenPaprika", Kind = Kind.Snack, Shape = "bag", Mesh = "FanniOfen", Texture = "FanniOfenPaprika", Kg = 0.133f, Kcal = 550f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш из печи»", En = "Fanni-frisch Oven crisps", RuF = "паприка", EnF = "paprika", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Из печи, по инструкции, без единой лишней капли масла. На упаковке иней, внутри всё по-прежнему. Снег вокруг не солёный. Это солёное.", EnJ = "From the oven, by the manual, without one drop of oil to spare. Frost on the wrapper, business as usual inside. The snow around is not salty. This is.", Rare = false },
        new Def { Id = "FanniOfenSourCream", Kind = Kind.Snack, Shape = "bag", Mesh = "FanniOfen", Texture = "FanniOfenSourCream", Kg = 0.133f, Kcal = 550f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш из печи»", En = "Fanni-frisch Oven crisps", RuF = "сметана", EnF = "sour cream", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Из печи, по инструкции, без единой лишней капли масла. Мороз ему нипочём: твёрже не стало, мягче тоже. Больше таких не делают. Совсем.", EnJ = "From the oven, by the manual, without one drop of oil to spare. The frost did nothing to it: no harder, no softer. They do not make these any more. At all.", Rare = false },
        new Def { Id = "FanniOfenSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "FanniOfen", Texture = "FanniOfenSalt", Kg = 0.133f, Kcal = 550f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш из печи»", En = "Fanni-frisch Oven crisps", RuF = "морская соль", EnF = "sea salt", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Из печи, по инструкции, без единой лишней капли масла. Из тех времён, когда еду выбирали по вкусу. Открывайте тихо: у волков отличный слух.", EnJ = "From the oven, by the manual, without one drop of oil to spare. From the days when people picked food for its taste. Open it quietly: wolves have excellent hearing.", Rare = false },
        new Def { Id = "FanniOfenKrauter", Kind = Kind.Snack, Shape = "bag", Mesh = "FanniOfen", Texture = "FanniOfenKrauter", Kg = 0.133f, Kcal = 550f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш из печи»", En = "Fanni-frisch Oven crisps", RuF = "травы", EnF = "herbs", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Из печи, по инструкции, без единой лишней капли масла. Чей-то перекус на ночную смену, которая не кончилась. Одной не обойдётся, но вторая неизвестно где.", EnJ = "From the oven, by the manual, without one drop of oil to spare. Someone's snack for a night shift that never ended. One won't be enough, and nobody knows where the second is.", Rare = false },
        new Def { Id = "FanniOfenTomate", Kind = Kind.Snack, Shape = "bag", Mesh = "FanniOfen", Texture = "FanniOfenTomate", Kg = 0.133f, Kcal = 550f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш из печи»", En = "Fanni-frisch Oven crisps", RuF = "томат", EnF = "tomato", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Из печи, по инструкции, без единой лишней капли масла. В охотничьей вышке таким встречали рассвет. Крошки с пола тоже считаются.", EnJ = "From the oven, by the manual, without one drop of oil to spare. In the hunting blind they met the dawn with this. The crumbs on the floor count too.", Rare = false },
        new Def { Id = "FanniOfenKase", Kind = Kind.Snack, Shape = "bag", Mesh = "FanniOfen", Texture = "FanniOfenKase", Kg = 0.133f, Kcal = 550f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш из печи»", En = "Fanni-frisch Oven crisps", RuF = "сыр", EnF = "cheese", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Из печи, по инструкции, без единой лишней капли масла. Такое носили в кармане куртки на всякий случай. Случай настал. Запейте чаем из шиповника и считайте это обедом.", EnJ = "From the oven, by the manual, without one drop of oil to spare. People carried these in a coat pocket just in case. The case has come. Wash it down with rosehip tea and call it lunch.", Rare = false },
        new Def { Id = "FanniOfenZwiebel", Kind = Kind.Snack, Shape = "bag", Mesh = "FanniOfen", Texture = "FanniOfenZwiebel", Kg = 0.133f, Kcal = 550f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Фанни-фриш из печи»", En = "Fanni-frisch Oven crisps", RuF = "лук", EnF = "onion", RuC = "Германия", EnC = "Germany", Fx = new[] { "SaltHold" }, RuJ = "Из печи, по инструкции, без единой лишней капли масла. Прежний хозяин оставил записку: «Не трогать». Записка сгорела. Медведю не показывать: отнимет вместе с рукой.", EnJ = "From the oven, by the manual, without one drop of oil to spare. The last owner left a note: 'Do not touch'. The note burned. Do not show the bear: he will take it, hand and all.", Rare = false },
        new Def { Id = "KarubiKataageSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "KarubiKataage", Texture = "KarubiKataageSalt", Kg = 0.073f, Kcal = 350f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби Ката-агэ»", En = "Karubi Kata-age hard-fried crisps", RuF = "соль", EnF = "light salt", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Жарены по-старому, твёрдые: японцы тренируют на них челюсть и характер. Такими торговали в поезде, пока поезд ходил. Диетолог не одобрил бы. Диетолога тут нет.", EnJ = "Fried the old way, hard: the Japanese train both jaw and character on them. They sold these on the train, while the train ran. A dietitian would not approve. There is no dietitian here.", Rare = false },
        new Def { Id = "KarubiKataagePepper", Kind = Kind.Snack, Shape = "bag", Mesh = "KarubiKataage", Texture = "KarubiKataagePepper", Kg = 0.073f, Kcal = 350f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби Ката-агэ»", En = "Karubi Kata-age hard-fried crisps", RuF = "чёрный перец", EnF = "black pepper", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Жарены по-старому, твёрдые: японцы тренируют на них челюсть и характер. Сторож шахты держал такое в ящике стола. Лучше, чем кора. Проверено.", EnJ = "Fried the old way, hard: the Japanese train both jaw and character on them. The mine watchman kept these in his desk drawer. Better than bark. Tested.", Rare = false },
        new Def { Id = "KarubiKataageNori", Kind = Kind.Snack, Shape = "bag", Mesh = "KarubiKataage", Texture = "KarubiKataageNori", Kg = 0.073f, Kcal = 350f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби Ката-агэ»", En = "Karubi Kata-age hard-fried crisps", RuF = "нори и соль", EnF = "seaweed salt", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Жарены по-старому, твёрдые: японцы тренируют на них челюсть и характер. Лавина прошла мимо, срок годности тоже. Хруст разносится до соседней долины.", EnJ = "Fried the old way, hard: the Japanese train both jaw and character on them. The avalanche missed it, and so did the best-before date. The crunch carries to the next valley.", Rare = false },
        new Def { Id = "KarubiKataageShoyu", Kind = Kind.Snack, Shape = "bag", Mesh = "KarubiKataage", Texture = "KarubiKataageShoyu", Kg = 0.073f, Kcal = 350f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби Ката-агэ»", En = "Karubi Kata-age hard-fried crisps", RuF = "соевый соус", EnF = "soy sauce", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Жарены по-старому, твёрдые: японцы тренируют на них челюсть и характер. Такое всегда стояло на видном месте, поэтому никто не брал. Ешьте медленно: когда ещё такое найдёте.", EnJ = "Fried the old way, hard: the Japanese train both jaw and character on them. These always stood in plain sight, which is why nobody took them. Eat slowly: who knows when you will find another.", Rare = false },
        new Def { Id = "KarubiKataageUme", Kind = Kind.Snack, Shape = "bag", Mesh = "KarubiKataage", Texture = "KarubiKataageUme", Kg = 0.073f, Kcal = 350f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби Ката-агэ»", En = "Karubi Kata-age hard-fried crisps", RuF = "слива умэ", EnF = "pickled plum", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Жарены по-старому, твёрдые: японцы тренируют на них челюсть и характер. Кто-то открыл, передумал и умер. Не связано. К этому просится пиво, а есть только талый снег.", EnJ = "Fried the old way, hard: the Japanese train both jaw and character on them. Someone opened it, changed their mind and died. Unrelated. It begs for a beer, and there is only melted snow.", Rare = false },
        new Def { Id = "KarubiKataageWasabi", Kind = Kind.Snack, Shape = "bag", Mesh = "KarubiKataage", Texture = "KarubiKataageWasabi", Kg = 0.073f, Kcal = 350f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби Ката-агэ»", En = "Karubi Kata-age hard-fried crisps", RuF = "васаби", EnF = "wasabi", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Жарены по-старому, твёрдые: японцы тренируют на них челюсть и характер. Такое вечно каталось под сиденьем пикапа. Сияние на вкус не влияет. Наверное.", EnJ = "Fried the old way, hard: the Japanese train both jaw and character on them. One of these was always rolling under a pickup seat. The aurora does not affect the taste. Probably.", Rare = false },
        new Def { Id = "KarubiKataageButter", Kind = Kind.Snack, Shape = "bag", Mesh = "KarubiKataage", Texture = "KarubiKataageButter", Kg = 0.073f, Kcal = 350f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби Ката-агэ»", En = "Karubi Kata-age hard-fried crisps", RuF = "масло", EnF = "butter", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Жарены по-старому, твёрдые: японцы тренируют на них челюсть и характер. Привезено паромом, которого больше нет. После тушёнки из банки это почти ресторан.", EnJ = "Fried the old way, hard: the Japanese train both jaw and character on them. Brought over by a ferry that no longer exists. After stew from a tin this is nearly a restaurant.", Rare = false },
        new Def { Id = "KarubiKataageYuzu", Kind = Kind.Snack, Shape = "bag", Mesh = "KarubiKataage", Texture = "KarubiKataageYuzu", Kg = 0.073f, Kcal = 350f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Каруби Ката-агэ»", En = "Karubi Kata-age hard-fried crisps", RuF = "юдзу и перец", EnF = "yuzu pepper", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "Жарены по-старому, твёрдые: японцы тренируют на них челюсть и характер. Раньше это ели под телевизор. Телевизор молчит. Делиться не с кем, и это впервые радует.", EnJ = "Fried the old way, hard: the Japanese train both jaw and character on them. People ate this in front of the telly. The telly is silent. Nobody to share with, and for once that is good news.", Rare = false },
        new Def { Id = "KarubiPizzaPizza", Kind = Kind.Snack, Shape = "bag", Mesh = "KarubiPizza", Texture = "KarubiPizzaPizza", Kg = 0.071f, Kcal = 340f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Каруби Пицца Потейто»", En = "Karubi Pizza Potato ridged crisps", RuF = "пицца", EnF = "pizza", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "На каждый ломтик напылён сыр: пицца, которую можно носить в кармане. Забыто туристами, которым повезло уехать. Пальцы потом оближите: зимой калории не выбрасывают.", EnJ = "Cheese is sprayed onto every slice: a pizza you can carry in your pocket. Left behind by tourists who were lucky enough to leave. Lick your fingers after: in winter you do not waste calories.", Rare = false },
        new Def { Id = "KarubiPizzaCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "KarubiPizza", Texture = "KarubiPizzaCheese", Kg = 0.071f, Kcal = 340f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Каруби Пицца Потейто»", En = "Karubi Pizza Potato ridged crisps", RuF = "четыре сыра", EnF = "four cheese", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "На каждый ломтик напылён сыр: пицца, которую можно носить в кармане. Механики заедали этим обед, не вытирая рук. Ворон на ветке уже ждёт свою долю.", EnJ = "Cheese is sprayed onto every slice: a pizza you can carry in your pocket. Mechanics ate these for lunch without wiping their hands. The crow on the branch is already waiting for its share.", Rare = false },
        new Def { Id = "KarubiPizzaMentai", Kind = Kind.Snack, Shape = "bag", Mesh = "KarubiPizza", Texture = "KarubiPizzaMentai", Kg = 0.071f, Kcal = 340f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Каруби Пицца Потейто»", En = "Karubi Pizza Potato ridged crisps", RuF = "икра минтая и майонез", EnF = "pollock roe mayo", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "На каждый ломтик напылён сыр: пицца, которую можно носить в кармане. Последнее на всю Одинокую топь. Скорее всего. На морозе хрустит вдвое громче.", EnJ = "Cheese is sprayed onto every slice: a pizza you can carry in your pocket. The last one in all of Forlorn Muskeg. Most likely. In the frost it crunches twice as loud.", Rare = false },
        new Def { Id = "KarubiPizzaMargherita", Kind = Kind.Snack, Shape = "bag", Mesh = "KarubiPizza", Texture = "KarubiPizzaMargherita", Kg = 0.071f, Kcal = 340f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Каруби Пицца Потейто»", En = "Karubi Pizza Potato ridged crisps", RuF = "маргарита", EnF = "margherita", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "На каждый ломтик напылён сыр: пицца, которую можно носить в кармане. Смотритель маяка грыз такое, ожидая кораблей. Не еда, а настроение. Настроение тоже греет.", EnJ = "Cheese is sprayed onto every slice: a pizza you can carry in your pocket. The lighthouse keeper munched these while waiting for ships. Not food but a mood. A mood warms you too.", Rare = false },
        new Def { Id = "KarubiPizzaCurry", Kind = Kind.Snack, Shape = "bag", Mesh = "KarubiPizza", Texture = "KarubiPizzaCurry", Kg = 0.071f, Kcal = 340f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Каруби Пицца Потейто»", En = "Karubi Pizza Potato ridged crisps", RuF = "карри", EnF = "curry", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "На каждый ломтик напылён сыр: пицца, которую можно носить в кармане. Полки рушились, а это уцелело. Сытости на час, воспоминаний на неделю.", EnJ = "Cheese is sprayed onto every slice: a pizza you can carry in your pocket. Shelves collapsed and this survived. An hour of fullness, a week of memories.", Rare = false },
        new Def { Id = "KarubiPizzaGarlic", Kind = Kind.Snack, Shape = "bag", Mesh = "KarubiPizza", Texture = "KarubiPizzaGarlic", Kg = 0.071f, Kcal = 340f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Каруби Пицца Потейто»", En = "Karubi Pizza Potato ridged crisps", RuF = "чеснок", EnF = "garlic", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "На каждый ломтик напылён сыр: пицца, которую можно носить в кармане. Смотритель заповедника называл это ужином. Кролик смотрит с осуждением.", EnJ = "Cheese is sprayed onto every slice: a pizza you can carry in your pocket. The park ranger called this dinner. The rabbit looks on with disapproval.", Rare = false },
        new Def { Id = "KarubiPizzaTomato", Kind = Kind.Snack, Shape = "bag", Mesh = "KarubiPizza", Texture = "KarubiPizzaTomato", Kg = 0.071f, Kcal = 340f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Каруби Пицца Потейто»", En = "Karubi Pizza Potato ridged crisps", RuF = "томат", EnF = "tomato", RuC = "Япония", EnC = "Japan", Fx = new[] { "SaltHold" }, RuJ = "На каждый ломтик напылён сыр: пицца, которую можно носить в кармане. Такое слали посылками с материка. Адресаты выбыли. У костра вкуснее. У костра всё вкуснее.", EnJ = "Cheese is sprayed onto every slice: a pizza you can carry in your pocket. These came in parcels from the mainland. The addressees are gone. It tastes better by the fire. Everything does.", Rare = false },
        new Def { Id = "SabritozRecetaSal", Kind = Kind.Snack, Shape = "bag", Mesh = "SabritozReceta", Texture = "SabritozRecetaSal", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сабритоз Рецета Кру́хьенте»", En = "Sabritoz Receta Crujiente kettle crisps", RuF = "соль", EnF = "sea salt", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold" }, RuJ = "Рецепт «хрустящий»: жарят в котле, пока не зазвенит. Иные держали это за лекарство. Тоже лечит. Упаковку не выбрасывайте: ею можно разжечь печь.", EnJ = "The ‘crunchy recipe’: kettle-fried until it rings. Some people counted this as medicine. Also a cure. Keep the wrapper: it will light the stove.", Rare = false },
        new Def { Id = "SabritozRecetaJalapeno", Kind = Kind.Snack, Shape = "bag", Mesh = "SabritozReceta", Texture = "SabritozRecetaJalapeno", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сабритоз Рецета Кру́хьенте»", En = "Sabritoz Receta Crujiente kettle crisps", RuF = "халапеньо", EnF = "jalapeno", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Рецепт «хрустящий»: жарят в котле, пока не зазвенит. В школьном рюкзаке такое не доживало до обеда. Если это последняя на острове, вы её достойны.", EnJ = "The ‘crunchy recipe’: kettle-fried until it rings. In a school bag this never lasted till lunch. If this is the last one on the island, you have earned it.", Rare = false },
        new Def { Id = "SabritozRecetaFlamin", Kind = Kind.Snack, Shape = "bag", Mesh = "SabritozReceta", Texture = "SabritozRecetaFlamin", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сабритоз Рецета Кру́хьенте»", En = "Sabritoz Receta Crujiente kettle crisps", RuF = "огненные", EnF = "flamin hot", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Рецепт «хрустящий»: жарят в котле, пока не зазвенит. Его обменяли бы на патрон, будь тут с кем меняться. Желудок удивится, но возражать не станет.", EnJ = "The ‘crunchy recipe’: kettle-fried until it rings. You could trade it for a cartridge, if there were anyone to trade with. Your stomach will be surprised but will not object.", Rare = false },
        new Def { Id = "SabritozRecetaLimon", Kind = Kind.Snack, Shape = "bag", Mesh = "SabritozReceta", Texture = "SabritozRecetaLimon", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сабритоз Рецета Кру́хьенте»", En = "Sabritoz Receta Crujiente kettle crisps", RuF = "лимон", EnF = "lemon", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold" }, RuJ = "Рецепт «хрустящий»: жарят в котле, пока не зазвенит. На вокзале это стоило втрое дороже. Теперь даром. Запах выдаёт вас за сто шагов. Оно того стоит.", EnJ = "The ‘crunchy recipe’: kettle-fried until it rings. At the station it cost three times as much. Now it is free. The smell gives you away at a hundred paces. Worth it.", Rare = false },
        new Def { Id = "SabritozRecetaQueso", Kind = Kind.Snack, Shape = "bag", Mesh = "SabritozReceta", Texture = "SabritozRecetaQueso", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сабритоз Рецета Кру́хьенте»", En = "Sabritoz Receta Crujiente kettle crisps", RuF = "сыр", EnF = "cheese", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold" }, RuJ = "Рецепт «хрустящий»: жарят в котле, пока не зазвенит. Пережило толчок и даже не помялось. Раньше это называли вредным. Теперь называют едой.", EnJ = "The ‘crunchy recipe’: kettle-fried until it rings. It came through the quake without a dent. They used to call this unhealthy. Now they call it food.", Rare = false },
        new Def { Id = "SabritozRecetaChipotle", Kind = Kind.Snack, Shape = "bag", Mesh = "SabritozReceta", Texture = "SabritozRecetaChipotle", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сабритоз Рецета Кру́хьенте»", En = "Sabritoz Receta Crujiente kettle crisps", RuF = "чипотле", EnF = "chipotle", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Рецепт «хрустящий»: жарят в котле, пока не зазвенит. Китобои такого не ели, но оценили бы. Спальный мешок потом вытряхните.", EnJ = "The ‘crunchy recipe’: kettle-fried until it rings. The whalers never ate this, but they would have approved. Shake out your sleeping bag afterwards.", Rare = false },
        new Def { Id = "SabritozRecetaHabanero", Kind = Kind.Snack, Shape = "bag", Mesh = "SabritozReceta", Texture = "SabritozRecetaHabanero", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сабритоз Рецета Кру́хьенте»", En = "Sabritoz Receta Crujiente kettle crisps", RuF = "хабанеро", EnF = "habanero", RuC = "Мексика", EnC = "Mexico", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Рецепт «хрустящий»: жарят в котле, пока не зазвенит. Осталось после чьего-то дня рождения. Гости не пришли. Зимой такое идёт за валюту.", EnJ = "The ‘crunchy recipe’: kettle-fried until it rings. Left over from someone's birthday. The guests never came. In winter this passes for currency.", Rare = false },
        new Def { Id = "SanKarloRusticaClassica", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarloRustica", Texture = "SanKarloRusticaClassica", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло Рустика»", En = "San Karlo Rustica kettle crisps", RuF = "классические", EnF = "classic", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Деревенская нарезка: толсто, с кожурой, как резала бы нонна, будь у неё время. Мерзлота хранит лучше любого холодильника. Торговец дал бы за это тряпку. Вы дадите больше.", EnJ = "Country cut: thick, skin on, as nonna would slice if she had the time. Permafrost keeps things better than any fridge. The trader would give a rag for it. You would give more.", Rare = false },
        new Def { Id = "SanKarloRusticaRosmarino", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarloRustica", Texture = "SanKarloRusticaRosmarino", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло Рустика»", En = "San Karlo Rustica kettle crisps", RuF = "розмарин", EnF = "rosemary", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Деревенская нарезка: толсто, с кожурой, как резала бы нонна, будь у неё время. Такое добывали из автомата, который съедал последнюю монету. Пока жуёте, метель кажется короче.", EnJ = "Country cut: thick, skin on, as nonna would slice if she had the time. These came from the vending machine that ate your last coin. While you chew, the blizzard seems shorter.", Rare = false },
        new Def { Id = "SanKarloRusticaPepe", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarloRustica", Texture = "SanKarloRusticaPepe", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло Рустика»", En = "San Karlo Rustica kettle crisps", RuF = "перец и лайм", EnF = "pepper & lime", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Деревенская нарезка: толсто, с кожурой, как резала бы нонна, будь у неё время. Такое брали в лодку под брезент, на весь день. Организм скажет спасибо. Или не скажет.", EnJ = "Country cut: thick, skin on, as nonna would slice if she had the time. People took these out in the boat under the tarpaulin, for the whole day. Your body will thank you. Or not.", Rare = false },
        new Def { Id = "SanKarloRusticaAglio", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarloRustica", Texture = "SanKarloRusticaAglio", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло Рустика»", En = "San Karlo Rustica kettle crisps", RuF = "чеснок", EnF = "garlic", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Деревенская нарезка: толсто, с кожурой, как резала бы нонна, будь у неё время. С ним кто-то шёл к перевалу и не дошёл. На третьей горсти забываешь, что вокруг конец света.", EnJ = "Country cut: thick, skin on, as nonna would slice if she had the time. Someone carried it towards the pass and never arrived. By the third handful you forget the world has ended.", Rare = false },
        new Def { Id = "SanKarloRusticaPomodoro", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarloRustica", Texture = "SanKarloRusticaPomodoro", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло Рустика»", En = "San Karlo Rustica kettle crisps", RuF = "томат", EnF = "tomato", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Деревенская нарезка: толсто, с кожурой, как резала бы нонна, будь у неё время. С таким сидели у окна с видом на метель. Рыба подо льдом завидует.", EnJ = "Country cut: thick, skin on, as nonna would slice if she had the time. People sat with these at a window with a view of the blizzard. The fish under the ice are jealous.", Rare = false },
        new Def { Id = "SanKarloRusticaOrigano", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarloRustica", Texture = "SanKarloRusticaOrigano", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло Рустика»", En = "San Karlo Rustica kettle crisps", RuF = "орегано", EnF = "oregano", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Деревенская нарезка: толсто, с кожурой, как резала бы нонна, будь у неё время. Уцелело там, где сгорело всё остальное. Олень от такого отказался бы. Олень не голодал.", EnJ = "Country cut: thick, skin on, as nonna would slice if she had the time. It survived where everything else burned. A deer would turn it down. A deer has never starved.", Rare = false },
        new Def { Id = "SanKarloRusticaTartufo", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarloRustica", Texture = "SanKarloRusticaTartufo", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло Рустика»", En = "San Karlo Rustica kettle crisps", RuF = "трюфель", EnF = "truffle", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Деревенская нарезка: толсто, с кожурой, как резала бы нонна, будь у неё время. Этим кормили сторожевого пса. Пёс ушёл в волки. Соль есть, жир есть, совести нет.", EnJ = "Country cut: thick, skin on, as nonna would slice if she had the time. They fed the guard dog with this. The dog joined the wolves. Salt: yes. Fat: yes. Conscience: none.", Rare = false },
        new Def { Id = "SanKarloRusticaCipolla", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarloRustica", Texture = "SanKarloRusticaCipolla", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Сан Карло Рустика»", En = "San Karlo Rustica kettle crisps", RuF = "лук", EnF = "onion", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Деревенская нарезка: толсто, с кожурой, как резала бы нонна, будь у неё время. Из запасов лесорубов: брали ящиками. Ешьте до темноты: в темноте крошки не найти.", EnJ = "Country cut: thick, skin on, as nonna would slice if she had the time. From the loggers' stores: they bought it by the crate. Eat before dark: you cannot find crumbs in the dark.", Rare = false },
        new Def { Id = "SanKarloGrillClassica", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarloGrill", Texture = "SanKarloGrillClassica", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Сан Карло Гриль»", En = "San Karlo Grill ridged crisps", RuF = "классические", EnF = "classic", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Итальянская волна: жестикулирует даже чипс. В пост такое не ели. Пост кончился вместе с миром. Лучшее, что случится с вами сегодня.", EnJ = "An Italian wave: even the crisp gestures. Nobody ate these during a fast. The fast ended with the world. The best thing that will happen to you today.", Rare = false },
        new Def { Id = "SanKarloGrillPaprika", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarloGrill", Texture = "SanKarloGrillPaprika", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Сан Карло Гриль»", En = "San Karlo Grill ridged crisps", RuF = "паприка", EnF = "paprika", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Итальянская волна: жестикулирует даже чипс. Теперь это ценнее денег. Деньги оставьте. Для полного счастья не хватает только дивана.", EnJ = "An Italian wave: even the crisp gestures. It is worth more than money now. Leave the money. All that is missing for perfect happiness is a sofa.", Rare = false },
        new Def { Id = "SanKarloGrillLime", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarloGrill", Texture = "SanKarloGrillLime", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Сан Карло Гриль»", En = "San Karlo Grill ridged crisps", RuF = "лайм и розовый перец", EnF = "lime & pink pepper", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Итальянская волна: жестикулирует даже чипс. Его несли на пикник. Пикник отменили навсегда. Вкус детства, если детство было так себе.", EnJ = "An Italian wave: even the crisp gestures. It was headed for a picnic. The picnic is cancelled forever. The taste of childhood, if childhood was so-so.", Rare = false },
        new Def { Id = "SanKarloGrillBacon", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarloGrill", Texture = "SanKarloGrillBacon", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Сан Карло Гриль»", En = "San Karlo Grill ridged crisps", RuF = "бекон", EnF = "bacon", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Итальянская волна: жестикулирует даже чипс. Такое стояло у кассы на случай слабости. Шуршит как надежда.", EnJ = "An Italian wave: even the crisp gestures. These stood by the till for moments of weakness. It rustles like hope.", Rare = false },
        new Def { Id = "SanKarloGrillPiccante", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarloGrill", Texture = "SanKarloGrillPiccante", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Сан Карло Гриль»", En = "San Karlo Grill ridged crisps", RuF = "острые", EnF = "hot", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Итальянская волна: жестикулирует даже чипс. Досталось вам, потому что вы дошли первым. Голод отступит, жажда придёт. Честный обмен.", EnJ = "An Italian wave: even the crisp gestures. It is yours because you got here first. Hunger leaves, thirst arrives. A fair trade.", Rare = false },
        new Def { Id = "SanKarloGrillFormaggio", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarloGrill", Texture = "SanKarloGrillFormaggio", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Сан Карло Гриль»", En = "San Karlo Grill ridged crisps", RuF = "сыр", EnF = "cheese", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Итальянская волна: жестикулирует даже чипс. Упаковка выцвела, внутри время остановилось. Не согреет, зато отвлечёт.", EnJ = "An Italian wave: even the crisp gestures. The wrapper has faded; inside, time stood still. It will not warm you, but it will distract you.", Rare = false },
        new Def { Id = "SanKarloGrillBarbecue", Kind = Kind.Snack, Shape = "bag", Mesh = "SanKarloGrill", Texture = "SanKarloGrillBarbecue", Kg = 0.158f, Kcal = 800f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Сан Карло Гриль»", En = "San Karlo Grill ridged crisps", RuF = "барбекю", EnF = "barbecue", RuC = "Италия", EnC = "Italy", Fx = new[] { "SaltHold" }, RuJ = "Итальянская волна: жестикулирует даже чипс. Из чемодана пассажира, который не долетел. Пума предпочитает мясо. Вам повезло.", EnJ = "An Italian wave: even the crisp gestures. From the suitcase of a passenger who never landed. The cougar prefers meat. Lucky you.", Rare = false },
        new Def { Id = "TaffellBroadwayOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "TaffellBroadway", Texture = "TaffellBroadwayOriginal", Kg = 0.243f, Kcal = 1260f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Таффель Бродвей»", En = "Taffell Broadway ridged crisps", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "Финляндия", EnC = "Finland", Fx = new[] { "SaltHold" }, RuJ = "Финский Бродвей: сцены нет, зато есть соус и молчаливая публика. Перезимовало и ничуть не обиделось. Сначала попробуйте одну штучку. Шутка: ешьте всё.", EnJ = "A Finnish Broadway: no stage, but there is dip and a silent audience. It made it through the winter and bears no grudge. Try just one first. Joke: eat the lot.", Rare = false },
        new Def { Id = "TaffellBroadwayGrill", Kind = Kind.Snack, Shape = "bag", Mesh = "TaffellBroadway", Texture = "TaffellBroadwayGrill", Kg = 0.243f, Kcal = 1260f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Таффель Бродвей»", En = "Taffell Broadway ridged crisps", RuF = "гриль", EnF = "grill", RuC = "Финляндия", EnC = "Finland", Fx = new[] { "SaltHold" }, RuJ = "Финский Бродвей: сцены нет, зато есть соус и молчаливая публика. Запасливая хозяйка купила по акции шесть штук. Такой ужин не стыдно записать в дневник.", EnJ = "A Finnish Broadway: no stage, but there is dip and a silent audience. A thrifty housewife bought six of these on offer. A dinner worth writing in the journal.", Rare = false },
        new Def { Id = "TaffellBroadwayChili", Kind = Kind.Snack, Shape = "bag", Mesh = "TaffellBroadway", Texture = "TaffellBroadwayChili", Kg = 0.243f, Kcal = 1260f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Таффель Бродвей»", En = "Taffell Broadway ridged crisps", RuF = "чили и сметана", EnF = "chili & sour cream", RuC = "Финляндия", EnC = "Finland", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Финский Бродвей: сцены нет, зато есть соус и молчаливая публика. Кто-то написал на упаковке «моё». Уже нет. Силы прибавит на один сугроб.", EnJ = "A Finnish Broadway: no stage, but there is dip and a silent audience. Someone wrote 'mine' on it. Not any more. It will carry you one snowdrift further.", Rare = false },
        new Def { Id = "TaffellBroadwayJuusto", Kind = Kind.Snack, Shape = "bag", Mesh = "TaffellBroadway", Texture = "TaffellBroadwayJuusto", Kg = 0.243f, Kcal = 1260f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Таффель Бродвей»", En = "Taffell Broadway ridged crisps", RuF = "сыр", EnF = "cheese", RuC = "Финляндия", EnC = "Finland", Fx = new[] { "SaltHold" }, RuJ = "Финский Бродвей: сцены нет, зато есть соус и молчаливая публика. В консервном цеху это ели тайком от мастера. Идеально к закату, которого не видно за бураном.", EnJ = "A Finnish Broadway: no stage, but there is dip and a silent audience. At the cannery they ate this behind the foreman's back. Perfect with a sunset you cannot see for the storm.", Rare = false },
        new Def { Id = "TaffellBroadwaySuola", Kind = Kind.Snack, Shape = "bag", Mesh = "TaffellBroadway", Texture = "TaffellBroadwaySuola", Kg = 0.243f, Kcal = 1260f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Таффель Бродвей»", En = "Taffell Broadway ridged crisps", RuF = "соль", EnF = "salted", RuC = "Финляндия", EnC = "Finland", Fx = new[] { "SaltHold" }, RuJ = "Финский Бродвей: сцены нет, зато есть соус и молчаливая публика. Его не взяли даже мародёры. Они спешили. Пахнет магазином. Помните магазины?", EnJ = "A Finnish Broadway: no stage, but there is dip and a silent audience. Even the looters left it. They were in a hurry. It smells of a shop. Remember shops?", Rare = false },
        new Def { Id = "TaffellBroadwayTulinen", Kind = Kind.Snack, Shape = "bag", Mesh = "TaffellBroadway", Texture = "TaffellBroadwayTulinen", Kg = 0.243f, Kcal = 1260f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Таффель Бродвей»", En = "Taffell Broadway ridged crisps", RuF = "огненные", EnF = "fiery hot", RuC = "Финляндия", EnC = "Finland", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Финский Бродвей: сцены нет, зато есть соус и молчаливая публика. Провело зиму на острове, как и вы. Мороз не испортил, время не взяло.", EnJ = "A Finnish Broadway: no stage, but there is dip and a silent audience. It spent the winter on the island, same as you. Frost did not spoil it and time could not take it.", Rare = false },
        new Def { Id = "SmifsThinlyOriginal", Kind = Kind.Snack, Shape = "bag", Mesh = "SmifsThinly", Texture = "SmifsThinlyOriginal", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Смифс Тонкие»", En = "Smif’s Thinly Cut crisps", RuF = "оригинальные", EnF = "original", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Нарезаны так тонко, что чайка унесёт по ломтику и не заметит. Дети прятали такое под кроватью, в тайнике. В рюкзаке не мнётся. Почти.", EnJ = "Cut so thin a gull could carry off a slice and not notice. Children hid these under the bed, in a secret place. It does not get crushed in a pack. Almost.", Rare = false },
        new Def { Id = "SmifsThinlyChicken", Kind = Kind.Snack, Shape = "bag", Mesh = "SmifsThinly", Texture = "SmifsThinlyChicken", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Смифс Тонкие»", En = "Smif’s Thinly Cut crisps", RuF = "курица", EnF = "chicken", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Нарезаны так тонко, что чайка унесёт по ломтику и не заметит. Осталось от геологов вместе с картой и долгами. Съешьте сейчас: завтра может не быть аппетита.", EnJ = "Cut so thin a gull could carry off a slice and not notice. Left by the geologists along with a map and some debts. Eat it now: tomorrow you may have no appetite.", Rare = false },
        new Def { Id = "SmifsThinlyLime", Kind = Kind.Snack, Shape = "bag", Mesh = "SmifsThinly", Texture = "SmifsThinlyLime", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Смифс Тонкие»", En = "Smif’s Thinly Cut crisps", RuF = "лайм и перец", EnF = "lime & black pepper", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Нарезаны так тонко, что чайка унесёт по ломтику и не заметит. На острове такое было праздником и до катастрофы. Хватит дойти до следующей хижины и пожалеть, что кончилось.", EnJ = "Cut so thin a gull could carry off a slice and not notice. On the island this was a treat even before the disaster. Enough to reach the next cabin and regret it is gone.", Rare = false },
        new Def { Id = "SmifsThinlyVinegar", Kind = Kind.Snack, Shape = "bag", Mesh = "SmifsThinly", Texture = "SmifsThinlyVinegar", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Смифс Тонкие»", En = "Smif’s Thinly Cut crisps", RuF = "соль и уксус", EnF = "salt & vinegar", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Нарезаны так тонко, что чайка унесёт по ломтику и не заметит. С таким слушали радио, которое теперь ловит только треск. От такого не толстеют те, кто ходит по двадцать километров.", EnJ = "Cut so thin a gull could carry off a slice and not notice. People ate these by the radio, which picks up nothing but crackle now. Nobody who walks twenty kilometres a day gets fat on this.", Rare = false },
        new Def { Id = "SmifsThinlyCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "SmifsThinly", Texture = "SmifsThinlyCheese", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Смифс Тонкие»", En = "Smif’s Thinly Cut crisps", RuF = "сыр и лук", EnF = "cheese & onion", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Нарезаны так тонко, что чайка унесёт по ломтику и не заметит. Крысы прогрызли соседнюю, эту пощадили. Волчья стая не в курсе. Пусть так и будет.", EnJ = "Cut so thin a gull could carry off a slice and not notice. The rats gnawed through the one next to it and spared this. The wolf pack does not know. Keep it that way.", Rare = false },
        new Def { Id = "SmifsThinlyBBQ", Kind = Kind.Snack, Shape = "bag", Mesh = "SmifsThinly", Texture = "SmifsThinlyBBQ", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Смифс Тонкие»", En = "Smif’s Thinly Cut crisps", RuF = "барбекю", EnF = "barbecue", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Нарезаны так тонко, что чайка унесёт по ломтику и не заметит. Бывший хозяин клялся бросить. Не успел. Хрустеть в засаде не рекомендуется.", EnJ = "Cut so thin a gull could carry off a slice and not notice. The former owner swore to give these up. He ran out of time. Crunching in an ambush is not recommended.", Rare = false },
        new Def { Id = "SmifsThinlySour", Kind = Kind.Snack, Shape = "bag", Mesh = "SmifsThinly", Texture = "SmifsThinlySour", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Смифс Тонкие»", En = "Smif’s Thinly Cut crisps", RuF = "сметана и лук", EnF = "sour cream & onion", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold" }, RuJ = "Нарезаны так тонко, что чайка унесёт по ломтику и не заметит. Его катали в кабине трактора три сезона. Лекарство от тоски, отпускается без рецепта.", EnJ = "Cut so thin a gull could carry off a slice and not notice. It rode around in a tractor cab for three seasons. A cure for the blues, no prescription needed.", Rare = false },
        new Def { Id = "SmifsThinlyChilli", Kind = Kind.Snack, Shape = "bag", Mesh = "SmifsThinly", Texture = "SmifsThinlyChilli", Kg = 0.183f, Kcal = 940f, Thirst = -8f, Eat = 4f, Ru = "Чипсы «Смифс Тонкие»", En = "Smif’s Thinly Cut crisps", RuF = "сладкий чили", EnF = "sweet chilli", RuC = "Австралия", EnC = "Australia", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "Нарезаны так тонко, что чайка унесёт по ломтику и не заметит. После бани такое шло лучше всего. Жуйте и думайте о хорошем. Например, о добавке.", EnJ = "Cut so thin a gull could carry off a slice and not notice. Nothing went down better after the sauna. Chew and think of nice things. Seconds, for example.", Rare = false },
        new Def { Id = "LeshiWaveSteak", Kind = Kind.Snack, Shape = "bag", Mesh = "LeshiWave", Texture = "LeshiWaveSteak", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лэши Большая волна»", En = "Leshi Big Wave ridged crisps", RuF = "стейк на камне", EnF = "sizzling steak", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "«Большая волна»: рёбра как на гравюре, только съедобные. В тюрьме на это выменивали что угодно. К утру от него останется только запах на варежках.", EnJ = "‘Big Wave’: ridges like the woodblock print, only edible. In the prison you could trade one of these for anything. By morning only the smell on your mittens will be left.", Rare = false },
        new Def { Id = "LeshiWaveWings", Kind = Kind.Snack, Shape = "bag", Mesh = "LeshiWave", Texture = "LeshiWaveWings", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лэши Большая волна»", En = "Leshi Big Wave ridged crisps", RuF = "жареные крылышки", EnF = "roasted wings", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "«Большая волна»: рёбра как на гравюре, только съедобные. Кто-то менял это на сигареты. Сделка сорвалась. Тишина вокруг такая, что слышно, как вы жуёте.", EnJ = "‘Big Wave’: ridges like the woodblock print, only edible. Someone was trading this for cigarettes. The deal fell through. It is so quiet you can hear yourself chew.", Rare = false },
        new Def { Id = "LeshiWaveSquid", Kind = Kind.Snack, Shape = "bag", Mesh = "LeshiWave", Texture = "LeshiWaveSquid", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лэши Большая волна»", En = "Leshi Big Wave ridged crisps", RuF = "кальмар на гриле", EnF = "grilled squid", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "«Большая волна»: рёбра как на гравюре, только съедобные. С ним зимовали на метеостанции, пока было с кем. Не делите на завтра: завтра будет новый голод.", EnJ = "‘Big Wave’: ridges like the woodblock print, only edible. They wintered with it at the weather station, while there was a 'they'. Do not save half for tomorrow: tomorrow brings its own hunger.", Rare = false },
        new Def { Id = "LeshiWaveTomato", Kind = Kind.Snack, Shape = "bag", Mesh = "LeshiWave", Texture = "LeshiWaveTomato", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лэши Большая волна»", En = "Leshi Big Wave ridged crisps", RuF = "томат", EnF = "tomato", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "«Большая волна»: рёбра как на гравюре, только съедобные. Такое терялось в кладовке среди крупы и надежд. Сосны вокруг делают вид, что не смотрят.", EnJ = "‘Big Wave’: ridges like the woodblock print, only edible. These got lost in the pantry among the grain and the hopes. The pines around pretend not to watch.", Rare = false },
        new Def { Id = "LeshiWaveCucumber", Kind = Kind.Snack, Shape = "bag", Mesh = "LeshiWave", Texture = "LeshiWaveCucumber", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лэши Большая волна»", En = "Leshi Big Wave ridged crisps", RuF = "огурец", EnF = "cucumber", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "«Большая волна»: рёбра как на гравюре, только съедобные. Его берегли к приезду внуков. Калории мелкие, зато свои.", EnJ = "‘Big Wave’: ridges like the woodblock print, only edible. It was being saved for the grandchildren's visit. Small calories, but your own.", Rare = false },
        new Def { Id = "LeshiWaveMala", Kind = Kind.Snack, Shape = "bag", Mesh = "LeshiWave", Texture = "LeshiWaveMala", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лэши Большая волна»", En = "Leshi Big Wave ridged crisps", RuF = "жгучая мала", EnF = "spicy mala", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold", "PepperBlood", "Sweat" }, RuJ = "«Большая волна»: рёбра как на гравюре, только съедобные. В баре такое ставили на стойку, бесплатно к пиву. Пива нет. После этого даже крапивный чай покажется десертом.", EnJ = "‘Big Wave’: ridges like the woodblock print, only edible. Bars put these out free with a beer. There is no beer. After this even nettle tea feels like dessert.", Rare = false },
        new Def { Id = "LeshiWaveCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "LeshiWave", Texture = "LeshiWaveCheese", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лэши Большая волна»", En = "Leshi Big Wave ridged crisps", RuF = "сыр", EnF = "cheese", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "«Большая волна»: рёбра как на гравюре, только съедобные. Такое лежало в каждом доме, пока не погас свет. Нашедшему полагается всё.", EnJ = "‘Big Wave’: ridges like the woodblock print, only edible. Every house had one of these until the lights went out. Finders keepers, all of it.", Rare = false },
        new Def { Id = "LeshiWaveSeaweed", Kind = Kind.Snack, Shape = "bag", Mesh = "LeshiWave", Texture = "LeshiWaveSeaweed", Kg = 0.078f, Kcal = 370f, Thirst = -8f, Eat = 4f, Ru = "Рифлёные чипсы «Лэши Большая волна»", En = "Leshi Big Wave ridged crisps", RuF = "нори", EnF = "seaweed", RuC = "Китай", EnC = "China", Fx = new[] { "SaltHold" }, RuJ = "«Большая волна»: рёбра как на гравюре, только съедобные. Кто-то берёг это на чёрный день. Он настал. Зубы целы? Тогда вперёд.", EnJ = "‘Big Wave’: ridges like the woodblock print, only edible. Someone saved this for a rainy day. It came. Teeth intact? Then go ahead.", Rare = false },
        new Def { Id = "MartynOtbornyeBig", Kind = Kind.Snack, Shape = "bag", Mesh = "MartynOtbornye", Texture = "MartynOtbornyeBig", Kg = 0.208f, Kcal = 1160f, Thirst = -6f, Eat = 25f, Ru = "Семечки «От Мартына Отборные»", En = "Ot Martyna Select seeds", RuF = "крупные жареные", EnF = "large roasted", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Отборные: каждую семечку Мартын знал в лицо. Пережило хозяина, кота и две зимы. Ночью приснится добавка.", EnJ = "Select: Martyn knew every seed by sight. It outlived its owner, the cat and two winters. Tonight you will dream of seconds.", Rare = false },
        new Def { Id = "MartynOtbornyeSeaSalt", Kind = Kind.Snack, Shape = "bag", Mesh = "MartynOtbornye", Texture = "MartynOtbornyeSeaSalt", Kg = 0.208f, Kcal = 1160f, Thirst = -6f, Eat = 25f, Ru = "Семечки «От Мартына Отборные»", En = "Ot Martyna Select seeds", RuF = "с морской солью", EnF = "with sea salt", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Отборные: каждую семечку Мартын знал в лицо. Такое обычно находили за диваном, как всё лучшее в жизни. С таким запасом можно пережить ещё один вечер.", EnJ = "Select: Martyn knew every seed by sight. These were usually found behind the sofa, like all the best things in life. With supplies like this you can survive one more evening.", Rare = false },
        new Def { Id = "MartynOtbornyeStriped", Kind = Kind.Snack, Shape = "bag", Mesh = "MartynOtbornye", Texture = "MartynOtbornyeStriped", Kg = 0.208f, Kcal = 1160f, Thirst = -6f, Eat = 25f, Ru = "Семечки «От Мартына Отборные»", En = "Ot Martyna Select seeds", RuF = "полосатые", EnF = "striped", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Отборные: каждую семечку Мартын знал в лицо. Последний завоз был до того, как упали самолёты. Пёс бы выпросил половину. Пса нет.", EnJ = "Select: Martyn knew every seed by sight. The last delivery came before the planes fell. A dog would beg half of it. There is no dog.", Rare = false },
        new Def { Id = "MartynOtbornyeSmoked", Kind = Kind.Snack, Shape = "bag", Mesh = "MartynOtbornye", Texture = "MartynOtbornyeSmoked", Kg = 0.208f, Kcal = 1160f, Thirst = -6f, Eat = 25f, Ru = "Семечки «От Мартына Отборные»", En = "Ot Martyna Select seeds", RuF = "копчёные", EnF = "smoked", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Отборные: каждую семечку Мартын знал в лицо. Ценник оторван: теперь это бесценно. Съедено будет быстрее, чем найдено.", EnJ = "Select: Martyn knew every seed by sight. The price tag is torn off: it is priceless now. It will be eaten faster than it was found.", Rare = false },
        new Def { Id = "MartynOtbornyePumpkin", Kind = Kind.Snack, Shape = "bag", Mesh = "MartynOtbornye", Texture = "MartynOtbornyePumpkin", Kg = 0.208f, Kcal = 1160f, Thirst = -6f, Eat = 25f, Ru = "Семечки «От Мартына Отборные»", En = "Ot Martyna Select seeds", RuF = "тыквенные", EnF = "pumpkin seeds", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Отборные: каждую семечку Мартын знал в лицо. Дата на шве стёрлась, и слава богу. На вкус как выходной.", EnJ = "Select: Martyn knew every seed by sight. The date on the seam has rubbed off, thank goodness. It tastes like a day off.", Rare = false },
        new Def { Id = "MartynOtbornyeShelled", Kind = Kind.Snack, Shape = "bag", Mesh = "MartynOtbornye", Texture = "MartynOtbornyeShelled", Kg = 0.208f, Kcal = 1160f, Thirst = -6f, Eat = 25f, Ru = "Семечки «От Мартына Отборные»", En = "Ot Martyna Select seeds", RuF = "очищенные", EnF = "shelled kernels", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Отборные: каждую семечку Мартын знал в лицо. Пахнет заправкой у Прибрежного шоссе. Ветер унесёт запах прямо к берлоге. Ешьте быстрее.", EnJ = "Select: Martyn knew every seed by sight. It smells of the petrol station on the Coastal Highway. The wind carries the smell straight to the den. Eat faster.", Rare = false },
        new Def { Id = "MartynOtbornyeUnsalted", Kind = Kind.Snack, Shape = "bag", Mesh = "MartynOtbornye", Texture = "MartynOtbornyeUnsalted", Kg = 0.208f, Kcal = 1160f, Thirst = -6f, Eat = 25f, Ru = "Семечки «От Мартына Отборные»", En = "Ot Martyna Select seeds", RuF = "без соли", EnF = "unsalted", RuC = "Россия", EnC = "Russia", Fx = new[] { "SeedHabit" }, RuJ = "Отборные: каждую семечку Мартын знал в лицо. Такое возили в бардачке на дальнюю дорогу. Дороги кончились. Пополняет запас соли и веры в человечество.", EnJ = "Select: Martyn knew every seed by sight. People kept these in the glovebox for long drives. The drives are over. Restores your salt and your faith in mankind.", Rare = false },
        new Def { Id = "PlanterzDeluxeMixed", Kind = Kind.Snack, Shape = "can", Mesh = "PlanterzDeluxe", Texture = "PlanterzDeluxeMixed", Kg = 0.27f, Kcal = 1080f, Thirst = -7f, Eat = 5f, Ru = "Ореховая смесь «Плантерз Делюкс»", En = "Planterz Deluxe mixed nuts", RuF = "ореховое ассорти", EnF = "mixed nuts", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "Sinew" }, RuJ = "Орех в монокле собрал высшее общество: кешью, миндаль, пекан и ни одного арахиса. Мыши не тронули. Думайте сами. Хорошо идёт под треск поленьев.", EnJ = "The monocled nut gathered high society: cashews, almonds, pecans and not one peanut. The mice left it alone. Draw your own conclusions. Goes down well with crackling logs.", Rare = false },
        new Def { Id = "PlanterzDeluxeCashew", Kind = Kind.Snack, Shape = "can", Mesh = "PlanterzDeluxe", Texture = "PlanterzDeluxeCashew", Kg = 0.27f, Kcal = 1080f, Thirst = -7f, Eat = 5f, Ru = "Ореховая смесь «Плантерз Делюкс»", En = "Planterz Deluxe mixed nuts", RuF = "кешью целые", EnF = "whole cashews", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "Sinew" }, RuJ = "Орех в монокле собрал высшее общество: кешью, миндаль, пекан и ни одного арахиса. Рыбаки брали такое на лёд вместо обеда. Руки вытирать о штаны: салфеток не завезли.", EnJ = "The monocled nut gathered high society: cashews, almonds, pecans and not one peanut. Fishermen took this onto the ice instead of lunch. Wipe your hands on your trousers: no napkins were delivered.", Rare = false },
        new Def { Id = "PlanterzDeluxeHoney", Kind = Kind.Snack, Shape = "can", Mesh = "PlanterzDeluxe", Texture = "PlanterzDeluxeHoney", Kg = 0.27f, Kcal = 1080f, Thirst = -7f, Eat = 5f, Ru = "Ореховая смесь «Плантерз Делюкс»", En = "Planterz Deluxe mixed nuts", RuF = "в мёде", EnF = "honey roasted", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "SugarDry" }, RuJ = "Орех в монокле собрал высшее общество: кешью, миндаль, пекан и ни одного арахиса. Смотритель плотины держал такое в заначке. Маленькая радость размером с ладонь.", EnJ = "The monocled nut gathered high society: cashews, almonds, pecans and not one peanut. The dam keeper kept a stash of these. A small joy the size of your palm.", Rare = false },
        new Def { Id = "PlanterzDeluxeAlmond", Kind = Kind.Snack, Shape = "can", Mesh = "PlanterzDeluxe", Texture = "PlanterzDeluxeAlmond", Kg = 0.27f, Kcal = 1080f, Thirst = -7f, Eat = 5f, Ru = "Ореховая смесь «Плантерз Делюкс»", En = "Planterz Deluxe mixed nuts", RuF = "миндаль", EnF = "almonds", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "Sinew" }, RuJ = "Орех в монокле собрал высшее общество: кешью, миндаль, пекан и ни одного арахиса. Кто-то спрятал это от детей. Дети не нашли. Совесть молчит, живот поёт.", EnJ = "The monocled nut gathered high society: cashews, almonds, pecans and not one peanut. Someone hid it from the kids. The kids never found it. Conscience is silent, the belly sings.", Rare = false },
        new Def { Id = "PlanterzDeluxePistachio", Kind = Kind.Snack, Shape = "can", Mesh = "PlanterzDeluxe", Texture = "PlanterzDeluxePistachio", Kg = 0.27f, Kcal = 1080f, Thirst = -7f, Eat = 5f, Ru = "Ореховая смесь «Плантерз Делюкс»", En = "Planterz Deluxe mixed nuts", RuF = "фисташки", EnF = "pistachios", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "Sinew" }, RuJ = "Орех в монокле собрал высшее общество: кешью, миндаль, пекан и ни одного арахиса. В сельском магазине такое вечно заваливалось за прилавок. Проверено поколениями и одной катастрофой.", EnJ = "The monocled nut gathered high society: cashews, almonds, pecans and not one peanut. In the village shop these kept slipping behind the counter. Tested by generations and one catastrophe.", Rare = false },
        new Def { Id = "PlanterzDeluxePecan", Kind = Kind.Snack, Shape = "can", Mesh = "PlanterzDeluxe", Texture = "PlanterzDeluxePecan", Kg = 0.27f, Kcal = 1080f, Thirst = -7f, Eat = 5f, Ru = "Ореховая смесь «Плантерз Делюкс»", En = "Planterz Deluxe mixed nuts", RuF = "пекан", EnF = "pecans", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "Sinew" }, RuJ = "Орех в монокле собрал высшее общество: кешью, миндаль, пекан и ни одного арахиса. Ждало покупателя дольше, чем тот прожил. Оставьте пару штук на перевал. Не оставите.", EnJ = "The monocled nut gathered high society: cashews, almonds, pecans and not one peanut. It waited for a buyer longer than the buyer lived. Save a couple for the pass. You will not.", Rare = false },
        new Def { Id = "PlanterzDeluxeUnsalted", Kind = Kind.Snack, Shape = "can", Mesh = "PlanterzDeluxe", Texture = "PlanterzDeluxeUnsalted", Kg = 0.27f, Kcal = 1080f, Thirst = -7f, Eat = 5f, Ru = "Ореховая смесь «Плантерз Делюкс»", En = "Planterz Deluxe mixed nuts", RuF = "смесь без соли", EnF = "unsalted mix", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "Sinew" }, RuJ = "Орех в монокле собрал высшее общество: кешью, миндаль, пекан и ни одного арахиса. С материка такое больше не привезут. Здесь это считается ужином при свечах.", EnJ = "The monocled nut gathered high society: cashews, almonds, pecans and not one peanut. Nobody will bring this from the mainland again. Round here this counts as a candlelit dinner.", Rare = false },
        new Def { Id = "PlanterzDeluxeMacadamia", Kind = Kind.Snack, Shape = "can", Mesh = "PlanterzDeluxe", Texture = "PlanterzDeluxeMacadamia", Kg = 0.27f, Kcal = 1080f, Thirst = -7f, Eat = 5f, Ru = "Ореховая смесь «Плантерз Делюкс»", En = "Planterz Deluxe mixed nuts", RuF = "макадамия", EnF = "macadamia", RuC = "весь мир", EnC = "worldwide", Fx = new[] { "Sinew" }, RuJ = "Орех в монокле собрал высшее общество: кешью, миндаль, пекан и ни одного арахиса. На упаковке иней, внутри всё по-прежнему. Луна светит, еда хрустит, жизнь налаживается.", EnJ = "The monocled nut gathered high society: cashews, almonds, pecans and not one peanut. Frost on the wrapper, business as usual inside. The moon shines, the food crunches, life is looking up.", Rare = false },
