        new Def { Id = "KiryushkiFlintRibs", Kind = Kind.Snack, Shape = "bag", Mesh = "KiryushkiFlint", Texture = "KiryushkiFlintRibs", Kg = 0.078f, Kcal = 280f, Thirst = -5f, Eat = 3f, Ru = "Гренки «Кирюшки»", En = "Kiryushki big croutons", RuF = "копчёные рёбрышки", EnF = "smoked ribs", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Гренки втрое крупнее сухариков: нёбо помнит каждую. Из тех времён, когда еду выбирали по вкусу. Больше таких не делают. Совсем.", EnJ = "Croutons three times the size: your palate remembers every one. From the days when people picked food for its taste. They do not make these any more. At all.", Rare = false },
        new Def { Id = "KiryushkiFlintCheese", Kind = Kind.Snack, Shape = "bag", Mesh = "KiryushkiFlint", Texture = "KiryushkiFlintCheese", Kg = 0.078f, Kcal = 280f, Thirst = -5f, Eat = 3f, Ru = "Гренки «Кирюшки»", En = "Kiryushki big croutons", RuF = "сырный соус", EnF = "cheese sauce", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Гренки втрое крупнее сухариков: нёбо помнит каждую. Чей-то перекус на ночную смену, которая не кончилась. Открывайте тихо: у волков отличный слух.", EnJ = "Croutons three times the size: your palate remembers every one. Someone's snack for a night shift that never ended. Open it quietly: wolves have excellent hearing.", Rare = false },
        new Def { Id = "KiryushkiFlintCrab", Kind = Kind.Snack, Shape = "bag", Mesh = "KiryushkiFlint", Texture = "KiryushkiFlintCrab", Kg = 0.078f, Kcal = 280f, Thirst = -5f, Eat = 3f, Ru = "Гренки «Кирюшки»", En = "Kiryushki big croutons", RuF = "краб", EnF = "crab", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Гренки втрое крупнее сухариков: нёбо помнит каждую. В охотничьей вышке таким встречали рассвет. Одной не обойдётся, но вторая неизвестно где.", EnJ = "Croutons three times the size: your palate remembers every one. In the hunting blind they met the dawn with this. One won't be enough, and nobody knows where the second is.", Rare = false },
        new Def { Id = "KiryushkiFlintShashlik", Kind = Kind.Snack, Shape = "bag", Mesh = "KiryushkiFlint", Texture = "KiryushkiFlintShashlik", Kg = 0.078f, Kcal = 280f, Thirst = -5f, Eat = 3f, Ru = "Гренки «Кирюшки»", En = "Kiryushki big croutons", RuF = "шашлык", EnF = "shashlik", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Гренки втрое крупнее сухариков: нёбо помнит каждую. Такое носили в кармане куртки на всякий случай. Случай настал. Крошки с пола тоже считаются.", EnJ = "Croutons three times the size: your palate remembers every one. People carried these in a coat pocket just in case. The case has come. The crumbs on the floor count too.", Rare = false },
