        new Def { Id = "KiryushkiFlintWasabi", Kind = Kind.Snack, Shape = "bag", Mesh = "KiryushkiFlint", Texture = "KiryushkiFlintWasabi", Kg = 0.078f, Kcal = 280f, Thirst = -5f, Eat = 3f, Ru = "Гренки «Кирюшки»", En = "Kiryushki big croutons", RuF = "васаби", EnF = "wasabi", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "PepperBlood", "Sweat", "DryLump" }, RuJ = "Гренки втрое крупнее сухариков: нёбо помнит каждую. Такими торговали в поезде, пока поезд ходил. Медведю не показывать: отнимет вместе с рукой.", EnJ = "Croutons three times the size: your palate remembers every one. They sold these on the train, while the train ran. Do not show the bear: he will take it, hand and all.", Rare = false },
