        new Def { Id = "KiryushkiFlintTomato", Kind = Kind.Snack, Shape = "bag", Mesh = "KiryushkiFlint", Texture = "KiryushkiFlintTomato", Kg = 0.078f, Kcal = 280f, Thirst = -5f, Eat = 3f, Ru = "Гренки «Кирюшки»", En = "Kiryushki big croutons", RuF = "томат спелый", EnF = "ripe tomato", RuC = "Россия", EnC = "Russia", Fx = new[] { "SaltHold", "DryLump" }, RuJ = "Гренки втрое крупнее сухариков: нёбо помнит каждую. Лавина прошла мимо, срок годности тоже. Лучше, чем кора. Проверено.", EnJ = "Croutons three times the size: your palate remembers every one. The avalanche missed it, and so did the best-before date. Better than bark. Tested.", Rare = false },
